+      if (this.disabled) return;
+      this.checked = !this.checked;
+      this.#persist();
+      this.dispatchEvent(new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { itemId: this.itemId, checked: this.checked },
+      }));
+    }
+
+    #persist() {
+      if (!this.itemId) return;
