diff --git a/src/utils/webmcp.ts b/src/utils/webmcp.ts
new file mode 100644
index 0000000..44e1569
--- /dev/null
+++ b/src/utils/webmcp.ts
@@ -0,0 +1,108 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Minimal typings and helpers for the WebMCP imperative API
+ * (`navigator.modelContext`), which lets a page expose client-side
+ * functionality as tools that in-browser AI agents can call.
+ *
+ * The API is still evolving, so everything here is feature-detected and
+ * tolerant of both the `{ unregister() }` return value and the
+ * `unregisterTool(name)` / AbortSignal styles of unregistration.
+ */
+
+export interface ToolTextContent {
+  type: 'text';
+  text: string;
+}
+
+export interface ToolResult {
+  content: ToolTextContent[];
+  isError?: boolean;
+}
+
+export interface JSONSchema {
+  type: string;
+  properties?: Record<string, JSONSchema & { description?: string }>;
+  required?: string[];
+  [key: string]: unknown;
+}
+
+export interface ModelContextTool<TInput = any> {
+  name: string;
+  description: string;
+  inputSchema: JSONSchema;
+  annotations?: {
+    readOnlyHint?: boolean;
+    [key: string]: unknown;
+  };
+  execute: (input: TInput, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+interface ModelContext {
+  registerTool: (
+    tool: ModelContextTool,
+    options?: { signal?: AbortSignal },
+  ) => { unregister?: () => void } | void;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+export function textResult(text: string, isError = false): ToolResult {
+  return { content: [{ type: 'text', text }], ...(isError ? { isError: true } : {}) };
+}
+
+/**
+ * Registers a WebMCP tool for the lifetime of the calling component.
+ * `execute` always calls the latest closure, so the tool is registered once
+ * and doesn't churn on re-renders.
+ */
+export function useWebMCPTool<TInput>(tool: ModelContextTool<TInput>): void {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  const { name, description, inputSchema, annotations } = tool;
+  const schemaKey = JSON.stringify(inputSchema);
+  const annotationsKey = JSON.stringify(annotations ?? null);
+
+  useEffect(() => {
+    const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+    if (!modelContext || typeof modelContext.registerTool !== 'function') return;
+
+    const controller = new AbortController();
+    let registration: { unregister?: () => void } | void;
+    try {
+      registration = modelContext.registerTool(
+        {
+          name,
+          description,
+          inputSchema,
+          ...(annotations ? { annotations } : {}),
+          execute: (input: TInput, client?: unknown) => executeRef.current(input, client),
+        },
+        { signal: controller.signal },
+      );
+    } catch (err) {
+      console.warn(`[WebMCP] Failed to register tool "${name}":`, err);
+      return;
+    }
+
+    return () => {
+      controller.abort();
+      try {
+        if (registration && typeof registration.unregister === 'function') {
+          registration.unregister();
+        } else if (typeof modelContext.unregisterTool === 'function') {
+          modelContext.unregisterTool(name);
+        }
+      } catch {
+        // Already unregistered (e.g. via the abort signal).
+      }
+    };
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [name, description, schemaKey, annotationsKey]);
+}

