+  .filter(item => !item.disabled && item.getAttribute('aria-disabled') !== 'true');
+
+const hasInvokers = 'commandForElement' in HTMLButtonElement.prototype;
+const hasAnchorPositioning = CSS.supports('position-area: block-end');
+
+const enterOnOpen = new WeakMap(); // menu -> 'first' | 'last', for keyboard opens
+const previewOnly = new WeakSet(); // menus shown by focusing their trigger, not entered
+const openAtPointerDown = new WeakSet();
+let windowBlurred = false;
+
+// Older implementations: showPopover({ source }) doesn't set an implicit anchor.
+if (hasAnchorPositioning && !('source' in (window.ToggleEvent?.prototype ?? {}))) {
+  rootTriggers.forEach((trigger, i) => {
+    trigger.style.setProperty('anchor-name', `--menubar-trigger-${i}`);
+    menuFor(trigger).style.setProperty('position-anchor', `--menubar-trigger-${i}`);
+  });
+}
+
+function showMenu(menu, trigger) {
+  try {
+    menu.showPopover({ source: trigger });
+  } catch {
+    menu.showPopover();
+  }
+}
+
+function closeAndRestore(menu, { fromPointer = false } = {}) {
+  triggerFor(menu).focus({ focusVisible: !fromPointer });
+  if (isOpen(menu)) menu.hidePopover();
+}
+
+function focusItem(menu, which) {
+  const items = itemsOf(menu);
+  (which === 'last' ? items.at(-1) : items[0])?.focus({ preventScroll: true });
+}
+
+// Left/Right always land on the adjacent trigger as a preview, never inside its menu.
+function moveToRootTrigger(from, direction) {
+  const next = rootTriggers[(rootTriggers.indexOf(from) + direction + rootTriggers.length) % rootTriggers.length];
+  rootTriggers.forEach(trigger => { trigger.tabIndex = trigger === next ? 0 : -1; });
+  rootTriggers.map(menuFor).filter(isOpen).forEach(menu => menu.hidePopover());
+  next.focus({ preventScroll: true }); // Focusing the trigger previews its menu.
+}
