+// Fallback placement when CSS anchor positioning is unavailable.
+function placeMenu(menu, trigger) {
+  const t = trigger.getBoundingClientRect();
+  const m = menu.getBoundingClientRect();
+  let left = t.left;
+  let top = t.bottom + 4;
+  if (left + m.width > innerWidth) left = t.right - m.width;
+  if (top + m.height > innerHeight && t.top - m.height - 4 >= 0) top = t.top - m.height - 4;
+  left = Math.min(Math.max(0, left), Math.max(0, innerWidth - m.width));
+  menu.style.left = `${left}px`;
+  menu.style.top = `${top}px`;
+}
+
+function openWith(trigger, which) {
+  const menu = menuFor(trigger);
+  if (isOpen(menu)) {
+    previewOnly.delete(menu);
+    focusItem(menu, which);
+  } else {
+    enterOnOpen.set(menu, which);
+    trigger.click(); // The invoker stays the only open path.
+  }
+}
+
+for (const trigger of rootTriggers) {
+  const menu = menuFor(trigger);
+
+  trigger.addEventListener('pointerdown', event => {
