+    if (!hasAnchorPositioning) placeMenu(menu, trigger);
+    if (enterOnOpen.has(menu)) {
+      const which = enterOnOpen.get(menu);
+      enterOnOpen.delete(menu);
+      previewOnly.delete(menu);
+      focusItem(menu, which);
+    } else if (document.activeElement !== trigger) {
+      // Pointer open: focus the trigger without a ring so arrow keys still work.
+      trigger.focus({ focusVisible: false });
+    }
+  });
+
+  menu.addEventListener('focusin', () => previewOnly.delete(menu));
+
+  menu.addEventListener('keydown', event => {
+    switch (event.key) {
+      case 'ArrowRight':
+      case 'ArrowLeft':
+        event.preventDefault();
+        moveToRootTrigger(trigger, event.key === 'ArrowRight' ? 1 : -1);
+        break;
+      case 'Home':
+      case 'End':
+        event.preventDefault();
+        focusItem(menu, event.key === 'End' ? 'last' : 'first');
+        break;
+      case 'Escape':
+        event.preventDefault();
+        event.stopPropagation();
+        closeAndRestore(menu);
+        break;
+      case 'Tab':
+        // Leave the bar; close once focus has moved.
+        setTimeout(() => {
+          if (isOpen(menu) && !menu.contains(document.activeElement)) menu.hidePopover();
+        });
+        break;
+    }
+  });
+
+  // Hover follows focus.
+  menu.addEventListener('pointermove', event => {
+    const item = event.target.closest('a[href], button');
+    if (item && menu.contains(item) && document.activeElement !== item) {
+      item.focus({ focusVisible: false, preventScroll: true });
+    }
+  });
+
+  // Activating a link closes the menu (matters for modifier-clicks that open a new tab).
+  menu.addEventListener('click', event => {
+    if (event.target.closest('a[href]')) closeAndRestore(menu, { fromPointer: event.detail !== 0 });
+  });
+}
+
+// Close every menu when focus lands outside the menu bar (triggers count as inside).
+document.addEventListener('focusin', event => {
+  if (menubar.contains(event.target)) return;
+  rootTriggers.map(menuFor).filter(isOpen).forEach(menu => menu.hidePopover());
+});
+
+// Don't reopen the last menu when switching back from another window.
+addEventListener('blur', () => { windowBlurred = true; });
+addEventListener('focus', () => { setTimeout(() => { windowBlurred = false; }); });
+
+// focusgroup fallback: arrow-key movement and roles where focusgroup is unsupported.
+if (!('focusGroup' in HTMLElement.prototype)) {
+  document.querySelectorAll('[focusgroup~="menu"]').forEach(group => {
+    group.setAttribute('role', 'menu');
+    group.querySelectorAll('a[href]:not([role]), button:not([role])').forEach(item => {
+      item.setAttribute('role', 'menuitem');
+    });
+    group.addEventListener('keydown', event => {
+      if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
+      const items = [...group.querySelectorAll('a[href], button')]
+        .filter(item => item.closest('[focusgroup]') === group)
+        .filter(item => !item.disabled && item.getAttribute('aria-disabled') !== 'true');
+      const current = items.indexOf(document.activeElement);
+      if (current < 0) return;
+      const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 :
+        (current + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length;
+      event.preventDefault();
+      event.stopImmediatePropagation();
+      items[next].focus({ preventScroll: true });
+    }, true);
+  });
+}

