+  <script>
+    /*
+     * Application menu bar following the WAI-ARIA Authoring Practices
+     * "menubar" pattern: roving tabindex, arrow-key navigation, Home/End,
+     * Escape, type-ahead, and mouse/touch support.
+     */
+    (function () {
+      const menubar = document.querySelector('[role="menubar"]');
+      if (!menubar) return;
+
+      const topItems = Array.from(menubar.querySelectorAll(':scope > li > [role="menuitem"]'));
+      const submenuOf = (item) => document.getElementById(item.getAttribute('aria-controls'));
+      const itemsOf = (menu) => Array.from(menu.querySelectorAll('[role="menuitem"]'));
+      let openItem = null;
+
+      // Roving tabindex: only one top-level item is in the tab order.
+      function setRoving(target) {
+        topItems.forEach((item) => { item.tabIndex = item === target ? 0 : -1; });
+      }
+
+      function openMenu(item, focus) {
+        if (openItem && openItem !== item) closeMenu(openItem);
+        const menu = submenuOf(item);
+        menu.hidden = false;
+        item.setAttribute('aria-expanded', 'true');
+        openItem = item;
+        setRoving(item);
+        const items = itemsOf(menu);
+        if (focus === 'first') items[0].focus();
+        else if (focus === 'last') items[items.length - 1].focus();
+      }
+
+      function closeMenu(item) {
+        if (!item) return;
+        submenuOf(item).hidden = true;
+        item.setAttribute('aria-expanded', 'false');
+        if (openItem === item) openItem = null;
+      }
+
+      function focusTop(index, keepOpen) {
+        const n = topItems.length;
+        const item = topItems[(index + n) % n];
+        setRoving(item);
+        if (keepOpen) openMenu(item, 'first');
+        else item.focus();
+      }
+
+      function typeAhead(items, current, char) {
+        const start = items.indexOf(current);
+        for (let i = 1; i <= items.length; i++) {
+          const candidate = items[(start + i) % items.length];
+          if (candidate.textContent.trim().toLowerCase().startsWith(char)) {
+            return candidate;
+          }
+        }
+        return null;
+      }
+
+      const isPrintable = (e) => e.key.length === 1 && /\S/.test(e.key) && !e.ctrlKey && !e.metaKey && !e.altKey;
+
+      topItems.forEach((item, index) => {
+        const menu = submenuOf(item);
+        const items = itemsOf(menu);
+        items.forEach((link) => { link.tabIndex = -1; });
+
+        item.addEventListener('click', () => {
+          if (item.getAttribute('aria-expanded') === 'true') {
+            closeMenu(item);
+          } else {
+            openMenu(item);
+          }
+          item.focus();
+        });
+
+        // Once a menu is open, hovering another top-level item switches to it.
+        item.addEventListener('mouseenter', () => {
+          if (openItem && openItem !== item) {
+            openMenu(item);
+            item.focus();
+          }
+        });
+
+        item.addEventListener('keydown', (e) => {
+          let handled = true;
+          switch (e.key) {
+            case 'ArrowRight': focusTop(index + 1, !!openItem); break;
+            case 'ArrowLeft': focusTop(index - 1, !!openItem); break;
+            case 'Home': focusTop(0, false); break;
+            case 'End': focusTop(topItems.length - 1, false); break;
+            case 'ArrowDown':
+            case 'Enter':
+            case ' ':
+              openMenu(item, 'first'); break;
+            case 'ArrowUp': openMenu(item, 'last'); break;
+            case 'Escape': closeMenu(item); break;
+            default:
+              if (isPrintable(e)) {
+                const match = typeAhead(topItems, item, e.key.toLowerCase());
+                if (match) { if (openItem) closeMenu(openItem); setRoving(match); match.focus(); }
+              } else {
+                handled = false;
+              }
+          }
+          if (handled) { e.preventDefault(); e.stopPropagation(); }
+        });
+
+        menu.addEventListener('keydown', (e) => {
+          const current = document.activeElement;
+          const i = items.indexOf(current);
+          let handled = true;
+          switch (e.key) {
+            case 'ArrowDown': items[(i + 1) % items.length].focus(); break;
+            case 'ArrowUp': items[(i - 1 + items.length) % items.length].focus(); break;
+            case 'Home': items[0].focus(); break;
+            case 'End': items[items.length - 1].focus(); break;
+            case 'ArrowRight': closeMenu(item); focusTop(index + 1, true); break;
+            case 'ArrowLeft': closeMenu(item); focusTop(index - 1, true); break;
+            case 'Escape': closeMenu(item); item.focus(); break;
+            case 'Tab': closeMenu(item); handled = false; break;
+            case ' ': current.click(); break;
+            default:
+              if (isPrintable(e)) {
+                const match = typeAhead(items, current, e.key.toLowerCase());
+                if (match) match.focus();
+              } else {
+                handled = false;
+              }
+          }
+          if (handled) { e.preventDefault(); e.stopPropagation(); }
+        });
+
+        menu.addEventListener('mouseover', (e) => {
+          const link = e.target.closest('[role="menuitem"]');
+          if (link) link.focus({ preventScroll: true });
+        });
+
+        menu.addEventListener('click', (e) => {
+          if (e.target.closest('[role="menuitem"]')) closeMenu(item);
+        });
+      });
+
+      // Close when clicking or moving focus outside the menu bar.
+      document.addEventListener('pointerdown', (e) => {
+        if (openItem && !menubar.contains(e.target)) closeMenu(openItem);
+      });
+      menubar.addEventListener('focusout', (e) => {
+        if (openItem && !menubar.contains(e.relatedTarget)) closeMenu(openItem);
+      });
+
+      setRoving(topItems[0]);
+    })();
+  </script>
