--- a/hero-ripple.js
+++ b/hero-ripple.js
@@ -0,0 +1,303 @@
+// GPU ripple distortion for the hero headline + "Order Now" button.
+//
+// Uses the HTML-in-Canvas API: the hero content lives inside a
+// <canvas content="drawable">, is uploaded to a WebGL texture with
+// texElementSubImage2D(), and drawn through a ripple fragment shader.
+// updateElementGeometry() keeps the real DOM element aligned with the drawn
+// pixels, so text stays selectable, the link stays clickable/focusable, and
+// assistive tech sees the content normally.
+//
+// Browsers without HTML-in-Canvas (or WebGL 2) get the plain HTML content
+// placed back in the hero, with no effect.
+(() => {
+  const hero = document.getElementById('hero');
+  const canvas = document.getElementById('hero-canvas');
+  const content = document.getElementById('hero-content');
+  if (!hero || !canvas || !content) return;
+
+  // Children of <canvas> are not rendered without HTML-in-Canvas, so move the
+  // content out of the canvas and drop the canvas.
+  function fallback() {
+    canvas.replaceWith(content);
+  }
+
+  const supported =
+    'content' in HTMLCanvasElement.prototype &&
+    typeof HTMLCanvasElement.prototype.captureElementImage === 'function' &&
+    typeof HTMLCanvasElement.prototype.requestPaint === 'function';
+  if (!supported) return fallback();
+
+  const gl = canvas.getContext('webgl2', { premultipliedAlpha: true, alpha: true });
+  if (!gl || typeof gl.texElementSubImage2D !== 'function') return fallback();
+
+  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
+
+  // ---------------------------------------------------------------- shaders
+  const VERT = `#version 300 es
+    in vec2 a_pos;
+    out vec2 v_uv;
+    void main() {
+      // Element texture row 0 is the top of the element; clip-space +y is up.
+      v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5);
+      gl_Position = vec4(a_pos, 0.0, 1.0);
+    }`;
+
+  const MAX_RIPPLES = 10;
+  const FRAG = `#version 300 es
+    precision highp float;
+    #define MAX_RIPPLES ${MAX_RIPPLES}
+    in vec2 v_uv;
+    out vec4 outColor;
+
+    uniform sampler2D u_tex;
+    uniform vec2 u_res;          // canvas size in CSS px
+    uniform float u_time;        // seconds
+    uniform float u_ambient;     // 0..1 strength of idle ripple
+    uniform vec4 u_ripples[MAX_RIPPLES]; // xy = origin (uv), z = start time, w = strength
+
+    void main() {
+      float aspect = u_res.x / u_res.y;
+      vec2 offset = vec2(0.0);
+      float light = 0.0;
+
+      // Pointer / click ripples: expanding damped rings.
+      for (int i = 0; i < MAX_RIPPLES; i++) {
+        vec4 r = u_ripples[i];
+        if (r.w <= 0.0) continue;
+        float age = u_time - r.z;
+        if (age < 0.0 || age > 2.5) continue;
+
+        vec2 d = v_uv - r.xy;
+        d.x *= aspect;
+        float dist = length(d);
+        float radius = age * 0.45;
+        float ring = dist - radius;
+        // Gaussian band around the wavefront, fading with age.
+        float band = exp(-ring * ring * 180.0);
+        float fade = (1.0 - age / 2.5);
+        fade *= fade;
+        float wave = sin(ring * 60.0) * band * fade * r.w;
+
+        vec2 dir = dist > 0.0001 ? d / dist : vec2(0.0);
+        dir.x /= aspect;
+        offset += dir * wave * 0.018;
+        light += wave;
+      }
+
+      // Gentle ambient ripple emanating from the centre.
+      if (u_ambient > 0.0) {
+        vec2 d = v_uv - vec2(0.5);
+        d.x *= aspect;
+        float dist = length(d);
+        float wave = sin(dist * 28.0 - u_time * 2.2) * exp(-dist * 1.6);
+        vec2 dir = dist > 0.0001 ? d / dist : vec2(0.0);
+        dir.x /= aspect;
+        offset += dir * wave * 0.0035 * u_ambient;
+        light += wave * 0.15 * u_ambient;
+      }
+
+      vec2 uv = v_uv + offset;
+      // Subtle chromatic split along the distortion.
+      vec2 ca = offset * 0.6;
+      vec4 base = texture(u_tex, uv);
+      float r = texture(u_tex, uv + ca).r;
+      float b = texture(u_tex, uv - ca).b;
+      vec4 col = vec4(r, base.g, b, base.a);
+
+      // Specular-ish highlight on wave crests (premultiplied, so scale by alpha).
+      col.rgb += max(light, 0.0) * 0.25 * col.a;
+      outColor = col;
+    }`;
+
+  function compile(type, src) {
+    const sh = gl.createShader(type);
+    gl.shaderSource(sh, src);
+    gl.compileShader(sh);
+    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
+      throw new Error(gl.getShaderInfoLog(sh));
+    }
+    return sh;
+  }
+
+  let program;
+  try {
+    program = gl.createProgram();
+    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
+    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
+    gl.linkProgram(program);
+    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
+      throw new Error(gl.getProgramInfoLog(program));
+    }
+  } catch (err) {
+    console.error('Hero ripple shader failed:', err);
+    return fallback();
+  }
+
+  const loc = {
+    pos: gl.getAttribLocation(program, 'a_pos'),
+    tex: gl.getUniformLocation(program, 'u_tex'),
+    res: gl.getUniformLocation(program, 'u_res'),
+    time: gl.getUniformLocation(program, 'u_time'),
+    ambient: gl.getUniformLocation(program, 'u_ambient'),
+    ripples: gl.getUniformLocation(program, 'u_ripples'),
+  };
+
+  // Full-screen quad.
+  const vao = gl.createVertexArray();
+  gl.bindVertexArray(vao);
+  const vbo = gl.createBuffer();
+  gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
+  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
+  gl.enableVertexAttribArray(loc.pos);
+  gl.vertexAttribPointer(loc.pos, 2, gl.FLOAT, false, 0, 0);
+
+  // ---------------------------------------------------------------- texture
+  const texture = gl.createTexture();
+  const textureState = { width: 0, height: 0 };
+
+  // Returns the element's size in canvas grid pixels, or null if it has no
+  // paint record yet.
+  function getElementImageSize(element) {
+    let image;
+    try {
+      image = canvas.captureElementImage(element);
+    } catch {
+      canvas.requestPaint();
+      return null;
+    }
+    const width = Math.ceil(image.width);
+    const height = Math.ceil(image.height);
