+/**
+ * The Daily Grind client-side analytics.
+ *
+ * Records page views and click interactions, then debounces/batches them into
+ * a single deferred background beacon using `fetchLater()` with
+ * `activateAfter`. Every new event within the batch window aborts the pending
+ * beacon and reschedules it with the full queue, so rapid interactions
+ * coalesce into one request. If the user leaves before the window expires the
+ * browser still delivers the latest batch.
+ */
+(() => {
+  'use strict';
+
+  // POST endpoint that receives a JSON array of events.
+  const ANALYTICS_ENDPOINT = '/api/analytics';
+
+  // All events that occur within this window are sent together.
+  const BATCH_WINDOW = 10 * 1000;
+
+  // Cap the batch size so the payload stays well under the fetchLater()
+  // quota (~64KB per origin).
+  const MAX_QUEUE_SIZE = 100;
+
+  // Minimal fetchLater() polyfill for browsers without native support
+  // (Firefox, Safari). Sends on timeout or when the page becomes hidden.
+  globalThis.fetchLater ??= function fetchLater(url, init = {}) {
+    let timeoutHandle;
+    let activated = false;
+
+    function sendNow() {
+      if (!(init.signal && init.signal.aborted)) {
+        if (
+          'keepalive' in Request.prototype ||
+          init.method !== 'POST' ||
+          init.headers
+        ) {
+          fetch(url, Object.assign({}, init, {keepalive: true})).catch(() => {});
+          activated = true;
+        } else {
+          activated = navigator.sendBeacon(url, init.body);
+        }
+      }
+      destroy();
+    }
+
+    function destroy() {
+      document.removeEventListener('visibilitychange', sendNow);
+      clearTimeout(timeoutHandle);
+    }
+
+    if (document.visibilityState === 'hidden') {
+      queueMicrotask(sendNow);
+    } else {
+      document.addEventListener('visibilitychange', sendNow);
+      if (typeof init.activateAfter === 'number' && init.activateAfter >= 0) {
+        timeoutHandle = setTimeout(sendNow, init.activateAfter);
+      }
+    }
+
+    if (init.signal) {
+      init.signal.addEventListener('abort', destroy);
+    }
+
+    return {
+      get activated() {
+        return activated;
+      },
+    };
+  };
+
+  const sessionId =
+    typeof crypto.randomUUID === 'function'
+      ? crypto.randomUUID()
+      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
+
+  const eventQueue = [];
+  let fetchLaterResult = null;
+  let fetchLaterController = null;
+
+  function startNewBatch() {
+    // Intentionally does NOT abort the previous controller: a full batch
+    // should still be delivered by its pending beacon.
+    fetchLaterController = null;
+    fetchLaterResult = null;
+    eventQueue.length = 0;
+  }
+
+  function trackEvent(type, data = {}) {
+    // Previous beacon already sent, or current batch is full: start fresh.
+    if (fetchLaterResult?.activated || eventQueue.length >= MAX_QUEUE_SIZE) {
+      startNewBatch();
+    }
+
+    eventQueue.push({
+      type,
+      ts: Date.now(),
+      path: location.pathname,
+      ...data,
+    });
+
+    // Debounce: replace the pending beacon with one carrying the full queue.
+    fetchLaterController?.abort();
+    fetchLaterController = new AbortController();
+
+    try {
+      fetchLaterResult = fetchLater(ANALYTICS_ENDPOINT, {
+        method: 'POST',
+        headers: {'content-type': 'application/json'},
+        body: JSON.stringify({sessionId, events: eventQueue}),
+        signal: fetchLaterController.signal,
+        activateAfter: BATCH_WINDOW,
+      });
+    } catch (error) {
+      // Most likely a quota error; drop this batch rather than break the page.
+      startNewBatch();
+    }
+  }
+
+  // Describe a clicked element without capturing user-entered content.
