+  'use strict';
+
+  var ENDPOINT = '/api/analytics';
+  var DEBOUNCE_MS = 1000;
+  var MAX_WAIT_MS = 5000;
+  var MAX_BATCH = 25;
+  var MAX_QUEUE = 200;
+  var MAX_TEXT = 80;
+
+  var nav = window.navigator || {};
