+        timer.dataset.state = 'upcoming';
+        const untilStart = now.until(start, diffOptions);
+        remainingEl.textContent = `Coming soon — starts in ${formatter.format(untilStart)}`;
+        elapsedEl.hidden = true;
+        return;
+      }
+
+      const elapsed = now.since(start, diffOptions);
+      elapsedEl.textContent = `Promotion running for ${formatter.format(elapsed)}`;
+      elapsedEl.hidden = false;
+
+      if (remaining.sign <= 0 && Temporal.ZonedDateTime.compare(now, end) >= 0) {
