+      if (anniversary) {
+        const today = Temporal.Now.plainDateISO();
+        const monthDay = anniversary.toPlainMonthDay();
+        let next = monthDay.toPlainDate({ year: today.year });
+        if (Temporal.PlainDate.compare(next, today) < 0) {
+          next = monthDay.toPlainDate({ year: today.year + 1 });
+        }
+        const days = today.until(next, { largestUnit: 'day' }).days;
+        const years = next.year - anniversary.year;
+        const when = anniversary.toLocaleString(undefined, { dateStyle: 'long' });
+        anniversarySummary.textContent = days === 0
+          ? `Happy ${years}-year coffee anniversary! (since ${when})`
+          : `Since ${when}. Next anniversary in ${days} day${days === 1 ? '' : 's'}.`;
+      } else {
+        anniversarySummary.textContent = '';
+      }
+    }
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      try {
+        const prefs = {
+          pickupTime: timeInput.value ? Temporal.PlainTime.from(timeInput.value) : null,
+          anniversary: dateInput.value ? Temporal.PlainDate.from(dateInput.value) : null,
+        };
+        save(prefs);
+        render(prefs);
+        status.textContent = 'Preferences saved.';
+      } catch {
+        status.textContent = 'Please enter a valid time and date.';
+      }
+    });
+
+    render(load());
+  </script>
+
 </body>

