+  <script>
+    /*
+     * Coffee reminders are stored as "floating" wall-clock values:
+     *   pickupTime      -> "HH:MM"       (e.g. "07:30")
+     *   anniversaryDate -> "YYYY-MM-DD"  (e.g. "2021-04-12")
+     * They are never turned into timestamps / local Date objects, so a
+     * change of device time zone (travel, DST) can never shift them.
+     * 07:30 stays 07:30 in Tokyo or New York; April 12 stays April 12.
+     */
+    (function () {
+      var STORAGE_KEY = 'dailyGrind.reminders';
+      var TIME_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;
+      var DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
+      var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
+        'August', 'September', 'October', 'November', 'December'];
+
+      var form = document.getElementById('prefs-form');
+      var timeInput = document.getElementById('pickup-time');
+      var dateInput = document.getElementById('anniversary-date');
+      var timeDisplay = document.getElementById('pickup-display');
+      var dateDisplay = document.getElementById('anniversary-display');
+      var statusEl = document.getElementById('prefs-status');
+      var clearBtn = document.getElementById('prefs-clear');
+
+      function isValidTime(v) {
+        return TIME_RE.test(v);
+      }
+
+      function parseDate(v) {
+        var m = DATE_RE.exec(v || '');
+        if (!m) return null;
+        var y = +m[1], mo = +m[2], d = +m[3];
+        // Validate via UTC arithmetic only (no local time zone involved).
+        var check = new Date(Date.UTC(y, mo - 1, d));
+        if (check.getUTCFullYear() !== y || check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) {
+          return null;
+        }
+        return { y: y, m: mo, d: d };
+      }
+
+      function formatTime(v) {
+        var m = TIME_RE.exec(v);
+        var h = +m[1];
+        var suffix = h < 12 ? 'AM' : 'PM';
+        var h12 = h % 12 === 0 ? 12 : h % 12;
+        return h12 + ':' + m[2] + ' ' + suffix;
+      }
+
+      function isLeap(y) {
+        return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
+      }
+
+      // Calendar-day number for a Y/M/D, computed in UTC so it's TZ-independent.
+      function dayNumber(y, m, d) {
+        return Math.round(Date.UTC(y, m - 1, d) / 86400000);
+      }
+
+      function daysUntilAnniversary(p) {
+        // "Today" is whatever the calendar says where the user currently is.
+        var now = new Date();
+        var ty = now.getFullYear(), tm = now.getMonth() + 1, td = now.getDate();
+        var today = dayNumber(ty, tm, td);
+        function occurrence(year) {
+          var day = p.d;
+          if (p.m === 2 && p.d === 29 && !isLeap(year)) day = 28;
+          return dayNumber(year, p.m, day);
+        }
+        var next = occurrence(ty);
+        var year = ty;
+        if (next < today) {
+          year = ty + 1;
+          next = occurrence(year);
+        }
+        return { days: next - today, years: year - p.y };
+      }
+
+      function describeAnniversary(v) {
+        var p = parseDate(v);
+        if (!p) return '';
+        var text = MONTHS[p.m - 1] + ' ' + p.d + ', ' + p.y;
+        var info = daysUntilAnniversary(p);
+        if (info.years <= 0) {
+          if (info.days === 0) return 'Saved: ' + text + ' — your coffee journey starts today! ☕';
+          return 'Saved: ' + text;
+        }
+        var label = info.years + (info.years === 1 ? ' year' : ' years');
+        if (info.days === 0) return 'Saved: ' + text + ' — happy ' + label + ' anniversary today! ☕';
+        return 'Saved: ' + text + ' — ' + label + ' in ' + info.days + (info.days === 1 ? ' day' : ' days');
+      }
+
+      function load() {
+        try {
+          var data = JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
+          return {
+            pickupTime: isValidTime(data.pickupTime) ? data.pickupTime : '',
+            anniversaryDate: parseDate(data.anniversaryDate) ? data.anniversaryDate : ''
+          };
+        } catch (e) {
+          return { pickupTime: '', anniversaryDate: '' };
+        }
+      }
+
+      function render(prefs) {
+        // Assign raw strings to .value (never valueAsDate/valueAsNumber),
+        // so the inputs show exactly what was chosen.
+        timeInput.value = prefs.pickupTime;
+        dateInput.value = prefs.anniversaryDate;
+        timeDisplay.textContent = prefs.pickupTime ? 'Saved: every day at ' + formatTime(prefs.pickupTime) + ' (local time wherever you are)' : '';
+        dateDisplay.textContent = describeAnniversary(prefs.anniversaryDate);
+      }
+
+      function setStatus(msg, isError) {
+        statusEl.textContent = msg;
+        statusEl.style.color = isError ? '#c62828' : '#2e7d32';
+      }
+
+      form.addEventListener('submit', function (e) {
+        e.preventDefault();
+        var t = timeInput.value.slice(0, 5); // drop seconds if a browser adds them
+        var d = dateInput.value;
+        if (t && !isValidTime(t)) return setStatus('Please enter a valid pickup time.', true);
+        if (d && !parseDate(d)) return setStatus('Please enter a valid anniversary date.', true);
+        var prefs = { pickupTime: t, anniversaryDate: d };
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
+        } catch (err) {
+          return setStatus('Could not save reminders on this device.', true);
+        }
+        render(prefs);
+        setStatus('Reminders saved.');
+      });
+
+      clearBtn.addEventListener('click', function () {
+        try { localStorage.removeItem(STORAGE_KEY); } catch (err) { /* ignore */ }
+        render({ pickupTime: '', anniversaryDate: '' });
+        setStatus('Reminders cleared.');
+      });
+
+      render(load());
+    })();
+  </script>
+
