+  <script>
+    (() => {
+      const KEY = 'dailyGrindOrder';
+      const countEl = document.getElementById('order-count');
+      let order;
+      try { order = JSON.parse(localStorage.getItem(KEY)) || []; } catch { order = []; }
+
+      const renderCount = () => {
+        const n = order.reduce((sum, line) => sum + line.qty, 0);
+        countEl.textContent = n;
+        countEl.setAttribute('aria-label', n === 1 ? '1 item' : `${n} items`);
+      };
+      renderCount();
+
+      document.querySelectorAll('.order-form').forEach((form) => {
+        const price = form.querySelector('.price');
+        const msg = form.querySelector('.added-msg');
+        let timer;
+
+        form.addEventListener('change', (e) => {
+          if (e.target.name === 'size') price.textContent = `$${e.target.dataset.price}`;
+        });
+
+        form.addEventListener('submit', (e) => {
+          e.preventDefault();
+          const size = form.elements.size.value;
+          const item = form.elements.item.value;
+          const unit = Number(form.querySelector('input[name="size"]:checked').dataset.price);
+          const line = order.find((l) => l.item === item && l.size === size);
+          if (line) line.qty += 1;
+          else order.push({ item, name: form.dataset.item, size, price: unit, qty: 1 });
+          try { localStorage.setItem(KEY, JSON.stringify(order)); } catch {}
+          renderCount();
+          msg.textContent = `Added a ${size} ${form.dataset.item} to your order.`;
+          clearTimeout(timer);
+          timer = setTimeout(() => { msg.textContent = ''; }, 4000);
+        });
+      });
+    })();
+  </script>
+
