+  <script>
+    (function () {
+      var STORAGE_KEY = 'dailyGrindOrder';
+      var countEl = document.querySelector('.order-count');
+      var toast = document.querySelector('.order-toast');
+      var toastTimer;
+
+      function loadOrder() {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
+        catch (e) { return []; }
+      }
+
+      function saveOrder(order) {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(order)); } catch (e) { /* storage unavailable */ }
+      }
+
+      function renderCount(order) {
+        var n = order.reduce(function (sum, item) { return sum + item.qty; }, 0);
+        countEl.textContent = n;
+        countEl.dataset.count = n;
+      }
+
+      function showToast(msg) {
+        toast.textContent = msg;
+        toast.classList.add('is-visible');
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(function () { toast.classList.remove('is-visible'); }, 2500);
+      }
+
+      function priceFor(card, sizeInput) {
+        var base = parseFloat(card.dataset.basePrice);
+        var up = sizeInput ? parseFloat(sizeInput.dataset.upcharge) : 0;
+        return base + up;
+      }
+
+      renderCount(loadOrder());
+
+      document.querySelectorAll('.drink-card').forEach(function (card) {
+        var form = card.querySelector('.drink-card__form');
+        var priceEl = card.querySelector('[data-price]');
+        var btn = card.querySelector('.add-btn');
+        var img = card.querySelector('.drink-card__media img');
+        var resetTimer;
+
+        if (img) {
+          img.addEventListener('error', function () { img.classList.add('is-broken'); });
+        }
+
+        form.addEventListener('change', function (e) {
+          if (e.target.type === 'radio') {
+            priceEl.textContent = '$' + priceFor(card, e.target).toFixed(2);
+          }
+        });
+
+        form.addEventListener('submit', function (e) {
+          e.preventDefault();
+          var sizeInput = form.querySelector('input[type="radio"]:checked');
+          if (!sizeInput) {
+            showToast('Please choose a size first.');
+            return;
+          }
+
+          var size = sizeInput.value;
+          var order = loadOrder();
+          var existing = order.find(function (item) {
+            return item.id === card.dataset.drinkId && item.size === size;
+          });
+          if (existing) {
+            existing.qty += 1;
+          } else {
+            order.push({
+              id: card.dataset.drinkId,
+              name: card.dataset.drinkName,
+              size: size,
+              price: priceFor(card, sizeInput),
+              qty: 1
+            });
+          }
+          saveOrder(order);
+          renderCount(order);
+
+          var label = size.charAt(0).toUpperCase() + size.slice(1);
+          showToast(label + ' ' + card.dataset.drinkName + ' added to your order.');
+
+          btn.classList.add('is-added');
+          btn.textContent = 'Added \u2713';
+          clearTimeout(resetTimer);
+          resetTimer = setTimeout(function () {
+            btn.classList.remove('is-added');
+            btn.textContent = 'Add to Order';
+          }, 1800);
+        });
+      });
+    })();
