@@ -0,0 +1,334 @@
+// Encrypted delivery notes for The Daily Grind.
+//
+// Envelope flow:
+//   1. The store (recipient) has a long-lived KEM key pair, persisted as
+//      non-extractable CryptoKeys in IndexedDB. Its public key is shared with
+//      customers (here: read from the same browser, standing in for a
+//      server-published key).
+//   2. For each note the customer encapsulates a fresh one-time shared key to
+//      the store's public key and encrypts the note with an AEAD cipher.
+//      The order number and suite are bound as additional authenticated data.
+//   3. Only the holder of the store's private key can decapsulate the key and
+//      decrypt; any tampering with ciphertext, capsule, or metadata fails.
+//
+// Preferred suite: hybrid post-quantum MLKEM768-X25519 + ChaCha20-Poly1305.
+// Fallback suite:  ephemeral-static X25519 + HKDF-SHA-256 + AES-GCM.
+
+const PQ_SUITE = 'MLKEM768-X25519+ChaCha20-Poly1305';
+const CLASSIC_SUITE = 'X25519+HKDF-SHA256+AES-GCM';
+const ENVELOPE_VERSION = 1;
+const HKDF_INFO = new TextEncoder().encode('daily-grind/delivery-note/v1');
+
+const DB_NAME = 'daily-grind-crypto';
+const STORE_NAME = 'keys';
+const KEY_ID = 'store-recipient-key';
+
+// ---------- encoding helpers ----------
+
+function toBase64(bytes) {
+  if (typeof bytes.toBase64 === 'function') return bytes.toBase64();
+  let binary = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(binary);
+}
+
+function fromBase64(str) {
+  if (typeof Uint8Array.fromBase64 === 'function') return Uint8Array.fromBase64(str);
+  return Uint8Array.from(atob(str), (c) => c.charCodeAt(0));
+}
+
+function aadFor(version, suite, orderId) {
+  return new TextEncoder().encode(JSON.stringify({ v: version, suite, orderId }));
+}
+
+// ---------- feature detection ----------
+
+export function supportsPostQuantumEnvelope() {
+  try {
+    return (
+      typeof globalThis.SubtleCrypto?.supports === 'function' &&
+      SubtleCrypto.supports('generateKey', 'MLKEM768-X25519') &&
+      SubtleCrypto.supports('encapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305')
+    );
+  } catch {
+    return false;
+  }
+}
+
+// ---------- IndexedDB persistence ----------
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE_NAME);
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function idb(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE_NAME, mode);
+      const req = fn(tx.objectStore(STORE_NAME));
+      tx.oncomplete = () => resolve(req.result);
+      tx.onerror = () => reject(tx.error);
+      tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+// ---------- recipient (store) keys ----------
+
+async function generateRecipientKeys() {
+  if (supportsPostQuantumEnvelope()) {
+    const keyPair = await crypto.subtle.generateKey(
+      'MLKEM768-X25519',
+      false,
+      ['encapsulateKey', 'decapsulateKey'],
+    );
+    return { suite: PQ_SUITE, keyPair };
+  }
+  const keyPair = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  return { suite: CLASSIC_SUITE, keyPair };
+}
+
+/** Load the store key pair from IndexedDB, creating it on first use. */
+export async function getRecipientKeys({ rotate = false } = {}) {
+  if (!rotate) {
+    const existing = await idb('readonly', (s) => s.get(KEY_ID));
+    if (existing?.keyPair && existing?.suite) return existing;
+  }
+  const record = await generateRecipientKeys();
+  // Non-extractable CryptoKeys are structured-cloneable into IndexedDB.
+  await idb('readwrite', (s) => s.put(record, KEY_ID));
+  return record;
+}
+
+export async function exportPublicKey({ suite, keyPair }) {
+  const format = suite === PQ_SUITE ? 'raw-public' : 'raw';
+  return new Uint8Array(await crypto.subtle.exportKey(format, keyPair.publicKey));
+}
+
+// ---------- key encapsulation ----------
+
+async function deriveClassicAesKey(privateKey, peerPublicKey) {
+  const sharedSecret = await crypto.subtle.deriveBits(
+    { name: 'X25519', public: peerPublicKey },
+    privateKey,
+    256,
+  );
+  const hkdfKey = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(32), info: HKDF_INFO },
+    hkdfKey,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+async function encapsulate(suite, publicKeyBytes) {
+  if (suite === PQ_SUITE) {
+    const pub = await crypto.subtle.importKey(
+      'raw-public',
+      publicKeyBytes,
+      'MLKEM768-X25519',
+      true,
+      ['encapsulateKey'],
+    );
+    const { sharedKey, ciphertext } = await crypto.subtle.encapsulateKey(
+      'MLKEM768-X25519',
+      pub,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt'],
+    );
+    return { sharedKey, capsule: new Uint8Array(ciphertext) };
+  }
+
+  // Classical: ephemeral X25519 key pair, ephemeral public key is the capsule.
+  const pub = await crypto.subtle.importKey('raw', publicKeyBytes, 'X25519', true, []);
+  const ephemeral = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  const capsule = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeral.publicKey));
+  const sharedKey = await deriveClassicAesKey(ephemeral.privateKey, pub);
+  return { sharedKey, capsule };
+}
+
+async function decapsulate(suite, privateKey, capsule) {
+  if (suite === PQ_SUITE) {
+    return crypto.subtle.decapsulateKey(
+      'MLKEM768-X25519',
+      privateKey,
+      capsule,
+      'ChaCha20-Poly1305',
+      false,
+      ['decrypt'],
+    );
+  }
+  const ephemeralPub = await crypto.subtle.importKey('raw', capsule, 'X25519', true, []);
+  return deriveClassicAesKey(privateKey, ephemeralPub);
+}
+
+// ---------- public API ----------
+
+/**
+ * Encrypt a delivery note to the store's public key.
+ * @param {{suite: string, publicKeyBytes: Uint8Array}} recipient
+ * @param {string} orderId  bound as authenticated (unencrypted) metadata
+ * @param {string} note     sensitive plaintext
+ */
+export async function sealNote({ suite, publicKeyBytes }, orderId, note) {
+  const { sharedKey, capsule } = await encapsulate(suite, publicKeyBytes);
+  const iv = crypto.getRandomValues(new Uint8Array(12)); // fresh per message
+  const ciphertext = new Uint8Array(
+    await crypto.subtle.encrypt(
+      { name: sharedKey.algorithm.name, iv, additionalData: aadFor(ENVELOPE_VERSION, suite, orderId) },
+      sharedKey,
+      new TextEncoder().encode(note),
+    ),
+  );
+  return {
+    v: ENVELOPE_VERSION,
+    suite,
+    orderId,
+    capsule: toBase64(capsule),
+    iv: toBase64(iv),
+    ciphertext: toBase64(ciphertext),
+  };
+}
+
+/**
+ * Decrypt an envelope with the store's private key.
+ * Throws if the envelope was tampered with or was sealed to another key.
+ */
+export async function openNote({ suite, keyPair }, envelope) {
+  if (envelope?.v !== ENVELOPE_VERSION) throw new Error('Unsupported envelope version.');
+  if (envelope.suite !== suite) {
+    throw new Error(`Envelope uses ${envelope.suite}, but the store key is ${suite}.`);
+  }
+  if (typeof envelope.orderId !== 'string') throw new Error('Envelope is missing an order number.');
+  const key = await decapsulate(suite, keyPair.privateKey, fromBase64(envelope.capsule));
+  const plaintext = await crypto.subtle.decrypt(
+    {
+      name: key.algorithm.name,
+      iv: fromBase64(envelope.iv),
+      additionalData: aadFor(envelope.v, envelope.suite, envelope.orderId),
+    },
+    key,
+    fromBase64(envelope.ciphertext),
+  );
+  return new TextDecoder().decode(plaintext);
+}
+
+export const SUITES = { PQ_SUITE, CLASSIC_SUITE };
+
+// ---------- UI wiring ----------
+
+function initUi() {
+  const root = document.getElementById('delivery-notes');
+  if (!root) return;
+
+  const form = root.querySelector('#note-form');
+  const orderInput = root.querySelector('#note-order');
+  const noteInput = root.querySelector('#note-text');
+  const envelopeOut = root.querySelector('#note-envelope');
+  const suiteBadge = root.querySelector('#note-suite');
+  const fingerprint = root.querySelector('#note-fingerprint');
+  const status = root.querySelector('#note-status');
+  const decryptBtn = root.querySelector('#note-decrypt');
+  const rotateBtn = root.querySelector('#note-rotate');
+  const decrypted = root.querySelector('#note-decrypted');
+
+  let recipient = null;
+
+  const setStatus = (msg, kind = 'info') => {
+    status.textContent = msg;
+    status.dataset.kind = kind;
+  };
+
+  async function loadKeys(rotate = false) {
+    const keys = await getRecipientKeys({ rotate });
+    const publicKeyBytes = await exportPublicKey(keys);
+    const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', publicKeyBytes));
+    recipient = { ...keys, publicKeyBytes };
+    const pq = keys.suite === PQ_SUITE;
+    suiteBadge.textContent = pq ? 'Hybrid post-quantum' : 'Classical (X25519)';
+    suiteBadge.dataset.pq = String(pq);
+    suiteBadge.title = keys.suite;
+    fingerprint.textContent = Array.from(digest.subarray(0, 8), (b) =>
+      b.toString(16).padStart(2, '0'),
+    ).join(':');
+  }
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    if (!form.reportValidity() || !recipient) return;
+    try {
+      const envelope = await sealNote(recipient, orderInput.value.trim(), noteInput.value);
+      envelopeOut.value = JSON.stringify(envelope, null, 2);
+      noteInput.value = ''; // don't leave plaintext lying around
+      decrypted.hidden = true;
+      decryptBtn.disabled = false;
+      setStatus(
+        `Note sealed with ${envelope.suite}. Only the store's private key can open it.`,
+        'success',
+      );
+    } catch (err) {
+      setStatus(`Encryption failed: ${err.message}`, 'error');
+    }
+  });
+
+  decryptBtn.addEventListener('click', async () => {
+    decrypted.hidden = true;
+    let envelope;
+    try {
+      envelope = JSON.parse(envelopeOut.value);
+    } catch {
+      setStatus('The envelope is not valid JSON.', 'error');
+      return;
+    }
+    try {
+      const note = await openNote(recipient, envelope);
+      decrypted.querySelector('[data-order]').textContent = envelope.orderId;
+      decrypted.querySelector('[data-note]').textContent = note;
+      decrypted.hidden = false;
+      setStatus('Envelope authenticated and decrypted with the store key.', 'success');
+    } catch (err) {
+      const msg =
+        err?.name === 'OperationError'
+          ? 'Authentication failed: the envelope was modified or sealed to a different key.'
+          : `Decryption failed: ${err.message}`;
+      setStatus(msg, 'error');
+    }
+  });
+
+  rotateBtn.addEventListener('click', async () => {
+    try {
+      await loadKeys(true);
+      decrypted.hidden = true;
+      setStatus('Store key rotated. Previously sealed notes can no longer be opened.', 'info');
+    } catch (err) {
+      setStatus(`Key rotation failed: ${err.message}`, 'error');
+    }
+  });
+
+  if (!globalThis.crypto?.subtle) {
+    setStatus('Encryption requires a secure (HTTPS) context.', 'error');
+    form.querySelector('button[type="submit"]').disabled = true;
+    rotateBtn.disabled = true;
+    return;
+  }
+
+  loadKeys().catch((err) => {
+    setStatus(`Could not set up encryption keys: ${err.message}`, 'error');
+    form.querySelector('button[type="submit"]').disabled = true;
+  });
+}
+
+initUi();
