+// Daily Grind — sealed delivery notes.
+//
+// Hybrid public-key encryption ("seal to the store's public key") for
+// sensitive customer delivery notes. Shared by the homepage (browser) and
+// the staff tools in /tools (Node 20+); both provide WebCrypto as
+// `globalThis.crypto`.
+//
+// Construction (KEM/DEM, in the spirit of HPKE base mode):
+//
+//   1. Key establishment, one of three suites:
+//        X-Wing     — hybrid ML-KEM-768 + X25519 KEM (draft-connolly-cfrg-xwing-kem).
+//                     Secure as long as EITHER primitive holds. Default.
+//        ML-KEM-768 — FIPS 203 post-quantum KEM on its own.
+//        X25519     — classical ephemeral-static ECDH (RFC 7748). Not
+//                     quantum-safe; offered for interoperability only.
+//      Each produces a 32-byte shared secret `ss` and an encapsulation
+//      `enc` (KEM ciphertext, or the ephemeral X25519 public key).
+//
+//   2. Key schedule: HKDF-SHA-256
+//        salt = SHA-256(enc)
+//        info = "DailyGrind/delivery-notes/v1|" || suite || "|" || kid
+//      where kid = SHA-256(KID_LABEL || suite || recipientPublicKey)[0..16],
+//      binding the derived key to the exact recipient key and transcript.
+//
+//   3. Authenticated encryption: AES-256-GCM with a random 96-bit IV. The
+//      envelope header (version, suite, kid, enc, iv, order ref, timestamp)
+//      is passed as additional authenticated data, so tampering with any of
+//      it makes decryption fail. Each note uses a fresh key (fresh KEM
+//      encapsulation), so IV reuse is not a concern.
+//
+//   The plaintext is padded (ISO/IEC 7816-4) to a multiple of 128 bytes so
+//   the ciphertext length doesn't reveal the exact note length.
+
+import { ml_kem768_x25519 } from '@noble/post-quantum/hybrid.js';
+import { ml_kem768 } from '@noble/post-quantum/ml-kem.js';
+import { x25519 } from '@noble/curves/ed25519.js';
+
+export const ENVELOPE_VERSION = 1;
+export const MAX_NOTE_CHARS = 1000;
+const PAD_BLOCK = 128;
+const IV_BYTES = 12;
+const KID_BYTES = 16;
+const KID_LABEL = 'DailyGrind/delivery-notes/kid/v1|';
+const INFO_LABEL = 'DailyGrind/delivery-notes/v1|';
+
+const subtle = globalThis.crypto?.subtle;
+const enc8 = new TextEncoder();
+const dec8 = new TextDecoder('utf-8', { fatal: true });
+
+/** Supported key-establishment suites, in order of preference. */
+export const SUITES = Object.freeze({
+  'X-Wing': {
+    label: 'Hybrid post-quantum (X-Wing: ML-KEM-768 + X25519)',
+    quantumSafe: true,
+    publicKeyBytes: ml_kem768_x25519.lengths.publicKey, // 1216
+    encBytes: ml_kem768_x25519.lengths.cipherText, // 1120
+    keygen() {
+      const { publicKey, secretKey } = ml_kem768_x25519.keygen();
+      return { publicKey, secretKey }; // secretKey is a 32-byte seed
+    },
+    encapsulate(pk) {
+      const { cipherText, sharedSecret } = ml_kem768_x25519.encapsulate(pk);
+      return { enc: cipherText, ss: sharedSecret };
+    },
+    decapsulate(enc, sk) {
+      return ml_kem768_x25519.decapsulate(enc, sk);
+    },
+  },
+  'ML-KEM-768': {
+    label: 'Post-quantum only (ML-KEM-768, FIPS 203)',
+    quantumSafe: true,
+    publicKeyBytes: ml_kem768.lengths.publicKey, // 1184
+    encBytes: ml_kem768.lengths.cipherText, // 1088
+    keygen() {
+      const seed = randomBytes(64);
+      const { publicKey } = ml_kem768.keygen(seed);
+      return { publicKey, secretKey: seed }; // store the 64-byte seed (d || z)
+    },
+    encapsulate(pk) {
+      const { cipherText, sharedSecret } = ml_kem768.encapsulate(pk);
+      return { enc: cipherText, ss: sharedSecret };
+    },
+    decapsulate(enc, seed) {
+      const { secretKey } = ml_kem768.keygen(seed);
+      try {
+        return ml_kem768.decapsulate(enc, secretKey);
+      } finally {
+        secretKey.fill(0);
+      }
+    },
+  },
+  X25519: {
+    label: 'Classical (X25519 ECDH) — not quantum-safe',
+    quantumSafe: false,
+    publicKeyBytes: 32,
+    encBytes: 32,
+    keygen() {
+      const secretKey = x25519.utils.randomSecretKey();
+      return { publicKey: x25519.getPublicKey(secretKey), secretKey };
+    },
+    encapsulate(pk) {
+      const eph = x25519.utils.randomSecretKey();
+      try {
+        // noble rejects low-order points / all-zero shared secrets.
+        return { enc: x25519.getPublicKey(eph), ss: x25519.getSharedSecret(eph, pk) };
+      } finally {
+        eph.fill(0);
+      }
+    },
+    decapsulate(enc, sk) {
+      return x25519.getSharedSecret(sk, enc);
+    },
+  },
+});
+
+export const DEFAULT_SUITE = 'X-Wing';
+
+// ---------------------------------------------------------------- encoding
+
+export function randomBytes(n) {
+  return globalThis.crypto.getRandomValues(new Uint8Array(n));
+}
+
+export function toB64u(bytes) {
+  let s = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromB64u(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url data');
+  }
+  const bin = atob(str.replace(/-/g, '+').replace(/_/g, '/'));
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+export function toHex(bytes) {
+  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+}
+
+function concat(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let off = 0;
+  for (const p of parts) {
+    out.set(p, off);
+    off += p.length;
+  }
+  return out;
+}
+
+async function sha256(bytes) {
+  return new Uint8Array(await subtle.digest('SHA-256', bytes));
+}
+
+function pad(bytes) {
+  const len = Math.ceil((bytes.length + 1) / PAD_BLOCK) * PAD_BLOCK;
+  const out = new Uint8Array(len);
+  out.set(bytes);
+  out[bytes.length] = 0x80;
+  return out;
+}
+
+function unpad(bytes) {
+  let i = bytes.length - 1;
+  while (i >= 0 && bytes[i] === 0) i--;
+  if (i < 0 || bytes[i] !== 0x80) throw new Error('Invalid padding');
+  return bytes.subarray(0, i);
+}
+
+// ----------------------------------------------------------- key handling
+
+function getSuite(name) {
+  if (!Object.prototype.hasOwnProperty.call(SUITES, name)) {
+    throw new Error(`Unsupported suite: ${String(name)}`);
+  }
+  return SUITES[name];
+}
+
+/** Key id: binds a public key to its suite. Hex, 16 bytes. */
+export async function keyId(suiteName, publicKey) {
+  const h = await sha256(concat(enc8.encode(KID_LABEL + suiteName + '|'), publicKey));
+  return toHex(h.subarray(0, KID_BYTES));
+}
+
+/** Human-friendly fingerprint for display, e.g. "3f2a 91c0 …". */
+export function formatFingerprint(kid) {
+  return kid.match(/.{1,4}/g).join(' ');
+}
+
+/**
+ * Parse and validate the store's published key bundle
+ * (keys/delivery-notes.pub.json). Returns { suiteName: { publicKey, kid } }.
+ * Each kid is recomputed locally rather than trusted from the file.
+ */
+export async function importPublicBundle(json) {
+  if (!json || json.version !== 1 || typeof json.keys !== 'object' || json.keys === null) {
+    throw new Error('Unrecognised public key bundle');
+  }
+  const out = {};
+  for (const [name, b64] of Object.entries(json.keys)) {
+    if (!Object.prototype.hasOwnProperty.call(SUITES, name)) continue; // ignore unknown future suites
+    const publicKey = fromB64u(b64);
+    if (publicKey.length !== SUITES[name].publicKeyBytes) {
+      throw new Error(`Bad ${name} public key length`);
+    }
+    out[name] = { publicKey, kid: await keyId(name, publicKey) };
+  }
+  if (!Object.keys(out).length) throw new Error('Key bundle contains no supported keys');
+  return out;
+}
+
+/** Generate a fresh recipient key set for all suites (store/staff side). */
+export async function generateKeyBundle() {
+  const pub = { version: 1, created: new Date().toISOString(), keys: {}, kids: {} };
+  const priv = { version: 1, created: pub.created, keys: {} };
+  for (const [name, suite] of Object.entries(SUITES)) {
+    const { publicKey, secretKey } = suite.keygen();
+    const kid = await keyId(name, publicKey);
+    pub.keys[name] = toB64u(publicKey);
+    pub.kids[name] = kid;
+    priv.keys[name] = { kid, secretKey: toB64u(secretKey) };
+    secretKey.fill(0);
+  }
+  return { publicBundle: pub, privateBundle: priv };
+}
+
+// ------------------------------------------------------ seal / open notes
+
+function headerAad(h) {
+  // Fixed field order => deterministic bytes on both sides.
+  return enc8.encode(
+    JSON.stringify([h.v, h.suite, h.kid, h.enc, h.iv, h.order ?? null, h.created])
+  );
+}
+
+async function deriveAesKey(ss, encBytes, suiteName, kid, usage) {
+  const ikm = await subtle.importKey('raw', ss, 'HKDF', false, ['deriveKey']);
+  return subtle.deriveKey(
+    {
+      name: 'HKDF',
+      hash: 'SHA-256',
+      salt: await sha256(encBytes),
+      info: enc8.encode(`${INFO_LABEL}${suiteName}|${kid}`),
+    },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    [usage]
+  );
+}
+
+const ORDER_RE = /^[A-Za-z0-9-]{1,32}$/;
+
+/**
+ * Encrypt a delivery note to the store.
+ * @param {string} note plaintext note (≤ MAX_NOTE_CHARS)
+ * @param {{publicKey: Uint8Array, kid: string}} recipient from importPublicBundle
+ * @param {{suite?: string, order?: string}} [opts]
+ * @returns {Promise<object>} JSON-serialisable envelope
+ */
+export async function sealNote(note, recipient, { suite = DEFAULT_SUITE, order } = {}) {
+  if (!subtle) throw new Error('WebCrypto is unavailable (a secure https:// context is required)');
+  if (typeof note !== 'string' || !note.trim()) throw new Error('Note is empty');
+  if ([...note].length > MAX_NOTE_CHARS) throw new Error(`Note exceeds ${MAX_NOTE_CHARS} characters`);
+  if (order != null && order !== '' && !ORDER_RE.test(order)) throw new Error('Invalid order reference');
+  const s = getSuite(suite);
+  if (recipient.kid !== (await keyId(suite, recipient.publicKey))) throw new Error('Recipient key mismatch');
+
+  const { enc, ss } = s.encapsulate(recipient.publicKey);
+  const iv = randomBytes(IV_BYTES);
+  const header = {
+    v: ENVELOPE_VERSION,
+    suite,
+    kid: recipient.kid,
+    enc: toB64u(enc),
+    iv: toB64u(iv),
+    order: order || null,
+    created: new Date().toISOString(),
+  };
+  const plaintext = pad(enc8.encode(note));
+  try {
+    const key = await deriveAesKey(ss, enc, suite, recipient.kid, 'encrypt');
+    const ct = await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: headerAad(header) }, key, plaintext);
+    return { ...header, ct: toB64u(new Uint8Array(ct)) };
+  } finally {
+    ss.fill(0);
+    plaintext.fill(0);
+  }
+}
+
+/**
+ * Decrypt an envelope with the store's private bundle (staff side).
+ * Throws on any authentication or format failure.
+ * @returns {Promise<{note: string, order: string|null, created: string, suite: string}>}
+ */
+export async function openNote(envelope, privateBundle) {
+  if (!envelope || envelope.v !== ENVELOPE_VERSION) throw new Error('Unsupported envelope version');
+  const s = getSuite(envelope.suite);
+  const entry = privateBundle?.keys?.[envelope.suite];
+  if (!entry || entry.kid !== envelope.kid) throw new Error('No private key for this envelope (kid mismatch)');
+  if (envelope.order != null && !ORDER_RE.test(envelope.order)) throw new Error('Invalid order reference');
+  if (typeof envelope.created !== 'string') throw new Error('Missing timestamp');
+
+  const enc = fromB64u(envelope.enc);
+  const iv = fromB64u(envelope.iv);
+  const ct = fromB64u(envelope.ct);
+  if (enc.length !== s.encBytes) throw new Error('Bad encapsulation length');
+  if (iv.length !== IV_BYTES) throw new Error('Bad IV length');
+  if (ct.length < PAD_BLOCK + 16 || (ct.length - 16) % PAD_BLOCK !== 0) throw new Error('Bad ciphertext length');
+
+  const sk = fromB64u(entry.secretKey);
+  let ss;
+  try {
+    ss = s.decapsulate(enc, sk);
+    const key = await deriveAesKey(ss, enc, envelope.suite, envelope.kid, 'decrypt');
+    let pt;
+    try {
+      pt = new Uint8Array(
+        await subtle.decrypt({ name: 'AES-GCM', iv, additionalData: headerAad(envelope) }, key, ct)
+      );
+    } catch {
+      throw new Error('Decryption failed: note was tampered with or sealed to a different key');
+    }
+    const note = dec8.decode(unpad(pt));
+    pt.fill(0);
+    return { note, order: envelope.order ?? null, created: envelope.created, suite: envelope.suite };
+  } finally {
+    sk.fill(0);
+    ss?.fill(0);
+  }
+}
