+// Homepage widget: seal a delivery note in the browser before it leaves the device.
+import {
+  SUITES, DEFAULT_SUITE, MAX_NOTE_CHARS, importPublicBundle, sealNote, formatFingerprint,
+} from './delivery-notes-crypto.js';
+
+const PUBLIC_KEY_URL = new URL('../keys/delivery-notes.pub.json', import.meta.url);
+const STORAGE_KEY = 'dailyGrind.sealedDeliveryNote';
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+const noteEl = $('dn-note');
+const orderEl = $('dn-order');
+const suiteEl = $('dn-suite');
+const submitEl = $('dn-submit');
+const statusEl = $('dn-status');
+const countEl = $('dn-count');
+const fpEl = $('dn-fingerprint');
+const resultEl = $('dn-result');
+const envelopeEl = $('dn-envelope');
+const summaryEl = $('dn-summary');
+const copyEl = $('dn-copy');
+const clearEl = $('dn-clear');
+
+let recipients = null;
+
+function setStatus(msg, kind = 'info') {
+  statusEl.textContent = msg;
+  statusEl.dataset.kind = kind;
+}
+
+function updateCount() {
+  const n = [...noteEl.value].length;
+  countEl.textContent = `${n} / ${MAX_NOTE_CHARS}`;
+  countEl.dataset.over = String(n > MAX_NOTE_CHARS);
+}
+
+function updateFingerprint() {
+  const r = recipients?.[suiteEl.value];
+  fpEl.textContent = r ? formatFingerprint(r.kid) : '—';
+  const suite = SUITES[suiteEl.value];
+  $('dn-suite-warning').hidden = !suite || suite.quantumSafe;
+}
+
+function showEnvelope(env) {
+  envelopeEl.textContent = JSON.stringify(env, null, 2);
+  const kb = (JSON.stringify(env).length / 1024).toFixed(1);
+  summaryEl.textContent =
+    `Sealed with ${SUITES[env.suite].label}${env.order ? ` for order ${env.order}` : ''} ` +
+    `at ${new Date(env.created).toLocaleString()} · ${kb} KB. ` +
+    'Only The Daily Grind delivery team can open it.';
+  resultEl.hidden = false;
+}
+
+async function loadKeys() {
+  try {
+    const res = await fetch(PUBLIC_KEY_URL, { cache: 'no-cache', credentials: 'omit' });
+    if (!res.ok) throw new Error(`HTTP ${res.status}`);
+    recipients = await importPublicBundle(await res.json());
+  } catch (e) {
+    setStatus(`Secure notes are unavailable right now (could not load store key: ${e.message}).`, 'error');
+    return;
+  }
+  for (const opt of suiteEl.options) opt.disabled = !recipients[opt.value];
+  if (!recipients[suiteEl.value]) {
+    suiteEl.value = recipients[DEFAULT_SUITE] ? DEFAULT_SUITE : Object.keys(recipients)[0];
+  }
+  updateFingerprint();
+  submitEl.disabled = false;
+  setStatus('Ready. Your note is encrypted on this device before it is saved.', 'info');
+}
+
+function init() {
+  if (!form) return;
+  if (!globalThis.isSecureContext || !globalThis.crypto?.subtle) {
+    setStatus('Secure notes need a secure (https://) connection.', 'error');
+    return;
+  }
+
+  // Populate protection options from the crypto module so labels stay in sync.
+  suiteEl.replaceChildren(
+    ...Object.entries(SUITES).map(([name, s]) => {
+      const o = document.createElement('option');
+      o.value = name;
+      o.textContent = name === DEFAULT_SUITE ? `${s.label} — recommended` : s.label;
+      return o;
+    })
+  );
+  suiteEl.value = DEFAULT_SUITE;
+  noteEl.maxLength = MAX_NOTE_CHARS * 2; // hard cap; exact code-point limit enforced in sealNote
+  updateCount();
+
+  noteEl.addEventListener('input', updateCount);
+  suiteEl.addEventListener('change', updateFingerprint);
+
+  form.addEventListener('submit', async (ev) => {
+    ev.preventDefault();
+    if (!recipients) return;
+    const suite = suiteEl.value;
+    submitEl.disabled = true;
+    setStatus('Encrypting…', 'info');
+    try {
+      const env = await sealNote(noteEl.value, recipients[suite], {
+        suite,
+        order: orderEl.value.trim() || undefined,
+      });
+      // Plaintext is no longer needed — clear it from the form.
+      noteEl.value = '';
+      updateCount();
+      try {
+        sessionStorage.setItem(STORAGE_KEY, JSON.stringify(env));
+      } catch {
+        /* storage disabled — the customer can still copy the sealed note */
+      }
+      showEnvelope(env);
+      setStatus('Note sealed and attached to your next checkout.', 'success');
+    } catch (e) {
+      setStatus(e.message, 'error');
+    } finally {
+      submitEl.disabled = false;
+    }
+  });
+
+  copyEl.addEventListener('click', async () => {
+    try {
+      await navigator.clipboard.writeText(envelopeEl.textContent);
+      setStatus('Sealed note copied to clipboard.', 'success');
+    } catch {
+      setStatus('Copy failed — select the text and copy it manually.', 'error');
+    }
+  });
+
+  clearEl.addEventListener('click', () => {
+    try {
+      sessionStorage.removeItem(STORAGE_KEY);
+    } catch {
+      /* ignore */
+    }
+    envelopeEl.textContent = '';
+    resultEl.hidden = true;
+    setStatus('Sealed note removed.', 'info');
+  });
+
+  // Restore a note sealed earlier in this tab session.
+  try {
+    const saved = sessionStorage.getItem(STORAGE_KEY);
+    if (saved) {
+      const env = JSON.parse(saved);
+      if (env && Object.hasOwn(SUITES, env.suite)) showEnvelope(env);
+    }
+  } catch {
+    /* ignore corrupt storage */
+  }
+
+  loadKeys();
+}
+
+init();
