@@ -0,0 +1,31 @@
+#!/usr/bin/env node
+// Generate the store's delivery-note key set.
+//   public  -> keys/delivery-notes.pub.json   (served to browsers; commit this)
+//   private -> keys/private/delivery-notes.key.json (NEVER commit / deploy; mode 0600)
+//
+// Usage: npm run keys:generate [-- --force]
+import fs from 'node:fs';
+import { generateKeyBundle, formatFingerprint } from '../js/delivery-notes-crypto.js';
+
+const root = new URL('../keys/', import.meta.url);
+const pubPath = new URL('delivery-notes.pub.json', root);
+const privDir = new URL('private/', root);
+const privPath = new URL('delivery-notes.key.json', privDir);
+
+if (fs.existsSync(privPath) && !process.argv.includes('--force')) {
+  console.error(`Refusing to overwrite ${privPath.pathname}. Re-run with --force to rotate keys.`);
+  process.exit(1);
+}
+
+const { publicBundle, privateBundle } = await generateKeyBundle();
+publicBundle.issuer = 'The Daily Grind Coffee Co.';
+fs.mkdirSync(root, { recursive: true });
+fs.mkdirSync(privDir, { recursive: true, mode: 0o700 });
+fs.writeFileSync(privPath, JSON.stringify(privateBundle, null, 2) + '\n', { mode: 0o600 });
+fs.writeFileSync(pubPath, JSON.stringify(publicBundle, null, 2) + '\n');
+
+console.log(`Public bundle : ${pubPath.pathname}`);
+console.log(`Private bundle: ${privPath.pathname} (keep offline / in a secrets manager)`);
+for (const [name, kid] of Object.entries(publicBundle.kids)) {
+  console.log(`  ${name.padEnd(11)} fingerprint ${formatFingerprint(kid)}`);
+}
