+#!/usr/bin/env node
+// Decrypt a sealed delivery note (staff side).
+//
+// Usage: npm run note:open -- <envelope.json | -> [--key keys/private/delivery-notes.key.json]
+// The envelope may be a single object or an array of envelopes.
+import fs from 'node:fs';
+import { openNote } from '../js/delivery-notes-crypto.js';
+
+const args = process.argv.slice(2);
+const ki = args.indexOf('--key');
+const keyPath = ki >= 0 ? args.splice(ki, 2)[1] : new URL('../keys/private/delivery-notes.key.json', import.meta.url);
+const input = args[0];
+if (!input) {
+  console.error('Usage: open-note.mjs <envelope.json | -> [--key <private-bundle.json>]');
+  process.exit(2);
+}
+
+const privateBundle = JSON.parse(fs.readFileSync(keyPath, 'utf8'));
+const raw = fs.readFileSync(input === '-' ? 0 : input, 'utf8');
+const envelopes = [].concat(JSON.parse(raw));
+
+let failed = 0;
+for (const env of envelopes) {
+  try {
+    const { note, order, created, suite } = await openNote(env, privateBundle);
+    console.log(`--- order ${order ?? '(none)'} | ${created} | ${suite}`);
+    console.log(note);
+  } catch (e) {
+    failed++;
+    console.error(`--- FAILED (${env?.order ?? 'unknown order'}): ${e.message}`);
+  }
+}
+process.exit(failed ? 1 : 0);
