@@ -0,0 +1,62 @@
+#!/usr/bin/env node
+// Round-trip and tamper tests for js/delivery-notes-crypto.js. Run: npm test
+import assert from 'node:assert/strict';
+import {
+  SUITES, generateKeyBundle, importPublicBundle, sealNote, openNote, fromB64u, toB64u, MAX_NOTE_CHARS,
+} from '../js/delivery-notes-crypto.js';
+
+const { publicBundle, privateBundle } = await generateKeyBundle();
+const recipients = await importPublicBundle(JSON.parse(JSON.stringify(publicBundle)));
+const other = await generateKeyBundle();
+const note = 'Gate code 4471 ☕ — leave with concierge, nut allergy!';
+let n = 0;
+const ok = (msg) => { n++; console.log(`ok ${n} - ${msg}`); };
+
+for (const suite of Object.keys(SUITES)) {
+  const env = await sealNote(note, recipients[suite], { suite, order: 'DG-1042' });
+  assert.equal(env.suite, suite);
+  assert.ok(!JSON.stringify(env).includes('4471'));
+  const out = await openNote(JSON.parse(JSON.stringify(env)), privateBundle);
+  assert.equal(out.note, note);
+  assert.equal(out.order, 'DG-1042');
+  ok(`${suite}: round trip`);
+
+  const env2 = await sealNote(note, recipients[suite], { suite, order: 'DG-1042' });
+  assert.notEqual(env2.enc, env.enc);
+  assert.notEqual(env2.ct, env.ct);
+  ok(`${suite}: randomized`);
+
+  await assert.rejects(openNote({ ...env, order: 'DG-9999' }, privateBundle), /tampered/);
+  ok(`${suite}: header (AAD) tamper detected`);
+
+  const ct = fromB64u(env.ct); ct[5] ^= 1;
+  await assert.rejects(openNote({ ...env, ct: toB64u(ct) }, privateBundle), /tampered/);
+  ok(`${suite}: ciphertext tamper detected`);
+
+  const enc = fromB64u(env.enc); enc[enc.length - 1] ^= 1;
+  await assert.rejects(openNote({ ...env, enc: toB64u(enc) }, privateBundle));
+  ok(`${suite}: encapsulation tamper detected`);
+
+  await assert.rejects(openNote(env, other.privateBundle), /kid mismatch/);
+  const forged = { ...other.privateBundle, keys: { ...other.privateBundle.keys, [suite]: { ...other.privateBundle.keys[suite], kid: env.kid } } };
+  await assert.rejects(openNote(env, forged), /tampered|invalid/i);
+  ok(`${suite}: wrong private key rejected`);
+}
+
+const short = await sealNote('hi', recipients['X-Wing']);
+const long = await sealNote('x'.repeat(100), recipients['X-Wing']);
+assert.equal(short.ct.length, long.ct.length);
+ok('length padding hides short-note length');
+
+await assert.rejects(sealNote('x'.repeat(MAX_NOTE_CHARS + 1), recipients['X-Wing']), /exceeds/);
+await assert.rejects(sealNote('   ', recipients['X-Wing']), /empty/);
+await assert.rejects(sealNote('hi', recipients['X-Wing'], { order: '<script>' }), /order/);
+await assert.rejects(sealNote('hi', recipients['X-Wing'], { suite: 'ML-KEM-768' }), /mismatch/);
+await assert.rejects(sealNote('hi', recipients['X-Wing'], { suite: '__proto__' }), /Unsupported/);
+ok('input validation');
+
+const bad = JSON.parse(JSON.stringify(publicBundle)); bad.keys['X-Wing'] = bad.keys['X-Wing'].slice(0, -4);
+await assert.rejects(importPublicBundle(bad), /length/);
+ok('malformed public key rejected');
+
+console.log(`\nAll ${n} tests passed.`);
