+++ b/tools/vendor-loader.mjs
@@ -0,0 +1,14 @@
+// Node.js module hook that resolves `@noble/*` bare specifiers to the
+// vendored copies in /vendor/noble — the same mapping the browser gets from
+// the <script type="importmap"> in index.html. This lets the tools in this
+// folder share js/delivery-notes-crypto.js with the homepage, with no
+// node_modules and no build step.
+//
+// Usage: node --import ./tools/register-vendor.mjs tools/<script>.mjs
+const VENDOR = new URL('../vendor/noble/', import.meta.url);
+
+export async function resolve(specifier, context, next) {
+  const m = /^@noble\/(post-quantum|curves|hashes)\/(.+)$/.exec(specifier);
+  if (m) return { url: new URL(`${m[1]}/${m[2]}`, VENDOR).href, shortCircuit: true, format: 'module' };
+  return next(specifier, context);
+}
