--- /dev/null
+++ b/js/theme.js
@@ -0,0 +1,42 @@
+// Applies the saved (or system) theme before first paint. Loaded with
+// `async blocking="render"`, so the page — and any incoming view transition —
+// is not rendered until the correct theme is set on <html>.
+(() => {
+  const KEY = 'daily-grind-theme';
+  const root = document.documentElement;
+
+  let stored = null;
+  try {
+    stored = localStorage.getItem(KEY);
+  } catch {
+    /* storage unavailable */
+  }
+  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
+  const initial = stored === 'dark' || stored === 'light' ? stored : prefersDark ? 'dark' : 'light';
+  root.dataset.theme = initial;
+
+  const wireToggle = () => {
+    const btn = document.querySelector('.theme-toggle');
+    if (!btn) return;
+    const sync = () => {
+      const dark = root.dataset.theme === 'dark';
+      btn.setAttribute('aria-pressed', String(dark));
+    };
+    sync();
+    btn.addEventListener('click', () => {
+      root.dataset.theme = root.dataset.theme === 'dark' ? 'light' : 'dark';
+      try {
+        localStorage.setItem(KEY, root.dataset.theme);
+      } catch {
+        /* storage unavailable */
+      }
+      sync();
+    });
+  };
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', wireToggle, { once: true });
+  } else {
+    wireToggle();
+  }
+})();
