--- /dev/null
+++ b/src/scripts/view-transitions.js
@@ -0,0 +1,115 @@
+// Cross-document view transitions for The DevTools Times.
+//
+// This file is inlined (classic, render-blocking script) in <head> so the
+// `pagereveal` listener is registered before the incoming page's first
+// rendering opportunity. The transition itself is opted into in CSS via
+// `@view-transition { navigation: auto; }` and its first frame is held back by
+// `<link rel="expect" blocking="render">` until the main content is parsed.
+//
+// What this script adds on top:
+//   * Direction types ("forward" / "back") so CSS can mirror the slide.
+//   * A shared-element morph between an article's teaser image and the hero
+//     image of the article page (and back again). Names are only assigned
+//     for the duration of a single transition, which keeps them unique even
+//     when the same article appears more than once on a page.
+(() => {
+  if (!("onpagereveal" in window)) return; // No cross-document VT support.
+
+  const SHARED_NAME = "article-image";
+  const ARTICLE_PATH = /\/articles\/([^/?#]+)\/?$/;
+
+  const articleSlug = (url) => {
+    if (!url) return null;
+    try {
+      const { pathname, origin } = new URL(url, location.href);
+      if (origin !== location.origin) return null;
+      const match = pathname.match(ARTICLE_PATH);
+      return match ? decodeURIComponent(match[1]) : null;
+    } catch {
+      return null;
+    }
+  };
+
+  const isInViewport = (el) => {
+    const rect = el.getBoundingClientRect();
+    return (
+      rect.width > 0 &&
+      rect.height > 0 &&
+      rect.bottom > 0 &&
+      rect.top < window.innerHeight
+    );
+  };
+
+  const findImage = (slug, preferredRoot) => {
+    if (!slug) return null;
+    const selector = `[data-vt-article="${CSS.escape(slug)}"]`;
+    const preferred = preferredRoot && preferredRoot.querySelector(selector);
+    if (preferred && isInViewport(preferred)) return preferred;
+    return [...document.querySelectorAll(selector)].find(isInViewport) || null;
+  };
+
+  const nameFor = (el, transition) => {
+    if (!el) return;
+    el.style.viewTransitionName = SHARED_NAME;
+    // Remove the name again so it can't collide with a later transition
+    // (e.g. when this page is restored from the back/forward cache).
+    transition.finished.finally(() => {
+      el.style.viewTransitionName = "";
+    });
+  };
+
+  const directionOf = (activation) => {
+    if (!activation) return "forward";
+    if (activation.navigationType === "traverse" && activation.from) {
+      return activation.entry.index < activation.from.index ? "back" : "forward";
+    }
+    return "forward";
+  };
+
+  // Remember the link that started the navigation so the morph uses the
+  // exact teaser the reader clicked.
+  let lastClickedLink = null;
+  document.addEventListener(
+    "click",
+    (event) => {
+      const link = event.target instanceof Element && event.target.closest("a[href]");
+      lastClickedLink = link || null;
+    },
+    { capture: true },
+  );
+
+  // Outgoing page: capture the "old" state.
+  window.addEventListener("pageswap", (event) => {
+    const transition = event.viewTransition;
+    if (!transition) return;
+
+    const activation = event.activation;
+    const targetSlug = articleSlug(activation && activation.entry && activation.entry.url);
+    const currentSlug = articleSlug(location.href);
+    // Morph toward the article being opened, or – when leaving an article –
+    // the article we are coming from.
+    const slug = targetSlug || currentSlug;
+
+    const clicked =
+      lastClickedLink && articleSlug(lastClickedLink.href) === targetSlug
+        ? lastClickedLink
+        : null;
+    nameFor(findImage(slug, clicked), transition);
+    lastClickedLink = null;
+  });
+
+  // Incoming page: runs before the first frame is rendered.
+  window.addEventListener("pagereveal", (event) => {
+    const transition = event.viewTransition;
+    if (!transition) return;
+
+    const activation = window.navigation ? window.navigation.activation : null;
+    transition.types.add(directionOf(activation));
+
+    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
+
+    const currentSlug = articleSlug(location.href);
+    const fromSlug = articleSlug(activation && activation.from && activation.from.url);
+    nameFor(findImage(currentSlug || fromSlug), transition);
+  });
+})();
