+}
+/* ------------------------------------------------------------------------
+ * Page transitions (cross-document View Transitions)
+ *
+ * Every same-origin navigation animates natively. The incoming page is held
+ * back by <link rel="expect" blocking="render"> (see Layout.astro) until its
+ * main content is fully parsed, so the animation always lands on a complete
+ * layout. Browsers without support simply navigate as before.
+ * --------------------------------------------------------------------- */
+@view-transition {
+  navigation: auto;
+}
+
+/* The masthead is identical on every page: keep it perfectly still. */
+.vt-site-header {
+  view-transition-name: site-header;
+}
+
+.vt-page-content {
+  view-transition-name: page-content;
+}
+
+/* Never show a blank hole while an image is still decoding. */
+img[data-vt-article] {
+  background-color: var(--color-gray-100);
+}
+
+::view-transition-group(site-header) {
+  animation: none;
+}
+
+::view-transition-old(root),
+::view-transition-new(root) {
+  animation-duration: 200ms;
+}
+
+::view-transition-group(page-content) {
+  animation-duration: 320ms;
+  animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
+}
+
+::view-transition-old(page-content) {
+  animation: 160ms cubic-bezier(0.4, 0, 1, 1) both vt-fade-out,
+    320ms cubic-bezier(0.2, 0, 0, 1) both vt-slide-to-left;
+}
+
+::view-transition-new(page-content) {
+  animation: 220ms cubic-bezier(0, 0, 0.2, 1) 80ms both vt-fade-in,
+    320ms cubic-bezier(0.2, 0, 0, 1) both vt-slide-from-right;
+}
+
+/* Back navigation mirrors the slide direction. */
+html:active-view-transition-type(back)::view-transition-old(page-content) {
+  animation-name: vt-fade-out, vt-slide-to-right;
+}
+
+html:active-view-transition-type(back)::view-transition-new(page-content) {
+  animation-name: vt-fade-in, vt-slide-from-left;
+}
+
+/* Teaser image <-> article hero image morph. */
+::view-transition-group(article-image) {
+  animation-duration: 380ms;
+  animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
+}
+
+::view-transition-old(article-image),
+::view-transition-new(article-image) {
+  height: 100%;
+  object-fit: cover;
+  overflow: clip;
+}
+
+@keyframes vt-fade-in {
+  from { opacity: 0; }
+}
+
+@keyframes vt-fade-out {
+  to { opacity: 0; }
+}
+
+@keyframes vt-slide-from-right {
+  from { transform: translateX(24px); }
+}
+
+@keyframes vt-slide-to-left {
+  to { transform: translateX(-24px); }
+}
+
+@keyframes vt-slide-from-left {
+  from { transform: translateX(-24px); }
+}
+
+@keyframes vt-slide-to-right {
+  to { transform: translateX(24px); }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation: none !important;
+  }
+}

