+    const progress = document.getElementById('render-progress');
+    const sppLabel = document.getElementById('render-spp');
+    const statusEl = document.getElementById('render-status');
+    const swatches = document.getElementById('swatches');
+
+    // smallpt's scene, in order: left, right, back, front, floor, ceiling walls,
+    // mirror sphere, glass sphere, light. These are the original colors.
+    const DEFAULT_COLORS = [
+      [.75, .25, .25], [.25, .25, .75], [.75, .75, .75], [0, 0, 0],
+      [.75, .75, .75], [.75, .75, .75], [.999, .999, .999], [.999, .999, .999], [0, 0, 0],
+    ];
+    const SWATCH_NAMES = ['Left wall', 'Right wall', 'Back wall', null, 'Floor', 'Ceiling', 'Mirror sphere', 'Glass sphere'];
+
+    // Random color with every channel in [min, max]; values stay below 1 so
+    // surfaces never reflect more light than they receive.
+    const randomColor = (min, max) =>
+      Array.from({ length: 3 }, () => +(min + Math.random() * (max - min)).toFixed(3));
+
+    function randomColors() {
+      return DEFAULT_COLORS.map((c, i) => {
+        if (i <= 5 && i !== 3) return randomColor(0.05, 0.9); // walls
+        if (i === 6 || i === 7) return randomColor(0.45, 0.999); // mirror & glass tints
+        return c; // unseen front wall and the light keep their values
+      });
+    }
+
+    const toCss = ([r, g, b]) =>
+      `rgb(${[r, g, b].map((v) => Math.round(Math.pow(v, 1 / 2.2) * 255)).join(' ')})`;
+
+    function showSwatches(colors) {
+      swatches.replaceChildren(...SWATCH_NAMES.flatMap((name, i) => {
+        if (!name) return [];
+        const li = document.createElement('li');
+        li.style.background = toCss(colors[i]);
+        li.title = name;
+        li.setAttribute('aria-label', name);
+        return li;
+      }));
+    }
+
+    const workerCount = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 8));
+    const bands = Array.from({ length: workerCount }, (_, i) => {
+      const row0 = Math.floor((i * HEIGHT) / workerCount);
+      return { row0, rows: Math.floor(((i + 1) * HEIGHT) / workerCount) - row0, passes: 0 };
+    });
+    const workers = bands.map(() =>
+      new Worker(new URL('./js/smallpt-worker.js', import.meta.url), { type: 'module' }));
+
+    let gen = 0;
+    let startTime = 0;
+
+    workers.forEach((worker, i) => {
+      worker.onmessage = ({ data }) => {
+        if (data.gen !== gen) return; // stale result from a previous render
+        ctx.putImageData(new ImageData(new Uint8ClampedArray(data.pixels.buffer), WIDTH, data.rows), 0, data.row0);
+        bands[i].passes = data.passes;
+        const done = Math.min(...bands.map((b) => b.passes));
+        progress.value = done / MAX_PASSES;
+        sppLabel.textContent = `${done * 4} spp`;
+        if (done === MAX_PASSES) {
+          const secs = ((performance.now() - startTime) / 1000).toFixed(1);
+          statusEl.textContent = `Done: ${MAX_PASSES * 4} samples per pixel in ${secs}s on ${workerCount} threads.`;
+        }
+      };
+      worker.onerror = (e) => {
+        statusEl.textContent = `The path tracer failed to load (${e.message || 'worker error'}).`;
+      };
+    });
+
+    function render(colors) {
+      gen++;
+      startTime = performance.now();
+      bands.forEach((b) => (b.passes = 0));
+      progress.value = 0;
+      sppLabel.textContent = '0 spp';
+      statusEl.textContent = `Rendering ${WIDTH}\u00d7${HEIGHT} with ${workerCount} WebAssembly threads\u2026`;
+      showSwatches(colors);
+      workers.forEach((worker, i) => worker.postMessage({
+        type: 'start', gen, width: WIDTH, height: HEIGHT,
+        row0: bands[i].row0, rows: bands[i].rows, colors, maxPasses: MAX_PASSES,
+      }));
+    }
+
+    button.addEventListener('click', () => render(randomColors()));
+    render(DEFAULT_COLORS);
+  </script>
+
 </body>

 </html>
diff --git a/js/smallpt-worker.js b/js/smallpt-worker.js
new file mode 100644
index 0000000..5fa2693
--- /dev/null
+++ b/js/smallpt-worker.js
@@ -0,0 +1,35 @@
+// Renders one horizontal band of the smallpt image, one 4-spp pass at a time,
+// posting the refined band back after every pass.
+import initSmallpt from '../wasm/smallpt.js';
+
+// Register onmessage synchronously so no message is lost while wasm loads.
+const wasmReady = initSmallpt();
+let wasm = null;
+let job = null;     // current { gen, row0, rows, maxPasses, ptr }
+let running = false;
+
+self.onmessage = async ({ data }) => {
+  if (data.type !== 'start') return;
+  wasm ??= await wasmReady;
+  const { gen, width, height, row0, rows, colors, maxPasses } = data;
+  const ptr = wasm._init(width, height, row0, rows);
+  colors.forEach(([r, g, b], i) => wasm._set_color(i, r, g, b));
+  wasm._reset();
+  job = { gen, width, row0, rows, maxPasses, ptr };
+  if (!running) loop();
+};
+
+async function loop() {
+  running = true;
+  while (job) {
+    const { gen, width, row0, rows, maxPasses, ptr } = job;
+    const passes = wasm._render_pass();
+    // Read HEAPU8 fresh: memory growth would detach an old view.
+    const pixels = wasm.HEAPU8.slice(ptr, ptr + width * rows * 4);
+    self.postMessage({ gen, row0, rows, passes, pixels }, [pixels.buffer]);
+    if (passes >= maxPasses && job.gen === gen) job = null;
+    // Yield so a new 'start' message can replace the job between passes.
+    await new Promise((resolve) => setTimeout(resolve, 0));
+  }
+  running = false;
+}
