+#!/usr/bin/env bash
+# Builds smallpt.cpp into an ES module + .wasm in ../wasm/
+set -euo pipefail
+cd "$(dirname "$0")"
+mkdir -p ../wasm build
+em++ -c smallpt.cpp -o build/smallpt.o -O3 -flto -Wall -Werror
+# Link with emcc: the code needs no C++ runtime (avoids pulling in libc++abi)
+emcc build/smallpt.o -o ../wasm/smallpt.js \
+  -O3 -flto \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_init,_num_spheres,_set_color,_reset,_render_pass \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
