+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// ---- WebAssembly interface -------------------------------------------------
+static int W, H, ROW0, ROWS, PASSES;  // image size, band [ROW0, ROW0+ROWS)
+static Vec *accum;                    // summed radiance per 2x2 subpixel
+static uint8_t *rgba;                 // display buffer for the band
+
+extern "C" {
+
+// Allocate buffers for output rows [row0, row0+rows) of a w*h image.
+// Output row 0 is the top of the image. Returns the RGBA buffer pointer.
+EMSCRIPTEN_KEEPALIVE uint8_t *init(int w, int h, int row0, int rows){
+  free(accum); free(rgba);
+  W=w; H=h; ROW0=row0; ROWS=rows; PASSES=0;
+  accum = (Vec *)calloc(w*rows*4, sizeof(Vec));  // all-zero bits == Vec()
+  rgba = (uint8_t *)malloc(w*rows*4);
+  return rgba;
+}
+
+EMSCRIPTEN_KEEPALIVE int num_spheres(){ return NUM_SPHERES; }
+
+EMSCRIPTEN_KEEPALIVE void set_color(int i, double r, double g, double b){
+  if (i>=0 && i<NUM_SPHERES) spheres[i].c = Vec(r,g,b);
+}
+
+// Clear accumulated samples (call after changing the scene).
+EMSCRIPTEN_KEEPALIVE void reset(){
+  PASSES=0;
+  for (int i=0; i<W*ROWS*4; i++) accum[i]=Vec();
+}
+
+// Add one pass (2x2 subpixels x 1 sample = 4 spp) to the band, then refresh
+// the RGBA buffer with the running average. Returns total passes so far.
+EMSCRIPTEN_KEEPALIVE int render_pass(){
+  int w=W, h=H;
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+  for (int row=ROW0; row<ROW0+ROWS; row++){
+    int y=h-row-1;                                 // smallpt's y is bottom-up
+    for (unsigned short x=0, Xi[3]={(unsigned short)PASSES,
+           (unsigned short)(PASSES*7919u), (unsigned short)(y*y*y)}; x<w; x++)
+      for (int sy=0, i=(row-ROW0)*w+x; sy<2; sy++)  // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()){         // 2x2 subpixel cols
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                  cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+          Vec &a = accum[i*4+sy*2+sx];  // unclamped running sum, like the
+          a = a + radiance(Ray(cam.o+d*140,d.norm()),0,Xi); // original's r
+        }
+  }
+  PASSES++;
+  double inv = 1.0/PASSES;
+  for (int i=0; i<W*ROWS; i++){           // clamp each subpixel's mean,
+    Vec c;                                 // then average the 2x2 (as in
+    for (int s=0; s<4; s++){               // the original smallpt)
+      Vec m = accum[i*4+s]*inv;
+      c = c + Vec(clamp(m.x),clamp(m.y),clamp(m.z))*.25;
+    }
+    rgba[i*4+0]=toInt(c.x);
+    rgba[i*4+1]=toInt(c.y);
+    rgba[i*4+2]=toInt(c.z);
+    rgba[i*4+3]=255;
+  }
+  return PASSES;
+}
+
+} // extern "C"
