+// Web Worker that runs the smallpt WebAssembly module off the main thread.
+// Message in:  { width, height, passes, sampsPerPass, colors: [[r,g,b] | null, ...] }
+// Messages out: { type: 'progress', pixels: ArrayBuffer, pass, row, spp }
+//               { type: 'done', spp, ms }
+importScripts('smallpt.js');
+
+const modulePromise = createSmallpt({
+  locateFile: (path) => new URL(path, self.location.href).href,
+});
+
+self.onmessage = async (e) => {
+  const { width: w, height: h, passes, sampsPerPass, colors } = e.data;
+  const M = await modulePromise;
+  colors.forEach((c, i) => { if (c) M._set_sphere_color(i, c[0], c[1], c[2]); });
+  const ptr = M._setup(w, h);
+  const t0 = performance.now();
+  const snapshot = () => M.HEAPU8.slice(ptr, ptr + w * h * 4).buffer;
+  const chunk = 8; // rows per progress update during the first pass
+
+  for (let pass = 0; pass < passes; pass++) {
+    // smallpt's y=0 is the bottom row; render top-down so the image fills in naturally.
+    for (let y1 = h; y1 > 0; y1 -= chunk) {
+      const y0 = Math.max(0, y1 - chunk);
+      M._render_rows(y0, y1, pass, sampsPerPass);
+      if (pass === 0) {
+        const buf = snapshot();
+        self.postMessage({ type: 'progress', pixels: buf, pass, row: h - y0, spp: 4 * sampsPerPass }, [buf]);
+      }
+    }
+    if (pass > 0) {
+      const buf = snapshot();
+      self.postMessage({ type: 'progress', pixels: buf, pass, row: h, spp: 4 * sampsPerPass * (pass + 1) }, [buf]);
+    }
+  }
+  self.postMessage({ type: 'done', spp: 4 * sampsPerPass * passes, ms: performance.now() - t0 });
+};
