@@ -0,0 +1,22 @@
+// Module worker that runs the smallpt WebAssembly build.
+// Receives a render job, renders its assigned rows one at a time and posts
+// each finished RGBA row back (transferring the buffer, no copy).
+import createSmallpt from './smallpt.mjs';
+
+const modulePromise = createSmallpt();
+
+self.onmessage = async ({ data: job }) => {
+  const { width, height, samps, seed, colors, rows } = job;
+  const wasm = await modulePromise;
+  const ptr = wasm._smallpt_init(width, height);
+  for (const [index, r, g, b] of colors) wasm._smallpt_set_color(index, r, g, b);
+
+  const rowBytes = width * 4;
+  for (const row of rows) {
+    wasm._smallpt_render_row(row, samps, seed);
+    // Read HEAPU8 fresh after each call: memory growth detaches old views.
+    const pixels = wasm.HEAPU8.slice(ptr, ptr + rowBytes);
+    self.postMessage({ type: 'row', row, pixels }, [pixels.buffer]);
+  }
+  self.postMessage({ type: 'done' });
+};
diff --git a/src/components/SmallptRenderer.astro b/src/components/SmallptRenderer.astro
