index 0000000..34b2c10
--- /dev/null
+++ b/src/components/SmallptRenderer.astro
@@ -0,0 +1,166 @@
+---
+// Client-side smallpt (Kevin Beason's 99-line C++ path tracer) compiled to
+// WebAssembly. Source: wasm/smallpt.cpp, built by wasm/build.sh into
+// public/smallpt/. Rendering is split across module Web Workers.
+const WIDTH = 400;
+const HEIGHT = 300;
+const SAMPS = 16; // per 2x2 sub-pixel => 64 samples per pixel
+---
+<section class="p-4 md:p-6" aria-labelledby="smallpt-heading">
+  <h2 id="smallpt-heading" class="text-3xl font-bold border-b-2 border-gray-900 pb-2 mb-6">
+    Rendered in Your Browser
+  </h2>
+  <div class="grid gap-6 md:grid-cols-[minmax(0,1fr)_minmax(0,22rem)] items-start">
+    <figure>
+      <canvas
+        id="smallpt-canvas"
+        width={WIDTH}
+        height={HEIGHT}
+        data-width={WIDTH}
+        data-height={HEIGHT}
+        data-samps={SAMPS}
+        class="w-full h-auto bg-gray-900 [image-rendering:pixelated]"
+        role="img"
+        aria-label="Path-traced Cornell box with a mirror sphere and a glass sphere"
+      ></canvas>
+      <figcaption class="text-xs text-gray-500 mt-2">
+        {WIDTH}×{HEIGHT}, {SAMPS * 4} samples per pixel, traced by
+        <a class="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/">smallpt</a>
+        compiled to WebAssembly.
+      </figcaption>
+    </figure>
+    <div class="space-y-4">
+      <p class="text-gray-700">
+        This image isn't a photo. Your browser computed it just now by running
+        <strong>smallpt</strong>, Kevin Beason's global-illumination path tracer
+        in 99 lines of C++, compiled to WebAssembly. Each pixel averages
+        {SAMPS * 4} random light paths bouncing around a Cornell box.
+      </p>
+      <button
+        id="smallpt-rerun"
+        type="button"
+        class="inline-flex items-center gap-2 bg-gray-900 text-white font-semibold px-4 py-2 hover:bg-amber-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 disabled:opacity-60"
+      >
+        Re-render with random colors
+      </button>
+      <ul id="smallpt-swatches" class="flex flex-wrap gap-3 text-xs text-gray-600" aria-label="Current sphere colors"></ul>
+      <p id="smallpt-status" class="text-sm text-gray-600 tabular-nums" role="status" aria-live="polite">
+        Loading renderer…
+      </p>
+    </div>
+  </div>
+</section>
+
+<script>
+  type RGB = [number, number, number];
+  type ColorEntry = { index: number; label: string; color: RGB };
+  type RowMessage = { type: 'row'; row: number; pixels: Uint8Array } | { type: 'done' };
+
+  const canvas = document.getElementById('smallpt-canvas') as HTMLCanvasElement | null;
+  const button = document.getElementById('smallpt-rerun') as HTMLButtonElement | null;
+  const status = document.getElementById('smallpt-status');
+  const swatches = document.getElementById('smallpt-swatches');
+
+  if (canvas && button && status && swatches) {
+    const width = Number(canvas.dataset.width);
+    const height = Number(canvas.dataset.height);
+    const samps = Number(canvas.dataset.samps);
+    const ctx = canvas.getContext('2d')!;
+    const workerUrl = `${import.meta.env.BASE_URL}smallpt/worker.js`;
+    const workerCount = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 8));
+
+    // Sphere indices in smallpt's scene array, with the original colors.
+    const ORIGINAL: ColorEntry[] = [
+      { index: 0, label: 'Left wall', color: [0.75, 0.25, 0.25] },
+      { index: 1, label: 'Right wall', color: [0.25, 0.25, 0.75] },
+      { index: 6, label: 'Mirror sphere', color: [0.999, 0.999, 0.999] },
+      { index: 7, label: 'Glass sphere', color: [0.999, 0.999, 0.999] },
+    ];
+
+    let workers: Worker[] = [];
+
+    function hslToRgb(h: number, s: number, l: number): RGB {
+      const k = (n: number) => (n + h / 30) % 12;
+      const a = s * Math.min(l, 1 - l);
+      const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+      return [f(0), f(8), f(4)];
+    }
+
+    function randomColors(): ColorEntry[] {
+      return ORIGINAL.map((entry) => {
+        const isWall = entry.index < 6;
+        // Walls are diffuse: keep albedo below 1 so light doesn't blow up.
+        // Mirror/glass tints stay bright so the spheres remain reflective.
+        const rgb = isWall
+          ? hslToRgb(Math.random() * 360, 0.5 + Math.random() * 0.4, 0.35 + Math.random() * 0.25)
+          : hslToRgb(Math.random() * 360, 0.4 + Math.random() * 0.5, 0.6 + Math.random() * 0.2);
+        const scale = isWall ? 0.9 : 0.999;
+        return { ...entry, color: rgb.map((c) => Math.min(c, scale)) as RGB };
+      });
+    }
+
+    function renderSwatches(colors: ColorEntry[]) {
+      swatches!.replaceChildren(
+        ...colors.map(({ label, color }) => {
+          const li = document.createElement('li');
+          li.className = 'flex items-center gap-1.5';
+          const chip = document.createElement('span');
+          chip.className = 'inline-block size-4 border border-gray-400';
+          chip.style.backgroundColor = `rgb(${color.map((c) => Math.round(c * 255)).join(' ')})`;
+          li.append(chip, label);
+          return li;
+        }),
+      );
+    }
+
+    function stop() {
+      for (const w of workers) w.terminate();
+      workers = [];
+    }
+
+    function render(colors: ColorEntry[]) {
+      stop();
+      renderSwatches(colors);
+      ctx.fillStyle = '#111827';
+      ctx.fillRect(0, 0, width, height);
+
+      const seed = (Math.random() * 0x7fffffff) | 0;
+      const colorArgs = colors.map(({ index, color }) => [index, ...color]);
+      const rowImage = new ImageData(width, 1);
+      const start = performance.now();
+      let rowsDone = 0;
+      let workersDone = 0;
+      status!.textContent = `Rendering on ${workerCount} worker${workerCount > 1 ? 's' : ''}… 0%`;
+
+      for (let k = 0; k < workerCount; k++) {
+        const worker = new Worker(workerUrl, { type: 'module' });
+        // Interleave rows so every worker gets a similar mix of easy and hard rows.
+        const rows: number[] = [];
+        for (let y = k; y < height; y += workerCount) rows.push(y);
+
+        worker.onmessage = ({ data }: MessageEvent<RowMessage>) => {
+          if (data.type === 'row') {
+            rowImage.data.set(data.pixels);
+            ctx.putImageData(rowImage, 0, data.row);
+            rowsDone++;
+            status!.textContent = `Rendering on ${workerCount} worker${workerCount > 1 ? 's' : ''}… ${Math.floor((rowsDone / height) * 100)}%`;
+          } else if (++workersDone === workerCount) {
+            const secs = ((performance.now() - start) / 1000).toFixed(1);
+            status!.textContent = `Done in ${secs}s (${samps * 4} spp, ${workerCount} worker${workerCount > 1 ? 's' : ''}).`;
+            stop();
+          }
+        };
+        worker.onerror = (event) => {
+          event.preventDefault();
+          status!.textContent = 'The renderer failed to load. Please try again.';
+          stop();
+        };
+        worker.postMessage({ width, height, samps, seed, colors: colorArgs, rows });
+        workers.push(worker);
+      }
+    }
+
+    button.addEventListener('click', () => render(randomColors()));
+    render(ORIGINAL);
+  }
+</script>
