+#!/bin/sh
+# Compiles smallpt.cpp to an ES module + .wasm in public/smallpt/.
+# The compiled output is committed, so this step is skipped (not failed) when
+# Emscripten isn't installed, e.g. in deployment images.
+set -e
+cd "$(dirname "$0")"
+OUT=../public/smallpt
+if ! command -v em++ >/dev/null 2>&1; then
+  echo "[smallpt] em++ not found; using prebuilt $OUT/smallpt.{mjs,wasm}"
+  exit 0
+fi
+mkdir -p build "$OUT"
+em++ -c smallpt.cpp -o build/smallpt.o -O3 -Wall -Werror
+em++ build/smallpt.o -o "$OUT/smallpt.mjs" \
+  -O3 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_smallpt_init,_smallpt_num_spheres,_smallpt_set_color,_smallpt_render_row,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+echo "[smallpt] built $OUT/smallpt.mjs + smallpt.wasm"
