+// Web Worker that runs the smallpt WebAssembly module.
+// Messages in:  { type: 'render', width, height, spp, colors: [[r,g,b]|null, ...], rows: [rowIndex, ...] }
+// Messages out: { type: 'ready' } | { type: 'row', row, pixels: Uint8ClampedArray } | { type: 'done' }
+importScripts('smallpt.js');
+
+const modulePromise = createSmallpt();
+
+self.onmessage = async (e) => {
+  const msg = e.data;
+  if (msg.type !== 'render') return;
+  const m = await modulePromise;
+  m._init(msg.width, msg.height, msg.spp);
+  msg.colors.forEach((c, i) => {
+    if (c) m._set_sphere_color(i, c[0], c[1], c[2]);
+  });
+  for (const row of msg.rows) {
+    const ptr = m._render_row(row);
+    const pixels = new Uint8ClampedArray(m.HEAPU8.buffer.slice(ptr, ptr + msg.width * 4));
+    self.postMessage({ type: 'row', row, pixels }, [pixels.buffer]);
+  }
+  self.postMessage({ type: 'done' });
+};
