+import { useCallback, useEffect, useRef, useState } from 'react';
+
+const WIDTH = 400;
+const HEIGHT = 300;
+const SPP = 64; // samples per pixel (multiple of 4)
+
+type RGB = [number, number, number];
+
+// Index order matches the `spheres` array in wasm/smallpt.cpp.
+const SPHERE_NAMES = ['Left wall', 'Right wall', 'Back wall', 'Front wall', 'Floor', 'Ceiling', 'Mirror ball', 'Glass ball', 'Light'];
+const DEFAULT_COLORS: (RGB | null)[] = [
+  [0.75, 0.25, 0.25],
+  [0.25, 0.25, 0.75],
+  [0.75, 0.75, 0.75],
+  [0, 0, 0],
+  [0.75, 0.75, 0.75],
+  [0.75, 0.75, 0.75],
+  [0.999, 0.999, 0.999],
+  [0.999, 0.999, 0.999],
+  [0, 0, 0],
+];
+
+function hslToRgb(h: number, s: number, l: number): RGB {
+  const k = (n: number) => (n + h * 12) % 12;
+  const a = s * Math.min(l, 1 - l);
+  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
+  return [f(0), f(8), f(4)];
+}
+
+function randomColors(): (RGB | null)[] {
+  const scale = (c: RGB, max: number): RGB => c.map((v) => v * max) as RGB;
+  const wall = () => scale(hslToRgb(Math.random(), 0.4 + Math.random() * 0.5, 0.35 + Math.random() * 0.3), 0.85);
+  const tint = () => scale(hslToRgb(Math.random(), 0.3 + Math.random() * 0.5, 0.6 + Math.random() * 0.25), 0.999);
+  return [
+    wall(), // left
+    wall(), // right
+    wall(), // back
+    null, // front wall (behind the camera) stays black
+    wall(), // floor
+    wall(), // ceiling
+    tint(), // mirror ball
+    tint(), // glass ball
+    null, // light keeps its emission
+  ];
+}
+
+const toCss = (c: RGB) => `rgb(${c.map((v) => Math.round(Math.pow(v, 1 / 2.2) * 255)).join(',')})`;
+
+function workerUrl() {
+  const base = import.meta.env.BASE_URL.replace(/\/?$/, '/');
+  return `${base.startsWith('/') ? '' : '/'}${base}smallpt/worker.js`;
+}
+
+export default function SmallptRenderer() {
+  const canvasRef = useRef<HTMLCanvasElement>(null);
+  const workersRef = useRef<Worker[]>([]);
+  const [colors, setColors] = useState<(RGB | null)[]>(DEFAULT_COLORS);
+  const [progress, setProgress] = useState(0);
+  const [elapsed, setElapsed] = useState<number | null>(null);
+  const [error, setError] = useState<string | null>(null);
+
+  const stop = () => {
+    workersRef.current.forEach((w) => w.terminate());
+    workersRef.current = [];
+  };
+
+  const render = useCallback((cols: (RGB | null)[]) => {
+    stop();
+    setColors(cols);
+    setProgress(0);
+    setElapsed(null);
+    setError(null);
+    const ctx = canvasRef.current?.getContext('2d');
+    if (!ctx) return;
+    ctx.fillStyle = '#111';
+    ctx.fillRect(0, 0, WIDTH, HEIGHT);
+
+    const n = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 8));
+    const start = performance.now();
+    let rowsDone = 0;
+    let workersDone = 0;
+    const workers: Worker[] = [];
+    for (let i = 0; i < n; i++) {
+      const w = new Worker(workerUrl());
+      const rows: number[] = [];
+      for (let r = i; r < HEIGHT; r += n) rows.push(r); // interleave rows across workers
+      w.onmessage = (e) => {
+        const msg = e.data;
+        if (msg.type === 'row') {
+          ctx.putImageData(new ImageData(msg.pixels, WIDTH, 1), 0, msg.row);
+          rowsDone++;
+          setProgress(rowsDone / HEIGHT);
+        } else if (msg.type === 'done') {
+          w.terminate();
+          if (++workersDone === n) setElapsed(performance.now() - start);
+        }
+      };
+      w.onerror = (e) => {
+        setError(e.message || 'Failed to run the WebAssembly path tracer.');
+        stop();
+      };
+      w.postMessage({ type: 'render', width: WIDTH, height: HEIGHT, spp: SPP, colors: cols, rows });
+      workers.push(w);
+    }
+    workersRef.current = workers;
+  }, []);
+
+  useEffect(() => {
+    render(DEFAULT_COLORS);
+    return stop;
+  }, [render]);
+
+  const running = elapsed === null && !error;
+
+  return (
+    <div className="flex flex-col md:flex-row gap-6 items-start">
+      <div className="w-full md:w-auto">
+        <canvas
+          ref={canvasRef}
+          width={WIDTH}
+          height={HEIGHT}
+          className="w-full md:w-[400px] h-auto bg-gray-900 border border-gray-300"
+          style={{ imageRendering: 'auto' }}
+          aria-label="Image rendered by the smallpt path tracer"
+        />
+        <div className="h-1 bg-gray-200 mt-1">
+          <div className="h-1 bg-amber-400 transition-[width]" style={{ width: `${progress * 100}%` }} />
+        </div>
+      </div>
+      <div className="flex-1 text-left">
+        <p className="text-sm text-gray-700 mb-3">
+          This Cornell box is rendered live in your browser by{' '}
+          <a className="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/" target="_blank" rel="noreferrer">
+            smallpt
+          </a>
+          , Kevin Beason's 99-line C++ path tracer, compiled to WebAssembly and run across {' '}
+          {typeof navigator !== 'undefined' ? Math.min(navigator.hardwareConcurrency || 4, 8) : 'several'} Web Workers at{' '}
+          {WIDTH}×{HEIGHT}, {SPP} samples per pixel.
+        </p>
+        <p className="text-xs text-gray-500 mb-3" aria-live="polite">
+          {error
+            ? `Error: ${error}`
+            : running
+              ? `Rendering… ${Math.round(progress * 100)}%`
+              : `Rendered in ${(elapsed! / 1000).toFixed(2)} s`}
+        </p>
+        <div className="flex flex-wrap gap-2 mb-4">
+          {colors.map((c, i) =>
+            c && i !== 3 && i !== 8 ? (
+              <span key={i} className="flex items-center gap-1 text-xs text-gray-600">
+                <span className="inline-block w-4 h-4 border border-gray-300" style={{ background: toCss(c) }} />
+                {SPHERE_NAMES[i]}
+              </span>
+            ) : null,
+          )}
+        </div>
+        <div className="flex gap-2">
+          <button
+            type="button"
+            onClick={() => render(randomColors())}
+            className="px-4 py-2 bg-gray-900 text-white text-sm font-semibold hover:bg-amber-400 hover:text-gray-900 transition-colors"
+          >
+            Render again with random colors
+          </button>
+          <button
+            type="button"
+            onClick={() => render(DEFAULT_COLORS)}
+            className="px-4 py-2 border border-gray-300 text-sm hover:border-gray-900"
+          >
+            Reset
+          </button>
+        </div>
+      </div>
+    </div>
+  );
+}
