+#!/usr/bin/env bash
+# Compiles smallpt to WebAssembly. Requires Emscripten (em++) on PATH.
+set -euo pipefail
+cd "$(dirname "$0")"
+em++ smallpt.cpp -O3 -fno-exceptions \
+  -sMODULARIZE=1 -sEXPORT_NAME=createSmallpt \
+  -sENVIRONMENT=worker -sALLOW_MEMORY_GROWTH=1 -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_init,_render_row,_set_sphere_color,_num_spheres \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8 \
+  -o ../public/smallpt/smallpt.js
+echo "Built public/smallpt/smallpt.js + smallpt.wasm"
