+/**
+ * <coffee-card> — an autonomous custom element for a menu item.
+ *
+ * Attributes (reflected to same-named camelCase properties):
+ *   name       string   Drink name, rendered as the card heading.
+ *   href       string   Link target for the "View Details" button.
+ *   image      string   Optional photo URL.
+ *   image-alt  string   Alt text for the photo (empty = decorative).
+ *   price      number   Price in USD; omitted/invalid hides the price.
+ *   rating     number   0–5 star rating; clamped on read.
+ *   featured   boolean  Shows a "Seasonal pick" badge.
+ *   sold-out   boolean  Shows a "Sold out" badge and dims the card.
+ *   favorite   boolean  Toggled by the heart button; fires `favorite-change`.
+ *
+ * The description is supplied as light-DOM children (default slot).
+ */
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      display: flex;
+      flex-direction: column;
+      background: white;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+      overflow: hidden;
+      position: relative;
+      transition: box-shadow 0.2s, transform 0.2s;
+    }
+    :host([hidden]) { display: none; }
+    :host(:hover) { box-shadow: 0 6px 16px rgba(0, 0, 0, 0.15); transform: translateY(-2px); }
+    :host([sold-out]) { opacity: 0.7; }
+    :host([sold-out]) img { filter: grayscale(1); }
+
+    figure { margin: 0; aspect-ratio: 3 / 2; background: var(--secondary, #d7ccc8); }
+    figure[hidden] { display: none; }
+    img { width: 100%; height: 100%; object-fit: cover; display: block; }
+
+    .body { padding: 20px; display: flex; flex-direction: column; flex: 1; }
+    h3 { margin: 0 0 10px; color: var(--primary, #4e342e); }
+    .meta { display: flex; justify-content: center; gap: 12px; margin-bottom: 8px; font-size: 0.9rem; }
+    .price { font-weight: 600; }
+    .rating { color: var(--accent, #ffab40); letter-spacing: 1px; }
+    [hidden] { display: none !important; }
+    ::slotted(*) { margin: 0; }
+    .description { flex: 1; }
+
+    .badges { position: absolute; top: 10px; left: 10px; display: flex; gap: 6px; }
+    .badge {
+      background: var(--accent, #ffab40);
+      color: var(--text, #3e2723);
+      font-size: 0.75rem;
+      font-weight: 600;
+      padding: 2px 8px;
+      border-radius: 999px;
+    }
+    .badge.sold-out { background: var(--text, #3e2723); color: white; }
+
+    .favorite {
+      position: absolute;
+      top: 8px;
+      right: 8px;
+      inline-size: 36px;
+      block-size: 36px;
+      border-radius: 50%;
+      border: none;
+      background: rgba(255, 255, 255, 0.9);
+      color: var(--primary, #4e342e);
+      font-size: 1.2rem;
+      line-height: 1;
+      cursor: pointer;
+    }
+    .favorite[aria-pressed="true"] { color: #c62828; }
+    .favorite:focus-visible { outline: 3px solid var(--accent, #ffab40); outline-offset: 2px; }
+
+    .btn {
+      display: inline-block;
+      align-self: center;
+      background: var(--primary, #4e342e);
+      color: white;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+    .btn:hover { background: #3e2723; }
+    .btn:focus-visible { outline: 3px solid var(--accent, #ffab40); outline-offset: 2px; }
+  </style>
+  <figure part="media" hidden><img part="image" alt="" loading="lazy" decoding="async"></figure>
+  <div class="badges">
+    <span class="badge featured" part="badge" hidden>Seasonal pick</span>
+    <span class="badge sold-out" part="badge" hidden>Sold out</span>
+  </div>
+  <button class="favorite" type="button" part="favorite" aria-pressed="false">
+    <span aria-hidden="true">♡</span>
+  </button>
+  <div class="body">
+    <h3 part="title"></h3>
+    <div class="meta">
+      <span class="price" hidden></span>
+      <span class="rating" role="img" hidden></span>
+    </div>
+    <div class="description"><slot></slot></div>
+    <a class="btn" part="link">View Details</a>
+  </div>
+`;
+
+const priceFormat = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+
+const STRING_ATTRS = ['name', 'href', 'image', 'image-alt'];
+const NUMBER_ATTRS = ['price', 'rating'];
+const BOOLEAN_ATTRS = ['featured', 'sold-out', 'favorite'];
+
+const toProp = (attr) => attr.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
+
+export class CoffeeCard extends HTMLElement {
+  static observedAttributes = [...STRING_ATTRS, ...NUMBER_ATTRS, ...BOOLEAN_ATTRS];
+
+  #els;
+  #abort = null;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.append(template.content.cloneNode(true));
+    this.#els = {
+      figure: root.querySelector('figure'),
+      img: root.querySelector('img'),
+      title: root.querySelector('h3'),
+      price: root.querySelector('.price'),
+      rating: root.querySelector('.rating'),
+      featured: root.querySelector('.badge.featured'),
+      soldOut: root.querySelector('.badge.sold-out'),
+      favorite: root.querySelector('.favorite'),
+      favoriteIcon: root.querySelector('.favorite span'),
+      link: root.querySelector('.btn'),
+    };
+  }
+
+  connectedCallback() {
+    // Properties set before upgrade live as own instance props that shadow the
+    // prototype accessors; re-run them through the setters.
+    for (const attr of CoffeeCard.observedAttributes) this.#upgradeProperty(toProp(attr));
+
+    // Idempotent: connectedCallback re-runs on every insertion.
+    if (!this.#abort) {
+      this.#abort = new AbortController();
+      const { signal } = this.#abort;
+      this.#els.favorite.addEventListener('click', () => this.toggleFavorite(), { signal });
+      this.#els.img.addEventListener('error', () => { this.#els.figure.hidden = true; }, { signal });
+    }
+
+    // Sync everything from attributes that may already be present (upgrade case).
+    this.#render();
+  }
+
+  disconnectedCallback() {
+    this.#abort?.abort();
+    this.#abort = null;
