+  <script>
+    (function () {
+      var picker = document.querySelector('.roast-picker');
+      if (!picker) return;
+      var select = document.getElementById(picker.dataset.select);
+      var trigger = picker.querySelector('.roast-trigger');
+      var list = picker.querySelector('.roast-list');
+      var options = Array.prototype.slice.call(list.querySelectorAll('.roast-option'));
+      var thumb = trigger.querySelector('.roast-trigger-thumb');
+      var label = trigger.querySelector('.roast-trigger-text');
+      var active = 0;
+
+      function selectedIndex() {
+        for (var i = 0; i < options.length; i++) {
+          if (options[i].dataset.value === select.value) return i;
+        }
+        return 0;
+      }
+
+      function setActive(i) {
+        active = (i + options.length) % options.length;
+        options.forEach(function (o, j) { o.classList.toggle('is-active', j === active); });
+        list.setAttribute('aria-activedescendant', options[active].id);
+      }
+
+      function choose(i) {
+        var opt = options[i];
+        select.value = opt.dataset.value;
+        select.dispatchEvent(new Event('change', { bubbles: true }));
+        options.forEach(function (o) { o.setAttribute('aria-selected', String(o === opt)); });
+        var img = opt.querySelector('.roast-option-img');
+        thumb.className = 'roast-trigger-thumb ' + img.className.replace('roast-option-img', '').trim();
+        thumb.style.backgroundImage = img.style.backgroundImage;
+        label.textContent = opt.querySelector('.roast-option-name').textContent;
+      }
+
+      function open() {
+        list.hidden = false;
+        trigger.setAttribute('aria-expanded', 'true');
+        setActive(selectedIndex());
+        list.focus();
+      }
+
+      function close(refocus) {
+        list.hidden = true;
+        trigger.setAttribute('aria-expanded', 'false');
+        if (refocus) trigger.focus();
+      }
+
+      trigger.addEventListener('click', function () {
+        list.hidden ? open() : close(true);
+      });
+
+      trigger.addEventListener('keydown', function (e) {
+        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
+          e.preventDefault();
+          open();
+        }
+      });
+
+      options.forEach(function (o, i) {
+        o.addEventListener('click', function () { choose(i); close(true); });
+        o.addEventListener('mousemove', function () { if (active !== i) setActive(i); });
+      });
+
+      list.addEventListener('keydown', function (e) {
+        switch (e.key) {
+          case 'ArrowRight': case 'ArrowDown': e.preventDefault(); setActive(active + 1); break;
+          case 'ArrowLeft': case 'ArrowUp': e.preventDefault(); setActive(active - 1); break;
+          case 'Home': e.preventDefault(); setActive(0); break;
+          case 'End': e.preventDefault(); setActive(options.length - 1); break;
+          case 'Enter': case ' ': e.preventDefault(); choose(active); close(true); break;
+          case 'Escape': e.preventDefault(); close(true); break;
+          case 'Tab': close(false); break;
+        }
+      });
+
+      document.addEventListener('click', function (e) {
