+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Fetch</title>
+</head>
+<body>
+  <button type="button" id="go">Load</button>
+  <pre id="out" aria-live="polite"></pre>
+  <script>
+    const out = document.getElementById('out');
+    document.getElementById('go').addEventListener('click', async () => {
+      // Analytics: fire-and-forget, low priority so it doesn't contend with the critical request.
+      fetch('/api/analytics', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ click: 1 }),
+        priority: 'low',
+        keepalive: true
+      }).catch(() => {});
+
+      // Mission-critical data: high priority.
+      try {
+        const res = await fetch('/api/data', { priority: 'high' });
+        if (!res.ok) throw new Error(`HTTP ${res.status}`);
+        out.textContent = await res.text();
+      } catch (err) {
+        out.textContent = `Error: ${err.message}`;
+      }
+    });
+  </script>
+</body>
+</html>

