+    // Detect whether this page was opened in a background tab during initial load.
+    (() => {
+      const FALLBACK_NOTE =
+        'VisibilityStateEntry is unsupported; fell back to document.visibilityState, ' +
+        'which is unreliable for async scripts (the page may have been foregrounded ' +
+        'before this script ran) and its timestamp is less precise.';
+
+      // Preferred: the Performance timeline records visibility changes from navigation
+      // start, regardless of when this script executes.
+      function getVisibilityInfo() {
+        const entries = performance.getEntriesByType('visibility-state');
+        if (entries.length === 0) return null;
+        const firstHidden = entries.find((entry) => entry.name === 'hidden');
+        return {
+          backgrounded: entries[0].name === 'hidden',
+          timestamp: firstHidden ? firstHidden.startTime : null,
+        };
+      }
