+      // Fallback: only sees the state at execution time.
+      function getFallbackVisibilityInfo() {
+        const backgrounded = document.visibilityState === 'hidden';
+        return {
+          backgrounded,
+          timestamp: backgrounded ? 0 : null,
+          note: FALLBACK_NOTE,
+        };
+      }
+
+      const info = ('VisibilityStateEntry' in window && getVisibilityInfo()) ||
+        getFallbackVisibilityInfo();
+
