   </style>
+
+  <!--
+    Background-tab detection.
+    Logs whether this page was opened in a background tab during initial load.
+    Prefers the Performance Timeline "visibility-state" entry (recorded by the
+    browser at navigation start, so it is accurate no matter when this script
+    runs). Older browsers fall back to document.visibilityState, which only
+    reflects the state at the moment this script executes.
+  -->
+  <script>
+    (function () {
+      var ASYNC_NOTE =
+        'Fallback check used: document.visibilityState reflects the state when this ' +
+        'script executed, not at navigation start. If this script is loaded async ' +
+        '(or deferred / injected late), the tab may have changed visibility before it ' +
+        'ran, so the result may be unreliable.';
+
+      function supportsVisibilityStateEntries() {
+        return typeof PerformanceObserver !== 'undefined' &&
+          Array.isArray(PerformanceObserver.supportedEntryTypes) &&
+          PerformanceObserver.supportedEntryTypes.indexOf('visibility-state') !== -1 &&
+          typeof performance !== 'undefined' &&
+          typeof performance.getEntriesByType === 'function';
+      }
+
+      function detectBackgrounded() {
+        if (supportsVisibilityStateEntries()) {
+          var entries = performance.getEntriesByType('visibility-state');
+          // The browser records the initial visibility state with startTime 0.
+          for (var i = 0; i < entries.length; i++) {
+            if (entries[i].startTime === 0) {
+              return { backgrounded: entries[i].name === 'hidden', reliable: true };
+            }
+          }
+        }
+
+        // Older fallback checks.
+        var hidden;
+        if (typeof document.visibilityState === 'string') {
+          hidden = document.visibilityState === 'hidden';
+        } else if (typeof document.hidden === 'boolean') {
+          hidden = document.hidden;
+        } else {
+          // Page Visibility API unavailable; assume foreground.
+          hidden = false;
+        }
+        return { backgrounded: hidden, reliable: false };
+      }
+
+      var result = detectBackgrounded();
+      var report = {
+        backgrounded: result.backgrounded,
+        timestamp: Date.now()
+      };
+      if (!result.reliable) {
+        report.note = ASYNC_NOTE;
+      }
+
+      console.log('[The Daily Grind] Initial load visibility:', report);
+    })();
+  </script>
 </head>

