+          if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return; // allow open-in-new-tab
+          e.preventDefault();
+          openDialog(el.dataset.openDrink, el);
+        });
+      });
+
+      dialog.querySelectorAll('[data-dismiss]').forEach((btn) => {
+        btn.addEventListener('click', requestDismiss);
+      });
+
+      // Escape key
+      dialog.addEventListener('cancel', (e) => {
+        e.preventDefault();
+        if (!discardPanel.hidden) {
+          // Escape on the prompt itself means "keep editing"
+          hideDiscardPrompt();
+          return;
+        }
+        requestDismiss();
+      });
+
+      // Backdrop click (clicks on the <dialog> element itself, outside its content box)
+      dialog.addEventListener('click', (e) => {
+        if (e.target !== dialog) return;
+        const r = dialog.getBoundingClientRect();
+        const inside = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
+        if (!inside) requestDismiss();
+      });
+
+      // Safety net: some browsers may close a modal on repeated Escape even when
+      // `cancel` is prevented. If that happens with unsaved changes, reopen it.
+      dialog.addEventListener('close', () => {
+        if (!allowClose && isDirty()) {
+          dialog.showModal();
+          showDiscardPrompt();
+          return;
+        }
+        document.body.classList.remove('modal-open');
+        hideDiscardPrompt();
+        if (opener && document.contains(opener)) opener.focus();
+      });
+
+      discardConfirm.addEventListener('click', closeDialog);
+      discardCancel.addEventListener('click', () => {
+        hideDiscardPrompt();
+        drinkSelect.focus();
+      });
+
+      drinkSelect.addEventListener('change', () => {
+        const key = drinkSelect.value;
+        showDrink(key);
+      });
+
+      form.addEventListener('input', () => {
+        updateTotal();
+        if (!isDirty()) hideDiscardPrompt();
+      });
+      form.addEventListener('change', updateTotal);
+
+      img.addEventListener('error', () => { img.hidden = true; });
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        if (!form.reportValidity()) return;
+        const data = new FormData(form);
+        const d = DRINKS[data.get('drink')];
+        const qty = parseInt(data.get('quantity'), 10) || 1;
+        const total = totalOut.value;
+        closeDialog();
+        toast.textContent = `Added ${qty} × ${d.name} to your order (${total}).`;
+        toast.hidden = false;
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(() => { toast.hidden = true; }, 4000);
+      });
+    })();
+  </script>
+
 </body>

