+import {
+  SUITES,
+  availableSuites,
+  getSigningKey,
+  signDocument,
+  verifyDocument,
+} from './signatures.js';
+
+const $ = (sel) => document.querySelector(sel);
+
+const MENU = {
+  'maple-oat-latte': { name: 'Maple Oat Latte', price: 5.75 },
+  'dark-roast-espresso': { name: 'Dark Roast Espresso', price: 3.5 },
+  'cold-brew': { name: 'Cold Brew', price: 4.95 },
+};
+
+const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+const dateFmt = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' });
+
+const suiteSelect = $('#sig-suite');
+const keyInfo = $('#sig-key-info');
+const docField = $('#sig-document');
+const status = $('#sig-status');
+const preview = $('#sig-preview');
+const section = $('#secure-receipts');
+
+function randomId(prefix) {
+  const bytes = crypto.getRandomValues(new Uint8Array(6));
+  return `${prefix}-${Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
+}
+
+function setStatus(state, message) {
+  status.dataset.state = state;
+  status.textContent = message;
+}
+
+async function refreshKeyInfo() {
+  const suite = suiteSelect.value;
+  keyInfo.textContent = 'Loading signing key…';
+  try {
+    const key = await getSigningKey(suite);
+    keyInfo.textContent = `Key fingerprint ${key.fingerprint} · ${
+      SUITES[suite].postQuantum ? 'quantum-resistant' : 'classical'
+    } · ${key.publicKeyBytes.byteLength}-byte public key`;
+  } catch (err) {
+    keyInfo.textContent = `Could not create a ${suite} key: ${err.message}`;
+  }
+}
+
+function addRow(dl, term, value) {
+  const dt = document.createElement('dt');
+  dt.textContent = term;
+  const dd = document.createElement('dd');
+  dd.textContent = value;
+  dl.append(dt, dd);
+}
+
+function renderPreview(payload) {
+  preview.replaceChildren();
+  if (!payload) {
+    preview.hidden = true;
+    return;
+  }
+  const title = document.createElement('h4');
+  const dl = document.createElement('dl');
+  if (payload.kind === 'receipt') {
+    title.textContent = `Receipt ${payload.id}`;
+    addRow(dl, 'Customer', payload.customer);
+    for (const line of payload.items ?? []) {
+      addRow(dl, `${line.qty} × ${line.name}`, money.format(line.lineTotal));
+    }
+    addRow(dl, 'Total', money.format(payload.total));
+    addRow(dl, 'Issued', dateFmt.format(new Date(payload.issuedAt)));
+  } else {
+    title.textContent = `Gift voucher ${payload.code}`;
+    addRow(dl, 'For', payload.recipient);
+    addRow(dl, 'From', payload.from);
+    addRow(dl, 'Value', money.format(payload.amount));
+    if (payload.message) addRow(dl, 'Message', payload.message);
+    addRow(dl, 'Expires', dateFmt.format(new Date(payload.expiresAt)));
+  }
+  preview.append(title, dl);
+  preview.hidden = false;
+}
+
+async function issue(kind, payload) {
+  setStatus('pending', 'Signing…');
+  try {
+    const envelope = await signDocument(kind, payload, suiteSelect.value);
+    docField.value = JSON.stringify(envelope, null, 2);
+    renderPreview(JSON.parse(envelope.payload));
+    setStatus('valid', `Signed with ${envelope.suite}. Edit any field below and press Verify to see tampering detected.`);
+    docField.focus();
+  } catch (err) {
+    setStatus('invalid', `Signing failed: ${err.message}`);
+  }
+}
+
+$('#receipt-form').addEventListener('submit', (event) => {
+  event.preventDefault();
+  const form = new FormData(event.currentTarget);
+  const item = MENU[form.get('item')];
+  const qty = Number(form.get('qty'));
+  const lineTotal = Math.round(item.price * qty * 100) / 100;
+  issue('receipt', {
+    id: randomId('RCPT'),
+    customer: String(form.get('customer')).trim(),
+    items: [{ name: item.name, qty, unitPrice: item.price, lineTotal }],
+    total: lineTotal,
+    currency: 'USD',
+    issuedAt: new Date().toISOString(),
+  });
+});
+
+$('#voucher-form').addEventListener('submit', (event) => {
+  event.preventDefault();
+  const form = new FormData(event.currentTarget);
+  const expires = new Date();
+  expires.setFullYear(expires.getFullYear() + 1);
+  issue('voucher', {
+    code: randomId('GIFT'),
+    recipient: String(form.get('recipient')).trim(),
+    from: String(form.get('from')).trim(),
+    amount: Number(form.get('amount')),
+    currency: 'USD',
+    message: String(form.get('message') ?? '').trim(),
+    issuedAt: new Date().toISOString(),
+    expiresAt: expires.toISOString(),
+  });
+});
+
+$('#verify-form').addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (!docField.value.trim()) {
+    setStatus('invalid', 'Paste a signed receipt or voucher first.');
+    return;
+  }
+  setStatus('pending', 'Verifying…');
+  const result = await verifyDocument(docField.value);
+  setStatus(result.status, result.message);
+  renderPreview(result.status === 'valid' || result.status === 'expired' ? result.payload : null);
+});
+
+$('#sig-copy').addEventListener('click', async () => {
+  if (!docField.value) return;
+  try {
+    await navigator.clipboard.writeText(docField.value);
+    setStatus(status.dataset.state ?? 'pending', 'Copied signed document to clipboard.');
+  } catch {
+    docField.select();
+  }
+});
+
+suiteSelect.addEventListener('change', refreshKeyInfo);
+
+(async function init() {
+  const suites = await availableSuites();
+  if (suites.length === 0) {
+    section.querySelectorAll('button, input, select, textarea').forEach((el) => (el.disabled = true));
+    setStatus('invalid', 'Digital signatures need a secure (HTTPS) connection and a modern browser.');
+    return;
+  }
+  suiteSelect.replaceChildren(
+    ...suites.map((id) => new Option(SUITES[id].label, id)),
+  );
+  suiteSelect.disabled = false;
+  if (!suites.includes('ML-DSA-65')) {
+    setStatus('pending', 'Your browser lacks post-quantum ML-DSA support; using classical signatures.');
+  }
+  await refreshKeyInfo();
+})();
