index 0000000..a43e43a
--- /dev/null
+++ b/js/signatures.js
@@ -0,0 +1,330 @@
+// Digital signatures for Daily Grind receipts and gift vouchers.
+//
+// Uses WebCrypto only (no dependencies):
+//   - ML-DSA-65 (post-quantum, NIST FIPS 204) when the browser supports it
+//   - Ed25519 (classical) as the first fallback
+//   - ECDSA P-256 / SHA-256 (classical) for older browsers
+//
+// Every signature is bound to a domain-separation context ("receipt" vs
+// "voucher") so a signed receipt can never be replayed as a gift voucher.
+
+export const FORMAT = 'daily-grind-signed/1';
+
+export const CONTEXTS = Object.freeze({
+  receipt: 'daily-grind/receipt/v1',
+  voucher: 'daily-grind/voucher/v1',
+});
+
+export const SUITES = Object.freeze({
+  'ML-DSA-65': { label: 'ML-DSA-65 — quantum-resistant (FIPS 204)', postQuantum: true },
+  Ed25519: { label: 'Ed25519 — classical', postQuantum: false },
+  'ECDSA-P256': { label: 'ECDSA P-256 — classical (legacy browsers)', postQuantum: false },
+});
+
+const encoder = new TextEncoder();
+
+/* ---------- base64url helpers (native when available) ---------- */
+
+export function toBase64Url(bytes) {
+  if (typeof bytes.toBase64 === 'function') {
+    return bytes.toBase64({ alphabet: 'base64url', omitPadding: true });
+  }
+  let binary = '';
+  for (const b of bytes) binary += String.fromCharCode(b);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromBase64Url(text) {
+  if (typeof text !== 'string') throw new TypeError('Expected base64url string');
+  if (typeof Uint8Array.fromBase64 === 'function') {
+    return Uint8Array.fromBase64(text, { alphabet: 'base64url' });
+  }
+  if (!/^[A-Za-z0-9_-]*$/.test(text)) throw new SyntaxError('Invalid base64url');
+  const b64 = text.replace(/-/g, '+').replace(/_/g, '/');
+  const binary = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+  return Uint8Array.from(binary, (c) => c.charCodeAt(0));
+}
+
+function bytesEqual(a, b) {
+  if (a.byteLength !== b.byteLength) return false;
+  let diff = 0;
+  for (let i = 0; i < a.byteLength; i++) diff |= a[i] ^ b[i];
+  return diff === 0;
+}
+
+/* ---------- algorithm descriptors ---------- */
+
+const ALGORITHMS = {
+  'ML-DSA-65': {
+    generate: 'ML-DSA-65',
+    import: 'ML-DSA-65',
+    publicFormat: 'raw-public', // ML-DSA rejects the legacy 'raw' format
+    nativeContext: true,
+    sign: (context) => ({ name: 'ML-DSA-65', context }),
+  },
+  Ed25519: {
+    generate: 'Ed25519',
+    import: 'Ed25519',
+    publicFormat: 'raw',
+    nativeContext: false,
+    sign: () => 'Ed25519',
+  },
+  'ECDSA-P256': {
+    generate: { name: 'ECDSA', namedCurve: 'P-256' },
+    import: { name: 'ECDSA', namedCurve: 'P-256' },
+    publicFormat: 'raw',
+    nativeContext: false,
+    sign: () => ({ name: 'ECDSA', hash: 'SHA-256' }),
+  },
+};
+
+// Classical algorithms ignore a `context` member, so emulate ML-DSA's domain
+// separation by prefixing a length-framed context to the signed bytes.
+function frame(payloadBytes, contextBytes) {
+  if (contextBytes.byteLength > 255) {
+    throw new DOMException('Context must not exceed 255 bytes', 'OperationError');
+  }
+  const framed = new Uint8Array(1 + contextBytes.byteLength + payloadBytes.byteLength);
+  framed[0] = contextBytes.byteLength;
+  framed.set(contextBytes, 1);
+  framed.set(payloadBytes, 1 + contextBytes.byteLength);
+  return framed;
+}
+
+function signingInput(suite, payloadBytes, contextBytes) {
+  const alg = ALGORITHMS[suite];
+  return alg.nativeContext
+    ? { params: alg.sign(contextBytes), data: payloadBytes }
+    : { params: alg.sign(contextBytes), data: frame(payloadBytes, contextBytes) };
+}
+
+/* ---------- feature detection ---------- */
+
+export function supportsPostQuantumSignatures() {
+  return (
+    typeof globalThis.SubtleCrypto?.supports === 'function' &&
+    SubtleCrypto.supports('sign', 'ML-DSA-65')
+  );
+}
+
+async function supportsEd25519() {
+  if (typeof globalThis.SubtleCrypto?.supports === 'function') {
+    return SubtleCrypto.supports('sign', 'Ed25519');
+  }
+  try {
+    await crypto.subtle.generateKey('Ed25519', false, ['sign', 'verify']);
+    return true;
+  } catch {
+    return false;
+  }
+}
+
+/** Returns available suite ids, strongest first. */
+export async function availableSuites() {
+  if (!globalThis.isSecureContext || !globalThis.crypto?.subtle) return [];
+  const suites = [];
+  if (supportsPostQuantumSignatures()) suites.push('ML-DSA-65');
+  if (await supportsEd25519()) suites.push('Ed25519');
+  suites.push('ECDSA-P256');
+  return suites;
+}
+
+/* ---------- key storage (IndexedDB keeps non-extractable CryptoKeys) ---------- */
+
+const DB_NAME = 'daily-grind-signing';
+const STORE = 'keys';
+const memoryKeys = new Map(); // fallback when IndexedDB is unavailable
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE, { keyPath: 'suite' });
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function idb(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE, mode);
+      const req = fn(tx.objectStore(STORE));
+      tx.oncomplete = () => resolve(req.result);
+      tx.onerror = tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+async function loadKeyRecord(suite) {
+  if (memoryKeys.has(suite)) return memoryKeys.get(suite);
+  try {
+    const record = await idb('readonly', (s) => s.get(suite));
+    if (record) memoryKeys.set(suite, record);
+    return record;
+  } catch {
+    return undefined;
+  }
+}
+
+async function saveKeyRecord(record) {
+  memoryKeys.set(record.suite, record);
+  try {
+    await idb('readwrite', (s) => s.put(record));
+  } catch {
+    /* private browsing etc. — keep in memory only */
+  }
+}
+
+async function fingerprint(suite, publicKeyBytes) {
+  const input = new Uint8Array([...encoder.encode(suite), 0, ...publicKeyBytes]);
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', input));
+  return Array.from(digest.slice(0, 16), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .match(/.{4}/g)
+    .join(':');
+}
+
+/**
+ * Returns the store's signing key for `suite`, creating it on first use.
+ * The private key is generated non-extractable so it can't be exfiltrated.
+ */
+export async function getSigningKey(suite) {
+  const existing = await loadKeyRecord(suite);
+  if (existing) return existing;
+
+  const alg = ALGORITHMS[suite];
+  if (!alg) throw new Error(`Unknown suite ${suite}`);
+  const keyPair = await crypto.subtle.generateKey(alg.generate, false, ['sign', 'verify']);
+  const publicKeyBytes = new Uint8Array(
+    await crypto.subtle.exportKey(alg.publicFormat, keyPair.publicKey),
+  );
+  const record = {
+    suite,
+    privateKey: keyPair.privateKey,
+    publicKey: keyPair.publicKey,
+    publicKeyBytes,
+    fingerprint: await fingerprint(suite, publicKeyBytes),
+    createdAt: new Date().toISOString(),
+  };
+  await saveKeyRecord(record);
+  return record;
+}
+
+/* ---------- sign / verify documents ---------- */
+
+/**
+ * Signs a receipt or voucher payload and returns a self-describing envelope.
+ * The payload is serialized once; the exact bytes signed are carried as a
+ * string so verification never depends on JSON key ordering.
+ */
+export async function signDocument(kind, payload, suite) {
+  if (!(kind in CONTEXTS)) throw new Error(`Unknown document kind ${kind}`);
+  const key = await getSigningKey(suite);
+  const payloadText = JSON.stringify({ ...payload, kind });
+  const payloadBytes = encoder.encode(payloadText);
+  const { params, data } = signingInput(suite, payloadBytes, encoder.encode(CONTEXTS[kind]));
+  const signature = new Uint8Array(await crypto.subtle.sign(params, key.privateKey, data));
+
+  return {
+    format: FORMAT,
+    kind,
+    suite,
+    keyId: key.fingerprint,
+    publicKey: toBase64Url(key.publicKeyBytes),
+    payload: payloadText,
+    signature: toBase64Url(signature),
+  };
+}
+
+/**
+ * Verifies an envelope against the store's *trusted* keys (never against a
+ * key supplied by the document itself, which anyone could forge).
+ *
+ * @returns {{ status: 'valid'|'expired'|'invalid'|'untrusted'|'malformed',
+ *             message: string, payload?: object, envelope?: object }}
+ */
+export async function verifyDocument(input) {
+  let envelope;
+  try {
+    envelope = typeof input === 'string' ? JSON.parse(input) : input;
+  } catch {
+    return { status: 'malformed', message: 'This is not a valid signed document (bad JSON).' };
+  }
+
+  if (
+    !envelope ||
+    envelope.format !== FORMAT ||
+    !(envelope.kind in CONTEXTS) ||
+    !(envelope.suite in ALGORITHMS) ||
+    typeof envelope.payload !== 'string' ||
+    typeof envelope.signature !== 'string' ||
+    typeof envelope.publicKey !== 'string'
+  ) {
+    return { status: 'malformed', message: 'Missing or unrecognized signature fields.' };
+  }
+
+  let signature;
+  let embeddedKey;
+  try {
+    signature = fromBase64Url(envelope.signature);
+    embeddedKey = fromBase64Url(envelope.publicKey);
+  } catch {
+    return { status: 'malformed', message: 'Signature or key is not valid base64url.' };
+  }
+
+  const trusted = await loadKeyRecord(envelope.suite);
+  if (!trusted || !bytesEqual(trusted.publicKeyBytes, embeddedKey)) {
+    return {
+      status: 'untrusted',
+      message: 'Signed by a key that is not a trusted Daily Grind key.',
+      envelope,
+    };
+  }
+
+  const payloadBytes = encoder.encode(envelope.payload);
+  const contextBytes = encoder.encode(CONTEXTS[envelope.kind]);
+  const { params, data } = signingInput(envelope.suite, payloadBytes, contextBytes);
+
+  let ok = false;
+  try {
+    ok = await crypto.subtle.verify(params, trusted.publicKey, signature, data);
+  } catch {
+    ok = false;
+  }
+  if (!ok) {
+    return {
+      status: 'invalid',
+      message: 'Signature check failed — this document was altered or forged.',
+      envelope,
+    };
+  }
+
+  let payload;
+  try {
+    payload = JSON.parse(envelope.payload);
+  } catch {
+    return { status: 'malformed', message: 'Signed payload is not valid JSON.', envelope };
+  }
+  if (payload?.kind !== envelope.kind) {
+    return { status: 'invalid', message: 'Document type does not match its signature.', envelope };
+  }
+
+  if (payload.expiresAt && Date.parse(payload.expiresAt) < Date.now()) {
+    return {
+      status: 'expired',
+      message: 'Authentic, but this voucher has expired.',
+      payload,
+      envelope,
+    };
+  }
+
+  return {
+    status: 'valid',
+    message: `Authentic and unmodified — signed with ${envelope.suite}.`,
+    payload,
+    envelope,
+  };
+}

