+// UI wiring for signed receipts & gift vouchers. All untrusted data is
+// rendered via textContent — never innerHTML.
+import * as dg from './signing.js';
+
+const $ = (id) => document.getElementById(id);
+const MENU = [
+  { sku: 'maple-oat-latte', name: 'Maple Oat Latte', unitCents: 575 },
+  { sku: 'dark-roast-espresso', name: 'Dark Roast Espresso', unitCents: 350 },
+  { sku: 'cold-brew', name: 'Cold Brew', unitCents: 495 },
+  { sku: 'butter-croissant', name: 'Butter Croissant', unitCents: 395 },
+];
+const TAX_BPS = 800; // 8.00%
+const money = (c) => (c / 100).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
+
+function el(tag, props = {}, ...children) {
+  const n = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (k === 'class') n.className = v; else if (k === 'text') n.textContent = v; else n.setAttribute(k, v);
+  }
+  for (const c of children) n.append(c);
+  return n;
+}
+
+function flash(target, msg, kind = 'info') {
+  target.textContent = msg;
+  target.className = `sig-msg sig-msg-${kind}`;
+}
+
+// ------------------------------------------------------------- issuer key panel
+
+async function renderIssuer() {
+  const key = await dg.getIssuerKey();
+  const box = $('sig-issuer-info');
+  box.replaceChildren();
+  if (!key) {
+    box.append(el('p', { text: 'No signing key on this device yet. Choose an algorithm and generate one.' }));
+    $('sig-sign-btn').disabled = true;
+  } else {
+    box.append(
+      el('p', {}, el('strong', { text: 'Algorithm: ' }), dg.ALGORITHMS[key.alg].label),
+      el('p', {}, el('strong', { text: 'Fingerprint: ' }), el('code', { text: key.fingerprint })),
+      el('p', { class: 'sig-small', text: `Created ${new Date(key.created).toLocaleString()}. Private key never leaves this browser.` }),
+    );
+    $('sig-sign-btn').disabled = false;
+  }
+  $('sig-export-key').disabled = !key;
+  await renderTrusted();
+}
+
+async function renderTrusted() {
+  const list = $('sig-trusted-list');
+  list.replaceChildren();
+  const keys = await dg.getTrustedKeys();
+  if (!keys.length) list.append(el('li', { class: 'sig-small', text: 'No trusted issuers yet.' }));
+  for (const k of keys) {
+    const rm = el('button', { class: 'sig-link', type: 'button', text: 'remove' });
+    rm.addEventListener('click', async () => { await dg.removeTrustedKey(k.kid); renderTrusted(); });
+    list.append(el('li', {}, el('span', { text: `${k.label} — ${k.alg} — ` }), el('code', { text: dg.formatFingerprint(k.kid) }), ' ', rm));
+  }
+}
+
+async function initIssuer() {
+  const select = $('sig-alg');
+  const algs = await dg.availableAlgorithms();
+  for (const a of algs) select.append(el('option', { value: a, text: dg.ALGORITHMS[a].label }));
+  select.value = algs.includes('Ed25519+ML-DSA-65') ? 'Ed25519+ML-DSA-65' : 'ML-DSA-65';
+  if (!algs.includes('Ed25519')) flash($('sig-key-msg'), 'Ed25519 is not available in this browser; ECDSA P-256 and ML-DSA are offered instead.', 'warn');
+
+  $('sig-gen-key').addEventListener('click', async () => {
+    const existing = await dg.getIssuerKey();
+    if (existing && !confirm('Replace the current signing key? Documents it signed remain verifiable and trusted.')) return;
+    try {
+      flash($('sig-key-msg'), 'Generating key…');
+      const k = await dg.generateIssuerKey(select.value);
+      flash($('sig-key-msg'), `New ${k.alg} key ready.`, 'ok');
+      renderIssuer();
+    } catch (e) { flash($('sig-key-msg'), e.message, 'err'); }
+  });
+
+  $('sig-export-key').addEventListener('click', async () => {
+    try { download('daily-grind-issuer-public-key.json', await dg.exportIssuerPublicKey(), 'application/json'); }
+    catch (e) { flash($('sig-key-msg'), e.message, 'err'); }
+  });
+
+  $('sig-import-key').addEventListener('click', async () => {
+    try {
+      const r = await dg.importTrustedKey($('sig-import-text').value, $('sig-import-label').value);
+      flash($('sig-key-msg'), `Trusted issuer added: ${r.fingerprint}`, 'ok');
+      $('sig-import-text').value = '';
+      renderTrusted();
+    } catch (e) { flash($('sig-key-msg'), e.message, 'err'); }
+  });
+}
+
+// ------------------------------------------------------------- create & sign
+
+function initItems() {
+  const tbody = $('sig-items');
+  for (const m of MENU) {
+    const qty = el('input', { type: 'number', min: '0', max: '20', value: '0', 'data-sku': m.sku, 'aria-label': `${m.name} quantity` });
+    qty.addEventListener('input', updateTotals);
+    tbody.append(el('tr', {}, el('td', { text: m.name }), el('td', { text: money(m.unitCents) }), el('td', {}, qty)));
+  }
+  tbody.querySelector('input').value = '1';
+  updateTotals();
+}
+
+function currentItems() {
+  return MENU.map((m) => {
+    const q = Math.max(0, Math.min(20, parseInt($('sig-items').querySelector(`[data-sku="${m.sku}"]`).value, 10) || 0));
+    return { sku: m.sku, name: m.name, unitCents: m.unitCents, qty: q };
+  }).filter((i) => i.qty > 0);
+}
+
+function totals(items) {
+  const subtotalCents = items.reduce((n, i) => n + i.unitCents * i.qty, 0);
+  const taxCents = Math.round((subtotalCents * TAX_BPS) / 10000);
+  return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
+}
+
+function updateTotals() {
+  const t = totals(currentItems());
+  $('sig-totals').textContent = `Subtotal ${money(t.subtotalCents)} · Tax ${money(t.taxCents)} · Total ${money(t.totalCents)}`;
+}
+
+function buildPayload() {
+  const now = new Date().toISOString();
+  if ($('sig-doc-type').value === 'receipt') {
+    const items = currentItems();
+    if (!items.length) throw new Error('Add at least one item to the order.');
+    return {
+      type: 'receipt',
+      orderId: 'DG-' + dg.randomId(6).toUpperCase(),
+      issuedAt: now,
+      store: $('sig-store').value,
+      customer: $('sig-customer').value.trim().slice(0, 80),
+      currency: 'USD',
+      items,
+      ...totals(items),
+    };
+  }
+  const amountCents = Math.round(parseFloat($('sig-v-amount').value) * 100);
+  if (!Number.isSafeInteger(amountCents) || amountCents < 100 || amountCents > 50000) throw new Error('Voucher amount must be between $1 and $500.');
+  const days = parseInt($('sig-v-days').value, 10);
+  if (!(days >= 1 && days <= 1095)) throw new Error('Validity must be 1–1095 days.');
+  return {
+    type: 'voucher',
+    code: 'GV-' + dg.randomId(12).toUpperCase().replace(/[-_]/g, 'X'),
+    issuedAt: now,
+    expiresAt: new Date(Date.now() + days * 86400000).toISOString(),
+    currency: 'USD',
+    amountCents,
+    recipient: $('sig-v-to').value.trim().slice(0, 80),
+    from: $('sig-v-from').value.trim().slice(0, 80),
+    message: $('sig-v-msg').value.trim().slice(0, 200),
+  };
+}
+
+let lastToken = '';
+
+function initSign() {
+  const typeSel = $('sig-doc-type');
+  const toggle = () => {
+    $('sig-receipt-fields').hidden = typeSel.value !== 'receipt';
+    $('sig-voucher-fields').hidden = typeSel.value !== 'voucher';
+  };
+  typeSel.addEventListener('change', toggle);
+  toggle();
+
+  $('sig-sign-btn').addEventListener('click', async () => {
+    try {
+      const { envelope, token } = await dg.signDocument(buildPayload());
+      lastToken = token;
+      $('sig-token').value = token;
+      $('sig-output').hidden = false;
+      renderDocument($('sig-preview'), envelope.payload);
+      flash($('sig-sign-msg'), `Signed with ${envelope.alg} (${token.length.toLocaleString()} characters).`, 'ok');
+    } catch (e) { flash($('sig-sign-msg'), e.message, 'err'); }
+  });
+
+  $('sig-copy').addEventListener('click', async () => {
+    try { await navigator.clipboard.writeText($('sig-token').value); flash($('sig-sign-msg'), 'Copied to clipboard.', 'ok'); }
+    catch { $('sig-token').select(); flash($('sig-sign-msg'), 'Press Ctrl/Cmd+C to copy.', 'info'); }
+  });
+  $('sig-download').addEventListener('click', () => download('daily-grind-signed.dg1', $('sig-token').value, 'text/plain'));
+  $('sig-send-verify').addEventListener('click', () => {
+    $('sig-verify-input').value = lastToken;
+    $('sig-verify-input').scrollIntoView({ behavior: 'smooth', block: 'center' });
+    runVerify();
+  });
+}
+
+// ------------------------------------------------------------- verify
+
+function renderDocument(container, p) {
+  container.replaceChildren();
+  if (!p || typeof p !== 'object') return;
+  const row = (k, v) => el('div', { class: 'sig-row' }, el('span', { text: k }), el('span', { text: String(v ?? '') }));
+  if (p.type === 'receipt') {
+    container.append(el('h4', { text: 'Order Receipt' }), row('Order', p.orderId), row('Store', p.store), row('Date', fmtDate(p.issuedAt)));
+    if (p.customer) container.append(row('Customer', p.customer));
+    for (const i of Array.isArray(p.items) ? p.items : []) container.append(row(`${i.qty} × ${i.name}`, money(i.unitCents * i.qty)));
+    container.append(row('Subtotal', money(p.subtotalCents)), row('Tax', money(p.taxCents)), el('div', { class: 'sig-row sig-total' }, el('span', { text: 'Total' }), el('span', { text: money(p.totalCents) })));
+  } else if (p.type === 'voucher') {
+    container.append(el('h4', { text: 'Gift Voucher' }), el('div', { class: 'sig-voucher-amt', text: money(p.amountCents) }),
+      row('Code', p.code), row('To', p.recipient), row('From', p.from), row('Issued', fmtDate(p.issuedAt)), row('Expires', fmtDate(p.expiresAt)));
+    if (p.message) container.append(el('p', { class: 'sig-small', text: `“${p.message}”` }));
+  } else {
+    container.append(el('pre', { text: JSON.stringify(p, null, 2) }));
+  }
+}
+
+function fmtDate(s) {
+  const d = new Date(s);
+  return isNaN(d) ? String(s ?? '') : d.toLocaleString();
+}
+
+async function runVerify() {
+  const out = $('sig-verify-result');
+  out.replaceChildren(el('p', { text: 'Verifying…' }));
+  const r = await dg.verifyDocument($('sig-verify-input').value);
+  const banner = {
+    trusted: ['sig-ok', '✔ Authentic & unmodified', `Signed by ${r.issuerLabel}.`],
+    untrusted: ['sig-warn', '⚠ Signature valid, issuer unknown', 'The document has not been altered since signing, but the signing key is not in your trusted issuers list. Compare the fingerprint with the issuer out-of-band before trusting it.'],
+    invalid: ['sig-bad', '✘ Verification failed', 'This document is forged, corrupted or has been tampered with. Do not accept it.'],
+  }[r.status];
+  const box = el('div', { class: `sig-banner ${banner[0]}` }, el('strong', { text: banner[1] }), el('p', { text: banner[2] }));
+  if (r.fingerprint) box.append(el('p', { class: 'sig-small' }, 'Signer fingerprint: ', el('code', { text: r.fingerprint })));
+  const checks = el('ul', { class: 'sig-checks' });
+  for (const c of r.checks) checks.append(el('li', { class: c.ok ? 'ok' : 'bad', text: c.label }));
+  out.replaceChildren(box, checks);
+  for (const w of r.warnings) out.append(el('p', { class: 'sig-msg sig-msg-warn', text: w }));
+  if (r.payload) { const doc = el('div', { class: 'sig-doc' }); renderDocument(doc, r.payload); out.append(doc); }
+}
+
+function initVerify() {
+  $('sig-verify-btn').addEventListener('click', runVerify);
+  $('sig-verify-file').addEventListener('change', async (e) => {
+    const f = e.target.files[0];
+    if (!f) return;
+    if (f.size > 256 * 1024) { flash($('sig-verify-msg'), 'File too large.', 'err'); return; }
+    $('sig-verify-input').value = await f.text();
+    runVerify();
+  });
+  $('sig-tamper').addEventListener('click', () => {
+    // Demo: change the amount/total inside the payload and re-encode, keeping the original signature.
+    try {
+      const env = dg.decodeToken($('sig-verify-input').value || lastToken);
+      if (env.payload?.type === 'voucher') env.payload.amountCents += 1000;
+      else if (env.payload?.type === 'receipt') env.payload.totalCents = Math.max(0, env.payload.totalCents - 100);
+      $('sig-verify-input').value = dg.encodeToken(env);
+      flash($('sig-verify-msg'), 'Payload altered (signature unchanged). Verifying…', 'info');
+      runVerify();
+    } catch (e) { flash($('sig-verify-msg'), 'Sign or paste a document first.', 'err'); }
+  });
+}
+
+function download(name, text, type) {
+  const url = URL.createObjectURL(new Blob([text], { type }));
+  const a = el('a', { href: url, download: name });
+  document.body.append(a); a.click(); a.remove();
+  setTimeout(() => URL.revokeObjectURL(url), 1000);
+}
+
+(async () => {
+  if (!window.isSecureContext || !window.crypto?.subtle || !window.indexedDB) {
+    flash($('sig-key-msg'), 'Signing needs a secure context (HTTPS or localhost) with WebCrypto and IndexedDB.', 'err');
+    return;
+  }
+  initItems();
+  initSign();
+  initVerify();
+  try { await initIssuer(); await renderIssuer(); }
+  catch (e) { flash($('sig-key-msg'), e.message, 'err'); }
+})();
