@@ -0,0 +1,410 @@
+// Daily Grind document signing core.
+//
+// Signs and verifies coffee order receipts and gift vouchers entirely in the
+// browser. Supported schemes:
+//   - "Ed25519"                 classical, WebCrypto
+//   - "ECDSA-P256"              classical, WebCrypto (SHA-256, IEEE P1363 r||s)
+//   - "ML-DSA-65"               post-quantum (FIPS 204), vendored noble library
+//   - "Ed25519+ML-DSA-65"       hybrid: BOTH signatures must verify
+//
+// Classical private keys are generated as non-extractable CryptoKeys and kept
+// in IndexedDB (CryptoKey objects are structured-cloneable), so script code
+// can use them but never read the raw key material. ML-DSA has no WebCrypto
+// support yet, so its 32-byte seed is stored in IndexedDB and expanded on use.
+
+import { ml_dsa65 } from '../vendor/noble-post-quantum-ml-dsa-0.7.1.mjs';
+
+export const FORMAT = 'daily-grind-signed-document';
+export const VERSION = 1;
+export const TOKEN_PREFIX = 'DG1.';
+const DOMAIN_TAG = 'DAILYGRIND-SIG-v1';
+const MAX_INPUT_BYTES = 64 * 1024;
+
+export const ALGORITHMS = {
+  'Ed25519': { label: 'Ed25519 (classical)', parts: ['ed25519'] },
+  'ECDSA-P256': { label: 'ECDSA P-256 / SHA-256 (classical)', parts: ['p256'] },
+  'ML-DSA-65': { label: 'ML-DSA-65 (post-quantum, FIPS 204)', parts: ['mldsa65'] },
+  'Ed25519+ML-DSA-65': { label: 'Hybrid Ed25519 + ML-DSA-65', parts: ['ed25519', 'mldsa65'] },
+};
+
+const ED25519 = { name: 'Ed25519' };
+const P256_GEN = { name: 'ECDSA', namedCurve: 'P-256' };
+const P256_SIGN = { name: 'ECDSA', hash: 'SHA-256' };
+
+// Expected raw public key / signature lengths, enforced during verification.
+const PART_SIZES = {
+  ed25519: { pk: 32, sig: 64 },
+  p256: { pk: 65, sig: 64 },
+  mldsa65: { pk: 1952, sig: 3309 },
+};
+
+// ---------------------------------------------------------------- encoding
+
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+export function b64urlEncode(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64urlDecode(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url data');
+  }
+  const pad = str.length % 4 === 0 ? '' : '='.repeat(4 - (str.length % 4));
+  const bin = atob(str.replace(/-/g, '+').replace(/_/g, '/') + pad);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+function concatBytes(...arrays) {
+  const len = arrays.reduce((n, a) => n + a.length, 0);
+  const out = new Uint8Array(len);
+  let off = 0;
+  for (const a of arrays) { out.set(a, off); off += a.length; }
+  return out;
+}
+
+/**
+ * Deterministic JSON serialisation (sorted object keys, no whitespace).
+ * Only plain objects, arrays, strings, booleans, null and safe integers are
+ * allowed, so the byte representation is unambiguous across browsers.
+ * Money is expressed in integer cents.
+ */
+export function canonicalize(value) {
+  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
+    return JSON.stringify(value);
+  }
+  if (typeof value === 'number') {
+    if (!Number.isSafeInteger(value)) throw new Error('Only safe integers are allowed in signed documents');
+    return JSON.stringify(value);
+  }
+  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
+  if (typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
+    return '{' + Object.keys(value).sort()
+      .map((k) => JSON.stringify(k) + ':' + canonicalize(value[k])).join(',') + '}';
+  }
+  throw new Error('Unsupported value in signed document');
+}
+
+/** Bytes actually signed: domain tag, algorithm and key id are bound in. */
+function signingInput(alg, kid, payload) {
+  return enc.encode(`${DOMAIN_TAG}\n${alg}\n${kid}\n${canonicalize(payload)}`);
+}
+
+async function sha256(bytes) {
+  return new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
+}
+
+/** Key id: SHA-256 over algorithm + all public key parts (truncated, 128 bits). */
+async function computeKid(alg, publicKeys) {
+  const parts = ALGORITHMS[alg].parts.map((p) => concatBytes(enc.encode(p + ':'), b64urlDecode(publicKeys[p]), enc.encode('\n')));
+  const digest = await sha256(concatBytes(enc.encode(alg + '\n'), ...parts));
+  return b64urlEncode(digest.subarray(0, 16));
+}
+
+/** Human-friendly fingerprint for display / out-of-band comparison. */
+export function formatFingerprint(kid) {
+  const hex = Array.from(b64urlDecode(kid), (b) => b.toString(16).padStart(2, '0')).join('').toUpperCase();
+  return hex.match(/.{4}/g).join(' ');
+}
+
+export function randomId(bytes = 16) {
+  return b64urlEncode(crypto.getRandomValues(new Uint8Array(bytes)));
+}
+
+// ---------------------------------------------------------------- storage
+
+const DB_NAME = 'daily-grind-signing';
+const STORE = 'keys';
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function dbOp(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE, mode);
+      const req = fn(tx.objectStore(STORE));
+      tx.oncomplete = () => resolve(req && req.result);
+      tx.onerror = () => reject(tx.error);
+      tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+const dbGet = (key) => dbOp('readonly', (s) => s.get(key));
+const dbPut = (key, val) => dbOp('readwrite', (s) => s.put(val, key));
+
+// ---------------------------------------------------------------- feature detection
+
+let ed25519Supported;
+export async function isEd25519Supported() {
+  if (ed25519Supported === undefined) {
+    try {
+      await crypto.subtle.generateKey(ED25519, false, ['sign', 'verify']);
+      ed25519Supported = true;
+    } catch {
+      ed25519Supported = false;
+    }
+  }
+  return ed25519Supported;
+}
+
+export async function availableAlgorithms() {
+  const ed = await isEd25519Supported();
+  return Object.keys(ALGORITHMS).filter((a) => ed || !ALGORITHMS[a].parts.includes('ed25519'));
+}
+
+// ---------------------------------------------------------------- issuer keys
+
+/**
+ * Generate a fresh issuer key for `alg` and persist it, replacing any
+ * existing one. The previous public key stays in the trusted list so
+ * documents it signed continue to verify as trusted.
+ */
+export async function generateIssuerKey(alg) {
+  if (!ALGORITHMS[alg]) throw new Error('Unknown algorithm');
+  if (!window.isSecureContext || !crypto.subtle) throw new Error('Signing requires a secure context (HTTPS or localhost)');
+
+  const record = { alg, created: new Date().toISOString(), privateKeys: {}, publicKeys: {} };
+  for (const part of ALGORITHMS[alg].parts) {
+    if (part === 'ed25519' || part === 'p256') {
+      const kp = await crypto.subtle.generateKey(part === 'ed25519' ? ED25519 : P256_GEN, false, ['sign', 'verify']);
+      record.privateKeys[part] = kp.privateKey; // non-extractable
+      record.publicKeys[part] = b64urlEncode(new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey)));
+    } else if (part === 'mldsa65') {
+      const seed = crypto.getRandomValues(new Uint8Array(32));
+      const { publicKey, secretKey } = ml_dsa65.keygen(seed);
+      secretKey.fill(0);
+      record.privateKeys[part] = seed;
+      record.publicKeys[part] = b64urlEncode(publicKey);
+    }
+  }
+  record.kid = await computeKid(alg, record.publicKeys);
+  await dbPut('issuer', record);
+  await addTrustedKey({ alg, kid: record.kid, publicKeys: record.publicKeys, label: 'This device (issuer)', added: record.created });
+  return describeKey(record);
+}
+
+function describeKey(record) {
+  return {
+    alg: record.alg,
+    kid: record.kid,
+    created: record.created,
+    publicKeys: { ...record.publicKeys },
+    fingerprint: formatFingerprint(record.kid),
+  };
+}
+
+export async function getIssuerKey() {
+  const rec = await dbGet('issuer');
+  return rec ? describeKey(rec) : null;
+}
+
+/** Shareable public key bundle so other devices can trust this issuer. */
+export async function exportIssuerPublicKey() {
+  const rec = await dbGet('issuer');
+  if (!rec) throw new Error('No issuer key yet');
+  return JSON.stringify({ format: 'daily-grind-public-key', version: VERSION, alg: rec.alg, kid: rec.kid, publicKeys: rec.publicKeys }, null, 2);
+}
+
+// ---------------------------------------------------------------- trust store
+
+export async function getTrustedKeys() {
+  return (await dbGet('trusted')) || [];
+}
+
+async function addTrustedKey(entry) {
+  const list = await getTrustedKeys();
+  if (!list.some((k) => k.kid === entry.kid)) list.push(entry);
+  await dbPut('trusted', list);
+}
+
+export async function removeTrustedKey(kid) {
+  await dbPut('trusted', (await getTrustedKeys()).filter((k) => k.kid !== kid));
+}
+
+/** Import another issuer's public key bundle (validated and kid recomputed). */
+export async function importTrustedKey(text, label) {
+  if (text.length > MAX_INPUT_BYTES) throw new Error('Input too large');
+  let obj;
+  try { obj = JSON.parse(text); } catch { throw new Error('Public key must be JSON'); }
+  if (obj?.format !== 'daily-grind-public-key' || obj.version !== VERSION) throw new Error('Not a Daily Grind public key bundle');
+  const publicKeys = validatePublicKeys(obj.alg, obj.publicKeys);
+  const kid = await computeKid(obj.alg, publicKeys);
+  if (obj.kid !== kid) throw new Error('Key id does not match key material');
+  await addTrustedKey({ alg: obj.alg, kid, publicKeys, label: String(label || 'Imported issuer').slice(0, 80), added: new Date().toISOString() });
+  return { kid, fingerprint: formatFingerprint(kid) };
+}
+
+function validatePublicKeys(alg, publicKeys) {
+  const spec = ALGORITHMS[alg];
+  if (!spec) throw new Error('Unsupported algorithm');
+  if (!publicKeys || typeof publicKeys !== 'object') throw new Error('Missing public key');
+  const keys = Object.keys(publicKeys);
+  if (keys.length !== spec.parts.length || !spec.parts.every((p) => keys.includes(p))) {
+    throw new Error('Public key parts do not match algorithm');
+  }
+  const out = {};
+  for (const p of spec.parts) {
+    if (b64urlDecode(publicKeys[p]).length !== PART_SIZES[p].pk) throw new Error(`Malformed ${p} public key`);
+    out[p] = publicKeys[p];
+  }
+  return out;
+}
+
+// ---------------------------------------------------------------- sign / verify
+
+/** Sign a document payload with the stored issuer key; returns envelope + token. */
+export async function signDocument(payload) {
+  const rec = await dbGet('issuer');
+  if (!rec) throw new Error('Generate an issuer key first');
+  const message = signingInput(rec.alg, rec.kid, payload);
+  const signatures = {};
+  for (const part of ALGORITHMS[rec.alg].parts) {
+    if (part === 'ed25519') {
+      signatures[part] = b64urlEncode(new Uint8Array(await crypto.subtle.sign(ED25519, rec.privateKeys[part], message)));
+    } else if (part === 'p256') {
+      signatures[part] = b64urlEncode(new Uint8Array(await crypto.subtle.sign(P256_SIGN, rec.privateKeys[part], message)));
+    } else if (part === 'mldsa65') {
+      const { secretKey } = ml_dsa65.keygen(rec.privateKeys[part]);
+      try {
+        signatures[part] = b64urlEncode(ml_dsa65.sign(message, secretKey));
+      } finally {
+        secretKey.fill(0);
+      }
+    }
+  }
+  const envelope = { format: FORMAT, version: VERSION, alg: rec.alg, kid: rec.kid, publicKeys: rec.publicKeys, payload, signatures };
+  return { envelope, token: encodeToken(envelope) };
+}
+
+export function encodeToken(envelope) {
+  return TOKEN_PREFIX + b64urlEncode(enc.encode(JSON.stringify(envelope)));
+}
+
+/** Accepts either a DG1. token or the raw JSON envelope. */
+export function decodeToken(input) {
+  const text = String(input || '').trim();
+  if (!text) throw new Error('Nothing to verify');
+  if (text.length > MAX_INPUT_BYTES * 2) throw new Error('Input too large');
+  let json;
+  if (text.startsWith(TOKEN_PREFIX)) {
+    try { json = dec.decode(b64urlDecode(text.slice(TOKEN_PREFIX.length).replace(/\s+/g, ''))); }
+    catch { throw new Error('Token is corrupted (bad encoding)'); }
+  } else if (text.startsWith('{')) {
+    json = text;
+  } else {
+    throw new Error('Unrecognised format: expected a DG1. token or JSON');
+  }
+  try { return JSON.parse(json); } catch { throw new Error('Token is corrupted (bad JSON)'); }
+}
+
+async function verifyPart(part, publicKeyB64, sigB64, message) {
+  const pk = b64urlDecode(publicKeyB64);
+  const sig = b64urlDecode(sigB64);
+  if (sig.length !== PART_SIZES[part].sig) return false;
+  if (part === 'ed25519') {
+    const key = await crypto.subtle.importKey('raw', pk, ED25519, false, ['verify']);
+    return crypto.subtle.verify(ED25519, key, sig, message);
+  }
+  if (part === 'p256') {
+    const key = await crypto.subtle.importKey('raw', pk, P256_GEN, false, ['verify']);
+    return crypto.subtle.verify(P256_SIGN, key, sig, message);
+  }
+  if (part === 'mldsa65') return ml_dsa65.verify(sig, message, pk);
+  return false;
+}
+
+/**
+ * Verify a token or envelope. Never throws for bad input; returns
+ * { status: 'trusted' | 'untrusted' | 'invalid', ... } plus any
+ * document-level warnings (expired voucher, totals mismatch).
+ */
+export async function verifyDocument(input) {
+  const result = { status: 'invalid', checks: [], warnings: [], envelope: null, payload: null };
+  const check = (ok, label) => { result.checks.push({ ok, label }); return ok; };
+  try {
+    const env = decodeToken(input);
+    result.envelope = env;
+    if (!check(env && env.format === FORMAT && env.version === VERSION, 'Recognised Daily Grind document format')) return result;
+    if (!check(Object.hasOwn(ALGORITHMS, env.alg), `Supported algorithm (${String(env.alg).slice(0, 40)})`)) return result;
+    if (env.alg.includes('Ed25519') && !(await isEd25519Supported())) {
+      check(false, 'This browser does not support Ed25519 verification');
+      return result;
+    }
+
+    let publicKeys;
+    try { publicKeys = validatePublicKeys(env.alg, env.publicKeys); check(true, 'Public key well-formed'); }
+    catch (e) { check(false, e.message); return result; }
+
+    const kid = await computeKid(env.alg, publicKeys);
+    if (!check(env.kid === kid, 'Key id matches embedded public key')) return result;
+
+    const parts = ALGORITHMS[env.alg].parts;
+    const sigs = env.signatures;
+    if (!check(sigs && typeof sigs === 'object' && Object.keys(sigs).length === parts.length && parts.every((p) => typeof sigs[p] === 'string'),
+      'All required signatures present')) return result;
+
+    let message;
+    try { canonicalize(env.payload); message = signingInput(env.alg, kid, env.payload); }
+    catch (e) { check(false, 'Payload is not canonical: ' + e.message); return result; }
+
+    let allOk = true;
+    for (const p of parts) {
+      let ok = false;
+      try { ok = await verifyPart(p, publicKeys[p], sigs[p], message); } catch { ok = false; }
+      check(ok, `${p === 'mldsa65' ? 'ML-DSA-65' : p === 'p256' ? 'ECDSA P-256' : 'Ed25519'} signature valid`);
+      allOk = allOk && ok;
+    }
+    if (!allOk) return result;
+
+    result.payload = env.payload;
+    result.kid = kid;
+    result.fingerprint = formatFingerprint(kid);
+    const trusted = (await getTrustedKeys()).find((k) => k.kid === kid);
+    if (trusted) {
+      result.status = 'trusted';
+      result.issuerLabel = trusted.label;
+      check(true, `Signed by trusted issuer: ${trusted.label}`);
+    } else {
+      result.status = 'untrusted';
+      check(false, 'Signer key is not in your trusted issuers list (integrity OK, authenticity unknown)');
+    }
+    result.warnings.push(...documentWarnings(env.payload));
+  } catch (e) {
+    check(false, e.message || 'Verification failed');
+  }
+  return result;
+}
+
+/** Business-level sanity checks on an authentic payload. */
+function documentWarnings(p) {
+  const w = [];
+  if (p?.type === 'receipt' && Array.isArray(p.items)) {
+    const sum = p.items.reduce((n, it) => n + (it.unitCents * it.qty || 0), 0);
+    if (sum !== p.subtotalCents) w.push('Line items do not add up to the subtotal.');
+    if (p.subtotalCents + (p.taxCents || 0) !== p.totalCents) w.push('Subtotal plus tax does not equal the total.');
+  }
+  if (p?.type === 'voucher') {
+    const now = Date.now();
+    if (p.expiresAt && Date.parse(p.expiresAt) < now) w.push('This voucher has expired.');
+    if (p.issuedAt && Date.parse(p.issuedAt) > now + 5 * 60 * 1000) w.push('Voucher issue date is in the future.');
+  }
