+    /* Seasonal Favorites carousel */
+    .seasonal-carousel {
+      max-width: 520px;
+      margin: 20px auto 0;
+    }
+
+    /* Without JavaScript every card stays visible, stacked */
+    .seasonal-stage {
+      display: grid;
+      gap: 20px;
+      /* Clips the sliding cards; also clips scoped view transitions automatically */
+      overflow: hidden;
+      border-radius: 8px;
+      padding: 4px;
+    }
+
+    .seasonal-slide img {
+      display: block;
+      width: 100%;
+      height: auto;
+      aspect-ratio: 8 / 5;
+      object-fit: cover;
+      border-radius: 6px;
+      margin-bottom: 15px;
+    }
+
+    .seasonal-slide[hidden] {
+      display: none;
+    }
+
+    /* Only the visible card is captured, so the old/new snapshots pair up */
+    .seasonal-slide:not([hidden]) {
+      view-transition-name: seasonal-card;
+    }
+
+    .seasonal-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      gap: 1rem;
+      margin-top: 16px;
+    }
+
+    .seasonal-controls[hidden] {
+      display: none;
+    }
+
+    .carousel-btn {
+      font: inherit;
+      background: white;
+      color: var(--primary);
+      border: 2px solid var(--primary);
+      border-radius: 5px;
+      padding: 8px 16px;
+      min-height: 44px;
+      cursor: pointer;
+      touch-action: manipulation;
+      transition: background-color 0.2s, color 0.2s;
+    }
+
+    .carousel-btn:hover {
+      background: var(--primary);
+      color: white;
+    }
+
+    .carousel-btn:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .seasonal-counter {
+      font-weight: bold;
+      color: var(--primary);
+    }
+
+    .visually-hidden {
+      position: absolute;
+      width: 1px;
+      height: 1px;
+      margin: -1px;
+      padding: 0;
+      overflow: hidden;
+      clip-path: inset(50%);
+      white-space: nowrap;
+      border: 0;
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); opacity: 0; }
