+        });
+        status.textContent = (index + 1) + ' / ' + slides.length;
+      }
+
+      function finishRunning() {
+        running.forEach(function (a) { a.finish(); });
+        running = [];
+      }
+
+      // dir: 1 = next (enter from right), -1 = previous (enter from left)
+      function go(dir) {
+        if (slides.length < 2) return;
