+import React, { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStory {
+  id: string;
+  title: string;
+  href: string;
+  date: string;
+}
+
+interface Props {
+  stories: TopStory[];
+}
+
+type Direction = 'next' | 'prev';
+
+interface CarouselState {
+  index: number;
+  direction: Direction;
+  outgoing: number | null;
+  // Incremented on every change so the incoming slide remounts and replays its animation.
+  key: number;
+}
+
+function Story({ story }: { story: TopStory }) {
+  return (
+    <>
+      <a href={story.href}>
+        <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">{story.title}</h3>
+      </a>
+      <span className="text-xs text-gray-500">{story.date}</span>
+    </>
+  );
+}
+
+export default function TopStoriesCarousel({ stories }: Props) {
+  const [state, setState] = useState<CarouselState>({ index: 0, direction: 'next', outgoing: null, key: 0 });
+  const count = stories.length;
+
+  if (count === 0) return null;
+
+  const go = (direction: Direction) => {
+    setState((s) => ({
+      index: (s.index + (direction === 'next' ? 1 : -1) + count) % count,
+      direction,
+      outgoing: s.index,
+      key: s.key + 1,
+    }));
+  };
+
+  const current = stories[state.index];
+  const animated = state.key > 0;
+  const inClass = animated ? (state.direction === 'next' ? 'story-slide-in-right' : 'story-slide-in-left') : '';
+  const outClass = state.direction === 'next' ? 'story-slide-out-left' : 'story-slide-out-right';
+
+  const buttonClass =
+    'shrink-0 p-1.5 rounded-full border border-gray-300 text-gray-700 hover:text-amber-400 hover:border-amber-400 focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 disabled:opacity-40 disabled:cursor-not-allowed';
