+        else if (e.key === 'ArrowLeft') go('prev');
+      }}
+    >
+      <button type="button" className={buttonClass} onClick={() => go('prev')} disabled={count < 2} aria-label="Previous story">
+        <ChevronLeftIcon className="h-5 w-5" />
+      </button>
