+      <span className="hidden sm:inline text-xs text-gray-500 tabular-nums" aria-hidden="true">
+        {state.index + 1} / {count}
+      </span>
+
+      <button type="button" className={buttonClass} onClick={() => go('next')} disabled={count < 2} aria-label="Next story">
+        <ChevronRightIcon className="h-5 w-5" />
+      </button>
+    </section>
+  );
+}
