+@keyframes story-in-from-left  { from { transform: translateX(-100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
+@keyframes story-out-to-left   { from { transform: translateX(0); opacity: 1; } to { transform: translateX(-100%); opacity: 0; } }
+@keyframes story-out-to-right  { from { transform: translateX(0); opacity: 1; } to { transform: translateX(100%); opacity: 0; } }
