+.story-slide-out-right { animation: story-out-to-right 350ms ease-out both; }
+
+@media (prefers-reduced-motion: reduce) {
+  .story-slide-in-right, .story-slide-in-left { animation: none; }
+  .story-slide-out-left, .story-slide-out-right { display: none; }
