+  <script>
+    (() => {
+      /* ---------- Cart logic ---------- */
+      const form = document.getElementById('quick-order-body');
+      const drinkSelect = document.getElementById('drink-select');
+      const photo = document.getElementById('drink-photo');
+      const qtyOut = document.getElementById('qty');
+      const addBtn = document.getElementById('add-to-cart');
+      const cartList = document.getElementById('cart-list');
+      const cartTotal = document.getElementById('cart-total');
+      const cartCount = document.getElementById('cart-count');
+      const checkoutBtn = document.getElementById('checkout');
+      const status = document.getElementById('quick-order-status');
+      const money = (n) => `$${n.toFixed(2)}`;
+      let qty = 1;
+      let cart = [];
+      try { cart = JSON.parse(localStorage.getItem('dg-cart')) || []; } catch { cart = []; }
+
+      function currentItem() {
+        const opt = drinkSelect.selectedOptions[0];
+        const sizeInput = form.querySelector('input[name="size"]:checked');
+        const extraShot = form.extraShot.checked;
+        const unit = parseFloat(opt.dataset.price) + parseFloat(sizeInput.dataset.extra) + (extraShot ? 0.75 : 0);
+        const name = `${sizeInput.value[0].toUpperCase()}${sizeInput.value.slice(1)} ${opt.textContent.split(' — ')[0]}${extraShot ? ' + shot' : ''}`;
+        return { key: `${opt.value}|${sizeInput.value}|${extraShot}`, name, unit, qty };
+      }
+
+      function updatePreview() {
+        const item = currentItem();
+        addBtn.textContent = `Add to cart — ${money(item.unit * item.qty)}`;
+        qtyOut.textContent = qty;
+      }
+
+      function renderCart() {
+        cartList.replaceChildren();
+        if (!cart.length) {
+          const li = document.createElement('li');
+          li.className = 'cart-empty';
+          li.textContent = 'Your cart is empty.';
+          cartList.append(li);
+        }
+        cart.forEach((item, i) => {
+          const li = document.createElement('li');
+          const name = document.createElement('span');
+          name.className = 'name';
+          name.textContent = `${item.qty}× ${item.name}`;
+          const price = document.createElement('span');
+          price.textContent = money(item.unit * item.qty);
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'remove';
+          remove.textContent = '✕';
+          remove.setAttribute('aria-label', `Remove ${item.name}`);
+          remove.addEventListener('click', () => {
+            cart.splice(i, 1);
+            status.textContent = `Removed ${item.name}.`;
+            renderCart();
+          });
+          li.append(name, price, remove);
+          cartList.append(li);
+        });
+        const count = cart.reduce((n, it) => n + it.qty, 0);
+        const total = cart.reduce((n, it) => n + it.qty * it.unit, 0);
+        cartTotal.textContent = money(total);
+        cartCount.textContent = count;
+        cartCount.setAttribute('aria-label', `${count} item${count === 1 ? '' : 's'} in cart`);
