+      drinkSelect.addEventListener('change', () => {
+        photo.src = drinkSelect.selectedOptions[0].dataset.img;
+        updatePreview();
+      });
+      form.addEventListener('change', updatePreview);
+      document.getElementById('qty-dec').addEventListener('click', () => { qty = Math.max(1, qty - 1); updatePreview(); });
+      document.getElementById('qty-inc').addEventListener('click', () => { qty = Math.min(20, qty + 1); updatePreview(); });
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const item = currentItem();
+        const existing = cart.find((it) => it.key === item.key);
+        if (existing) existing.qty += item.qty; else cart.push(item);
+        status.textContent = `Added ${item.qty}× ${item.name}.`;
+        qty = 1;
+        updatePreview();
+        renderCart();
+      });
+
+      checkoutBtn.addEventListener('click', () => {
+        const count = cart.reduce((n, it) => n + it.qty, 0);
+        status.textContent = `Order placed! ${count} item${count === 1 ? '' : 's'} will be ready for pickup in ~10 min.`;
+        cart = [];
+        renderCart();
+      });
+
+      updatePreview();
+      renderCart();
+
+      /* ---------- Draggable panel ---------- */
+      const panel = document.querySelector('[data-draggable]');
+      const handle = panel.querySelector('[data-drag-handle]');
+      const toggle = document.getElementById('quick-order-toggle');
+      const announcer = document.getElementById('drag-announcer');
+      const MARGIN = 12;
+      const STEP = 15;
+      let offsetX = 0, offsetY = 0, startX = 0, startY = 0, announceTimer;
+
+      handle.hidden = false;
+      document.getElementById('move-options').hidden = false;
+      panel.classList.add('is-draggable');
+
+      function announce(msg) {
+        announcer.textContent = `Quick order panel ${msg}`;
+        clearTimeout(announceTimer);
+        announceTimer = setTimeout(() => { announcer.textContent = ''; }, 1000);
+      }
+
+      function moveTo(left, top, save = true) {
+        const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
+        const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);
+        const x = Math.max(0, Math.min(left, maxLeft));
+        const y = Math.max(0, Math.min(top, maxTop));
+        panel.style.left = `${x}px`;
+        panel.style.top = `${y}px`;
+        panel.style.right = 'auto';
+        panel.style.bottom = 'auto';
+        if (save) localStorage.setItem('dg-quick-order-pos', JSON.stringify({ x, y }));
+      }
+
+      function reclamp() {
+        if (!panel.style.left) return;
+        const rect = panel.getBoundingClientRect();
+        moveTo(rect.left, rect.top, false);
+      }
+
+      try {
+        const saved = JSON.parse(localStorage.getItem('dg-quick-order-pos'));
+        if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) moveTo(saved.x, saved.y, false);
+      } catch { /* ignore bad saved state */ }
+
+      handle.addEventListener('pointerdown', (event) => {
+        if (event.button !== 0) return;
+        const rect = panel.getBoundingClientRect();
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        startX = event.clientX;
+        startY = event.clientY;
+        handle.setPointerCapture(event.pointerId);
+      });
