+          if (e.target.closest('button, a, input, select, textarea')) return;
+          if (e.pointerType === 'mouse' && e.button !== 0) return;
+          const rect = panel.getBoundingClientRect();
+          offsetX = e.clientX - rect.left;
+          offsetY = e.clientY - rect.top;
+          dragging = true;
+          pointerId = e.pointerId;
+          handle.setPointerCapture(e.pointerId);
+          panel.classList.add('is-dragging');
+          e.preventDefault();
+        });
+
+        handle.addEventListener('pointermove', function (e) {
+          if (!dragging || e.pointerId !== pointerId) return;
+          setPosition(e.clientX - offsetX, e.clientY - offsetY);
+        });
+
+        handle.addEventListener('pointerup', endDrag);
+        handle.addEventListener('pointercancel', endDrag);
+        handle.addEventListener('lostpointercapture', endDrag);
+
+        // Keyboard support: arrow keys nudge the panel when the handle is focused.
+        handle.addEventListener('keydown', function (e) {
+          if (e.target !== handle) return;
+          const step = e.shiftKey ? 50 : 10;
+          const moves = {
+            ArrowLeft: [-step, 0], ArrowRight: [step, 0],
+            ArrowUp: [0, -step], ArrowDown: [0, step]
+          };
+          const m = moves[e.key];
+          if (!m) return;
+          e.preventDefault();
+          const rect = panel.getBoundingClientRect();
+          setPosition(rect.left + m[0], rect.top + m[1]);
+          savePosition();
+        });
+
+        // Keep the panel on-screen when the viewport or panel size changes.
+        function reclamp() {
+          if (panel.style.left) {
+            const rect = panel.getBoundingClientRect();
+            setPosition(rect.left, rect.top);
+          }
+        }
+        window.addEventListener('resize', reclamp);
+        if ('ResizeObserver' in window) new ResizeObserver(reclamp).observe(panel);
+
+        restorePosition();
+        panel._reclamp = reclamp;
+      }
+
+      document.querySelectorAll('[data-draggable]').forEach(initDraggable);
+
+      /* ---------- Quick-order controls ---------- */
+      const panel = document.getElementById('quick-order');
+      const form = document.getElementById('qo-form');
+      const drink = document.getElementById('qo-drink');
+      const qtyOut = document.getElementById('qo-qty');
+      const addBtn = document.getElementById('qo-add');
+      const shot = document.getElementById('qo-shot');
+      const oat = document.getElementById('qo-oat');
+      const cartEl = document.getElementById('qo-cart');
+      const totalEl = document.getElementById('qo-total');
+      const countEl = document.getElementById('qo-count');
+      const checkout = document.getElementById('qo-checkout');
+      const statusEl = document.getElementById('qo-status');
+      const toggle = document.getElementById('qo-toggle');
+
+      const CART_KEY = 'dailyGrind.quickOrder.cart';
+      const COLLAPSE_KEY = 'dailyGrind.quickOrder.collapsed';
+      const MAX_QTY = 10;
+      const money = (n) => '$' + n.toFixed(2);
+
+      let qty = 1;
+      let cart = [];
+      try {
+        const saved = JSON.parse(localStorage.getItem(CART_KEY));
+        if (Array.isArray(saved)) cart = saved.filter(i => i && typeof i.name === 'string' && Number.isFinite(i.unit) && Number.isFinite(i.qty));
+      } catch (e) { /* ignore */ }
+
+      function unitPrice() {
+        const base = parseFloat(drink.selectedOptions[0].dataset.price);
+        const size = form.querySelector('input[name="size"]:checked');
+        let price = base + parseFloat(size ? size.dataset.delta : 0);
+        if (shot.checked) price += parseFloat(shot.dataset.price);
+        if (oat.checked) price += parseFloat(oat.dataset.price);
+        return Math.max(price, 0);
+      }
+
+      function updateAddButton() {
+        qtyOut.textContent = qty;
+        addBtn.textContent = 'Add to Cart — ' + money(unitPrice() * qty);
+      }
+
+      function saveCart() {
+        try { localStorage.setItem(CART_KEY, JSON.stringify(cart)); } catch (e) { /* ignore */ }
+      }
+
+      function renderCart() {
+        cartEl.innerHTML = '';
+        if (!cart.length) {
+          const li = document.createElement('li');
+          li.className = 'qo-empty';
+          li.textContent = 'Your cart is empty';
+          cartEl.appendChild(li);
+        }
+        cart.forEach(function (item, idx) {
+          const li = document.createElement('li');
+          const label = document.createElement('span');
+          label.textContent = item.qty + '× ' + item.size + ' ' + item.name + (item.extras ? ' (' + item.extras + ')' : '');
+          const right = document.createElement('span');
+          right.textContent = money(item.unit * item.qty) + ' ';
+          const rm = document.createElement('button');
+          rm.type = 'button';
+          rm.className = 'qo-remove';
+          rm.setAttribute('aria-label', 'Remove ' + item.name);
+          rm.innerHTML = '&times;';
+          rm.addEventListener('click', function () {
+            cart.splice(idx, 1);
+            saveCart();
+            renderCart();
+            statusEl.textContent = 'Removed ' + item.name + '.';
+          });
+          right.appendChild(rm);
+          li.append(label, right);
+          cartEl.appendChild(li);
+        });
+        const count = cart.reduce((s, i) => s + i.qty, 0);
+        const total = cart.reduce((s, i) => s + i.unit * i.qty, 0);
+        countEl.textContent = count;
+        totalEl.textContent = money(total);
+        checkout.setAttribute('aria-disabled', count ? 'false' : 'true');
+        if (count) checkout.removeAttribute('tabindex'); else checkout.setAttribute('tabindex', '-1');
+      }
+
+      document.getElementById('qo-dec').addEventListener('click', function () {
+        qty = Math.max(1, qty - 1);
+        updateAddButton();
+      });
+      document.getElementById('qo-inc').addEventListener('click', function () {
+        qty = Math.min(MAX_QTY, qty + 1);
+        updateAddButton();
+      });
+      form.addEventListener('change', updateAddButton);
+
+      form.addEventListener('submit', function (e) {
+        e.preventDefault();
+        const name = drink.selectedOptions[0].textContent.split(' — ')[0];
+        const size = form.querySelector('input[name="size"]:checked').value;
+        const extras = [shot.checked && 'extra shot', oat.checked && 'oat milk'].filter(Boolean).join(', ');
+        const unit = Math.round(unitPrice() * 100) / 100;
+        const existing = cart.find(i => i.name === name && i.size === size && i.extras === extras);
+        if (existing) existing.qty = Math.min(MAX_QTY * 5, existing.qty + qty);
+        else cart.push({ name, size, extras, unit, qty });
+        saveCart();
+        renderCart();
+        statusEl.textContent = 'Added ' + qty + '× ' + name + ' to your cart.';
+        qty = 1;
+        updateAddButton();
+      });
+
+      function setCollapsed(collapsed) {
+        panel.classList.toggle('is-collapsed', collapsed);
+        toggle.setAttribute('aria-expanded', String(!collapsed));
+        toggle.innerHTML = collapsed ? '+' : '&minus;';
+        toggle.title = collapsed ? 'Expand' : 'Minimize';
+        try { localStorage.setItem(COLLAPSE_KEY, collapsed ? '1' : '0'); } catch (e) { /* ignore */ }
+        if (panel._reclamp) panel._reclamp();
+      }
+      toggle.addEventListener('click', function () {
+        setCollapsed(!panel.classList.contains('is-collapsed'));
+      });
+      try { if (localStorage.getItem(COLLAPSE_KEY) === '1') setCollapsed(true); } catch (e) { /* ignore */ }
+
+      updateAddButton();
+      renderCart();
+    })();
+  </script>
+
 </body>

 </html>

