+    let lastWidth = 0;
+
+    // Show links inline only when the whole row actually fits — no hard-coded breakpoint.
+    function updateLayout() {
+      const width = inner.clientWidth;
+      const wasWide = header.classList.contains("is-wide");
+      // While collapsed, only re-measure when the header grows (avoids layout thrash).
+      if (!wasWide && width <= lastWidth) {
+        lastWidth = width;
