+      function updateSummary() {
+        const picked = [...selected.children].map((li) => byId.get(li.dataset.id));
+        const total = picked.reduce((sum, b) => sum + b.price, 0);
+        document.getElementById('bean-total').textContent = `$${total.toFixed(2)}`;
+        document.getElementById('available-count').textContent = `${available.children.length} left`;
+        document.getElementById('selected-count').textContent = `${picked.length} picked`;
+      }
