+        // item's group animates simultaneously. The rest of the page — nav,
+        // links, other sections — stays fully interactive meanwhile.
+        if (typeof board.startViewTransition === 'function') {
+          board.startViewTransition(update);
+          return;
+        }
+        flip(update);
+      }
+
+      board.addEventListener('click', (e) => {
+        const btn = e.target.closest('.bean-toggle');
+        if (!btn) return;
+        const li = btn.closest('.bean-item');
+        const wasSelected = li.parentElement === selected;
+        const name = byId.get(li.dataset.id).name;
+        transition(() => moveItem(li));
+        // Keep keyboard focus on the item that moved.
+        btn.focus({ preventScroll: true });
+        status.textContent = `${name} ${wasSelected ? 'removed from' : 'added to'} your selection.`;
+      });
+
+      for (const bean of BEANS) {
+        const li = createItem(bean);
+        available.appendChild(li);
+        syncButton(li);
+      }
+      updateSummary();
+    })();
+  </script>
+
