new file mode 100644
index 0000000..5b9e0c4
--- /dev/null
+++ b/src/utils/overlays.ts
@@ -0,0 +1,47 @@
+// Shared helpers for native overlays (<dialog> and [popover]).
+
+// Load the Popover API polyfill only in browsers that lack native support.
+if (typeof window !== 'undefined' && !Object.hasOwn(HTMLElement.prototype, 'popover')) {
+    import('@oddbird/popover-polyfill');
+}
+
+/** `:popover-open` throws in browsers without it; the polyfill uses a `.\:popover-open` class instead. */
+export function isPopoverOpen(element: Element): boolean {
+    try {
+        return element.matches(':popover-open');
+    } catch {
+        return element.classList.contains(':popover-open');
+    }
+}
+
+/**
+ * Light-dismiss fallback for `<dialog closedby="any">` in browsers without `closedby`
+ * support. Returns a cleanup function.
+ */
+export function addLightDismissFallback(dialog: HTMLDialogElement): () => void {
+    if ('closedBy' in HTMLDialogElement.prototype) return () => {};
+
+    // Test the pointer position, not event.target: the <dialog> is also the target for
+    // clicks on its own padding.
+    const isOutside = (event: PointerEvent) => {
+        const rect = dialog.getBoundingClientRect();
+        return event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom;
+    };
+
+    let pressedOutside = false;
+    const onPointerDown = (event: PointerEvent) => {
+        pressedOutside = isOutside(event);
+    };
+    // Require press and release outside, so a text-selection drag ending on the backdrop doesn't dismiss.
+    const onPointerUp = (event: PointerEvent) => {
+        if (pressedOutside && isOutside(event)) dialog.close();
+        pressedOutside = false;
+    };
+
+    dialog.addEventListener('pointerdown', onPointerDown);
+    dialog.addEventListener('pointerup', onPointerUp);
+    return () => {
+        dialog.removeEventListener('pointerdown', onPointerDown);
+        dialog.removeEventListener('pointerup', onPointerUp);
+    };
+}

