diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..2892ac3
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,80 @@
+import React, { useEffect, useId, useRef } from 'react';
+
+interface Props {
+  /** Accessible name of the dialog, rendered as its heading. */
+  title: string;
+  /** Visually hide the heading while keeping it as the dialog's accessible name. */
+  hideTitle?: boolean;
+  /** Element to focus once the dialog opens (defaults to the browser's dialog focusing steps). */
+  initialFocusRef?: React.RefObject<HTMLElement | null>;
+  onClose: () => void;
+  children: React.ReactNode;
+}
+
+/**
+ * Thin wrapper around the native modal <dialog>.
+ *
+ * `showModal()` gives us top-layer rendering, an inert background, a focus
+ * trap, Esc-to-close and a ::backdrop for free. Focus returns to the element
+ * that opened the dialog when it closes.
+ */
+export default function Modal({ title, hideTitle = false, initialFocusRef, onClose, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+  const onCloseRef = useRef(onClose);
+  onCloseRef.current = onClose;
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
+
+    if (!dialog.open) dialog.showModal();
+    initialFocusRef?.current?.focus();
+
+    const handleClose = () => onCloseRef.current();
+    dialog.addEventListener('close', handleClose);
+
+    return () => {
+      dialog.removeEventListener('close', handleClose);
+      if (dialog.open) dialog.close();
+      if (opener?.isConnected && document.activeElement !== opener) opener.focus();
+    };
+  }, [initialFocusRef]);
+
+  const close = () => dialogRef.current?.close();
+
+  // Light dismiss: a click whose target is the <dialog> itself landed on the
+  // backdrop, because the content wrapper fills the dialog box.
+  const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+    if (event.target === event.currentTarget) close();
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      onClick={handleClick}
+      // Native light dismiss where supported (`closedby` attribute).
+      {...{ closedby: 'any' }}
+      className="w-full max-w-[min(42rem,calc(100%-2rem))] mx-auto mt-[15vh] mb-auto p-0 border-0 bg-white shadow-xl overflow-visible backdrop:bg-white/30 backdrop:backdrop-blur-sm"
+    >
+      <div className="relative">
+        <button
+          type="button"
+          onClick={close}
+          aria-label="Close"
+          className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10"
+        >
+          <svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+          </svg>
+        </button>
+        <h2 id={titleId} className={hideTitle ? 'sr-only' : 'px-4 pt-4 text-lg font-semibold text-gray-800'}>
+          {title}
+        </h2>
+        {children}
+      </div>
+    </dialog>
+  );
+}
