+  <!--
+    Script performance monitor.
+    Uses the Long Animation Frames (LoAF) API to detect frames delayed > 50ms
+    and attribute the delay to the scripts that ran during them. Occurrences are
+    persisted to localStorage so past slow-script incidents survive reloads.
+
+    Console API:
+      scriptPerf.history()   -> array of recorded long frames (newest last)
+      scriptPerf.summary()   -> scripts ranked by total blocking time
+      scriptPerf.report()    -> console.table of summary()
+      scriptPerf.clear()     -> wipe recorded history
+    Add ?perf to the URL to show an on-page panel.
+  -->
+  <script>
+    (() => {
+      const STORAGE_KEY = 'scriptPerf:history';
+      const MAX_RECORDS = 200;       // cap persisted history
+      const SLOW_SCRIPT_MS = 20;     // per-script attribution threshold to reduce noise
+
+      const supported = typeof PerformanceObserver !== 'undefined' &&
+        PerformanceObserver.supportedEntryTypes?.includes('long-animation-frame');
+
+      const load = () => {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
+        catch { return []; }
+      };
+      let history = load();
+      const save = () => {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(history.slice(-MAX_RECORDS))); }
+        catch { /* storage full or disabled */ }
+      };
+
+      const round = n => Math.round(n * 10) / 10;
+
+      // Summarize the (very detailed) LoAF entry into what matters for diagnosis.
+      const toRecord = entry => ({
+        timestamp: Date.now() - (performance.now() - entry.startTime),
+        page: location.pathname,
+        duration: round(entry.duration),
+        blockingDuration: round(entry.blockingDuration ?? 0),
+        renderDuration: round(entry.renderStart ? entry.startTime + entry.duration - entry.renderStart : 0),
+        scripts: entry.scripts
+          .filter(s => s.duration >= SLOW_SCRIPT_MS)
+          .map(s => ({
+            sourceURL: s.sourceURL || '(inline/unknown)',
+            sourceFunctionName: s.sourceFunctionName || '',
+            sourceCharPosition: s.sourceCharPosition,
+            invoker: s.invoker,
+            invokerType: s.invokerType,
+            duration: round(s.duration),
+            forcedStyleAndLayoutDuration: round(s.forcedStyleAndLayoutDuration ?? 0),
+          })),
+      });
+
+      const summary = () => {
+        const bySource = new Map();
+        for (const frame of history) {
+          for (const s of frame.scripts) {
+            const key = s.sourceURL;
+            const agg = bySource.get(key) ?? { sourceURL: key, count: 0, totalDuration: 0, maxDuration: 0, lastSeen: 0 };
+            agg.count++;
+            agg.totalDuration = round(agg.totalDuration + s.duration);
+            agg.maxDuration = Math.max(agg.maxDuration, s.duration);
+            agg.lastSeen = Math.max(agg.lastSeen, frame.timestamp);
+            bySource.set(key, agg);
+          }
+        }
+        return [...bySource.values()]
+          .sort((a, b) => b.totalDuration - a.totalDuration)
+          .map(a => ({ ...a, lastSeen: new Date(a.lastSeen).toLocaleString() }));
+      };
+
+      let panel;
+      const renderPanel = () => {
+        if (!panel) return;
+        const rows = summary().slice(0, 10);
+        panel.querySelector('tbody').replaceChildren(...rows.map(r => {
+          const tr = document.createElement('tr');
+          for (const v of [r.sourceURL, r.count, r.totalDuration, r.maxDuration, r.lastSeen]) {
+            const td = document.createElement('td');
+            td.textContent = v;
+            tr.append(td);
+          }
+          return tr;
+        }));
+        panel.querySelector('[data-count]').textContent = history.length;
+      };
+
+      window.scriptPerf = {
+        supported,
+        history: () => structuredClone(history),
+        summary,
+        report: () => console.table(summary()),
+        clear: () => { history = []; save(); renderPanel(); },
+      };
+
+      if (!supported) return; // Chromium-only API; silently no-op elsewhere.
+
+      const observer = new PerformanceObserver(list => {
+        const records = list.getEntries().map(toRecord);
+        history.push(...records);
+        if (history.length > MAX_RECORDS) history = history.slice(-MAX_RECORDS);
+        save();
+        for (const r of records) {
+          if (r.scripts.length) {
+            console.warn(`[scriptPerf] ${r.duration}ms frame delayed by:`,
+              r.scripts.map(s => `${s.sourceURL} ${s.sourceFunctionName} (${s.duration}ms)`).join(', '));
+          }
+        }
+        renderPanel();
+      });
+      // buffered: true captures long frames that occurred before this observer was registered.
+      observer.observe({ type: 'long-animation-frame', buffered: true });
+
+      if (new URLSearchParams(location.search).has('perf')) {
+        panel = document.createElement('aside');
+        panel.setAttribute('aria-label', 'Script performance monitor');
+        panel.style.cssText = 'position:fixed;bottom:1rem;right:1rem;z-index:2000;max-width:min(640px,calc(100vw - 2rem));max-height:50vh;overflow:auto;background:#1e1e1e;color:#eee;font:12px/1.4 ui-monospace,monospace;padding:.75rem;border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,.4)';
+        panel.innerHTML = `
+          <div style="display:flex;justify-content:space-between;gap:1rem;margin-bottom:.5rem">
+            <strong>Slow scripts (<span data-count>0</span> long frames recorded)</strong>
+            <button type="button" style="font:inherit;cursor:pointer">Clear</button>
+          </div>
+          <table style="border-collapse:collapse;width:100%;text-align:left">
+            <thead><tr><th>Source</th><th>Count</th><th>Total ms</th><th>Max ms</th><th>Last seen</th></tr></thead>
+            <tbody></tbody>
+          </table>`;
+        panel.querySelector('button').addEventListener('click', window.scriptPerf.clear);
+        document.body.append(panel);
+        renderPanel();
+      }
+    })();
+  </script>
+
 </body>

