+    ctx.fillText('The Daily Grind Coffee Co. · Recyclable board', cssW / 2, cssH / 2);
+  }
+  return c;
+}
+
+/* ------------------------------------------------------------------ */
+/* Primary: WebGL 2 + HTML-in-Canvas                                    */
+/* ------------------------------------------------------------------ */
+
+const VERT = `#version 300 es
+in vec2 aPos;
+uniform mat4 uMvp;
+uniform mat4 uModel;
+out vec2 vUv;
+out vec3 vNormal;
+void main() {
+  // Unit quad spanning -0.5..0.5; texture row 0 is the top of the element.
+  vUv = vec2(aPos.x + 0.5, 0.5 - aPos.y);
+  vNormal = mat3(uModel) * vec3(0.0, 0.0, 1.0);
+  gl_Position = uMvp * vec4(aPos, 0.0, 1.0);
+}`;
+
+const FRAG = `#version 300 es
+precision mediump float;
+in vec2 vUv;
+in vec3 vNormal;
+uniform sampler2D uTex;
+uniform float uAmbient;
+out vec4 outColor;
+void main() {
+  float diffuse = max(dot(normalize(vNormal), normalize(vec3(0.35, 0.6, 1.0))), 0.0);
+  float light = uAmbient + (1.0 - uAmbient) * diffuse;
+  outColor = vec4(texture(uTex, vUv).rgb * light, 1.0);
+}`;
+
+function compile(gl, type, src) {
+  const shader = gl.createShader(type);
+  gl.shaderSource(shader, src);
+  gl.compileShader(shader);
+  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(shader));
+  return shader;
+}
+
+function perspective(fovY, aspect, near, far) {
+  const f = 1 / Math.tan(fovY / 2);
+  const nf = 1 / (near - far);
+  // Column-major, same layout as CSS matrix3d()/DOMMatrix.
+  return new DOMMatrix([
+    f / aspect, 0, 0, 0,
+    0, f, 0, 0,
+    0, 0, (far + near) * nf, -1,
+    0, 0, 2 * far * near * nf, 0,
+  ]);
+}
+
+// Maps the element's border box (CSS px) onto the canvas (CSS px) for a quad
+// spanning -0.5..0.5 in model space drawn with `mvp`.
+function computeCanvasTransform(canvas, element, mvp) {
+  const width = element.offsetWidth;
+  const height = element.offsetHeight;
+  const toGLModel = new DOMMatrix()
+    .scale(1 / width, -1 / height, 1 / height)
+    .translate(-width / 2, -height / 2);
+  const clipToCanvasViewport = new DOMMatrix()
+    .translate(canvas.clientWidth / 2, canvas.clientHeight / 2)
+    .scale(canvas.clientWidth / 2, -canvas.clientHeight / 2, canvas.clientHeight / 2);
+  return clipToCanvasViewport.multiply(mvp).multiply(toGLModel);
+}
+
+function getElementImageSize(canvas, element) {
+  let elementImage;
+  try {
+    elementImage = canvas.captureElementImage(element);
+  } catch {
+    canvas.requestPaint(); // No paint record yet: retry on the next paint event.
+    return null;
+  }
+  const width = Math.ceil(elementImage.width);
+  const height = Math.ceil(elementImage.height);
+  elementImage.close();
+  return width > 0 && height > 0 ? { width, height } : null;
+}
+
+function initWebGL() {
+  if (!('content' in HTMLCanvasElement.prototype)) return false;
+
+  const canvas = document.createElement('canvas');
+  canvas.className = 'box-canvas';
+  canvas.setAttribute('content', 'drawable');
+  canvas.setAttribute('aria-label', 'Interactive coffee box. The order form is on its front face.');
+  const gl = canvas.getContext('webgl2', { antialias: true, alpha: true, premultipliedAlpha: true });
+  if (!gl) return false;
+
+  let program;
+  try {
+    program = gl.createProgram();
+    gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERT));
+    gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAG));
+    gl.linkProgram(program);
+    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program));
+  } catch (err) {
+    console.warn('Coffee box: WebGL setup failed, using CSS fallback.', err);
+    return false;
+  }
+
+  // Move the real form into the canvas as a drawable child.
+  form.setAttribute('drawable', '');
+  canvas.append(form);
+  stage.append(canvas);
+
+  const loc = {
+    pos: gl.getAttribLocation(program, 'aPos'),
+    mvp: gl.getUniformLocation(program, 'uMvp'),
+    model: gl.getUniformLocation(program, 'uModel'),
+    tex: gl.getUniformLocation(program, 'uTex'),
+    ambient: gl.getUniformLocation(program, 'uAmbient'),
+  };
+
+  const vao = gl.createVertexArray();
+  gl.bindVertexArray(vao);
+  const quad = gl.createBuffer();
+  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
+  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-0.5, -0.5, 0.5, -0.5, -0.5, 0.5, 0.5, 0.5]), gl.STATIC_DRAW);
+  gl.enableVertexAttribArray(loc.pos);
+  gl.vertexAttribPointer(loc.pos, 2, gl.FLOAT, false, 0, 0);
+
+  const makeTexture = (source) => {
+    const tex = gl.createTexture();
+    gl.bindTexture(gl.TEXTURE_2D, tex);
+    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
+    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
+    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
+    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
+    if (source) gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
+    return tex;
+  };
+
+  const formW = form.offsetWidth || 360;
+  const formH = form.offsetHeight || 460;
+  const tex = {
+    form: makeTexture(null),
+    back: makeTexture(makePanel(formW, formH, 'back')),
+    side: makeTexture(makePanel(DEPTH_PX, formH, 'side')),
+    top: makeTexture(makePanel(formW, DEPTH_PX, 'top')),
+    bottom: makeTexture(makePanel(formW, DEPTH_PX, 'bottom')),
+  };
+  const formTexState = { width: 0, height: 0, ready: false };
