+  function uploadForm() {
+    const size = getElementImageSize(canvas, form);
+    if (!size) return;
+    gl.bindTexture(gl.TEXTURE_2D, tex.form);
+    if (formTexState.width !== size.width || formTexState.height !== size.height) {
+      // Reallocate only when the element size changes (reallocation clears the texture).
+      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, size.width, size.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
