+    if (!formTexState.ready || event.changedElements?.length) {
+      try {
+        uploadForm();
+      } catch (err) {
+        console.error('texElementSubImage2D copy failed:', err);
+      }
+    }
+    render();
+  };
+
+  function render() {
+    const w = form.offsetWidth / PX_PER_UNIT;
+    const h = form.offsetHeight / PX_PER_UNIT;
+    const d = DEPTH_PX / PX_PER_UNIT;
+    // Fit the box's diagonal footprint comfortably in the square canvas.
+    const extent = Math.max(h, Math.hypot(w, d)) / 0.78;
+    const camZ = extent / (2 * Math.tan(FOV / 2)) + d / 2;
+
+    gl.viewport(0, 0, canvas.width, canvas.height);
+    gl.clearColor(0, 0, 0, 0);
+    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+    gl.enable(gl.DEPTH_TEST);
+    gl.useProgram(program);
+    gl.bindVertexArray(vao);
+    gl.activeTexture(gl.TEXTURE0);
+    gl.uniform1i(loc.tex, 0);
+
+    const aspect = canvas.clientWidth / canvas.clientHeight || 1;
+    const viewProj = perspective(FOV, aspect, 0.1, 100).multiply(new DOMMatrix().translate(0, 0, -camZ));
+    const box = new DOMMatrix().rotate(motion.pitch, 0, 0).rotate(0, motion.yaw, 0);
+
+    const faces = [
+      { m: new DOMMatrix().translate(0, 0, d / 2).scale(w, h, 1), tex: formTexState.ready ? tex.form : tex.back, ambient: 0.85, front: true },
+      { m: new DOMMatrix().translate(0, 0, -d / 2).rotate(0, 180, 0).scale(w, h, 1), tex: tex.back, ambient: 0.45 },
+      { m: new DOMMatrix().translate(w / 2, 0, 0).rotate(0, 90, 0).scale(d, h, 1), tex: tex.side, ambient: 0.45 },
+      { m: new DOMMatrix().translate(-w / 2, 0, 0).rotate(0, -90, 0).scale(d, h, 1), tex: tex.side, ambient: 0.45 },
+      { m: new DOMMatrix().translate(0, h / 2, 0).rotate(-90, 0, 0).scale(w, d, 1), tex: tex.top, ambient: 0.45 },
+      { m: new DOMMatrix().translate(0, -h / 2, 0).rotate(90, 0, 0).scale(w, d, 1), tex: tex.bottom, ambient: 0.45 },
+    ];
+
+    let formMvp = null;
+    for (const face of faces) {
+      const model = box.multiply(face.m);
+      const mvp = viewProj.multiply(model);
+      if (face.front) formMvp = mvp;
+      gl.uniformMatrix4fv(loc.model, false, model.toFloat32Array());
+      gl.uniformMatrix4fv(loc.mvp, false, mvp.toFloat32Array());
+      gl.uniform1f(loc.ambient, face.ambient);
+      gl.bindTexture(gl.TEXTURE_2D, face.tex);
+      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
+    }
