+    // Keep the live form aligned with its pixels for hit testing, focus and a11y.
+    const visible = frontFaceVisible(box, d, camZ);
+    setFormHidden(!visible);
+    if (visible) {
+      canvas.updateElementGeometry(form, { canvasTransform: computeCanvasTransform(canvas, form, formMvp) });
+    } else {
+      canvas.clearElementGeometry(form);
+    }
+  }
+
+  setupInteraction(canvas);
+  stage.classList.add('is-3d');
+  modeHint.textContent = 'Drag the box sideways, or use the buttons, to rotate it.';
+  startLoop((now) => {
+    stepMotion(now);
+    canvas.requestPaint();
+  });
+  return true;
+}
+
+/* ------------------------------------------------------------------ */
+/* Fallback: CSS 3D transforms                                          */
+/* ------------------------------------------------------------------ */
+
+function initCSS3D() {
+  if (!CSS.supports('transform-style', 'preserve-3d')) {
+    modeHint.textContent = '';
