+  }
+
+  const scene = document.createElement('div');
+  scene.className = 'box3d-scene';
+  const box = document.createElement('div');
+  box.className = 'box3d';
+  box.innerHTML = `
+    <div class="box3d-face box3d-face--front"></div>
+    <div class="box3d-face box3d-face--back" aria-hidden="true">THE DAILY<br>GRIND<small>Ethically sourced · Locally roasted</small></div>
+    <div class="box3d-face box3d-face--right" aria-hidden="true">THE DAILY GRIND<small>FRESH ROAST BOX · 340 g BAGS</small></div>
+    <div class="box3d-face box3d-face--left" aria-hidden="true">THE DAILY GRIND<small>FRESH ROAST BOX · 340 g BAGS</small></div>
+    <div class="box3d-face box3d-face--top" aria-hidden="true">↑ THIS SIDE UP ↑<small>Open with care · smells amazing</small></div>
+    <div class="box3d-face box3d-face--bottom" aria-hidden="true"><small>The Daily Grind Coffee Co. · Recyclable board</small></div>`;
+  box.querySelector('.box3d-face--front').append(form);
+  scene.append(box);
+  stage.append(scene);
+
+  const sizeBox = () => {
+    box.style.setProperty('--w', `${form.offsetWidth}px`);
+    box.style.setProperty('--h', `${form.offsetHeight}px`);
+    box.style.setProperty('--d', `${DEPTH_PX}px`);
+  };
+  sizeBox();
+  new ResizeObserver(sizeBox).observe(form);
+
+  setupInteraction(stage);
+  stage.classList.add('is-3d');
+  modeHint.textContent = 'Drag the box sideways, or use the buttons, to rotate it.';
+  startLoop((now) => {
+    stepMotion(now);
+    // CSS's y axis points down, so pitch is negated to match the WebGL view.
+    box.style.transform = `rotateX(${-motion.pitch}deg) rotateY(${motion.yaw}deg)`;
+    const m = new DOMMatrix().rotate(motion.pitch, 0, 0).rotate(0, motion.yaw, 0);
+    setFormHidden(!frontFaceVisible(m, DEPTH_PX / PX_PER_UNIT, CSS_PERSPECTIVE_PX / PX_PER_UNIT));
+  });
+}
+
+if (!initWebGL()) initCSS3D();

