+      const OUTER = 110;  // px: radius where the reveal fades out
+
+      document.querySelectorAll('.product-card').forEach((card) => {
+        let hovered = false;
+        let focused = false;
+        let frame = 0;
+        let pending = null;
+
+        const setPos = (x, y) => {
+          card.style.setProperty('--mouse-x', `${x}px`);
+          card.style.setProperty('--mouse-y', `${y}px`);
+        };
+
+        const setSize = (inner, outer) => {
+          card.style.setProperty('--inner-size', `${inner}px`);
+          card.style.setProperty('--outer-size', `${outer}px`);
+        };
+
+        const update = () => {
+          if (hovered) {
+            setSize(INNER, OUTER);
+          } else if (focused) {
+            // Keyboard focus: reveal the whole card from its center
+            const { width, height } = card.getBoundingClientRect();
+            const radius = Math.hypot(width, height) / 2;
+            setPos(width / 2, height / 2);
+            setSize(radius, radius + 40);
+          } else {
+            setSize(0, 0);
+          }
+        };
+
+        const track = (event) => {
+          pending = event;
+          if (frame) return;
+          frame = requestAnimationFrame(() => {
+            frame = 0;
+            const rect = card.getBoundingClientRect();
+            setPos(pending.clientX - rect.left, pending.clientY - rect.top);
