+        params.set('sort', state.sort);
+        params.set('reverse', state.reverse ? '1' : '0');
+        params.set('group', state.group ? '1' : '0');
+        var query = params.toString();
+        var url = window.location.pathname + (query ? '?' + query : '') + window.location.hash;
+        if (url !== window.location.pathname + window.location.search + window.location.hash) {
+          window.history.replaceState(window.history.state, '', url);
+        }
+      }
+
+      function syncControls() {
+        categorySelect.value = state.category;
+        sortSelect.value = state.sort;
+        reverseToggle.setAttribute('aria-pressed', String(state.reverse));
+        groupToggle.setAttribute('aria-pressed', String(state.group));
+      }
+
+      function dispatchFilterChange(source) {
+        controls.dispatchEvent(new CustomEvent('daily-grind:filter-change', {
+          bubbles: true,
+          detail: Object.assign({}, state, { source: source })
+        }));
+      }
+
+      // Returns a NEW array; MENU is never sorted/reversed in place.
+      function getVisibleItems() {
+        var items = MENU.filter(function (item) {
+          return state.category === 'all' || item.category === state.category;
+        });
+        if (state.sort === 'price-asc') {
+          items.sort(function (a, b) { return a.price - b.price || a.featured - b.featured; });
+        } else if (state.sort === 'price-desc') {
+          items.sort(function (a, b) { return b.price - a.price || a.featured - b.featured; });
+        } else {
+          items.sort(function (a, b) { return a.featured - b.featured; });
+        }
+        if (state.reverse) items.reverse();
+        return items;
+      }
+
+      function renderCard(item) {
+        return el('article', { className: 'card menu-item', dataset: { id: item.id, category: item.category } }, [
+          el('span', { className: 'category-tag', text: categoryLabel(item.category) }),
+          el('h3', { text: item.name }),
+          el('p', { text: item.description }),
+          el('p', { className: 'price', text: formatPrice(item.price) }),
+          el('button', { type: 'button', className: 'btn add-to-order', dataset: { id: item.id }, 'aria-label': 'Add ' + item.name + ' to order', text: 'Add to Order' })
+        ]);
+      }
+
+      function renderMenu() {
+        var items = getVisibleItems();
+        var fragment = document.createDocumentFragment();
+        var plural = function (n) { return n + ' drink' + (n === 1 ? '' : 's'); };
+
+        if (state.group) {
+          var groups = state.category === 'all' ? CATEGORY_IDS : [state.category];
+          groups.forEach(function (catId) {
+            var groupItems = items.filter(function (i) { return i.category === catId; });
+            var section = el('section', { className: 'menu-group', dataset: { category: catId, count: String(groupItems.length) } }, [
+              el('h3', null, [
+                document.createTextNode(categoryLabel(catId) + ' '),
+                el('span', { className: 'group-count', text: '(' + plural(groupItems.length) + ')' })
+              ])
+            ]);
+            if (groupItems.length) {
+              section.appendChild(el('div', { className: 'grid' }, groupItems.map(renderCard)));
+            } else {
+              section.appendChild(el('p', { className: 'empty-state', text: 'No drinks in this category right now.' }));
+            }
+            fragment.appendChild(section);
+          });
+        } else if (items.length) {
+          fragment.appendChild(el('div', { className: 'grid' }, items.map(renderCard)));
+        } else {
+          fragment.appendChild(el('p', { className: 'empty-state', text: 'No drinks match your filters.' }));
+        }
+
+        menuList.replaceChildren(fragment);
+        menuCount.textContent = 'Showing ' + plural(items.length) + ' of ' + MENU.length;
+      }
+
+      function applyState(next, source) {
+        state = Object.assign({}, state, next);
+        syncControls();
+        writeStateToURL();
+        renderMenu();
+        dispatchFilterChange(source);
+      }
+
+      categorySelect.addEventListener('change', function () { applyState({ category: categorySelect.value }, 'category'); });
+      sortSelect.addEventListener('change', function () { applyState({ sort: sortSelect.value }, 'sort'); });
+      reverseToggle.addEventListener('click', function () { applyState({ reverse: !state.reverse }, 'reverse'); });
+      groupToggle.addEventListener('click', function () { applyState({ group: !state.group }, 'group'); });
+      window.addEventListener('popstate', function () { applyState(readStateFromURL(), 'popstate'); });
+
+      // ---------- Draft order ----------
+      var order = [];
+      var snapshot = null;
+      var lineCounter = 0;
+
+      function addToOrder(menuId) {
+        var item = MENU_BY_ID[menuId];
+        if (!item) return;
+        order.push({
+          lineId: 'line-' + Date.now().toString(36) + '-' + (++lineCounter),
+          menuId: item.id,
+          name: item.name,
+          category: item.category,
+          price: item.price,
+          options: {
+            milk: milkSelect.value,
+            size: sizeSelect.value,
+            customizations: { milk: milkSelect.value, size: sizeSelect.value }
+          },
+          note: noteInput.value.trim(),
+          addedAt: new Date().toISOString()
+        });
+        renderOrder();
+      }
+
+      function removeFromOrder(lineId) {
+        order = order.filter(function (line) { return line.lineId !== lineId; });
+        renderOrder();
+      }
+
+      function renderOrder() {
+        var fragment = document.createDocumentFragment();
+        if (!order.length) {
+          fragment.appendChild(el('li', { className: 'empty-state order-empty', text: 'Your draft order is empty.' }));
+        }
+        order.forEach(function (line) {
+          var time = new Date(line.addedAt);
+          var meta = line.options.size + ' · ' + line.options.milk + ' milk · added ' +
+            time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
+          fragment.appendChild(el('li', { className: 'order-item', dataset: { lineId: line.lineId, menuId: line.menuId } }, [
+            el('div', null, [
+              el('strong', { text: line.name }),
+              el('div', { className: 'order-meta', text: meta }),
+              line.note ? el('div', { className: 'order-meta order-note', text: 'Note: ' + line.note }) : null,
+              el('time', { className: 'order-meta', datetime: line.addedAt, hidden: 'hidden', text: line.addedAt })
+            ]),
+            el('div', null, [
+              el('span', { className: 'price', text: formatPrice(line.price) + ' ' }),
+              el('button', { type: 'button', className: 'remove-item', dataset: { lineId: line.lineId }, 'aria-label': 'Remove ' + line.name, text: 'Remove' })
+            ])
+          ]));
+        });
+        orderList.replaceChildren(fragment);
+        var total = order.reduce(function (sum, line) { return sum + line.price; }, 0);
+        orderTotal.textContent = 'Total: ' + formatPrice(total);
+        clearBtn.disabled = order.length === 0;
+      }
+
+      menuList.addEventListener('click', function (e) {
+        var btn = e.target.closest('.add-to-order');
+        if (btn) addToOrder(btn.dataset.id);
+      });
+
+      orderList.addEventListener('click', function (e) {
+        var btn = e.target.closest('.remove-item');
+        if (btn) removeFromOrder(btn.dataset.lineId);
+      });
+
+      saveBtn.addEventListener('click', function () {
+        snapshot = { savedAt: new Date().toISOString(), items: deepCopy(order) };
+        restoreBtn.disabled = false;
+        snapshotStatus.textContent = 'Snapshot saved with ' + snapshot.items.length + ' item(s) at ' +
+          new Date(snapshot.savedAt).toLocaleTimeString() + '.';
+      });
+
+      restoreBtn.addEventListener('click', function () {
+        if (!snapshot) return;
+        // Copy again so the stored snapshot stays isolated from future edits.
+        order = deepCopy(snapshot.items);
+        renderOrder();
+        snapshotStatus.textContent = 'Snapshot restored (' + order.length + ' item(s)).';
+      });
+
+      clearBtn.addEventListener('click', function () {
+        order = [];
+        renderOrder();
+      });
+
+      // Expose a read-only view for debugging/integration.
+      window.DailyGrind = {
+        menu: MENU,
+        getState: function () { return Object.assign({}, state); },
+        getOrder: function () { return deepCopy(order); },
+        getSnapshot: function () { return snapshot ? deepCopy(snapshot) : null; }
+      };
+
+      // ---------- Init ----------
+      applyState(readStateFromURL(), 'init');
+      renderOrder();
+    })();
+  </script>
 </body>

 </html>

