+      const SCRIPTS = [
+        [/[぀-ヿ]/g, 'ja'],
+        [/[가-힯ᄀ-ᇿ]/g, 'ko'],
+        [/[一-鿿]/g, 'zh'],
+        [/[฀-๿]/g, 'th'],
+        [/[֐-׿]/g, 'he'],
