+        [/[஀-௿]/g, 'ta'],
+        [/[Ⴀ-ჿ]/g, 'ka'],
+        [/[԰-֏]/g, 'hy']
+      ];
+
+      // Common function words for languages sharing a script.
+      const WORDS = {
+        en: 'the and is it to of in that was for you with this my not but are have very good great coffee service',
+        es: 'el la los las de que y en un una es por con no muy para pero fue me gusta mi su al lo café',
+        fr: 'le la les de des et est un une que qui pas pour dans très avec je mon mais ce sur au été café',
+        de: 'der die das und ist nicht ich ein eine zu mit sehr war es den dem auch aber für auf mein kaffee',
