+        da: 'og at det er en et jeg ikke som med for på var meget men min af kaffe',
+        no: 'og at det er en et jeg ikke som med for på var veldig men min av kaffe',
+        pl: 'i w nie na jest to się że z do bardzo ale był była mi jak kawa',
+        cs: 'a je to v se na že s z do ale byl byla velmi jsem káva',
+        tr: 've bir bu çok için ile ama da de ben değil gibi kahve güzel',
+        id: 'dan yang di ini itu tidak dengan untuk saya sangat ada kopi enak',
+        vi: 'và là của có không tôi rất được này cho với cà phê',
+        ru: 'и в не на что это я с как но очень был была мне кофе',
+        uk: 'і в не на що це я з як але дуже був була мені кава',
+        bg: 'и в не на че това аз с как но много беше ми кафе',
+        ar: 'في من على أن هذا إلى عن مع كان لا ما جدا القهوة',
+        fa: 'و در به از که این را با است من خیلی بود قهوه'
+      };
+      const WORD_SETS = Object.fromEntries(
