+            return { language: lang, confidence: Math.min(1, count / letters + 0.3) };
+          }
+        }
+
+        const words = text.toLowerCase().match(/[\p{L}\p{M}']+/gu) || [];
+        let best = null;
+        let bestScore = 0;
+        let total = 0;
+        for (const [lang, set] of Object.entries(WORD_SETS)) {
+          let score = 0;
+          for (const w of words) if (set.has(w)) score++;
+          total += score;
+          if (score > bestScore) {
+            bestScore = score;
+            best = lang;
+          }
+        }
+        if (!best) return null;
+        return { language: best, confidence: bestScore / Math.max(total, 1) };
+      }
+
+      // Prefer the browser's built-in Language Detector API when available.
+      let detectorPromise = null;
+      async function builtInDetect(text) {
+        if (!('LanguageDetector' in self)) return null;
+        try {
+          const availability = await LanguageDetector.availability();
+          if (availability === 'unavailable') return null;
+          detectorPromise = detectorPromise || LanguageDetector.create();
+          const detector = await detectorPromise;
+          const [top] = await detector.detect(text);
+          if (!top || top.detectedLanguage === 'und') return null;
+          return { language: top.detectedLanguage, confidence: top.confidence };
+        } catch (e) {
+          detectorPromise = null;
+          return null;
+        }
+      }
+
+      form.addEventListener('submit', async function (event) {
+        event.preventDefault();
+        const text = textarea.value.trim();
+        result.classList.remove('error');
+
+        if (!text) {
+          result.classList.add('error');
+          result.textContent = 'Please enter a message first.';
+          textarea.focus();
+          return;
+        }
+
+        button.disabled = true;
+        result.textContent = 'Detecting…';
+
+        const detected = (await builtInDetect(text)) || heuristicDetect(text);
+        button.disabled = false;
+
+        if (!detected) {
+          result.classList.add('error');
+          result.textContent = "Sorry, we couldn't identify the language of this message.";
+          return;
+        }
+
+        const pct = Math.round(detected.confidence * 100);
+        result.textContent = 'Detected language: ' + languageName(detected.language) +
+          ' (' + detected.language + ')' + (pct > 0 ? ' — ' + pct + '% confidence' : '');
+      });
+    })();
+  </script>
+
