+type ConnState =
+    | { kind: 'idle' }
+    | { kind: 'connecting' }
+    | { kind: 'ok'; status: number; ms: number; body: string; at: Date }
+    | { kind: 'error'; message: string };
+
+interface TargetConfig {
+    space: AddressSpace;
+    permission: LnaPermission;
+    title: string;
+    description: string;
+    defaultUrl: string;
+    storageKey: string;
+    permissionLabel: string;
+    troubleshooting: string[];
+}
+
+const TARGETS: TargetConfig[] = [
+    {
+        space: 'local',
+        permission: 'local-network',
+        title: 'Hardware test device (Wi-Fi LAN)',
+        description:
+            'Reach a test device on your private network, such as a dev board or sensor hub at 192.168.1.x or a .local hostname.',
+        defaultUrl: 'http://192.168.1.100:8080/api/status',
+        storageKey: 'dtt-diag-lan-url',
+        permissionLabel: 'Local network',
+        troubleshooting: [
+            'Make sure the device is powered on and joined to the same Wi-Fi network as this computer.',
+            'Make sure the device firmware sends an Access-Control-Allow-Origin header that allows this site.',
+            'Check the IP address in your router’s client list. DHCP may have given the device a new address.',
+        ],
+    },
+    {
+        space: 'loopback',
+        permission: 'loopback-network',
+        title: 'Companion CLI (this computer)',
+        description:
+            'Reach the DevTools Times companion CLI running on your own machine at 127.0.0.1.',
+        defaultUrl: 'http://127.0.0.1:45678/health',
+        storageKey: 'dtt-diag-cli-url',
+        permissionLabel: 'Loopback network',
+        troubleshooting: [
+            'Start the companion CLI in a terminal and check that it is listening on the port shown above.',
+            'Make sure the CLI sends an Access-Control-Allow-Origin header that allows this site.',
+            'Firewalls or VPN clients can block loopback ports. Try pausing them briefly.',
+        ],
+    },
