+function validateUrl(raw: string, space: AddressSpace): { url?: URL; error?: string } {
+    let url: URL;
+    try {
+        url = new URL(raw.trim());
+    } catch {
+        return { error: 'Enter a full URL, e.g. http://192.168.1.100:8080/status' };
+    }
+    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
+        return { error: 'Only http:// and https:// URLs are supported.' };
+    }
