+    prompt: { label: 'Will ask', cls: 'bg-amber-100 text-amber-800 ring-amber-600/20' },
+    denied: { label: 'Blocked', cls: 'bg-red-100 text-red-800 ring-red-600/20' },
+    unsupported: { label: 'Not reported', cls: 'bg-gray-100 text-gray-700 ring-gray-500/20' },
+};
+
+function TargetPanel({ config }: { config: TargetConfig }) {
+    const inputId = useId();
+    const errorId = useId();
+    const permission = useLnaPermission(config.permission);
+    const [url, setUrl] = useState(config.defaultUrl);
+    const [validationError, setValidationError] = useState<string | null>(null);
+    const [conn, setConn] = useState<ConnState>({ kind: 'idle' });
