+                    method: 'GET',
+                    mode: 'cors',
+                    credentials: 'omit',
+                    cache: 'no-store',
+                    signal: controller.signal,
+                    // Declares the target address space so the browser exempts http:// from
+                    // Mixed Content and verifies the resolved IP actually lands in this space.
+                    targetAddressSpace: config.space,
