new file mode 100644
index 0000000..42c4399
--- /dev/null
+++ b/src/pages/diagnostics.astro
@@ -0,0 +1,61 @@
+---
+import Layout from '../layouts/Layout.astro';
+import DiagnosticsConnect from '../components/DiagnosticsConnect';
+
+const siteOrigin = Astro.site?.origin ?? Astro.url.origin;
+---
+
+<Layout title="Developer Diagnostics | The DevTools Times">
+  <div class="px-4 py-8 md:px-8 md:py-12">
+    <header class="max-w-3xl mb-8">
+      <p class="text-xs font-bold uppercase tracking-widest text-gray-500 mb-2">Developer Tools</p>
+      <h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-3 pb-2 border-b-2">Diagnostics Connection</h1>
+      <p class="text-gray-700">
+        Connect directly from your browser to a hardware test device on your local network and to the companion CLI
+        running on your own machine. Requests go straight from your browser to those addresses — nothing is relayed
+        through or logged by our servers.
+      </p>
+    </header>
+
+    <DiagnosticsConnect client:only="react" />
+
+    <section class="mt-10 max-w-3xl prose prose-sm">
+      <h2>How it works</h2>
+      <ul>
+        <li>
+          A request is only sent when you click <strong>Connect</strong>. The page never scans your network.
+        </li>
+        <li>
+          The device panel accepts only private LAN addresses (<code>10.x</code>, <code>172.16–31.x</code>,
+          <code>192.168.x</code>, <code>169.254.x</code>) or <code>.local</code> hostnames. The CLI panel accepts only
+          loopback addresses (<code>127.0.0.1</code>, <code>localhost</code>, <code>::1</code>).
+        </li>
+        <li>
+          Your browser may ask for permission to access devices on your local network. You can revoke this at any time
+          in your browser's site settings.
+        </li>
+        <li>Host, port and path are remembered in this browser. Pairing tokens are never stored.</li>
+      </ul>
+
+      <h2>Requirements for devices and the CLI</h2>
+      <p>To accept connections from this page, the device firmware or CLI's status endpoint must:</p>
+      <ul>
+        <li>
+          Respond to the CORS preflight (<code>OPTIONS</code>) with
+          <code>Access-Control-Allow-Origin: {siteOrigin}</code> (an exact match — never <code>*</code>),
+          <code>Access-Control-Allow-Headers: Authorization, Accept</code>, and
+          <code>Access-Control-Allow-Private-Network: true</code>.
+        </li>
+        <li>
+          Reject requests whose <code>Origin</code> is not on its allowlist, and whose <code>Host</code> header is not its
+          own IP / hostname (protects against DNS-rebinding attacks).
+        </li>
+        <li>
+          Require a per-session pairing token (sent as <code>Authorization: Bearer &lt;token&gt;</code>) before exposing
+          anything sensitive or accepting state-changing commands.
+        </li>
+        <li>The CLI should bind to <code>127.0.0.1</code> only, never <code>0.0.0.0</code>.</li>
+      </ul>
+    </section>
+  </div>
+</Layout>

