+      toastTimer = setTimeout(() => { toast.textContent = ''; }, 4000);
+    }
+
+    document.querySelectorAll('.card[data-drink]').forEach(card => {
+      const slug = card.dataset.drink;
+      card.querySelector('.card-actions').insertAdjacentHTML('afterbegin', customizeMenu(slug));
+      const menu = card.querySelector('.menu');
+      applyState(menu, DRINKS[slug].defaults);
+      refreshCard(card);
+
+      card.addEventListener('menuchange', () => refreshCard(card));
+      card.addEventListener('menucommand', event => {
+        const name = card.querySelector('h3').textContent;
+        if (event.detail.action === 'add-to-order') {
+          const { text, price } = refreshCard(card);
+          cartCount.textContent = Number(cartCount.textContent) + 1;
+          announce(`Added ${name} (${text}) to your order, ${money(price)}.`);
+        } else if (event.detail.action === 'reset') {
+          applyState(menu, DRINKS[slug].defaults);
+          refreshCard(card);
+          announce(`${name} reset to its default recipe.`);
+        }
+      });
+    });
+
+    /* ================= Menu controller ================= */
+    const OPEN = ':is(:popover-open, .\\:popover-open)';
+    const GROUP = '[focusgroup~="menu"]';
+    const ITEM = `:is(${GROUP}, ${GROUP} > [role="group"]) > :is(button, a[href])`;
+    const hasInvokers = 'commandForElement' in HTMLButtonElement.prototype;
+    const hasAnchors = CSS.supports('position-area', 'block-end');
+    const canHover = matchMedia('(hover: hover)');
+
+    const enterOnOpen = new WeakSet();
+    let pointerTrigger = null;
+    let lastKey = null;
+    let windowBlurred = false;
+    let hoverTimer, hoverTarget;
+
+    const isOpen = menu => menu.matches(OPEN);
+    const menuFor = trigger => document.getElementById(trigger.getAttribute('commandfor'));
+    const triggerFor = menu => document.querySelector(`[commandfor="${menu.id}"]`);
+    const groupOf = menu => menu.querySelector(`:scope > ${GROUP}`);
+    const ownerGroup = el => el.closest(GROUP);
+    const isSubmenu = menu => !!menu.parentElement?.matches(GROUP);
+    const isMenuTrigger = el => !!el?.matches?.('button[aria-haspopup="menu"][commandfor]');
+    const rootMenu = el => {
+      let menu = el.closest('[popover]');
+      while (menu && isSubmenu(menu)) menu = menu.parentElement.closest('[popover]');
+      return menu;
+    };
+    const itemsOf = group => [...group.querySelectorAll('button, a[href]')]
+      .filter(item => ownerGroup(item) === group && !item.disabled && item.getAttribute('aria-disabled') !== 'true');
+    const focusItem = (item, visible = true) => item?.focus({ focusVisible: visible, preventScroll: true });
+
+    function closeAndRestore(menu, { fromPointer = false } = {}) {
+      if (!menu || !isOpen(menu)) return;
+      focusItem(triggerFor(menu), !fromPointer);
+      menu.hidePopover();
+    }
+
+    function enterMenu(menu) {
+      focusItem(itemsOf(groupOf(menu))[0]);
+    }
+
+    // Script positioning for browsers without CSS anchor positioning.
+    function placeWithoutAnchor(menu, trigger) {
+      const t = trigger.getBoundingClientRect();
+      const m = menu.getBoundingClientRect();
+      let left, top;
+      if (isSubmenu(menu)) {
+        left = t.right + 2;
+        top = t.top;
+        if (left + m.width > innerWidth) left = t.left - m.width - 2;
+        if (left < 0) { left = t.left + 16; top = t.bottom; }
+      } else {
+        left = t.left;
+        top = t.bottom + 4;
+        if (left + m.width > innerWidth) left = t.right - m.width;
+      }
+      if (top + m.height > innerHeight) top = Math.max(0, (isSubmenu(menu) ? t.bottom : t.top - 4) - m.height);
+      menu.style.left = `${Math.min(Math.max(0, left), Math.max(0, innerWidth - m.width))}px`;
+      menu.style.top = `${top}px`;
+    }
+
+    // Safe triangle: keeps a submenu open while the pointer travels diagonally towards it.
+    function startBridge(submenu, event) {
+      if (!canHover.matches || !isOpen(submenu)) return;
+      const rect = submenu.getBoundingClientRect();
+      const left = event.clientX < rect.left;
+      if (!left && event.clientX <= rect.right) return; // --below: no side edge.
+      submenu.style.setProperty('--pointer-x', `${event.clientX - rect.left}px`);
+      submenu.style.setProperty('--pointer-y', `${event.clientY - rect.top}px`);
+      submenu.dataset.bridge = '';
+      let timer;
+      let lastX = event.clientX;
+      const stop = () => {
+        clearTimeout(timer);
+        submenu.removeEventListener('pointermove', extend);
+        submenu.removeAttribute('data-bridge');
+      };
+      const extend = ({ target, clientX }) => {
+        if (target !== submenu || (left ? clientX < lastX : clientX > lastX)) return stop();
+        lastX = clientX;
+        clearTimeout(timer);
+        timer = setTimeout(stop, 300);
+      };
+      timer = setTimeout(stop, 300);
+      submenu.addEventListener('pointermove', extend);
+      submenu.addEventListener('toggle', stop, { once: true });
+    }
+
+    // Focusgroup fallback: arrow keys and roles for browsers without native focusgroup.
+    if (!('focusGroup' in HTMLElement.prototype)) {
+      document.querySelectorAll(GROUP).forEach(group => {
+        group.setAttribute('role', 'menu');
+        group.querySelectorAll('button:not([role]), a[href]:not([role])').forEach(item => {
+          if (ownerGroup(item) === group) item.setAttribute('role', 'menuitem');
+        });
+        group.addEventListener('keydown', event => {
+          if (!['ArrowDown', 'ArrowUp'].includes(event.key)) return;
+          const items = itemsOf(group);
+          const current = items.indexOf(document.activeElement);
+          if (current < 0) return;
+          event.preventDefault();
+          event.stopImmediatePropagation();
+          items[(current + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length].focus({ preventScroll: true });
+        }, true);
+      });
+    }
