+        if (!hasAnchors) placeWithoutAnchor(menu, trigger);
+        if (enterOnOpen.has(menu)) {
+          enterOnOpen.delete(menu);
+          enterMenu(menu);
+        } else if (!submenuLevel && pointerTrigger === trigger) {
+          focusItem(trigger, false);
+        }
+      });
+
+      trigger.addEventListener('pointerdown', event => {
+        event.preventDefault();
+        pointerTrigger = trigger;
+      });
+
+      trigger.addEventListener('click', event => {
+        const fromKeyboard = event.detail === 0;
+        if (!hasInvokers) {
+          event.preventDefault();
+          if (isOpen(menu)) return closeAndRestore(menu, { fromPointer: !fromKeyboard });
+          if (fromKeyboard) enterOnOpen.add(menu);
+          menu.showPopover({ source: trigger });
+          return;
+        }
+        if (fromKeyboard && !isOpen(menu)) enterOnOpen.add(menu);
+      });
