+      if (submenuLevel) {
+        trigger.addEventListener('pointerleave', event => {
+          if (hoverTarget === trigger) { clearTimeout(hoverTimer); hoverTarget = null; }
+          startBridge(menu, event);
+        });
+      } else {
+        trigger.addEventListener('keydown', event => {
+          if (event.key !== 'ArrowDown') return;
+          event.preventDefault();
+          if (isOpen(menu)) enterMenu(menu);
+          else { enterOnOpen.add(menu); trigger.click(); }
+        });
+      }
+
+      const group = groupOf(menu);
+      group.addEventListener('keydown', event => {
+        const item = event.target;
+        if (ownerGroup(item) !== group) return;
+        lastKey = event.key;
+        switch (event.key) {
+          case 'Home':
+          case 'End': {
+            const items = itemsOf(group);
+            event.preventDefault();
+            focusItem(items[event.key === 'Home' ? 0 : items.length - 1]);
+            break;
+          }
+          case 'ArrowRight':
+            if (isMenuTrigger(item)) {
+              event.preventDefault();
+              const sub = menuFor(item);
+              if (isOpen(sub)) enterMenu(sub);
+              else { enterOnOpen.add(sub); sub.showPopover({ source: item }); }
+            }
+            break;
+          case 'ArrowLeft':
+            if (!submenuLevel) break;
+          // falls through
+          case 'Escape':
+            event.preventDefault();
+            event.stopPropagation();
+            closeAndRestore(menu);
+            break;
+          case 'Tab': {
+            // Leave the whole menu system from its root trigger; never step through items.
+            const root = rootMenu(menu);
+            const rootTrigger = triggerFor(root);
+            if (event.shiftKey) event.preventDefault();
+            focusItem(rootTrigger);
+            root.hidePopover();
+            break;
+          }
+        }
+      });
+    });
+
+    document.addEventListener('pointerdown', () => { lastKey = null; }, true);
+    document.addEventListener('keydown', () => { pointerTrigger = null; }, true);
+    addEventListener('blur', () => { windowBlurred = true; });
+    addEventListener('focus', () => setTimeout(() => { windowBlurred = false; }));
+
+    document.addEventListener('focusin', event => {
+      const target = event.target;
+      // Close every root menu that focus has left.
+      document.querySelectorAll('.menu').forEach(menu => {
+        if (!isSubmenu(menu) && isOpen(menu) && !menu.contains(target) && triggerFor(menu) !== target) {
+          menu.hidePopover();
+        }
+      });
+      const group = ownerGroup(target);
+      if (!group) return;
+      // Moving to a sibling item closes the previewed submenu.
+      group.querySelectorAll(':scope > [popover]').forEach(sub => {
+        if (isOpen(sub) && triggerFor(sub) !== target) sub.hidePopover();
+      });
+      // Focusing a submenu trigger previews its submenu (unless focus came back from inside it).
+      if (isMenuTrigger(target) && !windowBlurred) {
+        const sub = menuFor(target);
+        if (!isOpen(sub) && !sub.contains(event.relatedTarget)) sub.showPopover({ source: target });
+      }
+    });
+
+    document.addEventListener('focusout', event => {
+      const trigger = event.target;
+      if (!isMenuTrigger(trigger) || !ownerGroup(trigger)) return;
+      const sub = menuFor(trigger);
+      setTimeout(() => {
+        if (!document.hasFocus() || !isOpen(sub)) return;
+        const active = document.activeElement;
+        if (active !== trigger && !sub.contains(active)) sub.hidePopover();
+      });
+    });
+
+    // Hover follows focus, with a short delay on submenu triggers so passing over them does not flash.
+    document.addEventListener('pointermove', event => {
+      if (event.pointerType === 'touch') return;
+      const item = event.target.closest?.(ITEM);
+      if (!item || document.activeElement === item) return;
+      if (!item.contains(document.elementFromPoint(event.clientX, event.clientY))) return;
+      if (isMenuTrigger(item)) {
+        if (hoverTarget === item) return;
+        clearTimeout(hoverTimer);
+        hoverTarget = item;
+        hoverTimer = setTimeout(() => { hoverTarget = null; focusItem(item, false); }, 120);
+      } else {
+        clearTimeout(hoverTimer);
+        hoverTarget = null;
+        focusItem(item, false);
+      }
+    });
