+      if (item.dataset.action) {
+        item.dispatchEvent(new CustomEvent('menucommand', { bubbles: true, detail: { action: item.dataset.action } }));
+      }
+      // Links still navigate natively; just tidy up the menus.
+      closeAndRestore(root, { fromPointer });
+    });
+  </script>
