+                type: 'radio-group', name: 'milk', label: 'Milk', value: state.milk,
+                options: MILKS.map((m) => ({ value: m.value, label: m.label, hint: plus(m.delta) })),
+              },
+            ],
+          },
+          {
+            type: 'submenu', id: 'flavor', label: 'Flavor & Sweetness', hint: '', items: [
+              {
+                type: 'submenu', id: 'syrups', label: 'Syrups', hint: '', items: SYRUPS.map((s) => ({
+                  type: 'checkbox', id: `syrup:${s.value}`, label: s.label,
+                  checked: state.syrups.has(s.value), hint: plus(SYRUP_PRICE),
+                })),
+              },
+              { type: 'separator' },
+              {
+                type: 'radio-group', name: 'sweetness', label: 'Sweetness', value: state.sweetness,
+                options: SWEETNESS.map((s) => ({ value: s.value, label: s.label })),
+              },
+            ],
+          },
+          { type: 'separator' },
+          {
+            type: 'radio-group', name: 'temp', label: 'Temperature', value: state.temp,
+            options: TEMPS.map((t) => ({ value: t.value, label: t.label })),
+          },
+          { type: 'separator' },
+          { type: 'checkbox', id: 'extraShot', label: 'Extra espresso shot', checked: false, hint: plus(SHOT_PRICE) },
+          { type: 'checkbox', id: 'decaf', label: 'Make it decaf', checked: false },
+          { type: 'separator' },
+          { label: 'Add to Order', action: 'add', id: 'add', hint: '' },
+          { label: 'Reset Customizations', action: 'reset' },
+          { label: 'View Details', href: d.href },
+        ];
+
+        const summaryEl = card.querySelector('.card-summary');
+        let menu;
+
+        function render() {
+          const total = fmt(price());
+          summaryEl.replaceChildren(
+            document.createTextNode(describe().join(' · ') + ' — '),
+            Object.assign(document.createElement('strong'), { textContent: total }),
+          );
+          menu.setHint('size', find(SIZES, state.size).label);
+          menu.setHint('milk', find(MILKS, state.milk).label);
+          menu.setHint('syrups', state.syrups.size ? `${state.syrups.size} selected` : 'None');
+          menu.setHint('flavor', find(SWEETNESS, state.sweetness).label);
+          menu.setHint('add', total);
+        }
+
+        menu = new MenuButton(card.querySelector('.card-actions .btn'), items, {
+          onChange(key, value) {
+            if (key.startsWith('syrup:')) {
+              const syrup = key.slice('syrup:'.length);
+              value ? state.syrups.add(syrup) : state.syrups.delete(syrup);
+            } else {
+              state[key] = value;
+            }
+            render();
+          },
+          onAction(action) {
+            if (action === 'add') {
+              bagCount += 1;
+              bagCountEl.textContent = bagCount;
+              bagLink.setAttribute('aria-label', `Order bag, ${bagCount} item${bagCount === 1 ? '' : 's'}`);
+              toast(`Added ${name} (${describe().join(', ')}) — ${fmt(price())}`);
+            } else if (action === 'reset') {
+              state = defaults();
+              ['size', 'milk', 'temp', 'sweetness', 'extraShot', 'decaf'].forEach((k) => menu.setValue(k, state[k]));
+              SYRUPS.forEach((s) => menu.setValue(`syrup:${s.value}`, state.syrups.has(s.value)));
+              render();
+              toast(`${name} reset to defaults`);
+            }
+          },
+        });
+
+        render();
+      });
+    })();
+  </script>
+
