+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Daily Grind settings bridge</title>
+  <meta name="robots" content="noindex">
+</head>
+<body>
+<script>
+  // Served from the OLD origin (https://app.dailygrind.coffee/settings-bridge.html).
+  // Hands this origin's user configuration to the NEW origin, which embeds this
+  // page in a hidden iframe. Only the trusted successor origin gets a reply.
+  const NEW_ORIGIN = 'https://www.dailygrind.coffee';
+  const SETTINGS_KEYS = ['dailygrind:prefs', 'dailygrind:favorites', 'dailygrind:last-store'];
+
+  window.addEventListener('message', (event) => {
+    if (event.origin !== NEW_ORIGIN) return;
+    if (event.data?.type !== 'dailygrind:request-settings') return;
+
+    const settings = {};
+    for (const key of SETTINGS_KEYS) {
+      const value = localStorage.getItem(key);
+      if (value !== null) settings[key] = value;
+    }
+    event.source.postMessage({ type: 'dailygrind:settings', settings }, NEW_ORIGIN);
+  });
+</script>
+</body>
