@@ -0,0 +1,51 @@
+// Runs on the NEW origin (https://www.dailygrind.coffee).
+// Web App Origin Migration moves the installation (shortcuts, home-screen and
+// taskbar icons) but NOT origin-bound storage, so pull user configuration from
+// the old origin once via a same-site iframe bridge.
+const OLD_ORIGIN = 'https://app.dailygrind.coffee';
+const BRIDGE_URL = `${OLD_ORIGIN}/settings-bridge.html`;
+const DONE_KEY = 'dailygrind:settings-migrated';
+const ALLOWED_KEYS = new Set(['dailygrind:prefs', 'dailygrind:favorites', 'dailygrind:last-store']);
+const TIMEOUT_MS = 10_000;
+
+function migrateSettings() {
+  if (localStorage.getItem(DONE_KEY)) return;
+
+  const iframe = document.createElement('iframe');
+  iframe.src = BRIDGE_URL;
+  iframe.hidden = true;
+  iframe.setAttribute('aria-hidden', 'true');
+  iframe.tabIndex = -1;
+
+  const controller = new AbortController();
+  const cleanup = () => {
+    controller.abort();
+    clearTimeout(timer);
+    iframe.remove();
+  };
+  // Give up quietly if the old origin is unreachable; retry on the next visit.
+  const timer = setTimeout(cleanup, TIMEOUT_MS);
+
+  window.addEventListener('message', (event) => {
+    if (event.origin !== OLD_ORIGIN || event.source !== iframe.contentWindow) return;
+    if (event.data?.type !== 'dailygrind:settings') return;
+
+    const settings = event.data.settings ?? {};
+    for (const [key, value] of Object.entries(settings)) {
+      // Only known keys, string values, and never clobber settings already
+      // changed on the new origin.
+      if (!ALLOWED_KEYS.has(key) || typeof value !== 'string') continue;
+      if (localStorage.getItem(key) === null) localStorage.setItem(key, value);
+    }
+    localStorage.setItem(DONE_KEY, new Date().toISOString());
+    cleanup();
+  }, { signal: controller.signal });
+
+  iframe.addEventListener('load', () => {
+    iframe.contentWindow.postMessage({ type: 'dailygrind:request-settings' }, OLD_ORIGIN);
+  }, { once: true, signal: controller.signal });
+
+  document.body.append(iframe);
+}
+
+migrateSettings();

