@@ -0,0 +1,67 @@
+import { VIEWS } from './migration-config.js';
+import { load, save, applyTheme, STORES, DRINKS, MILKS, SIZES, THEMES } from './prefs.js';
+import { runMigrationImport } from './migration-import.js';
+
+const LABELS = {
+  downtown: 'Downtown', riverside: 'Riverside', 'old-mill': 'Old Mill', campus: 'Campus',
+  'maple-oat-latte': 'Maple Oat Latte', 'dark-roast-espresso': 'Dark Roast Espresso',
+  'cold-brew': 'Cold Brew', 'flat-white': 'Flat White', drip: 'House Drip',
+  whole: 'Whole', skim: 'Skim', oat: 'Oat', almond: 'Almond', soy: 'Soy', none: 'No milk',
+  small: 'Small', medium: 'Medium', large: 'Large',
+  system: 'Match system', light: 'Light', dark: 'Dark',
+};
+const label = (v) => LABELS[v] ?? v;
+
+const form = document.getElementById('prefs-form');
+const options = { homeStore: STORES, defaultDrink: DRINKS, milk: MILKS, size: SIZES, theme: THEMES };
+
+for (const [name, values] of Object.entries(options)) {
+  const select = form.elements[name];
+  select.replaceChildren(...values.map((v) => new Option(label(v), v)));
+}
+
+function render(prefs) {
+  for (const name of Object.keys(options)) form.elements[name].value = prefs[name];
+  form.elements.orderReminders.checked = prefs.orderReminders;
+  applyTheme(prefs.theme);
+  document.getElementById('usual-summary').textContent =
+    `${label(prefs.size)} ${label(prefs.defaultDrink)}, ${label(prefs.milk).toLowerCase()} milk — pickup at ${label(prefs.homeStore)}`;
+  for (const li of document.querySelectorAll('[data-store]')) {
+    li.classList.toggle('is-home', li.dataset.store === prefs.homeStore);
+  }
+}
+
+form.addEventListener('change', () => {
+  const data = Object.fromEntries(new FormData(form));
+  render(save({ ...data, orderReminders: form.elements.orderReminders.checked }));
+  flash('Preferences saved');
+});
+
+function flash(message) {
+  const el = document.getElementById('toast');
+  el.textContent = message;
+  el.hidden = false;
+  clearTimeout(flash.t);
+  flash.t = setTimeout(() => (el.hidden = true), 3500);
+}
+
+// OS shortcut / deep-link views: /?view=order etc.
+function showView() {
+  const view = new URLSearchParams(location.search).get('view');
+  if (!VIEWS.includes(view)) return;
+  document.getElementById(`view-${view}`)?.scrollIntoView({ block: 'start' });
+}
+
+render(load());
+showView();
+
+runMigrationImport().then((result) => {
+  if (result?.imported) {
+    render(result.prefs);
+    flash('Welcome to our new home — your preferences came with you.');
+  }
+});
+
+if ('serviceWorker' in navigator) {
+  navigator.serviceWorker.register('/sw.js').catch(() => {});
+}
