index 0000000..8ed1ce9
--- /dev/null
+++ b/js/migration-config.js
@@ -0,0 +1,19 @@
+// Single source of truth for the origin move. Keep in sync with both
+// manifests (scripts/check-migration.mjs verifies this).
+export const OLD_ORIGIN = 'https://www.thedailygrind.coffee';
+export const NEW_ORIGIN = 'https://app.thedailygrind.coffee';
+
+// Manifest `id`s (absolute). The app id on the new origin is what the
+// browser will key the migrated installation on.
+export const OLD_APP_ID = `${OLD_ORIGIN}/`;
+export const NEW_APP_ID = `${NEW_ORIGIN}/`;
+
+// Fragment key used for the one-shot settings handoff. Fragments are never
+// sent to servers, so the payload doesn't land in access logs.
+export const HANDOFF_PARAM = 'dg-handoff';
+
+// OS-level shortcuts launch `/?view=<name>`. Query-string views (rather
+// than deep paths) work on any static host and before the service worker is
+// installed, and both manifests declare identical shortcut URLs so the
+// browser can re-point pinned shortcuts 1:1 during migration.
+export const VIEWS = ['order', 'menu', 'locations', 'settings'];
