new file mode 100644
index 0000000..08de7be
--- /dev/null
+++ b/js/migration-import.js
@@ -0,0 +1,73 @@
+// Runs on the NEW origin. Pulls user configuration over from the old origin
+// via (1) a one-shot URL-fragment handoff, or (2) a same-site iframe bridge.
+import { OLD_ORIGIN, HANDOFF_PARAM } from './migration-config.js';
+import { decodeHandoff, importIfNewer, loadStored } from './prefs.js';
+
+const BRIDGE_DONE_KEY = 'dg:migration:bridge-done';
+const BRIDGE_TIMEOUT_MS = 4000;
+
+/** Consume `#dg-handoff=...` if present and scrub it from the URL/history. */
+function consumeFragmentHandoff() {
+  const hash = new URLSearchParams(location.hash.slice(1));
+  const token = hash.get(HANDOFF_PARAM);
+  if (token === null) return null;
+
+  hash.delete(HANDOFF_PARAM);
+  const rest = hash.toString();
+  history.replaceState(history.state, '', location.pathname + location.search + (rest ? `#${rest}` : ''));
+
+  const prefs = decodeHandoff(token);
+  return prefs ? importIfNewer(prefs) : null;
+}
+
+/**
+ * Ask the old origin's bridge page for its stored prefs. Only works when the
+ * old origin's storage is reachable from an iframe (same-site origins under
+ * storage partitioning) — otherwise it resolves null and the fragment
+ * handoff from the old app remains the path.
+ */
+function requestFromBridge() {
+  return new Promise((resolve) => {
+    const nonce = crypto.randomUUID();
+    const iframe = document.createElement('iframe');
+    iframe.src = `${OLD_ORIGIN}/migration-bridge.html`;
+    iframe.hidden = true;
+    iframe.setAttribute('aria-hidden', 'true');
+    iframe.setAttribute('sandbox', 'allow-scripts allow-same-origin');
+
+    const finish = (result) => {
+      clearTimeout(timer);
+      window.removeEventListener('message', onMessage);
+      iframe.remove();
+      resolve(result);
+    };
+    const onMessage = (event) => {
+      if (event.origin !== OLD_ORIGIN || event.source !== iframe.contentWindow) return;
+      const data = event.data;
+      if (!data || data.type !== 'dg-prefs' || data.nonce !== nonce) return;
+      finish(data.prefs ? importIfNewer(data.prefs) : null);
+    };
+    const timer = setTimeout(() => finish(null), BRIDGE_TIMEOUT_MS);
+
+    window.addEventListener('message', onMessage);
+    iframe.addEventListener('load', () => {
+      iframe.contentWindow?.postMessage({ type: 'dg-prefs-request', nonce }, OLD_ORIGIN);
+    });
+    document.body.appendChild(iframe);
+  });
+}
+
+/** @returns {Promise<{imported: boolean, prefs: object} | null>} */
+export async function runMigrationImport() {
+  const fromFragment = consumeFragmentHandoff();
+  if (fromFragment) {
+    localStorage.setItem(BRIDGE_DONE_KEY, '1');
+    return fromFragment;
+  }
+  if (loadStored() || localStorage.getItem(BRIDGE_DONE_KEY)) return null;
+  if (location.origin === OLD_ORIGIN) return null;
+
+  const result = await requestFromBridge();
+  localStorage.setItem(BRIDGE_DONE_KEY, '1');
+  return result;
+}
