index 0000000..7449529
--- /dev/null
+++ b/js/prefs.js
@@ -0,0 +1,100 @@
+// User configuration: schema, strict sanitising, and persistence.
+// Shared verbatim by both origins so the handoff format can't drift.
+
+export const PREFS_KEY = 'dg:prefs:v1';
+export const SCHEMA_VERSION = 1;
+
+export const STORES = ['downtown', 'riverside', 'old-mill', 'campus'];
+export const DRINKS = ['maple-oat-latte', 'dark-roast-espresso', 'cold-brew', 'flat-white', 'drip'];
+export const MILKS = ['whole', 'skim', 'oat', 'almond', 'soy', 'none'];
+export const SIZES = ['small', 'medium', 'large'];
+export const THEMES = ['system', 'light', 'dark'];
+
+export const DEFAULTS = Object.freeze({
+  version: SCHEMA_VERSION,
+  updatedAt: 0,
+  homeStore: 'downtown',
+  defaultDrink: 'drip',
+  milk: 'whole',
+  size: 'medium',
+  theme: 'system',
+  orderReminders: false,
+});
+
+const pick = (value, allowed, fallback) => (allowed.includes(value) ? value : fallback);
+
+/**
+ * Whitelist-only normalisation. Unknown keys are dropped and invalid values
+ * fall back to defaults, so untrusted input (e.g. a crafted handoff link)
+ * can never inject arbitrary data into storage.
+ */
+export function sanitize(raw) {
+  const src = raw && typeof raw === 'object' ? raw : {};
+  const ts = Number(src.updatedAt);
+  return {
+    version: SCHEMA_VERSION,
+    updatedAt: Number.isFinite(ts) && ts > 0 && ts <= Date.now() + 60_000 ? Math.floor(ts) : 0,
+    homeStore: pick(src.homeStore, STORES, DEFAULTS.homeStore),
+    defaultDrink: pick(src.defaultDrink, DRINKS, DEFAULTS.defaultDrink),
+    milk: pick(src.milk, MILKS, DEFAULTS.milk),
+    size: pick(src.size, SIZES, DEFAULTS.size),
+    theme: pick(src.theme, THEMES, DEFAULTS.theme),
+    orderReminders: src.orderReminders === true,
+  };
+}
+
+/** Returns stored prefs, or null if the user never saved any on this origin. */
+export function loadStored() {
+  try {
+    const raw = localStorage.getItem(PREFS_KEY);
+    return raw ? sanitize(JSON.parse(raw)) : null;
+  } catch {
+    return null;
+  }
+}
+
+export function load() {
+  return loadStored() ?? { ...DEFAULTS };
+}
+
+export function save(prefs, { keepTimestamp = false } = {}) {
+  const clean = sanitize(prefs);
+  if (!keepTimestamp || !clean.updatedAt) clean.updatedAt = Date.now();
+  localStorage.setItem(PREFS_KEY, JSON.stringify(clean));
+  return clean;
+}
+
+/**
+ * Merge prefs arriving from the old origin. Only applied when this origin has
+ * nothing yet, or the incoming copy is strictly newer — re-running the
+ * handoff (or replaying an old link) never clobbers newer local changes.
+ */
+export function importIfNewer(incoming) {
+  const clean = sanitize(incoming);
+  if (!clean.updatedAt) return { imported: false, prefs: load() };
+  const current = loadStored();
+  if (current && current.updatedAt >= clean.updatedAt) return { imported: false, prefs: current };
+  return { imported: true, prefs: save(clean, { keepTimestamp: true }) };
+}
+
+// --- handoff encoding (URL-safe base64 of JSON) ---
+export function encodeHandoff(prefs) {
+  const json = JSON.stringify(sanitize(prefs));
+  const b64 = btoa(String.fromCharCode(...new TextEncoder().encode(json)));
+  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function decodeHandoff(token) {
+  if (typeof token !== 'string' || token.length > 2048 || !/^[A-Za-z0-9_-]+$/.test(token)) return null;
+  try {
+    const b64 = token.replace(/-/g, '+').replace(/_/g, '/');
+    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
+    return sanitize(JSON.parse(new TextDecoder().decode(bytes)));
+  } catch {
+    return null;
+  }
+}
+
+export function applyTheme(theme) {
+  document.documentElement.dataset.theme = theme;
+}
