+<!DOCTYPE html>
+<html lang="en">
+<!--
+  Served at the ROOT of the OLD origin (https://www.thedailygrind.coffee).
+  Its manifest declares `migrate_to`, so browsers that support web app
+  migration offer to move the installed app (including its OS shortcuts,
+  which are declared identically on both origins). This page also carries
+  the user's preferences across via a one-shot URL-fragment handoff.
+-->
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <meta name="referrer" content="no-referrer">
+  <title>The Daily Grind has moved</title>
+  <meta name="theme-color" content="#4e342e">
+  <link rel="manifest" href="/manifest.webmanifest">
+  <link rel="icon" href="/icons/icon.svg" type="image/svg+xml">
+  <style>
+    body {
+      margin: 0;
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+      background: #4e342e;
+      color: #fafafa;
+      text-align: center;
+      padding: 24px;
+      box-sizing: border-box;
+    }
+    main { max-width: 480px; }
+    img { width: 96px; height: 96px; border-radius: 20px; }
+    h1 { margin: 16px 0 8px; }
+    p { line-height: 1.6; color: #d7ccc8; }
+    a.btn {
+      display: inline-block;
+      margin-top: 16px;
+      background: #ffab40;
+      color: #3e2723;
+      font-weight: bold;
+      padding: 12px 24px;
+      border-radius: 6px;
+      text-decoration: none;
+    }
+    small { display: block; margin-top: 24px; color: #bcaaa4; }
+  </style>
+</head>
+<body>
+  <main>
+    <img src="/icons/icon-192.png" alt="">
+    <h1>We've moved!</h1>
+    <p>The Daily Grind app now lives at <strong id="new-host"></strong>.
+      Your preferences, home store and usual order come with you.</p>
+    <a id="continue" class="btn" href="#">Continue to the new app</a>
+    <small id="install-hint" hidden>Your browser may offer to update the installed app in place —
+      accept it to keep your home-screen icon and shortcuts.</small>
+    <noscript><p>Please visit <a href="https://app.thedailygrind.coffee/">app.thedailygrind.coffee</a>.</p></noscript>
+  </main>
+
+  <script type="module">
+    import { NEW_ORIGIN, HANDOFF_PARAM, VIEWS } from '/js/migration-config.js';
+    import { loadStored, encodeHandoff } from '/js/prefs.js';
+
+    // Preserve the shortcut view the OS launched us with (/?view=order …).
+    const view = new URLSearchParams(location.search).get('view');
+    const target = new URL('/', NEW_ORIGIN);
+    if (VIEWS.includes(view)) target.searchParams.set('view', view);
+
+    const prefs = loadStored();
+    if (prefs) target.hash = `${HANDOFF_PARAM}=${encodeHandoff(prefs)}`;
+
+    document.getElementById('new-host').textContent = target.host;
+    document.getElementById('continue').href = target.href;
+
+    const standalone = matchMedia('(display-mode: standalone)').matches
+      || matchMedia('(display-mode: window-controls-overlay)').matches
+      || navigator.standalone === true;
+
+    if (standalone) {
+      // Inside the installed app: stay put long enough for the browser's
+      // migration prompt to appear; the button still works immediately.
+      document.getElementById('install-hint').hidden = false;
+    } else {
+      // Regular tab / bookmark: go straight there.
+      location.replace(target.href);
+    }
+
+    if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
+  </script>
+</body>
+</html>
