new file mode 100644
index 0000000..61235e7
--- /dev/null
+++ b/legacy/sw.js
@@ -0,0 +1,34 @@
+// OLD-origin service worker. Replaces whatever SW the old app had installed
+// so a stale cached shell can't keep the user on the old origin forever:
+// it drops old caches and serves the "we've moved" page network-first.
+const CACHE = 'dg-legacy-moved-v1';
+const SHELL = ['/', '/index.html', '/manifest.webmanifest', '/js/prefs.js', '/js/migration-config.js', '/icons/icon.svg', '/icons/icon-192.png'];
+
+self.addEventListener('install', (e) => {
+  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (e) => {
+  e.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
+      .then(() => self.clients.claim()),
+  );
+});
+
+self.addEventListener('fetch', (e) => {
+  const req = e.request;
+  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
+  if (req.mode === 'navigate') {
+    const url = new URL(req.url);
+    if (url.pathname === '/migration-bridge.html') return; // always live
+    // Every old deep link / shortcut path lands on the handoff page, keeping
+    // its query string so `?view=` survives.
+    e.respondWith(
+      fetch(req).then((res) => (res.ok ? res : caches.match('/index.html')))
+        .catch(() => caches.match('/index.html')),
+    );
+    return;
+  }
+  e.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
+});
