+// Assembles the two deployables:
+//   dist/new-origin    → https://app.thedailygrind.coffee
+//   dist/legacy-origin → https://www.thedailygrind.coffee
+import { cpSync, rmSync, mkdirSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
+const dist = path.join(root, 'dist');
+const copy = (from, to) => cpSync(path.join(root, from), path.join(dist, to), { recursive: true });
+
+rmSync(dist, { recursive: true, force: true });
+mkdirSync(dist);
+
+for (const f of ['index.html', 'manifest.webmanifest', 'sw.js', 'js', 'icons']) copy(f, `new-origin/${f}`);
+
+copy('legacy', 'legacy-origin');
+copy('icons', 'legacy-origin/icons');
+for (const f of ['prefs.js', 'migration-config.js']) copy(`js/${f}`, `legacy-origin/js/${f}`);
+
+console.log('Built dist/new-origin and dist/legacy-origin');
