--- /dev/null
+++ b/scripts/check-migration.mjs
@@ -0,0 +1,59 @@
+// Static consistency checks for the origin migration. Fails (exit 1) if the
+// two manifests, the shared config and the service-worker shells disagree.
+import { readFileSync, existsSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
+const read = (p) => readFileSync(path.join(root, p), 'utf8');
+const cfg = await import(path.join(root, 'js/migration-config.js'));
+
+const errors = [];
+const expect = (cond, msg) => cond || errors.push(msg);
+
+const newM = JSON.parse(read('manifest.webmanifest'));
+const oldM = JSON.parse(read('legacy/manifest.webmanifest'));
+const absId = (m, origin) => new URL(m.id ?? m.start_url, origin).href;
+
+expect(absId(newM, cfg.NEW_ORIGIN) === cfg.NEW_APP_ID, `new manifest id resolves to ${absId(newM, cfg.NEW_ORIGIN)}, expected ${cfg.NEW_APP_ID}`);
+expect(absId(oldM, cfg.OLD_ORIGIN) === cfg.OLD_APP_ID, `old manifest id resolves to ${absId(oldM, cfg.OLD_ORIGIN)}, expected ${cfg.OLD_APP_ID}`);
+
+expect(oldM.migrate_to?.id === cfg.NEW_APP_ID, 'old manifest migrate_to.id must equal NEW_APP_ID');
+expect(oldM.migrate_to?.install_url?.startsWith(cfg.NEW_ORIGIN + '/'), 'old manifest migrate_to.install_url must be on NEW_ORIGIN');
+expect(!('migrate_from' in oldM), 'old manifest must not declare migrate_from');
+expect(!('migrate_to' in newM), 'new manifest must not declare migrate_to');
+const from = (newM.migrate_from ?? []).map((e) => (typeof e === 'string' ? { id: e } : e));
+expect(from.some((e) => e.id === cfg.OLD_APP_ID), 'new manifest migrate_from must list OLD_APP_ID');
+expect(from.every((e) => !e.behavior || ['suggest', 'force'].includes(e.behavior)), 'migrate_from behavior must be suggest|force');
+
+// OS shortcuts must match 1:1 so the browser can carry them across.
+const sc = (m) => JSON.stringify((m.shortcuts ?? []).map(({ name, short_name, url }) => ({ name, short_name, url })));
+expect(sc(newM) === sc(oldM), 'shortcuts differ between old and new manifests');
+for (const s of newM.shortcuts ?? []) {
+  const v = new URL(s.url, cfg.NEW_ORIGIN).searchParams.get('view');
+  expect(cfg.VIEWS.includes(v), `shortcut ${s.url} uses unknown view "${v}"`);
+}
+for (const k of ['scope', 'start_url', 'display', 'name']) {
+  expect(newM[k] === oldM[k], `manifest field "${k}" differs (${oldM[k]} → ${newM[k]})`);
+}
+
+// Service-worker shells must reference files that exist.
+const shell = (file, base) => {
+  const list = read(file).match(/const SHELL = \[([\s\S]*?)\]/)[1].match(/'([^']+)'/g).map((s) => s.slice(1, -1));
+  for (const p of list) {
+    if (p === '/') continue;
+    const candidates = [path.join(root, base, p), path.join(root, p)];
+    expect(candidates.some(existsSync), `${file}: precached ${p} not found`);
+  }
+};
+shell('sw.js', '.');
+shell('legacy/sw.js', 'legacy');
+
+const headers = read('legacy/_headers');
+expect(headers.includes(`frame-ancestors ${cfg.NEW_ORIGIN}`), 'legacy/_headers must allow NEW_ORIGIN to frame the bridge');
+
+if (errors.length) {
+  console.error('Migration check FAILED:\n - ' + errors.join('\n - '));
+  process.exit(1);
+}
+console.log('Migration check passed.');
