--- /dev/null
+++ b/sw.js
@@ -0,0 +1,30 @@
+// New-origin service worker: offline app shell.
+const CACHE = 'dg-app-v1';
+const SHELL = [
+  '/', '/index.html', '/manifest.webmanifest',
+  '/js/app.js', '/js/prefs.js', '/js/migration-config.js', '/js/migration-import.js',
+  '/icons/icon.svg', '/icons/icon-192.png', '/icons/icon-512.png',
+];
+
+self.addEventListener('install', (e) => {
+  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (e) => {
+  e.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
+      .then(() => self.clients.claim()),
+  );
+});
+
+self.addEventListener('fetch', (e) => {
+  const req = e.request;
+  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
+  if (req.mode === 'navigate') {
+    // Network-first so the latest manifest/markup is seen; shell when offline.
+    e.respondWith(fetch(req).catch(() => caches.match('/index.html')));
+    return;
+  }
+  e.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
+});

