+      // Tell the authenticator/password manager to drop a credential that the
+      // server never accepted, so the user isn't left with an orphaned passkey.
+      async function removeOrphanedCredential(rpId, credentialId) {
+        try {
+          if (rpId && credentialId &&
+              typeof PublicKeyCredential.signalUnknownCredential === 'function') {
+            await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+          }
+        } catch (_) { /* best effort, stay silent */ }
+      }
+
+      // ---- silent passkey registration (automatic passkey upgrade) ----
+      async function silentlyRegisterPasskey() {
+        if (!(await supportsSilentPasskeyCreation())) return;
+
+        const optionsRes = await fetch(REGISTER_OPTIONS_ENDPOINT, {
+          method: 'POST',
+          credentials: 'same-origin',
+          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+          body: JSON.stringify({}),
+        });
+        if (!optionsRes.ok) return;
+
+        const optionsData = await optionsRes.json();
+        const optionsJSON = optionsData.publicKey || optionsData.options || optionsData;
+        const publicKey = parseCreationOptions(optionsJSON);
+        const rpId = (optionsJSON.rp && optionsJSON.rp.id) || location.hostname;
+
+        let credential;
+        try {
+          credential = await navigator.credentials.create({
+            publicKey,
+            mediation: 'conditional',
+          });
+        } catch (_) {
+          // NotAllowedError etc.: the browser declined silently; nothing to do.
+          return;
+        }
+        if (!credential) return;
+
+        let verified = false;
+        try {
+          const verifyRes = await fetch(REGISTER_VERIFY_ENDPOINT, {
+            method: 'POST',
+            credentials: 'same-origin',
+            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+            body: JSON.stringify(credentialToJSON(credential)),
+          });
+          if (verifyRes.ok) {
+            const result = await verifyRes.json().catch(() => ({}));
+            verified = result.verified !== false && result.success !== false;
+          }
+        } catch (_) {
+          verified = false;
+        }
+
+        if (!verified) {
+          await removeOrphanedCredential(rpId, credential.id);
+        }
+      }
+
+      // ---- password sign-in ----
+      form.addEventListener('submit', async (event) => {
+        event.preventDefault();
+
+        const username = form.username.value.trim();
+        const password = form.password.value;
+        if (!username || !password) {
+          showMessage('Please enter your username and password.', 'error');
+          return;
+        }
+
+        button.disabled = true;
+        showMessage('Signing in…');
+
+        let signedIn = false;
+        try {
+          const res = await fetch(SIGNIN_ENDPOINT, {
+            method: 'POST',
+            credentials: 'same-origin',
+            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+            body: JSON.stringify({ username, password }),
+          });
+          if (res.ok) {
+            signedIn = true;
+          } else {
+            const data = await res.json().catch(() => ({}));
+            showMessage(data.error || data.message || 'Invalid username or password.', 'error');
+          }
+        } catch (_) {
+          showMessage('Unable to reach the server. Please try again.', 'error');
+        } finally {
+          button.disabled = false;
+        }
+
+        if (!signedIn) return;
+
+        form.password.value = '';
+        showMessage('Signed in successfully. Welcome back!', 'success');
+
+        // Fire-and-forget: never surface passkey errors to the user.
+        silentlyRegisterPasskey().catch(() => {});
+      });
+    })();
+  </script>
+
 </body>

