+// Small local subset of the community AAGUID registry
+// (https://github.com/passkeydeveloper/passkey-authenticator-aaguids).
+// Used only to help customers recognise which provider holds each passkey.
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export const AAGUID_REGISTRY = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', color: '#1a73e8' },
+  'adce0002-35bc-c60a-648b-0b25f1f05503': { name: 'Chrome on Mac', color: '#1a73e8' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', color: '#555555' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', color: '#0078d4' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello', color: '#0078d4' },
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': { name: 'Windows Hello', color: '#0078d4' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', color: '#0572ec' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', color: '#175ddc' },
+  '531126d6-e717-415c-9320-3d9aa6981239': { name: 'Dashlane', color: '#0e353d' },
+  '53414d53-554e-4700-0000-000000000000': { name: 'Samsung Pass', color: '#1428a0' },
+  'fa2b99dc-9e39-4257-8f92-4a30d23c4118': { name: 'YubiKey 5 Series with NFC', color: '#84bd00' },
+};
+
+/** Resolve provider details for an AAGUID. */
+export function lookupProvider(aaguid) {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: 'Unknown passkey provider', color: '#8d6e63', known: false };
+  }
+  const entry = AAGUID_REGISTRY[aaguid.toLowerCase()];
+  return entry ? { ...entry, known: true } : { name: 'Unknown passkey provider', color: '#8d6e63', known: false };
+}
