+++ b/account/api.js
@@ -0,0 +1,218 @@
+// Account / passkey API client.
+//
+// Talks to the real backend endpoints:
+//   GET    /api/credentials            -> { rpId, userId, user, credentials }
+//   PUT    /api/credential/:id         -> updated credential   (body: { name })
+//   DELETE /api/credential/:id         -> { success: true }
+//   PUT    /api/user                   -> { ...user, rpId, userId } (body: { name, displayName })
+//   POST   /api/passkey/registration-options -> PublicKeyCredentialCreationOptionsJSON
+//   POST   /api/passkey/register       -> stored credential   (body: credential.toJSON())
+//
+// This site is currently deployed as static files, so when those endpoints are
+// not available we fall back to a localStorage-backed mock "server" that
+// mirrors the same contract. All IDs are valid unpadded Base64URL strings.
+
+export function toBase64Url(bytes) {
+  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+  if (typeof u8.toBase64 === 'function') {
+    return u8.toBase64({ alphabet: 'base64url', omitPadding: true });
+  }
+  let bin = '';
+  for (const b of u8) bin += String.fromCharCode(b);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromBase64Url(str) {
+  if (typeof Uint8Array.fromBase64 === 'function') {
+    return Uint8Array.fromBase64(str, { alphabet: 'base64url' });
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
+}
+
+const encodeText = (s) => toBase64Url(new TextEncoder().encode(s));
+
+/* ------------------------------------------------------------------ */
+/* Real backend                                                        */
+/* ------------------------------------------------------------------ */
+
+async function request(method, url, body) {
+  const res = await fetch(url, {
+    method,
+    credentials: 'same-origin',
+    headers: body ? { 'Content-Type': 'application/json' } : undefined,
+    body: body ? JSON.stringify(body) : undefined,
+  });
+  if (!res.ok) {
+    let message = `Request failed (${res.status})`;
+    try { message = (await res.json()).error || message; } catch { /* ignore */ }
+    throw new Error(message);
+  }
+  return res.json();
+}
+
+const remoteApi = {
+  mode: 'remote',
+  listCredentials: () => request('GET', '/api/credentials'),
+  renameCredential: (id, name) => request('PUT', `/api/credential/${encodeURIComponent(id)}`, { name }),
+  deleteCredential: (id) => request('DELETE', `/api/credential/${encodeURIComponent(id)}`),
+  updateUser: (details) => request('PUT', '/api/user', details),
+  registrationOptions: () => request('POST', '/api/passkey/registration-options'),
+  registerCredential: (credentialJSON) => request('POST', '/api/passkey/register', credentialJSON),
+};
+
+/* ------------------------------------------------------------------ */
+/* Mock backend (static deployment / demo)                             */
+/* ------------------------------------------------------------------ */
+
+const STORE_KEY = 'dailygrind.mock-account.v1';
+// In a real deployment the RP ID is server configuration; the mock "server"
+// uses the current host because that's the only RP ID it can register against.
+const MOCK_RP_ID = location.hostname;
+const DAY = 24 * 60 * 60 * 1000;
+
+function seed() {
+  const now = Date.now();
+  return {
+    user: {
+      passkeyUserId: encodeText('daily-grind-user-1042'),
+      name: 'sam.rivera@example.com',
+      displayName: 'Sam Rivera',
+    },
+    credentials: [
+      {
+        id: encodeText('dg-cred-pixel-8'),
+        name: null,
+        aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+        registeredAt: now - 210 * DAY,
+        lastUsedAt: now - 2 * 60 * 60 * 1000,
+      },
+      {
+        id: encodeText('dg-cred-macbook'),
+        name: 'Work MacBook',
+        aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+        registeredAt: now - 95 * DAY,
+        lastUsedAt: now - 6 * DAY,
+      },
+      {
+        id: encodeText('dg-cred-yubikey'),
+        name: null,
+        aaguid: 'fa2b99dc-9e39-4257-8f92-4a30d23c4118',
+        registeredAt: now - 400 * DAY,
+        lastUsedAt: null,
+      },
+    ],
+  };
+}
+
+function load() {
+  try {
+    const raw = localStorage.getItem(STORE_KEY);
+    if (raw) return JSON.parse(raw);
+  } catch { /* fall through */ }
+  const data = seed();
+  save(data);
+  return data;
+}
+
+function save(data) {
+  try { localStorage.setItem(STORE_KEY, JSON.stringify(data)); } catch { /* ignore */ }
+}
+
+const delay = () => new Promise((r) => setTimeout(r, 150));
+const snapshot = (data) => ({
+  rpId: MOCK_RP_ID,
+  userId: data.user.passkeyUserId,
+  user: { name: data.user.name, displayName: data.user.displayName },
+  credentials: structuredClone(data.credentials),
+});
+
+function aaguidFromAuthData(authData) {
+  // rpIdHash(32) | flags(1) | signCount(4) | aaguid(16) ...
+  const bytes = new Uint8Array(authData);
+  if (bytes.length < 53 || !(bytes[32] & 0x40)) return '00000000-0000-0000-0000-000000000000';
+  const hex = Array.from(bytes.slice(37, 53), (b) => b.toString(16).padStart(2, '0')).join('');
+  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+}
+
+const mockApi = {
+  mode: 'mock',
+  async listCredentials() {
+    await delay();
+    return snapshot(load());
+  },
+  async renameCredential(id, name) {
+    await delay();
+    const data = load();
+    const cred = data.credentials.find((c) => c.id === id);
+    if (!cred) throw new Error('Credential not found.');
+    cred.name = name;
+    save(data);
+    return structuredClone(cred);
+  },
+  async deleteCredential(id) {
+    await delay();
+    const data = load();
+    const before = data.credentials.length;
+    data.credentials = data.credentials.filter((c) => c.id !== id);
+    if (data.credentials.length === before) throw new Error('Credential not found.');
+    save(data);
+    return { success: true };
+  },
+  async updateUser({ name, displayName }) {
+    await delay();
+    const data = load();
+    data.user.name = name;
+    data.user.displayName = displayName;
+    save(data);
+    return { name, displayName, rpId: MOCK_RP_ID, userId: data.user.passkeyUserId };
+  },
+  async registrationOptions() {
+    await delay();
+    const data = load();
+    return {
+      challenge: toBase64Url(crypto.getRandomValues(new Uint8Array(32))),
+      rp: { id: MOCK_RP_ID, name: 'The Daily Grind' },
+      user: { id: data.user.passkeyUserId, name: data.user.name, displayName: data.user.displayName },
+      pubKeyCredParams: [{ type: 'public-key', alg: -7 }, { type: 'public-key', alg: -257 }],
+      excludeCredentials: data.credentials.map((c) => ({ type: 'public-key', id: c.id })),
+      // No authenticatorAttachment so security keys can be registered too.
+      authenticatorSelection: { residentKey: 'required', userVerification: 'preferred' },
+      attestation: 'none',
+      timeout: 120000,
+    };
+  },
+  async registerCredential(credentialJSON) {
+    await delay();
+    // A real server MUST verify the attestation and challenge here.
+    const data = load();
+    const authData = credentialJSON.response?.authenticatorData;
+    const cred = {
+      id: credentialJSON.id,
+      name: null,
+      aaguid: authData ? aaguidFromAuthData(fromBase64Url(authData)) : '00000000-0000-0000-0000-000000000000',
+      registeredAt: Date.now(),
+      lastUsedAt: null,
+    };
+    data.credentials.push(cred);
+    save(data);
+    return structuredClone(cred);
+  },
+};
+
+/* ------------------------------------------------------------------ */
+
+let apiPromise;
+
+/** Resolve which backend to use (real endpoints if present, else mock). */
+export function getApi() {
+  apiPromise ??= (async () => {
+    try {
+      const res = await fetch('/api/credentials', { credentials: 'same-origin', headers: { Accept: 'application/json' } });
+      if (res.ok && res.headers.get('content-type')?.includes('application/json')) return remoteApi;
+    } catch { /* network / not found */ }
+    return mockApi;
+  })();
+  return apiPromise;
+}
