+++ b/account/passkeys.js
@@ -0,0 +1,353 @@
+import { getApi, toBase64Url, fromBase64Url } from './api.js';
+import { lookupProvider } from './aaguids.js';
+
+const $ = (sel) => document.querySelector(sel);
+
+const container = $('#passkey-container');
+const statusEl = $('#passkey-status');
+const createBtn = $('#create-passkey');
+const template = $('#passkey-row-template');
+const renameDialog = $('#rename-dialog');
+const deleteDialog = $('#delete-dialog');
+const profileForm = $('#profile-form');
+const profileStatus = $('#profile-status');
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const relFmt = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+let state = { rpId: null, userId: null, user: null, credentials: [] };
+let pendingId = null;
+
+/* ------------------------------------------------------------------ */
+/* Helpers                                                             */
+/* ------------------------------------------------------------------ */
+
+function setStatus(el, message, tone = 'info') {
+  el.dataset.tone = tone;
+  el.textContent = message;
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+function formatRelative(ts) {
+  const diff = ts - Date.now();
+  const abs = Math.abs(diff);
+  const units = [['year', 31536e6], ['month', 2592e6], ['week', 6048e5], ['day', 864e5], ['hour', 36e5], ['minute', 6e4]];
+  for (const [unit, ms] of units) {
+    if (abs >= ms) return relFmt.format(Math.round(diff / ms), unit);
+  }
+  return 'just now';
+}
+
+function timeEl(ts, el = document.createElement('time')) {
+  const d = new Date(ts);
+  el.dateTime = d.toISOString();
+  el.textContent = dateFmt.format(d);
+  el.title = d.toLocaleString();
+  return el;
+}
+
+const KEY_ICON = '<svg viewBox="0 0 24 24"><path d="M12.65 10A6 6 0 1 0 12.65 14H17v4h4v-4h2v-4H12.65zM7 14a2 2 0 1 1 0-4 2 2 0 0 1 0 4z"/></svg>';
+
+const displayName = (cred) => cred.name?.trim() || lookupProvider(cred.aaguid).name;
+
+/* ------------------------------------------------------------------ */
+/* Signal API synchronisation (progressive enhancement)                */
+/* ------------------------------------------------------------------ */
+
+async function syncAcceptedCredentials({ rpId, userId, credentials }) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const ids = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !ids.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL userId/credential IDs are required.');
+    return;
+  }
+  try {
+    // rpId always comes from the server, never window.location.hostname.
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: ids });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+async function syncUserDetails({ rpId, userId, name, displayName: dn }) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName: dn });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Rendering                                                           */
+/* ------------------------------------------------------------------ */
+
+function render() {
+  container.setAttribute('aria-busy', 'false');
+  const { credentials } = state;
+
+  if (!credentials.length) {
+    container.innerHTML = '';
+    const empty = document.createElement('p');
+    empty.className = 'empty-state';
+    empty.textContent = 'No passkeys found. Create one to sign in faster next time you order.';
+    container.append(empty);
+    return;
+  }
+
+  const list = document.createElement('ul');
+  list.className = 'passkey-list';
+  list.setAttribute('aria-label', 'Your passkeys');
+
+  const sorted = [...credentials].sort((a, b) => (b.lastUsedAt ?? b.registeredAt) - (a.lastUsedAt ?? a.registeredAt));
+  for (const cred of sorted) {
+    const provider = lookupProvider(cred.aaguid);
+    const name = displayName(cred);
+    const row = template.content.firstElementChild.cloneNode(true);
+    row.dataset.id = cred.id;
+
+    const icon = row.querySelector('.passkey-icon');
+    icon.style.setProperty('--provider-color', provider.color);
+    if (cred.providerIcon) {
+      const img = new Image(28, 28);
+      img.src = cred.providerIcon;
+      img.alt = '';
+      icon.append(img);
+    } else if (provider.known) {
+      icon.textContent = provider.name.charAt(0);
+    } else {
+      icon.innerHTML = KEY_ICON;
+    }
+
+    row.querySelector('.passkey-name').textContent = name;
+    row.querySelector('.passkey-provider').textContent =
+      cred.name?.trim() ? `Saved in ${provider.name}` : (provider.known ? 'Passkey' : 'Passkey · provider not recognised');
+
+    timeEl(cred.registeredAt, row.querySelector('[data-field="registered"]'));
+    const lastUsed = row.querySelector('[data-field="last-used-wrap"]');
+    if (cred.lastUsedAt) {
+      const t = timeEl(cred.lastUsedAt);
+      t.textContent = formatRelative(cred.lastUsedAt);
+      lastUsed.append('Last used ', t);
+    } else {
+      lastUsed.textContent = 'Never used';
+    }
+
+    for (const btn of row.querySelectorAll('[data-action]')) {
+      const verb = btn.dataset.action === 'rename' ? 'Rename' : 'Delete';
+      btn.setAttribute('aria-label', `${verb} ${name}`);
+    }
+    list.append(row);
+  }
+
+  container.replaceChildren(list);
+}
+
+function fillProfile(user) {
+  if (!user) return;
+  profileForm.elements.displayName.value = user.displayName ?? '';
+  profileForm.elements.name.value = user.name ?? '';
+}
+
+/* ------------------------------------------------------------------ */
+/* Data flow                                                           */
+/* ------------------------------------------------------------------ */
+
+async function refresh() {
+  const api = await getApi();
+  const data = await api.listCredentials();
+  state = { rpId: data.rpId, userId: data.userId, user: data.user ?? state.user, credentials: data.credentials ?? [] };
+  render();
+  return state;
+}
+
+async function init() {
+  try {
+    await refresh();
+    fillProfile(state.user);
+    // Keep password managers in sync with what the server accepts on every visit.
+    syncAcceptedCredentials(state);
+  } catch (e) {
+    container.setAttribute('aria-busy', 'false');
+    container.innerHTML = '<p class="empty-state">We couldn\'t load your passkeys. Please refresh the page to try again.</p>';
+    console.warn('Failed to load passkeys:', e);
+  }
+  setupCreateButton();
+}
+
+/* Rename ------------------------------------------------------------ */
+
+container.addEventListener('click', (event) => {
+  const btn = event.target.closest('button[data-action]');
+  if (!btn) return;
+  const id = btn.closest('.passkey').dataset.id;
+  const cred = state.credentials.find((c) => c.id === id);
+  if (!cred) return;
+  pendingId = id;
+
+  if (btn.dataset.action === 'rename') {
+    const input = renameDialog.querySelector('input[name="passkeyName"]');
+    input.value = displayName(cred);
+    renameDialog.showModal();
+    input.select();
+  } else {
+    deleteDialog.querySelector('[data-field="name"]').textContent = displayName(cred);
+    deleteDialog.querySelector('[data-field="last-warning"]').hidden = state.credentials.length > 1;
+    deleteDialog.showModal();
+  }
+});
+
+renameDialog.addEventListener('close', async () => {
+  const choice = renameDialog.returnValue;
+  renameDialog.returnValue = '';
+  const id = pendingId;
+  pendingId = null;
+  if (choice !== 'save' || !id) return;
+
+  const newName = renameDialog.querySelector('input[name="passkeyName"]').value.trim();
+  const cred = state.credentials.find((c) => c.id === id);
+  if (!newName || !cred || newName === displayName(cred)) return;
+
+  try {
+    const api = await getApi();
+    // A nickname is a server-side label only; no Signal API call is needed.
+    await api.renameCredential(id, newName);
+    await refresh();
+    setStatus(statusEl, `Passkey renamed to "${newName}".`, 'success');
+  } catch (e) {
+    setStatus(statusEl, `Couldn't rename passkey: ${e.message}`, 'error');
+  }
+});
+
+/* Delete ------------------------------------------------------------ */
+
+deleteDialog.addEventListener('close', async () => {
+  const choice = deleteDialog.returnValue;
+  deleteDialog.returnValue = '';
+  const id = pendingId;
+  pendingId = null;
+  if (choice !== 'delete' || !id) return;
+
+  const cred = state.credentials.find((c) => c.id === id);
+  const name = cred ? displayName(cred) : 'Passkey';
+  try {
+    const api = await getApi();
+    await api.deleteCredential(id);
+    const latest = await refresh();
+    // Tell the password manager which credentials remain valid so the deleted one disappears.
+    await syncAcceptedCredentials(latest);
+    setStatus(statusEl, `"${name}" was deleted.`, 'success');
+    // The invoking row is gone, so move focus somewhere predictable.
+    $('#passkeys-heading').focus();
+  } catch (e) {
+    setStatus(statusEl, `Couldn't delete passkey: ${e.message}`, 'error');
+  }
+});
+
+/* Profile ----------------------------------------------------------- */
+
+profileForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const name = profileForm.elements.name.value.trim();
+  const dn = profileForm.elements.displayName.value.trim();
+  const submit = profileForm.querySelector('button[type="submit"]');
+  submit.disabled = true;
+  try {
+    const api = await getApi();
+    const updated = await api.updateUser({ name, displayName: dn });
+    state.user = { name: updated.name ?? name, displayName: updated.displayName ?? dn };
+    await syncUserDetails({ rpId: updated.rpId, userId: updated.userId, name, displayName: dn });
+    setStatus(profileStatus, 'Profile saved.', 'success');
+  } catch (e) {
+    setStatus(profileStatus, `Couldn't save profile: ${e.message}`, 'error');
+  } finally {
+    submit.disabled = false;
+  }
+});
+
+/* Create passkey ---------------------------------------------------- */
+
+async function isPasskeySupported() {
+  if (!window.PublicKeyCredential) return false;
+  try {
+    if (PublicKeyCredential.getClientCapabilities) {
+      const caps = await PublicKeyCredential.getClientCapabilities();
+      return Boolean(caps.passkeyPlatformAuthenticator);
+    }
+    return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+  } catch {
+    return false;
+  }
+}
+
+async function setupCreateButton() {
+  const supported = await isPasskeySupported();
+  createBtn.hidden = !supported;
+  $('#unsupported-note').hidden = supported;
+}
+
+function parseCreationOptions(json) {
+  if (PublicKeyCredential.parseCreationOptionsFromJSON) {
+    return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: fromBase64Url(json.challenge),
+    user: { ...json.user, id: fromBase64Url(json.user.id) },
+    excludeCredentials: (json.excludeCredentials ?? []).map((c) => ({ ...c, id: fromBase64Url(c.id) })),
+  };
+}
+
+function credentialToJSON(cred) {
+  try {
+    if (typeof cred.toJSON === 'function') return cred.toJSON();
+  } catch { /* some providers return objects whose toJSON throws */ }
+  const r = cred.response;
+  return {
+    id: cred.id,
+    rawId: toBase64Url(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? undefined,
+    clientExtensionResults: cred.getClientExtensionResults(),
+    response: {
+      clientDataJSON: toBase64Url(r.clientDataJSON),
+      attestationObject: toBase64Url(r.attestationObject),
+      authenticatorData: r.getAuthenticatorData ? toBase64Url(r.getAuthenticatorData()) : undefined,
+      transports: r.getTransports ? r.getTransports() : [],
+      publicKeyAlgorithm: r.getPublicKeyAlgorithm ? r.getPublicKeyAlgorithm() : undefined,
+    },
+  };
+}
+
+createBtn.addEventListener('click', async () => {
+  createBtn.disabled = true;
+  setStatus(statusEl, 'Follow your browser\'s prompts to create a passkey…');
+  try {
+    const api = await getApi();
+    const optionsJSON = await api.registrationOptions();
+    const credential = await navigator.credentials.create({ publicKey: parseCreationOptions(optionsJSON) });
+    await api.registerCredential(credentialToJSON(credential));
+    await refresh();
+    setStatus(statusEl, 'Passkey created. You can rename it to make it easier to recognise.', 'success');
+  } catch (e) {
+    if (e.name === 'NotAllowedError' || e.name === 'AbortError') {
+      setStatus(statusEl, 'Passkey creation was cancelled.');
+    } else if (e.name === 'InvalidStateError') {
+      setStatus(statusEl, 'This device already has a passkey for your account.', 'error');
+    } else {
+      setStatus(statusEl, `Couldn't create passkey: ${e.message}`, 'error');
+    }
+  } finally {
+    createBtn.disabled = false;
+  }
+});
+
+init();

