+/**
+ * Passkey management for the "My Account" page.
+ *
+ * Expected backend contract (session-cookie authenticated, same origin):
+ *
+ *   GET    /api/account/passkeys
+ *     200 → {
+ *       rpId?: string,                       // defaults to location.hostname
+ *       user: { id: string,                  // base64url WebAuthn user handle
+ *               name: string, displayName?: string },
+ *       passkeys: [{ id: string,             // base64url credential ID
+ *                    name: string,
+ *                    createdAt: string,      // ISO 8601
+ *                    lastUsedAt?: string|null,
+ *                    backedUp?: boolean }]   // synced passkey (BS flag)
+ *     }
+ *   PATCH  /api/account/passkeys/:id   body { name }  → 200 updated passkey
+ *   DELETE /api/account/passkeys/:id                  → 204 (404 = already gone)
+ *   401 on any endpoint → user is sent to /login
+ *
+ * Browser authenticator sync uses the WebAuthn Signal API where supported:
+ *   - signalAllAcceptedCredentials: after every successful list load, so
+ *     passkeys removed here (or on another device) disappear from the
+ *     password manager / platform authenticator's sign-in prompts.
+ *   - signalUnknownCredential: targeted removal right after a delete.
+ *   - signalCurrentUserDetails: keeps the account name shown by the
+ *     authenticator up to date.
+ * All signals are best-effort; unsupported browsers simply skip them.
+ */
+
+const API_BASE = '/api/account/passkeys';
+const MAX_NAME_LENGTH = 64;
+
+const els = {
+  list: document.getElementById('passkey-list'),
+  status: document.getElementById('passkey-status'),
+  greeting: document.getElementById('account-greeting'),
+  renameDialog: document.getElementById('rename-dialog'),
+  renameForm: document.getElementById('rename-form'),
+  renameInput: document.getElementById('rename-input'),
+  deleteDialog: document.getElementById('delete-dialog'),
+  deleteForm: document.getElementById('delete-form'),
+  deleteMessage: document.getElementById('delete-message'),
+};
+
+const state = {
+  rpId: location.hostname,
+  user: null,
+  passkeys: [],
+  busy: false,
+};
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+
+/* ------------------------------------------------------------------ API */
+
+class ApiError extends Error {
+  constructor(message, status) {
+    super(message);
+    this.status = status;
+  }
+}
+
+async function api(path, { method = 'GET', body } = {}) {
+  const headers = { Accept: 'application/json', 'X-Requested-With': 'fetch' };
+  const csrf = document.querySelector('meta[name="csrf-token"]')?.content;
+  if (csrf) headers['X-CSRF-Token'] = csrf;
+  if (body !== undefined) headers['Content-Type'] = 'application/json';
+
+  let res;
+  try {
+    res = await fetch(path, {
+      method,
+      headers,
+      credentials: 'same-origin',
+      body: body === undefined ? undefined : JSON.stringify(body),
+    });
+  } catch {
+    throw new ApiError('Could not reach The Daily Grind. Check your connection and try again.', 0);
+  }
+
+  if (res.status === 401) {
+    location.assign(`/login?next=${encodeURIComponent(location.pathname)}`);
+    throw new ApiError('Your session has expired. Please sign in again.', 401);
+  }
+
+  const data = res.status === 204 ? null : await res.json().catch(() => null);
+  if (!res.ok) {
+    const message = (data && (data.message || data.error)) || `Request failed (${res.status}).`;
+    throw new ApiError(String(message), res.status);
+  }
+  return data;
+}
+
+const passkeyUrl = (id) => `${API_BASE}/${encodeURIComponent(id)}`;
+
+/* ------------------------------------------------- Authenticator sync */
+
+function signalSupported(method) {
+  return typeof window.PublicKeyCredential?.[method] === 'function';
+}
+
+async function signal(method, options) {
+  if (!signalSupported(method)) return;
+  try {
+    await PublicKeyCredential[method](options);
+  } catch (err) {
+    // Best-effort: the server remains the source of truth.
+    console.warn(`WebAuthn ${method} failed`, err);
+  }
+}
+
+/**
+ * Tell the authenticator the complete set of credentials the server accepts.
+ * Must only be called with a list freshly and successfully loaded from the
+ * server — an empty or stale list would hide valid passkeys.
+ */
+async function syncAuthenticator() {
+  if (!state.user?.id) return;
+  await Promise.all([
+    signal('signalAllAcceptedCredentials', {
+      rpId: state.rpId,
+      userId: state.user.id,
+      allAcceptedCredentialIds: state.passkeys.map((p) => p.id),
+    }),
+    signal('signalCurrentUserDetails', {
+      rpId: state.rpId,
+      userId: state.user.id,
+      name: state.user.name,
+      displayName: state.user.displayName || state.user.name,
+    }),
+  ]);
+}
+
+/* ------------------------------------------------------------ Loading */
+
+function isValidPayload(data) {
+  return (
+    data &&
+    typeof data.user?.id === 'string' &&
+    data.user.id.length > 0 &&
+    Array.isArray(data.passkeys) &&
+    data.passkeys.every((p) => p && typeof p.id === 'string' && p.id.length > 0)
+  );
+}
+
+async function loadPasskeys() {
+  const data = await api(API_BASE);
+  if (!isValidPayload(data)) {
+    throw new ApiError('We received an unexpected response while loading your passkeys.', 0);
+  }
+  state.rpId = typeof data.rpId === 'string' && data.rpId ? data.rpId : location.hostname;
+  state.user = data.user;
+  state.passkeys = data.passkeys;
+  render();
+  await syncAuthenticator();
+}
+
+/* ---------------------------------------------------------- Rendering */
+
+function formatDate(value) {
+  if (!value) return null;
+  const d = new Date(value);
+  return Number.isNaN(d.getTime()) ? null : dateFormat.format(d);
+}
+
+function el(tag, props = {}, ...children) {
+  const node = document.createElement(tag);
+  Object.assign(node, props);
+  for (const child of children) if (child != null) node.append(child);
+  return node;
+}
+
+function renderPasskey(passkey) {
+  const name = passkey.name?.trim() || 'Unnamed passkey';
+  const created = formatDate(passkey.createdAt);
+  const lastUsed = formatDate(passkey.lastUsedAt);
+  const meta = [
+    created && `Added ${created}`,
+    lastUsed ? `Last used ${lastUsed}` : 'Never used',
+  ].filter(Boolean).join(' · ');
+
+  const nameEl = el('div', { className: 'passkey-name', textContent: name });
+  if (passkey.backedUp) {
+    nameEl.append(el('span', {
+      className: 'badge',
+      textContent: 'Synced',
+      title: 'This passkey is backed up and synced across your devices',
+    }));
+  }
+
+  const renameBtn = el('button', {
+    type: 'button',
+    className: 'btn btn-secondary',
+    textContent: 'Rename',
+    disabled: state.busy,
+  });
+  renameBtn.setAttribute('aria-label', `Rename ${name}`);
+  renameBtn.addEventListener('click', () => openRename(passkey));
+
+  const deleteBtn = el('button', {
+    type: 'button',
+    className: 'btn btn-danger',
+    textContent: 'Delete',
+    disabled: state.busy,
+  });
+  deleteBtn.setAttribute('aria-label', `Delete ${name}`);
+  deleteBtn.addEventListener('click', () => openDelete(passkey));
+
+  const icon = el('div', { className: 'passkey-icon', textContent: '🔑' });
+  icon.setAttribute('aria-hidden', 'true');
+
+  return el('li', { className: 'passkey' },
+    icon,
+    el('div', { className: 'passkey-info' },
+      nameEl,
+      el('div', { className: 'passkey-meta', textContent: meta })),
+    el('div', { className: 'passkey-actions' }, renameBtn, deleteBtn));
+}
+
+function render() {
+  if (state.user?.displayName || state.user?.name) {
+    els.greeting.textContent =
+      `Signed in as ${state.user.displayName || state.user.name}. Manage how you sign in to The Daily Grind.`;
+  }
+  els.list.setAttribute('aria-busy', String(state.busy));
+  if (state.passkeys.length === 0) {
+    els.list.replaceChildren(el('li', {
+      className: 'empty-state',
+      textContent: 'You don’t have any passkeys registered.',
+    }));
+    return;
+  }
+  els.list.replaceChildren(...state.passkeys.map(renderPasskey));
+}
+
+function setStatus(message, type = 'success') {
+  els.status.className = `status ${type}`;
+  els.status.textContent = message;
+}
+
+function clearStatus() {
+  els.status.className = 'status';
+  els.status.textContent = '';
+}
+
+async function withBusy(fn) {
+  if (state.busy) return;
+  state.busy = true;
+  render();
+  try {
+    await fn();
+  } catch (err) {
+    setStatus(err.message || 'Something went wrong. Please try again.', 'error');
+  } finally {
+    state.busy = false;
+    render();
+  }
+}
+
+/* ------------------------------------------------------------- Rename */
+
+let renameTarget = null;
+
+function openRename(passkey) {
+  renameTarget = passkey;
+  els.renameInput.value = passkey.name || '';
+  els.renameDialog.showModal();
+  els.renameInput.select();
+}
+
+els.renameForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const target = renameTarget;
+  const name = els.renameInput.value.trim();
+  if (!target) return;
+  if (!name) {
+    els.renameInput.setCustomValidity('Please enter a name.');
+    els.renameInput.reportValidity();
+    return;
+  }
+  if (name.length > MAX_NAME_LENGTH) {
+    els.renameInput.setCustomValidity(`Names can be at most ${MAX_NAME_LENGTH} characters.`);
+    els.renameInput.reportValidity();
+    return;
+  }
+  els.renameDialog.close();
+  if (name === target.name) return;
+
+  clearStatus();
+  withBusy(async () => {
+    const updated = await api(passkeyUrl(target.id), { method: 'PATCH', body: { name } });
+    const newName = typeof updated?.name === 'string' ? updated.name : name;
+    state.passkeys = state.passkeys.map((p) =>
+      p.id === target.id ? { ...p, ...(updated && typeof updated === 'object' ? updated : {}), name: newName } : p);
+    setStatus(`Passkey renamed to “${newName}”.`);
+  });
+});
+
+els.renameInput.addEventListener('input', () => els.renameInput.setCustomValidity(''));
+
+/* ------------------------------------------------------------- Delete */
+
+let deleteTarget = null;
+
+function openDelete(passkey) {
+  deleteTarget = passkey;
+  const name = passkey.name?.trim() || 'this passkey';
+  const lastOne = state.passkeys.length === 1;
+  els.deleteMessage.textContent = lastOne
+    ? `“${name}” is your only passkey. After deleting it you’ll need another sign-in method, such as your password, to access your account.`
+    : `You won’t be able to sign in with “${name}” anymore. It will also be removed from your browser or password manager where supported.`;
+  els.deleteDialog.showModal();
+}
+
+els.deleteForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const target = deleteTarget;
+  els.deleteDialog.close();
+  if (!target) return;
+
+  clearStatus();
+  withBusy(async () => {
+    try {
+      await api(passkeyUrl(target.id), { method: 'DELETE' });
+    } catch (err) {
+      if (err.status !== 404) throw err; // 404: already deleted elsewhere
+    }
+
+    state.passkeys = state.passkeys.filter((p) => p.id !== target.id);
+
+    // Targeted removal from the authenticator; safe even if the full resync fails.
+    if (state.user?.id) {
+      await signal('signalUnknownCredential', { rpId: state.rpId, credentialId: target.id });
+    }
+
+    // Re-fetch the authoritative list (picks up changes from other devices)
+    // and resync the authenticator with it.
+    try {
+      await loadPasskeys();
+    } catch {
+      // The delete itself succeeded; keep the locally updated list.
+    }
+    setStatus(`“${target.name?.trim() || 'Passkey'}” was deleted.`);
+  });
+});
+
+/* -------------------------------------------------------------- Setup */
+
+for (const dialog of [els.renameDialog, els.deleteDialog]) {
+  dialog.querySelector('[data-close]').addEventListener('click', () => dialog.close());
+  dialog.addEventListener('close', () => {
+    if (dialog === els.renameDialog) renameTarget = null;
+    else deleteTarget = null;
+  });
+}
+
+loadPasskeys().catch((err) => {
+  if (err.status === 401) return;
+  els.list.replaceChildren(el('li', {
+    className: 'empty-state',
+    textContent: 'We couldn’t load your passkeys.',
+  }));
+  els.list.setAttribute('aria-busy', 'false');
+  setStatus(err.message, 'error');
+});
