@@ -0,0 +1,312 @@
+import React, { useCallback, useEffect, useRef, useState } from 'react';
+import { KeyIcon, PencilSquareIcon, TrashIcon } from '@heroicons/react/24/outline';
+import { getPasskeyProvider } from '../lib/passkey-providers';
+import { signalAcceptedCredentials } from '../lib/passkey-signals';
+
+interface PasskeyCredential {
+  id: string;
+  name: string;
+  aaguid: string;
+  registeredAt: number;
+  lastUsedAt?: number;
+}
+
+interface CredentialListResponse {
+  rpId: string;
+  userId: string;
+  credentials: PasskeyCredential[];
+}
+
+const API_BASE = `${import.meta.env.BASE_URL}api/passkeys`;
+const MAX_NAME_LENGTH = 64;
+
+const dateFormatter = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+
+function formatDate(epochMs: number) {
+  return dateFormatter.format(new Date(epochMs));
+}
+
+async function readError(response: Response, fallback: string) {
+  const data = await response.json().catch(() => null);
+  return data?.error || fallback;
+}
+
+export default function PasskeyManager() {
+  const [credentials, setCredentials] = useState<PasskeyCredential[] | null>(null);
+  const [loadError, setLoadError] = useState<string | null>(null);
+  const [status, setStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [draftName, setDraftName] = useState('');
+  const [busyId, setBusyId] = useState<string | null>(null);
+  const [pendingDelete, setPendingDelete] = useState<PasskeyCredential | null>(null);
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  /** Apply a server list response and keep the passkey provider in sync. */
+  const applyList = useCallback(async (data: CredentialListResponse) => {
+    setCredentials(data.credentials);
+    await signalAcceptedCredentials(
+      data.rpId,
+      data.userId,
+      data.credentials.map((c) => c.id),
+    );
+  }, []);
+
+  useEffect(() => {
+    let cancelled = false;
+    (async () => {
+      try {
+        const response = await fetch(API_BASE, { headers: { Accept: 'application/json' } });
+        if (!response.ok) throw new Error(await readError(response, 'Could not load your passkeys.'));
+        const data: CredentialListResponse = await response.json();
+        if (!cancelled) await applyList(data);
+      } catch (e) {
+        if (!cancelled) setLoadError(e instanceof Error ? e.message : 'Could not load your passkeys.');
+      }
+    })();
+    return () => {
+      cancelled = true;
+    };
+  }, [applyList]);
+
+  const startEditing = (credential: PasskeyCredential) => {
+    setStatus(null);
+    setEditingId(credential.id);
+    setDraftName(credential.name);
+  };
+
+  const cancelEditing = () => {
+    setEditingId(null);
+    setDraftName('');
+  };
+
+  const handleRename = async (e: React.FormEvent, credential: PasskeyCredential) => {
+    e.preventDefault();
+    const name = draftName.trim();
+    if (!name) return;
+    if (name === credential.name) {
+      cancelEditing();
+      return;
+    }
+
+    setBusyId(credential.id);
+    setStatus(null);
+    try {
+      const response = await fetch(`${API_BASE}/${encodeURIComponent(credential.id)}`, {
+        method: 'PATCH',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ name }),
+      });
+      if (!response.ok) throw new Error(await readError(response, 'Could not rename the passkey.'));
+      // Renaming is a server-side label only; no Signal API call is needed.
+      const data: CredentialListResponse = await response.json();
+      setCredentials(data.credentials);
+      cancelEditing();
+      setStatus({ type: 'success', message: `Passkey renamed to “${name}”.` });
+    } catch (err) {
+      setStatus({ type: 'error', message: err instanceof Error ? err.message : 'Could not rename the passkey.' });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  const requestDelete = (credential: PasskeyCredential) => {
+    setStatus(null);
+    setPendingDelete(credential);
+    dialogRef.current?.showModal();
+  };
+
+  const handleDialogClose = async () => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const choice = dialog.returnValue;
+    // Esc / light dismiss set no value; reset so a stale value can't leak.
+    dialog.returnValue = '';
+    const credential = pendingDelete;
+    setPendingDelete(null);
+    if (choice !== 'remove' || !credential) return;
+
+    setBusyId(credential.id);
+    try {
+      const response = await fetch(`${API_BASE}/${encodeURIComponent(credential.id)}`, { method: 'DELETE' });
+      if (!response.ok) throw new Error(await readError(response, 'Could not remove the passkey.'));
+      const data: CredentialListResponse = await response.json();
+      // Sync the remaining credential IDs so the browser/password manager drops the removed passkey.
+      await applyList(data);
+      setStatus({ type: 'success', message: `“${credential.name}” was removed from your account.` });
+    } catch (err) {
+      setStatus({ type: 'error', message: err instanceof Error ? err.message : 'Could not remove the passkey.' });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  return (
+    <section aria-labelledby="passkeys-heading" className="border border-gray-200 rounded-lg p-6">
+      <div className="flex items-start gap-3 mb-4">
+        <KeyIcon className="w-6 h-6 text-gray-700 shrink-0 mt-0.5" aria-hidden="true" />
+        <div>
+          <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900">
+            Passkeys
+          </h2>
+          <p className="text-sm text-gray-600 mt-1">
+            Passkeys let you sign in with your fingerprint, face, screen lock or security key. Remove any you no
+            longer use — supported browsers and password managers will be updated to match.
+          </p>
+        </div>
+      </div>
+
+      <div role="status" aria-live="polite" className="empty:hidden mb-4">
+        {status && (
+          <p
+            className={`p-3 text-sm rounded-lg ${
+              status.type === 'success' ? 'text-green-800 bg-green-100' : 'text-red-700 bg-red-100'
+            }`}
+          >
+            {status.message}
+          </p>
+        )}
+      </div>
+
+      {loadError ? (
+        <p className="p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+          {loadError}
+        </p>
+      ) : credentials === null ? (
+        <p className="text-sm text-gray-500">Loading your passkeys…</p>
+      ) : credentials.length === 0 ? (
+        <p className="text-sm text-gray-600 bg-gray-50 border border-dashed border-gray-300 rounded-lg p-4 text-center">
+          No passkeys found for your account.
+        </p>
+      ) : (
+        <ul className="divide-y divide-gray-200 border border-gray-200 rounded-lg">
+          {credentials.map((credential) => {
+            const provider = getPasskeyProvider(credential.aaguid);
+            const isEditing = editingId === credential.id;
+            const isBusy = busyId === credential.id;
+            const inputId = `passkey-name-${credential.id}`;
+
+            return (
+              <li key={credential.id} className="flex flex-col sm:flex-row sm:items-center gap-3 p-4">
+                <img src={provider.icon} alt="" width={40} height={40} className="w-10 h-10 rounded-lg shrink-0" />
+
+                <div className="flex-1 min-w-0">
+                  {isEditing ? (
+                    <form onSubmit={(e) => handleRename(e, credential)} className="flex flex-wrap items-end gap-2">
+                      <div className="flex-1 min-w-48">
+                        <label htmlFor={inputId} className="block text-xs font-medium text-gray-700 mb-1">
+                          Passkey name
+                        </label>
+                        <input
+                          id={inputId}
+                          type="text"
+                          value={draftName}
+                          onChange={(e) => setDraftName(e.target.value)}
+                          onKeyDown={(e) => {
+                            if (e.key === 'Escape') cancelEditing();
+                          }}
+                          maxLength={MAX_NAME_LENGTH}
+                          required
+                          autoFocus
+                          autoComplete="off"
+                          className="w-full px-3 py-1.5 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-gray-900"
+                        />
+                      </div>
+                      <button
+                        type="submit"
+                        disabled={isBusy || !draftName.trim()}
+                        className="px-3 py-1.5 text-sm font-medium text-white bg-gray-900 rounded-md hover:bg-gray-800 disabled:opacity-60"
+                      >
+                        {isBusy ? 'Saving…' : 'Save'}
+                      </button>
+                      <button
+                        type="button"
+                        onClick={cancelEditing}
+                        className="px-3 py-1.5 text-sm font-medium text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50"
+                      >
+                        Cancel
+                      </button>
+                    </form>
+                  ) : (
+                    <>
+                      <p className="font-semibold text-gray-900 truncate">{credential.name}</p>
+                      {credential.name !== provider.name && (
+                        <p className="text-xs text-gray-500">{provider.name}</p>
+                      )}
+                      <p className="text-xs text-gray-500 mt-1">
+                        Created <time dateTime={new Date(credential.registeredAt).toISOString()}>{formatDate(credential.registeredAt)}</time>
+                        {' · '}
+                        {credential.lastUsedAt ? (
+                          <>
+                            Last used{' '}
+                            <time dateTime={new Date(credential.lastUsedAt).toISOString()}>
+                              {formatDate(credential.lastUsedAt)}
+                            </time>
+                          </>
+                        ) : (
+                          'Never used'
+                        )}
+                      </p>
+                    </>
+                  )}
+                </div>
+
+                {!isEditing && (
+                  <div className="flex gap-2 shrink-0">
+                    <button
+                      type="button"
+                      onClick={() => startEditing(credential)}
+                      disabled={isBusy}
+                      aria-label={`Rename ${credential.name}`}
+                      className="inline-flex items-center gap-1 px-3 py-1.5 text-sm font-medium text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-60"
+                    >
+                      <PencilSquareIcon className="w-4 h-4" aria-hidden="true" />
+                      Rename
+                    </button>
+                    <button
+                      type="button"
+                      onClick={() => requestDelete(credential)}
+                      disabled={isBusy}
+                      aria-label={`Remove ${credential.name}`}
+                      className="inline-flex items-center gap-1 px-3 py-1.5 text-sm font-medium text-red-700 border border-red-200 rounded-md hover:bg-red-50 disabled:opacity-60"
+                    >
+                      <TrashIcon className="w-4 h-4" aria-hidden="true" />
+                      {isBusy ? 'Removing…' : 'Remove'}
+                    </button>
+                  </div>
+                )}
+              </li>
+            );
+          })}
+        </ul>
+      )}
+
+      <dialog
+        ref={dialogRef}
+        onClose={handleDialogClose}
+        aria-labelledby="remove-passkey-title"
+        className="passkey-dialog m-auto max-w-md w-[calc(100%-2rem)] rounded-lg p-6 shadow-xl"
+        {...({ closedby: 'any' } as Record<string, string>)}
+      >
+        <h1 id="remove-passkey-title" className="text-lg font-bold text-gray-900">
+          Remove “{pendingDelete?.name}”?
+        </h1>
+        <p className="text-sm text-gray-600 mt-2">
+          You won’t be able to sign in to The DevTools Times with this passkey anymore. Supported browsers and
+          password managers will be told to remove it too.
+        </p>
+        {/* Cancel is the first focusable control, so showModal() focuses the safe action. */}
+        <form method="dialog" className="flex justify-end gap-2 mt-6">
+          <button
+            value="cancel"
+            className="px-4 py-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-md hover:bg-gray-50"
+          >
+            Cancel
+          </button>
+          <button value="remove" className="px-4 py-2 text-sm font-medium text-white bg-red-700 rounded-md hover:bg-red-800">
+            Remove passkey
+          </button>
+        </form>
+      </dialog>
+    </section>
+  );
+}
