+import React, { useState } from 'react';
+import { UserCircleIcon } from '@heroicons/react/24/outline';
+import { signalUserDetails } from '../lib/passkey-signals';
+
+interface Props {
+  initialName: string;
+  initialDisplayName: string;
+}
+
+export default function ProfileSettings({ initialName, initialDisplayName }: Props) {
+  const [name, setName] = useState(initialName);
+  const [displayName, setDisplayName] = useState(initialDisplayName);
+  const [saving, setSaving] = useState(false);
+  const [status, setStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
+
+  const handleSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setSaving(true);
+    setStatus(null);
+    try {
+      const response = await fetch(`${import.meta.env.BASE_URL}api/account`, {
+        method: 'PUT',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ name: name.trim(), displayName: displayName.trim() }),
+      });
+      const data = await response.json().catch(() => null);
+      if (!response.ok) throw new Error(data?.error || 'Could not update your profile.');
+
+      setName(data.name);
+      setDisplayName(data.displayName);
+      // Update the account name shown by the browser / password manager for these passkeys.
+      await signalUserDetails(data.rpId, data.userId, data.name, data.displayName);
+      setStatus({ type: 'success', message: 'Profile updated.' });
+    } catch (err) {
+      setStatus({ type: 'error', message: err instanceof Error ? err.message : 'Could not update your profile.' });
+    } finally {
+      setSaving(false);
+    }
+  };
+
+  return (
+    <section aria-labelledby="profile-heading" className="border border-gray-200 rounded-lg p-6">
+      <div className="flex items-start gap-3 mb-4">
+        <UserCircleIcon className="w-6 h-6 text-gray-700 shrink-0 mt-0.5" aria-hidden="true" />
+        <div>
+          <h2 id="profile-heading" className="text-xl font-bold text-gray-900">
+            Profile
+          </h2>
+          <p className="text-sm text-gray-600 mt-1">
+            These names are shown when you choose a passkey to sign in.
+          </p>
+        </div>
+      </div>
+
+      <form onSubmit={handleSubmit} className="grid gap-4 sm:grid-cols-2">
+        <div>
+          <label htmlFor="profile-username" className="block text-sm font-medium text-gray-700 mb-1">
+            Username
+          </label>
+          <input
+            id="profile-username"
+            type="text"
+            value={name}
+            onChange={(e) => setName(e.target.value)}
+            required
+            maxLength={64}
+            autoComplete="username"
+            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-gray-900"
+          />
+        </div>
+        <div>
+          <label htmlFor="profile-display-name" className="block text-sm font-medium text-gray-700 mb-1">
+            Display name
+          </label>
+          <input
+            id="profile-display-name"
+            type="text"
+            value={displayName}
+            onChange={(e) => setDisplayName(e.target.value)}
+            required
+            maxLength={64}
+            autoComplete="name"
+            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-gray-900"
+          />
+        </div>
+        <div className="sm:col-span-2 flex flex-wrap items-center gap-3">
+          <button
+            type="submit"
+            disabled={saving}
+            className="py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60"
+          >
+            {saving ? 'Saving…' : 'Save profile'}
+          </button>
+          <p role="status" aria-live="polite" className={`text-sm ${status?.type === 'error' ? 'text-red-700' : 'text-green-700'}`}>
+            {status?.message}
+          </p>
+        </div>
+      </form>
+    </section>
+  );
+}
