diff --git a/src/lib/account.ts b/src/lib/account.ts
new file mode 100644
index 0000000..2c15df3
--- /dev/null
+++ b/src/lib/account.ts
@@ -0,0 +1,135 @@
+import type { APIContext } from 'astro';
+
+/**
+ * Session-backed account + passkey store.
+ *
+ * The DevTools Times does not have its own user database (sign-in is proxied
+ * to an external API), so the signed-in reader's profile and their registered
+ * passkeys live in the Astro session. All IDs handed to the WebAuthn Signal API
+ * (`passkeyUserId`, credential `id`) are unpadded Base64URL strings.
+ */
+
+export interface StoredPasskeyCredential {
+  /** Credential ID, unpadded Base64URL. */
+  id: string;
+  /** User-facing nickname (defaults to the AAGUID provider name). */
+  name: string;
+  /** Authenticator model identifier, used only as a UX hint. */
+  aaguid: string;
+  /** Epoch milliseconds. */
+  registeredAt: number;
+  /** Epoch milliseconds, if the passkey has ever been used. */
+  lastUsedAt?: number;
+}
+
+export interface Account {
+  /** Username (WebAuthn `user.name`). */
+  name: string;
+  /** WebAuthn `user.displayName`. */
+  displayName: string;
+  /** WebAuthn `user.id`, unpadded Base64URL. */
+  passkeyUserId: string;
+  credentials: StoredPasskeyCredential[];
+}
+
+type Session = APIContext['session'];
+
+const SESSION_KEY = 'account';
+
+export const MAX_NAME_LENGTH = 64;
+
+/**
+ * Relying Party ID used when the passkeys were registered. Configurable via the
+ * PASSKEY_RP_ID env var; falls back to the request host on the server (never
+ * derived on the client).
+ */
+export function getRpId(url: URL): string {
+  return import.meta.env.PASSKEY_RP_ID || url.hostname;
+}
+
+export function toBase64Url(input: string | Uint8Array): string {
+  return Buffer.from(input).toString('base64url');
+}
+
+function randomBase64Url(bytes: number): string {
+  return toBase64Url(crypto.getRandomValues(new Uint8Array(bytes)));
+}
+
+const DAY = 24 * 60 * 60 * 1000;
+
+/** Demo passkeys seeded for a newly signed-in reader. */
+function seedCredentials(): StoredPasskeyCredential[] {
+  const now = Date.now();
+  return [
+    {
+      id: randomBase64Url(32),
+      name: 'Google Password Manager',
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      registeredAt: now - 120 * DAY,
+      lastUsedAt: now - 1 * DAY,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'iCloud Keychain',
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      registeredAt: now - 45 * DAY,
+      lastUsedAt: now - 12 * DAY,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'YubiKey 5 Series',
+      aaguid: 'cb69481e-8ff7-4039-93ec-0a2729a154a8',
+      registeredAt: now - 300 * DAY,
+    },
+  ];
+}
+
+export function createAccount(username: string): Account {
+  return {
+    name: username,
+    displayName: username,
+    passkeyUserId: randomBase64Url(16),
+    credentials: seedCredentials(),
+  };
+}
+
+export async function getAccount(session: Session): Promise<Account | undefined> {
+  if (!session) return undefined;
+  return ((await session.get(SESSION_KEY)) as Account | undefined) ?? undefined;
+}
+
+export async function saveAccount(session: Session, account: Account): Promise<void> {
+  await session?.set(SESSION_KEY, account);
+}
+
+export async function clearAccount(session: Session): Promise<void> {
+  session?.delete(SESSION_KEY);
+}
+
+/** Trim and validate a user-supplied label. Returns undefined when invalid. */
+export function sanitizeName(value: unknown): string | undefined {
+  if (typeof value !== 'string') return undefined;
+  const trimmed = value.trim();
+  if (!trimmed || trimmed.length > MAX_NAME_LENGTH) return undefined;
+  return trimmed;
+}
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function unauthorized(): Response {
+  return json({ error: 'You must be signed in.' }, 401);
+}
+
+/** Response shape for the credential list endpoint. */
+export function credentialListBody(account: Account, url: URL) {
+  return {
+    rpId: getRpId(url),
+    userId: account.passkeyUserId,
+    credentials: account.credentials,
+  };
+}
