+/**
+ * Small local subset of the community AAGUID registry
+ * (github.com/passkeydeveloper/passkey-authenticator-aaguids), used only as a
+ * UX hint to label passkeys by provider. Never use AAGUIDs for security
+ * decisions.
+ */
+
+export interface PasskeyProvider {
+  name: string;
+  icon: string;
+}
+
+function monogram(letter: string, background: string): string {
+  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="8" fill="${background}"/><text x="20" y="26.5" font-family="Arial,Helvetica,sans-serif" font-size="18" font-weight="700" fill="#fff" text-anchor="middle">${letter}</text></svg>`;
+  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
+}
+
+const PROVIDERS: Record<string, PasskeyProvider> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', icon: monogram('G', '#1a73e8') },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', icon: monogram('i', '#4b5563') },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', icon: monogram('1', '#0572ec') },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', icon: monogram('B', '#175ddc') },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', icon: monogram('W', '#0078d4') },
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': { name: 'YubiKey 5 Series', icon: monogram('Y', '#84bd00') },
+};
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+const UNKNOWN: PasskeyProvider = { name: 'Unknown passkey provider', icon: monogram('?', '#6b7280') };
+
+export function getPasskeyProvider(aaguid: string | undefined): PasskeyProvider {
+  if (!aaguid || aaguid === ZERO_AAGUID) return UNKNOWN;
+  return PROVIDERS[aaguid] ?? UNKNOWN;
+}
diff --git a/src/lib/passkey-signals.ts b/src/lib/passkey-signals.ts
