--- /dev/null
+++ b/src/lib/passkey-signals.ts
@@ -0,0 +1,84 @@
+/**
+ * Client-side helpers for keeping the reader's password manager / browser
+ * authenticator in sync with the server via the WebAuthn Signal API.
+ *
+ * The Signal API is a progressive enhancement (not available in every
+ * browser), so every call is feature-detected and failures are logged with
+ * console.warn rather than surfaced as errors.
+ */
+
+interface SignalAllAcceptedCredentialsOptions {
+  rpId: string;
+  userId: string;
+  allAcceptedCredentialIds: string[];
+}
+
+interface SignalCurrentUserDetailsOptions {
+  rpId: string;
+  userId: string;
+  name: string;
+  displayName: string;
+}
+
+type PublicKeyCredentialWithSignals = typeof PublicKeyCredential & {
+  signalAllAcceptedCredentials?: (options: SignalAllAcceptedCredentialsOptions) => Promise<void>;
+  signalCurrentUserDetails?: (options: SignalCurrentUserDetailsOptions) => Promise<void>;
+};
+
+function getPublicKeyCredential(): PublicKeyCredentialWithSignals | undefined {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) return undefined;
+  return window.PublicKeyCredential as PublicKeyCredentialWithSignals;
+}
+
+/** Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no padding, length % 4 !== 1. */
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+/**
+ * Tell the passkey provider which credential IDs are still valid for this
+ * user so it can hide/remove passkeys that were deleted on the server.
+ * `rpId` must come from the server, never from window.location.hostname.
+ */
+export async function signalAcceptedCredentials(
+  rpId: string,
+  userId: string,
+  credentialIds: string[],
+): Promise<void> {
+  const pkc = getPublicKeyCredential();
+  if (!pkc?.signalAllAcceptedCredentials) return;
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    await pkc.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: credentialIds });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+/** Tell the passkey provider about the reader's updated username / display name. */
+export async function signalUserDetails(
+  rpId: string,
+  userId: string,
+  name: string,
+  displayName: string,
+): Promise<void> {
+  const pkc = getPublicKeyCredential();
+  if (!pkc?.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await pkc.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
