+import type { APIRoute } from 'astro';
+import { getAccount, getRpId, json, sanitizeName, saveAccount, unauthorized } from '../../lib/account';
+
+/** Update the signed-in reader's username and display name. */
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  const account = await getAccount(session);
+  if (!account) return unauthorized();
+
+  const body = await request.json().catch(() => ({}));
+  const name = sanitizeName(body?.name);
+  const displayName = sanitizeName(body?.displayName);
+  if (!name || !displayName) {
+    return json({ error: 'Username and display name are required (max 64 characters).' }, 400);
+  }
+
+  account.name = name;
+  account.displayName = displayName;
+  await saveAccount(session, account);
+
+  return json({
+    name: account.name,
+    displayName: account.displayName,
+    rpId: getRpId(url),
+    userId: account.passkeyUserId,
+  });
+};
