+import type { APIRoute } from 'astro';
+import { credentialListBody, getAccount, json, sanitizeName, saveAccount, unauthorized } from '../../../lib/account';
+
+/** Rename a passkey (server-side label only). */
+export const PATCH: APIRoute = async ({ params, request, session, url }) => {
+  const account = await getAccount(session);
+  if (!account) return unauthorized();
+
+  const credential = account.credentials.find((c) => c.id === params.id);
+  if (!credential) return json({ error: 'Passkey not found.' }, 404);
+
+  const body = await request.json().catch(() => ({}));
+  const name = sanitizeName(body?.name);
+  if (!name) return json({ error: 'Enter a name between 1 and 64 characters.' }, 400);
+
+  credential.name = name;
+  await saveAccount(session, account);
+  return json(credentialListBody(account, url));
+};
+
+/** Remove a passkey from the account. */
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  const account = await getAccount(session);
+  if (!account) return unauthorized();
+
+  const before = account.credentials.length;
+  account.credentials = account.credentials.filter((c) => c.id !== params.id);
+  if (account.credentials.length === before) return json({ error: 'Passkey not found.' }, 404);
+
+  await saveAccount(session, account);
+  return json(credentialListBody(account, url));
+};
