+import type { APIRoute } from 'astro';
+import { clearAccount, createAccount, getAccount, json, sanitizeName, saveAccount } from '../../lib/account';
+
+/** Establish the local signed-in session after the upstream login succeeds. */
+export const POST: APIRoute = async ({ request, session }) => {
+  // Require a JSON body so cross-site "simple" form posts can't create a session.
+  if (!request.headers.get('content-type')?.includes('application/json')) {
+    return json({ error: 'Expected a JSON request body.' }, 415);
+  }
+  const body = await request.json().catch(() => ({}));
+  const username = sanitizeName(body?.username);
+  if (!username) {
+    return json({ error: 'A valid username is required.' }, 400);
+  }
+
+  const existing = await getAccount(session);
+  // Keep the same account (and passkeys) when the same reader signs in again.
+  const account = existing && existing.name === username ? existing : createAccount(username);
+  await session?.regenerate();
+  await saveAccount(session, account);
+
+  return json({ name: account.name, displayName: account.displayName });
+};
+
+export const DELETE: APIRoute = async ({ session }) => {
+  await clearAccount(session);
+  return json({ success: true });
+};
