+++ b/src/components/PasskeyManager.tsx
@@ -0,0 +1,654 @@
+import React, { useCallback, useEffect, useRef, useState } from 'react';
+import {
+  CheckIcon,
+  CloudIcon,
+  DevicePhoneMobileIcon,
+  ExclamationTriangleIcon,
+  FingerPrintIcon,
+  KeyIcon,
+  PencilSquareIcon,
+  PlusIcon,
+  TrashIcon,
+  XMarkIcon,
+} from '@heroicons/react/24/outline';
+
+interface Passkey {
+  id: string;
+  name: string;
+  algorithm: number | null;
+  transports: string[];
+  aaguid: string;
+  provider: string | null;
+  backupEligible: boolean;
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+interface PasskeyUser {
+  id: string;
+  name: string;
+  displayName: string;
+}
+
+interface PasskeyListResponse {
+  rpId: string;
+  user: PasskeyUser;
+  passkeys: Passkey[];
+}
+
+type Notice = { kind: 'success' | 'error' | 'info'; text: string } | null;
+
+const MAX_NAME_LENGTH = 64;
+
+/* ------------------------------------------------------------------ */
+/* WebAuthn helpers                                                   */
+/* ------------------------------------------------------------------ */
+
+// The WebAuthn Signal API isn't in every TS DOM lib yet.
+type SignalCapablePublicKeyCredential = typeof PublicKeyCredential & {
+  signalAllAcceptedCredentials?: (options: {
+    rpId: string;
+    userId: string;
+    allAcceptedCredentialIds: string[];
+  }) => Promise<void>;
+  signalCurrentUserDetails?: (options: {
+    rpId: string;
+    userId: string;
+    name: string;
+    displayName: string;
+  }) => Promise<void>;
+  parseCreationOptionsFromJSON?: (options: any) => PublicKeyCredentialCreationOptions;
+};
+
+function getPKC(): SignalCapablePublicKeyCredential | null {
+  if (typeof window === 'undefined' || !('PublicKeyCredential' in window)) return null;
+  return window.PublicKeyCredential as SignalCapablePublicKeyCredential;
+}
+
+function bufferToBase64Url(buffer: ArrayBuffer | null | undefined): string | null {
+  if (!buffer) return null;
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (const byte of bytes) binary += String.fromCharCode(byte);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function base64UrlToBuffer(value: string): ArrayBuffer {
+  const base64 = value.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(value.length / 4) * 4, '=');
+  const binary = atob(base64);
+  const bytes = new Uint8Array(binary.length);
+  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
+  return bytes.buffer;
+}
+
+function parseCreationOptions(json: any): PublicKeyCredentialCreationOptions {
+  const PKC = getPKC();
+  if (PKC?.parseCreationOptionsFromJSON) return PKC.parseCreationOptionsFromJSON(json);
+  return {
+    ...json,
+    challenge: base64UrlToBuffer(json.challenge),
+    user: { ...json.user, id: base64UrlToBuffer(json.user.id) },
+    excludeCredentials: (json.excludeCredentials ?? []).map((c: any) => ({ ...c, id: base64UrlToBuffer(c.id) })),
+  };
+}
+
+/** Tells the browser's passkey provider which credentials are still valid for this account. */
+async function signalAcceptedCredentials(rpId: string, userId: string, ids: string[]): Promise<boolean> {
+  const PKC = getPKC();
+  if (!PKC?.signalAllAcceptedCredentials) return false;
+  try {
+    await PKC.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: ids });
+    return true;
+  } catch (error) {
+    console.warn('signalAllAcceptedCredentials failed', error);
+    return false;
+  }
+}
+
+/** Tells the browser's passkey provider the account's current username and display name. */
+async function signalUserDetails(rpId: string, user: PasskeyUser): Promise<boolean> {
+  const PKC = getPKC();
+  if (!PKC?.signalCurrentUserDetails) return false;
+  try {
+    await PKC.signalCurrentUserDetails({ rpId, userId: user.id, name: user.name, displayName: user.displayName });
+    return true;
+  } catch (error) {
+    console.warn('signalCurrentUserDetails failed', error);
+    return false;
+  }
+}
+
+async function readError(response: Response, fallback: string): Promise<string> {
+  try {
+    const data = await response.json();
+    return data.error || fallback;
+  } catch {
+    return fallback;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Formatting                                                         */
+/* ------------------------------------------------------------------ */
+
+const dateFormatter = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+
+function formatDate(value: string | null): string {
+  if (!value) return 'Never';
+  const date = new Date(value);
+  return Number.isNaN(date.getTime()) ? 'Unknown' : dateFormatter.format(date);
+}
+
+const TRANSPORT_LABELS: Record<string, string> = {
+  internal: 'This device',
+  hybrid: 'Phone / tablet',
+  cable: 'Phone / tablet',
+  usb: 'USB',
+  nfc: 'NFC',
+  ble: 'Bluetooth',
+  'smart-card': 'Smart card',
+};
+
+/* ------------------------------------------------------------------ */
+/* Component                                                          */
+/* ------------------------------------------------------------------ */
+
+interface Props {
+  apiBase: string;
+}
+
+export default function PasskeyManager({ apiBase }: Props) {
+  const [data, setData] = useState<PasskeyListResponse | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [loadError, setLoadError] = useState<string | null>(null);
+  const [notice, setNotice] = useState<Notice>(null);
+  const [busyId, setBusyId] = useState<string | null>(null);
+  const [creating, setCreating] = useState(false);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [draftName, setDraftName] = useState('');
+  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
+  const [displayNameDraft, setDisplayNameDraft] = useState('');
+  const [savingDisplayName, setSavingDisplayName] = useState(false);
+  const [webAuthnSupported, setWebAuthnSupported] = useState(true);
+  const [signalSupported, setSignalSupported] = useState(false);
+  const editInputRef = useRef<HTMLInputElement>(null);
+
+  const endpoint = `${apiBase}api/account/passkeys`;
+
+  const load = useCallback(async () => {
+    setLoading(true);
+    setLoadError(null);
+    try {
+      const response = await fetch(endpoint, { headers: { Accept: 'application/json' } });
+      if (!response.ok) throw new Error(await readError(response, 'Could not load your passkeys.'));
+      const result: PasskeyListResponse = await response.json();
+      setData(result);
+      setDisplayNameDraft(result.user.displayName);
+
+      // Keep the browser's passkey provider in sync with what the server knows about,
+      // e.g. after a passkey was removed from another device.
+      await Promise.all([
+        signalAcceptedCredentials(result.rpId, result.user.id, result.passkeys.map((p) => p.id)),
+        signalUserDetails(result.rpId, result.user),
+      ]);
+    } catch (error) {
+      setLoadError((error as Error).message);
+    } finally {
+      setLoading(false);
+    }
+  }, [endpoint]);
+
+  useEffect(() => {
+    const PKC = getPKC();
+    setWebAuthnSupported(Boolean(PKC && navigator.credentials?.create));
+    setSignalSupported(Boolean(PKC?.signalAllAcceptedCredentials && PKC?.signalCurrentUserDetails));
+    load();
+  }, [load]);
+
+  useEffect(() => {
+    if (editingId) editInputRef.current?.focus();
+  }, [editingId]);
+
+  /* ----------------------------- Create ----------------------------- */
+
+  const createPasskey = async () => {
+    if (!data) return;
+    setNotice(null);
+    setCreating(true);
+    try {
+      const optionsResponse = await fetch(`${endpoint}/options`, { method: 'POST' });
+      if (!optionsResponse.ok) throw new Error(await readError(optionsResponse, 'Could not start passkey setup.'));
+      const publicKey = parseCreationOptions(await optionsResponse.json());
+
+      const credential = (await navigator.credentials.create({ publicKey })) as PublicKeyCredential | null;
+      if (!credential) throw new Error('No passkey was created.');
+      const response = credential.response as AuthenticatorAttestationResponse;
+
+      const registerResponse = await fetch(endpoint, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          id: credential.id,
+          clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+          authenticatorData: bufferToBase64Url(response.getAuthenticatorData?.()),
+          publicKey: bufferToBase64Url(response.getPublicKey?.()),
+          publicKeyAlgorithm: response.getPublicKeyAlgorithm?.() ?? null,
+          transports: response.getTransports?.() ?? [],
+        }),
+      });
+
+      if (!registerResponse.ok) {
+        const message = await readError(registerResponse, 'Could not save your passkey.');
+        // The authenticator now holds a credential we rejected — tell it to drop it.
+        await signalAcceptedCredentials(data.rpId, data.user.id, data.passkeys.map((p) => p.id));
+        throw new Error(message);
+      }
+
+      const { passkey } = (await registerResponse.json()) as { passkey: Passkey };
+      setData((prev) => (prev ? { ...prev, passkeys: [...prev.passkeys, passkey] } : prev));
+      setNotice({ kind: 'success', text: `Passkey “${passkey.name}” was added. You can rename it at any time.` });
+    } catch (error) {
+      const err = error as DOMException;
+      if (err.name === 'NotAllowedError' || err.name === 'AbortError') {
+        setNotice({ kind: 'info', text: 'Passkey setup was cancelled.' });
+      } else if (err.name === 'InvalidStateError') {
+        setNotice({ kind: 'info', text: 'A passkey for this account already exists on this authenticator.' });
+      } else {
+        setNotice({ kind: 'error', text: err.message || 'Passkey setup failed.' });
+      }
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  /* ----------------------------- Rename ----------------------------- */
+
+  const startEditing = (passkey: Passkey) => {
+    setConfirmDeleteId(null);
+    setEditingId(passkey.id);
+    setDraftName(passkey.name);
+    setNotice(null);
+  };
+
+  const cancelEditing = () => {
+    setEditingId(null);
+    setDraftName('');
+  };
+
+  const saveName = async (passkey: Passkey) => {
+    const name = draftName.trim();
+    if (!name) {
+      setNotice({ kind: 'error', text: 'Passkey names cannot be empty.' });
+      return;
+    }
+    if (name === passkey.name) {
+      cancelEditing();
+      return;
+    }
+
+    setBusyId(passkey.id);
+    try {
+      const response = await fetch(`${endpoint}/${encodeURIComponent(passkey.id)}`, {
+        method: 'PATCH',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ name }),
+      });
+      if (!response.ok) throw new Error(await readError(response, 'Could not rename the passkey.'));
+      const { passkey: updated } = (await response.json()) as { passkey: Passkey };
+      setData((prev) =>
+        prev ? { ...prev, passkeys: prev.passkeys.map((p) => (p.id === updated.id ? updated : p)) } : prev,
+      );
+      setNotice({ kind: 'success', text: `Passkey renamed to “${updated.name}”.` });
+      cancelEditing();
+    } catch (error) {
+      setNotice({ kind: 'error', text: (error as Error).message });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  /* ----------------------------- Delete ----------------------------- */
+
+  const deletePasskey = async (passkey: Passkey) => {
+    if (!data) return;
+    setBusyId(passkey.id);
+    setNotice(null);
+    try {
+      const response = await fetch(`${endpoint}/${encodeURIComponent(passkey.id)}`, { method: 'DELETE' });
+      if (!response.ok) throw new Error(await readError(response, 'Could not remove the passkey.'));
+      const { acceptedCredentialIds } = (await response.json()) as { acceptedCredentialIds: string[] };
+
+      setData((prev) => (prev ? { ...prev, passkeys: prev.passkeys.filter((p) => p.id !== passkey.id) } : prev));
+      setConfirmDeleteId(null);
+
+      const synced = await signalAcceptedCredentials(data.rpId, data.user.id, acceptedCredentialIds);
+      setNotice({
+        kind: 'success',
+        text: synced
+          ? `“${passkey.name}” was removed and your passkey manager was asked to delete it too.`
+          : `“${passkey.name}” was removed. You may also want to delete it from your password manager or device settings.`,
+      });
+    } catch (error) {
+      setNotice({ kind: 'error', text: (error as Error).message });
+    } finally {
+      setBusyId(null);
+    }
+  };
+
+  /* -------------------------- Display name -------------------------- */
+
+  const saveDisplayName = async (event: React.FormEvent) => {
+    event.preventDefault();
+    if (!data) return;
+    const displayName = displayNameDraft.trim();
+    if (!displayName || displayName === data.user.displayName) return;
+
+    setSavingDisplayName(true);
+    setNotice(null);
+    try {
+      const response = await fetch(`${apiBase}api/account/profile`, {
+        method: 'PATCH',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ displayName }),
+      });
+      if (!response.ok) throw new Error(await readError(response, 'Could not update your display name.'));
+      const result = (await response.json()) as { displayName: string };
+      const user = { ...data.user, displayName: result.displayName };
+      setData({ ...data, user });
+      setDisplayNameDraft(result.displayName);
+
+      const synced = await signalUserDetails(data.rpId, user);
+      setNotice({
+        kind: 'success',
+        text: synced
+          ? 'Display name updated. Your passkey manager will show the new name.'
+          : 'Display name updated.',
+      });
+    } catch (error) {
+      setNotice({ kind: 'error', text: (error as Error).message });
+    } finally {
+      setSavingDisplayName(false);
+    }
+  };
+
+  /* ----------------------------- Render ----------------------------- */
+
+  if (loading && !data) {
+    return (
+      <div className="space-y-3" aria-busy="true" aria-live="polite">
+        <span className="sr-only">Loading passkeys…</span>
+        {[0, 1].map((i) => (
+          <div key={i} className="h-20 rounded-lg bg-gray-100 animate-pulse" />
+        ))}
+      </div>
+    );
+  }
+
+  if (loadError || !data) {
+    return (
+      <div className="p-4 text-sm text-red-700 bg-red-50 border border-red-200 rounded-lg" role="alert">
+        <p className="font-semibold">We couldn't load your passkeys.</p>
+        <p className="mt-1">{loadError}</p>
+        <button type="button" onClick={load} className="mt-3 text-sm font-semibold underline hover:no-underline">
+          Try again
+        </button>
+      </div>
+    );
+  }
+
+  const { passkeys } = data;
+
+  return (
+    <div className="space-y-6">
+      {/* Notices */}
+      <div aria-live="polite">
+        {notice && (
+          <div
+            role={notice.kind === 'error' ? 'alert' : 'status'}
+            className={`flex items-start gap-2 p-3 text-sm rounded-lg ${
+              notice.kind === 'success'
+                ? 'text-green-800 bg-green-50 border border-green-200'
+                : notice.kind === 'error'
+                  ? 'text-red-800 bg-red-50 border border-red-200'
+                  : 'text-gray-800 bg-gray-50 border border-gray-200'
+            }`}
+          >
+            <span className="flex-1">{notice.text}</span>
+            <button type="button" onClick={() => setNotice(null)} aria-label="Dismiss message" className="shrink-0">
+              <XMarkIcon className="w-4 h-4" />
+            </button>
+          </div>
+        )}
+      </div>
+
+      {!webAuthnSupported && (
+        <div className="flex gap-2 p-3 text-sm text-amber-900 bg-amber-50 border border-amber-200 rounded-lg">
+          <ExclamationTriangleIcon className="w-5 h-5 shrink-0" />
+          <p>This browser doesn't support passkeys. You can still rename or remove existing passkeys.</p>
+        </div>
+      )}
+
+      {/* Passkey list */}
+      <div>
+        <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
+          <h3 className="text-sm font-bold uppercase tracking-wider text-gray-700">
+            Your passkeys <span className="font-normal text-gray-500">({passkeys.length})</span>
+          </h3>
+          <button
+            type="button"
+            onClick={createPasskey}
+            disabled={!webAuthnSupported || creating}
+            className="inline-flex items-center gap-1.5 py-2 px-3 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
+          >
+            <PlusIcon className="w-4 h-4" />
+            {creating ? 'Waiting for authenticator…' : 'Create a passkey'}
+          </button>
+        </div>
+
+        {passkeys.length === 0 ? (
+          <div className="flex flex-col items-center text-center p-8 border border-dashed border-gray-300 rounded-lg">
+            <FingerPrintIcon className="w-10 h-10 text-gray-400" />
+            <p className="mt-3 font-semibold text-gray-800">No passkeys yet</p>
+            <p className="mt-1 max-w-sm text-sm text-gray-600">
+              Passkeys let you sign in with your fingerprint, face, or screen lock instead of a password.
+            </p>
+          </div>
+        ) : (
+          <ul className="divide-y divide-gray-200 border border-gray-200 rounded-lg">
+            {passkeys.map((passkey) => {
+              const isEditing = editingId === passkey.id;
+              const isConfirmingDelete = confirmDeleteId === passkey.id;
+              const isBusy = busyId === passkey.id;
+              const transportLabels = [...new Set(passkey.transports.map((t) => TRANSPORT_LABELS[t] ?? t))];
+
+              return (
+                <li key={passkey.id} className="p-4">
+                  <div className="flex items-start gap-3">
+                    <div className="mt-0.5 p-2 rounded-full bg-gray-100 text-gray-700">
+                      {passkey.backupEligible ? (
+                        <CloudIcon className="w-5 h-5" aria-hidden="true" />
+                      ) : (
+                        <KeyIcon className="w-5 h-5" aria-hidden="true" />
+                      )}
+                    </div>
+
+                    <div className="flex-1 min-w-0">
+                      {isEditing ? (
+                        <form
+                          className="flex flex-wrap items-center gap-2"
+                          onSubmit={(e) => {
+                            e.preventDefault();
+                            saveName(passkey);
+                          }}
+                        >
+                          <label htmlFor={`passkey-name-${passkey.id}`} className="sr-only">
+                            Passkey name
+                          </label>
+                          <input
+                            ref={editInputRef}
+                            id={`passkey-name-${passkey.id}`}
+                            type="text"
+                            value={draftName}
+                            maxLength={MAX_NAME_LENGTH}
+                            onChange={(e) => setDraftName(e.target.value)}
+                            onKeyDown={(e) => e.key === 'Escape' && cancelEditing()}
+                            disabled={isBusy}
+                            className="flex-1 min-w-[12rem] px-2 py-1 text-sm border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-gray-900"
+                          />
+                          <button
+                            type="submit"
+                            disabled={isBusy || !draftName.trim()}
+                            className="inline-flex items-center gap-1 py-1 px-2 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-700 disabled:opacity-50"
+                          >
+                            <CheckIcon className="w-4 h-4" /> Save
+                          </button>
+                          <button
+                            type="button"
+                            onClick={cancelEditing}
+                            disabled={isBusy}
+                            className="py-1 px-2 text-xs font-semibold text-gray-700 border border-gray-300 rounded hover:bg-gray-50"
+                          >
+                            Cancel
+                          </button>
+                        </form>
+                      ) : (
+                        <p className="font-semibold text-gray-900 break-words">{passkey.name}</p>
+                      )}
+
+                      <dl className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-600">
+                        {passkey.provider && (
+                          <div>
+                            <dt className="sr-only">Stored in</dt>
+                            <dd>{passkey.provider}</dd>
+                          </div>
+                        )}
+                        <div>
+                          <dt className="inline">Created </dt>
+                          <dd className="inline">{formatDate(passkey.createdAt)}</dd>
+                        </div>
+                        <div>
+                          <dt className="inline">Last used </dt>
+                          <dd className="inline">{formatDate(passkey.lastUsedAt)}</dd>
+                        </div>
+                        <div>
+                          <dt className="sr-only">Sync status</dt>
+                          <dd>
+                            {passkey.backedUp
+                              ? 'Synced across devices'
+                              : passkey.backupEligible
+                                ? 'Can sync across devices'
+                                : 'Stays on one device'}
+                          </dd>
+                        </div>
+                        {transportLabels.length > 0 && (
+                          <div className="inline-flex items-center gap-1">
+                            <dt>
+                              <DevicePhoneMobileIcon className="w-3.5 h-3.5" aria-label="Available via" />
+                            </dt>
+                            <dd>{transportLabels.join(', ')}</dd>
+                          </div>
+                        )}
+                      </dl>
+
+                      {isConfirmingDelete && (
+                        <div className="mt-3 p-3 text-sm bg-red-50 border border-red-200 rounded" role="alertdialog" aria-labelledby={`confirm-${passkey.id}`}>
+                          <p id={`confirm-${passkey.id}`} className="text-red-900">
+                            Remove “{passkey.name}”? You won't be able to sign in with it anymore.
+                            {signalSupported && ' We\'ll also ask your browser to remove it from your passkey manager.'}
+                          </p>
+                          <div className="mt-2 flex gap-2">
+                            <button
+                              type="button"
+                              onClick={() => deletePasskey(passkey)}
+                              disabled={isBusy}
+                              className="py-1 px-3 text-xs font-semibold text-white bg-red-700 rounded hover:bg-red-600 disabled:opacity-50"
+                            >
+                              {isBusy ? 'Removing…' : 'Remove passkey'}
+                            </button>
+                            <button
+                              type="button"
+                              onClick={() => setConfirmDeleteId(null)}
+                              disabled={isBusy}
+                              className="py-1 px-3 text-xs font-semibold text-gray-700 bg-white border border-gray-300 rounded hover:bg-gray-50"
+                            >
+                              Keep it
+                            </button>
+                          </div>
+                        </div>
+                      )}
+                    </div>
+
+                    {!isEditing && !isConfirmingDelete && (
+                      <div className="flex shrink-0 gap-1">
+                        <button
+                          type="button"
+                          onClick={() => startEditing(passkey)}
+                          disabled={isBusy}
+                          className="p-2 text-gray-600 rounded hover:bg-gray-100 hover:text-gray-900"
+                          aria-label={`Rename ${passkey.name}`}
+                          title="Rename"
+                        >
+                          <PencilSquareIcon className="w-5 h-5" />
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => {
+                            cancelEditing();
+                            setConfirmDeleteId(passkey.id);
+                          }}
+                          disabled={isBusy}
+                          className="p-2 text-gray-600 rounded hover:bg-red-50 hover:text-red-700"
+                          aria-label={`Remove ${passkey.name}`}
+                          title="Remove"
+                        >
+                          <TrashIcon className="w-5 h-5" />
+                        </button>
+                      </div>
+                    )}
+                  </div>
+                </li>
+              );
+            })}
+          </ul>
+        )}
+      </div>
+
+      {/* Account name shown by passkey managers */}
+      <form onSubmit={saveDisplayName} className="p-4 bg-gray-50 border border-gray-200 rounded-lg">
+        <label htmlFor="passkey-display-name" className="block text-sm font-semibold text-gray-800">
+          Name shown in your passkey manager
+        </label>
+        <p className="mt-0.5 text-xs text-gray-600">
+          Signed in as <span className="font-mono">{data.user.name}</span>. Changing your display name updates how this
+          account appears when you pick a passkey.
+        </p>
+        <div className="mt-2 flex flex-wrap gap-2">
+          <input
+            id="passkey-display-name"
+            type="text"
+            value={displayNameDraft}
+            maxLength={MAX_NAME_LENGTH}
+            onChange={(e) => setDisplayNameDraft(e.target.value)}
+            className="flex-1 min-w-[12rem] px-3 py-1.5 text-sm border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-gray-900"
+          />
+          <button
+            type="submit"
+            disabled={
+              savingDisplayName || !displayNameDraft.trim() || displayNameDraft.trim() === data.user.displayName
+            }
+            className="py-1.5 px-3 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
+          >
+            {savingDisplayName ? 'Saving…' : 'Update name'}
+          </button>
+        </div>
+      </form>
+
+      <p className="text-xs text-gray-500">
+        {signalSupported
+          ? 'Your browser supports passkey syncing: changes made here are automatically shared with your passkey manager.'
+          : 'Your browser can\'t sync passkey changes automatically. After removing a passkey here, also delete it from your password manager or device settings.'}
+      </p>
+    </div>
+  );
+}
