diff --git a/src/lib/account.ts b/src/lib/account.ts
new file mode 100644
index 0000000..de9c3c2
--- /dev/null
+++ b/src/lib/account.ts
@@ -0,0 +1,226 @@
+import type { APIContext } from 'astro';
+
+/**
+ * Account + passkey storage for The DevTools Times.
+ *
+ * The reader's account record (including their registered passkeys) lives in
+ * the Astro server session, alongside the reading list.
+ */
+
+export interface StoredPasskey {
+  /** base64url-encoded credential ID */
+  id: string;
+  /** Reader-chosen label, only stored on our side (authenticators don't keep it). */
+  name: string;
+  /** base64url-encoded SPKI public key, as returned by `getPublicKey()` */
+  publicKey: string | null;
+  /** COSE algorithm identifier, e.g. -7 (ES256) or -257 (RS256) */
+  algorithm: number | null;
+  transports: string[];
+  aaguid: string;
+  /** Whether the credential is eligible for backup (multi-device / synced passkey). */
+  backupEligible: boolean;
+  /** Whether the credential is currently backed up. */
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+export interface Account {
+  username: string;
+  displayName: string;
+  /** base64url-encoded WebAuthn user handle (user.id) — random, not PII. */
+  userHandle: string;
+  passkeys: StoredPasskey[];
+}
+
+/** Public shape of a passkey sent to the browser. */
+export type PasskeySummary = Omit<StoredPasskey, 'publicKey'> & { provider: string | null };
+
+type Session = NonNullable<APIContext['session']>;
+
+export const ACCOUNT_SESSION_KEY = 'account';
+export const REGISTRATION_CHALLENGE_KEY = 'passkeyRegistrationChallenge';
+
+export const MAX_PASSKEY_NAME_LENGTH = 64;
+export const MAX_DISPLAY_NAME_LENGTH = 64;
+
+export async function getAccount(session: Session | undefined): Promise<Account | null> {
+  if (!session) return null;
+  const account = (await session.get(ACCOUNT_SESSION_KEY)) as Account | undefined;
+  return account ?? null;
+}
+
+export async function saveAccount(session: Session, account: Account): Promise<void> {
+  await session.set(ACCOUNT_SESSION_KEY, account);
+}
+
+export function createAccount(username: string): Account {
+  return {
+    username,
+    displayName: username,
+    userHandle: toBase64Url(crypto.getRandomValues(new Uint8Array(32))),
+    passkeys: [],
+  };
+}
+
+/* ------------------------------------------------------------------ */
+/* Encoding helpers                                                   */
+/* ------------------------------------------------------------------ */
+
+export function toBase64Url(bytes: Uint8Array | ArrayBuffer): string {
+  const buf = Buffer.from(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes));
+  return buf.toString('base64url');
+}
+
+export function fromBase64Url(value: string): Uint8Array {
+  return new Uint8Array(Buffer.from(value, 'base64url'));
+}
+
+export function isBase64Url(value: unknown, maxLength = 2048): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length <= maxLength && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+/* ------------------------------------------------------------------ */
+/* Input sanitising                                                   */
+/* ------------------------------------------------------------------ */
+
+export function cleanLabel(value: unknown, maxLength: number): string | null {
+  if (typeof value !== 'string') return null;
+  // Collapse whitespace and strip control characters.
+  const cleaned = value.replace(/[\u0000-\u001f\u007f]/g, '').replace(/\s+/g, ' ').trim();
+  if (!cleaned || cleaned.length > maxLength) return null;
+  return cleaned;
+}
+
+/* ------------------------------------------------------------------ */
+/* Relying party                                                      */
+/* ------------------------------------------------------------------ */
+
+/** The RP ID is the effective domain the app is served from. */
+export function getRpId(url: URL): string {
+  return url.hostname;
+}
+
+export const RP_NAME = 'The DevTools Times';
+
+/** Accept origins whose host is the RP ID or a subdomain of it. */
+export function isAllowedOrigin(origin: string, rpId: string): boolean {
+  try {
+    const { protocol, hostname } = new URL(origin);
+    const secure = protocol === 'https:' || hostname === 'localhost' || hostname === '127.0.0.1';
+    return secure && (hostname === rpId || hostname.endsWith(`.${rpId}`));
+  } catch {
+    return false;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Authenticator providers (by AAGUID)                                */
+/* ------------------------------------------------------------------ */
+
+const KNOWN_AAGUIDS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  'f3809540-7f14-49c1-a8b3-8f813b225541': 'Enpass',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': 'YubiKey 5 Series',
+  'ee882879-721c-4913-9775-3dfcce97072a': 'YubiKey 5 Series',
+  'fa2b99dc-9e39-4257-8f92-4a30d23c4118': 'YubiKey 5 Series (NFC)',
+};
+
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export function providerForAaguid(aaguid: string): string | null {
+  return KNOWN_AAGUIDS[aaguid.toLowerCase()] ?? null;
+}
+
+export function toSummary(passkey: StoredPasskey): PasskeySummary {
+  const { publicKey: _publicKey, ...rest } = passkey;
+  return { ...rest, provider: providerForAaguid(passkey.aaguid) };
+}
+
+/* ------------------------------------------------------------------ */
+/* Authenticator data parsing                                         */
+/* ------------------------------------------------------------------ */
+
+export interface ParsedAuthenticatorData {
+  rpIdHash: Uint8Array;
+  userPresent: boolean;
+  userVerified: boolean;
+  backupEligible: boolean;
+  backedUp: boolean;
+  signCount: number;
+  aaguid: string | null;
+  credentialId: Uint8Array | null;
+}
+
+/**
+ * Parses the fixed-layout prefix of WebAuthn authenticator data:
+ * rpIdHash (32) | flags (1) | signCount (4) | [aaguid (16) | credIdLen (2) | credId (L) | ...]
+ */
+export function parseAuthenticatorData(data: Uint8Array): ParsedAuthenticatorData {
+  if (data.length < 37) throw new Error('Authenticator data is too short.');
+  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
+  const flags = data[32];
+  const attestedCredentialData = (flags & 0x40) !== 0;
+
+  let aaguid: string | null = null;
+  let credentialId: Uint8Array | null = null;
+  if (attestedCredentialData) {
+    if (data.length < 55) throw new Error('Attested credential data is truncated.');
+    const hex = Buffer.from(data.subarray(37, 53)).toString('hex');
+    aaguid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+    const idLength = view.getUint16(53);
+    if (data.length < 55 + idLength) throw new Error('Credential ID is truncated.');
+    credentialId = data.slice(55, 55 + idLength);
+  }
+
+  return {
+    rpIdHash: data.slice(0, 32),
+    userPresent: (flags & 0x01) !== 0,
+    userVerified: (flags & 0x04) !== 0,
+    backupEligible: (flags & 0x08) !== 0,
+    backedUp: (flags & 0x10) !== 0,
+    signCount: view.getUint32(33),
+    aaguid,
+    credentialId,
+  };
+}
+
+export async function sha256(data: Uint8Array | string): Promise<Uint8Array> {
+  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
+  return new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
+}
+
+export function bytesEqual(a: Uint8Array, b: Uint8Array): boolean {
+  if (a.length !== b.length) return false;
+  let diff = 0;
+  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
+  return diff === 0;
+}
+
+/* ------------------------------------------------------------------ */
+/* Responses                                                          */
+/* ------------------------------------------------------------------ */
+
+export function json(body: unknown, init: ResponseInit = {}): Response {
+  return new Response(JSON.stringify(body), {
+    ...init,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...(init.headers ?? {}) },
+  });
+}
+
+export function unauthorized(): Response {
+  return json({ error: 'You need to be signed in to manage passkeys.' }, { status: 401 });
+}
