+import type { APIRoute } from 'astro';
+import {
+  MAX_PASSKEY_NAME_LENGTH,
+  cleanLabel,
+  getAccount,
+  isBase64Url,
+  json,
+  saveAccount,
+  toSummary,
+  unauthorized,
+} from '../../../../lib/account';
+
+function notFound() {
+  return json({ error: 'Passkey not found.' }, { status: 404 });
+}
+
+/** Renames a passkey. */
+export const PATCH: APIRoute = async ({ params, request, session }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+  if (!isBase64Url(params.id)) return notFound();
+
+  const passkey = account.passkeys.find((p) => p.id === params.id);
+  if (!passkey) return notFound();
+
+  const body = await request.json().catch(() => null);
+  const name = cleanLabel(body?.name, MAX_PASSKEY_NAME_LENGTH);
+  if (!name) {
+    return json({ error: `Passkey names must be 1–${MAX_PASSKEY_NAME_LENGTH} characters.` }, { status: 400 });
+  }
+
+  passkey.name = name;
+  await saveAccount(session, account);
+  return json({ passkey: toSummary(passkey) });
+};
+
+/** Removes a passkey. Returns the remaining credential IDs so the client can signal them to the authenticator. */
+export const DELETE: APIRoute = async ({ params, session }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+  if (!isBase64Url(params.id)) return notFound();
+
+  const before = account.passkeys.length;
+  account.passkeys = account.passkeys.filter((p) => p.id !== params.id);
+  if (account.passkeys.length === before) return notFound();
+
+  await saveAccount(session, account);
+  return json({ acceptedCredentialIds: account.passkeys.map((p) => p.id) });
+};
