@@ -0,0 +1,127 @@
+import type { APIRoute } from 'astro';
+import {
+  MAX_PASSKEY_NAME_LENGTH,
+  REGISTRATION_CHALLENGE_KEY,
+  ZERO_AAGUID,
+  bytesEqual,
+  cleanLabel,
+  fromBase64Url,
+  getAccount,
+  getRpId,
+  isAllowedOrigin,
+  isBase64Url,
+  json,
+  parseAuthenticatorData,
+  providerForAaguid,
+  saveAccount,
+  sha256,
+  toBase64Url,
+  toSummary,
+  unauthorized,
+  type StoredPasskey,
+} from '../../../../lib/account';
+
+const ALLOWED_TRANSPORTS = new Set(['ble', 'cable', 'hybrid', 'internal', 'nfc', 'smart-card', 'usb']);
+
+/** Lists the signed-in reader's passkeys plus the data needed for the WebAuthn Signal API. */
+export const GET: APIRoute = async ({ session, url }) => {
+  const account = await getAccount(session);
+  if (!account) return unauthorized();
+
+  return json({
+    rpId: getRpId(url),
+    user: { id: account.userHandle, name: account.username, displayName: account.displayName },
+    passkeys: account.passkeys.map(toSummary),
+  });
+};
+
+/**
+ * Registers a new passkey from a `navigator.credentials.create()` result.
+ *
+ * Verifies the challenge, origin, ceremony type, RP ID hash, user presence and
+ * that the credential ID in the authenticator data matches the one reported.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+
+  const pending = (await session.get(REGISTRATION_CHALLENGE_KEY)) as { challenge: string; expires: number } | undefined;
+  session.delete(REGISTRATION_CHALLENGE_KEY);
+  if (!pending || pending.expires < Date.now()) {
+    return json({ error: 'The registration request expired. Please try again.' }, { status: 400 });
+  }
+
+  const body = await request.json().catch(() => null);
+  const { id, clientDataJSON, authenticatorData, publicKey, publicKeyAlgorithm, transports } = body ?? {};
+  if (!isBase64Url(id) || !isBase64Url(clientDataJSON, 8192) || !isBase64Url(authenticatorData, 8192)) {
+    return json({ error: 'Malformed passkey response.' }, { status: 400 });
+  }
+
+  const rpId = getRpId(url);
+
+  // Client data checks
+  let clientData: { type?: string; challenge?: string; origin?: string };
+  try {
+    clientData = JSON.parse(new TextDecoder().decode(fromBase64Url(clientDataJSON)));
+  } catch {
+    return json({ error: 'Malformed client data.' }, { status: 400 });
+  }
+  if (clientData.type !== 'webauthn.create') {
+    return json({ error: 'Unexpected ceremony type.' }, { status: 400 });
+  }
+  if (clientData.challenge !== pending.challenge) {
+    return json({ error: 'Challenge mismatch.' }, { status: 400 });
+  }
+  if (!clientData.origin || !isAllowedOrigin(clientData.origin, rpId)) {
+    return json({ error: 'Unexpected origin.' }, { status: 400 });
+  }
+
+  // Authenticator data checks
+  let authData;
+  try {
+    authData = parseAuthenticatorData(fromBase64Url(authenticatorData));
+  } catch (error) {
+    return json({ error: (error as Error).message }, { status: 400 });
+  }
+  if (!bytesEqual(authData.rpIdHash, await sha256(rpId))) {
+    return json({ error: 'RP ID mismatch.' }, { status: 400 });
+  }
+  if (!authData.userPresent) {
+    return json({ error: 'User presence is required.' }, { status: 400 });
+  }
+  if (!authData.credentialId || toBase64Url(authData.credentialId) !== id) {
+    return json({ error: 'Credential ID mismatch.' }, { status: 400 });
+  }
+  if (account.passkeys.some((p) => p.id === id)) {
+    return json({ error: 'This passkey is already registered.' }, { status: 409 });
+  }
+
+  const aaguid = authData.aaguid ?? ZERO_AAGUID;
+  const provider = providerForAaguid(aaguid);
+  const baseName = provider ?? 'Passkey';
+  const sameNameCount = account.passkeys.filter((p) => p.name === baseName || p.name.startsWith(`${baseName} (`)).length;
+
+  const passkey: StoredPasskey = {
+    id,
+    name: sameNameCount ? `${baseName} (${sameNameCount + 1})` : baseName,
+    publicKey: isBase64Url(publicKey, 8192) ? publicKey : null,
+    algorithm: Number.isInteger(publicKeyAlgorithm) ? publicKeyAlgorithm : null,
+    transports: Array.isArray(transports)
+      ? transports.filter((t: unknown): t is string => typeof t === 'string' && ALLOWED_TRANSPORTS.has(t))
+      : [],
+    aaguid,
+    backupEligible: authData.backupEligible,
+    backedUp: authData.backedUp,
+    createdAt: new Date().toISOString(),
+    lastUsedAt: null,
+  };
+
+  const requestedName = cleanLabel(body?.name, MAX_PASSKEY_NAME_LENGTH);
+  if (requestedName) passkey.name = requestedName;
+
+  account.passkeys.push(passkey);
+  await saveAccount(session, account);
+
+  return json({ passkey: toSummary(passkey) }, { status: 201 });
+};
+
