+import type { APIRoute } from 'astro';
+import {
+  RP_NAME,
+  REGISTRATION_CHALLENGE_KEY,
+  getAccount,
+  getRpId,
+  json,
+  toBase64Url,
+  unauthorized,
+} from '../../../../lib/account';
+
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+/** Returns `PublicKeyCredentialCreationOptionsJSON` for registering a new passkey. */
+export const POST: APIRoute = async ({ session, url }) => {
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+
+  const challenge = toBase64Url(crypto.getRandomValues(new Uint8Array(32)));
+  session.set(REGISTRATION_CHALLENGE_KEY, { challenge, expires: Date.now() + CHALLENGE_TTL_MS });
+
+  return json({
+    challenge,
+    rp: { id: getRpId(url), name: RP_NAME },
+    user: { id: account.userHandle, name: account.username, displayName: account.displayName },
+    pubKeyCredParams: [
+      { type: 'public-key', alg: -7 }, // ES256
+      { type: 'public-key', alg: -8 }, // EdDSA
+      { type: 'public-key', alg: -257 }, // RS256
+    ],
+    timeout: CHALLENGE_TTL_MS,
+    attestation: 'none',
+    authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'preferred' },
+    excludeCredentials: account.passkeys.map((p) => ({ type: 'public-key', id: p.id, transports: p.transports })),
+    hints: [],
+    extensions: { credProps: true },
+  });
+};
