+import type { APIRoute } from 'astro';
+import {
+  ACCOUNT_SESSION_KEY,
+  REGISTRATION_CHALLENGE_KEY,
+  cleanLabel,
+  createAccount,
+  getAccount,
+  json,
+  saveAccount,
+} from '../../../lib/account';
+
+/** Returns the signed-in reader (if any). */
+export const GET: APIRoute = async ({ session }) => {
+  const account = await getAccount(session);
+  if (!account) return json({ signedIn: false });
+  return json({ signedIn: true, username: account.username, displayName: account.displayName });
+};
+
+/**
+ * Establishes the server session after the auth service accepted the reader's
+ * credentials (see SignInForm). Re-signing in as the same reader keeps their
+ * registered passkeys.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'Sessions are unavailable.' }, { status: 500 });
+
+  const body = await request.json().catch(() => null);
+  const username = cleanLabel(body?.username, 64);
+  if (!username) return json({ error: 'A username is required.' }, { status: 400 });
+
+  const existing = await getAccount(session);
+  const account = existing && existing.username === username ? existing : createAccount(username);
+  await saveAccount(session, account);
+
+  return json({ signedIn: true, username: account.username, displayName: account.displayName });
+};
+
+/** Signs the reader out. */
+export const DELETE: APIRoute = async ({ session }) => {
+  session?.delete(ACCOUNT_SESSION_KEY);
+  session?.delete(REGISTRATION_CHALLENGE_KEY);
+  return json({ signedIn: false });
+};
