+        }
+        if (!res.ok) {
+          const err = new Error((data && (data.error || data.message)) || `Request failed (${res.status})`);
+          err.status = res.status;
+          throw err;
+        }
+        return data;
+      };
+
+      const isWebAuthnSupported = () =>
+        window.isSecureContext &&
+        typeof window.PublicKeyCredential === 'function' &&
+        !!(navigator.credentials && navigator.credentials.create);
+
+      if (!isWebAuthnSupported()) {
+        button.disabled = true;
+        setStatus('Passkeys are not supported in this browser or connection.', 'error');
+        return;
+      }
+
+      let inFlight = false;
+
+      button.addEventListener('click', async () => {
+        if (inFlight) return; // prevent concurrent ceremonies / double submits
+        inFlight = true;
+        button.disabled = true;
+        button.setAttribute('aria-busy', 'true');
+        setStatus('Preparing your passkey…');
+
+        try {
+          // 1. Fetch fresh, server-generated options (challenge is single-use and server-bound).
+          const optionsJSON = await postJSON('/api/register/options', { promotion: true });
+          const rawOptions = optionsJSON && optionsJSON.publicKey ? optionsJSON.publicKey : optionsJSON;
+          if (!rawOptions || !rawOptions.challenge || !rawOptions.user || !rawOptions.rp) {
+            throw new Error('Invalid registration options received from server.');
+          }
+          const publicKey = parseCreationOptions(rawOptions);
+
+          // 2. Run the WebAuthn ceremony. The browser enforces RP ID / origin binding.
+          setStatus('Follow the prompt on your device…');
+          const credential = await navigator.credentials.create({ publicKey });
+          if (!credential) throw new Error('No credential was created.');
+
+          // 3. Send the attestation to the server for verification (challenge, origin,
+          //    RP ID, and signature are all checked server-side).
+          setStatus('Verifying your passkey…');
+          const result = await postJSON('/api/register/verify', credentialToJSON(credential));
+
+          if (result && (result.verified === false || result.success === false)) {
+            throw new Error((result.error || result.message) || 'Passkey verification failed.');
+          }
+
+          setStatus('Passkey created! You can now sign in with it.', 'success');
+          button.textContent = 'Passkey created';
+          button.disabled = true;
+          return;
+        } catch (err) {
+          let message;
+          switch (err && err.name) {
+            case 'NotAllowedError':
+              message = 'Passkey creation was cancelled or timed out.';
+              break;
+            case 'InvalidStateError':
+              message = 'A passkey for this account already exists on this device.';
+              break;
+            case 'NotSupportedError':
+              message = 'Your device does not support the requested passkey type.';
+              break;
+            case 'SecurityError':
+              message = 'Passkey creation was blocked for security reasons.';
+              break;
+            case 'AbortError':
+              message = 'Passkey creation was aborted.';
+              break;
+            default:
+              message = (err && err.message) || 'Something went wrong creating your passkey.';
+          }
+          setStatus(message, 'error');
+          console.error('Passkey registration failed:', err);
+        } finally {
+          inFlight = false;
+          button.removeAttribute('aria-busy');
+          if (button.textContent !== 'Passkey created') button.disabled = false;
+        }
+      });
+    })();
+  </script>
+
