+      <div class="passkey-actions">
+        <button type="button" class="btn btn-small btn-outline" data-rename>Rename</button>
+        <button type="button" class="btn btn-small btn-outline" data-delete>Remove</button>
+      </div>
+    </li>
+  </template>
+
+  <!-- Reauthentication before sensitive changes -->
+  <dialog id="reauth-dialog" class="reauth-dialog" aria-labelledby="reauth-title" aria-describedby="reauth-reason">
+    <h2 id="reauth-title">Verify it's you</h2>
+    <p id="reauth-reason"></p>
+    <p id="reauth-status" class="status" role="status" aria-live="polite"></p>
+    <div class="reauth-actions">
+      <button type="button" id="reauth-passkey-btn" class="btn">Verify with passkey</button>
+      <form id="reauth-password-form" class="account-form">
+        <input type="email" id="reauth-username" name="username" autocomplete="username" readonly hidden>
+        <label for="reauth-password">Password</label>
+        <input type="password" id="reauth-password" name="password" autocomplete="current-password" required>
+        <button type="submit" class="btn btn-outline">Verify with password</button>
+      </form>
+      <button type="button" id="reauth-cancel" class="link-btn">Cancel</button>
+    </div>
+  </dialog>
+
+  <script type="module" src="js/account.js"></script>
+
 </body>

 </html>
