+// "My Account" dialog: customer registration, sign-in (passkey autofill, passkey
+// button, password fallback), profile updates, saved passkey management and
+// reauthentication before sensitive changes.
+import * as api from './api.js';
+import * as wa from './webauthn.js';
+
+const $ = (selector, root = document) => root.querySelector(selector);
+
+const els = {
+  accountLink: $('#account-link'),
+  logoutLink: $('#logout-link'),
+  dialog: $('#account-dialog'),
+  status: $('#account-status'),
+  views: document.querySelectorAll('#account-dialog [data-view]'),
+  // Sign in
+  signinForm: $('#signin-form'),
+  signinEmail: $('#signin-email'),
+  passkeySigninBtn: $('#passkey-signin-btn'),
+  // Register
+  registerForm: $('#register-form'),
+  registerPasswordGroup: $('#register-password-group'),
+  registerPassword: $('#register-password'),
+  registerPasskeyNote: $('#register-passkey-note'),
+  // Account
+  greetingName: $('#account-greeting-name'),
+  profileForm: $('#profile-form'),
+  profileName: $('#profile-name'),
+  profileEmail: $('#profile-email'),
+  createPasskeyBtn: $('#create-passkey-btn'),
+  passkeysUnsupported: $('#passkeys-unsupported'),
+  passkeyList: $('#passkey-list'),
+  passkeysEmpty: $('#passkeys-empty'),
+  passkeyTemplate: $('#passkey-item-template'),
+  signoutBtn: $('#signout-btn'),
+  // Reauth
+  reauthDialog: $('#reauth-dialog'),
+  reauthReason: $('#reauth-reason'),
+  reauthStatus: $('#reauth-status'),
+  reauthPasskeyBtn: $('#reauth-passkey-btn'),
+  reauthPasswordForm: $('#reauth-password-form'),
+  reauthUsername: $('#reauth-username'),
+  reauthCancel: $('#reauth-cancel'),
+};
+
+const state = {
+  /** @type {{name: string, displayName: string, hasPassword?: boolean} | null} */
+  user: null,
+  passkeys: [],
+  caps: {},
+};
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const GENERIC_ERROR = 'Something went wrong. Check your connection and try again.';
+const DEFAULT_PASSKEY_ICON =
+  'data:image/svg+xml,' +
+  encodeURIComponent(
+    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#4e342e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="9" r="4"/><path d="M11 12l9 0M17 12v3M20 12v2"/></svg>',
+  );
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function announce(message, tone = 'info', region = els.status) {
+  region.textContent = message;
+  region.dataset.tone = tone;
+}
+
+async function busy(control, task) {
+  const controls = control instanceof HTMLFormElement
+    ? control.querySelectorAll('button')
+    : [control];
+  controls.forEach((c) => { c.disabled = true; });
+  control.setAttribute?.('aria-busy', 'true');
+  try {
+    return await task();
+  } catch (err) {
+    console.error(err);
+    announce(GENERIC_ERROR, 'error');
+    return undefined;
+  } finally {
+    controls.forEach((c) => { c.disabled = false; });
+    control.removeAttribute?.('aria-busy');
+  }
+}
+
+async function errorMessage(response, fallback) {
+  const body = await api.readJSON(response);
+  return body.message || fallback;
+}
+
+function passkeyFailureMessage(reason) {
+  switch (reason) {
+    case 'cancelled':
+    case 'aborted':
+      return 'The passkey request was cancelled.';
+    case 'exists':
+      return 'A passkey for your account is already saved in this password manager or device.';
+    case 'unknown-credential':
+      return "That passkey isn't recognized. It may have been removed from your account — try another sign-in option.";
+    case 'wrong-account':
+      return 'That passkey belongs to a different account.';
+    case 'security':
+      return "Passkeys aren't available on this site right now. Please use another option.";
+    case 'unsupported':
+      return "This browser doesn't support passkeys.";
+    default:
+      return GENERIC_ERROR;
+  }
+}
+
+function formatDate(epochMs) {
+  return epochMs ? dateFormat.format(new Date(epochMs)) : null;
+}
+
+// ---------------------------------------------------------------------------
+// Views
+// ---------------------------------------------------------------------------
+
+function showView(name, { focus = true } = {}) {
+  for (const view of els.views) view.hidden = view.dataset.view !== name;
+
+  if (name === 'signin' && els.dialog.open) {
+    armPasskeyAutofill();
+  } else {
+    wa.abortConditionalSignIn();
+  }
+
+  if (focus && els.dialog.open) {
+    const target = name === 'signin'
+      ? els.signinEmail
+      : $(`[data-view="${name}"] h3`, els.dialog);
+    target?.focus();
+  }
+}
+
+function updateNav() {
+  els.logoutLink.hidden = !state.user;
+}
+
+function renderProfile() {
+  if (!state.user) return;
+  els.greetingName.textContent = state.user.displayName || state.user.name;
+  els.profileName.value = state.user.displayName ?? '';
+  els.profileEmail.value = state.user.name ?? '';
+  els.reauthUsername.value = state.user.name ?? '';
+}
+
+function setSignedIn(user) {
+  state.user = user;
+  updateNav();
+  renderProfile();
+}
+
+function setSignedOut() {
+  state.user = null;
+  state.passkeys = [];
+  els.passkeyList.replaceChildren();
+  updateNav();
+}
+
+async function openAccount() {
+  announce('');
+  if (!els.dialog.open) els.dialog.showModal();
+  if (state.user) {
+    showView('account');
+    await loadPasskeys();
+  } else {
+    showView('signin');
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Sign-in
+// ---------------------------------------------------------------------------
+
+async function armPasskeyAutofill() {
+  const result = await wa.startConditionalSignIn();
+  if (result) await handlePasskeySignIn(result);
+}
+
+async function completeSignIn(user) {
+  setSignedIn(user);
+  els.signinForm.reset();
+  showView('account');
+  announce(`Welcome back, ${user.displayName || user.name}.`, 'success');
+  await loadPasskeys();
+}
+
+async function handlePasskeySignIn(result) {
+  if (result.ok && result.user) {
+    await completeSignIn(result.user);
+    return;
+  }
+  if (result.reason !== 'cancelled' && result.reason !== 'aborted') {
+    announce(passkeyFailureMessage(result.reason), 'error');
+  }
+  // Re-arm autofill suggestions after a failed or cancelled attempt.
+  if (!state.user && els.dialog.open) armPasskeyAutofill();
+}
+
+els.passkeySigninBtn.addEventListener('click', () =>
+  busy(els.passkeySigninBtn, async () => {
+    announce('');
+    await handlePasskeySignIn(await wa.signInWithPasskey());
+  }),
+);
+
+els.signinForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const data = new FormData(els.signinForm);
+  busy(els.signinForm, async () => {
+    wa.abortConditionalSignIn();
+    const res = await api.passwordSignIn(data.get('email'), data.get('password'));
+    if (res.ok) {
+      const { user } = await res.json();
+      await completeSignIn(user);
+    } else {
+      announce(await errorMessage(res, 'That email and password combination is incorrect.'), 'error');
+      armPasskeyAutofill();
+    }
+  });
+});
+
+// Show-password toggles
+document.querySelectorAll('[data-toggle-password]').forEach((toggle) => {
+  toggle.addEventListener('change', () => {
+    const input = document.getElementById(toggle.dataset.togglePassword);
+    input.type = toggle.checked ? 'text' : 'password';
+  });
+});
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+function configureRegistration() {
+  const passkeysPossible = Boolean(state.caps.passkeyPlatformAuthenticator);
+  // Passkey-first sign-up; fall back to a password only when passkeys can't be created.
+  els.registerPasswordGroup.hidden = passkeysPossible;
+  els.registerPassword.required = !passkeysPossible;
+  els.registerPassword.disabled = passkeysPossible;
+  els.registerPasskeyNote.hidden = !passkeysPossible;
+}
+
+els.registerForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const data = new FormData(els.registerForm);
+  const details = {
+    name: data.get('email').trim(),
+    displayName: data.get('displayName').trim(),
+  };
+  if (data.has('password')) details.password = data.get('password');
+
+  busy(els.registerForm, async () => {
+    const res = await api.registerAccount(details);
+    if (res.status === 409) {
+      announce('An account with this email already exists. Sign in instead.', 'error');
+      return;
+    }
+    if (!res.ok) {
+      announce(await errorMessage(res, "We couldn't create your account. Please try again."), 'error');
+      return;
+    }
+    const { user } = await res.json();
+    setSignedIn(user);
+    els.registerForm.reset();
+    showView('account');
+
+    if (!state.caps.passkeyPlatformAuthenticator) {
+      announce(`Welcome to The Daily Grind, ${user.displayName}!`, 'success');
+      await loadPasskeys();
+      return;
+    }
+
+    announce('Account created. Save a passkey so you can sign in with your fingerprint, face or screen lock.');
+    const result = await wa.createPasskey({ promotion: true });
+    await loadPasskeys();
+    if (result.ok) {
+      announce(`Welcome to The Daily Grind, ${user.displayName}! Your passkey is saved.`, 'success');
+    } else {
+      announce(
+        `Your account is ready, but no passkey was saved (${passkeyFailureMessage(result.reason).toLowerCase()}) ` +
+          'Create one below so you can sign in next time.',
+        'error',
+      );
+    }
+  });
+});
+
+// ---------------------------------------------------------------------------
+// Passkey management
+// ---------------------------------------------------------------------------
+
+function configurePasskeyCreation() {
+  const supported = Boolean(state.caps.passkeyPlatformAuthenticator);
+  els.createPasskeyBtn.hidden = !supported;
+  els.passkeysUnsupported.hidden = supported;
+  els.passkeySigninBtn.hidden = !wa.webauthnAvailable;
+}
+
+async function loadPasskeys() {
+  try {
+    const res = await api.listPasskeys();
+    if (res.status === 401) {
+      setSignedOut();
+      showView('signin');
+      announce('Your session expired. Please sign in again.', 'error');
+      return;
+    }
+    if (!res.ok) throw new Error(`List passkeys failed (${res.status})`);
+    const { rpId, userId, credentials = [] } = await res.json();
+    state.passkeys = credentials;
+    renderPasskeys();
+    // Keep password managers in sync with the server's accepted credentials.
+    await wa.signalAllAcceptedCredentials(rpId, userId, credentials.map((c) => c.id));
+  } catch (err) {
+    console.error(err);
+    announce("We couldn't load your passkeys.", 'error');
+  }
+}
+
+function renderPasskeys() {
+  els.passkeysEmpty.hidden = state.passkeys.length > 0;
+  const items = state.passkeys.map((passkey, index) => {
+    const item = els.passkeyTemplate.content.firstElementChild.cloneNode(true);
+    const nameId = `passkey-name-${index}`;
+
+    const icon = $('.passkey-icon', item);
+    icon.src = passkey.providerIcon || DEFAULT_PASSKEY_ICON;
+
+    const nameEl = $('.passkey-name', item);
+    nameEl.id = nameId;
+    nameEl.textContent = passkey.name || 'Passkey';
+
+    const registered = formatDate(passkey.registeredAt);
+    const lastUsed = formatDate(passkey.lastUsedAt);
+    $('[data-registered]', item).textContent = registered ? `Created ${registered}` : '';
+    $('[data-last-used]', item).textContent = lastUsed ? `Last used ${lastUsed}` : 'Never used';
+    $('[data-synced]', item).hidden = !passkey.credentialBackedUp;
+
+    const renameBtn = $('[data-rename]', item);
+    const deleteBtn = $('[data-delete]', item);
+    renameBtn.setAttribute('aria-describedby', nameId);
+    deleteBtn.setAttribute('aria-describedby', nameId);
+
+    const renameForm = $('.rename-form', item);
+    const renameInput = $('input', renameForm);
+    renameInput.id = `passkey-rename-${index}`;
+    $('label', renameForm).htmlFor = renameInput.id;
+
+    renameBtn.addEventListener('click', () => {
+      renameForm.hidden = false;
+      renameBtn.hidden = true;
+      renameInput.value = passkey.name || '';
+      renameInput.focus();
+      renameInput.select();
+    });
+    $('[data-cancel]', renameForm).addEventListener('click', () => {
+      renameForm.hidden = true;
+      renameBtn.hidden = false;
+      renameBtn.focus();
+    });
+    renameForm.addEventListener('submit', (event) => {
+      event.preventDefault();
+      busy(renameForm, () => renamePasskey(passkey, renameInput.value.trim()));
+    });
+    deleteBtn.addEventListener('click', () => busy(deleteBtn, () => deletePasskey(passkey)));
+
+    return item;
+  });
+  els.passkeyList.replaceChildren(...items);
+}
+
+els.createPasskeyBtn.addEventListener('click', () =>
+  busy(els.createPasskeyBtn, async () => {
+    announce('');
+    // Settings flow: allow platform authenticators and security keys.
+    const result = await wa.createPasskey({ promotion: false });
+    if (result.ok) {
+      await loadPasskeys();
+      announce('Passkey created. You can now use it to sign in.', 'success');
+    } else if (result.reason !== 'cancelled' && result.reason !== 'aborted') {
+      announce(passkeyFailureMessage(result.reason), 'error');
+    }
+  }),
+);
+
+async function renamePasskey(passkey, name) {
+  if (!name) return;
+  // Renaming a nickname is a server-side label change only (no Signal API call).
+  const res = await withReauth(() => api.renamePasskey(passkey.id, name), 'Verify it’s you to rename this passkey.');
+  if (res?.ok) {
+    await loadPasskeys();
+    announce(`Passkey renamed to “${name}”.`, 'success');
+    els.passkeyList.querySelector('[data-rename]')?.focus();
+  } else if (res) {
+    announce(await errorMessage(res, "We couldn't rename that passkey."), 'error');
+  }
+}
+
+async function deletePasskey(passkey) {
+  const label = passkey.name || 'this passkey';
+  const lastSignInMethod = state.passkeys.length === 1 && !state.user?.hasPassword;
+  const reason =
+    `Remove “${label}” from your account? You won't be able to sign in with it anymore.` +
+    (lastSignInMethod ? ' This is your only passkey — create another one first so you don’t lose access.' : '');
+
+  // Sensitive action: always verify identity first (also serves as confirmation).
+  if (!(await reauthenticate(reason))) return;
+
+  const res = await withReauth(() => api.deletePasskey(passkey.id), reason);
+  if (res?.ok) {
+    await loadPasskeys(); // also calls signalAllAcceptedCredentials with the remaining IDs
+    announce(`“${label}” was removed.`, 'success');
+    (els.passkeyList.querySelector('[data-delete]') ?? els.createPasskeyBtn).focus();
+  } else if (res) {
+    announce(await errorMessage(res, "We couldn't remove that passkey."), 'error');
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Profile updates
+// ---------------------------------------------------------------------------
+
+els.profileForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const data = new FormData(els.profileForm);
+  const name = data.get('email').trim();
+  const displayName = data.get('displayName').trim();
+
+  busy(els.profileForm, async () => {
+    const emailChanged = name !== state.user.name;
+    if (emailChanged && !(await reauthenticate('Verify it’s you to change the email address on your account.'))) {
+      return;
+    }
+
+    const res = await withReauth(
+      () => api.updateUser({ name, displayName }),
+      'Verify it’s you to update your profile.',
+    );
+    if (!res) return;
+    if (!res.ok) {
+      announce(
+        await errorMessage(res, res.status === 409 ? 'That email is already in use.' : "We couldn't update your profile."),
+        'error',
+      );
+      return;
+    }
+
+    const updated = await res.json();
+    setSignedIn({ ...state.user, ...updated });
+    announce('Profile updated.', 'success');
+    // Update the username / display name stored alongside saved passkeys.
+    await wa.signalCurrentUserDetails(updated.rpId, updated.userId, updated.name ?? name, updated.displayName ?? displayName);
+  });
+});
+
+// ---------------------------------------------------------------------------
+// Reauthentication
+// ---------------------------------------------------------------------------
+
+/**
+ * Run a request; if the server responds 403 `reauth_required`, verify the user and retry once.
+ * Resolves with the Response, or `undefined` when the user cancels verification.
+ */
+async function withReauth(request, reason) {
+  let res = await request();
+  if (res.status === 403 && (await api.readJSON(res)).error === 'reauth_required') {
+    if (!(await reauthenticate(reason))) return undefined;
+    res = await request();
+  }
+  return res;
+}
+
+/** Ask the signed-in user to verify with a passkey (preferred) or password. */
+function reauthenticate(reason) {
+  const { reauthDialog: dialog } = els;
+  const canUsePasskey = wa.webauthnAvailable && state.passkeys.length > 0;
+  const canUsePassword = Boolean(state.user?.hasPassword);
+
+  els.reauthReason.textContent = reason;
+  announce('', 'info', els.reauthStatus);
+  els.reauthPasskeyBtn.hidden = !canUsePasskey;
+  els.reauthPasswordForm.hidden = !canUsePassword;
+  els.reauthPasswordForm.reset();
+  els.reauthUsername.value = state.user?.name ?? '';
+  if (!canUsePasskey && !canUsePassword) {
+    announce('Add a passkey to your account to make this change.', 'error', els.reauthStatus);
+  }
+
+  dialog.returnValue = '';
+  dialog.showModal();
+  (canUsePasskey ? els.reauthPasskeyBtn : canUsePassword ? $('#reauth-password') : els.reauthCancel).focus();
+
+  return new Promise((resolve) => {
+    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'verified'), { once: true });
+  });
+}
+
+els.reauthPasskeyBtn.addEventListener('click', () =>
+  busy(els.reauthPasskeyBtn, async () => {
+    announce('Waiting for your passkey…', 'info', els.reauthStatus);
+    const result = await wa.reauthenticate();
+    if (result.ok) {
+      els.reauthDialog.close('verified');
+    } else {
+      announce(passkeyFailureMessage(result.reason), 'error', els.reauthStatus);
+    }
+  }),
+);
+
+els.reauthPasswordForm.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const password = new FormData(els.reauthPasswordForm).get('password');
+  busy(els.reauthPasswordForm, async () => {
+    const res = await api.reauthPassword(password);
+    if (res.ok) {
+      els.reauthDialog.close('verified');
+    } else {
+      announce(await errorMessage(res, 'That password is incorrect.'), 'error', els.reauthStatus);
+    }
+  });
+});
+
+els.reauthCancel.addEventListener('click', () => els.reauthDialog.close(''));
+
+// ---------------------------------------------------------------------------
+// Session, navigation and dialog wiring
+// ---------------------------------------------------------------------------
+
+async function signOut() {
+  wa.abortConditionalSignIn();
+  try {
+    await api.signOut();
+  } catch (err) {
+    console.error(err);
+  }
+  setSignedOut();
+  if (els.dialog.open) {
+    showView('signin');
+    announce('You have been signed out.', 'success');
+  }
+}
+
+els.accountLink.addEventListener('click', (event) => {
+  event.preventDefault();
+  openAccount();
+});
+
+els.logoutLink.addEventListener('click', (event) => {
+  event.preventDefault();
+  signOut();
+});
+
+els.signoutBtn.addEventListener('click', () => busy(els.signoutBtn, signOut));
+
+els.dialog.querySelectorAll('[data-show-view]').forEach((button) => {
+  button.addEventListener('click', () => {
+    announce('');
+    showView(button.dataset.showView);
+  });
+});
+
+$('[data-close]', els.dialog).addEventListener('click', () => els.dialog.close());
+
+els.dialog.addEventListener('close', () => {
+  wa.abortConditionalSignIn();
+  announce('');
+});
+
+async function init() {
+  const [caps, sessionRes] = await Promise.all([
+    wa.getCapabilities(),
+    api.getSession().catch(() => null),
+  ]);
+  state.caps = caps;
+  configureRegistration();
+  configurePasskeyCreation();
+
+  if (sessionRes?.ok) {
+    const { user } = await sessionRes.json();
+    if (user) setSignedIn(user);
+  }
+  updateNav();
+
+  if (location.hash === '#account') openAccount();
+}
+
+init();
