@@ -0,0 +1,64 @@
+// Thin HTTP client for the account + passkey backend.
+// The full request/response contract is documented in docs/passkeys-api.md.
+// Every function resolves with the raw `Response` (callers inspect status codes,
+// e.g. 404 → unknown credential, 403 → reauthentication required).
+
+async function request(method, path, body) {
+  return fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: body === undefined
+      ? { Accept: 'application/json' }
+      : { Accept: 'application/json', 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+}
+
+/** Read a JSON body without throwing on empty / non-JSON responses. */
+export async function readJSON(response) {
+  try {
+    return await response.clone().json();
+  } catch {
+    return {};
+  }
+}
+
+// Session
+export const getSession = () => request('GET', '/api/session');
+export const signOut = () => request('POST', '/api/auth/logout');
+
+// Customer registration
+export const registerAccount = (details) => request('POST', '/api/account/register', details);
+
+// Password sign-in (fallback)
+export const passwordSignIn = (email, password) =>
+  request('POST', '/api/auth/password', { email, password });
+
+// Passkey sign-in (discoverable credentials)
+export const signInOptions = () => request('POST', '/api/auth/passkey/options');
+export const verifySignIn = (credentialJSON) =>
+  request('POST', '/api/auth/passkey/verify', credentialJSON);
+
+// Passkey registration
+export const passkeyCreationOptions = ({ promotion = false } = {}) =>
+  request('POST', '/api/passkeys/register/options', { promotion });
+export const verifyPasskeyRegistration = (credentialJSON) =>
+  request('POST', '/api/passkeys/register/verify', credentialJSON);
+
+// Passkey management
+export const listPasskeys = () => request('GET', '/api/passkeys');
+export const renamePasskey = (id, name) =>
+  request('PATCH', `/api/passkeys/${encodeURIComponent(id)}`, { name });
+export const deletePasskey = (id) =>
+  request('DELETE', `/api/passkeys/${encodeURIComponent(id)}`);
+
+// Profile
+export const updateUser = ({ name, displayName }) =>
+  request('PUT', '/api/user', { name, displayName });
+
+// Reauthentication
+export const reauthOptions = () => request('POST', '/api/reauth/options');
+export const verifyReauth = (credentialJSON) =>
+  request('POST', '/api/reauth/verify', credentialJSON);
+export const reauthPassword = (password) =>
+  request('POST', '/api/reauth/password', { password });
