@@ -0,0 +1,274 @@
+// Native WebAuthn helpers for passkey registration, sign-in, reauthentication
+// and Signal API synchronization. No client-side wrapper library is used; the
+// self-hosted webauthn-polyfills module is only loaded when the browser lacks
+// getClientCapabilities() / parse*OptionsFromJSON() / toJSON().
+import * as api from './api.js';
+
+const POLYFILL_URL = new URL('../vendor/webauthn-polyfills-0.1.7.mjs', import.meta.url);
+
+export const webauthnAvailable =
+  typeof window !== 'undefined' && 'PublicKeyCredential' in window && window.isSecureContext;
+
+let readyPromise;
+
+/** Ensure the JSON (de)serialization + capability APIs exist. Resolves to false when WebAuthn is unavailable. */
+export function loadWebAuthn() {
+  if (!webauthnAvailable) return Promise.resolve(false);
+  readyPromise ??= (async () => {
+    const PKC = window.PublicKeyCredential;
+    const needsPolyfill =
+      !PKC.getClientCapabilities ||
+      !PKC.parseCreationOptionsFromJSON ||
+      !PKC.parseRequestOptionsFromJSON ||
+      !PKC.prototype.toJSON;
+    if (needsPolyfill) await import(POLYFILL_URL.href);
+    return true;
+  })().catch((err) => {
+    console.warn('WebAuthn polyfill failed to load:', err);
+    return false;
+  });
+  return readyPromise;
+}
+
+/** @returns {Promise<Record<string, boolean>>} */
+export async function getCapabilities() {
+  if (!(await loadWebAuthn())) return {};
+  try {
+    return await PublicKeyCredential.getClientCapabilities();
+  } catch {
+    return {};
+  }
+}
+
+/** Map WebAuthn DOMExceptions to UI-friendly reasons. */
+function reasonFor(err) {
+  switch (err?.name) {
+    case 'InvalidStateError': return 'exists';      // matched excludeCredentials
+    case 'NotAllowedError': return 'cancelled';     // user dismissed / timed out
+    case 'AbortError': return 'aborted';            // aborted programmatically
+    case 'SecurityError': return 'security';        // RP ID / secure context misconfiguration
+    default: return 'error';
+  }
+}
+
+async function optionsFrom(responsePromise) {
+  const res = await responsePromise;
+  if (!res.ok) {
+    const err = new Error(`Options request failed (${res.status})`);
+    err.status = res.status;
+    throw err;
+  }
+  return res.json();
+}
+
+// ---------------------------------------------------------------------------
+// Signal API (progressive enhancement, never fatal)
+// ---------------------------------------------------------------------------
+
+/** Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no padding, length % 4 !== 1 */
+export function isValidBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+export async function signalUnknownCredential(rpId, credentialId) {
+  if (!webauthnAvailable || !PublicKeyCredential.signalUnknownCredential) return;
+  if (!rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    // rpId always comes from the server-provided options — never window.location.hostname.
+    await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+  } catch (e) {
+    console.warn('signalUnknownCredential sync warning:', e);
+  }
+}
+
+export async function signalAllAcceptedCredentials(rpId, userId, credentialIds) {
+  if (!webauthnAvailable || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId,
+      userId,
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export async function signalCurrentUserDetails(rpId, userId, name, displayName) {
+  if (!webauthnAvailable || !PublicKeyCredential.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+/**
+ * Create a passkey for the signed-in user.
+ * @param {{promotion?: boolean}} opts promotion=true restricts to platform authenticators
+ *   (post-signup prompt); false (settings page) also allows security keys.
+ * @returns {Promise<{ok: true, credential: object} | {ok: false, reason: string}>}
+ */
+export async function createPasskey({ promotion = false } = {}) {
+  if (!(await loadWebAuthn())) return { ok: false, reason: 'unsupported' };
+
+  const json = await optionsFrom(api.passkeyCreationOptions({ promotion }));
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  const rpId = json.rp?.id;
+
+  let credential;
+  try {
+    credential = await navigator.credentials.create({ publicKey });
+  } catch (err) {
+    if (err?.name === 'SecurityError') console.error('Passkey RP ID or secure context misconfiguration:', err);
+    // Standard WebAuthn cancellations are not signalled as unknown credentials.
+    return { ok: false, reason: reasonFor(err) };
+  }
