+  const encoded = credential.toJSON();
+  try {
+    const res = await api.verifyPasskeyRegistration(encoded);
+    if (!res.ok) {
+      // The authenticator saved a passkey the server rejected — tell the provider to drop it.
+      await signalUnknownCredential(rpId, encoded.id);
+      return { ok: false, reason: 'server' };
+    }
+    return { ok: true, credential: await api.readJSON(res) };
+  } catch (err) {
+    console.error('Passkey registration verification failed:', err);
+    await signalUnknownCredential(rpId, encoded.id);
+    return { ok: false, reason: 'network' };
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Sign-in
+// ---------------------------------------------------------------------------
+
+let conditionalController = null;
+
+export function abortConditionalSignIn() {
+  conditionalController?.abort();
+  conditionalController = null;
+}
+
+async function verifySignIn(rpId, credential) {
+  const encoded = credential.toJSON();
+  try {
+    const res = await api.verifySignIn(encoded);
+    if (res.ok) return { ok: true, ...(await api.readJSON(res)) };
+    if (res.status === 404) {
+      // Credential unknown to the server; this runs pre-authentication.
+      await signalUnknownCredential(rpId, encoded.id);
+      return { ok: false, reason: 'unknown-credential' };
+    }
+    return { ok: false, reason: 'server' };
+  } catch (err) {
+    console.error('Passkey sign-in verification failed:', err);
+    return { ok: false, reason: 'network' };
+  }
+}
+
+/**
+ * Arm passkey suggestions in the `autocomplete="username webauthn"` field.
+ * Resolves with a result once the user picks a passkey, or `null` when aborted/unsupported.
+ */
+export async function startConditionalSignIn() {
+  abortConditionalSignIn();
+  const caps = await getCapabilities();
+  if (!caps.conditionalGet) return null;
+
+  const controller = new AbortController();
+  conditionalController = controller;
+
+  let json;
+  try {
+    json = await optionsFrom(api.signInOptions());
+  } catch (err) {
+    console.warn('Could not prepare passkey autofill:', err);
+    return null;
+  }
+  if (controller.signal.aborted) return null;
+
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(json);
+  let credential;
+  try {
+    credential = await navigator.credentials.get({
+      publicKey,
+      mediation: 'conditional',
+      signal: controller.signal,
+    });
+  } catch (err) {
+    if (err?.name !== 'NotAllowedError' && err?.name !== 'AbortError') {
+      console.error('Unexpected conditional passkey error:', err);
+    }
+    return null;
+  } finally {
+    if (conditionalController === controller) conditionalController = null;
+  }
+  if (!credential) return null;
+  return verifySignIn(json.rpId, credential);
+}
+
+/** Explicit "Sign in with a passkey" button flow. */
+export async function signInWithPasskey() {
+  if (!(await loadWebAuthn())) return { ok: false, reason: 'unsupported' };
+  // Abort pending autofill request to avoid passkey prompt collisions.
+  abortConditionalSignIn();
+
+  const json = await optionsFrom(api.signInOptions());
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(json);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.get({ publicKey });
+  } catch (err) {
+    return { ok: false, reason: reasonFor(err) };
+  }
+  return verifySignIn(json.rpId, credential);
+}
+
+// ---------------------------------------------------------------------------
+// Reauthentication (allowCredentials restricted to the signed-in user)
+// ---------------------------------------------------------------------------
+
+export async function reauthenticate() {
+  if (!(await loadWebAuthn())) return { ok: false, reason: 'unsupported' };
+  abortConditionalSignIn();
+
+  const json = await optionsFrom(api.reauthOptions());
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(json);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.get({ publicKey });
+  } catch (err) {
+    return { ok: false, reason: reasonFor(err) };
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const res = await api.verifyReauth(encoded);
+    if (res.ok) return { ok: true };
+    if (res.status === 404) {
+      await signalUnknownCredential(json.rpId, encoded.id);
+      return { ok: false, reason: 'unknown-credential' };
+    }
+    return { ok: false, reason: res.status === 403 ? 'wrong-account' : 'server' };
+  } catch (err) {
+    console.error('Reauthentication verification failed:', err);
+    return { ok: false, reason: 'network' };
+  }
+}
