+++ b/assets/account.css
@@ -0,0 +1,370 @@
+/* The Daily Grind — My Account (passkeys) */
+
+[hidden] {
+  display: none !important;
+}
+
+button.btn {
+  border: none;
+  cursor: pointer;
+  font: inherit;
+  font-size: 0.95rem;
+}
+
+button.btn:disabled,
+.btn-link:disabled {
+  opacity: 0.55;
+  cursor: not-allowed;
+}
+
+button[aria-busy="true"] {
+  cursor: progress;
+}
+
+.btn:focus-visible,
+.btn-link:focus-visible,
+.acct-tabs [role="tab"]:focus-visible,
+.acct-close:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 2px;
+}
+
+.btn-block {
+  display: block;
+  width: 100%;
+}
+
+.btn-secondary {
+  background: transparent;
+  color: var(--primary);
+  box-shadow: inset 0 0 0 1px var(--primary);
+}
+
+.btn-secondary:hover {
+  background: var(--secondary);
+}
+
+.btn.btn-danger {
+  background: #b3261e;
+}
+
+.btn.btn-danger:hover {
+  background: #8c1d18;
+}
+
+.btn-small {
+  background: var(--primary);
+  color: white;
+  border: none;
+  border-radius: 4px;
+  padding: 6px 12px;
+  font: inherit;
+  font-size: 0.85rem;
+  cursor: pointer;
+}
+
+.btn-link {
+  background: none;
+  border: none;
+  padding: 4px 6px;
+  color: var(--primary);
+  font: inherit;
+  font-size: 0.85rem;
+  text-decoration: underline;
+  cursor: pointer;
+}
+
+.btn-link.danger {
+  color: #b3261e;
+}
+
+/* Dialogs */
+
+.account-dialog,
+.small-dialog {
+  border: none;
+  border-radius: 12px;
+  padding: 0;
+  color: var(--text);
+  background: white;
+  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
+  margin: auto;
+}
+
+.account-dialog {
+  width: min(560px, calc(100vw - 24px));
+  max-height: calc(100vh - 24px);
+  overflow-y: auto;
+}
+
+.small-dialog {
+  width: min(420px, calc(100vw - 24px));
+  padding: 24px;
+}
+
+.small-dialog h2 {
+  font-size: 1.25rem;
+  color: var(--primary);
+  margin-bottom: 8px;
+}
+
+.account-dialog::backdrop,
+.small-dialog::backdrop {
+  background: rgba(30, 18, 14, 0.6);
+}
+
+.acct-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 18px 24px;
+  background: var(--primary);
+  color: white;
+  position: sticky;
+  top: 0;
+  z-index: 1;
+}
+
+.acct-header h2 {
+  font-size: 1.3rem;
+  letter-spacing: 0.5px;
+}
+
+.acct-close {
+  background: none;
+  border: none;
+  color: white;
+  font-size: 1.8rem;
+  line-height: 1;
+  cursor: pointer;
+  padding: 0 4px;
+}
+
+#account-signed-out,
+#account-signed-in {
+  padding: 20px 24px 24px;
+}
+
+.acct-status {
+  margin: 16px 24px 0;
+  padding: 10px 14px;
+  border-radius: 6px;
+  font-size: 0.9rem;
+  background: #efebe9;
+  border-left: 4px solid var(--primary);
+}
+
+.small-dialog .acct-status {
+  margin: 12px 0 0;
+}
+
+.acct-status[data-kind="success"] {
+  background: #e8f5e9;
+  border-color: #2e7d32;
+}
+
+.acct-status[data-kind="error"] {
+  background: #fdecea;
+  border-color: #b3261e;
+}
+
+/* Tabs */
+
+.acct-tabs {
+  display: flex;
+  border-bottom: 2px solid var(--secondary);
+  margin-bottom: 18px;
+}
+
+.acct-tabs [role="tab"] {
+  flex: 1;
+  background: none;
+  border: none;
+  border-bottom: 3px solid transparent;
+  margin-bottom: -2px;
+  padding: 10px;
+  font: inherit;
+  font-weight: 600;
+  color: #8d6e63;
+  cursor: pointer;
+}
+
+.acct-tabs [role="tab"][aria-selected="true"] {
+  color: var(--primary);
+  border-bottom-color: var(--accent);
+}
+
+/* Forms */
+
+.acct-form {
+  display: flex;
+  flex-direction: column;
+}
+
+.acct-form label {
+  font-weight: 600;
+  font-size: 0.9rem;
