diff --git a/assets/account.js b/assets/account.js
new file mode 100644
index 0000000..af406de
--- /dev/null
+++ b/assets/account.js
@@ -0,0 +1,757 @@
+// The Daily Grind — "My Account" with passkeys.
+//
+// Covers: account registration, sign-in (modal + autofill/conditional UI),
+// saved passkey management (add / rename / remove), profile updates and
+// reauthentication before sensitive actions.
+
+const $ = (sel, root = document) => root.querySelector(sel);
+
+const els = {
+  dialog: $('#account-dialog'),
+  status: $('#account-status'),
+  unsupported: $('#account-unsupported'),
+  signedOut: $('#account-signed-out'),
+  signedIn: $('#account-signed-in'),
+  tabs: document.querySelectorAll('[data-account-tab]'),
+  signinForm: $('#signin-form'),
+  registerForm: $('#register-form'),
+  greeting: $('#account-greeting'),
+  profileForm: $('#profile-form'),
+  passkeyList: $('#passkey-list'),
+  addPasskey: $('#add-passkey'),
+  signOut: $('#sign-out'),
+  deleteAccount: $('#delete-account'),
+  reauthDialog: $('#reauth-dialog'),
+  confirmDialog: $('#confirm-dialog'),
+  navAccount: $('#nav-account'),
+  navAuth: $('#nav-auth'),
+};
+
+const webauthnSupported = typeof window.PublicKeyCredential === 'function' &&
+  typeof navigator.credentials?.create === 'function';
+
+const state = {
+  session: { user: null },
+  clockOffset: 0,          // serverNow - clientNow
+  conditional: null,       // AbortController for the autofill request
+};
+
+/* ------------------------------------------------------------------ */
+/* Utilities                                                            */
+/* ------------------------------------------------------------------ */
+
+class ApiError extends Error {
+  constructor(status, data) {
+    super(data?.message || 'Something went wrong. Please try again.');
+    this.status = status;
+    this.code = data?.error;
+    this.data = data || {};
+  }
+}
+
+async function api(method, url, body) {
+  const res = await fetch(url, {
+    method,
+    credentials: 'same-origin',
+    headers: body !== undefined || method !== 'GET' ? { 'Content-Type': 'application/json' } : {},
+    body: body !== undefined ? JSON.stringify(body) : undefined,
+  });
+  let data = null;
+  try { data = await res.json(); } catch { /* empty body */ }
+  if (!res.ok) throw new ApiError(res.status, data);
+  return data;
+}
+
+function h(tag, props = {}, ...children) {
+  const el = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (v === undefined || v === null || v === false) continue;
+    if (k === 'class') el.className = v;
+    else if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
+    else if (k === 'text') el.textContent = v;
+    else el.setAttribute(k, v === true ? '' : v);
+  }
+  for (const c of children.flat()) {
+    if (c !== null && c !== undefined && c !== false) el.append(c);
+  }
+  return el;
+}
+
+const toB64url = (buf) => {
+  const bytes = new Uint8Array(buf);
+  let s = '';
+  for (const b of bytes) s += String.fromCharCode(b);
+  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+};
+
+const fromB64url = (str) => {
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(str.length / 4) * 4, '=');
+  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
+};
+
+function decodeCreationOptions(json) {
+  if (typeof PublicKeyCredential.parseCreationOptionsFromJSON === 'function') {
+    return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: fromB64url(json.challenge),
+    user: { ...json.user, id: fromB64url(json.user.id) },
+    excludeCredentials: (json.excludeCredentials || []).map((c) => ({ ...c, id: fromB64url(c.id) })),
+  };
+}
+
+function decodeRequestOptions(json) {
+  if (typeof PublicKeyCredential.parseRequestOptionsFromJSON === 'function') {
+    return PublicKeyCredential.parseRequestOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: fromB64url(json.challenge),
+    allowCredentials: (json.allowCredentials || []).map((c) => ({ ...c, id: fromB64url(c.id) })),
+  };
+}
+
+// Serialise manually rather than via credential.toJSON(): some passkey
+// provider extensions ship incomplete toJSON() implementations.
+function credentialToJSON(cred) {
+  const r = cred.response;
+  const response = { clientDataJSON: toB64url(r.clientDataJSON) };
+  if (r.attestationObject) {
+    response.attestationObject = toB64url(r.attestationObject);
+    response.transports = typeof r.getTransports === 'function' ? r.getTransports() : [];
+  } else {
+    response.authenticatorData = toB64url(r.authenticatorData);
+    response.signature = toB64url(r.signature);
+    if (r.userHandle) response.userHandle = toB64url(r.userHandle);
+  }
+  return {
+    id: cred.id,
+    rawId: toB64url(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? null,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response,
+  };
+}
+
+async function createPasskey(optionsJSON) {
+  const cred = await navigator.credentials.create({ publicKey: decodeCreationOptions(optionsJSON) });
+  return credentialToJSON(cred);
+}
+
+async function getPasskey(optionsJSON, extra = {}) {
+  const cred = await navigator.credentials.get({ publicKey: decodeRequestOptions(optionsJSON), ...extra });
+  return credentialToJSON(cred);
+}
+
+/** Map WebAuthn / API errors to friendly copy. Returns null for silent cancellations. */
+function describeError(err, context) {
+  if (err instanceof ApiError) return err.message;
+  switch (err?.name) {
+    case 'AbortError':
+      return null;
+    case 'NotAllowedError':
+      return 'The passkey request was cancelled or timed out.';
+    case 'InvalidStateError':
+      return context === 'create'
+        ? 'This device or password manager already has a passkey for your account.'
+        : 'That passkey can’t be used right now.';
+    case 'SecurityError':
+      return 'Passkeys aren’t available on this address. Please use the secure site.';
+    case 'NotSupportedError':
+      return 'This device doesn’t support the required passkey type.';
+    case 'ReauthCancelled':
+      return null;
+    default:
+      return 'Something went wrong. Please try again.';
+  }
+}
+
+function setStatus(message, kind = 'info') {
+  els.status.textContent = message || '';
+  els.status.dataset.kind = kind;
+  els.status.hidden = !message;
+}
+
+async function busy(button, fn) {
+  const label = button.textContent;
+  button.disabled = true;
+  button.setAttribute('aria-busy', 'true');
+  try {
+    return await fn();
+  } finally {
+    button.disabled = false;
+    button.removeAttribute('aria-busy');
+    button.textContent = label;
+  }
+}
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
+const relFmt = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function relativeTime(iso) {
+  const diff = (new Date(iso).getTime() - Date.now()) / 1000;
+  const units = [['year', 31536000], ['month', 2592000], ['week', 604800], ['day', 86400], ['hour', 3600], ['minute', 60]];
+  for (const [unit, secs] of units) {
+    if (Math.abs(diff) >= secs) return relFmt.format(Math.round(diff / secs), unit);
+  }
+  return 'just now';
+}
+
+/* ------------------------------------------------------------------ */
+/* WebAuthn Signal API — keep passkey providers in sync with the server */
+/* ------------------------------------------------------------------ */
+
+function signalAccountState(session) {
+  const PKC = window.PublicKeyCredential;
+  if (!session?.user || !PKC) return;
+  const base = { rpId: session.rpId, userId: session.userHandle };
+  PKC.signalAllAcceptedCredentials?.({
+    ...base, allAcceptedCredentialIds: session.passkeys.map((p) => p.id),
+  }).catch(() => {});
+  PKC.signalCurrentUserDetails?.({
+    ...base, name: session.user.email, displayName: session.user.name,
+  }).catch(() => {});
+}
+
+function signalUnknownCredential(credentialId) {
+  if (!credentialId) return;
+  window.PublicKeyCredential?.signalUnknownCredential?.({
+    rpId: state.session.rpId, credentialId,
+  }).catch(() => {});
+}
+
+/* ------------------------------------------------------------------ */
+/* Session                                                              */
+/* ------------------------------------------------------------------ */
+
+function applySession(session) {
+  state.session = session;
+  if (typeof session.now === 'number') state.clockOffset = session.now - Date.now();
+  render();
+}
+
+function isRecentlyVerified() {
+  const until = state.session.reauthUntil;
+  return !!until && until - (Date.now() + state.clockOffset) > 15_000;
+}
+
+async function refreshSession() {
+  try {
+    applySession(await api('GET', '/api/session'));
+  } catch {
+    applySession({ user: null });
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Rendering                                                            */
+/* ------------------------------------------------------------------ */
+
+function render() {
+  const { user } = state.session;
+  els.signedOut.hidden = !!user;
+  els.signedIn.hidden = !user;
+  els.unsupported.hidden = webauthnSupported;
+
+  if (els.navAuth) {
+    els.navAuth.textContent = user ? 'Logout' : 'Sign in';
+    els.navAuth.setAttribute('href', user ? '/logout' : '/account');
+  }
+  if (els.navAccount) els.navAccount.textContent = user ? `My Account (${user.name.split(' ')[0]})` : 'My Account';
+
+  for (const btn of document.querySelectorAll('[data-requires-webauthn]')) {
+    btn.disabled = !webauthnSupported;
+  }
+
+  if (user) {
+    stopConditionalSignIn();
+    els.greeting.textContent = `Welcome back, ${user.name}!`;
+    const f = els.profileForm.elements;
+    if (document.activeElement?.form !== els.profileForm) {
+      f.name.value = user.name;
+      f.email.value = user.email;
+    }
+    renderPasskeys();
+  } else if (els.dialog.open) {
+    startConditionalSignIn();
+  }
+}
+
+function renderPasskeys() {
+  const { passkeys } = state.session;
+  els.passkeyList.replaceChildren(...passkeys.map((pk) => passkeyItem(pk, passkeys.length)));
+}
+
+function passkeyItem(pk, total) {
+  const meta = [
+    pk.provider && pk.provider !== pk.name ? pk.provider : null,
+    `Created ${dateFmt.format(new Date(pk.createdAt))}`,
+    pk.lastUsedAt ? `Last used ${relativeTime(pk.lastUsedAt)}` : null,
+  ].filter(Boolean).join(' · ');
+
+  const badges = [
+    pk.current ? h('span', { class: 'badge badge-current', text: 'Signed in with this' }) : null,
+    pk.backedUp
+      ? h('span', { class: 'badge badge-synced', title: 'Backed up and synced by your passkey provider', text: 'Synced' })
+      : h('span', { class: 'badge', title: 'Stored only on this device or security key', text: 'Device-bound' }),
+  ];
+
+  const li = h('li', { class: 'passkey' });
+  const main = h('div', { class: 'pk-main' },
+    h('div', { class: 'pk-name' }, h('strong', { text: pk.name }), ...badges),
+    h('div', { class: 'pk-meta', text: meta }));
+
+  const renameBtn = h('button', {
+    type: 'button', class: 'btn-link', 'aria-label': `Rename passkey ${pk.name}`, text: 'Rename',
+    onclick: () => startRename(li, pk),
+  });
+  const removeBtn = h('button', {
+    type: 'button', class: 'btn-link danger', 'aria-label': `Remove passkey ${pk.name}`, text: 'Remove',
+    disabled: total <= 1,
+    title: total <= 1 ? 'Add another passkey before removing this one' : null,
+    onclick: (e) => removePasskey(e.currentTarget, pk),
+  });
+
+  li.append(keyIcon(), main, h('div', { class: 'pk-actions' }, renameBtn, removeBtn));
+  return li;
+}
+
+function keyIcon() {
+  const span = h('span', { class: 'pk-icon', 'aria-hidden': 'true' });
+  span.innerHTML = '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="15" r="4"/><path d="M10.85 12.15 19 4M18 5l2 2M15 8l2 2"/></svg>';
+  return span;
+}
+
+/* ------------------------------------------------------------------ */
+/* Sign in                                                              */
+/* ------------------------------------------------------------------ */
+
+async function completeSignIn(credential, autofill = false) {
+  try {
+    const session = await api('POST', '/api/login/verify', { credential, autofill });
+    applySession(session);
+    signalAccountState(session);
+    setStatus(`Signed in. Welcome back, ${session.user.name}!`, 'success');
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'unknown_credential') {
+      signalUnknownCredential(err.data.credentialId || credential.id);
+    }
+    throw err;
+  }
+}
+
+/** Passkey autofill: offer saved passkeys in the email field's suggestions. */
+async function startConditionalSignIn() {
+  if (state.conditional || state.session.user || !webauthnSupported) return;
+  const controller = new AbortController();
+  state.conditional = controller;
+  let retry = false;
+  try {
+    if (!(await PublicKeyCredential.isConditionalMediationAvailable?.())) return;
+    if (controller.signal.aborted) return;
+    const options = await api('POST', '/api/login/options', { autofill: true });
+    if (controller.signal.aborted) return;
+    const credential = await getPasskey(options, { mediation: 'conditional', signal: controller.signal });
+    await completeSignIn(credential, true);
+  } catch (err) {
+    if (controller.signal.aborted) return;
+    retry = true;
+    const msg = describeError(err, 'get');
+    if (msg && err?.name !== 'NotAllowedError') setStatus(msg, 'error');
+  } finally {
+    if (state.conditional === controller) state.conditional = null;
+    // Re-arm autofill if we're still signed out and the dialog is open.
+    if (retry && !state.session.user && els.dialog.open) setTimeout(startConditionalSignIn, 1000);
+  }
+}
+
+function stopConditionalSignIn() {
+  if (state.conditional) {
+    state.conditional.abort(new DOMException('Superseded', 'AbortError'));
+    state.conditional = null;
+  }
+}
+
+els.signinForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const button = event.submitter || els.signinForm.querySelector('button[type="submit"]');
+  stopConditionalSignIn();
+  setStatus('');
+  await busy(button, async () => {
+    button.textContent = 'Waiting for your passkey…';
+    try {
+      const options = await api('POST', '/api/login/options');
+      const credential = await getPasskey(options);
+      await completeSignIn(credential);
+    } catch (err) {
+      const msg = describeError(err, 'get');
+      if (msg) setStatus(msg, 'error');
+    }
+  });
+  if (!state.session.user) startConditionalSignIn();
+});
+
+/* ------------------------------------------------------------------ */
+/* Registration                                                         */
+/* ------------------------------------------------------------------ */
+
+els.registerForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const form = els.registerForm;
+  if (!form.reportValidity()) return;
+  const button = event.submitter || form.querySelector('button[type="submit"]');
+  stopConditionalSignIn();
+  setStatus('');
+  await busy(button, async () => {
+    button.textContent = 'Creating your passkey…';
+    try {
+      const options = await api('POST', '/api/register/options', {
+        name: form.elements.name.value,
+        email: form.elements.email.value,
+      });
+      const credential = await createPasskey(options);
+      const session = await api('POST', '/api/register/verify', { credential });
+      form.reset();
+      applySession(session);
+      signalAccountState(session);
+      setStatus(`Welcome to The Daily Grind, ${session.user.name}! Your passkey is saved — use it to sign in next time.`, 'success');
+    } catch (err) {
+      const msg = describeError(err, 'create');
+      if (msg) setStatus(msg, 'error');
+      if (err instanceof ApiError && err.data.field) form.elements[err.data.field]?.focus();
+    }
+  });
+});
+
+/* ------------------------------------------------------------------ */
+/* Reauthentication                                                     */
+/* ------------------------------------------------------------------ */
+
+class ReauthCancelled extends Error {
+  constructor() { super('Reauthentication cancelled'); this.name = 'ReauthCancelled'; }
+}
+
+/**
+ * Ask the customer to confirm it's them with a user-verifying passkey
+ * assertion. If `continueLabel` is given, a second click is requested after
+ * verification so the follow-up WebAuthn call has fresh user activation.
+ */
+function reauthenticate(reason, { continueLabel } = {}) {
+  const dlg = els.reauthDialog;
+  const reasonEl = $('#reauth-reason', dlg);
+  const errorEl = $('#reauth-error', dlg);
+  const verifyBtn = $('#reauth-verify', dlg);
+  const continueBtn = $('#reauth-continue', dlg);
+  const cancelBtn = $('#reauth-cancel', dlg);
+
+  reasonEl.textContent = reason;
+  errorEl.hidden = true;
+  verifyBtn.hidden = false;
+  continueBtn.hidden = true;
+
+  // Fetch the challenge up-front so the click goes straight to the passkey prompt.
+  let optionsPromise = api('POST', '/api/reauth/options');
+  optionsPromise.catch(() => {});
+
+  return new Promise((resolve, reject) => {
+    let settled = false;
+    const cleanup = () => {
+      verifyBtn.onclick = null;
+      continueBtn.onclick = null;
+      cancelBtn.onclick = null;
+      dlg.removeEventListener('close', onClose);
+    };
+    const finish = () => {
+      settled = true;
+      cleanup();
+      dlg.close();
+      resolve();
+    };
+    const onClose = () => {
+      if (!settled) { cleanup(); reject(new ReauthCancelled()); }
+    };
+
+    verifyBtn.onclick = () => busy(verifyBtn, async () => {
+      verifyBtn.textContent = 'Waiting for your passkey…';
+      errorEl.hidden = true;
+      try {
+        const options = await optionsPromise;
+        const credential = await getPasskey(options);
+        const session = await api('POST', '/api/reauth/verify', { credential });
+        applySession(session);
+        if (continueLabel) {
+          reasonEl.textContent = 'Thanks — you’re verified.';
+          verifyBtn.hidden = true;
+          continueBtn.textContent = continueLabel;
+          continueBtn.hidden = false;
+          continueBtn.focus();
+        } else {
+          finish();
+        }
+      } catch (err) {
+        // The challenge is single-use: get a fresh one for the next attempt.
+        optionsPromise = api('POST', '/api/reauth/options');
+        optionsPromise.catch(() => {});
+        const msg = describeError(err, 'get');
+        if (msg) { errorEl.textContent = msg; errorEl.hidden = false; }
+      }
+    });
+    continueBtn.onclick = finish;
+    cancelBtn.onclick = () => dlg.close();
+    dlg.addEventListener('close', onClose);
+    dlg.showModal();
+  });
+}
+
+/**
+ * Run a sensitive action, prompting for reauthentication first if the last
+ * verification is stale (and again if the server says it has expired).
+ */
+async function withReauth(reason, action, opts) {
+  if (!isRecentlyVerified()) await reauthenticate(reason, opts);
+  try {
+    return await action();
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'reauth_required') {
+      await reauthenticate(reason, opts);
+      return action();
+    }
+    throw err;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Confirmation dialog                                                  */
+/* ------------------------------------------------------------------ */
+
+function confirmAction({ title, message, confirmLabel, danger = false }) {
+  const dlg = els.confirmDialog;
+  $('#confirm-title', dlg).textContent = title;
+  $('#confirm-message', dlg).textContent = message;
+  const ok = $('#confirm-ok', dlg);
+  ok.textContent = confirmLabel;
+  ok.classList.toggle('btn-danger', danger);
+  dlg.returnValue = '';
+  return new Promise((resolve) => {
+    dlg.addEventListener('close', () => resolve(dlg.returnValue === 'confirm'), { once: true });
+    dlg.showModal();
+  });
+}
+
+/* ------------------------------------------------------------------ */
+/* Passkey management                                                   */
+/* ------------------------------------------------------------------ */
+
+els.addPasskey.addEventListener('click', async () => {
+  setStatus('');
+  await busy(els.addPasskey, async () => {
+    try {
+      const options = await withReauth(
+        'To add a new passkey, first confirm it’s you with a passkey you already have.',
+        () => api('POST', '/api/passkeys/options'),
+        { continueLabel: 'Continue to create passkey' },
+      );
+      els.addPasskey.textContent = 'Creating your passkey…';
+      const credential = await createPasskey(options);
+      const session = await api('POST', '/api/passkeys/verify', { credential });
+      applySession(session);
+      signalAccountState(session);
+      const added = session.passkeys.find((p) => p.id === session.added);
+      setStatus(`Passkey added${added ? `: ${added.name}` : ''}. You can rename it below.`, 'success');
+    } catch (err) {
+      const msg = describeError(err, 'create');
+      if (msg) setStatus(msg, 'error');
+    }
+  });
+});
+
+function startRename(li, pk) {
+  const input = h('input', {
+    type: 'text', name: 'name', value: pk.name, maxlength: '64', required: true,
+    'aria-label': 'Passkey name', autocomplete: 'off',
+  });
+  const cancel = h('button', { type: 'button', class: 'btn-link', text: 'Cancel', onclick: () => renderPasskeys() });
+  const save = h('button', { type: 'submit', class: 'btn-small', text: 'Save' });
+  const form = h('form', { class: 'pk-rename' }, input, save, cancel);
+  form.addEventListener('submit', async (e) => {
+    e.preventDefault();
+    if (!form.reportValidity()) return;
+    await busy(save, async () => {
+      try {
+        applySession(await api('PATCH', `/api/passkeys/${encodeURIComponent(pk.id)}`, { name: input.value }));
+        setStatus('Passkey renamed.', 'success');
+      } catch (err) {
+        setStatus(describeError(err), 'error');
+      }
+    });
+  });
+  form.addEventListener('keydown', (e) => {
+    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); renderPasskeys(); }
+  });
+  li.replaceChildren(keyIcon(), form);
+  input.focus();
+  input.select();
+}
+
+async function removePasskey(button, pk) {
+  const confirmed = await confirmAction({
+    title: 'Remove this passkey?',
+    message: `“${pk.name}” will no longer work for signing in to The Daily Grind. ` +
+      'You may also want to delete it from your password manager or device settings.',
+    confirmLabel: 'Remove passkey',
+    danger: true,
+  });
+  if (!confirmed) return;
+  setStatus('');
+  await busy(button, async () => {
+    try {
+      const session = await withReauth(
+        'To remove a passkey, confirm it’s you.',
+        () => api('DELETE', `/api/passkeys/${encodeURIComponent(pk.id)}`),
+      );
+      applySession(session);
+      signalAccountState(session);
+      setStatus(`Removed “${pk.name}”.`, 'success');
+    } catch (err) {
+      const msg = describeError(err, 'get');
+      if (msg) setStatus(msg, 'error');
+    }
+  });
+}
+
+/* ------------------------------------------------------------------ */
+/* Profile                                                              */
+/* ------------------------------------------------------------------ */
+
+els.profileForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const form = els.profileForm;
+  if (!form.reportValidity()) return;
+  const button = event.submitter || form.querySelector('button[type="submit"]');
+  const name = form.elements.name.value.trim();
+  const email = form.elements.email.value.trim();
+  const emailChanged = email.toLowerCase() !== state.session.user.email;
+  setStatus('');
+  await busy(button, async () => {
+    try {
+      const update = () => api('PATCH', '/api/profile', { name, email });
+      const session = emailChanged
+        ? await withReauth('Your email is how we identify your account. To change it, confirm it’s you.', update)
+        : await update();
+      applySession(session);
+      signalAccountState(session);
+      setStatus('Your profile has been updated.', 'success');
+    } catch (err) {
+      const msg = describeError(err, 'get');
+      if (msg) setStatus(msg, 'error');
+      if (err instanceof ApiError && err.data.field) form.elements[err.data.field]?.focus();
+    }
+  });
+});
+
+/* ------------------------------------------------------------------ */
+/* Sign out / delete account                                            */
+/* ------------------------------------------------------------------ */
+
+async function signOut() {
+  try { await api('POST', '/api/logout'); } catch { /* ignore */ }
+  applySession({ ...state.session, user: null, passkeys: [] });
+  setStatus('You’ve been signed out.', 'info');
+}
+
+els.signOut.addEventListener('click', signOut);
+
+els.deleteAccount.addEventListener('click', async () => {
+  const confirmed = await confirmAction({
+    title: 'Delete your account?',
+    message: 'This permanently deletes your Daily Grind account, rewards and saved passkeys. This can’t be undone.',
+    confirmLabel: 'Delete account',
+    danger: true,
+  });
+  if (!confirmed) return;
+  setStatus('');
+  await busy(els.deleteAccount, async () => {
+    try {
+      const { rpId, userHandle } = state.session;
+      await withReauth('To delete your account, confirm it’s you.', () => api('DELETE', '/api/account'));
+      // Tell passkey providers no credentials remain valid for this account.
+      window.PublicKeyCredential?.signalAllAcceptedCredentials?.({
+        rpId, userId: userHandle, allAcceptedCredentialIds: [],
+      }).catch(() => {});
+      applySession({ ...state.session, user: null, passkeys: [] });
+      setStatus('Your account has been deleted. You can now remove its passkey from your password manager.', 'info');
+    } catch (err) {
+      const msg = describeError(err, 'get');
+      if (msg) setStatus(msg, 'error');
+    }
+  });
+});
+
+/* ------------------------------------------------------------------ */
+/* Tabs, dialog & navigation wiring                                     */
+/* ------------------------------------------------------------------ */
+
+function selectTab(name) {
+  for (const tab of els.tabs) {
+    const selected = tab.dataset.accountTab === name;
+    tab.setAttribute('aria-selected', String(selected));
+    tab.tabIndex = selected ? 0 : -1;
+    $(`#${tab.getAttribute('aria-controls')}`).hidden = !selected;
+  }
+  setStatus('');
+}
+
+for (const tab of els.tabs) {
+  tab.addEventListener('click', () => selectTab(tab.dataset.accountTab));
+  tab.addEventListener('keydown', (e) => {
+    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
+    const list = [...els.tabs];
+    const next = list[(list.indexOf(tab) + (e.key === 'ArrowRight' ? 1 : list.length - 1)) % list.length];
+    selectTab(next.dataset.accountTab);
+    next.focus();
+  });
+}
+
+function openAccount(tab) {
+  if (tab) selectTab(tab);
+  if (!els.dialog.open) els.dialog.showModal();
+  if (location.pathname !== '/account') history.pushState({ account: true }, '', '/account');
+  render();
+}
+
+function closeAccount() {
+  if (els.dialog.open) els.dialog.close();
+}
+
+els.dialog.addEventListener('close', () => {
+  stopConditionalSignIn();
+  setStatus('');
+  if (location.pathname === '/account') history.replaceState(null, '', '/');
+});
+els.dialog.addEventListener('click', (e) => {
+  if (e.target === els.dialog) closeAccount(); // backdrop click
+});
+$('#account-close').addEventListener('click', closeAccount);
+
+for (const link of document.querySelectorAll('a[href="/account"]')) {
+  link.addEventListener('click', (e) => { e.preventDefault(); openAccount(); });
+}
+els.navAuth?.addEventListener('click', (e) => {
+  e.preventDefault();
+  if (state.session.user) signOut();
+  else openAccount('signin');
+});
+window.addEventListener('popstate', () => {
+  if (location.pathname === '/account') openAccount();
+  else closeAccount();
+});
+
+/* ------------------------------------------------------------------ */
+/* Boot                                                                 */
+/* ------------------------------------------------------------------ */
+
+selectTab('signin');
+await refreshSession();
+if (location.pathname === '/account') openAccount();
