+// HTTP application for The Daily Grind: serves the static site and the
+// passkey-based "My Account" API. Zero dependencies (Node >= 20).
+
+import fs from 'node:fs';
+import path from 'node:path';
+import crypto from 'node:crypto';
+import { fileURLToPath } from 'node:url';
+
+import { Store, normalizeEmail } from './store.js';
+import {
+  b64url, randomChallenge, verifyRegistration, verifyAuthentication,
+  providerNameFor, SUPPORTED_ALGS, WebAuthnError,
+} from './webauthn.js';
+
+const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
+
+const RP_NAME = 'The Daily Grind';
+const SESSION_COOKIE = 'dg_session';
+const SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;     // absolute session lifetime
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;              // ceremony timeout
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;       // how long a reauth stays "fresh"
+const MAX_BODY_BYTES = 64 * 1024;
+const MAX_SESSIONS = 50_000;
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+const STATIC_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.webp': 'image/webp',
+  '.ico': 'image/x-icon',
+};
+
+const SECURITY_HEADERS = {
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'same-origin',
+  'X-Frame-Options': 'DENY',
+  'Content-Security-Policy': [
+    "default-src 'self'",
+    "script-src 'self'",
+    "style-src 'self' 'unsafe-inline'",
+    "img-src 'self' data: https://images.unsplash.com",
+    "connect-src 'self'",
+    "frame-ancestors 'none'",
+    "base-uri 'self'",
+    "form-action 'self'",
+  ].join('; '),
+};
+
+class HttpError extends Error {
+  constructor(status, code, message, extra = {}) {
+    super(message);
+    this.status = status;
+    this.code = code;
+    this.extra = extra;
+  }
+}
+
+export function createApp({
+  dataFile = process.env.DATA_FILE || path.join(ROOT, 'data', 'db.json'),
+  rpId: configuredRpId = process.env.RP_ID,
+  origins: configuredOrigins = process.env.ORIGIN,
+  trustProxy = process.env.TRUST_PROXY === '1',
+} = {}) {
+  const store = new Store(dataFile);
+  const sessions = new Map();
+  const rateBuckets = new Map();
+
+  setInterval(() => {
+    const now = Date.now();
+    for (const [sid, s] of sessions) if (s.expiresAt < now) sessions.delete(sid);
+    rateBuckets.clear();
+  }, 60_000).unref();
+
+  /* ---------------------------------------------------------------- */
+  /* Request context helpers                                            */
+  /* ---------------------------------------------------------------- */
+
+  function requestProto(req) {
+    if (trustProxy) {
+      const fwd = String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim();
+      if (fwd) return fwd;
+    }
+    return req.socket.encrypted ? 'https' : 'http';
+  }
+
+  function relyingParty(req) {
+    const host = String(req.headers.host || 'localhost');
+    const origins = configuredOrigins
+      ? configuredOrigins.split(',').map((o) => o.trim()).filter(Boolean)
+      : [`${requestProto(req)}://${host}`];
+    const rpId = configuredRpId || new URL(origins[0]).hostname;
+    return { rpId, origins };
+  }
+
+  function parseCookies(req) {
+    const out = {};
+    for (const part of String(req.headers.cookie || '').split(';')) {
+      const i = part.indexOf('=');
+      if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+    }
+    return out;
+  }
+
+  function setSessionCookie(req, res, sid, maxAgeMs) {
+    const attrs = [
+      `${SESSION_COOKIE}=${sid}`, 'Path=/', 'HttpOnly', 'SameSite=Lax',
+      `Max-Age=${Math.floor(maxAgeMs / 1000)}`,
+    ];
+    if (requestProto(req) === 'https') attrs.push('Secure');
+    res.setHeader('Set-Cookie', attrs.join('; '));
+  }
+
+  function getSession(req) {
+    const sid = parseCookies(req)[SESSION_COOKIE];
+    if (!sid) return null;
+    const s = sessions.get(sid);
+    if (!s) return null;
+    if (s.expiresAt < Date.now()) { sessions.delete(sid); return null; }
+    return s;
+  }
+
+  function createSession(req, res, data = {}) {
+    if (sessions.size >= MAX_SESSIONS) {
+      // Evict the oldest session to bound memory use.
+      sessions.delete(sessions.keys().next().value);
+    }
+    const sid = b64url.encode(crypto.randomBytes(32));
+    const session = { sid, expiresAt: Date.now() + SESSION_TTL_MS, challenges: {}, ...data };
+    sessions.set(sid, session);
+    setSessionCookie(req, res, sid, SESSION_TTL_MS);
+    return session;
+  }
+
+  function ensureSession(req, res) {
+    return getSession(req) || createSession(req, res);
+  }
+
+  /** Start a fresh session for a signed-in user (prevents session fixation). */
+  function startUserSession(req, res, oldSession, userId, credentialId, userVerified) {
+    if (oldSession) sessions.delete(oldSession.sid);
+    return createSession(req, res, {
+      userId,
+      credentialId,
+      reauthAt: userVerified ? Date.now() : null,
+    });
+  }
+
+  function destroySession(req, res, session) {
+    if (session) sessions.delete(session.sid);
+    setSessionCookie(req, res, '', 0);
+  }
+
+  function requireUser(session) {
+    const user = session?.userId ? store.getUser(session.userId) : null;
+    if (!user) throw new HttpError(401, 'not_signed_in', 'Please sign in to continue.');
+    return user;
+  }
+
+  function requireRecentAuth(session) {
+    if (!session.reauthAt || Date.now() - session.reauthAt > REAUTH_WINDOW_MS) {
+      throw new HttpError(403, 'reauth_required', 'Please confirm it’s you to continue.');
+    }
+  }
+
+  function storeChallenge(session, purpose, extra = {}) {
+    const challenge = randomChallenge();
+    session.challenges[purpose] = { challenge, expiresAt: Date.now() + CHALLENGE_TTL_MS, ...extra };
+    return challenge;
+  }
+
+  /** Retrieve and consume (single-use) a pending ceremony challenge. */
+  function takeChallenge(session, purpose) {
+    const entry = session?.challenges?.[purpose];
+    if (session) delete session.challenges[purpose];
+    if (!entry || entry.expiresAt < Date.now()) {
+      throw new HttpError(400, 'challenge_expired', 'This request expired. Please try again.');
+    }
+    return entry;
+  }
+
+  function rateLimit(req) {
+    const ip = req.socket.remoteAddress || 'unknown';
+    const count = (rateBuckets.get(ip) || 0) + 1;
+    rateBuckets.set(ip, count);
+    if (count > 120) throw new HttpError(429, 'rate_limited', 'Too many requests. Please slow down.');
+  }
+
+  function checkCsrf(req, rp) {
+    const ct = String(req.headers['content-type'] || '');
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      if (!ct.startsWith('application/json')) {
+        throw new HttpError(415, 'unsupported_media_type', 'Expected application/json.');
+      }
+      const origin = req.headers.origin;
+      const site = req.headers['sec-fetch-site'];
+      const originOk = origin ? rp.origins.includes(origin) : site === 'same-origin';
+      if (!originOk) throw new HttpError(403, 'bad_origin', 'Cross-site request rejected.');
+    }
+  }
+
+  async function readJson(req) {
+    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'DELETE') return {};
+    let size = 0;
+    const chunks = [];
+    for await (const chunk of req) {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) throw new HttpError(413, 'too_large', 'Request body too large.');
+      chunks.push(chunk);
+    }
+    if (!size) return {};
+    try {
+      const body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+      if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error();
+      return body;
+    } catch {
+      throw new HttpError(400, 'bad_json', 'Malformed JSON body.');
+    }
+  }
+
+  /* ---------------------------------------------------------------- */
+  /* Validation & serialisation                                         */
+  /* ---------------------------------------------------------------- */
+
+  function cleanName(value, field = 'name', max = 80) {
+    const v = String(value ?? '').replace(/\s+/g, ' ').trim();
+    if (!v) throw new HttpError(400, 'invalid_input', `Please enter a ${field}.`, { field });
+    if (v.length > max) throw new HttpError(400, 'invalid_input', `That ${field} is too long (max ${max} characters).`, { field });
+    return v;
+  }
+
+  function cleanEmail(value) {
+    const v = normalizeEmail(value);
+    if (!EMAIL_RE.test(v) || v.length > 254) {
+      throw new HttpError(400, 'invalid_input', 'Please enter a valid email address.', { field: 'email' });
+    }
+    return v;
+  }
+
+  function publicUser(user) {
+    return { name: user.name, email: user.email, createdAt: user.createdAt };
+  }
+
+  function publicCredential(cred, session) {
+    return {
+      id: cred.id,
+      name: cred.name,
+      provider: providerNameFor(cred.aaguid),
+      createdAt: cred.createdAt,
+      lastUsedAt: cred.lastUsedAt,
+      backupEligible: cred.backupEligible,
+      backedUp: cred.backedUp,
+      transports: cred.transports,
+      current: cred.id === session.credentialId,
+    };
+  }
+
+  function sessionPayload(session, rp) {
+    const user = session?.userId ? store.getUser(session.userId) : null;
+    if (!user) return { user: null, rpId: rp.rpId, now: Date.now() };
+    const reauthUntil = session.reauthAt ? session.reauthAt + REAUTH_WINDOW_MS : null;
+    return {
+      user: publicUser(user),
+      userHandle: user.handle,
+      rpId: rp.rpId,
+      now: Date.now(),
+      reauthUntil: reauthUntil && reauthUntil > Date.now() ? reauthUntil : null,
+      passkeys: store.listCredentials(user.id)
+        .sort((a, b) => a.createdAt.localeCompare(b.createdAt))
+        .map((c) => publicCredential(c, session)),
+    };
+  }
+
+  function creationOptions(rp, challenge, user, existing) {
+    return {
+      challenge,
+      rp: { name: RP_NAME, id: rp.rpId },
+      user: { id: user.handle, name: user.email, displayName: user.name },
+      pubKeyCredParams: SUPPORTED_ALGS.map((alg) => ({ type: 'public-key', alg })),
+      timeout: CHALLENGE_TTL_MS,
+      attestation: 'none',
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'preferred',
+      },
+      excludeCredentials: existing.map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+      extensions: { credProps: true },
+    };
+  }
+
+  function saveNewCredential(userId, verified, requestedName) {
+    const provider = providerNameFor(verified.aaguid);
+    const now = new Date().toISOString();
+    let name = provider || 'Passkey';
+    if (requestedName) {
+      try { name = cleanName(requestedName, 'passkey name', 64); } catch { /* keep default */ }
+    }
+    return store.addCredential({
+      id: verified.credentialId,
+      userId,
+      publicKey: verified.publicKey,
+      alg: verified.alg,
+      signCount: verified.signCount,
+      aaguid: verified.aaguid,
+      transports: verified.transports,
+      backupEligible: verified.backupEligible,
+      backedUp: verified.backedUp,
+      name,
+      createdAt: now,
+      lastUsedAt: now,
+    });
+  }
+
+  /* ---------------------------------------------------------------- */
+  /* API routes                                                         */
+  /* ---------------------------------------------------------------- */
+
+  const routes = {
+    'GET /api/session': ({ session, rp }) => sessionPayload(session, rp),
+
+    /* ---- Registration (new customer) ---- */
+    'POST /api/register/options': ({ req, res, body, rp }) => {
+      const name = cleanName(body.name);
+      const email = cleanEmail(body.email);
+      if (store.getUserByEmail(email)) {
+        throw new HttpError(409, 'email_taken', 'An account with this email already exists. Try signing in with your passkey.', { field: 'email' });
+      }
+      const session = ensureSession(req, res);
+      const handle = b64url.encode(crypto.randomBytes(32));
+      const challenge = storeChallenge(session, 'register', { name, email, handle });
+      return creationOptions(rp, challenge, { handle, name, email }, []);
+    },
+
+    'POST /api/register/verify': async ({ req, res, body, session, rp }) => {
+      const pending = takeChallenge(session, 'register');
+      if (store.getUserByEmail(pending.email)) {
+        throw new HttpError(409, 'email_taken', 'An account with this email already exists.');
+      }
+      const verified = verifyRegistration(body.credential, {
+        expectedChallenge: pending.challenge, expectedOrigins: rp.origins, rpId: rp.rpId,
+      });
+      if (store.getCredential(verified.credentialId)) {
+        throw new HttpError(409, 'credential_exists', 'This passkey is already registered.');
+      }
+      const user = store.createUser({ name: pending.name, email: pending.email, handle: pending.handle });
+      saveNewCredential(user.id, verified, body.passkeyName);
+      await store.save();
+      const newSession = startUserSession(req, res, session, user.id, verified.credentialId, verified.userVerified);
+      return sessionPayload(newSession, rp);
+    },
+
+    /* ---- Sign in (discoverable credential / autofill) ---- */
+    // Autofill (conditional mediation) and the explicit "Sign in" button run
+    // independent ceremonies, so they keep separate pending challenges.
+    'POST /api/login/options': ({ req, res, body, rp }) => {
+      const session = ensureSession(req, res);
+      const challenge = storeChallenge(session, body.autofill ? 'login-autofill' : 'login');
+      return {
+        challenge,
+        rpId: rp.rpId,
+        timeout: CHALLENGE_TTL_MS,
+        userVerification: 'preferred',
+        allowCredentials: [],
+      };
+    },
+
+    'POST /api/login/verify': async ({ req, res, body, session, rp }) => {
+      const pending = takeChallenge(session, body.autofill ? 'login-autofill' : 'login');
+      const credId = body.credential?.id;
+      const stored = typeof credId === 'string' ? store.getCredential(credId) : null;
+      const user = stored ? store.getUser(stored.userId) : null;
+      if (!stored || !user) {
+        throw new HttpError(404, 'unknown_credential',
+          'We don’t recognise this passkey. It may have been removed from your account.',
+          { credentialId: typeof credId === 'string' ? credId : undefined });
+      }
+      const result = verifyAuthentication(body.credential, stored, {
+        expectedChallenge: pending.challenge, expectedOrigins: rp.origins, rpId: rp.rpId,
+        expectedUserHandle: user.handle,
+      });
+      store.updateCredential(stored.id, {
+        signCount: result.signCount, backedUp: result.backedUp, lastUsedAt: new Date().toISOString(),
+      });
+      await store.save();
+      const newSession = startUserSession(req, res, session, user.id, stored.id, result.userVerified);
+      return sessionPayload(newSession, rp);
+    },
+
+    'POST /api/logout': ({ req, res, session }) => {
+      destroySession(req, res, session);
+      return { ok: true };
+    },
+
+    /* ---- Reauthentication ---- */
+    'POST /api/reauth/options': ({ session, rp }) => {
+      const user = requireUser(session);
+      const challenge = storeChallenge(session, 'reauth');
+      return {
+        challenge,
+        rpId: rp.rpId,
+        timeout: CHALLENGE_TTL_MS,
+        userVerification: 'required',
+        allowCredentials: store.listCredentials(user.id)
+          .map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+      };
+    },
+
+    'POST /api/reauth/verify': async ({ body, session, rp }) => {
+      const user = requireUser(session);
+      const pending = takeChallenge(session, 'reauth');
+      const stored = store.getCredential(body.credential?.id);
+      if (!stored || stored.userId !== user.id) {
+        throw new HttpError(400, 'wrong_credential', 'Please use a passkey saved to this account.');
+      }
+      const result = verifyAuthentication(body.credential, stored, {
+        expectedChallenge: pending.challenge, expectedOrigins: rp.origins, rpId: rp.rpId,
+        requireUserVerification: true, expectedUserHandle: user.handle,
+      });
+      store.updateCredential(stored.id, {
+        signCount: result.signCount, backedUp: result.backedUp, lastUsedAt: new Date().toISOString(),
+      });
+      await store.save();
+      session.reauthAt = Date.now();
+      return sessionPayload(session, rp);
+    },
+
+    /* ---- Profile ---- */
+    'PATCH /api/profile': async ({ body, session, rp }) => {
+      const user = requireUser(session);
+      const changes = {};
+      if (body.name !== undefined) changes.name = cleanName(body.name);
+      if (body.email !== undefined) {
+        const email = cleanEmail(body.email);
+        if (email !== user.email) {
+          requireRecentAuth(session); // changing the sign-in identifier is sensitive
+          const other = store.getUserByEmail(email);
+          if (other && other.id !== user.id) {
+            throw new HttpError(409, 'email_taken', 'That email is already used by another account.', { field: 'email' });
+          }
+          changes.email = email;
+        }
+      }
+      store.updateUser(user.id, changes);
+      await store.save();
+      return sessionPayload(session, rp);
+    },
+
+    'DELETE /api/account': async ({ req, res, session }) => {
+      const user = requireUser(session);
+      requireRecentAuth(session);
+      store.deleteUser(user.id);
+      await store.save();
+      for (const [sid, s] of sessions) if (s.userId === user.id) sessions.delete(sid);
+      destroySession(req, res, session);
+      return { ok: true };
+    },
+
+    /* ---- Passkey management ---- */
+    'POST /api/passkeys/options': ({ session, rp }) => {
+      const user = requireUser(session);
+      requireRecentAuth(session);
+      const challenge = storeChallenge(session, 'add-passkey');
+      return creationOptions(rp, challenge, user, store.listCredentials(user.id));
+    },
+
+    'POST /api/passkeys/verify': async ({ body, session, rp }) => {
+      const user = requireUser(session);
+      const pending = takeChallenge(session, 'add-passkey');
+      const verified = verifyRegistration(body.credential, {
+        expectedChallenge: pending.challenge, expectedOrigins: rp.origins, rpId: rp.rpId,
+      });
+      if (store.getCredential(verified.credentialId)) {
+        throw new HttpError(409, 'credential_exists', 'This passkey is already registered.');
+      }
+      const cred = saveNewCredential(user.id, verified, body.passkeyName);
+      await store.save();
+      return { ...sessionPayload(session, rp), added: cred.id };
+    },
+  };
+
+  const paramRoutes = [
+    {
+      method: 'PATCH', pattern: /^\/api\/passkeys\/([A-Za-z0-9_-]{1,1400})$/,
+      handler: async ({ body, session, rp }, id) => {
+        const user = requireUser(session);
+        const cred = store.getCredential(id);
+        if (!cred || cred.userId !== user.id) throw new HttpError(404, 'not_found', 'Passkey not found.');
+        store.updateCredential(id, { name: cleanName(body.name, 'passkey name', 64) });
+        await store.save();
+        return sessionPayload(session, rp);
+      },
+    },
+    {
+      method: 'DELETE', pattern: /^\/api\/passkeys\/([A-Za-z0-9_-]{1,1400})$/,
+      handler: async ({ session, rp }, id) => {
+        const user = requireUser(session);
+        const cred = store.getCredential(id);
+        if (!cred || cred.userId !== user.id) throw new HttpError(404, 'not_found', 'Passkey not found.');
+        requireRecentAuth(session);
+        if (store.listCredentials(user.id).length <= 1) {
+          throw new HttpError(409, 'last_passkey',
+            'You can’t remove your only passkey — you’d be locked out. Add another passkey first.');
+        }
+        store.deleteCredential(id);
+        await store.save();
+        return sessionPayload(session, rp);
+      },
+    },
+  ];
+
+  /* ---------------------------------------------------------------- */
+  /* Static files                                                       */
+  /* ---------------------------------------------------------------- */
+
+  const PAGES = { '/': 'index.html', '/index.html': 'index.html', '/account': 'index.html' };
+  const ASSET_DIR = path.join(ROOT, 'assets');
+
+  function serveStatic(req, res, pathname) {
+    let file = PAGES[pathname] ? path.join(ROOT, PAGES[pathname]) : null;
+    if (!file && pathname.startsWith('/assets/')) {
+      const resolved = path.resolve(ASSET_DIR, '.' + decodeURIComponent(pathname.slice('/assets'.length)));
+      if (resolved.startsWith(ASSET_DIR + path.sep)) file = resolved;
+    }
+    if (file) {
+      try {
+        const data = fs.readFileSync(file);
+        res.writeHead(200, {
+          ...SECURITY_HEADERS,
+          'Content-Type': STATIC_TYPES[path.extname(file)] || 'application/octet-stream',
+          'Cache-Control': file.endsWith('.html') ? 'no-cache' : 'public, max-age=300',
+        });
+        return res.end(req.method === 'HEAD' ? undefined : data);
+      } catch { /* fall through to 404 */ }
+    }
+    res.writeHead(404, { ...SECURITY_HEADERS, 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not found');
+  }
+
+  /* ---------------------------------------------------------------- */
+  /* Dispatcher                                                         */
+  /* ---------------------------------------------------------------- */
+
+  function sendJson(res, status, payload) {
+    res.writeHead(status, {
+      ...SECURITY_HEADERS,
+      'Content-Type': 'application/json; charset=utf-8',
+      'Cache-Control': 'no-store',
+    });
+    res.end(JSON.stringify(payload));
+  }
+
+  return async function handler(req, res) {
+    let pathname;
+    try {
+      pathname = new URL(req.url, 'http://localhost').pathname;
+    } catch {
+      return sendJson(res, 400, { error: 'bad_request', message: 'Bad request.' });
+    }
+
+    if (!pathname.startsWith('/api/')) {
+      if (req.method !== 'GET' && req.method !== 'HEAD') {
+        res.writeHead(405, SECURITY_HEADERS);
+        return res.end();
+      }
+      return serveStatic(req, res, pathname);
+    }
+
+    try {
+      const rp = relyingParty(req);
+      if (req.method !== 'GET') rateLimit(req);
+      checkCsrf(req, rp);
+
+      let handler = routes[`${req.method} ${pathname}`];
+      let param;
+      if (!handler) {
+        for (const r of paramRoutes) {
+          const m = r.method === req.method && pathname.match(r.pattern);
+          if (m) { handler = r.handler; param = m[1]; break; }
+        }
+      }
+      if (!handler) throw new HttpError(404, 'not_found', 'Not found.');
+
+      const body = await readJson(req);
+      const session = getSession(req);
+      const result = await handler({ req, res, body, session, rp }, param);
+      sendJson(res, 200, result);
+    } catch (err) {
+      if (err instanceof HttpError) {
+        return sendJson(res, err.status, { error: err.code, message: err.message, ...err.extra });
+      }
+      if (err instanceof WebAuthnError) {
+        return sendJson(res, 400, {
+          error: err.code,
+          message: 'We couldn’t verify your passkey. Please try again.',
+          detail: err.message,
+        });
+      }
+      console.error(err);
+      sendJson(res, 500, { error: 'server_error', message: 'Something went wrong. Please try again.' });
+    }
+  };
+}
