+// Entry point: `npm start` (or `node server/index.js`).
+//
+// Environment variables:
+//   PORT         Port to listen on (default 11222)
+//   RP_ID        WebAuthn relying-party ID, e.g. "dailygrind.example" (default: request host)
+//   ORIGIN       Comma-separated allowed origins, e.g. "https://dailygrind.example"
+//                (default: derived from the request's Host header)
+//   TRUST_PROXY  Set to 1 to honour X-Forwarded-Proto behind a TLS-terminating proxy
+//   DATA_FILE    Path of the JSON data file (default ./data/db.json)
+
+import http from 'node:http';
+import { createApp } from './app.js';
+
+const port = Number(process.env.PORT) || 11222;
+const server = http.createServer(createApp());
+server.listen(port, () => {
+  console.log(`The Daily Grind is running at http://localhost:${port}`);
+});
diff --git a/server/store.js b/server/store.js
new file mode 100644
index 0000000..294c961
--- /dev/null
+++ b/server/store.js
@@ -0,0 +1,101 @@
+// Tiny JSON-file persistence for customer accounts and their passkeys.
+// Writes are serialised and atomic (write to temp file, then rename).
+
+import fs from 'node:fs';
+import path from 'node:path';
+import crypto from 'node:crypto';
+
+export class Store {
+  constructor(file) {
+    this.file = file;
+    this.data = { users: [], credentials: [] };
+    this.writing = Promise.resolve();
+    try {
+      const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
+      this.data.users = Array.isArray(parsed.users) ? parsed.users : [];
+      this.data.credentials = Array.isArray(parsed.credentials) ? parsed.credentials : [];
+    } catch (err) {
+      if (err.code !== 'ENOENT') throw err;
+    }
+  }
+
+  save() {
+    const snapshot = JSON.stringify(this.data, null, 2);
+    this.writing = this.writing.then(async () => {
+      await fs.promises.mkdir(path.dirname(this.file), { recursive: true });
+      const tmp = `${this.file}.${process.pid}.tmp`;
+      await fs.promises.writeFile(tmp, snapshot, { mode: 0o600 });
+      await fs.promises.rename(tmp, this.file);
+    }).catch((err) => console.error('Failed to persist store:', err));
+    return this.writing;
+  }
+
+  /* Users ------------------------------------------------------------ */
+
+  getUser(id) {
+    return this.data.users.find((u) => u.id === id) || null;
+  }
+
+  getUserByEmail(email) {
+    const e = normalizeEmail(email);
+    return this.data.users.find((u) => u.email === e) || null;
+  }
+
+  createUser({ name, email, handle }) {
+    const now = new Date().toISOString();
+    const user = {
+      id: crypto.randomUUID(),
+      handle, // WebAuthn user.id (opaque, random, no PII)
+      name,
+      email: normalizeEmail(email),
+      createdAt: now,
+      updatedAt: now,
+    };
+    this.data.users.push(user);
+    return user;
+  }
+
+  updateUser(id, changes) {
+    const user = this.getUser(id);
+    if (!user) return null;
+    if (changes.name !== undefined) user.name = changes.name;
+    if (changes.email !== undefined) user.email = normalizeEmail(changes.email);
+    user.updatedAt = new Date().toISOString();
+    return user;
+  }
+
+  deleteUser(id) {
+    this.data.users = this.data.users.filter((u) => u.id !== id);
+    this.data.credentials = this.data.credentials.filter((c) => c.userId !== id);
+  }
+
+  /* Credentials -------------------------------------------------------- */
+
+  getCredential(id) {
+    return this.data.credentials.find((c) => c.id === id) || null;
+  }
+
+  listCredentials(userId) {
+    return this.data.credentials.filter((c) => c.userId === userId);
+  }
+
+  addCredential(record) {
+    this.data.credentials.push(record);
+    return record;
+  }
+
+  updateCredential(id, changes) {
+    const cred = this.getCredential(id);
+    if (!cred) return null;
+    Object.assign(cred, changes);
+    return cred;
+  }
+
+  deleteCredential(id) {
+    this.data.credentials = this.data.credentials.filter((c) => c.id !== id);
+  }
+}
+
+export function normalizeEmail(email) {
+  return String(email || '').trim().toLowerCase();
+}
diff --git a/server/webauthn.js b/server/webauthn.js
new file mode 100644
index 0000000..fbdeae8
--- /dev/null
+++ b/server/webauthn.js
@@ -0,0 +1,397 @@
+// Minimal, dependency-free WebAuthn (passkey) relying-party helpers.
+//
+// Implements the parts of WebAuthn Level 3 needed by a passkey RP that uses
+// `attestation: "none"`: CBOR/COSE decoding, authenticator-data parsing and
+// verification of registration and authentication ceremonies.
+
+import crypto from 'node:crypto';
+
+/* ------------------------------------------------------------------ */
+/* base64url                                                            */
+/* ------------------------------------------------------------------ */
+
+export const b64url = {
+  encode: (buf) => Buffer.from(buf).toString('base64url'),
+  decode: (str) => {
+    if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*={0,2}$/.test(str)) {
+      throw new WebAuthnError('Malformed base64url value');
+    }
+    return Buffer.from(str, 'base64url');
+  },
+};
+
+export class WebAuthnError extends Error {
+  constructor(message, code = 'webauthn_error') {
+    super(message);
+    this.code = code;
+  }
+}
+
+export function randomChallenge() {
+  return b64url.encode(crypto.randomBytes(32));
+}
+
+/* ------------------------------------------------------------------ */
+/* CBOR (RFC 8949) – decoder for the subset used by WebAuthn            */
+/* ------------------------------------------------------------------ */
+
+export function decodeCBOR(buf, offset = 0) {
+  const view = Buffer.from(buf);
+  let pos = offset;
+  let depth = 0;
+
+  const need = (n) => {
+    if (pos + n > view.length) throw new WebAuthnError('Truncated CBOR data');
+  };
+
+  const readLength = (info) => {
+    if (info < 24) return info;
+    if (info === 24) { need(1); return view.readUInt8(pos++); }
+    if (info === 25) { need(2); const v = view.readUInt16BE(pos); pos += 2; return v; }
+    if (info === 26) { need(4); const v = view.readUInt32BE(pos); pos += 4; return v; }
+    if (info === 27) {
+      need(8);
+      const v = view.readBigUInt64BE(pos); pos += 8;
+      if (v > BigInt(Number.MAX_SAFE_INTEGER)) throw new WebAuthnError('CBOR integer too large');
+      return Number(v);
+    }
+    throw new WebAuthnError('Unsupported CBOR length encoding');
+  };
+
+  const readItem = () => {
+    if (++depth > 32) throw new WebAuthnError('CBOR nesting too deep');
+    need(1);
+    const initial = view.readUInt8(pos++);
+    const major = initial >> 5;
+    const info = initial & 0x1f;
+    let result;
+
+    switch (major) {
+      case 0: result = readLength(info); break;
+      case 1: result = -1 - readLength(info); break;
+      case 2: {
+        const len = readLength(info); need(len);
+        result = Buffer.from(view.subarray(pos, pos + len)); pos += len; break;
+      }
+      case 3: {
+        const len = readLength(info); need(len);
+        result = view.toString('utf8', pos, pos + len); pos += len; break;
+      }
+      case 4: {
+        const len = readLength(info);
+        result = [];
+        for (let i = 0; i < len; i++) result.push(readItem());
+        break;
+      }
+      case 5: {
+        const len = readLength(info);
+        result = new Map();
+        for (let i = 0; i < len; i++) {
+          const k = readItem();
+          result.set(k, readItem());
+        }
+        break;
+      }
+      case 6: readLength(info); result = readItem(); break; // ignore tags
+      case 7: {
+        if (info === 20) result = false;
+        else if (info === 21) result = true;
+        else if (info === 22) result = null;
+        else if (info === 23) result = undefined;
+        else if (info === 25) { need(2); result = halfToFloat(view.readUInt16BE(pos)); pos += 2; }
+        else if (info === 26) { need(4); result = view.readFloatBE(pos); pos += 4; }
+        else if (info === 27) { need(8); result = view.readDoubleBE(pos); pos += 8; }
+        else throw new WebAuthnError('Unsupported CBOR simple value');
+        break;
+      }
+      default:
+        throw new WebAuthnError('Unsupported CBOR major type');
+    }
+    depth--;
+    return result;
+  };
+
+  const value = readItem();
+  return { value, offset: pos };
+}
+
+function halfToFloat(h) {
+  const s = (h & 0x8000) ? -1 : 1;
+  const e = (h >> 10) & 0x1f;
+  const f = h & 0x3ff;
+  if (e === 0) return s * 2 ** -14 * (f / 1024);
+  if (e === 31) return f ? NaN : s * Infinity;
+  return s * 2 ** (e - 15) * (1 + f / 1024);
+}
+
+/* ------------------------------------------------------------------ */
+/* COSE keys                                                            */
+/* ------------------------------------------------------------------ */
+
+export const COSE_ALG = { ES256: -7, EdDSA: -8, ES384: -35, ES512: -36, PS256: -37, RS256: -257 };
+export const SUPPORTED_ALGS = [COSE_ALG.ES256, COSE_ALG.EdDSA, COSE_ALG.RS256];
+
+const EC_CURVES = { 1: 'P-256', 2: 'P-384', 3: 'P-521' };
+const ALG_HASH = {
+  [COSE_ALG.ES256]: 'sha256', [COSE_ALG.ES384]: 'sha384', [COSE_ALG.ES512]: 'sha512',
+  [COSE_ALG.RS256]: 'sha256', [COSE_ALG.PS256]: 'sha256', [COSE_ALG.EdDSA]: null,
+};
+
+/** Convert a CBOR-encoded COSE_Key into a Node KeyObject plus its algorithm. */
+export function coseToPublicKey(coseBytes) {
+  const { value: key } = decodeCBOR(coseBytes);
+  if (!(key instanceof Map)) throw new WebAuthnError('Invalid COSE key');
+  const kty = key.get(1);
+  const alg = key.get(3);
+  if (!(alg in ALG_HASH)) throw new WebAuthnError(`Unsupported COSE algorithm ${alg}`);
+
+  let jwk;
+  if (kty === 2) {
+    const crv = EC_CURVES[key.get(-1)];
+    const x = key.get(-2);
+    const y = key.get(-3);
+    if (!crv || !Buffer.isBuffer(x) || !Buffer.isBuffer(y)) throw new WebAuthnError('Invalid EC2 key');
+    if (![COSE_ALG.ES256, COSE_ALG.ES384, COSE_ALG.ES512].includes(alg)) throw new WebAuthnError('EC2 key/alg mismatch');
+    jwk = { kty: 'EC', crv, x: b64url.encode(x), y: b64url.encode(y) };
+  } else if (kty === 3) {
+    const n = key.get(-1);
+    const e = key.get(-2);
+    if (!Buffer.isBuffer(n) || !Buffer.isBuffer(e)) throw new WebAuthnError('Invalid RSA key');
+    if (![COSE_ALG.RS256, COSE_ALG.PS256].includes(alg)) throw new WebAuthnError('RSA key/alg mismatch');
+    jwk = { kty: 'RSA', n: b64url.encode(n), e: b64url.encode(e) };
+  } else if (kty === 1) {
+    const x = key.get(-2);
+    if (key.get(-1) !== 6 || !Buffer.isBuffer(x)) throw new WebAuthnError('Unsupported OKP key');
+    if (alg !== COSE_ALG.EdDSA) throw new WebAuthnError('OKP key/alg mismatch');
+    jwk = { kty: 'OKP', crv: 'Ed25519', x: b64url.encode(x) };
+  } else {
+    throw new WebAuthnError('Unsupported COSE key type');
+  }
+
+  try {
+    return { alg, keyObject: crypto.createPublicKey({ key: jwk, format: 'jwk' }) };
+  } catch {
+    throw new WebAuthnError('Invalid public key');
+  }
+}
+
+function verifySignature(alg, keyObject, data, signature) {
+  const hash = ALG_HASH[alg];
+  if (alg === COSE_ALG.EdDSA) return crypto.verify(null, data, keyObject, signature);
+  if (alg === COSE_ALG.PS256) {
+    return crypto.verify(hash, data, {
+      key: keyObject,
+      padding: crypto.constants.RSA_PKCS1_PSS_PADDING,
+      saltLength: 32,
+    }, signature);
+  }
+  return crypto.verify(hash, data, keyObject, signature); // ECDSA (DER) / RSASSA-PKCS1-v1_5
+}
+
+/* ------------------------------------------------------------------ */
+/* Authenticator data                                                   */
+/* ------------------------------------------------------------------ */
+
+const FLAG_UP = 0x01;
+const FLAG_UV = 0x04;
+const FLAG_BE = 0x08;
+const FLAG_BS = 0x10;
+const FLAG_AT = 0x40;
+const FLAG_ED = 0x80;
+
+export function parseAuthenticatorData(authData) {
+  const buf = Buffer.from(authData);
+  if (buf.length < 37) throw new WebAuthnError('Authenticator data too short');
+  const rpIdHash = buf.subarray(0, 32);
+  const flagsByte = buf.readUInt8(32);
+  const flags = {
+    up: !!(flagsByte & FLAG_UP),
+    uv: !!(flagsByte & FLAG_UV),
+    be: !!(flagsByte & FLAG_BE),
+    bs: !!(flagsByte & FLAG_BS),
+    at: !!(flagsByte & FLAG_AT),
+    ed: !!(flagsByte & FLAG_ED),
+  };
+  const signCount = buf.readUInt32BE(33);
+  let pos = 37;
+  const result = { rpIdHash, flags, signCount };
+
+  if (flags.at) {
+    if (buf.length < pos + 18) throw new WebAuthnError('Attested credential data truncated');
+    const aaguid = buf.subarray(pos, pos + 16); pos += 16;
+    const credIdLen = buf.readUInt16BE(pos); pos += 2;
+    if (credIdLen > 1023 || buf.length < pos + credIdLen) throw new WebAuthnError('Invalid credential ID length');
+    const credentialId = buf.subarray(pos, pos + credIdLen); pos += credIdLen;
+    const { offset } = decodeCBOR(buf, pos);
+    const credentialPublicKey = buf.subarray(pos, offset); pos = offset;
+    result.attestedCredentialData = { aaguid: formatAaguid(aaguid), credentialId, credentialPublicKey };
+  }
+  if (flags.ed) {
+    const { offset } = decodeCBOR(buf, pos);
+    pos = offset;
+  }
+  if (pos !== buf.length) throw new WebAuthnError('Unexpected trailing bytes in authenticator data');
+  if (flags.bs && !flags.be) throw new WebAuthnError('Invalid backup flags');
+  return result;
+}
+
+function formatAaguid(bytes) {
+  const h = Buffer.from(bytes).toString('hex');
+  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
+}
+
+/* ------------------------------------------------------------------ */
+/* Ceremony verification                                                */
+/* ------------------------------------------------------------------ */
+
+function parseClientData(clientDataJSONb64, { type, expectedChallenge, expectedOrigins }) {
+  const raw = b64url.decode(clientDataJSONb64);
+  let clientData;
+  try {
+    clientData = JSON.parse(raw.toString('utf8'));
+  } catch {
+    throw new WebAuthnError('Malformed clientDataJSON');
+  }
+  if (clientData.type !== type) throw new WebAuthnError('Unexpected ceremony type');
+  if (!expectedChallenge || typeof clientData.challenge !== 'string' ||
+      !timingSafeEqualStr(clientData.challenge, expectedChallenge)) {
+    throw new WebAuthnError('Challenge mismatch', 'challenge_mismatch');
+  }
+  if (!expectedOrigins.includes(clientData.origin)) throw new WebAuthnError('Origin mismatch', 'origin_mismatch');
+  if (clientData.crossOrigin === true) throw new WebAuthnError('Cross-origin ceremonies are not allowed');
+  return { raw, clientData };
+}
+
+function timingSafeEqualStr(a, b) {
+  const ab = Buffer.from(a);
+  const bb = Buffer.from(b);
+  return ab.length === bb.length && crypto.timingSafeEqual(ab, bb);
+}
+
+function checkRpIdHash(rpIdHash, rpId) {
+  const expected = crypto.createHash('sha256').update(rpId).digest();
+  if (!crypto.timingSafeEqual(Buffer.from(rpIdHash), expected)) {
+    throw new WebAuthnError('RP ID mismatch', 'rpid_mismatch');
+  }
+}
+
+/**
+ * Verify a registration (navigator.credentials.create) response.
+ * @param {object} credential  PublicKeyCredential JSON (toJSON() shape)
+ */
+export function verifyRegistration(credential, {
+  expectedChallenge, expectedOrigins, rpId, requireUserVerification = false, allowedAlgs = SUPPORTED_ALGS,
+}) {
+  if (!credential || credential.type !== 'public-key' || !credential.response) {
+    throw new WebAuthnError('Invalid credential');
+  }
+  const { response } = credential;
+  parseClientData(response.clientDataJSON, { type: 'webauthn.create', expectedChallenge, expectedOrigins });
+
+  const { value: attObj } = decodeCBOR(b64url.decode(response.attestationObject));
+  if (!(attObj instanceof Map) || !Buffer.isBuffer(attObj.get('authData'))) {
+    throw new WebAuthnError('Malformed attestation object');
+  }
+  // We request `attestation: "none"`, so the attestation statement is not
+  // evaluated (per WebAuthn §7.1 step 21, the RP may accept it as-is).
+  const authData = parseAuthenticatorData(attObj.get('authData'));
+  checkRpIdHash(authData.rpIdHash, rpId);
+  if (!authData.flags.up) throw new WebAuthnError('User presence required');
+  if (requireUserVerification && !authData.flags.uv) throw new WebAuthnError('User verification required', 'uv_required');
+  if (!authData.attestedCredentialData) throw new WebAuthnError('Missing attested credential data');
+
+  const { credentialId, credentialPublicKey, aaguid } = authData.attestedCredentialData;
+  if (b64url.encode(credentialId) !== credential.id || credential.rawId !== credential.id) {
+    throw new WebAuthnError('Credential ID mismatch');
+  }
+  const { alg } = coseToPublicKey(credentialPublicKey);
+  if (!allowedAlgs.includes(alg)) throw new WebAuthnError('Algorithm not allowed');
+
+  const transports = Array.isArray(response.transports)
+    ? response.transports.filter((t) => typeof t === 'string' && t.length < 32).slice(0, 8)
+    : [];
+
+  return {
+    credentialId: credential.id,
+    publicKey: b64url.encode(credentialPublicKey),
+    alg,
+    signCount: authData.signCount,
+    aaguid,
+    transports,
+    userVerified: authData.flags.uv,
+    backupEligible: authData.flags.be,
+    backedUp: authData.flags.bs,
+  };
+}
+
+/**
+ * Verify an authentication (navigator.credentials.get) response against a
+ * stored credential record.
+ */
+export function verifyAuthentication(credential, storedCredential, {
+  expectedChallenge, expectedOrigins, rpId, requireUserVerification = false, expectedUserHandle,
+}) {
+  if (!credential || credential.type !== 'public-key' || !credential.response) {
+    throw new WebAuthnError('Invalid credential');
+  }
+  if (credential.id !== storedCredential.id) throw new WebAuthnError('Credential mismatch');
+  const { response } = credential;
+  const { raw: clientDataRaw } = parseClientData(response.clientDataJSON, {
+    type: 'webauthn.get', expectedChallenge, expectedOrigins,
+  });
+
+  const authDataRaw = b64url.decode(response.authenticatorData);
+  const authData = parseAuthenticatorData(authDataRaw);
+  checkRpIdHash(authData.rpIdHash, rpId);
+  if (!authData.flags.up) throw new WebAuthnError('User presence required');
+  if (requireUserVerification && !authData.flags.uv) throw new WebAuthnError('User verification required', 'uv_required');
+  if (response.userHandle && expectedUserHandle && response.userHandle !== expectedUserHandle) {
+    throw new WebAuthnError('User handle mismatch');
+  }
+
+  const { alg, keyObject } = coseToPublicKey(b64url.decode(storedCredential.publicKey));
+  const clientDataHash = crypto.createHash('sha256').update(clientDataRaw).digest();
+  const signedData = Buffer.concat([authDataRaw, clientDataHash]);
+  if (!verifySignature(alg, keyObject, signedData, b64url.decode(response.signature))) {
+    throw new WebAuthnError('Invalid signature', 'bad_signature');
+  }
+
+  const stored = storedCredential.signCount || 0;
+  if ((authData.signCount !== 0 || stored !== 0) && authData.signCount <= stored) {
+    throw new WebAuthnError('Signature counter did not increase; the authenticator may be cloned', 'counter_error');
+  }
+
+  return {
+    signCount: authData.signCount,
+    userVerified: authData.flags.uv,
+    backupEligible: authData.flags.be,
+    backedUp: authData.flags.bs,
+  };
+}
+
+/* ------------------------------------------------------------------ */
+/* Friendly provider names for common passkey providers (by AAGUID)     */
+/* ------------------------------------------------------------------ */
+
+const KNOWN_AAGUIDS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  '50726f74-6f6e-5061-7373-50726f746f6e': 'Proton Pass',
+  'fdb141b2-5d84-443e-8a35-4698c205a502': 'KeePassXC',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  '771b48fd-d3d4-4f74-9232-fc157ab0507a': 'Microsoft Password Manager',
+};
+
+export function providerNameFor(aaguid) {
+  return KNOWN_AAGUIDS[aaguid] || null;
+}
