+// End-to-end tests of the account API, driving the request handler directly
+// with in-memory request/response objects (no network listener).
+
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import os from 'node:os';
+import path from 'node:path';
+import fs from 'node:fs';
+import { Readable } from 'node:stream';
+
+import { createApp } from '../server/app.js';
+import { SoftAuthenticator } from './helpers/authenticator.js';
+
+const ORIGIN = 'http://localhost:11222';
+
+function makeClient() {
+  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'dg-test-'));
+  const handler = createApp({ dataFile: path.join(dir, 'db.json'), rpId: undefined, origins: undefined });
+  let cookie = '';
+
+  async function call(method, url, body, { origin = ORIGIN } = {}) {
+    const payload = body === undefined ? '' : JSON.stringify(body);
+    const req = Readable.from(payload ? [Buffer.from(payload)] : []);
+    Object.assign(req, {
+      method, url,
+      headers: {
+        host: 'localhost:11222',
+        'content-type': 'application/json',
+        ...(origin ? { origin } : {}),
+        ...(cookie ? { cookie } : {}),
+      },
+      socket: { remoteAddress: '127.0.0.1', encrypted: false },
+    });
+    const res = await new Promise((resolve) => {
+      const out = { headers: {}, status: 0, body: '' };
+      out.setHeader = (k, v) => { out.headers[k.toLowerCase()] = v; };
+      out.writeHead = (s, h = {}) => { out.status = s; for (const [k, v] of Object.entries(h)) out.setHeader(k, v); };
+      out.end = (d) => { if (d) out.body += d; resolve(out); };
+      handler(req, out);
+    });
+    const setCookie = res.headers['set-cookie'];
+    if (setCookie) cookie = setCookie.split(';')[0];
+    return { status: res.status, data: res.body ? JSON.parse(res.body) : null };
+  }
+  return { call, dir };
+}
+
+async function signUp(client, auth, name = 'Ada Lovelace', email = 'ada@example.com') {
+  const opts = await client.call('POST', '/api/register/options', { name, email });
+  assert.equal(opts.status, 200);
+  const credential = auth.create(opts.data, { origin: ORIGIN });
+  return client.call('POST', '/api/register/verify', { credential });
+}
+
+async function reauth(client, auth) {
+  const opts = await client.call('POST', '/api/reauth/options', {});
+  assert.equal(opts.status, 200);
+  assert.equal(opts.data.userVerification, 'required');
+  return client.call('POST', '/api/reauth/verify', { credential: auth.get(opts.data, { origin: ORIGIN }) });
+}
+
+test('register, sign out, sign in with a discoverable passkey', async () => {
+  const client = makeClient();
+  const auth = new SoftAuthenticator();
+
+  const reg = await signUp(client, auth);
+  assert.equal(reg.status, 200);
+  assert.equal(reg.data.user.email, 'ada@example.com');
+  assert.equal(reg.data.passkeys.length, 1);
+  assert.equal(reg.data.passkeys[0].name, 'Google Password Manager');
+  assert.equal(reg.data.passkeys[0].current, true);
+  assert.ok(reg.data.reauthUntil, 'fresh UV registration counts as recent auth');
+
+  const opts = await client.call('POST', '/api/register/options', { name: 'Ada', email: 'ADA@example.com' });
+  assert.equal(opts.status, 409, 'duplicate emails are rejected');
+
+  assert.equal((await client.call('POST', '/api/logout', {})).status, 200);
+  assert.equal((await client.call('GET', '/api/session')).data.user, null);
+
+  const loginOpts = await client.call('POST', '/api/login/options', {});
+  assert.deepEqual(loginOpts.data.allowCredentials, []);
+  const login = await client.call('POST', '/api/login/verify', {
+    credential: auth.get(loginOpts.data, { origin: ORIGIN }),
+  });
+  assert.equal(login.status, 200);
+  assert.equal(login.data.user.name, 'Ada Lovelace');
+});
+
+test('autofill and button sign-in keep independent challenges', async () => {
+  const client = makeClient();
+  const auth = new SoftAuthenticator();
+  await signUp(client, auth);
+  await client.call('POST', '/api/logout', {});
+
+  const button = await client.call('POST', '/api/login/options', {});
+  await client.call('POST', '/api/login/options', { autofill: true }); // issued later
+  const login = await client.call('POST', '/api/login/verify', {
+    credential: auth.get(button.data, { origin: ORIGIN }),
+  });
+  assert.equal(login.status, 200);
+});
+
+test('challenges are single-use and origin-bound', async () => {
+  const client = makeClient();
+  const auth = new SoftAuthenticator();
+  await signUp(client, auth);
+  await client.call('POST', '/api/logout', {});
+
+  const opts = await client.call('POST', '/api/login/options', {});
+  const credential = auth.get(opts.data, { origin: 'https://evil.example' });
+  const bad = await client.call('POST', '/api/login/verify', { credential });
+  assert.equal(bad.status, 400);
+  const replay = await client.call('POST', '/api/login/verify', { credential: auth.get(opts.data, { origin: ORIGIN }) });
+  assert.equal(replay.data.error, 'challenge_expired');
+});
+
+test('unknown credentials are reported for the Signal API', async () => {
+  const client = makeClient();
+  const auth = new SoftAuthenticator();
+  await signUp(client, auth);
+  await client.call('POST', '/api/logout', {});
+
+  const stranger = new SoftAuthenticator();
+  stranger.create({ challenge: 'x', rp: { id: 'localhost' }, user: { id: 'eA' } }, { origin: ORIGIN });
+  const opts = await client.call('POST', '/api/login/options', {});
+  const credential = stranger.get(opts.data, { origin: ORIGIN });
+  const res = await client.call('POST', '/api/login/verify', { credential });
+  assert.equal(res.status, 404);
+  assert.equal(res.data.error, 'unknown_credential');
+  assert.equal(res.data.credentialId, credential.id);
+});
+
+test('passkey management requires reauthentication and protects the last passkey', async () => {
+  const client = makeClient();
+  const phone = new SoftAuthenticator();
+  const laptop = new SoftAuthenticator({ aaguid: '00000000-0000-0000-0000-000000000000', be: false });
+  await signUp(client, phone);
+
+  // Sign in again *without* user verification so the session isn't "fresh".
+  await client.call('POST', '/api/logout', {});
+  phone.uv = false;
+  const lo = await client.call('POST', '/api/login/options', {});
+  const login = await client.call('POST', '/api/login/verify', { credential: phone.get(lo.data, { origin: ORIGIN }) });
+  assert.equal(login.data.reauthUntil, null);
+  const firstId = login.data.passkeys[0].id;
+
+  assert.equal((await client.call('POST', '/api/passkeys/options', {})).data.error, 'reauth_required');
+  assert.equal((await client.call('DELETE', `/api/passkeys/${firstId}`)).data.error, 'reauth_required');
+
+  // Reauth must be user-verifying.
+  assert.equal((await reauth(client, phone)).status, 400);
+  phone.uv = true;
+  const fresh = await reauth(client, phone);
+  assert.equal(fresh.status, 200);
+  assert.ok(fresh.data.reauthUntil > Date.now());
+
+  assert.equal((await client.call('DELETE', `/api/passkeys/${firstId}`)).data.error, 'last_passkey');
+
+  const addOpts = await client.call('POST', '/api/passkeys/options', {});
+  assert.equal(addOpts.status, 200);
+  assert.deepEqual(addOpts.data.excludeCredentials.map((c) => c.id), [firstId]);
+  const added = await client.call('POST', '/api/passkeys/verify', { credential: laptop.create(addOpts.data, { origin: ORIGIN }) });
+  assert.equal(added.status, 200);
+  assert.equal(added.data.passkeys.length, 2);
+  const second = added.data.passkeys.find((p) => p.id === added.data.added);
+  assert.equal(second.name, 'Passkey');
+  assert.equal(second.backedUp, false);
+
+  const renamed = await client.call('PATCH', `/api/passkeys/${second.id}`, { name: '  Work   laptop ' });
+  assert.equal(renamed.data.passkeys.find((p) => p.id === second.id).name, 'Work laptop');
+
+  const removed = await client.call('DELETE', `/api/passkeys/${firstId}`);
+  assert.equal(removed.status, 200);
+  assert.deepEqual(removed.data.passkeys.map((p) => p.id), [second.id]);
+});
+
+test('profile updates: name is free, email change needs reauth', async () => {
+  const client = makeClient();
+  const auth = new SoftAuthenticator();
+  await signUp(client, auth);
