+  const lo = await client.call('POST', '/api/login/options', {});
+  await client.call('POST', '/api/login/verify', { credential: auth.get(lo.data, { origin: ORIGIN }) });
+  auth.uv = true;
+
+  const nameOnly = await client.call('PATCH', '/api/profile', { name: 'Ada King', email: 'ada@example.com' });
+  assert.equal(nameOnly.status, 200);
+  assert.equal(nameOnly.data.user.name, 'Ada King');
+
+  const emailChange = await client.call('PATCH', '/api/profile', { email: 'countess@example.com' });
+  assert.equal(emailChange.data.error, 'reauth_required');
+
+  await reauth(client, auth);
+  const invalid = await client.call('PATCH', '/api/profile', { email: 'not-an-email' });
+  assert.equal(invalid.status, 400);
+  const changed = await client.call('PATCH', '/api/profile', { email: 'Countess@Example.com' });
+  assert.equal(changed.status, 200);
+  assert.equal(changed.data.user.email, 'countess@example.com');
+});
+
+test('account deletion requires reauth and removes data', async () => {
+  const client = makeClient();
