index 0000000..fedf03b
--- /dev/null
+++ b/test/helpers/authenticator.js
@@ -0,0 +1,122 @@
+// A software WebAuthn authenticator for tests.
+
+import crypto from 'node:crypto';
+
+export function encodeCBOR(value) {
+  const head = (major, n) => {
+    if (n < 24) return Buffer.from([(major << 5) | n]);
+    if (n < 256) return Buffer.from([(major << 5) | 24, n]);
+    if (n < 65536) { const b = Buffer.alloc(3); b[0] = (major << 5) | 25; b.writeUInt16BE(n, 1); return b; }
+    const b = Buffer.alloc(5); b[0] = (major << 5) | 26; b.writeUInt32BE(n, 1); return b;
+  };
+  if (typeof value === 'number') return value >= 0 ? head(0, value) : head(1, -1 - value);
+  if (Buffer.isBuffer(value)) return Buffer.concat([head(2, value.length), value]);
+  if (typeof value === 'string') { const b = Buffer.from(value); return Buffer.concat([head(3, b.length), b]); }
+  if (Array.isArray(value)) return Buffer.concat([head(4, value.length), ...value.map(encodeCBOR)]);
+  if (value instanceof Map) {
+    const parts = [head(5, value.size)];
+    for (const [k, v] of value) parts.push(encodeCBOR(k), encodeCBOR(v));
+    return Buffer.concat(parts);
+  }
+  throw new Error('unsupported');
+}
+
+const b64u = (b) => Buffer.from(b).toString('base64url');
+
+export class SoftAuthenticator {
+  constructor({ alg = -7, aaguid = 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4', uv = true, be = true } = {}) {
+    this.alg = alg;
+    this.aaguid = Buffer.from(aaguid.replace(/-/g, ''), 'hex');
+    this.uv = uv;
+    this.be = be;
+    this.credentials = new Map(); // id -> { privateKey, cose, rpId, userHandle, counter }
+  }
+
+  #keypair() {
+    if (this.alg === -7) {
+      const { publicKey, privateKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
+      const jwk = publicKey.export({ format: 'jwk' });
+      const cose = new Map([[1, 2], [3, -7], [-1, 1],
+        [-2, Buffer.from(jwk.x, 'base64url')], [-3, Buffer.from(jwk.y, 'base64url')]]);
+      return { privateKey, cose: encodeCBOR(cose), sign: (d) => crypto.sign('sha256', d, privateKey) };
+    }
+    if (this.alg === -8) {
+      const { publicKey, privateKey } = crypto.generateKeyPairSync('ed25519');
+      const jwk = publicKey.export({ format: 'jwk' });
+      const cose = new Map([[1, 1], [3, -8], [-1, 6], [-2, Buffer.from(jwk.x, 'base64url')]]);
+      return { privateKey, cose: encodeCBOR(cose), sign: (d) => crypto.sign(null, d, privateKey) };
+    }
+    if (this.alg === -257) {
+      const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
+      const jwk = publicKey.export({ format: 'jwk' });
+      const cose = new Map([[1, 3], [3, -257],
+        [-1, Buffer.from(jwk.n, 'base64url')], [-2, Buffer.from(jwk.e, 'base64url')]]);
+      return { privateKey, cose: encodeCBOR(cose), sign: (d) => crypto.sign('sha256', d, privateKey) };
+    }
+    throw new Error('alg');
+  }
+
+  #flags({ at = false } = {}) {
+    let f = 0x01; // UP
+    if (this.uv) f |= 0x04;
+    if (this.be) f |= 0x08 | 0x10;
+    if (at) f |= 0x40;
+    return f;
+  }
+
+  create(options, { origin, rpIdOverride } = {}) {
+    const rpId = rpIdOverride || options.rp.id;
+    const credId = crypto.randomBytes(16);
+    const kp = this.#keypair();
+    this.credentials.set(b64u(credId), { ...kp, rpId, userHandle: options.user.id, counter: 0 });
+
+    const clientDataJSON = Buffer.from(JSON.stringify({
+      type: 'webauthn.create', challenge: options.challenge, origin, crossOrigin: false,
+    }));
+    const idLen = Buffer.alloc(2); idLen.writeUInt16BE(credId.length);
+    const authData = Buffer.concat([
+      crypto.createHash('sha256').update(rpId).digest(),
+      Buffer.from([this.#flags({ at: true })]),
+      Buffer.alloc(4),
+      this.aaguid, idLen, credId, kp.cose,
+    ]);
+    const attestationObject = encodeCBOR(new Map([
+      ['fmt', 'none'], ['attStmt', new Map()], ['authData', authData],
+    ]));
+    return {
+      id: b64u(credId), rawId: b64u(credId), type: 'public-key',
+      authenticatorAttachment: 'platform', clientExtensionResults: {},
+      response: {
+        clientDataJSON: b64u(clientDataJSON),
+        attestationObject: b64u(attestationObject),
+        transports: ['internal', 'hybrid'],
+      },
+    };
+  }
+
+  get(options, { origin, credentialId, counterStep = 1, tamper = false } = {}) {
+    const id = credentialId || [...this.credentials.keys()].find((k) =>
+      !options.allowCredentials?.length || options.allowCredentials.some((c) => c.id === k));
+    const cred = this.credentials.get(id);
+    cred.counter += counterStep;
+    const clientDataJSON = Buffer.from(JSON.stringify({
+      type: 'webauthn.get', challenge: options.challenge, origin, crossOrigin: false,
+    }));
+    const counter = Buffer.alloc(4); counter.writeUInt32BE(cred.counter);
+    const authData = Buffer.concat([
+      crypto.createHash('sha256').update(options.rpId || cred.rpId).digest(),
+      Buffer.from([this.#flags()]), counter,
+    ]);
+    const signed = Buffer.concat([authData, crypto.createHash('sha256').update(clientDataJSON).digest()]);
+    const signature = cred.sign(tamper ? Buffer.concat([signed, Buffer.from([0])]) : signed);
+    return {
+      id, rawId: id, type: 'public-key', authenticatorAttachment: 'platform', clientExtensionResults: {},
+      response: {
+        clientDataJSON: b64u(clientDataJSON),
+        authenticatorData: b64u(authData),
+        signature: b64u(signature),
+        userHandle: cred.userHandle,
+      },
+    };
+  }
+}
