+++ b/test/webauthn.test.js
@@ -0,0 +1,85 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+
+import { verifyRegistration, verifyAuthentication, randomChallenge, decodeCBOR } from '../server/webauthn.js';
+import { SoftAuthenticator, encodeCBOR } from './helpers/authenticator.js';
+
+const ORIGIN = 'https://dailygrind.example';
+const RP_ID = 'dailygrind.example';
+
+function register(auth) {
+  const challenge = randomChallenge();
+  const options = { challenge, rp: { id: RP_ID }, user: { id: 'dXNlcg' } };
+  const credential = auth.create(options, { origin: ORIGIN });
+  const verified = verifyRegistration(credential, { expectedChallenge: challenge, expectedOrigins: [ORIGIN], rpId: RP_ID });
+  return {
+    credential,
+    stored: { id: verified.credentialId, publicKey: verified.publicKey, signCount: verified.signCount, backupEligible: verified.backupEligible },
+    verified,
+  };
+}
+
+function authenticate(auth, stored, opts = {}) {
+  const challenge = randomChallenge();
+  const assertion = auth.get({ challenge, rpId: RP_ID }, { origin: ORIGIN, ...opts });
+  return verifyAuthentication(assertion, stored, {
+    expectedChallenge: challenge, expectedOrigins: [ORIGIN], rpId: RP_ID, ...opts.verify,
+  });
+}
+
+test('CBOR round-trip of nested structures', () => {
+  const value = new Map([[1, 2], [-3, Buffer.from('abc')], ['k', [1, 'two', new Map()]]]);
+  assert.deepEqual(decodeCBOR(encodeCBOR(value)).value, value);
+});
+
+for (const [label, alg] of [['ES256', -7], ['EdDSA', -8], ['RS256', -257]]) {
+  test(`registers and authenticates with ${label}`, () => {
+    const auth = new SoftAuthenticator({ alg });
+    const { stored, verified } = register(auth);
+    assert.equal(verified.alg, alg);
+    assert.equal(verified.aaguid, 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+    assert.equal(verified.backedUp, true);
+    assert.deepEqual(verified.transports, ['internal', 'hybrid']);
+    const result = authenticate(auth, stored);
+    assert.equal(result.signCount, 1);
+    assert.equal(result.userVerified, true);
+  });
+}
+
+test('rejects registration with wrong challenge, origin or RP ID', () => {
+  const auth = new SoftAuthenticator();
+  const challenge = randomChallenge();
+  const options = { challenge, rp: { id: RP_ID }, user: { id: 'dXNlcg' } };
+  const ok = { expectedChallenge: challenge, expectedOrigins: [ORIGIN], rpId: RP_ID };
+
+  const cred = auth.create(options, { origin: ORIGIN });
+  assert.throws(() => verifyRegistration(cred, { ...ok, expectedChallenge: randomChallenge() }), /Challenge/);
+  assert.throws(() => verifyRegistration(auth.create(options, { origin: 'https://evil.example' }), ok), /Origin/);
+  assert.throws(() => verifyRegistration(auth.create(options, { origin: ORIGIN, rpIdOverride: 'evil.example' }), ok), /RP ID/);
+});
+
+test('rejects tampered signatures', () => {
+  const auth = new SoftAuthenticator();
+  const { stored } = register(auth);
+  assert.throws(() => authenticate(auth, stored, { tamper: true }), /signature/i);
+});
+
+test('rejects signature counter regressions', () => {
+  const auth = new SoftAuthenticator();
+  const { stored } = register(auth);
+  stored.signCount = 10;
+  assert.throws(() => authenticate(auth, stored), /counter/i);
+});
+
+test('enforces user verification when required', () => {
+  const auth = new SoftAuthenticator({ uv: false });
+  const { stored } = register(auth);
+  assert.throws(() => authenticate(auth, stored, { verify: { requireUserVerification: true } }), /verification/);
+  assert.doesNotThrow(() => authenticate(auth, stored));
+});
+
+test('rejects mismatched user handle', () => {
+  const auth = new SoftAuthenticator();
+  const { stored } = register(auth);
+  assert.throws(() => authenticate(auth, stored, { verify: { expectedUserHandle: 'b3RoZXI' } }), /handle/);
+});

