+import React, { useEffect, useId, useRef, useState } from 'react';
+import {
+  ApiError,
+  api,
+  getPasskeyCapabilities,
+  goTo,
+  isReauthRequired,
+  registerPasskey,
+  signalAcceptedCredentials,
+  signalUserDetails,
+  type AccountPayload,
+  type PublicCredential,
+} from '../lib/passkeys-client';
+import { useReauth } from './ReauthDialog';
+import { PasskeyIcon } from './SignInForm';
+
+interface Props {
+  initialAccount: AccountPayload;
+}
+
+type Notice = { kind: 'success' | 'error'; text: string } | null;
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const dateTimeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+
+export default function AccountSettings({ initialAccount }: Props) {
+  const [account, setAccount] = useState(initialAccount);
+  const [notice, setNotice] = useState<Notice>(null);
+  const [canCreate, setCanCreate] = useState<boolean | null>(null);
+  const [creating, setCreating] = useState(false);
+  const { requestReauth, dialog: reauthDialog } = useReauth(account.credentials.length > 0);
+
+  // On load: refresh the list and sync accepted credentials with the passkey provider.
+  useEffect(() => {
+    getPasskeyCapabilities().then((caps) => setCanCreate(caps.webauthn));
+    api<AccountPayload>('api/account/passkeys', { method: 'GET' })
+      .then((fresh) => {
+        setAccount(fresh);
+        void signalAcceptedCredentials(fresh);
+      })
+      .catch((err) => {
+        if (err instanceof ApiError && err.status === 401) void goTo('signin');
+      });
+  }, []);
+
+  /** Runs a sensitive action, asking the user to reauthenticate if the server requires it. */
+  async function withReauth<T>(action: () => Promise<T>): Promise<T | undefined> {
+    try {
+      return await action();
+    } catch (err) {
+      if (!isReauthRequired(err)) throw err;
+      if (!(await requestReauth())) return undefined;
+      return await action();
+    }
+  }
+
+  const handleCreate = async () => {
+    setNotice(null);
+    setCreating(true);
+    try {
+      const result = await withReauth(() => registerPasskey('management'));
+      if (!result) return;
+      if (result.status === 'created') {
+        setAccount(result.account);
+        setNotice({ kind: 'success', text: 'Passkey created. You can now use it to sign in.' });
+      } else if (result.status === 'exists') {
+        setNotice({ kind: 'error', text: 'A passkey for this account already exists in that passkey provider.' });
+      } else if (result.status === 'error') {
+        setNotice({ kind: 'error', text: result.message });
+      }
+    } catch (err) {
+      setNotice({ kind: 'error', text: err instanceof ApiError ? err.message : 'Couldn’t create a passkey.' });
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const handleRename = async (credential: PublicCredential, name: string) => {
+    setNotice(null);
+    try {
+      // Nickname changes are a server-side label only; no Signal API call needed.
+      const updated = await api<AccountPayload>(`api/account/passkeys/${encodeURIComponent(credential.id)}`, {
+        method: 'PATCH',
+        body: { name },
+      });
+      setAccount(updated);
+      setNotice({ kind: 'success', text: `Passkey renamed to “${name}”.` });
+      return true;
+    } catch (err) {
+      setNotice({ kind: 'error', text: err instanceof ApiError ? err.message : 'Couldn’t rename the passkey.' });
+      return false;
+    }
+  };
+
+  const handleDelete = async (credential: PublicCredential) => {
+    setNotice(null);
+    try {
+      const updated = await withReauth(() =>
+        api<AccountPayload>(`api/account/passkeys/${encodeURIComponent(credential.id)}`, { method: 'DELETE' }),
+      );
+      if (!updated) return;
+      setAccount(updated);
+      setNotice({ kind: 'success', text: `“${credential.name}” was deleted.` });
+      // Let the passkey provider hide the deleted passkey.
+      void signalAcceptedCredentials(updated);
+    } catch (err) {
+      setNotice({ kind: 'error', text: err instanceof ApiError ? err.message : 'Couldn’t delete the passkey.' });
+    }
+  };
+
+  const handleDisplayName = async (displayName: string) => {
+    setNotice(null);
+    try {
+      const updated = await api<AccountPayload>('api/account/user', { method: 'PUT', body: { displayName } });
+      setAccount(updated);
+      setNotice({ kind: 'success', text: 'Display name updated.' });
+      // Keep the name shown in passkey pickers in sync.
+      void signalUserDetails(updated);
+      return true;
+    } catch (err) {
+      setNotice({ kind: 'error', text: err instanceof ApiError ? err.message : 'Couldn’t update your display name.' });
+      return false;
+    }
+  };
+
+  const handleSignOut = async () => {
+    try {
+      await api('api/auth/logout');
+    } finally {
+      await goTo('');
+    }
+  };
+
+  return (
+    <div className="mx-auto max-w-3xl px-4 py-10">
+      {reauthDialog}
+
+      <div className="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-gray-300 pb-4">
+        <div>
+          <h1 className="font-brand text-4xl text-gray-900">Account settings</h1>
+          <p className="mt-1 text-sm text-gray-600">
+            Signed in as <strong>{account.username}</strong>
+          </p>
+        </div>
+        <button
+          type="button"
+          onClick={handleSignOut}
+          className="rounded-md border border-gray-300 px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
+        >
+          Sign out
+        </button>
+      </div>
+
+      <div aria-live="polite">
+        {notice && (
+          <div
+            className={`mb-6 rounded-lg p-3 text-sm ${
+              notice.kind === 'success' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
+            }`}
+          >
+            {notice.text}
+          </div>
+        )}
+      </div>
+
+      <ProfileSection account={account} onSave={handleDisplayName} />
+
+      <section aria-labelledby="passkeys-heading" className="mt-10">
+        <div className="flex flex-wrap items-start justify-between gap-4">
+          <div className="max-w-prose">
+            <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900">
+              Passkeys
+            </h2>
+            <p className="mt-1 text-sm text-gray-600">
+              Passkeys let you sign in with your fingerprint, face, screen lock, or security key instead of a password.
+              They’re stored in your password manager and can’t be phished.
+            </p>
+          </div>
+          {canCreate !== false && (
+            <button
