+              className="flex items-center gap-2 rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-75"
+            >
+              <PasskeyIcon />
+              {creating ? 'Creating…' : 'Create a passkey'}
+            </button>
+          )}
+        </div>
+
+        {canCreate === false && (
+          <p className="mt-4 rounded-md bg-gray-100 p-3 text-sm text-gray-700">
+            This browser doesn’t support passkeys. Keep your account safe with a strong, unique password.
+          </p>
+        )}
+
+        {account.credentials.length === 0 ? (
+          <p className="mt-6 rounded-lg border border-dashed border-gray-300 p-6 text-center text-sm text-gray-600">
+            No passkeys found. Create one to sign in faster next time.
+          </p>
+        ) : (
+          <ul className="mt-6 divide-y divide-gray-200 rounded-lg border border-gray-200">
+            {account.credentials.map((credential) => (
+              <PasskeyRow
+                key={credential.id}
+                credential={credential}
+                onRename={(name) => handleRename(credential, name)}
+                onDelete={() => handleDelete(credential)}
+              />
+            ))}
+          </ul>
+        )}
+      </section>
+    </div>
+  );
+}
+
+function ProfileSection({ account, onSave }: { account: AccountPayload; onSave: (name: string) => Promise<boolean> }) {
+  const [displayName, setDisplayName] = useState(account.displayName);
+  const [saving, setSaving] = useState(false);
+  const inputId = useId();
+  const hintId = useId();
+
+  useEffect(() => setDisplayName(account.displayName), [account.displayName]);
+
+  const submit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setSaving(true);
+    await onSave(displayName.trim());
+    setSaving(false);
+  };
+
+  return (
+    <section aria-labelledby="profile-heading">
+      <h2 id="profile-heading" className="text-xl font-bold text-gray-900">
+        Profile
+      </h2>
+      <dl className="mt-4 text-sm">
+        <dt className="font-medium text-gray-700">Username</dt>
+        <dd className="mt-1 text-gray-900">{account.username}</dd>
+      </dl>
+      <form onSubmit={submit} className="mt-4 flex flex-wrap items-end gap-3">
+        <div className="min-w-0 flex-1">
+          <label htmlFor={inputId} className="mb-1 block text-sm font-medium text-gray-700">
+            Display name
+          </label>
+          <input
+            id={inputId}
+            type="text"
+            autoComplete="name"
+            required
+            maxLength={64}
+            value={displayName}
+            onChange={(e) => setDisplayName(e.target.value)}
+            aria-describedby={hintId}
+            className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
+          />
+          <p id={hintId} className="mt-1 text-xs text-gray-500">
+            Shown in your passkey manager next to your username.
+          </p>
+        </div>
+        <button
+          type="submit"
+          disabled={saving || displayName.trim() === account.displayName || !displayName.trim()}
+          className="mb-5 rounded-md border border-gray-900 px-4 py-2 text-sm font-medium text-gray-900 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
+        >
+          {saving ? 'Saving…' : 'Save'}
+        </button>
+      </form>
+    </section>
+  );
+}
+
+function PasskeyRow({
+  credential,
+  onRename,
+  onDelete,
+}: {
+  credential: PublicCredential;
+  onRename: (name: string) => Promise<boolean>;
+  onDelete: () => Promise<void>;
+}) {
+  const [editing, setEditing] = useState(false);
+  const [name, setName] = useState(credential.name);
+  const [busy, setBusy] = useState(false);
+  const confirmRef = useRef<HTMLDialogElement>(null);
+  const inputId = useId();
+  const confirmTitleId = useId();
+  const confirmDescId = useId();
+
+  const saveName = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setBusy(true);
+    if (await onRename(name.trim())) setEditing(false);
+    setBusy(false);
+  };
+
+  const onConfirmClose = async () => {
+    const dialog = confirmRef.current;
+    if (!dialog) return;
+    const choice = dialog.returnValue;
+    dialog.returnValue = '';
+    if (choice !== 'delete') return;
+    setBusy(true);
+    await onDelete();
+    setBusy(false);
+  };
+
+  return (
+    <li className="flex flex-wrap items-center gap-4 p-4">
+      {credential.providerIconLight ? (
+        <picture>
+          {credential.providerIconDark && (
+            <source srcSet={credential.providerIconDark} media="(prefers-color-scheme: dark)" />
+          )}
+          <img src={credential.providerIconLight} alt="" width={32} height={32} className="h-8 w-8 shrink-0" />
+        </picture>
+      ) : (
+        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-gray-100 text-gray-700">
+          <PasskeyIcon className="h-5 w-5" />
+        </span>
+      )}
+
+      <div className="min-w-0 flex-1">
+        {editing ? (
+          <form onSubmit={saveName} className="flex flex-wrap items-center gap-2">
+            <label htmlFor={inputId} className="sr-only">
+              Passkey name
+            </label>
+            <input
+              id={inputId}
+              type="text"
+              autoFocus
+              required
+              maxLength={64}
+              value={name}
+              onChange={(e) => setName(e.target.value)}
+              className="min-w-0 flex-1 rounded-md border border-gray-300 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+            <button type="submit" disabled={busy} className="rounded-md bg-gray-900 px-3 py-1 text-sm text-white hover:bg-gray-800 disabled:opacity-75">
+              Save
+            </button>
+            <button
+              type="button"
+              onClick={() => {
+                setName(credential.name);
+                setEditing(false);
+              }}
+              className="rounded-md px-3 py-1 text-sm text-gray-700 hover:bg-gray-100"
+            >
+              Cancel
+            </button>
+          </form>
+        ) : (
+          <p className="truncate font-medium text-gray-900">
+            {credential.name}
+            {credential.name !== credential.providerName && (
+              <span className="ml-2 text-sm font-normal text-gray-500">{credential.providerName}</span>
+            )}
+          </p>
+        )}
+        <p className="mt-1 text-xs text-gray-600">
+          Created <time dateTime={new Date(credential.registeredAt).toISOString()}>{dateFormat.format(credential.registeredAt)}</time>
+          {' · '}
+          {credential.lastUsedAt ? (
+            <>
+              Last used{' '}
+              <time dateTime={new Date(credential.lastUsedAt).toISOString()}>{dateTimeFormat.format(credential.lastUsedAt)}</time>
+            </>
+          ) : (
+            'Never used'
+          )}
+          {' · '}
+          {credential.credentialBackedUp ? 'Synced' : 'This device only'}
+        </p>
+      </div>
+
+      {!editing && (
+        <div className="flex gap-2">
+          <button
+            type="button"
+            onClick={() => setEditing(true)}
+            disabled={busy}
+            aria-label={`Rename ${credential.name}`}
+            className="rounded-md border border-gray-300 px-3 py-1.5 text-sm text-gray-700 hover:bg-gray-50"
+          >
+            Rename
+          </button>
+          <button
+            type="button"
+            onClick={() => confirmRef.current?.showModal()}
+            disabled={busy}
+            aria-label={`Delete ${credential.name}`}
+            className="rounded-md border border-red-300 px-3 py-1.5 text-sm text-red-700 hover:bg-red-50"
+          >
+            {busy ? 'Deleting…' : 'Delete'}
+          </button>
+        </div>
+      )}
+
+      <dialog
+        ref={confirmRef}
+        aria-labelledby={confirmTitleId}
+        aria-describedby={confirmDescId}
+        onClose={onConfirmClose}
+        {...({ closedby: 'any' } as Record<string, string>)}
+        className="m-auto w-full max-w-sm rounded-lg border border-gray-200 p-6 shadow-xl backdrop:bg-gray-900/50"
+      >
+        <h1 id={confirmTitleId} className="text-xl font-bold text-gray-900">
+          Delete this passkey?
+        </h1>
+        <p id={confirmDescId} className="mt-2 text-sm text-gray-600">
+          You won’t be able to sign in with “{credential.name}” anymore. You can still sign in with your password or
+          other passkeys.
+        </p>
+        <form method="dialog" className="mt-6 flex justify-end gap-3">
+          <button value="cancel" autoFocus className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50">
+            Cancel
+          </button>
+          <button value="delete" className="rounded-md bg-red-700 px-4 py-2 text-sm font-medium text-white hover:bg-red-800">
+            Delete
+          </button>
+        </form>
+      </dialog>
+    </li>
+  );
+}
