diff --git a/src/components/ReauthDialog.tsx b/src/components/ReauthDialog.tsx
new file mode 100644
index 0000000..f69fd4e
--- /dev/null
+++ b/src/components/ReauthDialog.tsx
@@ -0,0 +1,185 @@
+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { ApiError, api, reauthenticateWithPasskey } from '../lib/passkeys-client';
+
+type Resolver = (verified: boolean) => void;
+
+/**
+ * Reauthentication ("confirm it's you") dialog for sensitive account actions.
+ * Prefers the user's own passkeys and falls back to their password.
+ *
+ * Usage:
+ *   const { requestReauth, dialog } = useReauth();
+ *   if (await requestReauth()) retry();
+ *   return <>{dialog}...</>;
+ */
+export function useReauth(hasPasskeys: boolean) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const resolverRef = useRef<Resolver | null>(null);
+  const abortRef = useRef<AbortController | null>(null);
+  const [mode, setMode] = useState<'passkey' | 'password'>(hasPasskeys ? 'passkey' : 'password');
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [busy, setBusy] = useState(false);
+  const titleId = useId();
+  const descId = useId();
+  const passwordId = useId();
+
+  const finish = useCallback((verified: boolean) => {
+    abortRef.current?.abort();
+    resolverRef.current?.(verified);
+    resolverRef.current = null;
+    dialogRef.current?.close();
+  }, []);
+
+  const requestReauth = useCallback((): Promise<boolean> => {
+    resolverRef.current?.(false);
+    setMode(hasPasskeys ? 'passkey' : 'password');
+    setPassword('');
+    setError(null);
+    setBusy(false);
+    dialogRef.current?.showModal();
+    return new Promise<boolean>((resolve) => {
+      resolverRef.current = resolve;
+    });
+  }, [hasPasskeys]);
+
+  // Esc / close requests resolve as "not verified".
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const onClose = () => {
+      abortRef.current?.abort();
+      resolverRef.current?.(false);
+      resolverRef.current = null;
+    };
+    dialog.addEventListener('close', onClose);
+    return () => dialog.removeEventListener('close', onClose);
+  }, []);
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy(true);
+    abortRef.current?.abort();
+    abortRef.current = new AbortController();
+    try {
+      const result = await reauthenticateWithPasskey(abortRef.current.signal);
+      if (result.status === 'success') return finish(true);
+      if (result.status === 'no-passkeys') {
+        setMode('password');
+      } else if (result.status === 'error') {
+        setError(result.message);
+      }
+    } catch (err) {
+      setError(err instanceof ApiError ? err.message : 'Something went wrong. Please try again.');
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const verifyWithPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy(true);
+    try {
+      await api('api/auth/reauth/password', { body: { password } });
+      finish(true);
+    } catch (err) {
+      setError(err instanceof ApiError ? err.message : 'Something went wrong. Please try again.');
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const dialog = (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      aria-describedby={descId}
+      {...({ closedby: 'any' } as Record<string, string>)}
+      className="reauth-dialog w-full max-w-sm rounded-lg border border-gray-200 p-6 shadow-xl backdrop:bg-gray-900/50 m-auto"
+    >
+      <h1 id={titleId} className="text-xl font-bold text-gray-900">
+        Confirm it’s you
+      </h1>
+      <p id={descId} className="mt-2 text-sm text-gray-600">
+        For your security, please verify your identity before making this change.
+      </p>
+
+      {error && (
+        <div className="mt-4 rounded-md bg-red-100 p-3 text-sm text-red-700" role="alert">
+          {error}
+        </div>
+      )}
+
+      {mode === 'passkey' ? (
+        <div className="mt-6 space-y-3">
+          <button
+            type="button"
+            autoFocus
+            onClick={verifyWithPasskey}
+            disabled={busy}
+            className="w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-75"
+          >
+            {busy ? 'Waiting for passkey…' : 'Verify with passkey'}
+          </button>
+          <button
+            type="button"
+            onClick={() => {
+              abortRef.current?.abort();
+              setError(null);
+              setMode('password');
+            }}
+            className="w-full text-sm font-medium text-gray-700 underline hover:text-gray-900"
+          >
+            Use your password instead
+          </button>
+        </div>
+      ) : (
+        <form onSubmit={verifyWithPassword} className="mt-6 space-y-4">
+          <div>
+            <label htmlFor={passwordId} className="mb-1 block text-sm font-medium text-gray-700">
+              Password
+            </label>
+            <input
+              id={passwordId}
+              type="password"
+              autoComplete="current-password"
+              autoFocus
+              required
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+          </div>
+          <button
+            type="submit"
+            disabled={busy}
+            className="w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-75"
+          >
+            {busy ? 'Verifying…' : 'Confirm'}
+          </button>
+          {hasPasskeys && (
+            <button
+              type="button"
+              onClick={() => {
+                setError(null);
+                setMode('passkey');
+              }}
+              className="w-full text-sm font-medium text-gray-700 underline hover:text-gray-900"
+            >
+              Use a passkey instead
+            </button>
+          )}
+        </form>
+      )}
+
+      <form method="dialog" className="mt-4">
+        <button type="submit" className="w-full rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50">
+          Cancel
+        </button>
+      </form>
+    </dialog>
+  );
+
+  return { requestReauth, dialog };
+}
