index 0000000..a97fec1
--- /dev/null
+++ b/src/lib/auth/aaguid.ts
@@ -0,0 +1,61 @@
+/**
+ * Maps authenticator AAGUIDs to passkey provider names and icons.
+ * Used strictly as a UX hint in the passkey management list — never for
+ * security decisions (platform passkeys do not attest their AAGUID).
+ */
+
+const REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
+
+interface RegistryEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+let registry: Record<string, RegistryEntry> | null = null;
+let fetchedAt = 0;
+let inflight: Promise<Record<string, RegistryEntry> | null> | null = null;
+
+async function loadRegistry(): Promise<Record<string, RegistryEntry> | null> {
+  if (registry && Date.now() - fetchedAt < CACHE_TTL_MS) return registry;
+  inflight ??= (async () => {
+    try {
+      const res = await fetch(REGISTRY_URL, { signal: AbortSignal.timeout(5000) });
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      registry = (await res.json()) as Record<string, RegistryEntry>;
+      fetchedAt = Date.now();
+    } catch (err) {
+      console.warn('AAGUID registry unavailable:', err);
+    } finally {
+      inflight = null;
+    }
+    return registry;
+  })();
+  return inflight;
+}
+
+function deviceNameFromUserAgent(userAgent: string | null): string {
+  if (!userAgent) return 'Unknown passkey provider';
+  if (/iPhone|iPad/.test(userAgent)) return 'Passkey on iOS';
+  if (/Android/.test(userAgent)) return 'Passkey on Android';
+  if (/Mac OS X/.test(userAgent)) return 'Passkey on macOS';
+  if (/Windows/.test(userAgent)) return 'Passkey on Windows';
+  if (/CrOS/.test(userAgent)) return 'Passkey on ChromeOS';
+  if (/Linux/.test(userAgent)) return 'Passkey on Linux';
+  return 'Unknown passkey provider';
+}
+
+export async function lookupProvider(
+  aaguid: string,
+  userAgent: string | null,
+): Promise<{ name: string; iconLight?: string; iconDark?: string }> {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: deviceNameFromUserAgent(userAgent) };
+  }
+  const entry = (await loadRegistry())?.[aaguid];
+  if (!entry) return { name: 'Unknown passkey provider' };
+  return { name: entry.name, iconLight: entry.icon_light, iconDark: entry.icon_dark };
+}
