--- /dev/null
+++ b/src/lib/auth/assertion.ts
@@ -0,0 +1,47 @@
+import { verifyAuthenticationResponse, type AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { getExpectedOrigins, getRpId } from './config';
+import { saveCredential, type StoredPasskeyCredential } from './store';
+import type { PendingChallenge } from './session';
+
+/**
+ * Verifies a WebAuthn assertion against a stored credential and updates its
+ * counter, backup state and last-used timestamp on success.
+ */
+export async function verifyAssertion(
+  response: AuthenticationResponseJSON,
+  stored: StoredPasskeyCredential,
+  pending: PendingChallenge,
+  url: URL,
+): Promise<boolean> {
+  // The user handle, when returned, must match the credential's owner.
+  if (response.response.userHandle && response.response.userHandle !== stored.passkeyUserId) {
+    return false;
+  }
+  try {
+    const { verified, authenticationInfo } = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      requireUserVerification: pending.userVerification === 'required',
+      credential: {
+        id: stored.id,
+        publicKey: new Uint8Array(Buffer.from(stored.credentialPublicKey, 'base64url')),
+        counter: stored.counter,
+        transports: stored.transports,
+      },
+    });
+    if (!verified) return false;
+    await saveCredential({
+      ...stored,
+      counter: authenticationInfo.newCounter,
+      credentialBackedUp: authenticationInfo.credentialBackedUp,
+      credentialDeviceType: authenticationInfo.credentialDeviceType,
+      lastUsedAt: Date.now(),
+    });
+    return true;
+  } catch (err) {
+    console.warn('Passkey assertion verification failed:', err);
+    return false;
+  }
+}
