@@ -0,0 +1,42 @@
+/**
+ * Relying Party configuration for WebAuthn / passkeys.
+ *
+ * In production, set PASSKEY_RP_ID (e.g. "astro-news-pytrpecapa-uc.a.run.app")
+ * and PASSKEY_ORIGINS (comma-separated list of allowed origins). When unset
+ * (local development), the RP ID and origin fall back to the host the request
+ * was served from, as resolved by Astro on the server.
+ *
+ * The client never derives the RP ID itself: it always reads it from the
+ * options/responses returned by these endpoints.
+ */
+export const RP_NAME = 'The DevTools Times';
+
+/** Upstream password authentication service. */
+export const AUTH_API_BASE =
+  'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+/** How long a sign-in / reauthentication counts as "recent" for sensitive actions. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+/** How long a WebAuthn challenge remains valid. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+/** COSE algorithms accepted for new passkeys: EdDSA, ES256, RS256. */
+export const SUPPORTED_ALGORITHMS = [-8, -7, -257];
+
+function env(name: string): string | undefined {
+  const value = process.env[name] ?? (import.meta.env as Record<string, string | undefined>)[name];
+  return value && value.trim() ? value.trim() : undefined;
+}
+
+export function getRpId(url: URL): string {
+  return env('PASSKEY_RP_ID') ?? url.hostname;
+}
+
+export function getExpectedOrigins(url: URL): string[] {
+  const configured = env('PASSKEY_ORIGINS');
+  if (configured) {
+    return configured.split(',').map((o) => o.trim()).filter(Boolean);
+  }
+  return [url.origin];
+}
