+import type { StoredPasskeyCredential, StoredUser } from './store';
+
+/** Public, client-safe view of a stored passkey (no key material or counters). */
+export function toPublicCredential(c: StoredPasskeyCredential) {
+  return {
+    id: c.id,
+    name: c.name,
+    providerName: c.providerName,
+    providerIconLight: c.providerIconLight,
+    providerIconDark: c.providerIconDark,
+    credentialDeviceType: c.credentialDeviceType,
+    credentialBackedUp: c.credentialBackedUp,
+    registeredAt: c.registeredAt,
+    lastUsedAt: c.lastUsedAt,
+  };
+}
+
+export type PublicCredential = ReturnType<typeof toPublicCredential>;
+
+export function toAccountPayload(user: StoredUser, credentials: StoredPasskeyCredential[], rpId: string) {
+  return {
+    rpId,
+    userId: user.passkeyUserId,
+    username: user.username,
+    displayName: user.displayName,
+    credentials: credentials.map(toPublicCredential),
+  };
+}
+
+export type AccountPayload = ReturnType<typeof toAccountPayload>;
diff --git a/src/lib/auth/session.ts b/src/lib/auth/session.ts
new file mode 100644
index 0000000..3296d79
--- /dev/null
+++ b/src/lib/auth/session.ts
@@ -0,0 +1,104 @@
+import type { AstroSession } from 'astro';
+import { CHALLENGE_TTL_MS, REAUTH_WINDOW_MS } from './config';
+
+export type ChallengePurpose = 'register' | 'login' | 'reauth';
+
+export interface PendingChallenge {
+  challenge: string;
+  expiresAt: number;
+  /** Expected user verification level, persisted server-side (never trusted from the client). */
+  userVerification: UserVerificationRequirement;
+  /** Registration only: credential created through conditional mediation (relaxes UP check). */
+  conditional?: boolean;
+  /** Registration / reauth only: user the ceremony was started for. */
+  username?: string;
+}
+
+export interface SessionUser {
+  username: string;
+  signedInAt: number;
+  reauthenticatedAt?: number;
+}
+
+export function json(data: unknown, status = 200): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function errorResponse(status: number, error: string, code?: string): Response {
+  return json({ error, ...(code && { code }) }, status);
+}
+
+/**
+ * Parses a JSON request body. Requiring `application/json` means cross-site
+ * HTML forms cannot reach these endpoints without a CORS preflight.
+ */
+export async function readJson<T = Record<string, unknown>>(request: Request): Promise<T | Response> {
+  const type = request.headers.get('content-type') ?? '';
+  if (!type.includes('application/json')) {
+    return errorResponse(415, 'Expected a JSON request body.');
+  }
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return errorResponse(400, 'Malformed JSON body.');
+  }
+}
+
+export async function getSessionUser(session: AstroSession | undefined): Promise<SessionUser | undefined> {
+  return (await session?.get('user')) as SessionUser | undefined;
+}
+
+export async function signIn(session: AstroSession | undefined, username: string): Promise<void> {
+  if (!session) throw new Error('Sessions are not configured.');
+  // New session ID on privilege change prevents session fixation.
+  await session.regenerate();
+  session.set('user', { username, signedInAt: Date.now() } satisfies SessionUser);
+}
+
+export async function signOut(session: AstroSession | undefined): Promise<void> {
+  if (!session) return;
+  session.delete('user');
+  session.delete('challenge:register');
+  session.delete('challenge:login');
+  session.delete('challenge:reauth');
+  await session.regenerate();
+}
+
+export async function markReauthenticated(session: AstroSession | undefined): Promise<void> {
+  const user = await getSessionUser(session);
+  if (!session || !user) return;
+  session.set('user', { ...user, reauthenticatedAt: Date.now() } satisfies SessionUser);
+}
+
+/** True if the user signed in or reauthenticated within the reauth window. */
+export function isRecentlyAuthenticated(user: SessionUser): boolean {
+  const last = Math.max(user.signedInAt, user.reauthenticatedAt ?? 0);
+  return Date.now() - last < REAUTH_WINDOW_MS;
+}
+
+export function reauthRequired(): Response {
+  return errorResponse(401, 'Please confirm it’s you to continue.', 'REAUTH_REQUIRED');
+}
+
+export function setChallenge(
+  session: AstroSession,
+  purpose: ChallengePurpose,
+  value: Omit<PendingChallenge, 'expiresAt'>,
+): void {
+  session.set(`challenge:${purpose}`, { ...value, expiresAt: Date.now() + CHALLENGE_TTL_MS });
+}
+
+/** Reads and removes a pending challenge so each challenge can be used only once. */
+export async function consumeChallenge(
+  session: AstroSession,
+  purpose: ChallengePurpose,
+): Promise<PendingChallenge | undefined> {
+  const key = `challenge:${purpose}`;
+  const pending = (await session.get(key)) as PendingChallenge | undefined;
+  session.delete(key);
+  if (!pending || pending.expiresAt < Date.now()) return undefined;
+  return pending;
+}
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..a93767d
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,145 @@
+import { randomBytes } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+
+/**
+ * Minimal file-backed persistence for passkey users and credentials.
+ *
+ * Password accounts live in the upstream auth service; this store links a
+ * username to a stable, random WebAuthn user handle and its passkeys.
+ */
+
+export interface StoredUser {
+  username: string;
+  displayName: string;
+  /** Unpadded Base64URL WebAuthn user handle (never derived from the username). */
+  passkeyUserId: string;
+  createdAt: number;
+}
+
+export interface StoredPasskeyCredential {
+  /** Unpadded Base64URL credential ID. */
+  id: string;
+  /** Owning user's WebAuthn user handle. */
+  passkeyUserId: string;
+  /** Unpadded Base64URL public key. */
+  credentialPublicKey: string;
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  /** Provider name derived from the AAGUID registry (UX hint only). */
+  providerName: string;
+  providerIconLight?: string;
+  providerIconDark?: string;
+  /** Display name: provider name by default, or a user-chosen nickname. */
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+interface Data {
+  users: Record<string, StoredUser>;
+  credentials: Record<string, StoredPasskeyCredential>;
+}
+
+const DATA_DIR = process.env.PASSKEY_DATA_DIR || path.join(process.cwd(), '.data');
+const DATA_FILE = path.join(DATA_DIR, 'passkeys.json');
+
+let cache: Data | null = null;
+let writeChain: Promise<void> = Promise.resolve();
+
+async function load(): Promise<Data> {
+  if (cache) return cache;
+  try {
+    const raw = await readFile(DATA_FILE, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<Data>;
+    cache = { users: parsed.users ?? {}, credentials: parsed.credentials ?? {} };
+  } catch {
+    cache = { users: {}, credentials: {} };
+  }
+  return cache;
+}
+
+function persist(data: Data): Promise<void> {
+  // Serialize writes and replace the file atomically.
+  writeChain = writeChain
+    .catch(() => {})
+    .then(async () => {
+      await mkdir(DATA_DIR, { recursive: true });
+      const tmp = `${DATA_FILE}.${process.pid}.tmp`;
+      await writeFile(tmp, JSON.stringify(data, null, 2), 'utf8');
+      await rename(tmp, DATA_FILE);
+    });
+  return writeChain;
+}
+
+function userKey(username: string): string {
+  return username.trim().toLowerCase();
+}
+
+export async function getUser(username: string): Promise<StoredUser | undefined> {
+  const data = await load();
+  return data.users[userKey(username)];
+}
+
+export async function getUserByPasskeyUserId(passkeyUserId: string): Promise<StoredUser | undefined> {
+  const data = await load();
+  return Object.values(data.users).find((u) => u.passkeyUserId === passkeyUserId);
+}
+
+/** Returns the local record for a username, creating it on first use. */
+export async function ensureUser(username: string): Promise<StoredUser> {
+  const data = await load();
+  const key = userKey(username);
+  let user = data.users[key];
+  if (!user) {
+    user = {
+      username: username.trim(),
+      displayName: username.trim(),
+      passkeyUserId: randomBytes(32).toString('base64url'),
+      createdAt: Date.now(),
+    };
+    data.users[key] = user;
+    await persist(data);
+  }
+  return user;
+}
+
+export async function updateUser(
+  username: string,
+  changes: Partial<Pick<StoredUser, 'displayName'>>,
+): Promise<StoredUser | undefined> {
+  const data = await load();
+  const user = data.users[userKey(username)];
+  if (!user) return undefined;
+  Object.assign(user, changes);
+  await persist(data);
+  return user;
+}
+
+export async function listCredentials(passkeyUserId: string): Promise<StoredPasskeyCredential[]> {
+  const data = await load();
+  return Object.values(data.credentials)
+    .filter((c) => c.passkeyUserId === passkeyUserId)
+    .sort((a, b) => a.registeredAt - b.registeredAt);
+}
+
+export async function getCredential(id: string): Promise<StoredPasskeyCredential | undefined> {
+  const data = await load();
+  return data.credentials[id];
+}
+
+export async function saveCredential(credential: StoredPasskeyCredential): Promise<void> {
+  const data = await load();
+  data.credentials[credential.id] = credential;
+  await persist(data);
+}
+
+export async function deleteCredential(id: string): Promise<void> {
+  const data = await load();
+  delete data.credentials[id];
+  await persist(data);
+}
diff --git a/src/lib/auth/upstream.ts b/src/lib/auth/upstream.ts
