+++ b/src/lib/auth/upstream.ts
@@ -0,0 +1,28 @@
+import { AUTH_API_BASE } from './config';
+
+export interface UpstreamResult {
+  ok: boolean;
+  status: number;
+  error?: string;
+}
+
+/** Calls the upstream password auth service (login or register). */
+export async function callPasswordService(
+  action: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<UpstreamResult> {
+  try {
+    const res = await fetch(`${AUTH_API_BASE}/${action}`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+      signal: AbortSignal.timeout(10_000),
+    });
+    const data = (await res.json().catch(() => ({}))) as { error?: string };
+    return { ok: res.ok, status: res.status, error: data.error };
+  } catch (err) {
+    console.error(`Upstream ${action} failed:`, err);
+    return { ok: false, status: 502, error: 'Authentication service unavailable.' };
+  }
+}
diff --git a/src/lib/passkeys-client.ts b/src/lib/passkeys-client.ts
new file mode 100644
index 0000000..b9ef451
--- /dev/null
+++ b/src/lib/passkeys-client.ts
@@ -0,0 +1,303 @@
+/**
+ * Browser-side passkey helpers. Uses the native WebAuthn APIs directly
+ * (parse*OptionsFromJSON / toJSON / getClientCapabilities / Signal API),
+ * with `webauthn-polyfills` filling gaps in older browsers.
+ *
+ * The RP ID is always taken from server responses — never from location.hostname.
+ */
+import type {
+  AuthenticationResponseJSON,
+  PublicKeyCredentialCreationOptionsJSON,
+  PublicKeyCredentialRequestOptionsJSON,
+  RegistrationResponseJSON,
+} from '@simplewebauthn/server';
+import type { AccountPayload } from './auth/serialize';
+
+export type { AccountPayload };
+export type PublicCredential = AccountPayload['credentials'][number];
+
+const BASE = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
+
+export function appUrl(path: string): string {
+  return `${BASE}${path.replace(/^\//, '')}`;
+}
+
+export class ApiError extends Error {
+  constructor(
+    message: string,
+    public status: number,
+    public code?: string,
+  ) {
+    super(message);
+  }
+}
+
+export async function api<T = unknown>(path: string, init: { method?: string; body?: unknown } = {}): Promise<T> {
+  const res = await fetch(appUrl(path), {
+    method: init.method ?? 'POST',
+    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+    credentials: 'same-origin',
+    body: init.body !== undefined ? JSON.stringify(init.body) : (init.method ?? 'POST') === 'POST' ? '{}' : undefined,
+  });
+  const data = (await res.json().catch(() => ({}))) as { error?: string; code?: string };
+  if (!res.ok) throw new ApiError(data.error || `Request failed (${res.status})`, res.status, data.code);
+  return data as T;
+}
+
+export function isReauthRequired(err: unknown): boolean {
+  return err instanceof ApiError && err.code === 'REAUTH_REQUIRED';
+}
+
+let polyfillPromise: Promise<unknown> | null = null;
+
+/** Loads webauthn-polyfills (parse*FromJSON, toJSON, getClientCapabilities) where WebAuthn exists. */
+export function ensureWebAuthn(): Promise<boolean> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) return Promise.resolve(false);
+  polyfillPromise ??= import('webauthn-polyfills').catch((err) => console.warn('WebAuthn polyfills failed to load:', err));
+  return polyfillPromise.then(() => true);
+}
+
+export interface PasskeyCapabilities {
+  /** WebAuthn is available at all (security keys, roaming authenticators, etc). */
+  webauthn: boolean;
+  /** A platform authenticator that can hold passkeys is available. */
+  platform: boolean;
+  conditionalGet: boolean;
+  conditionalCreate: boolean;
+}
+
+const NO_CAPABILITIES: PasskeyCapabilities = { webauthn: false, platform: false, conditionalGet: false, conditionalCreate: false };
+
+export async function getPasskeyCapabilities(): Promise<PasskeyCapabilities> {
+  if (!(await ensureWebAuthn()) || !PublicKeyCredential.getClientCapabilities) return NO_CAPABILITIES;
+  try {
+    const caps = (await PublicKeyCredential.getClientCapabilities()) as Record<string, boolean | undefined>;
+    return {
+      webauthn: true,
+      // The polyfill can't detect passkeyPlatformAuthenticator; fall back to UVPA.
+      platform: Boolean(caps.passkeyPlatformAuthenticator ?? caps.userVerifyingPlatformAuthenticator),
+      conditionalGet: caps.conditionalGet === true,
+      conditionalCreate: caps.conditionalCreate === true,
+    };
+  } catch {
+    return { ...NO_CAPABILITIES, webauthn: true };
+  }
+}
+
+/** Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no padding, length % 4 !== 1. */
+export function isValidBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+// ---------------------------------------------------------------------------
+// Signal API (progressive enhancement — failures are non-fatal and only warn)
+// ---------------------------------------------------------------------------
+
+type SignalPKC = typeof PublicKeyCredential & {
+  signalUnknownCredential?: (o: { rpId: string; credentialId: string }) => Promise<void>;
+  signalAllAcceptedCredentials?: (o: { rpId: string; userId: string; allAcceptedCredentialIds: string[] }) => Promise<void>;
+  signalCurrentUserDetails?: (o: { rpId: string; userId: string; name: string; displayName: string }) => Promise<void>;
+};
+
+function signalApi(): SignalPKC | undefined {
+  return typeof window !== 'undefined' && window.PublicKeyCredential ? (PublicKeyCredential as SignalPKC) : undefined;
+}
+
+export async function signalUnknownCredential(rpId: string | undefined, credentialId: string): Promise<void> {
+  const pkc = signalApi();
+  if (!pkc?.signalUnknownCredential || !rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await pkc.signalUnknownCredential({ rpId, credentialId });
+  } catch (e) {
+    console.warn('signalUnknownCredential sync warning:', e);
+  }
+}
+
+export async function signalAcceptedCredentials(account: Pick<AccountPayload, 'rpId' | 'userId' | 'credentials'>): Promise<void> {
+  const pkc = signalApi();
+  if (!pkc?.signalAllAcceptedCredentials) return;
+  const ids = account.credentials.map((c) => c.id);
+  if (!account.rpId || !isValidBase64Url(account.userId) || !ids.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: invalid rpId, userId or credential IDs.');
+    return;
+  }
+  try {
+    await pkc.signalAllAcceptedCredentials({ rpId: account.rpId, userId: account.userId, allAcceptedCredentialIds: ids });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export async function signalUserDetails(account: Pick<AccountPayload, 'rpId' | 'userId' | 'username' | 'displayName'>): Promise<void> {
+  const pkc = signalApi();
+  if (!pkc?.signalCurrentUserDetails) return;
+  if (!account.rpId || !isValidBase64Url(account.userId)) {
+    console.warn('signalCurrentUserDetails skipped: invalid rpId or userId.');
+    return;
+  }
+  try {
+    await pkc.signalCurrentUserDetails({
+      rpId: account.rpId,
+      userId: account.userId,
+      name: account.username,
+      displayName: account.displayName,
+    });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+export type RegisterMode = 'promotion' | 'management' | 'conditional';
+
+export type RegisterResult =
+  | { status: 'created'; account: AccountPayload }
+  | { status: 'cancelled' }
+  | { status: 'exists' }
+  | { status: 'error'; message: string };
+
+/**
+ * Creates a passkey for the signed-in user. Throws ApiError with
+ * code REAUTH_REQUIRED if the server wants the user to confirm their identity first.
+ */
+export async function registerPasskey(mode: RegisterMode): Promise<RegisterResult> {
+  if (!(await ensureWebAuthn())) return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+
+  const optionsJSON = await api<PublicKeyCredentialCreationOptionsJSON>('api/auth/passkey/register-options', {
+    body: { mode },
+  });
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(optionsJSON);
+
+  let credential: PublicKeyCredential;
+  try {
+    credential = (await navigator.credentials.create({
+      publicKey,
+      ...(mode === 'conditional' && { mediation: 'conditional' as CredentialMediationRequirement }),
+    })) as PublicKeyCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'InvalidStateError') return { status: 'exists' };
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    if (name === 'SecurityError') {
+      console.error('Passkey creation failed: RP ID or secure context misconfiguration.', err);
+      return { status: 'error', message: 'Passkeys aren’t available on this site right now.' };
+    }
+    console.error('Unexpected passkey creation error:', err);
+    return { status: 'error', message: 'Something went wrong while creating your passkey.' };
+  }
+
+  // Server verification — segregated so a failed save can be signalled to the provider.
+  const encoded = credential.toJSON() as RegistrationResponseJSON;
+  const rpId = optionsJSON.rp.id;
+  try {
+    const { account } = await api<{ account: AccountPayload }>('api/auth/passkey/register-verify', { body: encoded });
+    return { status: 'created', account };
+  } catch (err) {
+    await signalUnknownCredential(rpId, encoded.id);
+    return { status: 'error', message: err instanceof ApiError ? err.message : 'We couldn’t save your passkey.' };
+  }
+}
+
+/**
+ * Silently offers to create a passkey right after a successful password sign-in.
+ * All failures are swallowed — this must never interrupt the sign-in flow.
+ */
+export async function conditionalCreatePasskey(): Promise<void> {
+  try {
+    const caps = await getPasskeyCapabilities();
+    if (!caps.conditionalCreate) return;
+    await registerPasskey('conditional');
+  } catch (err) {
+    console.warn('Conditional passkey creation skipped:', err);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Authentication / reauthentication
+// ---------------------------------------------------------------------------
+
+export type AuthResult =
+  | { status: 'success'; username: string }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string };
+
+/**
+ * Runs a passkey sign-in ceremony. With `conditional`, the request backs the
+ * browser's autofill suggestions instead of showing a modal prompt.
+ */
+export async function authenticateWithPasskey(opts: { signal: AbortSignal; conditional?: boolean }): Promise<AuthResult> {
+  if (!(await ensureWebAuthn())) return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+
+  const optionsJSON = await api<PublicKeyCredentialRequestOptionsJSON>('api/auth/passkey/login-options');
+  if (opts.signal.aborted) return { status: 'cancelled' };
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+  let credential: PublicKeyCredential;
+  try {
+    credential = (await navigator.credentials.get({
+      publicKey,
+      signal: opts.signal,
+      ...(opts.conditional && { mediation: 'conditional' as CredentialMediationRequirement }),
+    })) as PublicKeyCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    console.error('Unexpected passkey sign-in error:', err);
+    return { status: 'error', message: 'Something went wrong while signing in with your passkey.' };
+  }
+
+  const encoded = credential.toJSON() as AuthenticationResponseJSON;
+  try {
+    const { username } = await api<{ username: string }>('api/auth/passkey/login-verify', { body: encoded });
+    return { status: 'success', username };
+  } catch (err) {
+    if (err instanceof ApiError && err.status === 404) {
+      // Pre-authentication: tell the passkey provider this credential no longer exists.
+      await signalUnknownCredential(optionsJSON.rpId, encoded.id);
+    }
+    return { status: 'error', message: err instanceof ApiError ? err.message : 'We couldn’t sign you in.' };
+  }
+}
+
+/** Reauthenticates the signed-in user with one of their own passkeys. */
+export async function reauthenticateWithPasskey(signal: AbortSignal): Promise<AuthResult | { status: 'no-passkeys' }> {
+  if (!(await ensureWebAuthn())) return { status: 'no-passkeys' };
+
+  let optionsJSON: PublicKeyCredentialRequestOptionsJSON;
+  try {
+    optionsJSON = await api<PublicKeyCredentialRequestOptionsJSON>('api/auth/reauth/options');
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'NO_PASSKEYS') return { status: 'no-passkeys' };
+    throw err;
+  }
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+  let credential: PublicKeyCredential;
+  try {
+    credential = (await navigator.credentials.get({ publicKey, signal })) as PublicKeyCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    console.error('Unexpected passkey reauthentication error:', err);
+    return { status: 'error', message: 'Something went wrong while verifying your passkey.' };
+  }
+
+  const encoded = credential.toJSON() as AuthenticationResponseJSON;
+  try {
+    await api('api/auth/reauth/verify', { body: encoded });
+    return { status: 'success', username: '' };
+  } catch (err) {
+    if (err instanceof ApiError && err.status === 404) {
+      await signalUnknownCredential(optionsJSON.rpId, encoded.id);
+    }
+    return { status: 'error', message: err instanceof ApiError ? err.message : 'We couldn’t verify that passkey.' };
+  }
+}
+
+export async function goTo(path: string): Promise<void> {
+  const { navigate } = await import('astro:transitions/client');
+  await navigate(appUrl(path));
+}
