+---
+import Layout from '../layouts/Layout.astro';
+import AccountSettings from '../components/AccountSettings';
+import { getRpId } from '../lib/auth/config';
+import { getSessionUser } from '../lib/auth/session';
+import { ensureUser, listCredentials } from '../lib/auth/store';
+import { toAccountPayload } from '../lib/auth/serialize';
+
+const sessionUser = await getSessionUser(Astro.session);
+if (!sessionUser) {
+  return Astro.redirect(`${import.meta.env.BASE_URL}signin`);
+}
+const user = await ensureUser(sessionUser.username);
+const account = toAccountPayload(user, await listCredentials(user.passkeyUserId), getRpId(Astro.url));
+Astro.response.headers.set('Cache-Control', 'no-store');
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <AccountSettings client:only="react" initialAccount={account}>
+    <p slot="fallback" class="mx-auto max-w-3xl px-4 py-10 text-gray-600">Loading your account…</p>
+  </AccountSettings>
+</Layout>
diff --git a/src/pages/api/account/passkeys.ts b/src/pages/api/account/passkeys.ts
new file mode 100644
