--- /dev/null
+++ b/src/pages/api/account/passkeys.ts
@@ -0,0 +1,13 @@
+import type { APIRoute } from 'astro';
+import { getRpId } from '../../../lib/auth/config';
+import { ensureUser, listCredentials } from '../../../lib/auth/store';
+import { toAccountPayload } from '../../../lib/auth/serialize';
+import { errorResponse, getSessionUser, json } from '../../../lib/auth/session';
+
+/** Lists the signed-in user's passkeys along with the server RP ID and WebAuthn user handle. */
+export const GET: APIRoute = async ({ session, url }) => {
+  const sessionUser = await getSessionUser(session);
+  if (!sessionUser) return errorResponse(401, 'You need to sign in first.');
+  const user = await ensureUser(sessionUser.username);
+  return json(toAccountPayload(user, await listCredentials(user.passkeyUserId), getRpId(url)));
+};
diff --git a/src/pages/api/account/passkeys/[id].ts b/src/pages/api/account/passkeys/[id].ts
new file mode 100644
index 0000000..5db714d
--- /dev/null
+++ b/src/pages/api/account/passkeys/[id].ts
@@ -0,0 +1,50 @@
+import type { APIRoute } from 'astro';
+import { getRpId } from '../../../../lib/auth/config';
+import { deleteCredential, ensureUser, getCredential, listCredentials, saveCredential } from '../../../../lib/auth/store';
+import { toAccountPayload } from '../../../../lib/auth/serialize';
+import {
+  errorResponse,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  readJson,
+  reauthRequired,
+} from '../../../../lib/auth/session';
+
+async function loadOwned(id: string | undefined, username: string) {
+  const user = await ensureUser(username);
+  const credential = id ? await getCredential(id) : undefined;
+  if (!credential || credential.passkeyUserId !== user.passkeyUserId) return { user, credential: undefined };
+  return { user, credential };
+}
+
+/** Renames a passkey (server-side label only). */
+export const PATCH: APIRoute = async ({ params, request, session, url }) => {
+  const body = await readJson<{ name?: string }>(request);
+  if (body instanceof Response) return body;
+  const sessionUser = await getSessionUser(session);
+  if (!sessionUser) return errorResponse(401, 'You need to sign in first.');
+
+  const name = body.name?.trim();
+  if (!name) return errorResponse(400, 'Enter a name for this passkey.');
+  if (name.length > 64) return errorResponse(400, 'Passkey names can be at most 64 characters.');
+
+  const { user, credential } = await loadOwned(params.id, sessionUser.username);
+  if (!credential) return errorResponse(404, 'Passkey not found.');
+
+  await saveCredential({ ...credential, name });
+  return json(toAccountPayload(user, await listCredentials(user.passkeyUserId), getRpId(url)));
+};
+
+/** Deletes a passkey. Requires a recent sign-in or reauthentication. */
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  const sessionUser = await getSessionUser(session);
+  if (!sessionUser) return errorResponse(401, 'You need to sign in first.');
+  if (!isRecentlyAuthenticated(sessionUser)) return reauthRequired();
+
+  const { user, credential } = await loadOwned(params.id, sessionUser.username);
+  if (!credential) return errorResponse(404, 'Passkey not found.');
+
+  await deleteCredential(credential.id);
+  return json(toAccountPayload(user, await listCredentials(user.passkeyUserId), getRpId(url)));
+};
