+import type { APIRoute } from 'astro';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { verifyAssertion } from '../../../../lib/auth/assertion';
+import { getCredential, getUserByPasskeyUserId } from '../../../../lib/auth/store';
+import { consumeChallenge, errorResponse, json, readJson, signIn } from '../../../../lib/auth/session';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  if (response instanceof Response) return response;
+  if (!session) return errorResponse(500, 'Sessions are not configured.');
+
+  const pending = await consumeChallenge(session, 'login');
+  if (!pending) return errorResponse(400, 'Sign-in request expired. Please try again.');
+
+  const stored = response.id ? await getCredential(response.id) : undefined;
+  const user = stored && (await getUserByPasskeyUserId(stored.passkeyUserId));
+  if (!stored || !user) {
+    // 404 lets the client tell the passkey provider this credential is gone.
+    return errorResponse(404, 'This passkey isn’t registered with The DevTools Times anymore.');
+  }
+
+  if (!(await verifyAssertion(response, stored, pending, url))) {
+    return errorResponse(400, 'We couldn’t verify that passkey.');
+  }
+
+  await signIn(session, user.username);
+  return json({ username: user.username, displayName: user.displayName });
+};
