+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { RP_NAME, SUPPORTED_ALGORITHMS, getRpId } from '../../../../lib/auth/config';
+import { ensureUser, listCredentials } from '../../../../lib/auth/store';
+import {
+  errorResponse,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  readJson,
+  reauthRequired,
+  setChallenge,
+} from '../../../../lib/auth/session';
+
+/**
+ * Creates passkey registration options for the signed-in user.
+ *
+ * mode:
+ *  - "promotion":   offered right after sign-up/sign-in; restricted to platform authenticators.
+ *  - "conditional": silent post-password-login creation (conditional mediation).
+ *  - "management":  from account settings; security keys allowed.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await readJson<{ mode?: string }>(request);
+  if (body instanceof Response) return body;
+  const mode = body.mode === 'promotion' || body.mode === 'conditional' ? body.mode : 'management';
+
+  const sessionUser = await getSessionUser(session);
+  if (!session || !sessionUser) return errorResponse(401, 'You need to sign in first.');
+  // Adding a sign-in method is sensitive: require a recent sign-in or reauthentication.
+  if (!isRecentlyAuthenticated(sessionUser)) return reauthRequired();
+
+  const user = await ensureUser(sessionUser.username);
+  const existing = await listCredentials(user.passkeyUserId);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: getRpId(url),
+    userName: user.username,
+    userDisplayName: user.displayName,
+    userID: new Uint8Array(Buffer.from(user.passkeyUserId, 'base64url')),
+    attestationType: 'none',
+    supportedAlgorithmIDs: SUPPORTED_ALGORITHMS,
+    excludeCredentials: existing.map((c) => ({ id: c.id, transports: c.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(mode === 'promotion' && { authenticatorAttachment: 'platform' as const }),
+    },
+  });
+
+  setChallenge(session, 'register', {
+    challenge: options.challenge,
+    userVerification: 'preferred',
+    conditional: mode === 'conditional',
+    username: user.username,
+  });
+
+  return json(options);
+};
