@@ -0,0 +1,71 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse, type RegistrationResponseJSON } from '@simplewebauthn/server';
+import { SUPPORTED_ALGORITHMS, getExpectedOrigins, getRpId } from '../../../../lib/auth/config';
+import { lookupProvider } from '../../../../lib/auth/aaguid';
+import { ensureUser, getCredential, listCredentials, saveCredential } from '../../../../lib/auth/store';
+import { toAccountPayload, toPublicCredential } from '../../../../lib/auth/serialize';
+import { consumeChallenge, errorResponse, getSessionUser, json, readJson } from '../../../../lib/auth/session';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const response = await readJson<RegistrationResponseJSON>(request);
+  if (response instanceof Response) return response;
+
+  const sessionUser = await getSessionUser(session);
+  if (!session || !sessionUser) return errorResponse(401, 'You need to sign in first.');
+
+  const pending = await consumeChallenge(session, 'register');
+  if (!pending || pending.username !== sessionUser.username) {
+    return errorResponse(400, 'Passkey registration expired. Please try again.');
+  }
+
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      // Options requested userVerification "preferred": accept authenticators without UV.
+      requireUserVerification: pending.userVerification === 'required',
+      // User presence is only relaxed for conditional (automatic) creation.
+      requireUserPresence: !pending.conditional,
+      supportedAlgorithmIDs: SUPPORTED_ALGORITHMS,
+    });
+  } catch (err) {
+    console.warn('Passkey registration verification failed:', err);
+    return errorResponse(400, 'We couldn’t verify that passkey.');
+  }
+  if (!verification.verified) return errorResponse(400, 'We couldn’t verify that passkey.');
+
+  const { credential, aaguid, credentialDeviceType, credentialBackedUp } = verification.registrationInfo;
+  const user = await ensureUser(sessionUser.username);
+
+  if (await getCredential(credential.id)) {
+    return errorResponse(409, 'This passkey is already registered.');
+  }
+
+  const provider = await lookupProvider(aaguid, request.headers.get('user-agent'));
+  const stored = {
+    id: credential.id,
+    passkeyUserId: user.passkeyUserId,
+    credentialPublicKey: Buffer.from(credential.publicKey).toString('base64url'),
+    credentialType: 'public-key' as const,
+    credentialDeviceType,
+    credentialBackedUp,
+    aaguid,
+    providerName: provider.name,
+    providerIconLight: provider.iconLight,
+    providerIconDark: provider.iconDark,
+    name: provider.name,
+    transports: credential.transports ?? response.response.transports ?? [],
+    registeredAt: Date.now(),
+    counter: credential.counter,
+  };
+  await saveCredential(stored);
+
+  const credentials = await listCredentials(user.passkeyUserId);
+  return json({
+    credential: toPublicCredential(stored),
+    account: toAccountPayload(user, credentials, getRpId(url)),
+  });
+};
