+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRpId } from '../../../../lib/auth/config';
+import { ensureUser, listCredentials } from '../../../../lib/auth/store';
+import { errorResponse, getSessionUser, json, readJson, setChallenge } from '../../../../lib/auth/session';
+
+/** Reauthentication options, restricted to the signed-in user's own passkeys. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await readJson(request);
+  if (body instanceof Response) return body;
+  const sessionUser = await getSessionUser(session);
+  if (!session || !sessionUser) return errorResponse(401, 'You need to sign in first.');
+
+  const user = await ensureUser(sessionUser.username);
+  const credentials = await listCredentials(user.passkeyUserId);
+  if (credentials.length === 0) {
+    return errorResponse(409, 'No passkeys registered. Confirm with your password instead.', 'NO_PASSKEYS');
+  }
+
+  const options = await generateAuthenticationOptions({
+    rpID: getRpId(url),
+    allowCredentials: credentials.map((c) => ({ id: c.id, transports: c.transports as never })),
+    userVerification: 'preferred',
+  });
+  setChallenge(session, 'reauth', {
+    challenge: options.challenge,
+    userVerification: 'preferred',
+    username: user.username,
+  });
+  return json(options);
+};
