+import type { APIRoute } from 'astro';
+import { callPasswordService } from '../../../../lib/auth/upstream';
+import { errorResponse, getSessionUser, json, markReauthenticated, readJson } from '../../../../lib/auth/session';
+
+/** Password reauthentication fallback for the signed-in user. */
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await readJson<{ password?: string }>(request);
+  if (body instanceof Response) return body;
+  const sessionUser = await getSessionUser(session);
+  if (!session || !sessionUser) return errorResponse(401, 'You need to sign in first.');
+  if (!body.password) return errorResponse(400, 'Password is required.');
+
+  const result = await callPasswordService('login', sessionUser.username, body.password);
+  if (!result.ok) return errorResponse(result.status >= 500 ? 502 : 403, result.error ?? 'Incorrect password.');
+
+  await markReauthenticated(session);
+  return json({ ok: true });
+};
