+import type { APIRoute } from 'astro';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { verifyAssertion } from '../../../../lib/auth/assertion';
+import { ensureUser, getCredential } from '../../../../lib/auth/store';
+import {
+  consumeChallenge,
+  errorResponse,
+  getSessionUser,
+  json,
+  markReauthenticated,
+  readJson,
+} from '../../../../lib/auth/session';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  if (response instanceof Response) return response;
+  const sessionUser = await getSessionUser(session);
+  if (!session || !sessionUser) return errorResponse(401, 'You need to sign in first.');
+
+  const pending = await consumeChallenge(session, 'reauth');
+  if (!pending || pending.username !== sessionUser.username) {
+    return errorResponse(400, 'Verification expired. Please try again.');
+  }
+
+  const stored = response.id ? await getCredential(response.id) : undefined;
+  if (!stored) return errorResponse(404, 'This passkey isn’t registered anymore.');
+
+  // The passkey must belong to the signed-in user — never accept another account's passkey.
+  const user = await ensureUser(sessionUser.username);
+  if (stored.passkeyUserId !== user.passkeyUserId) {
+    return errorResponse(403, 'That passkey belongs to a different account.');
+  }
+
+  if (!(await verifyAssertion(response, stored, pending, url))) {
+    return errorResponse(400, 'We couldn’t verify that passkey.');
+  }
+
+  await markReauthenticated(session);
+  return json({ ok: true });
+};
