+import React, { useCallback, useEffect, useRef, useState } from 'react';
+import {
+  ApiError,
+  BASE_URL,
+  authApi,
+  createPasskey,
+  describeError,
+  goTo,
+  isCancellation,
+  supportsPasskeys,
+  syncPasskeysWithProvider,
+  type PasskeyInfo,
+  type SessionInfo,
+  type SessionUser,
+} from '../lib/client/passkeys';
+import ReauthDialog from './auth/ReauthDialog';
+import { Alert, PasskeyIcon, inputClass } from './auth/ui';
+
+interface Props {
+  initialSession: SessionInfo;
+  initialPasskeys: PasskeyInfo[];
+}
+
+type Notice = { kind: 'error' | 'success' | 'info'; text: string } | null;
+
+const dateFormat = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+const relativeFormat = new Intl.RelativeTimeFormat('en-US', { numeric: 'auto' });
+
+function formatRelative(iso: string) {
+  const diffSeconds = (new Date(iso).getTime() - Date.now()) / 1000;
+  const units: [Intl.RelativeTimeFormatUnit, number][] = [
+    ['year', 31536000],
+    ['month', 2592000],
+    ['week', 604800],
+    ['day', 86400],
+    ['hour', 3600],
+    ['minute', 60],
+  ];
+  for (const [unit, seconds] of units) {
+    if (Math.abs(diffSeconds) >= seconds) return relativeFormat.format(Math.round(diffSeconds / seconds), unit);
+  }
+  return 'just now';
+}
+
+export default function AccountSettings({ initialSession, initialPasskeys }: Props) {
+  const [session, setSession] = useState<SessionInfo>(initialSession);
+  const [passkeys, setPasskeys] = useState<PasskeyInfo[]>(initialPasskeys);
