+    setNotice(null);
+    setCreating(true);
+    const startedAt = Date.now();
+    try {
+      const result = await withReauth('create a passkey', createPasskey);
+      if (result) {
+        updateSession(result.session);
+        setPasskeys((list) => [result.passkey, ...list.filter((p) => p.id !== result.passkey.id)]);
+        setHighlightId(result.passkey.id);
+        setNotice({
+          kind: 'success',
+          text: `Passkey created${result.passkey.providerName ? ` in ${result.passkey.providerName}` : ''}. You can now use it to sign in.`,
+        });
