+    } catch (err) {
+      if (isCancellation(err)) {
+        // Some browsers require a fresh click after the confirmation dialog.
+        if (reauthPromptedAt.current >= startedAt) setNotice({ kind: 'info', text: 'Identity confirmed. Select “Create a passkey” to continue.' });
+      } else {
+        setNotice({ kind: 'error', text: describeError(err) });
+      }
