+    const { passkey } = await authApi<{ passkey: PasskeyInfo }>(`passkeys/${encodeURIComponent(id)}`, {
+      method: 'PATCH',
+      body: { name },
+    });
+    setPasskeys((list) => list.map((p) => (p.id === id ? passkey : p)));
+    setNotice({ kind: 'success', text: 'Passkey renamed.' });
+  };
+
+  const handleDelete = async (passkey: PasskeyInfo) => {
+    setNotice(null);
+    try {
+      const result = await withReauth('remove this passkey', () =>
+        authApi<{ passkeys: PasskeyInfo[]; session: SessionInfo }>(`passkeys/${encodeURIComponent(passkey.id)}`, {
+          method: 'DELETE',
+        }),
+      );
+      if (!result) return false;
+      setPasskeys(result.passkeys);
+      updateSession(result.session);
