+          <p className="text-xs font-semibold uppercase tracking-widest text-gray-500">Account settings</p>
+          <h1 className="font-serif text-4xl font-bold text-gray-900">{user.displayName}</h1>
+          <p className="text-sm text-gray-600">Signed in as {user.username}</p>
+        </div>
+        <button
+          type="button"
+          onClick={handleSignOut}
+          className="text-sm font-semibold py-2 px-3 rounded border border-gray-300 hover:bg-gray-50"
+        >
+          Sign out
+        </button>
+      </div>
+
+      {notice && <Alert kind={notice.kind}>{notice.text}</Alert>}
+
+      {/* Sign-in methods overview */}
+      <section aria-labelledby="signin-methods" className="mb-10">
+        <h2 id="signin-methods" className="text-xl font-bold text-gray-900 mb-3">
+          Sign-in methods
+        </h2>
+        <dl className="divide-y divide-gray-200 border border-gray-200 rounded-lg">
+          <div className="flex items-center justify-between p-4">
+            <dt className="text-sm font-medium text-gray-900">Password</dt>
+            <dd className="text-sm text-gray-600">{user.hasPassword ? 'Set' : 'Not set — this account uses passkeys only'}</dd>
+          </div>
+          <div className="flex items-center justify-between p-4">
+            <dt className="text-sm font-medium text-gray-900">Passkeys</dt>
+            <dd className="text-sm text-gray-600">
+              {passkeys.length === 0 ? 'None yet' : `${passkeys.length} passkey${passkeys.length === 1 ? '' : 's'}`}
+            </dd>
+          </div>
+        </dl>
+      </section>
+
+      {/* Passkeys */}
+      <section aria-labelledby="passkeys-heading">
+        <div className="flex flex-wrap items-center justify-between gap-3 mb-2">
+          <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900">
+            Passkeys
+          </h2>
+          {passkeysAvailable && (
+            <button
+              type="button"
+              onClick={handleCreate}
+              disabled={creating}
