+          setReauth(null);
+        }}
+        onCancel={() => {
+          reauth?.resolve(false);
+          setReauth(null);
+        }}
+      />
+    </div>
+  );
+}
+
+interface RowProps {
+  passkey: PasskeyInfo;
+  highlighted: boolean;
+  deleteBlocked: boolean;
+  onRename: (id: string, name: string) => Promise<void>;
+  onDelete: (passkey: PasskeyInfo) => Promise<boolean>;
+}
+
+function PasskeyRow({ passkey, highlighted, deleteBlocked, onRename, onDelete }: RowProps) {
+  const [mode, setMode] = useState<'view' | 'rename' | 'confirm-delete'>('view');
+  const [name, setName] = useState(passkey.name);
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const inputRef = useRef<HTMLInputElement>(null);
+
+  useEffect(() => {
+    if (mode === 'rename') inputRef.current?.select();
+  }, [mode]);
+
+  const submitRename = useCallback(
+    async (e: React.FormEvent) => {
+      e.preventDefault();
+      if (name.trim() === passkey.name) {
+        setMode('view');
+        return;
+      }
+      setBusy(true);
+      setError(null);
+      try {
+        await onRename(passkey.id, name.trim());
+        setMode('view');
+      } catch (err) {
+        setError(describeError(err));
+      } finally {
+        setBusy(false);
+      }
+    },
+    [name, passkey, onRename],
+  );
+
+  const confirmDelete = async () => {
+    setBusy(true);
+    const removed = await onDelete(passkey);
+    if (!removed) {
+      setBusy(false);
+      setMode('view');
+    }
+  };
+
+  return (
+    <li className={`p-4 transition-colors ${highlighted ? 'bg-green-50' : ''}`}>
+      <div className="flex items-start gap-4">
+        <div className="flex h-10 w-10 flex-none items-center justify-center rounded-md border border-gray-200 bg-white">
+          {passkey.providerIcon ? (
+            <img src={passkey.providerIcon} alt="" className="h-6 w-6" />
+          ) : (
+            <PasskeyIcon className="h-6 w-6 text-gray-700" />
+          )}
+        </div>
+
+        <div className="min-w-0 flex-1">
+          {mode === 'rename' ? (
+            <form onSubmit={submitRename} className="flex flex-wrap items-center gap-2">
+              <label htmlFor={`rename-${passkey.id}`} className="sr-only">
+                Passkey name
+              </label>
+              <input
+                id={`rename-${passkey.id}`}
+                ref={inputRef}
+                value={name}
+                maxLength={64}
+                onChange={(e) => setName(e.target.value)}
+                onKeyDown={(e) => {
+                  if (e.key === 'Escape') {
+                    setName(passkey.name);
+                    setMode('view');
+                  }
+                }}
+                required
+                className={`${inputClass} max-w-xs py-1`}
+              />
+              <button type="submit" disabled={busy} className="text-sm font-semibold text-gray-900 hover:underline">
+                Save
+              </button>
+              <button
+                type="button"
+                onClick={() => {
+                  setName(passkey.name);
+                  setMode('view');
+                }}
+                className="text-sm text-gray-600 hover:underline"
+              >
+                Cancel
+              </button>
+            </form>
+          ) : (
+            <p className="truncate font-medium text-gray-900">{passkey.name}</p>
+          )}
+
+          <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-gray-500">
+            {passkey.providerName && passkey.providerName !== passkey.name && <span>{passkey.providerName}</span>}
+            <span
+              className={`inline-flex items-center rounded-full px-2 py-0.5 font-medium ${
+                passkey.synced ? 'bg-blue-50 text-blue-700' : 'bg-gray-100 text-gray-700'
+              }`}
+              title={
+                passkey.synced
+                  ? 'Backed up and available on your other devices signed in to the same password manager.'
+                  : 'Stored only on this device or security key.'
+              }
+            >
+              {passkey.synced ? 'Synced' : 'This device only'}
+            </span>
+            <span>Created {dateFormat.format(new Date(passkey.createdAt))}</span>
+            <span>{passkey.lastUsedAt ? `Last used ${formatRelative(passkey.lastUsedAt)}` : 'Never used to sign in'}</span>
+          </div>
+
+          {error && <p className="mt-2 text-sm text-red-700">{error}</p>}
+
+          {mode === 'confirm-delete' && (
+            <div className="mt-3 rounded-md bg-red-50 p-3 text-sm text-red-800" role="alertdialog" aria-label="Remove passkey">
+              <p>
+                Remove <strong>{passkey.name}</strong>? You won’t be able to sign in with it anymore.
+              </p>
+              <div className="mt-2 flex gap-3">
+                <button
+                  type="button"
+                  onClick={confirmDelete}
+                  disabled={busy}
+                  className="rounded bg-red-700 px-3 py-1 font-semibold text-white hover:bg-red-800 disabled:opacity-75"
+                >
+                  {busy ? 'Removing…' : 'Remove'}
+                </button>
+                <button type="button" onClick={() => setMode('view')} disabled={busy} className="font-medium hover:underline">
+                  Cancel
+                </button>
+              </div>
+            </div>
+          )}
+        </div>
+
+        {mode === 'view' && (
+          <div className="flex flex-none items-center gap-3 text-sm">
+            <button
+              type="button"
+              onClick={() => setMode('rename')}
+              className="font-medium text-gray-700 hover:text-gray-900 hover:underline"
+              aria-label={`Rename ${passkey.name}`}
+            >
+              Rename
+            </button>
+            <button
+              type="button"
+              onClick={() => setMode('confirm-delete')}
+              disabled={deleteBlocked}
+              title={deleteBlocked ? 'Create another passkey before removing your only way to sign in.' : undefined}
+              className="font-medium text-red-700 hover:text-red-900 hover:underline disabled:cursor-not-allowed disabled:text-gray-400 disabled:no-underline"
+              aria-label={`Remove ${passkey.name}`}
+            >
+              Remove
+            </button>
+          </div>
+        )}
+      </div>
+    </li>
+  );
+}
