new file mode 100644
index 0000000..2baf6f8
--- /dev/null
+++ b/src/components/auth/PasskeyUpsell.tsx
@@ -0,0 +1,50 @@
+import React, { useState } from 'react';
+import { createPasskey, describeError, isCancellation } from '../../lib/client/passkeys';
+import { Alert, PasskeyIcon, primaryButtonClass, secondaryButtonClass } from './ui';
+
+interface Props {
+  /** Called after a passkey was created or the user chose to skip. */
+  onDone: (created: boolean) => void;
+  heading?: string;
+}
+
+/** Prompt shown right after a password sign-in/sign-up, encouraging a passkey upgrade. */
+export default function PasskeyUpsell({ onDone, heading = 'Sign in faster next time' }: Props) {
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  const create = async () => {
+    setBusy(true);
+    setError(null);
+    try {
+      await createPasskey();
+      onDone(true);
+    } catch (err) {
+      if (!isCancellation(err)) setError(describeError(err));
+      setBusy(false);
+    }
+  };
+
+  return (
+    <div className="text-center">
+      <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-gray-100 text-gray-900">
+        <PasskeyIcon className="h-8 w-8" />
+      </div>
+      <h3 className="text-lg font-semibold text-gray-900">{heading}</h3>
+      <p className="mt-2 mb-6 text-sm text-gray-600">
+        Create a passkey to sign in to The DevTools Times with your fingerprint, face, or screen lock. Passkeys are
+        safer than passwords: they can’t be guessed, reused, or phished.
+      </p>
+      {error && <Alert kind="error">{error}</Alert>}
+      <div className="space-y-3">
+        <button type="button" onClick={create} disabled={busy} className={primaryButtonClass}>
+          <PasskeyIcon />
+          {busy ? 'Waiting for your passkey…' : 'Create a passkey'}
+        </button>
+        <button type="button" onClick={() => onDone(false)} disabled={busy} className={secondaryButtonClass}>
+          Not now
+        </button>
+      </div>
+    </div>
+  );
+}
diff --git a/src/components/auth/ReauthDialog.tsx b/src/components/auth/ReauthDialog.tsx
new file mode 100644
index 0000000..0cbf7a7
--- /dev/null
+++ b/src/components/auth/ReauthDialog.tsx
@@ -0,0 +1,136 @@
+import React, { useEffect, useRef, useState } from 'react';
+import {
+  ApiError,
+  authApi,
+  describeError,
+  isCancellation,
+  reauthenticateWithPasskey,
+  type SessionInfo,
+  type SessionUser,
+} from '../../lib/client/passkeys';
+import { Alert, Divider, PasskeyIcon, inputClass, primaryButtonClass, secondaryButtonClass } from './ui';
+
+interface Props {
+  open: boolean;
+  user: SessionUser;
+  /** Short description of what the user is confirming, e.g. "remove this passkey". */
+  reason?: string;
+  onSuccess: (session: SessionInfo) => void;
+  onCancel: () => void;
+}
+
+/** Asks the signed-in user to confirm their identity (passkey or password) before a sensitive action. */
+export default function ReauthDialog({ open, user, reason, onSuccess, onCancel }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [busy, setBusy] = useState<'passkey' | 'password' | null>(null);
+  const canUsePasskey = user.passkeyCount > 0;
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (open && !dialog.open) {
+      setError(null);
+      setPassword('');
+      dialog.showModal();
+    } else if (!open && dialog.open) {
+      dialog.close();
+    }
+  }, [open]);
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy('passkey');
+    try {
+      onSuccess(await reauthenticateWithPasskey());
+    } catch (err) {
+      if (!isCancellation(err)) setError(describeError(err));
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const verifyWithPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy('password');
+    try {
+      const session = await authApi<SessionInfo>('reauth-password', { body: { password } });
+      setPassword('');
+      onSuccess(session);
+    } catch (err) {
+      setError(err instanceof ApiError ? err.message : 'An unexpected error occurred. Please try again later.');
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      onCancel={(e) => {
+        e.preventDefault();
+        if (!busy) onCancel();
+      }}
+      aria-labelledby="reauth-title"
+      className="m-auto w-full max-w-sm rounded-lg p-0 shadow-xl backdrop:bg-gray-900/50"
+    >
+      <div className="p-6">
+        <h2 id="reauth-title" className="text-lg font-semibold text-gray-900">
+          Confirm it’s you
+        </h2>
+        <p className="mt-1 mb-5 text-sm text-gray-600">
+          For your security, please verify your identity{reason ? ` to ${reason}` : ''}. Signed in as{' '}
+          <span className="font-medium text-gray-900">{user.username}</span>.
+        </p>
+
+        {error && <Alert kind="error">{error}</Alert>}
+
+        {canUsePasskey && (
+          <button type="button" onClick={verifyWithPasskey} disabled={busy !== null} className={primaryButtonClass}>
+            <PasskeyIcon />
+            {busy === 'passkey' ? 'Waiting for your passkey…' : 'Use your passkey'}
+          </button>
+        )}
+
+        {canUsePasskey && user.hasPassword && <Divider label="or" />}
+
+        {user.hasPassword && (
+          <form onSubmit={verifyWithPassword} className="space-y-3">
+            {/* Hidden username helps password managers pick the right credential. */}
+            <input type="text" name="username" autoComplete="username" value={user.username} readOnly hidden />
+            <label htmlFor="reauth-password" className="block text-sm font-medium text-gray-700">
+              Password
+            </label>
+            <input
+              id="reauth-password"
+              type="password"
+              autoComplete="current-password"
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              required
+              className={inputClass}
+            />
+            <button
+              type="submit"
+              disabled={busy !== null}
+              className={canUsePasskey ? secondaryButtonClass : primaryButtonClass}
+            >
+              {busy === 'password' ? 'Verifying…' : 'Continue with password'}
+            </button>
+          </form>
+        )}
+
+        <button
+          type="button"
+          onClick={onCancel}
+          disabled={busy !== null}
+          className="mt-4 w-full text-center text-sm font-medium text-gray-600 hover:text-gray-900"
+        >
+          Cancel
+        </button>
+      </div>
+    </dialog>
+  );
+}
