@@ -0,0 +1,56 @@
+import React from 'react';
+
+export const inputClass =
+  'w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500';
+
+export const primaryButtonClass =
+  'w-full inline-flex items-center justify-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed';
+
+export const secondaryButtonClass =
+  'w-full inline-flex items-center justify-center gap-2 py-2 px-4 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-800 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed';
+
+/** The FIDO Alliance-style passkey glyph (person + key). */
+export function PasskeyIcon({ className = 'w-5 h-5' }: { className?: string }) {
+  return (
+    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
+      <circle cx="9" cy="7.5" r="4" />
+      <path d="M2 19.5c0-3.3 2.9-5.5 7-5.5 1.3 0 2.5.2 3.5.6A5 5 0 0 0 12 17v2.5H2z" />
+      <path d="M17.5 10.5a3.5 3.5 0 0 0-1 6.86V21l1.5 1.5 1.5-1.5-1-1 1-1-1-1 .5-.5v-.14a3.5 3.5 0 0 0-1.5-6.86zm0 1.75a1 1 0 1 1 0 2 1 1 0 0 1 0-2z" />
+    </svg>
+  );
+}
+
+export function Alert({ kind, children }: { kind: 'error' | 'success' | 'info'; children: React.ReactNode }) {
+  const styles = {
+    error: 'text-red-700 bg-red-100',
+    success: 'text-green-700 bg-green-100',
+    info: 'text-blue-800 bg-blue-50',
+  }[kind];
+  return (
+    <div className={`mb-4 p-3 text-sm rounded-lg ${styles}`} role={kind === 'error' ? 'alert' : 'status'}>
+      {children}
+    </div>
+  );
+}
+
+export function Divider({ label }: { label: string }) {
+  return (
+    <div className="relative my-6" role="separator">
+      <div className="absolute inset-0 flex items-center" aria-hidden="true">
+        <div className="w-full border-t border-gray-200" />
+      </div>
+      <div className="relative flex justify-center text-xs uppercase tracking-wide">
+        <span className="bg-white px-2 text-gray-500">{label}</span>
+      </div>
+    </div>
+  );
+}
+
+export function Card({ title, children }: { title: string; children: React.ReactNode }) {
+  return (
+    <div className="max-w-md mx-auto mt-10 p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+      <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">{title}</h2>
+      {children}
+    </div>
+  );
+}
