+export interface SessionUser {
+  id: string;
+  username: string;
+  displayName: string;
+  hasPassword: boolean;
+  passkeyCount: number;
+}
+
+export interface SessionInfo {
+  rpID: string;
+  user: SessionUser | null;
+  reauthUntil?: number;
+}
+
+export interface PasskeyInfo {
+  id: string;
+  name: string;
+  providerName: string | null;
+  providerIcon: string | null;
+  providerIconDark: string | null;
+  synced: boolean;
+  deviceType: 'singleDevice' | 'multiDevice';
+  transports: string[];
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+export class ApiError extends Error {
+  constructor(
+    message: string,
+    public code: string,
+    public status: number,
+    public data: any = null,
+  ) {
+    super(message);
+    this.name = 'ApiError';
+  }
+}
+
+export const BASE_URL = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
+
+export async function authApi<T = any>(path: string, init: { method?: string; body?: unknown } = {}): Promise<T> {
+  const response = await fetch(`${BASE_URL}api/auth/${path}`, {
+    method: init.method ?? (init.body === undefined ? 'GET' : 'POST'),
+    headers: init.body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: init.body === undefined ? undefined : JSON.stringify(init.body),
+    credentials: 'same-origin',
+  });
+  let data: any = null;
+  try {
+    data = await response.json();
+  } catch {
+    // ignore
+  }
+  if (!response.ok) {
+    throw new ApiError(
+      data?.error?.message ?? 'An unexpected error occurred. Please try again later.',
+      data?.error?.code ?? 'unknown',
+      response.status,
+      data,
+    );
+  }
+  return data as T;
+}
+
+// ---------------------------------------------------------------------------------------------
+// Feature detection
+// ---------------------------------------------------------------------------------------------
+
+export const supportsPasskeys = () => typeof window !== 'undefined' && browserSupportsWebAuthn();
+export const supportsAutofill = () => browserSupportsWebAuthnAutofill();
+
+export async function supportsConditionalCreate() {
+  if (!supportsPasskeys()) return false;
+  try {
+    return (await getBrowserCapabilities()).conditionalCreate === 'supported';
+  } catch {
+    return false;
+  }
+}
+
+// ---------------------------------------------------------------------------------------------
+// Ceremonies
+// ---------------------------------------------------------------------------------------------
+
+/** Sign in with a discoverable passkey, either via an explicit button or via browser autofill. */
+export async function signInWithPasskey({ autofill = false } = {}): Promise<SessionInfo> {
+  const optionsJSON = await authApi('passkeys/authentication-options', { body: { purpose: 'signin' } });
+  const response = await startAuthentication({ optionsJSON, useBrowserAutofill: autofill });
+  return verifyAuthentication(response);
+}
+
+/** Confirm the signed-in user with one of their own passkeys. */
+export async function reauthenticateWithPasskey(): Promise<SessionInfo> {
+  const optionsJSON = await authApi('passkeys/authentication-options', { body: { purpose: 'reauth' } });
+  const response = await startAuthentication({ optionsJSON });
+  return verifyAuthentication(response);
+}
+
+async function verifyAuthentication(response: unknown): Promise<SessionInfo> {
+  try {
+    return await authApi<SessionInfo>('passkeys/authentication-verify', { body: { response } });
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'unknown_credential' && err.data?.credentialID) {
+      // Let the passkey provider know this passkey is gone so it stops offering it.
+      await signal({ signalName: 'unknownCredential', rpID: err.data.rpID, credentialID: err.data.credentialID });
+    }
+    throw err;
+  }
+}
+
+/**
+ * Create a passkey. When signed in it's added to the current account; when signed out a new,
+ * passkey-only account is created for `username`. `conditional` attempts a silent passkey upgrade
+ * with the password manager the user just signed in with.
+ */
+export async function createPasskey(
+  opts: { username?: string; conditional?: boolean } = {},
+): Promise<{ passkey: PasskeyInfo; session: SessionInfo }> {
+  const optionsJSON = await authApi('passkeys/registration-options', {
+    body: { username: opts.username, conditional: opts.conditional },
+  });
+  const response = await startRegistration({ optionsJSON, useAutoRegister: Boolean(opts.conditional) });
+  const result = await authApi<{ passkey: PasskeyInfo; session: SessionInfo }>('passkeys/registration-verify', {
+    body: { response },
+  });
+  const user = result.session.user;
+  if (user) {
+    await signal({
+      signalName: 'currentUserDetails',
+      rpID: result.session.rpID,
+      userID: user.id,
+      userName: user.username,
+      userDisplayName: user.displayName,
+    });
+  }
+  return result;
+}
+
+export function cancelPasskeyCeremony() {
+  WebAuthnAbortService.cancelCeremony();
+}
+
+// ---------------------------------------------------------------------------------------------
+// Signal API (keeps passkey providers in sync with the server; best effort)
+// ---------------------------------------------------------------------------------------------
+
+async function signal(opts: Parameters<typeof sendSignal>[0]) {
+  try {
+    await sendSignal(opts);
+  } catch {
+    // Unsupported browser or provider; signals are fire-and-forget.
+  }
+}
+
+export async function syncPasskeysWithProvider(session: SessionInfo, passkeyIDs: string[]) {
+  const user = session.user;
+  if (!user) return;
+  await signal({
+    signalName: 'allAcceptedCredentials',
+    rpID: session.rpID,
+    userID: user.id,
+    allAcceptedCredentialIDs: passkeyIDs,
+  });
+  await signal({
+    signalName: 'currentUserDetails',
+    rpID: session.rpID,
+    userID: user.id,
+    userName: user.username,
+    userDisplayName: user.displayName,
+  });
+}
+
+// ---------------------------------------------------------------------------------------------
+// Errors
+// ---------------------------------------------------------------------------------------------
+
+/** True when the user dismissed the passkey prompt or another ceremony replaced this one. */
+export function isCancellation(err: unknown) {
+  if (err instanceof WebAuthnError) {
+    if (err.code === 'ERROR_CEREMONY_ABORTED') return true;
+    const cause = err.cause as Error | undefined;
+    return cause?.name === 'NotAllowedError' || cause?.name === 'AbortError';
+  }
+  const name = (err as Error | undefined)?.name;
+  return name === 'NotAllowedError' || name === 'AbortError';
+}
+
+export function describeError(err: unknown): string {
+  if (err instanceof ApiError) return err.message;
+  if (err instanceof WebAuthnError) {
+    switch (err.code) {
+      case 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED':
+        return 'You already have a passkey for this account in this password manager or on this security key.';
+      case 'ERROR_INVALID_DOMAIN':
+      case 'ERROR_INVALID_RP_ID':
+        return 'Passkeys aren’t available on this domain. Use a secure (HTTPS) connection or localhost.';
+      case 'ERROR_AUTHENTICATOR_MISSING_DISCOVERABLE_CREDENTIAL_SUPPORT':
+      case 'ERROR_AUTHENTICATOR_MISSING_USER_VERIFICATION_SUPPORT':
+        return 'This authenticator can’t store passkeys. Try a different device or password manager.';
+      default:
+        break;
+    }
+  }
+  if (isCancellation(err)) return 'The passkey request was cancelled or timed out.';
+  return 'Something went wrong with your passkey. Please try again.';
+}
+
+// ---------------------------------------------------------------------------------------------
+// Navigation helpers
+// ---------------------------------------------------------------------------------------------
+
+/** Resolve a safe, same-site post-sign-in destination from `?next=`. */
+export function postSignInDestination(fallback = BASE_URL) {
+  if (typeof window === 'undefined') return fallback;
+  const next = new URLSearchParams(window.location.search).get('next');
+  if (next && next.startsWith(BASE_URL) && !next.startsWith('//')) return next;
+  return fallback;
+}
+
+export function goTo(url: string) {
+  // Full navigation so the server-rendered header reflects the new session state.
+  window.location.assign(url);
+}
diff --git a/src/lib/server/auth-store.ts b/src/lib/server/auth-store.ts
new file mode 100644
index 0000000..7001da8
--- /dev/null
+++ b/src/lib/server/auth-store.ts
@@ -0,0 +1,175 @@
+import { randomBytes } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+
+/**
+ * A tiny file-backed store for local user records and their passkeys.
+ *
+ * Password verification is still delegated to the upstream Times auth API; this store only holds
+ * what the relying party needs for WebAuthn (a stable, random user handle and the registered
+ * public-key credentials).
+ *
+ * NOTE: data lives on the local filesystem (`AUTH_DATA_DIR`, default `./.data`). For deployments
+ * with multiple instances, swap this module for a shared database.
+ */
+
+export interface StoredUser {
+  /** Random, opaque WebAuthn user handle (base64url, 32 bytes). Never contains PII. */
+  id: string;
+  username: string;
+  displayName: string;
+  /** Whether the user has a password with the upstream auth API. */
+  hasPassword: boolean;
+  createdAt: string;
+}
+
+export interface StoredPasskey {
+  /** Credential ID (base64url). */
+  id: string;
+  userId: string;
+  /** COSE public key (base64url). */
+  publicKey: string;
+  counter: number;
+  transports: string[];
+  aaguid: string;
+  name: string;
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+interface StoreData {
+  users: StoredUser[];
+  passkeys: StoredPasskey[];
+}
+
+const DATA_DIR = process.env.AUTH_DATA_DIR || path.join(process.cwd(), '.data');
+const DATA_FILE = path.join(DATA_DIR, 'auth-store.json');
+
+let cache: StoreData | null = null;
+let queue: Promise<unknown> = Promise.resolve();
+
+async function load(): Promise<StoreData> {
+  if (cache) return cache;
+  try {
+    const raw = await readFile(DATA_FILE, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<StoreData>;
+    cache = { users: parsed.users ?? [], passkeys: parsed.passkeys ?? [] };
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') console.error('[auth-store] Failed to read store, starting empty', err);
+    cache = { users: [], passkeys: [] };
+  }
+  return cache;
+}
+
+async function persist(data: StoreData) {
+  await mkdir(DATA_DIR, { recursive: true });
+  const tmp = `${DATA_FILE}.${process.pid}.tmp`;
+  await writeFile(tmp, JSON.stringify(data, null, 2), 'utf8');
+  await rename(tmp, DATA_FILE);
+}
+
+/** Serialize all access so read-modify-write cycles never interleave. */
+function withStore<T>(fn: (data: StoreData) => T | Promise<T>, write = false): Promise<T> {
+  const run = queue.then(async () => {
+    const data = await load();
+    const result = await fn(data);
+    if (write) await persist(data);
+    return result;
+  });
+  queue = run.catch(() => undefined);
+  return run;
+}
+
+export const usernameKey = (username: string) => username.trim().toLowerCase();
+
+export function findUserById(id: string) {
+  return withStore((d) => d.users.find((u) => u.id === id) ?? null);
+}
+
+export function findUserByUsername(username: string) {
+  const key = usernameKey(username);
+  return withStore((d) => d.users.find((u) => usernameKey(u.username) === key) ?? null);
+}
+
+export function createUser(input: { username: string; displayName?: string; hasPassword: boolean }) {
+  return withStore((d) => {
+    const key = usernameKey(input.username);
+    if (d.users.some((u) => usernameKey(u.username) === key)) {
+      throw new Error('USERNAME_TAKEN');
+    }
+    const user: StoredUser = {
+      id: randomBytes(32).toString('base64url'),
+      username: input.username.trim(),
+      displayName: (input.displayName || input.username).trim(),
+      hasPassword: input.hasPassword,
+      createdAt: new Date().toISOString(),
+    };
+    d.users.push(user);
+    return user;
+  }, true);
+}
+
+export function updateUser(id: string, patch: Partial<Pick<StoredUser, 'displayName' | 'hasPassword'>>) {
+  return withStore((d) => {
+    const user = d.users.find((u) => u.id === id);
+    if (!user) return null;
+    Object.assign(user, patch);
+    return user;
+  }, true);
+}
+
+export function listPasskeys(userId: string) {
+  return withStore((d) =>
+    d.passkeys
+      .filter((p) => p.userId === userId)
+      .sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
+  );
+}
+
+export function findPasskey(id: string) {
+  return withStore((d) => d.passkeys.find((p) => p.id === id) ?? null);
+}
+
+export function addPasskey(passkey: StoredPasskey) {
+  return withStore((d) => {
+    if (d.passkeys.some((p) => p.id === passkey.id)) throw new Error('CREDENTIAL_EXISTS');
+    d.passkeys.push(passkey);
+    return passkey;
+  }, true);
+}
+
+/** Atomically create a user together with their first passkey (passkey-only sign-up). */
+export function createUserWithPasskey(user: StoredUser, passkey: StoredPasskey) {
+  return withStore((d) => {
+    const key = usernameKey(user.username);
+    if (d.users.some((u) => usernameKey(u.username) === key)) throw new Error('USERNAME_TAKEN');
+    if (d.passkeys.some((p) => p.id === passkey.id)) throw new Error('CREDENTIAL_EXISTS');
+    d.users.push(user);
+    d.passkeys.push(passkey);
+    return user;
+  }, true);
+}
+
+export function updatePasskey(
+  id: string,
+  userId: string,
+  patch: Partial<Pick<StoredPasskey, 'name' | 'counter' | 'lastUsedAt' | 'backedUp' | 'deviceType'>>,
+) {
+  return withStore((d) => {
+    const passkey = d.passkeys.find((p) => p.id === id && p.userId === userId);
+    if (!passkey) return null;
+    Object.assign(passkey, patch);
+    return passkey;
+  }, true);
+}
+
+export function deletePasskey(id: string, userId: string) {
+  return withStore((d) => {
+    const index = d.passkeys.findIndex((p) => p.id === id && p.userId === userId);
+    if (index === -1) return false;
+    d.passkeys.splice(index, 1);
+    return true;
+  }, true);
+}
