@@ -0,0 +1,246 @@
+import type { APIContext } from 'astro';
+import { ConvenienceMetadataService } from '@simplewebauthn/server';
+import { findUserById, listPasskeys, type StoredPasskey, type StoredUser } from './auth-store';
+
+type Session = NonNullable<APIContext['session']>;
+
+export const RP_NAME = 'The DevTools Times';
+/** How long a sign-in or reauthentication counts as "recent" for sensitive actions. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+/** How long a WebAuthn challenge stays valid. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+export const UPSTREAM_AUTH_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+// ---------------------------------------------------------------------------------------------
+// HTTP helpers
+// ---------------------------------------------------------------------------------------------
+
+export function json(data: unknown, status = 200, headers: Record<string, string> = {}) {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+}
+
+export function apiError(code: string, message: string, status = 400) {
+  return json({ error: { code, message } }, status);
+}
+
+/**
+ * Parse a JSON body. Requiring `application/json` means cross-site form posts can't reach these
+ * endpoints without a CORS preflight, which acts as CSRF protection (Astro's `checkOrigin` is
+ * disabled in this project).
+ */
+export async function readJson<T = Record<string, unknown>>(request: Request): Promise<T | null> {
+  const type = request.headers.get('content-type') || '';
+  if (!type.toLowerCase().includes('application/json')) return null;
+  try {
+    const body = await request.json();
+    return body && typeof body === 'object' ? (body as T) : null;
+  } catch {
+    return null;
+  }
+}
+
+export const badRequest = () => apiError('invalid_request', 'The request body must be valid JSON.', 400);
+export const noSession = () => apiError('session_unavailable', 'Sessions are not available on this server.', 500);
+
+// ---------------------------------------------------------------------------------------------
+// Relying party configuration
+// ---------------------------------------------------------------------------------------------
+
+export function getRelyingParty(url: URL) {
+  const rpID = process.env.PASSKEY_RP_ID || url.hostname;
+  const configured = process.env.PASSKEY_ORIGINS?.split(',').map((o) => o.trim()).filter(Boolean);
+  // Behind TLS-terminating proxies (e.g. Cloud Run) the server may see `http://`, while the
+  // browser reports `https://` as the origin, so accept both for the request's own host.
+  const origins = configured?.length
+    ? configured
+    : Array.from(new Set([url.origin, `https://${url.host}`]));
+  return { rpID, rpName: RP_NAME, origins };
+}
+
+// ---------------------------------------------------------------------------------------------
+// Session helpers
+// ---------------------------------------------------------------------------------------------
+
+interface AuthSession {
+  userId: string;
+  /** Timestamp (ms) of the last sign-in or successful reauthentication. */
+  authAt: number;
+}
+
+export type ChallengePurpose = 'register' | 'signup' | 'signin' | 'reauth';
+
+export interface PendingChallenge {
+  challenge: string;
+  purpose: ChallengePurpose;
+  expiresAt: number;
+  userId?: string;
+  pendingUser?: StoredUser;
+  /** Registration via conditional create (automatic passkey upgrade); user verification not performed. */
+  conditional?: boolean;
+}
+
+export async function getAuth(session: Session | undefined): Promise<{ user: StoredUser; authAt: number } | null> {
+  if (!session) return null;
+  const auth = (await session.get('auth')) as AuthSession | undefined;
+  if (!auth?.userId) return null;
+  const user = await findUserById(auth.userId);
+  if (!user) {
+    session.delete('auth');
+    return null;
+  }
+  return { user, authAt: auth.authAt };
+}
+
+export async function signIn(session: Session, user: StoredUser) {
+  // Rotate the session ID on privilege change to prevent session fixation.
+  await session.regenerate();
+  session.set('auth', { userId: user.id, authAt: Date.now() } satisfies AuthSession);
+  session.delete('webauthnChallenge');
+}
+
+export async function markReauthenticated(session: Session, user: StoredUser) {
+  session.set('auth', { userId: user.id, authAt: Date.now() } satisfies AuthSession);
+}
+
+export function signOut(session: Session) {
+  session.destroy();
+}
+
+export function isRecentAuth(authAt: number) {
+  return Date.now() - authAt < REAUTH_WINDOW_MS;
+}
+
+export const reauthRequired = () =>
+  apiError('reauth_required', 'Please confirm it’s you to continue.', 401);
+
+export const notSignedIn = () => apiError('not_signed_in', 'You need to sign in first.', 401);
+
+export function saveChallenge(session: Session, challenge: Omit<PendingChallenge, 'expiresAt'>) {
+  session.set('webauthnChallenge', { ...challenge, expiresAt: Date.now() + CHALLENGE_TTL_MS } satisfies PendingChallenge);
+}
+
+/** Read and clear the pending challenge. Challenges are single-use. */
+export async function consumeChallenge(session: Session, purposes: ChallengePurpose[]) {
+  const pending = (await session.get('webauthnChallenge')) as PendingChallenge | undefined;
+  session.delete('webauthnChallenge');
+  if (!pending || !purposes.includes(pending.purpose) || pending.expiresAt < Date.now()) return null;
+  return pending;
+}
+
+// ---------------------------------------------------------------------------------------------
+// Passkey provider metadata (friendly names + icons by AAGUID)
+// ---------------------------------------------------------------------------------------------
+
+/** Fallback names for common passkey providers, used when the convenience MDS is unreachable. */
+const KNOWN_PROVIDERS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'b5397666-4885-aa6b-cebf-e52262a439a2': 'Chromium Browser',
+  '771b48fd-d3d4-4f74-9232-fc157ab0507a': 'Edge on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  '50726f74-6f6e-5061-7373-50726f746f6e': 'Proton Pass',
+  'f3809540-7f14-49c1-a8b3-8f813b225541': 'Enpass',
+  'fdb141b2-5d84-443e-8a35-4698c205a502': 'KeePassXC',
+};
+
+let metadataReady: Promise<boolean> | null = null;
+
+function initProviderMetadata() {
+  if (process.env.PASSKEY_PROVIDER_METADATA === 'off') return Promise.resolve(false);
+  metadataReady ??= Promise.race([
+    ConvenienceMetadataService.initialize().then(() => true),
+    new Promise<boolean>((resolve) => setTimeout(() => resolve(false), 4000)),
+  ]).catch((err) => {
+    console.warn('[passkeys] Could not load passkey provider metadata; using built-in names.', err);
+    return false;
+  });
+  return metadataReady;
+}
+
+export interface ProviderInfo {
+  name: string | null;
+  icon: string | null;
+  iconDark: string | null;
+}
+
+export async function getProviderInfo(aaguid: string): Promise<ProviderInfo> {
+  const fallback = KNOWN_PROVIDERS[aaguid] ?? null;
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return { name: null, icon: null, iconDark: null };
+  }
+  try {
+    if (await initProviderMetadata()) {
+      const meta = await ConvenienceMetadataService.getProviderMetadata(aaguid);
+      if (meta) {
+        const names = meta.friendlyNames ?? {};
+        const name = names['en-US'] ?? names.en ?? Object.values(names)[0] ?? fallback;
+        return { name: name ?? null, icon: meta.icon ?? null, iconDark: meta.iconDark ?? null };
+      }
+    }
+  } catch {
+    // Fall through to built-in names.
+  }
+  return { name: fallback, icon: null, iconDark: null };
+}
+
+export async function defaultPasskeyName(aaguid: string, existing: StoredPasskey[]) {
+  const { name } = await getProviderInfo(aaguid);
+  const base = name ?? 'Passkey';
+  const taken = new Set(existing.map((p) => p.name));
+  if (!taken.has(base)) return base;
+  let n = 2;
+  while (taken.has(`${base} (${n})`)) n++;
+  return `${base} (${n})`;
+}
+
+// ---------------------------------------------------------------------------------------------
+// Serialization for the client
+// ---------------------------------------------------------------------------------------------
+
+export async function serializePasskey(p: StoredPasskey) {
+  const provider = await getProviderInfo(p.aaguid);
+  return {
+    id: p.id,
+    name: p.name,
+    providerName: provider.name,
+    providerIcon: provider.icon,
+    providerIconDark: provider.iconDark,
+    synced: p.backedUp,
+    deviceType: p.deviceType,
+    transports: p.transports,
+    createdAt: p.createdAt,
+    lastUsedAt: p.lastUsedAt,
+  };
+}
+
+export async function sessionPayload(session: Session | undefined, url: URL) {
+  const auth = await getAuth(session);
+  const { rpID } = getRelyingParty(url);
+  if (!auth) return { user: null, rpID };
+  const passkeys = await listPasskeys(auth.user.id);
+  return {
+    rpID,
+    user: {
+      id: auth.user.id,
+      username: auth.user.username,
+      displayName: auth.user.displayName,
+      hasPassword: auth.user.hasPassword,
+      passkeyCount: passkeys.length,
+    },
+    reauthUntil: auth.authAt + REAUTH_WINDOW_MS,
+  };
+}
+
