+++ b/src/lib/server/upstream.ts
@@ -0,0 +1,38 @@
+import { UPSTREAM_AUTH_API } from './auth';
+
+export interface UpstreamResult {
+  ok: boolean;
+  status: number;
+  /** Error code/message reported by the upstream API, if any (e.g. `APP_ERR_2001`). */
+  error?: string;
+}
+
+/** Verify or create a username/password account with the upstream Times auth API. */
+export async function callUpstreamAuth(
+  action: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<UpstreamResult> {
+  try {
+    const response = await fetch(`${UPSTREAM_AUTH_API}/${action}`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+      signal: AbortSignal.timeout(10_000),
+    });
+    let data: any = null;
+    try {
+      data = await response.json();
+    } catch {
+      // Non-JSON response.
+    }
+    return {
+      ok: response.ok,
+      status: response.status,
+      error: response.ok ? undefined : String(data?.error ?? data?.message ?? 'Unknown error'),
+    };
+  } catch (err) {
+    console.error(`[auth] Upstream ${action} request failed`, err);
+    return { ok: false, status: 502, error: 'UPSTREAM_UNAVAILABLE' };
+  }
+}
