@@ -0,0 +1,41 @@
+import type { APIRoute } from 'astro';
+import { apiError, badRequest, json, noSession, readJson, sessionPayload, signIn } from '../../../lib/server/auth';
+import { createUser, findUserByUsername, updateUser } from '../../../lib/server/auth-store';
+import { callUpstreamAuth } from '../../../lib/server/upstream';
+
+/** Password sign-in, verified by the upstream auth API, establishing a local session. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ username?: string; password?: string }>(request);
+  if (!body) return badRequest();
+  const username = String(body.username ?? '').trim();
+  const password = String(body.password ?? '');
+  if (!username || !password) return apiError('missing_fields', 'Enter your username and password.');
+
+  const existing = await findUserByUsername(username);
+  // Passkey-only accounts have no upstream password; never let an upstream account with the same
+  // name sign into them.
+  if (existing && !existing.hasPassword) {
+    return apiError('use_passkey', 'This account uses a passkey to sign in. Use “Sign in with a passkey” instead.', 401);
+  }
+
+  const result = await callUpstreamAuth('login', username, password);
+  if (!result.ok) {
+    return apiError('login_failed', `Login failed: ${result.error}`, result.status >= 500 ? 502 : 401);
+  }
+
+  let user = existing;
+  if (!user) {
+    try {
+      user = await createUser({ username, hasPassword: true });
+    } catch {
+      user = await findUserByUsername(username);
+      if (!user?.hasPassword) return apiError('login_failed', 'Login failed. Please try again.', 409);
+    }
+  } else if (!user.hasPassword) {
+    user = (await updateUser(user.id, { hasPassword: true })) ?? user;
+  }
+
+  await signIn(session, user);
+  return json(await sessionPayload(session, url));
+};
