@@ -0,0 +1,46 @@
+import type { APIRoute } from 'astro';
+import {
+  apiError, badRequest, getAuth, isRecentAuth, json, noSession, notSignedIn, readJson, reauthRequired,
+  serializePasskey, sessionPayload,
+} from '../../../../lib/server/auth';
+import { deletePasskey, listPasskeys, updatePasskey } from '../../../../lib/server/auth-store';
+
+/** Rename a passkey. */
+export const PATCH: APIRoute = async ({ params, request, session }) => {
+  if (!session) return noSession();
+  const auth = await getAuth(session);
+  if (!auth) return notSignedIn();
+  const body = await readJson<{ name?: string }>(request);
+  if (!body) return badRequest();
+  const name = String(body.name ?? '').trim().replace(/\s+/g, ' ');
+  if (!name || name.length > 64) return apiError('invalid_name', 'Passkey names must be 1–64 characters.');
+
+  const updated = await updatePasskey(params.id!, auth.user.id, { name });
+  if (!updated) return apiError('not_found', 'Passkey not found.', 404);
+  return json({ passkey: await serializePasskey(updated) });
+};
+
+/** Remove a passkey. Requires a recent sign-in or reauthentication. */
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  if (!session) return noSession();
+  const auth = await getAuth(session);
+  if (!auth) return notSignedIn();
+  if (!isRecentAuth(auth.authAt)) return reauthRequired();
+
+  const passkeys = await listPasskeys(auth.user.id);
+  if (!passkeys.some((p) => p.id === params.id)) return apiError('not_found', 'Passkey not found.', 404);
+  if (passkeys.length === 1 && !auth.user.hasPassword) {
+    return apiError(
+      'last_sign_in_method',
+      'This is the only way to sign in to your account. Create another passkey before removing this one.',
+      409,
+    );
+  }
+
+  await deletePasskey(params.id!, auth.user.id);
+  const remaining = await listPasskeys(auth.user.id);
+  return json({
+    passkeys: await Promise.all(remaining.map(serializePasskey)),
+    session: await sessionPayload(session, url),
+  });
+};
diff --git a/src/pages/api/auth/passkeys/authentication-options.ts b/src/pages/api/auth/passkeys/authentication-options.ts
