@@ -0,0 +1,40 @@
+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import {
+  apiError, badRequest, getAuth, getRelyingParty, json, noSession, notSignedIn, readJson, saveChallenge,
+} from '../../../../lib/server/auth';
+import { listPasskeys } from '../../../../lib/server/auth-store';
+
+/**
+ * Creates passkey authentication options.
+ *
+ * - `purpose: "signin"` (default): discoverable-credential sign-in (button or autofill).
+ * - `purpose: "reauth"`: confirm the signed-in user, restricted to their own passkeys.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ purpose?: string }>(request);
+  if (!body) return badRequest();
+  const purpose = body.purpose === 'reauth' ? 'reauth' : 'signin';
+  const { rpID } = getRelyingParty(url);
+
+  let allowCredentials: { id: string; transports?: string[] }[] = [];
+  let userId: string | undefined;
+  if (purpose === 'reauth') {
+    const auth = await getAuth(session);
+    if (!auth) return notSignedIn();
+    const passkeys = await listPasskeys(auth.user.id);
+    if (passkeys.length === 0) return apiError('no_passkeys', 'This account doesn’t have any passkeys yet.');
+    allowCredentials = passkeys.map((p) => ({ id: p.id, transports: p.transports }));
+    userId = auth.user.id;
+  }
+
+  const options = await generateAuthenticationOptions({
+    rpID,
+    allowCredentials,
+    userVerification: 'required',
+  });
+
+  saveChallenge(session, { challenge: options.challenge, purpose, userId });
+  return json(options);
+};
diff --git a/src/pages/api/auth/passkeys/authentication-verify.ts b/src/pages/api/auth/passkeys/authentication-verify.ts
new file mode 100644
index 0000000..8bf491c
--- /dev/null
+++ b/src/pages/api/auth/passkeys/authentication-verify.ts
@@ -0,0 +1,82 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse, type AuthenticationResponseJSON } from '@simplewebauthn/server';
+import {
+  apiError, badRequest, consumeChallenge, getAuth, getRelyingParty, json, markReauthenticated, noSession, readJson,
+  sessionPayload, signIn,
+} from '../../../../lib/server/auth';
+import { findPasskey, findUserById, updatePasskey } from '../../../../lib/server/auth-store';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ response?: AuthenticationResponseJSON }>(request);
+  if (!body?.response?.id) return badRequest();
+  const { rpID, origins } = getRelyingParty(url);
+
+  const pending = await consumeChallenge(session, ['signin', 'reauth']);
+  if (!pending) return apiError('challenge_expired', 'That request expired. Please try again.', 400);
+
+  const passkey = await findPasskey(body.response.id);
+  if (!passkey) {
+    // The client uses this to signal the browser/password manager to hide the stale passkey.
+    return json(
+      {
+        error: { code: 'unknown_credential', message: 'This passkey isn’t registered with The DevTools Times anymore. It may have been removed.' },
+        rpID,
+        credentialID: body.response.id,
+      },
+      404,
+    );
+  }
+
+  const userHandle = body.response.response.userHandle;
+  if (userHandle && userHandle !== passkey.userId) {
+    return apiError('verification_failed', 'We couldn’t verify that passkey.', 400);
+  }
+
+  const user = await findUserById(passkey.userId);
+  if (!user) return apiError('verification_failed', 'We couldn’t verify that passkey.', 400);
+
+  let auth = null;
+  if (pending.purpose === 'reauth') {
+    auth = await getAuth(session);
+    if (!auth || auth.user.id !== pending.userId || passkey.userId !== auth.user.id) {
+      return apiError('wrong_account', 'That passkey belongs to a different account.', 403);
+    }
+  }
+
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response: body.response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      credential: {
+        id: passkey.id,
+        publicKey: new Uint8Array(Buffer.from(passkey.publicKey, 'base64url')),
+        counter: passkey.counter,
+        transports: passkey.transports,
+      },
+      requireUserVerification: true,
+    });
+  } catch (err) {
+    console.warn('[passkeys] Authentication verification failed', err);
+    return apiError('verification_failed', 'We couldn’t verify that passkey. Please try again.', 400);
+  }
+  if (!verification.verified) {
+    return apiError('verification_failed', 'We couldn’t verify that passkey. Please try again.', 400);
+  }
+
+  const info = verification.authenticationInfo;
+  await updatePasskey(passkey.id, user.id, {
+    counter: info.newCounter,
+    lastUsedAt: new Date().toISOString(),
+    backedUp: info.credentialBackedUp,
+    deviceType: info.credentialDeviceType,
+  });
+
+  if (pending.purpose === 'reauth') await markReauthenticated(session, user);
+  else await signIn(session, user);
+
+  return json(await sessionPayload(session, url));
+};
