new file mode 100644
index 0000000..1f8a7fd
--- /dev/null
+++ b/src/pages/api/auth/passkeys/registration-options.ts
@@ -0,0 +1,84 @@
+import type { APIRoute } from 'astro';
+import { randomBytes } from 'node:crypto';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import {
+  apiError, badRequest, getAuth, getRelyingParty, isRecentAuth, json, noSession, readJson, reauthRequired, saveChallenge,
+} from '../../../../lib/server/auth';
+import { findUserByUsername, listPasskeys, type StoredUser } from '../../../../lib/server/auth-store';
+
+const USERNAME_PATTERN = /^[A-Za-z0-9._@+-]{3,64}$/;
+
+/**
+ * Creates passkey registration options.
+ *
+ * - Signed in: adds a passkey to the current account (requires a recent sign-in/reauth).
+ *   `conditional: true` requests options for automatic passkey upgrades (conditional create)
+ *   right after a password sign-in.
+ * - Signed out: starts a passkey-only sign-up for `username`.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ username?: string; displayName?: string; conditional?: boolean }>(request);
+  if (!body) return badRequest();
+  const { rpID, rpName } = getRelyingParty(url);
+  const auth = await getAuth(session);
+
+  let user: StoredUser;
+  let purpose: 'register' | 'signup';
+  let excludeCredentials: { id: string; transports?: string[] }[] = [];
+  const conditional = Boolean(body.conditional) && Boolean(auth);
+
+  if (auth) {
+    if (!isRecentAuth(auth.authAt)) return reauthRequired();
+    user = auth.user;
+    purpose = 'register';
+    excludeCredentials = (await listPasskeys(user.id)).map((p) => ({ id: p.id, transports: p.transports }));
+  } else {
+    const username = String(body.username ?? '').trim();
+    if (!USERNAME_PATTERN.test(username)) {
+      return apiError(
+        'invalid_username',
+        'Usernames must be 3–64 characters: letters, numbers, and . _ @ + - only.',
+      );
+    }
+    if (await findUserByUsername(username)) {
+      return apiError('username_taken', 'That username is already taken. Sign in instead?', 409);
+    }
+    const displayName = String(body.displayName ?? '').trim().slice(0, 64) || username;
+    user = {
+      id: randomBytes(32).toString('base64url'),
+      username,
+      displayName,
+      hasPassword: false,
+      createdAt: new Date().toISOString(),
+    };
+    purpose = 'signup';
+  }
+
+  const options = await generateRegistrationOptions({
+    rpName,
+    rpID,
+    userID: new Uint8Array(Buffer.from(user.id, 'base64url')),
+    userName: user.username,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials,
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+    },
+    // Ask for credProps so we know whether a discoverable credential was created.
+    extensions: { credProps: true } as any,
+  });
+
+  saveChallenge(session, {
+    challenge: options.challenge,
+    purpose,
+    userId: user.id,
+    pendingUser: purpose === 'signup' ? user : undefined,
+    conditional,
+  });
+
+  return json(options);
+};
diff --git a/src/pages/api/auth/passkeys/registration-verify.ts b/src/pages/api/auth/passkeys/registration-verify.ts
new file mode 100644
index 0000000..f24643c
--- /dev/null
+++ b/src/pages/api/auth/passkeys/registration-verify.ts
@@ -0,0 +1,82 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse, type RegistrationResponseJSON } from '@simplewebauthn/server';
+import {
+  apiError, badRequest, consumeChallenge, defaultPasskeyName, getAuth, getRelyingParty, json, noSession, readJson,
+  serializePasskey, sessionPayload, signIn,
+} from '../../../../lib/server/auth';
+import {
+  addPasskey, createUserWithPasskey, listPasskeys, type StoredPasskey,
+} from '../../../../lib/server/auth-store';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ response?: RegistrationResponseJSON }>(request);
+  if (!body?.response) return badRequest();
+
+  const pending = await consumeChallenge(session, ['register', 'signup']);
+  if (!pending) return apiError('challenge_expired', 'That request expired. Please try again.', 400);
+
+  const auth = await getAuth(session);
+  if (pending.purpose === 'register' && (!auth || auth.user.id !== pending.userId)) {
+    return apiError('not_signed_in', 'You need to sign in first.', 401);
+  }
+  if (pending.purpose === 'signup' && auth) {
+    return apiError('already_signed_in', 'You’re already signed in.', 400);
+  }
+
+  const { rpID, origins } = getRelyingParty(url);
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response: body.response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      // Conditional (automatic) creation happens without user verification by design.
+      requireUserVerification: !pending.conditional,
+    });
+  } catch (err: any) {
+    console.warn('[passkeys] Registration verification failed', err);
+    return apiError('verification_failed', 'We couldn’t verify that passkey. Please try again.', 400);
+  }
+  if (!verification.verified) {
+    return apiError('verification_failed', 'We couldn’t verify that passkey. Please try again.', 400);
+  }
+
+  const info = verification.registrationInfo;
+  const userId = pending.userId!;
+  const existing = pending.purpose === 'register' ? await listPasskeys(userId) : [];
+  const now = new Date().toISOString();
+  const passkey: StoredPasskey = {
+    id: info.credential.id,
+    userId,
+    publicKey: Buffer.from(info.credential.publicKey).toString('base64url'),
+    counter: info.credential.counter,
+    transports: info.credential.transports ?? body.response.response.transports ?? [],
+    aaguid: info.aaguid,
+    name: await defaultPasskeyName(info.aaguid, existing),
+    deviceType: info.credentialDeviceType,
+    backedUp: info.credentialBackedUp,
+    createdAt: now,
+    lastUsedAt: null,
+  };
+
+  try {
+    if (pending.purpose === 'signup') {
+      const user = await createUserWithPasskey(pending.pendingUser!, passkey);
+      await signIn(session, user);
+    } else {
+      await addPasskey(passkey);
+    }
+  } catch (err: any) {
+    if (err?.message === 'USERNAME_TAKEN') {
+      return apiError('username_taken', 'That username was just taken. Please choose another.', 409);
+    }
+    if (err?.message === 'CREDENTIAL_EXISTS') {
+      return apiError('credential_exists', 'This passkey is already registered.', 409);
+    }
+    throw err;
+  }
+
+  return json({ passkey: await serializePasskey(passkey), session: await sessionPayload(session, url) });
+};
diff --git a/src/pages/api/auth/reauth-password.ts b/src/pages/api/auth/reauth-password.ts
