@@ -0,0 +1,24 @@
+import type { APIRoute } from 'astro';
+import {
+  apiError, badRequest, getAuth, json, markReauthenticated, noSession, notSignedIn, readJson, sessionPayload,
+} from '../../../lib/server/auth';
+import { callUpstreamAuth } from '../../../lib/server/upstream';
+
+/** Reauthenticate the signed-in user with their password before a sensitive action. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const auth = await getAuth(session);
+  if (!auth) return notSignedIn();
+  if (!auth.user.hasPassword) return apiError('no_password', 'This account doesn’t have a password. Use a passkey instead.');
+
+  const body = await readJson<{ password?: string }>(request);
+  if (!body) return badRequest();
+  const password = String(body.password ?? '');
+  if (!password) return apiError('missing_fields', 'Enter your password.');
+
+  const result = await callUpstreamAuth('login', auth.user.username, password);
+  if (!result.ok) return apiError('reauth_failed', 'That password isn’t right. Try again.', 401);
+
+  await markReauthenticated(session, auth.user);
+  return json(await sessionPayload(session, url));
+};
diff --git a/src/pages/api/auth/register.ts b/src/pages/api/auth/register.ts
new file mode 100644
index 0000000..4976546
--- /dev/null
+++ b/src/pages/api/auth/register.ts
@@ -0,0 +1,33 @@
+import type { APIRoute } from 'astro';
+import { apiError, badRequest, json, noSession, readJson, sessionPayload, signIn } from '../../../lib/server/auth';
+import { createUser, findUserByUsername } from '../../../lib/server/auth-store';
+import { callUpstreamAuth } from '../../../lib/server/upstream';
+
+/** Password sign-up via the upstream auth API; the new user is signed in immediately. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return noSession();
+  const body = await readJson<{ username?: string; password?: string }>(request);
+  if (!body) return badRequest();
+  const username = String(body.username ?? '').trim();
+  const password = String(body.password ?? '');
+  if (!username || !password) return apiError('missing_fields', 'Enter a username and password.');
+
+  if (await findUserByUsername(username)) {
+    return apiError('username_taken', 'That username is already taken.', 409);
+  }
+
+  const result = await callUpstreamAuth('register', username, password);
+  if (!result.ok) {
+    return apiError('registration_failed', `Registration failed: ${result.error}`, result.status >= 500 ? 502 : 400);
+  }
+
