--- /dev/null
+++ b/components/drink-card.js
@@ -0,0 +1,116 @@
+/**
+ * <drink-card> — a server-rendered (Declarative Shadow DOM) drink card.
+ *
+ * The markup and styles arrive in the HTML inside
+ * <template shadowrootmode="open">, so the browser paints a fully styled
+ * card before this script ever runs. This class only *hydrates* the
+ * existing shadow root: it never replaces innerHTML, it just looks up the
+ * pre-rendered favorite button and wires up behavior + persisted state.
+ */
+const STORAGE_KEY = 'daily-grind:favorites';
+
+function readFavorites() {
+  try {
+    return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'));
+  } catch {
+    return new Set();
+  }
+}
+
+function writeFavorites(set) {
+  try {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...set]));
+  } catch {
+    /* storage unavailable (private mode, quota) — keep in-memory state only */
+  }
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['favorite'];
+
+  #button = null;
+  #onClick = () => this.toggleFavorite();
+
+  constructor() {
+    super();
+    // Browsers with Declarative Shadow DOM have already attached the root.
+    // For older browsers, promote the server-rendered template manually
+    // (still reusing the server markup rather than building our own).
+    if (!this.shadowRoot) {
+      const tpl = this.querySelector(':scope > template[shadowrootmode]');
+      if (tpl) {
+        this.attachShadow({ mode: tpl.getAttribute('shadowrootmode') || 'open' })
+          .appendChild(tpl.content);
+        tpl.remove();
+      }
+    }
+  }
+
+  get drinkId() {
+    return this.getAttribute('drink-id') || '';
+  }
+
+  get favorite() {
+    return this.hasAttribute('favorite');
+  }
+
+  set favorite(value) {
+    this.toggleAttribute('favorite', Boolean(value));
+  }
+
+  connectedCallback() {
+    this.#button = this.shadowRoot?.querySelector('[data-favorite-toggle]');
+    if (!this.#button) return;
+
+    // Restore persisted state (server render defaults to "not favorite").
+    if (this.drinkId && readFavorites().has(this.drinkId)) {
+      this.favorite = true;
+    }
+    this.#sync();
+    this.#button.addEventListener('click', this.#onClick);
+    this.setAttribute('hydrated', '');
+  }
+
+  disconnectedCallback() {
+    this.#button?.removeEventListener('click', this.#onClick);
+  }
+
+  attributeChangedCallback() {
+    this.#sync();
+  }
+
+  toggleFavorite() {
+    this.favorite = !this.favorite;
+
+    if (this.drinkId) {
+      const favorites = readFavorites();
+      this.favorite ? favorites.add(this.drinkId) : favorites.delete(this.drinkId);
+      writeFavorites(favorites);
+    }
+
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { id: this.drinkId, favorite: this.favorite },
+      })
+    );
+  }
+
+  // Only touches attributes on existing nodes — no re-render.
+  #sync() {
+    const btn = this.#button;
+    if (!btn) return;
+    const name = this.getAttribute('drink-name') || 'this drink';
+    btn.setAttribute('aria-pressed', String(this.favorite));
+    btn.setAttribute(
+      'aria-label',
+      this.favorite ? `Remove ${name} from favorites` : `Add ${name} to favorites`
+    );
+    btn.title = this.favorite ? 'Remove from favorites' : 'Add to favorites';
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
