+# Production HTTP response headers for The Daily Grind.
+# Format: Netlify / Cloudflare Pages `_headers`. If you deploy elsewhere, port
+# these to your server/CDN config. Keep the CSP in sync with the <meta> fallback
+# in index.html and privacy-policy/index.html and the `start` script.
+# See PRIVACY.md for the reasoning behind each header.
+
+# --- Injection / XSS ---------------------------------------------------
+# No inline script/style and no third-party origins at all. Trusted Types is
+# enforced, and no policies are allowed ('none'): code must use textContent.
+# The report endpoint must strip PII (query strings, IPs, emails) before storage.
+# Network-layer allowlist (Chrome 152+): our own origin plus outbound link targets. This also blocks
+# dns-prefetch/preconnect/WebRTC exfiltration channels that CSP doesn't cover.
+# redirects=allow keeps same-origin POST-redirect-GET (e.g. /logout) working.
+# --- Privacy -----------------------------------------------------------
+# Disable powerful/tracking-related features we don't use, for us and any frame.
+# --- Transport & isolation --------------------------------------------
+# Rollout: start with a short max-age and raise to 31536000 once verified.
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self' 'report-sample'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; worker-src 'none'; frame-ancestors 'none'; require-trusted-types-for 'script'; trusted-types 'none'; upgrade-insecure-requests; report-to csp
+  Reporting-Endpoints: csp="/api/reports/csp"
+  Connection-Allowlist: (response-origin "https://globalprivacycontrol.org"); redirects=allow; report-to=csp
+  Referrer-Policy: strict-origin-when-cross-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), attribution-reporting=(), autoplay=(), bluetooth=(), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), focus-without-user-activation=(), geolocation=(), gyroscope=(), hid=(), idle-detection=(), join-ad-interest-group=(), local-fonts=(), magnetometer=(), microphone=(), midi=(), payment=(), private-state-token-issuance=(), private-state-token-redemption=(), run-ad-auction=(), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+  X-DNS-Prefetch-Control: off
+  Strict-Transport-Security: max-age=300; includeSubDomains
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin-allow-popups
+  Cross-Origin-Resource-Policy: same-origin
+  Origin-Agent-Cluster: ?1
+
+# Pages that may show personal data must never be stored by shared or browser caches.
+/account
+  Cache-Control: no-store
+/account/*
+  Cache-Control: no-store
+
+# Logout must wipe everything we may have left in the browser.
+# (The backend handling POST /logout must send these too.)
+/logout
+  Clear-Site-Data: "cookies", "storage", "cache"
+  Cache-Control: no-store
+
+/newsletter
+  Cache-Control: no-store
+
+/assets/*
+  Cache-Control: public, max-age=86400
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Access-Control-Allow-Origin: *
