@@ -0,0 +1,317 @@
+:root {
+  --primary: #4e342e;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+}
+
+/* Navigation */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+}
+
+.logo {
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+}
+
+nav ul {
+  display: flex;
+  list-style: none;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover {
+  color: var(--accent);
+}
+
+/* Logout is a POST form (state-changing actions must never be GET links:
+   they can be triggered by prefetchers, crawlers or cross-site <img> tags). */
+.logout-form {
+  display: inline;
+}
+
+.logout-link {
+  font: inherit;
+  font-size: 0.9rem;
+  color: white;
+  background: none;
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+  cursor: pointer;
+  transition: color 0.3s;
+}
+
+.logout-link:hover {
+  color: var(--accent);
+}
+
+/* Hero Section
+   The hero photo is self-hosted (assets/img) so viewing the page never sends
+   the visitor's IP address, User-Agent or Referer to a third-party image CDN. */
+.hero {
+  position: relative;
+  isolation: isolate;
+  min-height: 60vh;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+  background: var(--primary);
+}
+
+.hero-img {
+  position: absolute;
+  inset: 0;
+  z-index: -1;
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  filter: brightness(0.5);
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+}
+
+/* Content Sections */
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: white;
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+  text-align: center;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--primary);
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+.section-title {
+  text-align: center;
+}
+
+a:focus-visible,
+button:focus-visible,
+input:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 2px;
+}
+
+/* Newsletter (data-minimised: email only) */
+.newsletter {
+  max-width: 560px;
+  margin: 60px auto 0;
+  background: white;
+  padding: 24px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+}
+
+.newsletter h2 {
+  color: var(--primary);
+  margin-bottom: 0.5rem;
+}
+
+.field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.25rem;
+  margin-block: 1rem 1.5rem;
+}
+
+.field input {
+  font: inherit;
+  font-size: max(1rem, 1em);
+  padding: 0.75rem;
+  min-height: 48px;
+  border: 1px solid #767676;
+  border-radius: 4px;
+}
+
+.field input:user-invalid {
+  border-color: #b3261e;
+  border-width: 2px;
+}
+
+.hint {
+  font-size: 0.85rem;
+  color: #5d4037;
+}
+
+.error {
+  font-size: 0.9rem;
+  color: #b3261e;
+  font-weight: 600;
+}
+
+.error:empty {
+  display: none;
+}
+
+.newsletter button[type="submit"] {
+  font: inherit;
+  border: 0;
+  cursor: pointer;
+  min-height: 48px;
+}
+
+.newsletter button[disabled] {
+  opacity: 0.7;
+  cursor: progress;
+}
+
+.form-status {
+  margin-top: 1rem;
+  font-weight: 600;
+}
+
+.form-status:empty {
+  display: none;
+}
+
+/* Honeypot: invisible to people and assistive tech; bots tend to fill it. */
+.hp {
+  position: absolute;
+  clip-path: inset(50%);
+  overflow: hidden;
+  width: 1px;
+  height: 1px;
+  margin: -1px;
+  padding: 0;
+  border: 0;
+  white-space: nowrap;
+}
+
+.privacy-note {
+  font-size: 0.8rem;
+  margin-top: 0.5rem;
+}
+
+.privacy-note:empty {
+  display: none;
+}
+
+/* Privacy policy page */
+.policy {
+  max-width: 800px;
+}
+
+.policy h1,
+.policy h2 {
+  color: var(--primary);
+  margin-block: 1.5rem 0.5rem;
+}
+
+.policy p,
+.policy ul {
+  margin-bottom: 1rem;
+}
+
+.policy ul {
+  padding-inline-start: 1.5rem;
+}
+
+.policy table {
+  width: 100%;
+  border-collapse: collapse;
+  margin-bottom: 1rem;
+  background: white;
+}
+
+.policy th,
+.policy td {
+  text-align: start;
+  padding: 0.5rem;
+  border: 1px solid var(--secondary);
+  vertical-align: top;
+}
+
+.table-scroll {
+  overflow-x: auto;
+}
