@@ -0,0 +1,113 @@
+/**
+ * The Daily Grind – client-side privacy helpers.
+ *
+ * Privacy-by-design rules this file follows (keep them when editing):
+ *  - No third-party code, no analytics, no fingerprinting, no UA sniffing
+ *    (feature-detect instead).
+ *  - Never write personal data to localStorage/sessionStorage/IndexedDB/cookies,
+ *    and never log it to the console.
+ *  - Only talk to our own origin (enforced by CSP connect-src 'self').
+ *  - Only write to the DOM with textContent (CSP enforces Trusted Types, so
+ *    innerHTML-style sinks will throw).
+ */
+
+const EMAIL_ERROR = 'Enter an email address like name@example.com.';
+
+/** Honour Global Privacy Control (https://globalprivacycontrol.org/). */
+function announceGpc() {
+  const note = document.getElementById('gpc-note');
+  if (!note || !('globalPrivacyControl' in navigator)) return;
+  if (navigator.globalPrivacyControl === true) {
+    note.textContent =
+      'Global Privacy Control detected: we honour it. We already never sell or share your data.';
+  }
+}
+
+/** Progressive enhancement for the email-only newsletter form. */
+function enhanceNewsletter() {
+  const form = document.getElementById('newsletter-form');
+  if (!(form instanceof HTMLFormElement)) return;
+
+  const email = form.elements.namedItem('email');
+  const honeypot = form.elements.namedItem('website');
+  const error = document.getElementById('newsletter-error');
+  const status = document.getElementById('newsletter-status');
+  const submit = form.querySelector('button[type="submit"]');
+  if (!(email instanceof HTMLInputElement) || !error || !status || !submit) return;
+
+  let edited = false;
+
+  const showError = () => {
+    const valid = email.checkValidity();
+    email.setAttribute('aria-invalid', String(!valid));
+    error.textContent = valid ? '' : EMAIL_ERROR;
+    return valid;
+  };
+
+  const clearError = () => {
+    email.removeAttribute('aria-invalid');
+    error.textContent = '';
+  };
+
+  // Validate when the user leaves the field (if they typed), clear while typing.
+  email.addEventListener('input', () => {
+    edited = true;
+    if (email.validity.valid) clearError();
+  });
+  email.addEventListener('blur', () => {
+    if (edited) showError();
+  });
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    status.textContent = '';
+
+    // Normalise before validating so we never store accidental whitespace.
+    email.value = email.value.trim();
+    if (!showError()) {
+      email.focus();
+      return;
+    }
+
+    // Bots fill hidden fields: pretend success, send nothing.
+    if (honeypot instanceof HTMLInputElement && honeypot.value !== '') {
+      form.reset();
+      status.textContent = 'Thanks! Check your inbox to confirm your subscription.';
+      return;
+    }
+
+    submit.disabled = true;
+    try {
+      const response = await fetch(form.action, {
+        method: 'POST',
+        // Send only the fields the server needs (email + CSRF token).
+        body: new URLSearchParams({
+          email: email.value,
+          csrf_token: form.elements.namedItem('csrf_token')?.value ?? '',
+        }),
+        credentials: 'same-origin',
+        cache: 'no-store',
+        referrerPolicy: 'no-referrer',
+        headers: { Accept: 'application/json' },
+      });
+      if (!response.ok) throw new Error(`HTTP ${response.status}`);
+
+      // Drop the address from the page as soon as it has been handed off.
+      form.reset();
+      edited = false;
+      clearError();
+      status.textContent = 'Thanks! Check your inbox to confirm your subscription.';
+    } catch {
+      // Deliberately generic: don't echo server errors or the address back.
+      status.textContent = "Sorry, we couldn't subscribe you right now. Please try again later.";
+    } finally {
+      submit.disabled = false;
+    }
+  });
+
+  // Don't keep typed personal data around in the back/forward cache.
+  window.addEventListener('pagehide', () => form.reset());
+}
+
+announceGpc();
+enhanceNewsletter();
