+# HTTP security & privacy headers (Netlify / Cloudflare Pages `_headers` format).
+# If you deploy elsewhere (nginx, Express, CDN), set the same headers there.
+# The CSP must match the <meta http-equiv="Content-Security-Policy"> in index.html.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; manifest-src 'self'; frame-ancestors 'none'; upgrade-insecure-requests
+  Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
+  Referrer-Policy: strict-origin-when-cross-origin
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Resource-Policy: same-origin
+  Cross-Origin-Embedder-Policy: require-corp
+  Origin-Agent-Cluster: ?1
+  X-DNS-Prefetch-Control: off
+  X-Permitted-Cross-Domain-Policies: none
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), battery=(), bluetooth=(), browsing-topics=(), camera=(), display-capture=(), document-domain=(), encrypted-media=(), geolocation=(), gyroscope=(), hid=(), identity-credentials-get=(), idle-detection=(), interest-cohort=(), local-fonts=(), magnetometer=(), microphone=(), midi=(), otp-credentials=(), payment=(), publickey-credentials-get=(self), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+
+# Per-page feature grants. Netlify/Cloudflare append these to the /* value above;
+# Permissions-Policy is a structured-field dictionary, so the later key wins.
+#
+# The store finder may ask for location, but only on that page, only first-party,
+# and only after the user clicks "Find stores near me" (never on page load).
+/locations*
+  Permissions-Policy: geolocation=(self)
+
+# Checkout needs the Payment Request API (first-party only).
+/order-online*
+  Permissions-Policy: payment=(self)
+  Cache-Control: no-store, private
+
+# Personal data must never land in shared/proxy caches or the bfcache.
+/account*
+  Cache-Control: no-store, private
+  X-Robots-Tag: noindex, nofollow, noarchive
+
+/rewards*
+  Cache-Control: no-store, private
+  X-Robots-Tag: noindex, nofollow, noarchive
+
+# Logout wipes everything this origin stored in the browser.
+/logout
+  Cache-Control: no-store
+  Clear-Site-Data: "cache", "cookies", "storage"
+
+/index.html
+  Cache-Control: no-cache
+
+/
+  Cache-Control: no-cache
+
+/assets/*
+  Cache-Control: public, max-age=604800
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Access-Control-Allow-Origin: *
+  Cross-Origin-Resource-Policy: cross-origin
