+/*
+ * The Daily Grind – client-side privacy helpers.
+ *
+ * Design rules for this file (and any script added to the site):
+ *   - No network requests. Nothing here phones home, ever.
+ *   - No cookies, no fingerprinting, no persistent identifiers.
+ *   - Only touches data the user already has in their own browser.
+ */
+(function () {
+  'use strict';
+
+  // Query parameters that sometimes carry personal data in from email
+  // campaigns, password-reset links, or third-party redirects. Stripping them
+  // keeps them out of browser history, bookmarks, screenshots, and the
+  // Referer header sent with any later navigation.
+  var SENSITIVE_PARAMS = [
+    'email', 'e', 'name', 'first_name', 'last_name', 'phone', 'token',
+    'auth', 'session', 'sid', 'code', 'password',
+    // Cross-site click/ad trackers – we don't use them, so don't keep them.
+    'gclid', 'dclid', 'fbclid', 'msclkid', 'mc_eid', 'mc_cid', '_hsenc',
+    '_hsmi', 'igshid', 'yclid', 'twclid', 'ttclid', 'li_fat_id'
+  ];
+
+  // Keys an app on this origin might put in Web Storage. Cleared on logout so
+  // nothing about the account is left on a shared device.
+  var STORAGE_PREFIX = 'dg:';
+
+  function stripSensitiveParams() {
+    if (!window.URL || !window.history || !history.replaceState) return;
+    var url;
+    try { url = new URL(window.location.href); } catch (e) { return; }
+
+    var changed = false;
+    SENSITIVE_PARAMS.forEach(function (p) {
+      if (url.searchParams.has(p)) { url.searchParams.delete(p); changed = true; }
+    });
+    // utm_* is campaign info, not personal data, but there's no reason to keep it.
+    Array.from(url.searchParams.keys()).forEach(function (k) {
+      if (k.indexOf('utm_') === 0) { url.searchParams.delete(k); changed = true; }
+    });
+
+    if (changed) history.replaceState(history.state, '', url.pathname + url.search + url.hash);
+  }
+
+  function privacySignalEnabled() {
+    // Global Privacy Control (legally binding opt-out in e.g. California/Colorado).
+    if (navigator.globalPrivacyControl === true) return true;
+    // Legacy Do Not Track – no legal weight, but we treat it the same way.
+    var dnt = navigator.doNotTrack || window.doNotTrack || navigator.msDoNotTrack;
+    return dnt === '1' || dnt === 'yes';
+  }
+
+  function reflectPrivacySignal() {
+    if (!privacySignalEnabled()) return;
+    document.documentElement.setAttribute('data-privacy-signal', 'on');
+    var notice = document.getElementById('privacy-signal');
+    if (notice) notice.hidden = false;
+  }
+
+  function clearLocalData() {
+    [window.localStorage, window.sessionStorage].forEach(function (store) {
+      try {
+        if (!store) return;
+        for (var i = store.length - 1; i >= 0; i--) {
+          var key = store.key(i);
+          if (key && key.indexOf(STORAGE_PREFIX) === 0) store.removeItem(key);
+        }
+      } catch (e) { /* storage disabled or blocked – nothing to clear */ }
+    });
+  }
+
+  function hardenOutboundLinks() {
+    // Any link to another origin: don't leak window.opener or the full URL.
+    Array.prototype.forEach.call(document.querySelectorAll('a[href]'), function (a) {
+      if (a.origin && a.origin !== window.location.origin) {
+        var rel = (a.getAttribute('rel') || '').split(/\s+/).filter(Boolean);
+        ['noopener', 'noreferrer'].forEach(function (r) {
+          if (rel.indexOf(r) === -1) rel.push(r);
+        });
+        a.setAttribute('rel', rel.join(' '));
+      }
+    });
+  }
+
+  function wireLogout() {
+    Array.prototype.forEach.call(
+      document.querySelectorAll('form[data-clear-local-data]'),
+      function (form) { form.addEventListener('submit', clearLocalData); }
+    );
+  }
+
+  // Pages restored from the back/forward cache after logout could show account
+  // details on a shared computer; force a fresh load so the server decides.
+  window.addEventListener('pageshow', function (event) {
+    if (event.persisted && document.documentElement.hasAttribute('data-requires-auth')) {
+      window.location.reload();
+    }
+  });
+
+  stripSensitiveParams();
+
+  function init() {
+    reflectPrivacySignal();
+    hardenOutboundLinks();
+    wireLogout();
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+
+  // Expose a tiny read-only API so future features can respect the signal.
+  window.DailyGrindPrivacy = Object.freeze({
+    signalEnabled: privacySignalEnabled,
+    clearLocalData: clearLocalData
+  });
+})();
