@@ -0,0 +1,77 @@
+#!/usr/bin/env node
+// Privacy audit: fails if the site loads anything from a third party, ships
+// known tracker code, uses inline script/style (which would force a weaker
+// CSP), or if the meta CSP and the _headers CSP drift apart.
+//
+// Usage: node scripts/privacy-audit.mjs   (or: pnpm run audit:privacy)
+import { readFileSync, readdirSync, statSync } from 'node:fs';
+import { join, extname, relative } from 'node:path';
+
+const ROOT = new URL('..', import.meta.url).pathname;
+const SCAN_EXT = new Set(['.html', '.css', '.js', '.mjs', '.json', '.svg']);
+const SKIP_DIRS = new Set(['node_modules', '.git', 'scripts']);
+
+// Third-party origins that are explicitly approved. Keep this empty unless a
+// vendor has passed review (DPA signed, data flow documented in PRIVACY.md).
+const ALLOWED_ORIGINS = new Set([]);
+
+const TRACKER_PATTERNS = [
+  /google-analytics\.com|googletagmanager\.com|gtag\(|ga\(\s*['"]create/i,
+  /connect\.facebook\.net|fbq\(/i,
+  /doubleclick\.net|adservice\.google/i,
+  /hotjar|fullstory|mouseflow|clarity\.ms|segment\.(io|com)|mixpanel|amplitude/i,
+  /fonts\.googleapis\.com|fonts\.gstatic\.com|use\.typekit\.net/i,
+  /navigator\.(plugins|hardwareConcurrency|deviceMemory)|getChannelData|toDataURL\(/, // fingerprinting
+];
+
+const files = [];
+(function walk(dir) {
+  for (const name of readdirSync(dir)) {
+    if (SKIP_DIRS.has(name)) continue;
+    const p = join(dir, name);
+    if (statSync(p).isDirectory()) walk(p);
+    else if (SCAN_EXT.has(extname(name))) files.push(p);
+  }
+})(ROOT);
+
+const problems = [];
+const report = (file, msg) => problems.push(`${relative(ROOT, file)}: ${msg}`);
+
+for (const file of files) {
+  const src = readFileSync(file, 'utf8');
+  // Ignore comments and doc-only URLs (xmlns etc.).
+  const code = src.replace(/<!--[\s\S]*?-->/g, '').replace(/\/\*[\s\S]*?\*\//g, '');
+
+  for (const m of code.matchAll(/(?:https?:)?\/\/([a-z0-9.-]+\.[a-z]{2,})(?::\d+)?/gi)) {
+    const host = m[1].toLowerCase();
+    if (host === 'www.w3.org') continue; // XML namespaces, not fetched
+    if (!ALLOWED_ORIGINS.has(host)) report(file, `third-party reference to ${host}`);
+  }
+  for (const re of TRACKER_PATTERNS) {
+    if (re.test(code)) report(file, `matches tracker/fingerprinting pattern ${re}`);
+  }
+  if (extname(file) === '.html') {
+    if (/<script(?![^>]*\bsrc=)[^>]*>/i.test(code)) report(file, 'inline <script> (breaks script-src \'self\')');
+    if (/<style[\s>]/i.test(code)) report(file, 'inline <style> (breaks style-src \'self\')');
+    if (/\sstyle=/i.test(code)) report(file, 'inline style="" attribute');
+    if (/\son[a-z]+=/i.test(code)) report(file, 'inline event handler attribute');
+    if (/<form(?![^>]*method=["']?post)[^>]*>/i.test(code) && /type=["']?password/i.test(code))
+      report(file, 'password form not using POST');
+    if (/<a[^>]+href=["']\/logout["']/i.test(code)) report(file, 'logout via GET link (use a POST form)');
+
+    const meta = code.match(/http-equiv="Content-Security-Policy"\s+content="([^"]+)"/i);
+    if (!meta) report(file, 'missing CSP meta tag');
+    else {
+      const hdr = readFileSync(join(ROOT, '_headers'), 'utf8').match(/Content-Security-Policy:\s*(.+)/)[1];
+      const norm = (s) => s.split(';').map((d) => d.trim()).filter((d) => d && !d.startsWith('frame-ancestors')).sort().join(';');
+      if (norm(meta[1]) !== norm(hdr)) report(file, 'meta CSP differs from _headers CSP');
+    }
+    if (!/<meta[^>]+name=["']referrer["']/i.test(code)) report(file, 'missing referrer policy meta tag');
+  }
+}
+
+if (problems.length) {
+  console.error(`Privacy audit FAILED (${problems.length}):\n  - ` + problems.join('\n  - '));
+  process.exit(1);
+}
+console.log(`Privacy audit passed: ${files.length} files, 0 third-party requests, 0 trackers.`);

