diff --git a/src/components/ConsentManager.astro b/src/components/ConsentManager.astro
new file mode 100644
index 0000000..7664fc5
--- /dev/null
+++ b/src/components/ConsentManager.astro
@@ -0,0 +1,181 @@
+---
+import { ANALYTICS_SCRIPT_SRC, CONSENT_STORAGE_KEY } from '../config/privacy';
+const baseUrl = import.meta.env.BASE_URL;
+---
+
+<!--
+  Privacy by design: optional analytics is OFF by default and is only loaded
+  after an explicit opt-in. Global Privacy Control / Do Not Track signals are
+  honoured as a refusal. The choice lives in localStorage and is never sent to
+  a server. Credential pages (data-sensitive) never load third-party scripts.
+-->
+<div
+  id="privacy-consent"
+  role="dialog"
+  aria-modal="false"
+  aria-labelledby="privacy-consent-title"
+  aria-describedby="privacy-consent-desc"
+  data-analytics-src={ANALYTICS_SCRIPT_SRC}
+  data-storage-key={CONSENT_STORAGE_KEY}
+  hidden
+  class="fixed inset-x-0 bottom-0 z-[100] border-t border-gray-300 bg-white p-4 shadow-lg md:p-6"
+>
+  <div class="mx-auto flex max-w-4xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
+    <div class="text-sm text-gray-700">
+      <h2 id="privacy-consent-title" class="mb-1 text-base font-bold text-gray-900">Your privacy choices</h2>
+      <p id="privacy-consent-desc">
+        We only use what is strictly necessary to run this site. With your permission we would also
+        use <strong>optional analytics</strong>, which records the label of links and buttons you click
+        plus a timestamp, sent to our analytics provider (Google Cloud). It is off unless you turn it on,
+        and you can change your mind at any time via “Manage Privacy Preferences” in the footer.
+        <a href={`${baseUrl}legal/privacy`} class="underline">Read our Privacy Policy</a>.
+      </p>
+      <p data-gpc-notice hidden class="mt-2 text-xs text-gray-600">
+        Your browser sends a Global Privacy Control or Do Not Track signal, so analytics stays off.
+      </p>
+      <p data-status role="status" class="mt-2 text-xs text-gray-600"></p>
+    </div>
+    <div class="flex shrink-0 gap-2">
+      <button
+        type="button"
+        data-consent="reject"
+        data-skip-tracking="true"
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Reject optional
+      </button>
+      <button
+        type="button"
+        data-consent="accept"
+        data-skip-tracking="true"
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Allow analytics
+      </button>
+    </div>
+  </div>
+</div>
+
+<script>
+  type Consent = { analytics: boolean; decidedAt: string };
+
+  let analyticsLoaded = false;
+
+  function banner() {
+    return document.getElementById('privacy-consent') as HTMLElement | null;
+  }
+
+  function storageKey() {
+    return banner()?.dataset.storageKey ?? 'dtt-privacy-consent-v1';
+  }
+
+  function privacySignal(): boolean {
+    const nav = navigator as Navigator & { globalPrivacyControl?: boolean };
+    return nav.globalPrivacyControl === true || navigator.doNotTrack === '1';
+  }
+
+  function readConsent(): Consent | null {
+    try {
+      const raw = localStorage.getItem(storageKey());
+      return raw ? (JSON.parse(raw) as Consent) : null;
+    } catch {
+      return null;
+    }
+  }
+
+  function writeConsent(analytics: boolean) {
+    try {
+      const value: Consent = { analytics, decidedAt: new Date().toISOString() };
+      localStorage.setItem(storageKey(), JSON.stringify(value));
+    } catch {
+      /* storage unavailable: treat as not consented */
+    }
+  }
+
+  function isSensitivePage() {
+    return document.documentElement.hasAttribute('data-sensitive');
+  }
+
+  function analyticsAllowed() {
+    return !privacySignal() && readConsent()?.analytics === true && !isSensitivePage();
+  }
+
+  function loadAnalytics() {
+    const src = banner()?.dataset.analyticsSrc;
+    if (analyticsLoaded || !src || !analyticsAllowed()) return;
+    const script = document.createElement('script');
+    script.src = src;
+    script.async = true;
+    script.referrerPolicy = 'no-referrer';
+    document.head.appendChild(script);
+    analyticsLoaded = true;
+  }
+
+  function showBanner(status = '') {
+    const el = banner();
+    if (!el) return;
+    const signal = privacySignal();
+    el.querySelector<HTMLElement>('[data-gpc-notice]')!.hidden = !signal;
+    el.querySelector<HTMLButtonElement>('[data-consent="accept"]')!.disabled = signal;
+    el.querySelector<HTMLElement>('[data-status]')!.textContent = status;
+    el.hidden = false;
+  }
+
+  function currentStatus() {
+    if (privacySignal()) return 'Current setting: analytics off (browser privacy signal).';
+    const consent = readConsent();
+    if (!consent) return '';
+    return `Current setting: analytics ${consent.analytics ? 'on' : 'off'}.`;
+  }
+
+  function decide(analytics: boolean) {
+    const wasLoaded = analyticsLoaded;
+    writeConsent(analytics);
+    banner()!.hidden = true;
+    if (analytics) {
+      loadAnalytics();
+    } else if (wasLoaded) {
+      // A loaded third-party script can't be unloaded; reload to stop it immediately.
+      location.reload();
+    }
+  }
+
+  function init() {
+    // Never keep a third-party tracker running on a credential page, even if
+    // we arrived here through a client-side navigation.
+    if (analyticsLoaded && isSensitivePage()) {
+      location.reload();
+      return;
+    }
+
+    const el = banner();
+    if (!el) return;
+
+    el.querySelector('[data-consent="accept"]')?.addEventListener('click', () => decide(true));
+    el.querySelector('[data-consent="reject"]')?.addEventListener('click', () => decide(false));
+    document.querySelectorAll('[data-open-privacy-preferences]').forEach((trigger) =>
+      trigger.addEventListener('click', (event) => {
+        event.preventDefault();
+        showBanner(currentStatus());
+      }),
+    );
+
+    if (privacySignal()) {
+      // Respect the signal silently; no need to ask.
+      return;
+    }
+    if (readConsent() === null) {
+      showBanner();
+      return;
+    }
+    loadAnalytics();
+  }
+
+  if (document.querySelector('[name="astro-view-transitions-enabled"]')) {
+    // ClientRouter fires astro:page-load on the first load and after every navigation.
+    document.addEventListener('astro:page-load', init);
+  } else {
+    // Sensitive pages render without the ClientRouter.
+    init();
+  }
+</script>
