+
+/** Account endpoints (username + password are sent here, nothing else). */
+export const AUTH_ENDPOINTS = {
+  login: `${TIMES_CDN_BASE}/api/login`,
+  register: `${TIMES_CDN_BASE}/api/register`,
+} as const;
+
+/** Optional, consent-gated analytics script. Never loaded without opt-in. */
+export const ANALYTICS_SCRIPT_SRC = `${TIMES_CDN_BASE}/lib/analytics-client.js`;
+
+/** localStorage key holding the visitor's consent choice (never sent to a server). */
+export const CONSENT_STORAGE_KEY = 'dtt-privacy-consent-v1';
+
+/** Pages handling credentials: no third-party scripts, no caching. */
+export const SENSITIVE_PATHS = ['signin', 'signup'];
