+// Progressive enhancement for the newsletter signup form.
+// Without JS the form still posts to /api/newsletter and the server returns an HTML page.
+const form = document.getElementById('newsletter-form');
+const status = document.getElementById('newsletter-status');
+const emailInput = document.getElementById('newsletter-email');
+
+function showStatus(state, message) {
+  status.dataset.state = state;
+  status.textContent = message;
+}
+
+const BLOCKED_MESSAGE =
+  "Sorry, we couldn't reach our server to sign you up. Please check your connection and try again in a moment.";
+
+emailInput?.addEventListener('input', () => {
+  emailInput.removeAttribute('aria-invalid');
+  if (status.dataset.state === 'error') showStatus('', '');
+});
+
+form?.addEventListener('submit', async (event) => {
+  event.preventDefault();
+
+  if (!form.checkValidity()) {
+    emailInput.setAttribute('aria-invalid', 'true');
+    showStatus('error', 'Please enter a valid email address, like name@example.com.');
+    emailInput.focus();
+    return;
+  }
+
+  const button = form.querySelector('button[type="submit"]');
+  button.disabled = true;
+  showStatus('pending', 'Signing you up…');
+
+  try {
+    const response = await fetch(form.action, {
+      method: 'POST',
+      headers: { Accept: 'application/json' },
+      body: new URLSearchParams(new FormData(form)),
+    });
+
+    let data = {};
+    try {
+      data = await response.json();
+    } catch {
+      // Non-JSON response; fall through to the generic message below.
+    }
+
+    if (response.ok) {
+      showStatus('success', data.message || "Thanks! You're on the list.");
+      form.reset();
+    } else {
+      if (response.status === 400) emailInput.setAttribute('aria-invalid', 'true');
+      showStatus('error', data.error || "Sorry, we couldn't sign you up right now. Please try again later.");
+    }
+  } catch {
+    // fetch() rejects with a TypeError when the request is blocked by the
+    // page's connection policy (Connection-Allowlist / CSP) or the network is down.
+    showStatus('error', BLOCKED_MESSAGE);
+  } finally {
+    button.disabled = false;
+  }
+});
