+// Minimal Node server for The Daily Grind homepage.
+// Serves the static homepage with strict outbound-connection headers and
+// handles newsletter signups and security violation reports.
+import { createServer } from 'node:http';
+import { readFile, appendFile, mkdir } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const ROOT = path.dirname(fileURLToPath(import.meta.url));
+const PUBLIC_DIR = path.join(ROOT, 'public');
+const DATA_DIR = path.join(ROOT, 'data');
+const PORT = Number(process.env.PORT) || 11222;
+
+// The only external origin the page may talk to (hero photo).
+const PHOTO_HOST = 'https://images.unsplash.com';
+const REPORT_ENDPOINT_NAME = 'security';
+const REPORT_PATH = '/api/security-reports';
+
+// Connection-Allowlist: one network-layer allowlist covering fetch, XHR, beacons,
+// subresources, navigations, resource hints, WebSockets and WebRTC (blocked by default).
+// Redirects stay blocked (the default) so an allowed request can't be bounced elsewhere.
+const CONNECTION_ALLOWLIST = `(response-origin "${PHOTO_HOST}"); report-to=${REPORT_ENDPOINT_NAME}`;
+
+// CSP fallback for browsers without Connection-Allowlist support.
+// form-action has no default-src fallback, so it's listed explicitly.
+const CONTENT_SECURITY_POLICY = [
+  "default-src 'self'",
+  "script-src 'self'",
+  "style-src 'self'",
+  `img-src 'self' ${PHOTO_HOST}`,
+  "connect-src 'self'",
+  "font-src 'self'",
+  "form-action 'self'",
+  "worker-src 'self'",
+  "manifest-src 'self'",
+  "media-src 'self'",
+  "frame-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  `report-to ${REPORT_ENDPOINT_NAME}`,
+].join('; ');
+
+// Connection-Allowlist is only honored on document and worker responses.
+const ALLOWLIST_DESTS = new Set(['document', 'iframe', 'worker', 'sharedworker', 'serviceworker']);
+
+// Explicit file map: nothing outside it can be served (no path traversal).
+const STATIC_FILES = {
+  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/index.html': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/styles.css': { file: 'styles.css', type: 'text/css; charset=utf-8' },
+  '/newsletter.js': { file: 'newsletter.js', type: 'text/javascript; charset=utf-8' },
+};
+
+const MAX_BODY_BYTES = 16 * 1024;
+const EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;
+
+function setSecurityHeaders(req, res) {
+  res.setHeader('Vary', 'Sec-Fetch-Dest');
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+  res.setHeader('Content-Security-Policy', CONTENT_SECURITY_POLICY);
+  res.setHeader('Reporting-Endpoints', `${REPORT_ENDPOINT_NAME}="${REPORT_PATH}"`);
+
+  const dest = String(req.headers['sec-fetch-dest'] || '').toLowerCase();
+  // Missing Sec-Fetch-Dest (older clients): apply it anyway; it's harmless on other responses.
+  if (!dest || ALLOWLIST_DESTS.has(dest)) {
+    res.setHeader('Connection-Allowlist', CONNECTION_ALLOWLIST);
+  }
+}
+
+function send(res, status, body, type = 'text/plain; charset=utf-8', extra = {}) {
+  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-cache', ...extra });
+  res.end(body);
+}
+
+function sendJson(res, status, obj) {
+  send(res, status, JSON.stringify(obj), 'application/json; charset=utf-8', { 'Cache-Control': 'no-store' });
+}
+
+function escapeHtml(s) {
+  return String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
+}
+
+function htmlPage(title, message) {
+  return `<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>${escapeHtml(title)} | The Daily Grind</title>
+  <link rel="stylesheet" href="/styles.css">
+</head>
+<body>
+  <main class="container newsletter">
+    <h1>${escapeHtml(title)}</h1>
+    <p>${escapeHtml(message)}</p>
+    <a href="/" class="btn">Back to the homepage</a>
+  </main>
+</body>
+</html>`;
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let size = 0;
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function isSameOrigin(req) {
+  // Reject cross-site form posts. Browsers send Origin on POST; Sec-Fetch-Site when supported.
+  const site = req.headers['sec-fetch-site'];
+  if (site && site !== 'same-origin' && site !== 'none') return false;
+  const origin = req.headers.origin;
+  if (!origin) return true;
+  try {
+    return new URL(origin).host === req.headers.host;
+  } catch {
+    return false;
+  }
+}
+
+async function handleNewsletter(req, res) {
+  const wantsJson = String(req.headers.accept || '').includes('application/json');
+  const reply = (status, ok, message) =>
+    wantsJson
+      ? sendJson(res, status, ok ? { message } : { error: message })
+      : send(res, status, htmlPage(ok ? "You're subscribed!" : 'Signup problem', message), 'text/html; charset=utf-8');
+
+  if (!isSameOrigin(req)) return reply(403, false, 'This request was not allowed.');
+
+  let params;
+  try {
+    params = new URLSearchParams(await readBody(req));
+  } catch (err) {
+    return reply(err.status || 400, false, 'We could not read your signup. Please try again.');
+  }
+
+  // Honeypot: pretend success for bots.
+  if (params.get('website')) return reply(200, true, "Thanks! You're on the list.");
+
+  const email = (params.get('email') || '').trim().toLowerCase();
+  if (email.length > 254 || !EMAIL_RE.test(email)) {
+    return reply(400, false, 'Please enter a valid email address, like name@example.com.');
+  }
+
+  try {
+    await mkdir(DATA_DIR, { recursive: true });
+    await appendFile(
+      path.join(DATA_DIR, 'subscribers.jsonl'),
+      JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n',
+    );
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    return reply(500, false, "Sorry, we couldn't sign you up right now. Please try again later.");
+  }
+
+  return reply(200, true, "Thanks! You're on the list. Watch your inbox for our next issue.");
+}
+
+async function handleReport(req, res) {
+  try {
+    const body = await readBody(req);
+    const reports = JSON.parse(body);
+    for (const report of Array.isArray(reports) ? reports : [reports]) {
+      console.warn('[security-report]', report?.type ?? 'csp-violation', JSON.stringify(report?.body ?? report));
+    }
+  } catch {
+    // Ignore malformed reports.
+  }
+  res.writeHead(204);
+  res.end();
+}
+
+const server = createServer(async (req, res) => {
+  setSecurityHeaders(req, res);
+  const { pathname } = new URL(req.url, 'http://localhost');
+
+  try {
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', undefined, { Allow: 'POST' });
+      return await handleNewsletter(req, res);
+    }
+
+    if (pathname === REPORT_PATH) {
+      if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', undefined, { Allow: 'POST' });
+      return await handleReport(req, res);
+    }
+
+    const entry = STATIC_FILES[pathname];
+    if (entry && (req.method === 'GET' || req.method === 'HEAD')) {
+      const content = await readFile(path.join(PUBLIC_DIR, entry.file));
+      res.writeHead(200, { 'Content-Type': entry.type, 'Cache-Control': 'no-cache' });
+      return res.end(req.method === 'HEAD' ? undefined : content);
+    }
+
+    return send(res, 404, htmlPage('Page not found', "We couldn't find that page."), 'text/html; charset=utf-8');
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) send(res, 500, 'Internal Server Error');
+    else res.end();
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`The Daily Grind running at http://localhost:${PORT}`);
+});

