+'use strict';
+
+(function () {
+  var TIMEOUT_MS = 10000;
+  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+  var MESSAGES = {
+    invalid: 'Please enter a valid email address.',
+    offline: "You appear to be offline. Please check your connection and try again.",
+    network: "We couldn't reach our server just now. Please try again in a moment.",
+    timeout: 'The request took too long. Please try again.',
+    server: 'Something went wrong on our end. Please try again later.',
+    rateLimited: "You've tried a few times already. Please wait a minute and try again.",
+    success: "Thanks for subscribing! Watch your inbox for fresh brews."
+  };
+
+  function init() {
+    var form = document.getElementById('newsletter-form');
+    var status = document.getElementById('newsletter-status');
+    if (!form || !status) return;
+
+    var input = form.querySelector('input[name="email"]');
+    var button = form.querySelector('button[type="submit"]');
+
+    function show(kind, text) {
+      status.textContent = text;
+      status.className = 'form-status ' + kind;
+      status.hidden = false;
+    }
+
+    // Show the result of a no-JS fallback submission (server redirects with ?newsletter=...).
+    var params = new URLSearchParams(window.location.search);
+    var fallback = params.get('newsletter');
+    if (fallback === 'ok') show('success', MESSAGES.success);
+    else if (fallback === 'invalid') show('error', MESSAGES.invalid);
+    else if (fallback === 'error') show('error', MESSAGES.server);
+
+    form.addEventListener('submit', function (event) {
+      event.preventDefault();
+
+      var email = input.value.trim();
+      if (!EMAIL_RE.test(email) || email.length > 254) {
+        show('error', MESSAGES.invalid);
+        input.focus();
+        return;
+      }
+
+      if (navigator.onLine === false) {
+        show('error', MESSAGES.offline);
+        return;
+      }
+
+      var controller = typeof AbortController === 'function' ? new AbortController() : null;
+      var timer = controller ? setTimeout(function () { controller.abort(); }, TIMEOUT_MS) : null;
+
+      button.disabled = true;
+      status.hidden = true;
+
+      // Relative URL: same-origin only, which is all the Content-Security-Policy allows.
+      fetch('/api/newsletter', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
+        body: JSON.stringify({ email: email }),
+        credentials: 'same-origin',
+        signal: controller ? controller.signal : undefined
+      })
+        .then(function (res) {
+          return res.json().catch(function () { return {}; }).then(function (data) {
+            if (res.ok) {
+              show('success', MESSAGES.success);
+              form.reset();
+            } else if (res.status === 400) {
+              show('error', MESSAGES.invalid);
+            } else if (res.status === 429) {
+              show('error', MESSAGES.rateLimited);
+            } else {
+              show('error', MESSAGES.server);
+            }
+          });
+        })
+        .catch(function (err) {
+          // fetch rejects on network failure, CSP blocks, and aborts.
+          if (err && err.name === 'AbortError') show('error', MESSAGES.timeout);
+          else if (navigator.onLine === false) show('error', MESSAGES.offline);
+          else show('error', MESSAGES.network);
+        })
+        .then(function () {
+          if (timer) clearTimeout(timer);
+          button.disabled = false;
+        });
+    });
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();
