--- /dev/null
+++ b/server.js
@@ -0,0 +1,209 @@
+'use strict';
+
+const http = require('node:http');
+const fs = require('node:fs');
+const fsp = require('node:fs/promises');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const HOST = process.env.HOST || '0.0.0.0';
+const PUBLIC_DIR = path.join(__dirname, 'public');
+const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const MAX_BODY_BYTES = 1024;
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+// The page may only talk to this origin, plus load photos from Unsplash.
+// No inline scripts/styles are allowed, so an injected <script> or style
+// attribute is inert, and any fetch/XHR/beacon/WebSocket to another host is blocked.
+const CSP = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "font-src 'self'",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  "frame-src 'none'",
+  "object-src 'none'",
+  "manifest-src 'self'",
+  "worker-src 'none'",
+].join('; ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CSP,
+  'X-Content-Type-Options': 'nosniff',
+  'X-Frame-Options': 'DENY',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+};
+
+// Explicit allowlist of static files: no directory traversal possible.
+const STATIC_FILES = {
+  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/index.html': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/styles.css': { file: 'styles.css', type: 'text/css; charset=utf-8' },
+  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, ...headers });
+  res.end(body);
+}
+
+function sendJson(res, status, obj) {
+  send(res, status, JSON.stringify(obj), {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+}
+
+// --- simple in-memory rate limiting for the signup endpoint ---
+const RATE_WINDOW_MS = 60_000;
+const RATE_MAX = 5;
+const hits = new Map();
+function rateLimited(ip) {
+  const now = Date.now();
+  const entry = hits.get(ip);
+  if (!entry || now - entry.start > RATE_WINDOW_MS) {
+    hits.set(ip, { start: now, count: 1 });
+    return false;
+  }
+  entry.count += 1;
+  return entry.count > RATE_MAX;
+}
+setInterval(() => {
+  const now = Date.now();
+  for (const [ip, e] of hits) if (now - e.start > RATE_WINDOW_MS) hits.delete(ip);
+}, RATE_WINDOW_MS).unref();
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function parseEmail(raw, contentType) {
+  try {
+    if (contentType.startsWith('application/json')) {
+      const data = JSON.parse(raw);
+      return typeof data?.email === 'string' ? data.email : null;
+    }
+    if (contentType.startsWith('application/x-www-form-urlencoded')) {
+      return new URLSearchParams(raw).get('email');
+    }
+  } catch {
+    return null;
+  }
+  return null;
+}
+
+async function saveSubscriber(email) {
+  await fsp.mkdir(DATA_DIR, { recursive: true });
+  const line = JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n';
+  await fsp.appendFile(SUBSCRIBERS_FILE, line, { mode: 0o600 });
+}
+
+async function handleNewsletter(req, res) {
+  const contentType = String(req.headers['content-type'] || '').toLowerCase();
+  const wantsJson = contentType.startsWith('application/json');
+  // Plain HTML form fallback (no JS): redirect back to the homepage with a status.
+  const reply = (status, code) => {
+    if (wantsJson) return sendJson(res, status, { ok: status < 300, code });
+    const result = status < 300 ? 'ok' : status === 400 ? 'invalid' : 'error';
+    send(res, 303, '', { Location: `/?newsletter=${result}#newsletter-title` });
+  };
+
+  if (rateLimited(req.socket.remoteAddress || 'unknown')) {
+    return reply(429, 'rate_limited');
+  }
+
+  let raw;
+  try {
+    raw = await readBody(req);
+  } catch (err) {
+    return reply(err.status || 400, 'bad_request');
+  }
+
+  const email = (parseEmail(raw, contentType) || '').trim().toLowerCase();
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    return reply(400, 'invalid_email');
+  }
+
+  try {
+    await saveSubscriber(email);
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    return reply(500, 'server_error');
+  }
+  return reply(201, 'subscribed');
+}
+
+async function handleStatic(req, res, pathname) {
+  const entry = STATIC_FILES[pathname];
+  if (!entry) {
+    return send(res, 404, 'Not found', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+  try {
+    const body = await fsp.readFile(path.join(PUBLIC_DIR, entry.file));
+    send(res, 200, req.method === 'HEAD' ? undefined : body, {
+      'Content-Type': entry.type,
+      'Cache-Control': entry.file === 'index.html' ? 'no-cache' : 'public, max-age=3600',
+    });
+  } catch (err) {
+    console.error('Static file error:', err);
+    send(res, 500, 'Internal server error', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+}
+
+const server = http.createServer((req, res) => {
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    return send(res, 400, 'Bad request', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  const handle = async () => {
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') {
+        return send(res, 405, 'Method not allowed', { Allow: 'POST', 'Content-Type': 'text/plain; charset=utf-8' });
+      }
+      return handleNewsletter(req, res);
+    }
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      return send(res, 405, 'Method not allowed', { Allow: 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8' });
+    }
+    return handleStatic(req, res, pathname);
+  };
+
+  handle().catch((err) => {
+    console.error('Unhandled error:', err);
+    if (!res.headersSent) send(res, 500, 'Internal server error', { 'Content-Type': 'text/plain; charset=utf-8' });
+    else res.end();
+  });
+});
+
+if (require.main === module) {
+  server.listen(PORT, HOST, () => {
+    console.log(`The Daily Grind running at http://${HOST}:${PORT}`);
+  });
+}
+
+module.exports = { server, CSP };

