+      const cards = [...document.querySelectorAll(".thumbnail")];
+      const baseTitle = document.title;
+
+      let current = null;     // card currently shown in detail view
+      let transition = null;  // running view transition, if any
+
+      function run(update) {
+        transition?.skipTransition();
+        if (!document.startViewTransition) {
+          update();
+          return Promise.resolve();
+        }
+        transition = document.startViewTransition(update);
+        const done = transition.finished.catch(() => {});
+        done.then(() => { transition = null; });
+        return done;
+      }
+
+      function preload(src) {
+        const img = new Image();
+        img.src = src;
+        return img.decode().catch(() => {});
+      }
+
+      async function showDetail(card) {
+        if (current === card && !detailPage.hidden) return;
+        cards.forEach((c) => c.classList.remove("selected"));
+        current = card;
+        // Name the clicked card (and its title) before the "old" snapshot is taken.
+        card.classList.add("selected");
+        // Make sure the hero image is ready so the "new" snapshot isn't blank.
+        await preload(card.dataset.img);
+
