+          title.textContent = card.querySelector(".title").textContent;
+          detailText.textContent = card.dataset.details;
+          listPage.hidden = true;
+          detailPage.hidden = false;
+          // Unname the card so it doesn't collide with #hero later on.
+          card.classList.remove("selected");
+          document.title = `${title.textContent} | ${baseTitle}`;
+          if (detailPage.getBoundingClientRect().top < 90) {
+            detailPage.scrollIntoView({ block: "start" });
+          }
+        });
+        title.focus({ preventScroll: true });
+      }
+
+      async function showList() {
+        if (detailPage.hidden) return;
+        const card = current;
+        await run(() => {
+          detailPage.hidden = true;
+          listPage.hidden = false;
+          card?.classList.add("selected");
+          document.title = baseTitle;
+          card?.scrollIntoView({ block: "nearest" });
+        });
+        card?.classList.remove("selected");
+        current = null;
+        // Return focus to the item the user came from (fall back to the heading).
+        (card?.querySelector(".title a") ?? listHeading).focus({ preventScroll: true });
+      }
+
+      function cardFromHash() {
+        const id = decodeURIComponent(location.hash.slice(1));
