+    (function () {
+      var nav = document.querySelector('nav');
+      var links = Array.prototype.slice.call(document.querySelectorAll('nav .nav-link'));
+      var sections = links
+        .map(function (link) { return document.querySelector(link.getAttribute('href')); })
+        .filter(Boolean);
+      var currentId = null;
+      var ticking = false;
+
+      function setActive(id) {
+        if (id === currentId) return;
+        currentId = id;
+        links.forEach(function (link) {
+          var isActive = link.getAttribute('href') === '#' + id;
+          link.classList.toggle('active', isActive);
+          if (isActive) {
+            link.setAttribute('aria-current', 'location');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function update() {
+        ticking = false;
+        // A section counts as "current" once its top passes just below the sticky nav.
+        var threshold = nav.offsetHeight + window.innerHeight * 0.25;
+        var activeId = null;
+
+        sections.forEach(function (section) {
+          if (section.getBoundingClientRect().top <= threshold) {
+            activeId = section.id;
+          }
+        });
+
+        // At the very bottom of the page, the last section may be too short to
+        // reach the threshold, so highlight it explicitly.
+        var atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
+        if (atBottom && sections.length) {
+          activeId = sections[sections.length - 1].id;
+        }
+
+        setActive(activeId);
+      }
