+/**
+ * <drink-card> — reusable menu card with an encapsulated layout.
+ *
+ * Usage:
+ *   <drink-card href="/menu/cold-brew" limited>
+ *     <h3 slot="title">Cold Brew</h3>
+ *     <p>Steeped for 18 hours for maximum smoothness.</p>
+ *     <span slot="action">Order Cold Brew</span>   <!-- optional, defaults to "View Details" -->
+ *   </drink-card>
+ *
+ * Attributes / properties:
+ *   href     (string)  — destination of the card's action link.
+ *   limited  (boolean) — shows the "Limited" badge when present. Add/remove at any time,
+ *                        e.g. `card.limited = false` or `card.toggleAttribute('limited')`.
+ *
+ * Theming (optional, set on any ancestor):
+ *   --drink-card-bg, --drink-card-accent, --drink-card-accent-hover,
+ *   --drink-card-badge-bg, --drink-card-badge-fg
+ *
+ * Parts: card, badge, action
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--drink-card-bg, #fff);
+    --_accent: var(--drink-card-accent, #4e342e);
+    --_accent-hover: var(--drink-card-accent-hover, #3e2723);
+    --_badge-bg: var(--drink-card-badge-bg, #ffab40);
+    --_badge-fg: var(--drink-card-badge-fg, #3e2723);
+    display: block;
+  }
+
+  :host([hidden]) { display: none; }
+
+  article {
+    position: relative;
+    box-sizing: border-box;
+    height: 100%;
+    margin: 0;
+    padding: 20px;
+    background: var(--_bg);
+    border-radius: 8px;
+    box-shadow: 0 2px 5px rgb(0 0 0 / 0.1);
+    text-align: center;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    right: 12px;
+    padding: 2px 10px;
+    border-radius: 999px;
+    background: var(--_badge-bg);
+    color: var(--_badge-fg);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    line-height: 1.6;
+  }
+
+  :host(:not([limited])) .badge { display: none; }
+
+  /* Leave room so a long title never runs under the badge. */
+  :host([limited]) .title { padding-inline: 4.5rem; }
+
+  .title { margin: 0 0 10px; }
+
+  ::slotted([slot="title"]) {
+    color: var(--_accent);
+    font-size: 1.17em;
+    font-weight: 700;
+  }
+
+  .action {
+    display: inline-block;
+    margin-top: 15px;
+    padding: 10px 20px;
+    border-radius: 5px;
+    background: var(--_accent);
+    color: #fff;
+    font: inherit;
+    text-decoration: none;
+    transition: background 0.3s;
+  }
+
+  .action:hover { background: var(--_accent-hover); }
+
+  .action:focus-visible {
+    outline: 2px solid var(--_accent);
+    outline-offset: 3px;
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <article part="card">
+    <span class="badge" part="badge">Limited</span>
+    <div class="title"><slot name="title"></slot></div>
+    <div class="description"><slot></slot></div>
+    <a class="action" part="action"><slot name="action">View Details</slot></a>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['href'];
+
+  #link;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+    this.#link = root.querySelector('.action');
+  }
+
+  connectedCallback() {
+    this.#syncHref();
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal !== newVal) this.#syncHref();
+  }
+
+  get href() { return this.getAttribute('href') ?? ''; }
+  set href(v) { v ? this.setAttribute('href', v) : this.removeAttribute('href'); }
+
+  get limited() { return this.hasAttribute('limited'); }
+  set limited(on) { this.toggleAttribute('limited', !!on); }
+
+  #syncHref() {
+    const href = this.getAttribute('href');
+    if (href) this.#link.setAttribute('href', href);
+    else this.#link.removeAttribute('href');
+  }
+}
+
+customElements.define('drink-card', DrinkCard);
