@@ -0,0 +1,149 @@
+/**
+ * <drink-card> — reusable, style-isolated product card.
+ *
+ * Attributes (all reactive, so the page can change them at any time):
+ *   heading       Card title, e.g. "Cold Brew"
+ *   description   Short blurb shown under the title
+ *   href          URL for the action link
+ *   action-label  Link text (defaults to "View Details")
+ *   limited       Boolean; when present, shows the "Limited" badge
+ *   badge-label   Optional badge text override (defaults to "Limited")
+ *
+ * Layout and styles live in Shadow DOM, so global page CSS (.card, .btn,
+ * h3, a, * resets, ...) cannot leak in and card styles cannot leak out.
+ * Theme colours may be tuned from outside via CSS custom properties:
+ *   --card-primary, --card-primary-hover, --card-accent, --card-text
+ * (falling back to the page's --primary / --accent / --text tokens).
+ */
+const template = document.createElement('template');
+template.innerHTML = `
+  <style>
+    :host {
+      display: block;
+      font-family: inherit;
+      color: var(--card-text, var(--text, #3e2723));
+      line-height: 1.6;
+    }
+    :host([hidden]) { display: none; }
+
+    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+    .card {
+      position: relative;
+      height: 100%;
+      background: #fff;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+    }
+
+    /* Leave room so the badge never overlaps a long title. */
+    :host([limited]) .card { padding-top: 36px; }
+
+    .badge {
+      position: absolute;
+      top: 12px;
+      right: 12px;
+      background: var(--card-accent, var(--accent, #ffab40));
+      color: var(--card-primary, var(--primary, #4e342e));
+      font-size: 0.7rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+      padding: 2px 8px;
+      border-radius: 999px;
+    }
+    .badge[hidden] { display: none; }
+
+    h3 {
+      font-size: 1.17em;
+      margin-bottom: 10px;
+      color: var(--card-primary, var(--primary, #4e342e));
+    }
+
+    .btn {
+      display: inline-block;
+      background: var(--card-primary, var(--primary, #4e342e));
+      color: #fff;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+    .btn:hover,
+    .btn:focus-visible {
+      background: var(--card-primary-hover, #3e2723);
+    }
+    .btn:focus-visible {
+      outline: 2px solid var(--card-accent, var(--accent, #ffab40));
+      outline-offset: 2px;
+    }
+  </style>
+  <article class="card" part="card">
+    <span class="badge" part="badge" hidden></span>
+    <h3 part="heading"></h3>
+    <p part="description"></p>
+    <a class="btn" part="action"></a>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static get observedAttributes() {
+    return ['heading', 'description', 'href', 'action-label', 'limited', 'badge-label'];
+  }
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.appendChild(template.content.cloneNode(true));
+    this._els = {
+      badge: root.querySelector('.badge'),
+      heading: root.querySelector('h3'),
+      description: root.querySelector('p'),
+      action: root.querySelector('a'),
+    };
+  }
+
+  connectedCallback() {
+    this._render();
+  }
+
+  attributeChangedCallback() {
+    this._render();
+  }
+
+  /** Convenience property so scripts can toggle the badge: card.limited = true */
+  get limited() {
+    return this.hasAttribute('limited');
+  }
+  set limited(value) {
+    this.toggleAttribute('limited', Boolean(value));
+  }
+
+  _render() {
+    const { badge, heading, description, action } = this._els;
+    const heading_ = this.getAttribute('heading') || '';
+
+    heading.textContent = heading_;
+    description.textContent = this.getAttribute('description') || '';
+
+    action.textContent = this.getAttribute('action-label') || 'View Details';
+    const href = this.getAttribute('href');
+    if (href) action.setAttribute('href', href);
+    else action.removeAttribute('href');
+    action.hidden = !href;
+    if (heading_) action.setAttribute('aria-label', `${action.textContent}: ${heading_}`);
+    else action.removeAttribute('aria-label');
+
+    badge.textContent = this.getAttribute('badge-label') || 'Limited';
+    badge.hidden = !this.limited;
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
+
+export { DrinkCard };
