+        logo.style.letterSpacing = lerp(1, 0.5, p).toFixed(3) + 'px';
+      }
+
+      function onScroll() {
+        if (!ticking) {
+          ticking = true;
+          raf(update);
+        }
+      }
+
+      window.addEventListener('scroll', onScroll, false);
+      window.addEventListener('resize', onScroll, false);
+      update();
+    })();
