+  return `the number ending in ${phone.slice(-2)}`;
+}
+
+export function generateOtp(): string {
+  return randomInt(0, 10 ** OTP_LENGTH).toString().padStart(OTP_LENGTH, '0');
+}
+
+export function hashOtp(code: string, phone: string): string {
+  return createHash('sha256').update(`${phone}:${code}`).digest('hex');
+}
+
+export function otpMatches(code: string, pending: PendingOtp): boolean {
+  const a = Buffer.from(hashOtp(code, pending.phone), 'hex');
+  const b = Buffer.from(pending.codeHash, 'hex');
+  return a.length === b.length && timingSafeEqual(a, b);
