@@ -0,0 +1,71 @@
+import type { APIRoute } from 'astro';
+import {
+  OTP_RESEND_COOLDOWN_MS,
+  OTP_TTL_MS,
+  buildSmsBody,
+  generateOtp,
+  hashOtp,
+  maskPhone,
+  normalizePhone,
+  sendSms,
+  type PendingOtp,
+} from '../../../lib/smsOtp';
+
+const json = (body: unknown, status = 200, headers: Record<string, string> = {}) =>
+  new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return json({ error: 'Sessions are unavailable.' }, 500);
+
+  let payload: { phone?: unknown };
+  try {
+    payload = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(payload.phone);
+  if (!phone) {
+    return json({ error: 'Enter a phone number in international format, starting with + and your country code.' }, 400);
+  }
+
+  const now = Date.now();
+  const previous = (await session.get('smsOtp')) as PendingOtp | undefined;
+  if (previous && previous.phone === phone && now - previous.sentAt < OTP_RESEND_COOLDOWN_MS) {
+    const retryAfter = Math.ceil((OTP_RESEND_COOLDOWN_MS - (now - previous.sentAt)) / 1000);
+    return json(
+      { error: `Please wait ${retryAfter} seconds before requesting another code.`, retryAfter },
+      429,
+      { 'Retry-After': String(retryAfter) },
+    );
+  }
+
+  const code = generateOtp();
+  const pending: PendingOtp = {
+    phone,
+    codeHash: hashOtp(code, phone),
+    expiresAt: now + OTP_TTL_MS,
+    sentAt: now,
+    attempts: 0,
+  };
+
+  try {
+    // Host only: no scheme, port or path, as required by the origin-bound SMS format.
+    await sendSms(phone, buildSmsBody(code, url.hostname));
+  } catch (err) {
+    console.error('[sms-otp] delivery failed', err);
+    return json({ error: 'We could not send a text message right now. Please try again later.' }, 502);
+  }
+
+  session.set('smsOtp', pending);
+  session.delete('verifiedPhone');
+
+  return json({
+    maskedPhone: maskPhone(phone),
+    expiresIn: OTP_TTL_MS / 1000,
+    resendIn: OTP_RESEND_COOLDOWN_MS / 1000,
+  });
+};
