+import type { APIRoute } from 'astro';
+import { OTP_LENGTH, OTP_MAX_ATTEMPTS, otpMatches, type PendingOtp, type VerifiedPhone } from '../../../lib/smsOtp';
+
+const json = (body: unknown, status = 200) =>
+  new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+
+const CODE_RE = new RegExp(`^\\d{${OTP_LENGTH}}$`);
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'Sessions are unavailable.' }, 500);
+
+  let payload: { code?: unknown };
+  try {
+    payload = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const code = typeof payload.code === 'string' ? payload.code.trim() : '';
+  if (!CODE_RE.test(code)) {
+    return json({ error: `Enter the ${OTP_LENGTH}-digit code from the text message.` }, 400);
+  }
+
+  const pending = (await session.get('smsOtp')) as PendingOtp | undefined;
+  if (!pending) {
+    return json({ error: 'No verification is in progress. Request a new code.', expired: true }, 400);
+  }
+
+  if (Date.now() > pending.expiresAt) {
+    session.delete('smsOtp');
+    return json({ error: 'This code has expired. Request a new code.', expired: true }, 400);
+  }
+
+  if (!otpMatches(code, pending)) {
+    pending.attempts += 1;
+    if (pending.attempts >= OTP_MAX_ATTEMPTS) {
+      session.delete('smsOtp');
+      return json({ error: 'Too many incorrect attempts. Request a new code.', expired: true }, 429);
+    }
+    session.set('smsOtp', pending);
+    const left = OTP_MAX_ATTEMPTS - pending.attempts;
+    return json({ error: `That code is incorrect. ${left} attempt${left === 1 ? '' : 's'} left.` }, 400);
+  }
+
+  session.delete('smsOtp');
+  const verified: VerifiedPhone = { phone: pending.phone, verifiedAt: Date.now() };
+  session.set('verifiedPhone', verified);
+  session.regenerate();
+
+  return json({ verified: true, phone: pending.phone });
+};
