@@ -0,0 +1,200 @@
+/**
+ * Server-only helpers for verifying phone numbers with SMS one-time passcodes.
+ *
+ * Codes are kept in process memory (hashed), expire quickly, and are limited
+ * in both send frequency and verification attempts. Successful verification
+ * yields a short-lived HMAC-signed token that proves the phone was verified.
+ *
+ * SMS delivery uses Twilio when TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN and
+ * TWILIO_FROM_NUMBER are configured. Otherwise (development), the message is
+ * written to the server log instead of being sent.
+ */
+import { createHash, createHmac, randomBytes, randomInt, timingSafeEqual } from 'node:crypto';
+
+export const CODE_LENGTH = 6;
+const CODE_TTL_MS = 5 * 60 * 1000;
+const RESEND_COOLDOWN_MS = 30 * 1000;
+const MAX_VERIFY_ATTEMPTS = 5;
+const MAX_SENDS_PER_WINDOW = 5;
+const SEND_WINDOW_MS = 60 * 60 * 1000;
+const MAX_SENDS_PER_IP_PER_WINDOW = 20;
+const TOKEN_TTL_MS = 15 * 60 * 1000;
+
+const env = (key: string): string | undefined =>
+  (typeof process !== 'undefined' ? process.env[key] : undefined) ||
+  ((import.meta.env as Record<string, string | undefined>)[key] ?? undefined);
+
+const SECRET = env('PHONE_VERIFICATION_SECRET') || randomBytes(32).toString('hex');
+
+interface PendingCode {
+  codeHash: string;
+  expiresAt: number;
+  attempts: number;
+  lastSentAt: number;
+}
+
+const pending = new Map<string, PendingCode>();
+const sendLog = new Map<string, number[]>();
+
+function prune(now: number) {
+  for (const [phone, entry] of pending) {
+    if (entry.expiresAt < now) pending.delete(phone);
+  }
+  for (const [key, times] of sendLog) {
+    const recent = times.filter((t) => now - t < SEND_WINDOW_MS);
+    if (recent.length) sendLog.set(key, recent);
+    else sendLog.delete(key);
+  }
+}
+
+function hashCode(phone: string, code: string) {
+  return createHmac('sha256', SECRET).update(`${phone}:${code}`).digest('hex');
+}
+
+function safeEqual(a: string, b: string) {
+  const ab = Buffer.from(a);
+  const bb = Buffer.from(b);
+  return ab.length === bb.length && timingSafeEqual(ab, bb);
+}
+
+/** Normalizes user input to E.164 (e.g. "+1 (555) 123-4567" -> "+15551234567"). */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  const trimmed = input.trim();
+  const hasPlus = trimmed.startsWith('+') || trimmed.startsWith('00');
+  let digits = trimmed.replace(/\D/g, '');
+  if (trimmed.startsWith('00')) digits = digits.slice(2);
+  if (!hasPlus) return null; // Require an explicit country code.
+  if (!/^[1-9]\d{7,14}$/.test(digits)) return null;
+  return `+${digits}`;
+}
+
+export function maskPhone(phone: string) {
+  return phone.length <= 4 ? phone : `${phone.slice(0, 3)}${'•'.repeat(Math.max(phone.length - 5, 0))}${phone.slice(-2)}`;
+}
+
+export type SendResult =
+  | { ok: true; expiresInSeconds: number; resendInSeconds: number }
+  | { ok: false; status: number; error: string; retryAfterSeconds?: number };
+
+export async function sendVerificationCode(phone: string, clientKey: string, otpDomain: string): Promise<SendResult> {
+  const now = Date.now();
+  prune(now);
+
+  const existing = pending.get(phone);
+  if (existing && now - existing.lastSentAt < RESEND_COOLDOWN_MS) {
+    const retryAfterSeconds = Math.ceil((RESEND_COOLDOWN_MS - (now - existing.lastSentAt)) / 1000);
+    return { ok: false, status: 429, error: `Please wait ${retryAfterSeconds} seconds before requesting a new code.`, retryAfterSeconds };
+  }
+
+  const phoneSends = sendLog.get(`phone:${phone}`) ?? [];
+  const ipSends = sendLog.get(`ip:${clientKey}`) ?? [];
+  if (phoneSends.length >= MAX_SENDS_PER_WINDOW || ipSends.length >= MAX_SENDS_PER_IP_PER_WINDOW) {
+    return { ok: false, status: 429, error: 'Too many codes requested. Please try again later.', retryAfterSeconds: SEND_WINDOW_MS / 1000 };
+  }
+
+  const code = randomInt(0, 10 ** CODE_LENGTH).toString().padStart(CODE_LENGTH, '0');
+  // The final line follows the WebOTP origin-bound format so supporting
+  // browsers can extract the code automatically: "@<host> #<code>".
+  const body = `${code} is your DevTools Times verification code. It expires in ${CODE_TTL_MS / 60000} minutes.\n\n@${otpDomain} #${code}`;
+
+  try {
+    await deliverSms(phone, body);
+  } catch (err) {
+    console.error('[phone-verification] SMS delivery failed', err);
+    return { ok: false, status: 502, error: 'We could not send a text message to that number. Please check it and try again.' };
+  }
+
+  pending.set(phone, { codeHash: hashCode(phone, code), expiresAt: now + CODE_TTL_MS, attempts: 0, lastSentAt: now });
+  sendLog.set(`phone:${phone}`, [...phoneSends, now]);
+  sendLog.set(`ip:${clientKey}`, [...ipSends, now]);
+
+  return { ok: true, expiresInSeconds: CODE_TTL_MS / 1000, resendInSeconds: RESEND_COOLDOWN_MS / 1000 };
+}
+
+export type VerifyResult =
+  | { ok: true; verificationToken: string }
+  | { ok: false; status: number; error: string; attemptsRemaining?: number };
+
+export function verifyCode(phone: string, code: unknown): VerifyResult {
+  const now = Date.now();
+  if (typeof code !== 'string' || !new RegExp(`^\\d{${CODE_LENGTH}}$`).test(code)) {
+    return { ok: false, status: 400, error: `Enter the ${CODE_LENGTH}-digit code from the text message.` };
+  }
+
+  const entry = pending.get(phone);
+  if (!entry || entry.expiresAt < now) {
+    pending.delete(phone);
+    return { ok: false, status: 410, error: 'This code has expired. Request a new code to continue.' };
+  }
+
+  entry.attempts += 1;
+  if (!safeEqual(entry.codeHash, hashCode(phone, code))) {
+    const attemptsRemaining = MAX_VERIFY_ATTEMPTS - entry.attempts;
+    if (attemptsRemaining <= 0) {
+      pending.delete(phone);
+      return { ok: false, status: 429, error: 'Too many incorrect attempts. Request a new code to continue.', attemptsRemaining: 0 };
+    }
+    return {
+      ok: false,
+      status: 400,
+      error: `That code is incorrect. ${attemptsRemaining} ${attemptsRemaining === 1 ? 'attempt' : 'attempts'} remaining.`,
+      attemptsRemaining,
+    };
+  }
+
+  pending.delete(phone);
+  return { ok: true, verificationToken: createVerificationToken(phone, now) };
+}
+
+function createVerificationToken(phone: string, now: number) {
+  const payload = Buffer.from(JSON.stringify({ phone, exp: now + TOKEN_TTL_MS })).toString('base64url');
+  const sig = createHmac('sha256', SECRET).update(payload).digest('base64url');
+  return `${payload}.${sig}`;
+}
+
+/** Returns the verified phone number if the token is valid and unexpired. */
+export function readVerificationToken(token: unknown): string | null {
+  if (typeof token !== 'string') return null;
+  const [payload, sig] = token.split('.');
+  if (!payload || !sig) return null;
+  const expected = createHmac('sha256', SECRET).update(payload).digest('base64url');
+  if (!safeEqual(sig, expected)) return null;
+  try {
+    const { phone, exp } = JSON.parse(Buffer.from(payload, 'base64url').toString());
+    return typeof phone === 'string' && typeof exp === 'number' && exp > Date.now() ? phone : null;
+  } catch {
+    return null;
+  }
+}
+
+async function deliverSms(to: string, body: string) {
+  const sid = env('TWILIO_ACCOUNT_SID');
+  const authToken = env('TWILIO_AUTH_TOKEN');
+  const from = env('TWILIO_FROM_NUMBER');
+
+  if (!sid || !authToken || !from) {
+    if (import.meta.env.PROD && env('SMS_ALLOW_LOG_DELIVERY') !== 'true') {
+      throw new Error('SMS provider is not configured (set TWILIO_* env vars).');
+    }
+    console.info(`[phone-verification] SMS to ${maskPhone(to)} (log delivery):\n${body}`);
+    return;
+  }
+
+  const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`, {
+    method: 'POST',
+    headers: {
+      Authorization: `Basic ${Buffer.from(`${sid}:${authToken}`).toString('base64')}`,
+      'Content-Type': 'application/x-www-form-urlencoded',
+    },
+    body: new URLSearchParams({ To: to, From: from, Body: body }),
+  });
+  if (!res.ok) {
+    throw new Error(`Twilio responded with ${res.status}: ${await res.text()}`);
+  }
+}
+
+/** Fingerprint used for per-client rate limiting without storing raw IPs. */
+export function clientKeyFrom(address: string | undefined) {
+  return createHash('sha256').update(address || 'unknown').digest('hex').slice(0, 16);
+}
