+import type { APIRoute } from 'astro';
+import { clientKeyFrom, normalizePhone, sendVerificationCode } from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+const json = (data: unknown, status = 200, headers: Record<string, string> = {}) =>
+  new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+
+export const POST: APIRoute = async ({ request, url, clientAddress }) => {
+  let body: { phone?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) {
+    return json({ error: 'Enter a valid mobile number including the country code, for example +1 555 123 4567.' }, 400);
+  }
+
+  let address: string | undefined;
+  try {
+    address = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || clientAddress;
+  } catch {
+    address = undefined;
+  }
+
+  // The WebOTP origin-bound line must match the host the user sees.
+  const otpDomain = process.env.SMS_OTP_DOMAIN || request.headers.get('x-forwarded-host') || url.host;
+  const result = await sendVerificationCode(phone, clientKeyFrom(address), otpDomain);
+
+  if (!result.ok) {
+    return json(
+      { error: result.error, retryAfterSeconds: result.retryAfterSeconds },
+      result.status,
+      result.retryAfterSeconds ? { 'Retry-After': String(result.retryAfterSeconds) } : {},
+    );
+  }
+  return json({ phone, expiresInSeconds: result.expiresInSeconds, resendInSeconds: result.resendInSeconds });
+};
