+import type { APIRoute } from 'astro';
+import { normalizePhone, verifyCode } from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+const json = (data: unknown, status = 200) =>
+  new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+
+export const POST: APIRoute = async ({ request }) => {
+  let body: { phone?: unknown; code?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) return json({ error: 'Invalid phone number.' }, 400);
+
+  const code = typeof body.code === 'string' ? body.code.replace(/\D/g, '') : body.code;
+  const result = verifyCode(phone, code);
+  if (!result.ok) {
+    return json({ error: result.error, attemptsRemaining: result.attemptsRemaining }, result.status);
+  }
+  return json({ phone, verified: true, verificationToken: result.verificationToken });
+};

