+        for (const row of rows) {
+          if (tbody.moveBefore) tbody.moveBefore(row, null);
+          else tbody.appendChild(row);
+        }
+      }
+
+      function reorderWithTransition(rows) {
+        if (table.startViewTransition) table.startViewTransition(() => reorder(rows));
+        else reorder(rows);
+      }
+
