@@ -0,0 +1,405 @@
+/**
+ * <drink-card> — encapsulated card for menu drinks.
+ *
+ * Theme: inherits the page's coffee palette (--primary, --secondary, --accent,
+ * --text, --light) across the shadow boundary through CSS custom properties.
+ * Override any part of it per card with the public --drink-card-* properties.
+ *
+ * Attributes
+ *   variant    "classic" (default) | "featured" | "bold" | "iced"
+ *   image-src  URL of the drink photo (rendered into the internal <img part="image">)
+ *   image-alt  alt text for the photo
+ *
+ * Slots
+ *   title      the drink name (use a real heading, e.g. <h3 slot="title">)
+ *   (default)  description copy
+ *   badge      small label overlaid on the photo ("New", "Limited", ...)
+ *   price      price text shown in the footer
+ *   action     call to action (link/button) shown in the footer
+ *   media      replaces the built-in <img> entirely (e.g. a <picture>)
+ *
+ * Parts
+ *   card, media, image, badge, body, title, description, footer, price, action
+ *
+ * Public custom properties
+ *   --drink-card-bg, --drink-card-ink, --drink-card-heading, --drink-card-accent,
+ *   --drink-card-muted, --drink-card-radius, --drink-card-shadow,
+ *   --drink-card-padding, --drink-card-media-ratio
+ */
+
+const css = /* css */ `
+  /* Priority tiers, lowest to highest. Later layers win regardless of selector
+     specificity, so a variant never has to out-specify the base styles and a
+     state never has to out-specify a variant. */
+  @layer reset, tokens, base, layout, variants, states;
+
+  /* ---------------------------------------------------------------- reset */
+  @layer reset {
+    :host {
+      display: block;
+      box-sizing: border-box;
+    }
+
+    :host([hidden]) {
+      display: none;
+    }
+
+    *,
+    *::before,
+    *::after {
+      box-sizing: inherit;
+      margin: 0;
+      padding: 0;
+    }
+
+    img {
+      display: block;
+      max-width: 100%;
+    }
+  }
+
+  /* --------------------------------------------------------------- tokens */
+  /* Private tokens (--_*) resolve public overrides first, then the inherited
+     site theme, then a hard-coded fallback so the component works anywhere. */
+  @layer tokens {
+    :host {
+      --_bg: var(--drink-card-bg, #fff);
+      --_ink: var(--drink-card-ink, var(--text, #3e2723));
+      --_heading: var(--drink-card-heading, var(--primary, #4e342e));
+      --_accent: var(--drink-card-accent, var(--accent, #ffab40));
+      --_muted: var(--drink-card-muted, var(--secondary, #d7ccc8));
+      --_radius: var(--drink-card-radius, 8px);
+      --_shadow: var(--drink-card-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+      --_pad: var(--drink-card-padding, 20px);
+      --_media-ratio: var(--drink-card-media-ratio, 16 / 10);
+      --_border: transparent;
+    }
+  }
+
+  /* ----------------------------------------------------------------- base */
+  @layer base {
+    /* Outer chrome lives on the host so variants restyle it via :host(). */
+    :host {
+      container: drink-card / inline-size;
+      background: var(--_bg);
+      color: var(--_ink);
+      border: 2px solid var(--_border);
+      border-radius: var(--_radius);
+      box-shadow: var(--_shadow);
+      overflow: hidden;
+      transition: transform 0.25s ease, box-shadow 0.25s ease;
+    }
+
+    .media {
+      position: relative;
+      background: var(--_muted);
+      overflow: hidden;
+    }
+
+    .media img,
+    ::slotted([slot="media"]) {
+      width: 100%;
+      height: 100%;
+      object-fit: cover;
+    }
+
+    .badge {
+      position: absolute;
+      top: 12px;
+      inset-inline-start: 12px;
+      background: var(--_accent);
+      color: var(--_heading);
+      font-size: 0.7rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+      padding: 3px 10px;
+      border-radius: 999px;
+    }
+
+    .title ::slotted(*) {
+      margin: 0;
+      color: var(--_heading);
+      font-size: clamp(1.1rem, 0.6rem + 3.5cqi, 1.75rem);
+      line-height: 1.25;
+    }
+
+    .description {
+      font-size: 0.95rem;
+    }
+
+    .price {
+      font-weight: 700;
+      color: var(--_heading);
+    }
+
+    /* Empty optional regions collapse instead of leaving gaps. */
+    [data-empty] {
+      display: none;
+    }
+  }
+
+  /* --------------------------------------------------------------- layout */
+  /* Layouts respond to the card's own width (container queries), not the
+     viewport, so the same card adapts wherever the page places it. */
+  @layer layout {
+    .card {
+      display: grid;
+      grid-template-areas:
+        "media"
+        "body";
+      grid-template-rows: auto 1fr;
+      height: 100%;
+    }
+
+    .media {
+      grid-area: media;
+      aspect-ratio: var(--_media-ratio);
+    }
+
+    .body {
+      grid-area: body;
+      display: flex;
+      flex-direction: column;
+      align-items: center;
+      gap: 10px;
+      padding: var(--_pad);
+      text-align: center;
+    }
+
+    .footer {
+      display: flex;
+      flex-wrap: wrap;
+      align-items: center;
+      justify-content: center;
+      gap: 8px 16px;
+      margin-top: auto;
+      padding-top: 5px;
+    }
+
+    /* Narrow card: tighter spacing, shorter photo, stacked footer. */
+    @container drink-card (max-width: 260px) {
+      .media {
+        aspect-ratio: 2 / 1;
+      }
+
+      .body {
+        --_pad: 14px;
+        gap: 6px;
+      }
+
+      .footer {
+        flex-direction: column;
+        gap: 4px;
+      }
+    }
+
+    /* Wide card: side-by-side media and body. */
+    @container drink-card (min-width: 520px) {
+      .card {
+        grid-template-areas: "media body";
+        grid-template-columns: minmax(200px, 2fr) 3fr;
+        grid-template-rows: 1fr;
+      }
+
+      .media {
+        aspect-ratio: auto;
+        min-height: 240px;
+      }
+
+      .media[data-empty] + .body {
+        grid-column: 1 / -1;
+      }
+
+      .body {
+        align-items: flex-start;
+        justify-content: center;
+        text-align: start;
+        padding: calc(var(--_pad) * 1.5);
+      }
+
+      .footer {
+        justify-content: flex-start;
+        margin-top: 10px;
+      }
+    }
+
+    /* Very wide card: let the description breathe. */
+    @container drink-card (min-width: 800px) {
+      .card {
+        grid-template-columns: 1fr 1fr;
+      }
+
+      .description {
+        font-size: 1.05rem;
+        max-width: 48ch;
+      }
+    }
+  }
+
+  /* ------------------------------------------------------------- variants */
+  /* Each variant only swaps default token values; public --drink-card-*
+     overrides set by the page still take precedence. */
+  @layer variants {
+    :host([variant="featured"]) {
+      --_bg: var(--drink-card-bg,
+        linear-gradient(135deg, #fff 55%, color-mix(in srgb, var(--accent, #ffab40) 18%, #fff)));
+      --_border: var(--_accent);
+      --_shadow: var(--drink-card-shadow, 0 8px 24px rgb(78 52 46 / 0.18));
+    }
+
+    :host([variant="bold"]) {
+      --_bg: var(--drink-card-bg, var(--primary, #4e342e));
+      --_ink: var(--drink-card-ink, var(--secondary, #d7ccc8));
+      --_heading: var(--drink-card-heading, var(--light, #fafafa));
+      --_muted: var(--drink-card-muted, #3e2723);
+      --_shadow: var(--drink-card-shadow, 0 6px 18px rgb(0 0 0 / 0.3));
+    }
+
+    :host([variant="bold"]) .badge {
+      color: var(--primary, #4e342e);
+    }
+
+    :host([variant="iced"]) {
+      --_bg: var(--drink-card-bg,
+        linear-gradient(180deg, #fff, color-mix(in srgb, var(--secondary, #d7ccc8) 45%, #fff)));
+      --_border: color-mix(in srgb, var(--secondary, #d7ccc8) 80%, #fff);
+    }
+  }
+
+  /* --------------------------------------------------------------- states */
+  @layer states {
+    :host(:hover) {
+      transform: translateY(-3px);
+      box-shadow: 0 10px 24px rgb(0 0 0 / 0.15);
+    }
+
+    :host(:focus-within) {
+      outline: 3px solid var(--_accent);
+      outline-offset: 2px;
+    }
+
+    .media img {
+      transition: transform 0.4s ease;
+    }
+
+    :host(:hover) .media img {
+      transform: scale(1.04);
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      :host,
+      .media img {
+        transition: none;
+      }
+
+      :host(:hover),
+      :host(:hover) .media img {
+        transform: none;
+      }
+    }
+  }
+`;
+
+const template = document.createElement("template");
+template.innerHTML = `
+  <article class="card" part="card">
+    <div class="media" part="media">
+      <slot name="media"><img part="image" alt="" loading="lazy" decoding="async"></slot>
+      <span class="badge" part="badge"><slot name="badge"></slot></span>
+    </div>
+    <div class="body" part="body">
+      <div class="title" part="title"><slot name="title"></slot></div>
+      <div class="description" part="description"><slot></slot></div>
+      <div class="footer" part="footer">
+        <span class="price" part="price"><slot name="price"></slot></span>
+        <span class="action" part="action"><slot name="action"></slot></span>
+      </div>
+    </div>
+  </article>
+`;
+
+let sharedSheet = null;
+function getSheet() {
+  if (!sharedSheet && "adoptedStyleSheets" in Document.prototype) {
+    sharedSheet = new CSSStyleSheet();
+    sharedSheet.replaceSync(css);
+  }
+  return sharedSheet;
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ["image-src", "image-alt"];
+
+  #img;
+  #media;
+  #regions = new Map();
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: "open" });
+
+    const sheet = getSheet();
+    if (sheet) {
+      root.adoptedStyleSheets = [sheet];
+    } else {
+      const style = document.createElement("style");
+      style.textContent = css;
+      root.append(style);
+    }
+
+    root.append(template.content.cloneNode(true));
+
+    this.#img = root.querySelector("img");
+    this.#media = root.querySelector(".media");
+
+    // Optional regions that should collapse when nothing is slotted into them.
+    for (const [name, selector] of [
+      ["badge", ".badge"],
+      ["price", ".price"],
+      ["action", ".action"],
+      ["media", ".media"],
+    ]) {
+      const slot = root.querySelector(`slot[name="${name}"]`);
+      this.#regions.set(slot, root.querySelector(selector));
+      slot.addEventListener("slotchange", () => this.#syncEmpty());
+    }
+  }
+
+  connectedCallback() {
+    this.#syncImage();
+    this.#syncEmpty();
+  }
+
+  attributeChangedCallback() {
+    this.#syncImage();
+    this.#syncEmpty();
+  }
+
+  #syncImage() {
+    const src = this.getAttribute("image-src");
+    if (src) {
+      this.#img.src = src;
+    } else {
+      this.#img.removeAttribute("src");
+    }
+    this.#img.alt = this.getAttribute("image-alt") ?? "";
+  }
+
+  #syncEmpty() {
+    for (const [slot, region] of this.#regions) {
+      const hasContent = slot.assignedNodes({ flatten: false }).some(
+        (n) => n.nodeType === Node.ELEMENT_NODE || n.textContent.trim()
+      );
+      const isMedia = region === this.#media;
+      const empty = isMedia ? !hasContent && !this.hasAttribute("image-src") : !hasContent;
+      region.toggleAttribute("data-empty", empty);
+    }
+  }
+}
+
+if (!customElements.get("drink-card")) {
+  customElements.define("drink-card", DrinkCard);
+}
+
+export { DrinkCard };
