+  <script>
+    (() => {
+      const menu = document.getElementById('coffee-menu');
+      const tablist = menu.querySelector('[focusgroup]');
+      const tabs = [...tablist.querySelectorAll('button')];
+      const panelFor = tab => document.getElementById(tab.id.replace(/^tab-/, 'panel-'));
+
+      function select(selected) {
+        for (const tab of tabs) {
+          const isSelected = tab === selected;
+          tab.ariaSelected = String(isSelected);
+          tab.toggleAttribute('focusgroupstart', isSelected);
+          panelFor(tab).hidden = isSelected ? false : 'until-found';
+        }
+        // Scroll only the tablist (not the page) so the selected tab and a peek of its neighbour are visible
+        selected.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
+      }
+
+      // Selection follows focus: arrow keys (via focusgroup) move focus, which selects the tab
+      tablist.addEventListener('focusin', e => {
+        const tab = e.target.closest('button');
+        if (tab && tab.ariaSelected !== 'true') select(tab);
+      });
+      tablist.addEventListener('click', e => {
+        const tab = e.target.closest('button');
+        if (tab) select(tab);
+      });
+
+      // Find-in-page revealed a hidden panel: sync the tab selection
+      for (const tab of tabs) {
+        panelFor(tab).addEventListener('beforematch', () => select(tab));
+      }
+
+      // Deep links like #panel-tea open that category
+      const fromHash = tabs.find(tab => '#' + panelFor(tab).id === location.hash);
+      if (fromHash) select(fromHash);
+    })();
+  </script>
