+    .map((l) => (l.toLowerCase() === 'zh-tw' || l.toLowerCase() === 'zh-hk' ? 'zh-Hant' : l.split('-')[0]))
+    .find((l) => l !== pageLanguage && (TARGET_LANGUAGES as readonly string[]).includes(l));
+  return preferred ?? (pageLanguage === 'es' ? 'en' : 'es');
+};
