+/**
+ * On-device page translation built on the browser's Translator API
+ * (and, when already downloaded, the LanguageDetector API).
+ *
+ * Any element marked with `data-translatable` is translated in place.
+ * Text nodes are translated individually so inline markup (links, emphasis,
+ * etc.) inside article bodies stays intact. The original text is kept so the
+ * page can be restored at any time.
+ */
+
+export type Availability = 'unavailable' | 'downloadable' | 'downloading' | 'available';
+
+interface DownloadProgressEvent extends Event {
+  loaded: number;
+}
+
+interface CreateMonitor extends EventTarget {
+  addEventListener(
+    type: 'downloadprogress',
+    listener: (event: DownloadProgressEvent) => void,
+  ): void;
+}
+
+interface TranslatorOptions {
+  sourceLanguage: string;
+  targetLanguage: string;
+}
+
+interface TranslatorInstance {
+  translate(input: string, options?: { signal?: AbortSignal }): Promise<string>;
+  destroy(): void;
+}
+
+interface TranslatorStatic {
+  availability(options: TranslatorOptions): Promise<Availability>;
+  create(
+    options: TranslatorOptions & {
+      monitor?: (m: CreateMonitor) => void;
+      signal?: AbortSignal;
+    },
+  ): Promise<TranslatorInstance>;
+}
+
+interface LanguageDetectorInstance {
+  detect(input: string): Promise<{ detectedLanguage: string; confidence: number }[]>;
+}
+
+interface LanguageDetectorStatic {
+  availability(): Promise<Availability>;
+  create(): Promise<LanguageDetectorInstance>;
+}
+
+const getTranslatorApi = (): TranslatorStatic | undefined =>
+  typeof self !== 'undefined' && 'Translator' in self
+    ? ((self as any).Translator as TranslatorStatic)
+    : undefined;
+
+const getDetectorApi = (): LanguageDetectorStatic | undefined =>
+  typeof self !== 'undefined' && 'LanguageDetector' in self
+    ? ((self as any).LanguageDetector as LanguageDetectorStatic)
+    : undefined;
+
+export const isTranslationSupported = () => getTranslatorApi() !== undefined;
+
+/** Languages supported by Chrome's Translator API implementation. */
+export const TARGET_LANGUAGES = [
+  'ar', 'bg', 'bn', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'he', 'hi',
+  'hr', 'hu', 'id', 'it', 'ja', 'kn', 'ko', 'lt', 'mr', 'nl', 'no', 'pl', 'pt',
+  'ro', 'ru', 'sk', 'sl', 'sv', 'ta', 'te', 'th', 'tr', 'uk', 'vi', 'zh', 'zh-Hant',
+] as const;
+
+const RTL_LANGUAGES = new Set(['ar', 'he']);
+
+export const TRANSLATABLE_SELECTOR = '[data-translatable]';
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'NOSCRIPT', 'TEMPLATE']);
+
+/** Original text of every translated node, so it can be restored. */
+const originalText = new Map<Text, string>();
+/** Original `lang`/`dir` attribute values of each translated container. */
+const originalAttrs = new Map<HTMLElement, { lang: string | null; dir: string | null }>();
+/** Cache of translators and translated strings per language pair. */
+const translators = new Map<string, Promise<TranslatorInstance>>();
+const translationCache = new Map<string, Map<string, string>>();
+
+const pairKey = ({ sourceLanguage, targetLanguage }: TranslatorOptions) =>
+  `${sourceLanguage}→${targetLanguage}`;
+
+/** The document's declared language, reduced to its primary subtag. */
+export const getPageLanguage = () =>
+  (document.documentElement.lang || 'en').split('-')[0].toLowerCase();
+
+/**
+ * Determine the source language of the page content. Uses the LanguageDetector
+ * API only when its model is already on the device (so no download or user
+ * activation is spent on it); otherwise trusts the document's `lang` attribute.
+ */
+export async function detectSourceLanguage(): Promise<string> {
+  const fallback = getPageLanguage();
+  const detectorApi = getDetectorApi();
+  if (!detectorApi) return fallback;
+
+  try {
+    if ((await detectorApi.availability()) !== 'available') return fallback;
+    const sample = getTranslatableElements()
+      .map((el) => el.textContent ?? '')
+      .join(' ')
+      .replace(/\s+/g, ' ')
+      .slice(0, 2000);
+    // Accuracy drops on short text; keep the declared language in that case.
+    if (sample.length < 40) return fallback;
+
+    const detector = await detectorApi.create();
+    const [best] = await detector.detect(sample);
+    if (best && best.confidence >= 0.7 && best.detectedLanguage !== 'und') {
+      return best.detectedLanguage;
+    }
+  } catch (error) {
+    console.warn('Language detection failed, using page language.', error);
+  }
+  return fallback;
+}
+
+export async function getAvailability(options: TranslatorOptions): Promise<Availability> {
+  const api = getTranslatorApi();
+  if (!api) return 'unavailable';
+  try {
+    return await api.availability(options);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+/**
+ * Create (or reuse) a translator for a language pair. Must be called during a
+ * user gesture whenever the pair is 'downloadable' or 'downloading'.
+ */
+export function getTranslator(
+  options: TranslatorOptions,
+  onDownloadProgress?: (fraction: number) => void,
+): Promise<TranslatorInstance> {
+  const api = getTranslatorApi();
+  if (!api) return Promise.reject(new Error('Translator API is not supported.'));
+
+  const key = pairKey(options);
+  let translator = translators.get(key);
+  if (!translator) {
+    translator = api.create({
+      ...options,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onDownloadProgress?.(e.loaded));
+      },
+    });
+    translators.set(key, translator);
+    // Allow a retry later if creation fails (e.g. missing user activation).
+    translator.catch(() => translators.delete(key));
+  }
+  return translator;
+}
+
+function getTranslatableElements(): HTMLElement[] {
+  const all = Array.from(document.querySelectorAll<HTMLElement>(TRANSLATABLE_SELECTOR));
+  // Skip elements nested in another translatable element; the outer one covers them.
+  return all.filter((el) => !el.parentElement?.closest(TRANSLATABLE_SELECTOR));
+}
+
+function collectTextNodes(root: HTMLElement): Text[] {
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      for (let el = node.parentElement; el && el !== root.parentElement; el = el.parentElement) {
+        if (SKIP_TAGS.has(el.tagName) || el.translate === false) {
+          return NodeFilter.FILTER_REJECT;
+        }
+      }
+      return /\p{L}/u.test(node.nodeValue ?? '') ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
+    },
+  });
+  const nodes: Text[] = [];
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+/** Restore every translated node and container attribute to its original state. */
+export function restoreOriginal() {
+  for (const [node, text] of originalText) {
+    if (node.isConnected) node.nodeValue = text;
+  }
+  originalText.clear();
+
+  for (const [el, { lang, dir }] of originalAttrs) {
+    if (lang === null) el.removeAttribute('lang');
+    else el.setAttribute('lang', lang);
+    if (dir === null) el.removeAttribute('dir');
+    else el.setAttribute('dir', dir);
+  }
+  originalAttrs.clear();
+}
+
+/**
+ * Translate all `[data-translatable]` content on the page in place.
+ * Always translates from the original text, so switching between target
+ * languages never compounds translation errors.
+ */
+export async function translatePage(
+  translator: TranslatorInstance,
+  options: TranslatorOptions,
+  { signal, onProgress }: { signal?: AbortSignal; onProgress?: (done: number, total: number) => void } = {},
+) {
+  restoreOriginal();
+
+  const key = pairKey(options);
+  let cache = translationCache.get(key);
+  if (!cache) {
+    cache = new Map();
+    translationCache.set(key, cache);
+  }
+
+  const elements = getTranslatableElements();
+  const work = elements.map((el) => ({ el, nodes: collectTextNodes(el) }));
+  const total = work.reduce((sum, { nodes }) => sum + nodes.length, 0);
+  let done = 0;
+  onProgress?.(done, total);
+
+  for (const { el, nodes } of work) {
+    if (nodes.length === 0) continue;
+
+    // Mark the container with the target language for assistive technology.
+    if (!originalAttrs.has(el)) {
+      originalAttrs.set(el, { lang: el.getAttribute('lang'), dir: el.getAttribute('dir') });
+    }
+    el.setAttribute('lang', options.targetLanguage);
+    el.setAttribute('dir', RTL_LANGUAGES.has(options.targetLanguage) ? 'rtl' : 'ltr');
+
+    for (const node of nodes) {
+      signal?.throwIfAborted();
+      const source = node.nodeValue ?? '';
+      // Translate the trimmed text, keeping surrounding whitespace so inline
+      // elements stay correctly spaced.
+      const [, leading, core, trailing] = source.match(/^(\s*)([\s\S]*?)(\s*)$/)!;
+
+      let translated = cache.get(core);
+      if (translated === undefined) {
+        translated = await translator.translate(core, { signal });
+        cache.set(core, translated);
+      }
+      signal?.throwIfAborted();
+
+      if (!originalText.has(node)) originalText.set(node, source);
+      node.nodeValue = `${leading}${translated}${trailing}`;
+      onProgress?.(++done, total);
+    }
+  }
+}
+
+export const isPageTranslated = () => originalText.size > 0;

