+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { LanguageIcon, CheckIcon, ArrowUturnLeftIcon } from '@heroicons/react/24/outline';
+import {
+  LANGUAGES,
+  STORAGE_KEY,
+  isTranslationSupported,
+  languageLabel,
+  pageLanguage,
+  restoreOriginal,
+  translatePage,
+  translationAvailability,
+} from '../utils/translation';
+
+type Status =
+  | { kind: 'idle' }
+  | { kind: 'downloading'; progress: number }
+  | { kind: 'translating'; done: number; total: number }
+  | { kind: 'done'; target: string; sources: string[] }
+  | { kind: 'error'; message: string };
+
+const AVAILABILITY_HINT: Record<AIAvailability, string> = {
+  available: 'Ready',
+  downloadable: 'Download',
+  downloading: 'Downloading…',
+  unavailable: 'Not available',
+};
+
+/**
+ * Header control that translates news articles and teasers on the current
+ * page using the browser's on-device Translator API.
+ */
+export default function TranslateButton() {
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [open, setOpen] = useState(false);
+  const [target, setTarget] = useState('');
+  const [status, setStatus] = useState<Status>({ kind: 'idle' });
+  const [availability, setAvailability] = useState<Record<string, AIAvailability>>({});
+  const abortRef = useRef<AbortController | null>(null);
+  const containerRef = useRef<HTMLDivElement>(null);
+  const panelId = useId();
+
+  const run = useCallback(async (lang: string, userInitiated: boolean) => {
+    abortRef.current?.abort();
+    setTarget(lang);
+
+    if (!lang) {
+      abortRef.current = null;
+      restoreOriginal();
+      localStorage.removeItem(STORAGE_KEY);
+      setStatus({ kind: 'idle' });
+      return;
+    }
+
+    const controller = new AbortController();
+    abortRef.current = controller;
+    localStorage.setItem(STORAGE_KEY, lang);
+    setStatus({ kind: 'translating', done: 0, total: 0 });
+
+    try {
+      const result = await translatePage(lang, {
+        signal: controller.signal,
+        allowDownload: userInitiated,
+        onDownloadProgress: (progress) => {
+          if (!controller.signal.aborted) setStatus({ kind: 'downloading', progress });
+        },
+        onProgress: (done, total) => {
+          if (!controller.signal.aborted) setStatus({ kind: 'translating', done, total });
+        },
+      });
+      if (controller.signal.aborted) return;
+
+      if (result.translated === 0 && result.needsDownload.length) {
+        setStatus({
+          kind: 'error',
+          message: `The ${languageLabel(lang)} language pack needs to be downloaded. Pick the language again to start the download.`,
+        });
+      } else if (result.translated === 0 && result.unsupported.length) {
+        setStatus({
+          kind: 'error',
+          message: `Translating ${result.unsupported.map((l) => languageLabel(l)).join(', ')} to ${languageLabel(lang)} isn't supported on this device.`,
+        });
+      } else {
+        setStatus({ kind: 'done', target: lang, sources: result.sources });
+      }
+    } catch (err) {
+      if (controller.signal.aborted) return;
+      console.error('[translate]', err);
+      setStatus({ kind: 'error', message: 'Translation failed. Please try again.' });
+    }
+  }, []);
+
+  // Feature detection + re-apply the reader's saved language on every page.
+  useEffect(() => {
+    const isSupported = isTranslationSupported();
+    setSupported(isSupported);
+    const saved = localStorage.getItem(STORAGE_KEY);
+    if (isSupported && saved) run(saved, false);
+    return () => abortRef.current?.abort();
+  }, [run]);
+
+  // Query per-language model availability when the panel opens.
+  useEffect(() => {
+    if (!open || !supported) return;
+    let cancelled = false;
+    const source = pageLanguage();
+    Promise.all(LANGUAGES.map(async (lang) => [lang, await translationAvailability(source, lang)] as const)).then(
+      (entries) => {
+        if (!cancelled) setAvailability(Object.fromEntries(entries));
+      },
+    );
+    return () => {
+      cancelled = true;
+    };
+  }, [open, supported, status.kind]);
+
+  // Close on outside click / Escape.
+  useEffect(() => {
+    if (!open) return;
+    const onPointer = (e: PointerEvent) => {
+      if (!containerRef.current?.contains(e.target as Node)) setOpen(false);
+    };
+    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false);
+    document.addEventListener('pointerdown', onPointer);
+    document.addEventListener('keydown', onKey);
+    return () => {
+      document.removeEventListener('pointerdown', onPointer);
+      document.removeEventListener('keydown', onKey);
+    };
+  }, [open]);
+
+  const busy = status.kind === 'translating' || status.kind === 'downloading';
+  const source = typeof document !== 'undefined' ? pageLanguage() : 'en';
+
+  return (
+    <div ref={containerRef} className="relative" translate="no">
+      <button
+        type="button"
+        onClick={() => setOpen((o) => !o)}
+        aria-expanded={open}
+        aria-controls={panelId}
+        aria-label={target ? `Translate page (currently ${languageLabel(target)})` : 'Translate page'}
+        title="Translate articles on-device"
+        className={`p-1 flex items-center gap-1 rounded ${target ? 'text-amber-500' : 'text-gray-600'} hover:text-amber-400`}
+      >
+        <LanguageIcon className={`h-6 w-6 ${busy ? 'animate-pulse' : ''}`} />
+        {target && <span className="text-xs font-semibold uppercase">{target}</span>}
+      </button>
+
+      {open && (
+        <div
+          id={panelId}
+          role="dialog"
+          aria-label="Translate articles"
+          className="absolute left-0 top-full mt-2 z-50 w-72 bg-white border border-gray-200 rounded-md shadow-lg text-sm"
+        >
+          <div className="px-4 pt-3 pb-2 border-b border-gray-100">
+            <p className="font-semibold text-gray-900">Translate articles</p>
+            <p className="text-xs text-gray-500">Runs privately on your device. Nothing is sent to a server.</p>
+          </div>
+
+          {supported === false ? (
+            <p className="px-4 py-3 text-gray-700">
+              On-device translation isn't available in this browser. Try a recent desktop version of Chrome
+              (138 or later).
+            </p>
+          ) : (
+            <>
+              <ul className="max-h-72 overflow-y-auto py-1" aria-label="Target language">
+                {target && (
+                  <li>
+                    <button
+                      type="button"
+                      onClick={() => run('', true)}
+                      className="w-full flex items-center gap-2 px-4 py-1.5 text-left text-gray-800 hover:bg-gray-50"
+                    >
+                      <ArrowUturnLeftIcon className="w-4 h-4" />
+                      Show original
+                    </button>
+                  </li>
+                )}
+                {LANGUAGES.map((lang) => {
+                  const avail = availability[lang];
+                  const isOriginal = lang === source || (lang !== 'zh-Hant' && lang === source.split('-')[0]);
+                  const disabled = avail === 'unavailable' || isOriginal;
+                  const selected = lang === target;
+                  return (
+                    <li key={lang}>
+                      <button
+                        type="button"
+                        disabled={disabled}
+                        aria-pressed={selected}
+                        onClick={() => run(lang, true)}
+                        className={`w-full flex items-center justify-between px-4 py-1.5 text-left ${
+                          disabled ? 'text-gray-300 cursor-not-allowed' : 'text-gray-800 hover:bg-gray-50'
+                        } ${selected ? 'font-semibold' : ''}`}
+                      >
+                        <span className="flex items-center gap-2">
+                          <span className="w-4">{selected && <CheckIcon className="w-4 h-4 text-amber-500" />}</span>
+                          <span>
+                            {languageLabel(lang)}
+                            <span className="text-gray-400 ml-1" lang={lang}>
+                              {languageLabel(lang, lang) !== languageLabel(lang) ? languageLabel(lang, lang) : ''}
+                            </span>
+                          </span>
+                        </span>
+                        <span className="text-[10px] uppercase tracking-wide text-gray-400">
+                          {isOriginal ? 'Original' : avail ? AVAILABILITY_HINT[avail] : ''}
+                        </span>
+                      </button>
+                    </li>
+                  );
+                })}
+              </ul>
+              <StatusLine status={status} />
+            </>
+          )}
+        </div>
+      )}
+      <span className="sr-only" aria-live="polite">
+        {status.kind === 'done' ? `Page translated to ${languageLabel(status.target)}` : ''}
+        {status.kind === 'error' ? status.message : ''}
+      </span>
+    </div>
+  );
+}
+
+function StatusLine({ status }: { status: Status }) {
+  if (status.kind === 'idle') return null;
+  let content: React.ReactNode;
+  switch (status.kind) {
+    case 'downloading':
+      content = (
+        <>
+          <span>Downloading language pack… {Math.round(status.progress * 100)}%</span>
+          <Progress value={status.progress} />
+        </>
+      );
+      break;
+    case 'translating':
+      content = (
+        <>
+          <span>Translating{status.total ? `… ${status.done}/${status.total}` : '…'}</span>
+          <Progress value={status.total ? status.done / status.total : 0} />
+        </>
+      );
+      break;
+    case 'done':
+      content = status.sources.length ? (
+        <span>
+          Translated from {status.sources.map((l) => languageLabel(l)).join(', ')} to {languageLabel(status.target)}.
+        </span>
+      ) : (
+        <span>Nothing to translate on this page.</span>
+      );
+      break;
+    case 'error':
+      content = <span className="text-red-700">{status.message}</span>;
+      break;
+  }
+  return <div className="px-4 py-2 border-t border-gray-100 text-xs text-gray-600 space-y-1">{content}</div>;
+}
+
+function Progress({ value }: { value: number }) {
+  return (
+    <div className="h-1 w-full bg-gray-100 rounded overflow-hidden">
+      <div className="h-full bg-amber-400 transition-all" style={{ width: `${Math.round(value * 100)}%` }} />
+    </div>
+  );
+}
