@@ -0,0 +1,282 @@
+/**
+ * On-device page translation built on Chrome's built-in AI APIs
+ * (Translator API + Language Detector API). Nothing leaves the browser:
+ * language models are downloaded once by the browser and run locally.
+ *
+ * Content opts in with the `data-translatable` attribute. Every text node
+ * inside such an element is translated individually, so inline markup
+ * (links, emphasis, headings inside article bodies) is preserved.
+ */
+
+export const STORAGE_KEY = 'devtools-times:translate-lang';
+
+/** Languages offered in the picker (BCP 47 tags supported by Chrome's Translator API). */
+export const LANGUAGES = [
+  'en', 'es', 'fr', 'de', 'it', 'pt', 'nl', 'pl', 'uk', 'ru', 'tr',
+  'ar', 'hi', 'bn', 'th', 'vi', 'ja', 'ko', 'zh', 'zh-Hant',
+] as const;
+
+const RTL_LANGUAGES = new Set(['ar', 'he', 'fa', 'ur']);
+const SKIP_SELECTOR = 'script, style, code, pre, kbd, samp, astro-island, [translate="no"]';
+const DETECTION_CONFIDENCE = 0.6;
+const CONCURRENCY = 3;
+
+/** Original text of every text node we have rewritten. */
+const originalText = new WeakMap<Text, string>();
+/** Original lang/dir attributes and detected source language of each translatable root. */
+const rootState = new WeakMap<HTMLElement, { lang: string | null; dir: string | null; source?: string }>();
+/** Translators are expensive to create, so keep them for the lifetime of the document (survives client-side navigation). */
+const translators = new Map<string, Promise<Translator>>();
+let detectorPromise: Promise<LanguageDetector | null> | null = null;
+
+export function isTranslationSupported(): boolean {
+  return typeof globalThis !== 'undefined' && typeof globalThis.Translator !== 'undefined';
+}
+
+export function pageLanguage(): string {
+  return document.documentElement.lang || 'en';
+}
+
+export function languageLabel(code: string, displayIn = 'en'): string {
+  try {
+    return new Intl.DisplayNames([displayIn], { type: 'language' }).of(code) ?? code;
+  } catch {
+    return code;
+  }
+}
+
+export async function translationAvailability(source: string, target: string): Promise<AIAvailability> {
+  if (!globalThis.Translator) return 'unavailable';
+  if (sameLanguage(source, target)) return 'available';
+  try {
+    return await globalThis.Translator.availability({ sourceLanguage: source, targetLanguage: target });
+  } catch {
+    return 'unavailable';
+  }
+}
+
+function sameLanguage(a: string, b: string): boolean {
+  const norm = (l: string) => l.toLowerCase();
+  if (norm(a) === norm(b)) return true;
+  // "zh" and "zh-Hant" are different targets; otherwise compare primary subtags.
+  if (a.startsWith('zh') || b.startsWith('zh')) return false;
+  return norm(a).split('-')[0] === norm(b).split('-')[0];
+}
+
+function translatableRoots(): HTMLElement[] {
+  return Array.from(document.querySelectorAll<HTMLElement>('[data-translatable]'));
+}
+
+function textNodes(root: HTMLElement): Text[] {
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const parent = node.parentElement;
+      if (!parent || parent.closest(SKIP_SELECTOR)) return NodeFilter.FILTER_REJECT;
+      const text = originalText.get(node as Text) ?? node.nodeValue ?? '';
+      return text.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
+    },
+  });
+  const nodes: Text[] = [];
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+/** Puts every translated text node and root attribute back the way it was. */
+export function restoreOriginal(): void {
+  for (const root of translatableRoots()) {
+    for (const node of textNodes(root)) {
+      const original = originalText.get(node);
+      if (original !== undefined && node.nodeValue !== original) node.nodeValue = original;
+    }
+    const state = rootState.get(root);
+    if (state && root.hasAttribute('data-translated-to')) {
+      setOrRemove(root, 'lang', state.lang);
+      setOrRemove(root, 'dir', state.dir);
+      root.removeAttribute('data-translated-to');
+    }
+  }
+}
+
+function setOrRemove(el: HTMLElement, attr: string, value: string | null) {
+  if (value === null) el.removeAttribute(attr);
+  else el.setAttribute(attr, value);
+}
+
+async function getDetector(allowDownload: boolean): Promise<LanguageDetector | null> {
+  const api = globalThis.LanguageDetector;
+  if (!api) return null;
+  if (!detectorPromise) {
+    detectorPromise = (async () => {
+      try {
+        const availability = await api.availability();
+        if (availability === 'unavailable') return null;
+        if (availability !== 'available' && !allowDownload) return null;
+        return await api.create();
+      } catch {
+        return null;
+      }
+    })();
+  }
+  const detector = await detectorPromise;
+  if (!detector) detectorPromise = null; // allow a later, user-initiated attempt
+  return detector;
+}
+
+async function sourceLanguageOf(root: HTMLElement, detector: LanguageDetector | null, fallback: string): Promise<string> {
+  const state = rootState.get(root)!;
+  if (state.source) return state.source;
+  let source = state.lang || root.closest<HTMLElement>('[lang]')?.lang || fallback;
+  if (detector) {
+    // Detect on the original (untranslated) text only.
+    const sample = textNodes(root).map((n) => originalText.get(n) ?? n.nodeValue).join(' ').slice(0, 1500);
+    try {
+      const [best] = await detector.detect(sample);
+      if (best && best.detectedLanguage !== 'und' && best.confidence >= DETECTION_CONFIDENCE) {
+        source = best.detectedLanguage;
+      }
+    } catch {
+      /* keep fallback */
+    }
+  }
+  state.source = source;
+  return source;
+}
+
+function getTranslator(
+  source: string,
+  target: string,
+  onDownloadProgress?: (fraction: number) => void,
+): Promise<Translator> {
+  const key = `${source}->${target}`;
+  let translator = translators.get(key);
+  if (!translator) {
+    translator = globalThis.Translator!.create({
+      sourceLanguage: source,
+      targetLanguage: target,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onDownloadProgress?.(e.loaded));
+      },
+    });
+    translators.set(key, translator);
+    translator.catch(() => translators.delete(key));
+  }
+  return translator;
+}
+
+export interface TranslateOptions {
+  signal: AbortSignal;
+  /** True when triggered by a user gesture: allows model downloads (which require user activation). */
+  allowDownload: boolean;
+  onDownloadProgress?: (fraction: number) => void;
+  onProgress?: (done: number, total: number) => void;
+}
+
+export interface TranslateResult {
+  translated: number;
+  /** Source languages that could not be translated into the target. */
+  unsupported: string[];
+  /** Source languages whose model needs a user-initiated download first. */
+  needsDownload: string[];
+  sources: string[];
+}
+
+/**
+ * Translates all `[data-translatable]` content on the page into `target`.
+ * Always starts from the original text, so switching languages never
+ * compounds translation errors.
+ */
+export async function translatePage(target: string, opts: TranslateOptions): Promise<TranslateResult> {
+  const { signal, allowDownload } = opts;
+  const result: TranslateResult = { translated: 0, unsupported: [], needsDownload: [], sources: [] };
+
+  restoreOriginal();
+  const roots = translatableRoots();
+  if (!roots.length) return result;
+
+  for (const root of roots) {
+    if (!rootState.has(root)) rootState.set(root, { lang: root.getAttribute('lang'), dir: root.getAttribute('dir') });
+  }
+
+  // Grab the translator for the most likely pair first, while the user
+  // activation from the click is still fresh (needed for model downloads).
+  const fallback = pageLanguage();
+  if (allowDownload && !sameLanguage(fallback, target)) {
+    getTranslator(fallback, target, opts.onDownloadProgress).catch(() => {});
+  }
+
+  const detector = await getDetector(allowDownload);
+  if (signal.aborted) return result;
+
+  // Group roots by their source language.
+  const groups = new Map<string, HTMLElement[]>();
+  for (const root of roots) {
+    const source = await sourceLanguageOf(root, detector, fallback);
+    if (signal.aborted) return result;
+    if (sameLanguage(source, target)) continue;
+    groups.set(source, [...(groups.get(source) ?? []), root]);
+  }
+  result.sources = [...groups.keys()];
+
+  // Resolve a translator per source language.
+  const jobs: { node: Text; translator: Translator }[] = [];
+  const translatedRoots: HTMLElement[] = [];
+  for (const [source, groupRoots] of groups) {
+    const availability = await translationAvailability(source, target);
+    if (signal.aborted) return result;
+    if (availability === 'unavailable') {
+      result.unsupported.push(source);
+      continue;
+    }
+    if (availability !== 'available' && !allowDownload && !translators.has(`${source}->${target}`)) {
+      result.needsDownload.push(source);
+      continue;
+    }
+    let translator: Translator;
+    try {
+      translator = await getTranslator(source, target, opts.onDownloadProgress);
+    } catch (err) {
+      if (signal.aborted) return result;
+      if (err instanceof DOMException && err.name === 'NotAllowedError') result.needsDownload.push(source);
+      else result.unsupported.push(source);
+      continue;
+    }
+    if (signal.aborted) return result;
+    for (const root of groupRoots) {
+      translatedRoots.push(root);
+      for (const node of textNodes(root)) jobs.push({ node, translator });
+    }
+  }
+
+  const total = jobs.length;
+  let done = 0;
+  opts.onProgress?.(done, total);
+
+  for (const root of translatedRoots) {
+    root.setAttribute('data-translated-to', target);
+    root.setAttribute('lang', target);
+    root.setAttribute('dir', RTL_LANGUAGES.has(target.split('-')[0]) ? 'rtl' : 'ltr');
+  }
+
+  let cursor = 0;
+  const worker = async () => {
+    while (cursor < jobs.length && !signal.aborted) {
+      const { node, translator } = jobs[cursor++];
+      const original = originalText.get(node) ?? node.nodeValue ?? '';
+      const [, lead, core, trail] = original.match(/^(\s*)([\s\S]*?)(\s*)$/)!;
+      try {
+        const translated = await translator.translate(core, { signal });
+        if (signal.aborted) return;
+        if (!originalText.has(node)) originalText.set(node, original);
+        node.nodeValue = lead + translated + trail;
+        result.translated++;
+      } catch (err) {
+        if (signal.aborted) return;
+        console.warn('[translate] Failed to translate text node', err);
+      }
+      opts.onProgress?.(++done, total);
+    }
+  };
+  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, jobs.length) }, worker));
+
+  return result;
+}

