@@ -0,0 +1,134 @@
+/**
+ * Safe HTML rendering for The Daily Grind.
+ *
+ * Every HTML string that reaches a DOM insertion sink (innerHTML,
+ * insertAdjacentHTML, ...) must go through `toTrustedHTML()`. The page's CSP
+ * enforces this via Trusted Types (`require-trusted-types-for 'script'`), so a
+ * raw string assigned to a sink throws instead of executing.
+ *
+ * The sanitizer is allowlist-based: only known-safe elements, attributes and
+ * URL schemes survive. Everything else (scripts, event handlers, inline
+ * styles, iframes, SVG, javascript:/data: URLs, ...) is stripped.
+ */
+
+const HTML_POLICY_NAME = 'daily-grind-html';
+const PARSER_POLICY_NAME = 'daily-grind-sanitizer';
+
+// Elements allowed in rendered content. Unknown elements are unwrapped
+// (their safe children are kept); dangerous ones are dropped entirely.
+const ALLOWED_TAGS = new Set([
+  'a', 'article', 'b', 'br', 'div', 'em', 'h2', 'h3', 'h4', 'i', 'img',
+  'li', 'ol', 'p', 'small', 'span', 'strong', 'ul',
+]);
+
+// Elements whose content must never be kept, even as text.
+const DROP_WITH_CONTENT = new Set([
+  'script', 'style', 'template', 'iframe', 'frame', 'frameset', 'object',
+  'embed', 'noscript', 'noembed', 'noframes', 'xmp', 'plaintext', 'svg',
+  'math', 'form', 'textarea', 'select', 'option', 'title', 'link', 'meta',
+  'base',
+]);
+
+const GLOBAL_ATTRS = new Set(['class', 'title', 'aria-label', 'aria-hidden', 'role']);
+const TAG_ATTRS = {
+  a: new Set(['href']),
+  img: new Set(['src', 'alt', 'width', 'height', 'loading', 'decoding']),
+};
+const URL_ATTRS = new Set(['href', 'src']);
+const SAFE_URL_SCHEMES = new Set(['http:', 'https:']);
+
+function isSafeUrl(value) {
+  const trimmed = value.trim();
+  if (trimmed === '') return false;
+  try {
+    // Resolves relative URLs against the page; the browser strips control
+    // chars/whitespace the same way it would when following the link.
+    const url = new URL(trimmed, document.baseURI);
+    return SAFE_URL_SCHEMES.has(url.protocol);
+  } catch {
+    return false;
+  }
+}
+
+function sanitizeAttributes(el, tag) {
+  const tagAttrs = TAG_ATTRS[tag];
+  for (const attr of Array.from(el.attributes)) {
+    const name = attr.name.toLowerCase();
+    const allowed = GLOBAL_ATTRS.has(name) || (tagAttrs && tagAttrs.has(name));
+    if (!allowed || (URL_ATTRS.has(name) && !isSafeUrl(attr.value))) {
+      el.removeAttribute(attr.name);
+    }
+  }
+  if (tag === 'a' && el.hasAttribute('href')) {
+    // Prevent reverse-tabnabbing if content ever links off-site.
+    const url = new URL(el.getAttribute('href'), document.baseURI);
+    if (url.origin !== window.location.origin) {
+      el.setAttribute('rel', 'noopener noreferrer');
+    }
+  }
+}
+
+function sanitizeNode(node) {
+  for (const child of Array.from(node.childNodes)) {
+    if (child.nodeType === Node.TEXT_NODE) continue;
+    if (child.nodeType !== Node.ELEMENT_NODE) {
+      child.remove(); // comments, processing instructions, etc.
+      continue;
+    }
+    const tag = child.localName;
+    if (child.namespaceURI !== 'http://www.w3.org/1999/xhtml' || DROP_WITH_CONTENT.has(tag)) {
+      child.remove();
+      continue;
+    }
+    sanitizeNode(child);
+    if (!ALLOWED_TAGS.has(tag)) {
+      child.replaceWith(...Array.from(child.childNodes));
+      continue;
+    }
+    sanitizeAttributes(child, tag);
+  }
+}
+
+// Internal policy used only to feed the *inert* DOMParser document (no
+// scripts run, no resources load). It is never exposed outside this module,
+// and its output is never inserted into the live page directly.
+const parserPolicy = window.trustedTypes
+  ? window.trustedTypes.createPolicy(PARSER_POLICY_NAME, { createHTML: (s) => s })
+  : null;
+
+/**
+ * Returns a sanitized HTML string. Safe to use as a fallback in browsers
+ * without Trusted Types.
+ */
+export function sanitizeHTML(dirty) {
+  const input = String(dirty ?? '');
+  const parserInput = parserPolicy ? parserPolicy.createHTML(input) : input;
+  const doc = new DOMParser().parseFromString(parserInput, 'text/html');
+  sanitizeNode(doc.body);
+  return doc.body.innerHTML;
+}
+
+// The only policy allowed to produce TrustedHTML for the live document.
+const htmlPolicy = window.trustedTypes
+  ? window.trustedTypes.createPolicy(HTML_POLICY_NAME, { createHTML: sanitizeHTML })
+  : null;
+
+/** Converts an untrusted HTML string into sink-safe (sanitized) HTML. */
+export function toTrustedHTML(dirty) {
+  return htmlPolicy ? htmlPolicy.createHTML(dirty) : sanitizeHTML(dirty);
+}
+
+/** Replaces the children of `element` with sanitized HTML. */
+export function setSafeHTML(element, dirty) {
+  element.innerHTML = toTrustedHTML(dirty);
+}
+
+/** Escapes text for interpolation into an HTML string template. */
+export function escapeHTML(value) {
+  return String(value ?? '')
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;')
+    .replace(/'/g, '&#39;');
+}
diff --git a/js/seasonal-favorites.js b/js/seasonal-favorites.js
new file mode 100644
