+++ b/js/seasonal-favorites.js
@@ -0,0 +1,53 @@
+import { escapeHTML, setSafeHTML } from './safe-html.js';
+
+const IMG = (id) =>
+  `https://images.unsplash.com/${id}?auto=format&fit=crop&w=600&q=80`;
+
+// Card data. In production this could come from a CMS or API; treat every
+// field as untrusted.
+const SEASONAL_FAVORITES = [
+  {
+    name: 'Maple Oat Latte',
+    description: 'Creamy oat milk with a hint of Vermont maple syrup.',
+    href: '/menu/seasonal',
+    image: IMG('photo-1461023058943-07fcbe16d735'),
+    imageAlt: 'A latte with oat milk in a glass',
+  },
+  {
+    name: 'Dark Roast Espresso',
+    description: 'Bold, smokey, and perfect for a morning boost.',
+    href: '/menu/espresso',
+    image: IMG('photo-1510591509098-f4fdc6d0ff04'),
+    imageAlt: 'A shot of espresso in a small cup',
+  },
+  {
+    name: 'Cold Brew',
+    description: 'Steeped for 18 hours for maximum smoothness.',
+    href: '/menu/cold-brew',
+    image: IMG('photo-1517701604599-bb29b565090c'),
+    imageAlt: 'Iced cold brew coffee in a glass',
+  },
+];
+
+// Builds a card as an HTML string. Values are escaped here (defense in
+// depth); the final string is additionally run through the sanitizing
+// Trusted Types policy before it touches the DOM.
+function cardTemplate(item) {
+  return `
+    <article class="card">
+      <img src="${escapeHTML(item.image)}" alt="${escapeHTML(item.imageAlt)}" loading="lazy" width="600" height="400">
+      <h3>${escapeHTML(item.name)}</h3>
+      <p>${escapeHTML(item.description)}</p>
+      <a href="${escapeHTML(item.href)}" class="btn">View Details</a>
+    </article>`;
+}
+
+export function renderSeasonalFavorites(container, items = SEASONAL_FAVORITES) {
+  if (!container) return;
+  const html = items.length
+    ? items.map(cardTemplate).join('')
+    : '<p class="grid-status">Check back soon for new seasonal drinks.</p>';
+  setSafeHTML(container, html);
+}
+
+renderSeasonalFavorites(document.getElementById('seasonal-favorites'));

