+/* ------------------------------------------------------------------
+ * Semantic surface context
+ *
+ * Sections declare *what kind of surface they are* via --surface;
+ * components decide on their own how to react to it. Neither side
+ * names the other, so new featured sections or new adaptive
+ * components can be added independently.
+ * ------------------------------------------------------------------ */
+[data-surface="featured"] {
+  --surface: featured;
+}
+
+[data-surface="default"] {
+  --surface: default;
+}
+
+/* Promotional badge — hidden on default surfaces */
+.teaser-badge {
+  display: none;
+  align-items: center;
+  gap: 0.25rem;
+  padding: 0.125rem 0.5rem;
+  border-radius: 9999px;
+  background: var(--color-amber-100);
+  color: var(--color-amber-900);
+  font-size: 0.6875rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  line-height: 1.25rem;
+  text-transform: uppercase;
+}
+
+/* Action button — subtle outlined variant by default */
+.action-button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  padding: 0.25rem;
+  border: 1px solid var(--color-gray-300);
+  border-radius: 0.375rem;
+  background: transparent;
+  cursor: pointer;
+  transition: background-color 150ms, border-color 150ms;
+}
+
+.action-button:hover {
+  border-color: var(--color-amber-400);
+}
+
+.action-button:focus-visible {
+  outline: 2px solid var(--color-amber-500);
+  outline-offset: 2px;
+}
+
+/* Fallback for browsers without container style queries.
+ * :where() keeps specificity equal to the style-query rules below,
+ * so those win by source order where supported. Remove once style
+ * queries are Baseline widely available. */
+:where([data-surface="featured"]) .teaser-badge {
+  display: inline-flex;
+}
+
+:where([data-surface="featured"]) .action-button {
+  border-color: var(--color-amber-700);
+  background: var(--color-amber-700);
+}
+
+:where([data-surface="featured"]) .action-button:hover {
+  border-color: var(--color-amber-800);
+  background: var(--color-amber-800);
+}
+
+:where([data-surface="featured"]) .action-button svg {
+  color: white;
+}
+
+/* Prominent featured presentation, driven by the inherited flag */
+@container style(--surface: featured) {
+  .teaser-badge {
+    display: inline-flex;
+  }
+
+  .action-button {
+    border-color: var(--color-amber-700);
+    background: var(--color-amber-700);
+  }
+
+  .action-button:hover {
+    border-color: var(--color-amber-800);
+    background: var(--color-amber-800);
+  }
+
+  .action-button svg {
+    color: white;
+  }
+}
+

