+}
+/*
+ * Context-aware teaser presentation
+ * ---------------------------------
+ * Sections declare their semantic context via `data-teaser-context`
+ * ("featured" | "default"). That context is exposed as the inherited
+ * `--teaser-variant` custom property, and teaser cards adapt to it with
+ * CSS container style queries — the cards themselves need no props.
+ *
+ *   default  → badge hidden, outlined action button (subtle)
+ *   featured → promotional badge shown, filled action button (prominent)
+ */
+@property --teaser-variant {
+  syntax: "featured | default";
+  inherits: true;
+  initial-value: default;
+}
+
+[data-teaser-context="featured"] {
+  --teaser-variant: featured;
+}
+
+[data-teaser-context="default"] {
+  --teaser-variant: default;
+}
+
+@layer components {
+  /* Default (subtle) presentation */
+  .teaser-badge {
+    display: none;
+    align-items: center;
+    gap: 0.25rem;
+    width: fit-content;
+    padding: 0.125rem 0.5rem;
+    border-radius: 9999px;
+    background-color: var(--color-amber-400);
+    color: var(--color-gray-900);
+    font-size: 0.6875rem;
+    font-weight: 700;
+    letter-spacing: 0.08em;
+    line-height: 1.25rem;
+    text-transform: uppercase;
+  }
+
+  .teaser-action {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.25rem;
+    padding: 0.25rem 0.75rem;
+    border: 1px solid var(--color-gray-300);
+    border-radius: 0.375rem;
+    background-color: transparent;
+    color: var(--color-gray-700);
+    font-size: 0.8125rem;
+    font-weight: 600;
+    line-height: 1.25rem;
+    white-space: nowrap;
+    transition: background-color 150ms, border-color 150ms, color 150ms;
+  }
+
+  .teaser-action:hover,
+  .teaser-action:focus-visible {
+    border-color: var(--color-amber-400);
+    color: var(--color-amber-800);
+  }
+
+  /* Featured (prominent) presentation */
+  @container style(--teaser-variant: featured) {
+    .teaser-badge {
+      display: inline-flex;
+    }
+
+    .teaser-action {
+      border-color: var(--color-gray-900);
+      background-color: var(--color-gray-900);
+      color: var(--color-white);
+    }
+
+    .teaser-action:hover,
+    .teaser-action:focus-visible {
+      border-color: var(--color-amber-400);
+      background-color: var(--color-amber-400);
+      color: var(--color-gray-900);
+    }
+  }
+}

