--- /dev/null
+++ b/server.js
@@ -0,0 +1,311 @@
+// The Daily Grind web server.
+//
+// - GET  /                         Homepage, rendered with a fresh single-use EVP nonce.
+// - POST /api/rewards/signup       Rewards sign-up. Verifies the browser-issued Email
+//                                  Verification Token; falls back to a confirmation
+//                                  email link when it is absent or invalid.
+// - GET  /api/rewards/confirm      Fallback confirmation link target.
+//
+// Environment:
+//   PORT                          Port to listen on (default 11222)
+//   RP_ORIGIN                     Public origin of this site, e.g. https://dailygrind.example
+//                                 (must match exactly what the browser sees; used as KB-JWT aud)
+//   EMAIL_VERIFICATION_OT_TOKEN   Chrome Origin Trial token for the Email Verification API
+
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { randomBytes, scrypt, createHash } from 'node:crypto';
+import { promisify } from 'node:util';
+import { verifyEmailVerificationToken } from './lib/email-verification.js';
+
+const scryptAsync = promisify(scrypt);
+
+const PORT = Number(process.env.PORT) || 11222;
+const RP_ORIGIN = (process.env.RP_ORIGIN || `http://localhost:${PORT}`).replace(/\/+$/, '');
+const OT_TOKEN = process.env.EMAIL_VERIFICATION_OT_TOKEN || '';
+const SECURE_COOKIES = RP_ORIGIN.startsWith('https://');
+
+const SESSION_COOKIE = 'dg_sid';
+const SESSION_TTL_MS = 30 * 60 * 1000;
+const NONCE_TTL_MS = 10 * 60 * 1000;
+const CONFIRM_TTL_MS = 24 * 60 * 60 * 1000;
+const MAX_BODY_BYTES = 32 * 1024;
+
+const template = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+
+// ---------------------------------------------------------------------------
+// Storage (in-memory). Swap for a real database / session store in production;
+// nonce consumption must stay atomic (e.g. Redis GETDEL) when you do.
+// ---------------------------------------------------------------------------
+
+/** @type {Map<string, {nonce?: string, nonceExpires?: number, flash?: string, expires: number}>} */
+const sessions = new Map();
+/** @type {Map<string, {name: string, email: string, passwordHash: string, emailVerified: boolean, verifiedVia?: string, createdAt: number}>} */
+const accounts = new Map();
+/** @type {Map<string, {emailKey: string, expires: number}>} keyed by sha256(token) */
+const pendingConfirmations = new Map();
+
+setInterval(() => {
+  const now = Date.now();
+  for (const [id, s] of sessions) if (s.expires < now) sessions.delete(id);
+  for (const [id, p] of pendingConfirmations) if (p.expires < now) pendingConfirmations.delete(id);
+}, 60 * 1000).unref();
+
+const emailKey = (email) => email.toLowerCase();
+const sha256 = (value) => createHash('sha256').update(value).digest('base64url');
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+  }
+  return out;
+}
+
+/** Get or create the session for this request, refreshing the cookie. */
+function getSession(req, res) {
+  const now = Date.now();
+  let id = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  let session = id && sessions.get(id);
+  if (!session || session.expires < now) {
+    id = randomBytes(32).toString('base64url');
+    session = { expires: 0 };
+    sessions.set(id, session);
+  }
+  session.expires = now + SESSION_TTL_MS;
+  res.setHeader(
+    'Set-Cookie',
+    `${SESSION_COOKIE}=${id}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${SESSION_TTL_MS / 1000}${SECURE_COOKIES ? '; Secure' : ''}`,
+  );
+  return session;
+}
+
+/** Atomically read and delete the session's single-use nonce. */
+function consumeSessionNonce(session) {
+  const { nonce, nonceExpires } = session;
+  delete session.nonce;
+  delete session.nonceExpires;
+  return nonce && nonceExpires > Date.now() ? nonce : null;
+}
+
+// ---------------------------------------------------------------------------
+// Accounts
+// ---------------------------------------------------------------------------
+
+async function hashPassword(password) {
+  const salt = randomBytes(16);
+  const key = await scryptAsync(password.normalize('NFKC'), salt, 64);
+  return `scrypt$${salt.toString('base64url')}$${key.toString('base64url')}`;
+}
+
+/**
+ * Fallback path: email a confirmation link. Replace the console output with your
+ * transactional email provider.
+ */
+async function sendTraditionalVerificationEmail(email, { alreadyRegistered }) {
+  if (alreadyRegistered) {
+    console.info(`[email] to=${email}: "Someone tried to create a Daily Grind Rewards account with this address. You already have one — sign in or reset your password."`);
+    return;
+  }
+  const token = randomBytes(32).toString('base64url');
+  pendingConfirmations.set(sha256(token), { emailKey: emailKey(email), expires: Date.now() + CONFIRM_TTL_MS });
+  console.info(`[email] to=${email}: "Confirm your Daily Grind Rewards account: ${RP_ORIGIN}/api/rewards/confirm?token=${token}"`);
+}
+
+// ---------------------------------------------------------------------------
+// HTTP helpers
+// ---------------------------------------------------------------------------
+
+const SECURITY_HEADERS = {
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, 'Content-Type': 'text/plain; charset=utf-8', ...headers });
+  res.end(body);
+}
+
+function redirect(res, location) {
+  res.writeHead(303, { ...SECURITY_HEADERS, Location: location, 'Cache-Control': 'no-store' });
+  res.end();
+}
+
+async function readForm(req) {
+  const type = req.headers['content-type'] || '';
+  if (!type.startsWith('application/x-www-form-urlencoded')) throw Object.assign(new Error('Unsupported media type'), { status: 415 });
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > MAX_BODY_BYTES) throw Object.assign(new Error('Payload too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
+}
+
+// Flash messages are fixed server strings keyed by status — never echo user input.
+const FLASH = {
+  verified: { kind: 'success', text: 'Welcome to Daily Grind Rewards! Your email address was confirmed instantly, so your account is ready to use.' },
+  pending: { kind: 'info', text: 'Almost there! We sent a confirmation link to your inbox. Open it to activate your rewards account.' },
+  exists: { kind: 'info', text: 'You already have a Daily Grind Rewards account with this email address. Sign in from My Account instead.' },
+  confirmed: { kind: 'success', text: 'Thanks! Your email address is confirmed and your rewards account is active.' },
+  'confirm-invalid': { kind: 'error', text: 'That confirmation link is invalid or has expired. Please sign up again.' },
+  invalid: { kind: 'error', text: 'Some details were missing or invalid. Please check the form and try again.' },
+  expired: { kind: 'error', text: 'Your sign-up form expired. Please try again.' },
+};
+
+function renderHome(session) {
+  // Fresh single-use nonce (256 bits) per render, stored server-side only.
+  const nonce = randomBytes(32).toString('base64url');
+  session.nonce = nonce;
+  session.nonceExpires = Date.now() + NONCE_TTL_MS;
+
+  const flash = session.flash && FLASH[session.flash];
+  delete session.flash;
+  const status = flash
+    ? `<p class="signup-status signup-status--${flash.kind}">${flash.text}</p>`
+    : '';
+
+  return template.replace('{{EVT_NONCE}}', nonce).replace('<!--SIGNUP_STATUS-->', status);
+}
+
+// ---------------------------------------------------------------------------
+// Routes
+// ---------------------------------------------------------------------------
+
+async function handleSignup(req, res) {
+  // CSRF defence in depth (the session cookie is also SameSite=Lax).
+  const origin = req.headers.origin;
+  if (origin && origin !== RP_ORIGIN) return send(res, 403, 'Forbidden');
+
+  const session = getSession(req, res);
+  // Consume the nonce first so a token can never be replayed, even if parsing fails.
+  const expectedNonce = consumeSessionNonce(session);
+
+  let form;
+  try {
+    form = await readForm(req);
+  } catch (err) {
+    return send(res, err.status || 400, err.message);
+  }
+
+  const name = String(form.get('name') || '').trim();
+  const email = String(form.get('email') || '').trim();
+  const password = String(form.get('new-password') || '');
+  const rawToken = String(form.get('email-verification-token') || '').trim();
+
+  const emailLooksValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
+  const passwordValid = password.length >= 8 && password.length <= 128;
+  if (!name || name.length > 100 || !emailLooksValid || !passwordValid) {
+    session.flash = 'invalid';
+    return redirect(res, '/#rewards');
+  }
+  if (!expectedNonce) {
+    session.flash = 'expired';
+    return redirect(res, '/#rewards');
+  }
+
+  // Fast path: the browser vouched for the email via the user's email provider.
+  let verified = false;
+  if (rawToken) {
+    try {
+      await verifyEmailVerificationToken({ rawToken, submittedEmail: email, expectedNonce, expectedAudience: RP_ORIGIN });
+      verified = true;
+    } catch (err) {
+      console.warn('Email verification token check failed; falling back to email link:', err?.message || err);
+    }
+  }
+
+  const key = emailKey(email);
+  const existing = accounts.get(key);
+
+  if (existing?.emailVerified) {
+    if (verified) {
+      // The submitter proved ownership, so it is safe to tell them directly.
+      session.flash = 'exists';
+    } else {
+      // Don't reveal registration status to someone who hasn't proven ownership.
+      await sendTraditionalVerificationEmail(email, { alreadyRegistered: true });
+      session.flash = 'pending';
+    }
+    return redirect(res, '/#rewards');
+  }
+
+  // New account, or replacing an unconfirmed pending one.
+  accounts.set(key, {
+    name,
+    email,
+    passwordHash: await hashPassword(password),
+    emailVerified: verified,
+    verifiedVia: verified ? 'email-verification-protocol' : undefined,
+    createdAt: Date.now(),
+  });
+
+  if (verified) {
+    session.flash = 'verified';
+  } else {
+    await sendTraditionalVerificationEmail(email, { alreadyRegistered: false });
+    session.flash = 'pending';
+  }
+  return redirect(res, '/#rewards');
+}
+
+function handleConfirm(req, res, url) {
+  const session = getSession(req, res);
+  const token = url.searchParams.get('token') || '';
+  const hashed = sha256(token);
+  const pending = pendingConfirmations.get(hashed);
+  pendingConfirmations.delete(hashed);
+  const account = pending && pending.expires > Date.now() && accounts.get(pending.emailKey);
+  if (account) {
+    account.emailVerified = true;
+    account.verifiedVia = 'email-link';
+    session.flash = 'confirmed';
+  } else {
+    session.flash = 'confirm-invalid';
+  }
+  return redirect(res, '/#rewards');
+}
+
+const server = createServer(async (req, res) => {
+  try {
+    const url = new URL(req.url, RP_ORIGIN);
+
+    if (url.pathname === '/' || url.pathname === '/index.html') {
+      if (req.method !== 'GET' && req.method !== 'HEAD') return send(res, 405, 'Method Not Allowed', { Allow: 'GET, HEAD' });
+      const session = getSession(req, res);
+      const headers = {
+        ...SECURITY_HEADERS,
+        'Content-Type': 'text/html; charset=utf-8',
+        // The page embeds a single-use nonce; never let bfcache/proxies reuse it.
+        'Cache-Control': 'no-store',
+      };
+      if (OT_TOKEN) headers['Origin-Trial'] = OT_TOKEN;
+      res.writeHead(200, headers);
+      return res.end(req.method === 'HEAD' ? undefined : renderHome(session));
+    }
+
+    if (url.pathname === '/api/rewards/signup') {
+      if (req.method !== 'POST') return send(res, 405, 'Method Not Allowed', { Allow: 'POST' });
+      return await handleSignup(req, res);
+    }
+
+    if (url.pathname === '/api/rewards/confirm') {
+      if (req.method !== 'GET') return send(res, 405, 'Method Not Allowed', { Allow: 'GET' });
+      return handleConfirm(req, res, url);
+    }
+
+    return send(res, 404, 'Not Found');
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) send(res, 500, 'Internal Server Error');
+    else res.end();
+  }
+});
+
+server.listen(PORT, () => {
+  console.info(`The Daily Grind listening on port ${PORT} (RP origin ${RP_ORIGIN})`);
+});

