+// Rewards sign-up with browser-native email verification (Email Verification Protocol).
+// When the shopper picks their address from the browser's email autofill, a
+// supporting browser asks their email provider to vouch for it and fires an
+// `emailverified` event with a signed token. We forward that token to the
+// server, which verifies it. No passcode or magic link email is ever sent.
+(() => {
+  const form = document.getElementById('rewards-form');
+  if (!form) return;
+
+  const emailInput = form.querySelector('#rewards-email');
+  const status = form.querySelector('#email-status');
+  const message = form.querySelector('#rewards-message');
+  const submitBtn = form.querySelector('button[type="submit"]');
+  const success = document.getElementById('rewards-success');
+
+  const IDLE_TEXT = 'Tip: choose your email from your browser’s autofill to verify it instantly. No code needed.';
+  let verifiedEmail = null;
+  let verifying = null;
+
+  const setStatus = (state, text) => {
+    status.dataset.state = state;
+    status.textContent = text;
+  };
+
+  async function post(path, body = {}) {
+    try {
+      const res = await fetch(path, {
+        method: 'POST',
+        credentials: 'same-origin',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(body),
+      });
+      let data = {};
+      try { data = await res.json(); } catch { /* empty body */ }
+      return { ok: res.ok, status: res.status, data };
+    } catch {
+      return { ok: false, status: 0, data: { error: 'Network error. Please check your connection.' } };
+    }
+  }
+
+  // Bind a fresh, single-use server nonce to the email field. The browser
+  // embeds it in the token's key-binding JWT, so tokens can't be replayed.
+  async function armNonce() {
+    const { ok, data } = await post('/api/email-verification/nonce');
+    if (ok && data.nonce) {
+      emailInput.setAttribute('nonce', data.nonce);
+      emailInput.nonce = data.nonce;
+    }
+  }
+
+  async function verifyToken(token) {
+    setStatus('pending', 'Confirming your email with your provider…');
+    const email = emailInput.value.trim();
+    const { ok, data } = await post('/api/email-verification/verify', {
+      presentationToken: token,
+      ...(email ? { email } : {}),
+    });
+
+    if (ok && data.verified) {
+      verifiedEmail = data.email;
+      if (!emailInput.value.trim()) emailInput.value = data.email;
+      setStatus('verified', `✓ Email verified by ${data.issuer}`);
+    } else {
+      verifiedEmail = null;
+      setStatus('error', `${data.error || 'We couldn’t confirm that email.'} You can still join and verify later.`);
+    }
+    await armNonce(); // nonce was consumed either way
+  }
+
+  emailInput.addEventListener('emailverified', (event) => {
+    const token = event.presentationToken;
+    if (typeof token !== 'string' || !token) return;
+    verifying = verifyToken(token).finally(() => { verifying = null; });
+  });
+
+  emailInput.addEventListener('input', () => {
+    if (verifiedEmail && emailInput.value.trim().toLowerCase() !== verifiedEmail) {
+      verifiedEmail = null;
+      setStatus('idle', IDLE_TEXT);
+    }
+  });
+
+  function showFieldErrors(fields = {}) {
+    form.querySelectorAll('[data-error-for]').forEach((el) => {
+      const msg = fields[el.dataset.errorFor] || '';
+      el.textContent = msg;
+      const input = form.elements[el.dataset.errorFor];
+      if (input) input.setAttribute('aria-invalid', msg ? 'true' : 'false');
+    });
+  }
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    message.textContent = '';
+    message.dataset.state = '';
+    showFieldErrors();
+
+    if (verifying) await verifying; // don't race an in-flight verification
+
+    submitBtn.disabled = true;
+    submitBtn.textContent = 'Creating your account…';
+
+    const fd = new FormData(form);
+    const { ok, data } = await post('/api/rewards/signup', {
+      firstName: fd.get('firstName'),
+      email: fd.get('email'),
+      birthday: fd.get('birthday'),
+      favoriteDrink: fd.get('favoriteDrink'),
+      marketingOptIn: fd.get('marketingOptIn') === 'on',
+      acceptTerms: fd.get('acceptTerms') === 'on',
+    });
+
+    submitBtn.disabled = false;
+    submitBtn.textContent = 'Join Daily Grind Rewards';
+
+    if (!ok) {
+      showFieldErrors(data.fields);
+      message.dataset.state = 'error';
+      message.textContent = data.error || 'Something went wrong. Please try again.';
+      return;
+    }
+
+    const { member } = data;
+    form.hidden = true;
+    success.hidden = false;
+    success.querySelector('[data-name]').textContent = member.firstName;
+    success.querySelector('[data-detail]').textContent = member.emailVerified
+      ? `Your email ${member.email} is verified and your account is active. We've added ${member.points} welcome points!`
+      : `Your account for ${member.email} is created. Your welcome points unlock once your email is verified. Choose your address from your browser's autofill next time you sign in.`;
+    success.focus();
+  });
+
+  setStatus('idle', IDLE_TEXT);
+  armNonce();
+})();
