+// Server-side verifier for the browser Email Verification Protocol (EVP).
+//
+// Flow (see https://github.com/WICG/email-verification-protocol):
+//   1. The page puts a server-issued `nonce` on an <input autocomplete="email">.
+//   2. When the user picks an address from autofill, the browser discovers the
+//      email domain's issuer via DNS (`_email-verification.<domain>` TXT
+//      "iss=<issuer>"), obtains an issuer-signed SD-JWT bound to a browser key,
+//      appends a Key Binding JWT (aud = our origin, nonce = our nonce) and fires
+//      an `emailverified` event carrying the SD-JWT+KB presentation token.
+//   3. This module checks every link of that chain before we trust the email.
+
+import { createHash, createPublicKey, timingSafeEqual, verify as cryptoVerify, constants } from 'node:crypto';
+
+export class VerificationError extends Error {
+  constructor(code, message) {
+    super(message);
+    this.name = 'VerificationError';
+    this.code = code;
+  }
+}
+
+const fail = (code, message) => {
+  throw new VerificationError(code, message);
+};
+
+const SD_JWT_TYPES = new Set(['evp+sd-jwt', 'web-identity+sd-jwt']);
+const KB_JWT_TYPE = 'kb+jwt';
+const MAX_TOKEN_LENGTH = 16 * 1024;
+
+// Asymmetric algorithms only; "none" and HMAC algorithms are never accepted.
+const ALGORITHMS = {
+  ES256: { hash: 'sha256', kty: 'EC', crv: 'P-256', dsaEncoding: 'ieee-p1363' },
+  ES384: { hash: 'sha384', kty: 'EC', crv: 'P-384', dsaEncoding: 'ieee-p1363' },
+  ES512: { hash: 'sha512', kty: 'EC', crv: 'P-521', dsaEncoding: 'ieee-p1363' },
+  RS256: { hash: 'sha256', kty: 'RSA' },
+  PS256: { hash: 'sha256', kty: 'RSA', padding: constants.RSA_PKCS1_PSS_PADDING, saltLength: 32 },
+  EdDSA: { hash: null, kty: 'OKP', crv: 'Ed25519' },
+};
+
+const B64URL_RE = /^[A-Za-z0-9_-]+$/;
+const HOSTNAME_RE = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$/;
+
+export const isValidHostname = (value) => typeof value === 'string' && HOSTNAME_RE.test(value);
+
+export const base64url = (buf) => Buffer.from(buf).toString('base64url');
+
+export const normalizeEmail = (value) => (typeof value === 'string' ? value.trim().toLowerCase() : '');
+
+function decodeSegment(segment, what) {
+  if (!segment || !B64URL_RE.test(segment)) fail('malformed_token', `Malformed ${what}`);
+  return Buffer.from(segment, 'base64url');
+}
+
+function parseJson(buf, what) {
+  try {
+    const value = JSON.parse(buf.toString('utf8'));
+    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('not an object');
+    return value;
+  } catch {
+    return fail('malformed_token', `Malformed ${what}`);
+  }
+}
+
+export function parseJwt(compact, what = 'JWT') {
+  const parts = compact.split('.');
+  if (parts.length !== 3) fail('malformed_token', `Malformed ${what}`);
+  const header = parseJson(decodeSegment(parts[0], `${what} header`), `${what} header`);
+  const payload = parseJson(decodeSegment(parts[1], `${what} payload`), `${what} payload`);
+  const signature = decodeSegment(parts[2], `${what} signature`);
+  if (header.crit !== undefined) fail('unsupported_token', `${what} uses unsupported critical headers`);
+  return { header, payload, signature, signingInput: `${parts[0]}.${parts[1]}` };
+}
+
+// Rebuild the JWK with public members only, so a key that (wrongly) carries
+// private parameters can never be used to *sign* anything on our side.
+function toPublicJwk(jwk) {
+  switch (jwk.kty) {
+    case 'EC':
+      return { kty: 'EC', crv: jwk.crv, x: jwk.x, y: jwk.y };
+    case 'RSA':
+      return { kty: 'RSA', n: jwk.n, e: jwk.e };
+    case 'OKP':
+      return { kty: 'OKP', crv: jwk.crv, x: jwk.x };
+    default:
+      return fail('unsupported_key', 'Unsupported key type');
+  }
+}
+
+export function verifyJwsSignature(jwt, jwk, what = 'JWT') {
+  const alg = jwt.header.alg;
+  const spec = Object.hasOwn(ALGORITHMS, alg) ? ALGORITHMS[alg] : null;
+  if (!spec) fail('unsupported_alg', `${what} uses an unsupported algorithm`);
+  if (!jwk || typeof jwk !== 'object') fail('unsupported_key', `${what} key is missing`);
+  if (jwk.kty !== spec.kty || (spec.crv && jwk.crv !== spec.crv)) {
+    fail('key_mismatch', `${what} key does not match its algorithm`);
+  }
+  if (jwk.alg !== undefined && jwk.alg !== alg) fail('key_mismatch', `${what} key is restricted to another algorithm`);
+  if (jwk.use !== undefined && jwk.use !== 'sig') fail('key_mismatch', `${what} key is not a signing key`);
+
+  let key;
+  try {
+    key = createPublicKey({ key: toPublicJwk(jwk), format: 'jwk' });
+  } catch {
+    fail('unsupported_key', `${what} key is invalid`);
+  }
+  if (spec.kty === 'RSA' && (key.asymmetricKeyDetails?.modulusLength ?? 0) < 2048) {
+    fail('unsupported_key', `${what} RSA key is too short`);
+  }
+
+  const options = { key };
+  if (spec.dsaEncoding) options.dsaEncoding = spec.dsaEncoding;
+  if (spec.padding) {
+    options.padding = spec.padding;
+    options.saltLength = spec.saltLength;
+  }
+
+  let ok = false;
+  try {
+    ok = cryptoVerify(spec.hash, Buffer.from(jwt.signingInput), options, jwt.signature);
+  } catch {
+    ok = false;
+  }
+  if (!ok) fail('bad_signature', `${what} signature is invalid`);
+}
+
+function safeEqual(a, b) {
+  const ab = Buffer.from(String(a));
+  const bb = Buffer.from(String(b));
+  return ab.length === bb.length && timingSafeEqual(ab, bb);
+}
+
+// `iss` may be expressed as a bare host ("issuer.example") or an https origin.
+export function normalizeIssuer(iss) {
+  if (typeof iss !== 'string' || !iss) return null;
+  let host = iss.trim().toLowerCase();
+  if (host.includes('://')) {
+    let url;
+    try {
+      url = new URL(host);
+    } catch {
+      return null;
+    }
+    if (url.protocol !== 'https:' || url.username || url.password || url.port) return null;
+    if ((url.pathname !== '/' && url.pathname !== '') || url.search || url.hash) return null;
+    host = url.hostname;
+  }
+  host = host.replace(/\.$/, '');
+  return isValidHostname(host) ? host : null;
+}
+
+function checkTime(value, what, nowSec, { maxAgeSec, skewSec }) {
+  if (!Number.isFinite(value)) fail('missing_claim', `${what} is missing iat`);
+  if (value > nowSec + skewSec) fail('not_yet_valid', `${what} was issued in the future`);
+  if (nowSec - value > maxAgeSec) fail('expired', `${what} is too old`);
+}
+
+/**
+ * Verify an EVP SD-JWT+KB presentation token.
+ *
+ * @param {string} token                 `<issuer-signed JWT>~<KB-JWT>`
+ * @param {object} opts
+ * @param {string}   opts.expectedNonce  nonce we issued to this browser session
+ * @param {string[]} opts.audiences      acceptable `aud` values (our origin(s))
+ * @param {string}  [opts.expectedEmail] email the form submitted (must match if given)
+ * @param {(domain: string) => Promise<string>} opts.discoverIssuer  DNS lookup of the email domain's issuer
+ * @param {(url: string) => Promise<object>}    opts.fetchJson       hardened HTTPS JSON fetcher
+ * @returns {Promise<{ email: string, issuer: string }>}
+ */
+export async function verifyEmailPresentation(token, opts) {
+  const {
+    expectedNonce,
+    audiences,
+    expectedEmail,
+    discoverIssuer,
+    fetchJson,
+    now = Date.now(),
+    skewSec = 60,
+    kbMaxAgeSec = 300,
+    issuerMaxAgeSec = 600,
+  } = opts;
+  const nowSec = Math.floor(now / 1000);
+
+  if (typeof token !== 'string' || !token || token.length > MAX_TOKEN_LENGTH) {
+    fail('malformed_token', 'Missing or oversized presentation token');
+  }
+  if (!expectedNonce) fail('nonce_missing', 'No verification nonce is active for this session');
+
+  // --- 1. Split SD-JWT+KB --------------------------------------------------
+  const parts = token.split('~');
+  if (parts.length < 2) fail('malformed_token', 'Token is not an SD-JWT+KB presentation');
+  const kbCompact = parts.pop();
+  const [issuerCompact, ...disclosures] = parts;
+  if (!kbCompact) fail('malformed_token', 'Token has no key binding JWT');
+  // EVP tokens carry email/email_verified as plain claims; no disclosures expected.
+  if (disclosures.length) fail('unsupported_token', 'Unexpected selective disclosures');
+
+  const sdJwt = parseJwt(issuerCompact, 'Issuer token');
+  const kbJwt = parseJwt(kbCompact, 'Key binding token');
+
+  if (!SD_JWT_TYPES.has(sdJwt.header.typ)) fail('wrong_type', 'Issuer token has the wrong type');
+  if (kbJwt.header.typ !== KB_JWT_TYPE) fail('wrong_type', 'Key binding token has the wrong type');
+
+  // --- 2. Issuer token claims (cheap checks before any network I/O) ----------
+  const claims = sdJwt.payload;
+  const email = normalizeEmail(claims.email);
+  const at = email.lastIndexOf('@');
+  if (!email || at < 1 || email.length > 254) fail('missing_claim', 'Issuer token has no valid email');
+  if (claims.email_verified !== true) fail('email_not_verified', 'Issuer did not assert the email is verified');
+  if (expectedEmail !== undefined && normalizeEmail(expectedEmail) !== email) {
+    fail('email_mismatch', 'Verified email does not match the email entered');
+  }
+  const domain = email.slice(at + 1);
+  if (!isValidHostname(domain)) fail('missing_claim', 'Email domain is invalid');
+
+  const claimedIssuer = normalizeIssuer(claims.iss);
+  if (!claimedIssuer) fail('missing_claim', 'Issuer token has no valid iss');
+  checkTime(claims.iat, 'Issuer token', nowSec, { maxAgeSec: issuerMaxAgeSec, skewSec });
+  if (claims.exp !== undefined && !(Number.isFinite(claims.exp) && claims.exp > nowSec - skewSec)) {
+    fail('expired', 'Issuer token has expired');
+  }
+  if (claims.nbf !== undefined && !(Number.isFinite(claims.nbf) && claims.nbf <= nowSec + skewSec)) {
+    fail('not_yet_valid', 'Issuer token is not yet valid');
+  }
+
+  // --- 3. Key binding: proves *this* browser, *our* origin, *this* nonce -----
+  const cnfJwk = claims.cnf?.jwk;
+  if (!cnfJwk || typeof cnfJwk !== 'object') fail('missing_claim', 'Issuer token has no bound key');
+  verifyJwsSignature(kbJwt, cnfJwk, 'Key binding token');
+
+  const kb = kbJwt.payload;
+  if (typeof kb.aud !== 'string' || !audiences.includes(kb.aud)) fail('wrong_audience', 'Token was not issued for this site');
+  if (typeof kb.nonce !== 'string' || !safeEqual(kb.nonce, expectedNonce)) fail('wrong_nonce', 'Token nonce does not match');
+  checkTime(kb.iat, 'Key binding token', nowSec, { maxAgeSec: kbMaxAgeSec, skewSec });
+  const expectedSdHash = base64url(createHash('sha256').update(`${issuerCompact}~`).digest());
+  if (typeof kb.sd_hash !== 'string' || !safeEqual(kb.sd_hash, expectedSdHash)) {
+    fail('bad_sd_hash', 'Key binding token is not bound to this issuer token');
+  }
+
+  // --- 4. Issuer authority: DNS says who may vouch for this email domain -----
+  let issuerHost;
+  try {
+    issuerHost = normalizeIssuer(await discoverIssuer(domain));
+  } catch {
+    issuerHost = null;
+  }
+  if (!issuerHost) fail('issuer_unknown', 'Email domain does not publish an email verification issuer');
+  if (issuerHost !== claimedIssuer) fail('issuer_mismatch', 'Token issuer is not authorized for this email domain');
+
+  // --- 5. Issuer signature via its published metadata / JWKS -----------------
+  let metadata;
+  try {
+    metadata = await fetchJson(`https://${issuerHost}/.well-known/email-verification`);
+  } catch {
+    fail('issuer_unreachable', 'Could not load issuer metadata');
+  }
+  let jwksUrl;
+  try {
+    jwksUrl = new URL(metadata?.jwks_uri);
+  } catch {
+    fail('issuer_metadata', 'Issuer metadata has no valid jwks_uri');
+  }
+  if (jwksUrl.protocol !== 'https:') fail('issuer_metadata', 'Issuer jwks_uri must use https');
+  if (Array.isArray(metadata.signing_alg_values_supported) && !metadata.signing_alg_values_supported.includes(sdJwt.header.alg)) {
+    fail('unsupported_alg', 'Issuer token algorithm is not advertised by the issuer');
+  }
+
+  let jwks;
+  try {
+    jwks = await fetchJson(jwksUrl.href);
+  } catch {
+    fail('issuer_unreachable', 'Could not load issuer keys');
+  }
+  const keys = Array.isArray(jwks?.keys) ? jwks.keys.filter((k) => k && typeof k === 'object') : [];
+  const kid = sdJwt.header.kid;
+  let candidates = kid !== undefined ? keys.filter((k) => k.kid === kid) : keys;
+  if (kid === undefined && candidates.length !== 1) fail('key_not_found', 'Issuer token has no kid');
+  if (candidates.length !== 1) fail('key_not_found', 'Issuer signing key not found');
+  verifyJwsSignature(sdJwt, candidates[0], 'Issuer token');
+
+  return { email, issuer: issuerHost };
+}
