new file mode 100644
index 0000000..cedeeb3
--- /dev/null
+++ b/lib/issuer-discovery.js
@@ -0,0 +1,115 @@
+// Network helpers for EVP issuer discovery: DNS TXT lookup and a hardened
+// HTTPS JSON fetcher. The issuer host comes from DNS records an attacker may
+// control, so outbound requests are restricted to public IPs (checked at
+// connect time, which also defeats DNS rebinding), never follow redirects,
+// and are bounded in time and size.
+
+import dns from 'node:dns';
+import https from 'node:https';
+import net from 'node:net';
+import { isValidHostname } from './email-verification.js';
+
+const blockedV4 = new net.BlockList();
+const blockedV6 = new net.BlockList();
+for (const [addr, prefix] of [
+  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16],
+  ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
+  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
+]) blockedV4.addSubnet(addr, prefix, 'ipv4');
+for (const [addr, prefix] of [
+  ['::', 128], ['::1', 128], ['::ffff:0:0', 96], ['64:ff9b::', 96], ['100::', 64],
+  ['2001:db8::', 32], ['fc00::', 7], ['fe80::', 10], ['ff00::', 8],
+]) blockedV6.addSubnet(addr, prefix, 'ipv6');
+
+export function isPublicAddress(address) {
+  const family = net.isIP(address);
+  if (family === 4) return !blockedV4.check(address, 'ipv4');
+  if (family === 6) {
+    // IPv4-mapped (::ffff:a.b.c.d) is judged by its IPv4 address; any other
+    // spelling of the mapped range (e.g. ::ffff:7f00:1) falls into blockedV6.
+    const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/i.exec(address);
+    if (mapped) return !blockedV4.check(mapped[1], 'ipv4');
+    return !blockedV6.check(address, 'ipv6');
+  }
+  return false;
+}
+
+function publicOnlyLookup(hostname, options, callback) {
+  dns.lookup(hostname, { all: true }, (err, addresses) => {
+    if (err) return callback(err);
+    if (!addresses.length || addresses.some((a) => !isPublicAddress(a.address))) {
+      return callback(Object.assign(new Error(`Refusing to connect to non-public address for ${hostname}`), { code: 'EBLOCKED' }));
+    }
+    if (options?.all) return callback(null, addresses);
+    return callback(null, addresses[0].address, addresses[0].family);
+  });
+}
+
+export function fetchJsonSafely(url, { timeoutMs = 5000, maxBytes = 64 * 1024 } = {}) {
+  return new Promise((resolve, reject) => {
+    const target = new URL(url);
+    if (target.protocol !== 'https:' || target.username || target.password) {
+      return reject(new Error('Only plain https URLs are allowed'));
+    }
+    if (net.isIP(target.hostname.replace(/^\[|\]$/g, '')) || !isValidHostname(target.hostname)) {
+      return reject(new Error('URL host must be a DNS name'));
+    }
+
+    const req = https.get(target, {
+      lookup: publicOnlyLookup,
+      timeout: timeoutMs,
+      headers: { accept: 'application/json', 'user-agent': 'DailyGrind-EVP/1.0' },
+    }, (res) => {
+      if (res.statusCode !== 200) {
+        res.resume();
+        return reject(new Error(`Unexpected HTTP ${res.statusCode} from ${target.host}`));
+      }
+      const chunks = [];
+      let size = 0;
+      res.on('data', (chunk) => {
+        size += chunk.length;
+        if (size > maxBytes) {
+          req.destroy(new Error('Response too large'));
+          return;
+        }
+        chunks.push(chunk);
+      });
+      res.on('end', () => {
+        try {
+          resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
+        } catch {
+          reject(new Error('Response is not valid JSON'));
+        }
+      });
+      res.on('error', reject);
+    });
+    req.on('timeout', () => req.destroy(new Error('Request timed out')));
+    req.on('error', reject);
+  });
+}
+
+// `_email-verification.<domain>` TXT  ->  "iss=<issuer host>"
+export async function discoverIssuerViaDns(domain) {
+  if (!isValidHostname(domain)) throw new Error('Invalid domain');
+  const records = await dns.promises.resolveTxt(`_email-verification.${domain}`);
+  const issuers = records
+    .map((chunks) => chunks.join('').trim())
+    .filter((txt) => txt.startsWith('iss='))
+    .map((txt) => txt.slice(4).trim());
+  const unique = [...new Set(issuers)];
+  if (unique.length !== 1) throw new Error('Expected exactly one iss= record');
+  return unique[0];
+}
+
+// Small TTL cache so a burst of sign-ups doesn't hammer issuers.
+export function cached(fn, ttlMs = 5 * 60 * 1000, maxEntries = 500) {
+  const store = new Map();
+  return async (key) => {
+    const hit = store.get(key);
+    if (hit && hit.expires > Date.now()) return hit.value;
+    const value = await fn(key);
+    if (store.size >= maxEntries) store.delete(store.keys().next().value);
+    store.set(key, { value, expires: Date.now() + ttlMs });
+    return value;
+  };
+}
