--- /dev/null
+++ b/server.js
@@ -0,0 +1,324 @@
+// The Daily Grind web server: serves the homepage and the rewards sign-up API.
+//
+//   POST /api/email-verification/nonce   -> { nonce }  (binds a fresh nonce to the session)
+//   POST /api/email-verification/verify  -> { verified, email, issuer }
+//   POST /api/rewards/signup             -> { member }
+//
+// Environment:
+//   PORT       listen port (default 11222)
+//   RP_ORIGIN  public origin(s) of the site, comma separated, e.g. https://dailygrind.example
+//              (used as the expected `aud` of EVP tokens and for Origin/CSRF checks)
+//   DATA_DIR   where members.json is stored (default ./data)
+
+import http from 'node:http';
+import { randomBytes, randomUUID } from 'node:crypto';
+import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { verifyEmailPresentation, normalizeEmail, VerificationError } from './lib/email-verification.js';
+import { discoverIssuerViaDns, fetchJsonSafely, cached } from './lib/issuer-discovery.js';
+
+const ROOT = path.dirname(fileURLToPath(import.meta.url));
+const PORT = Number(process.env.PORT || 11222);
+const ORIGINS = (process.env.RP_ORIGIN || `http://localhost:${PORT},http://127.0.0.1:${PORT}`)
+  .split(',')
+  .map((o) => new URL(o.trim()).origin);
+const SECURE_COOKIES = ORIGINS.every((o) => o.startsWith('https:'));
+const DATA_DIR = process.env.DATA_DIR || path.join(ROOT, 'data');
+const MEMBERS_FILE = path.join(DATA_DIR, 'members.json');
+
+const NONCE_TTL_MS = 5 * 60 * 1000;
+const VERIFIED_TTL_MS = 15 * 60 * 1000;
+const SESSION_IDLE_MS = 30 * 60 * 1000;
+const MAX_SESSIONS = 50_000;
+const MAX_BODY_BYTES = 32 * 1024;
+
+const discoverIssuer = cached(discoverIssuerViaDns);
+const fetchJson = cached((url) => fetchJsonSafely(url));
+
+// ---------------------------------------------------------------------------
+// Static files (explicit allow-list; nothing else on disk is reachable)
+// ---------------------------------------------------------------------------
+const STATIC = {
+  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/index.html': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/assets/rewards-signup.js': { file: 'assets/rewards-signup.js', type: 'text/javascript; charset=utf-8' },
+};
+
+const SECURITY_HEADERS = {
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+  'Content-Security-Policy': [
+    "default-src 'self'",
+    "script-src 'self'",
+    "style-src 'self' 'unsafe-inline'",
+    "img-src 'self' https://images.unsplash.com",
+    "connect-src 'self'",
+    "base-uri 'none'",
+    "form-action 'self'",
+    "frame-ancestors 'none'",
+  ].join('; '),
+};
+
+// ---------------------------------------------------------------------------
+// Sessions (in memory; swap for Redis or similar when running multiple nodes)
+// ---------------------------------------------------------------------------
+const sessions = new Map();
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+  }
+  return out;
+}
+
+function getSession(req, res) {
+  const sid = parseCookies(req.headers.cookie).dg_sid;
+  const now = Date.now();
+  let session = sid && sessions.get(sid);
+  if (session && now - session.lastSeen > SESSION_IDLE_MS) {
+    sessions.delete(sid);
+    session = null;
+  }
+  if (!session) {
+    if (sessions.size >= MAX_SESSIONS) sessions.delete(sessions.keys().next().value);
+    const id = randomBytes(32).toString('base64url');
+    session = { id, lastSeen: now, nonce: null, verified: null, attempts: [] };
+    sessions.set(id, session);
+    res.setHeader('Set-Cookie', `dg_sid=${id}; Path=/; HttpOnly; SameSite=Lax${SECURE_COOKIES ? '; Secure' : ''}; Max-Age=${SESSION_IDLE_MS / 1000}`);
+  }
+  session.lastSeen = now;
+  return session;
+}
+
+setInterval(() => {
+  const cutoff = Date.now() - SESSION_IDLE_MS;
+  for (const [id, s] of sessions) if (s.lastSeen < cutoff) sessions.delete(id);
+}, 60_000).unref();
+
+// Allow at most `limit` verification attempts per session per minute.
+function rateLimited(session, limit = 10) {
+  const now = Date.now();
+  session.attempts = session.attempts.filter((t) => now - t < 60_000);
+  if (session.attempts.length >= limit) return true;
+  session.attempts.push(now);
+  return false;
+}
+
+// ---------------------------------------------------------------------------
+// Members store (JSON file, serialized atomic writes)
+// ---------------------------------------------------------------------------
+let membersCache = null;
+let writeChain = Promise.resolve();
+
+async function loadMembers() {
+  if (membersCache) return membersCache;
+  try {
+    membersCache = JSON.parse(await readFile(MEMBERS_FILE, 'utf8'));
+  } catch (err) {
+    if (err.code !== 'ENOENT') throw err;
+    membersCache = [];
+  }
+  return membersCache;
+}
+
+function withMembers(mutator) {
+  const run = writeChain.then(async () => {
+    const members = await loadMembers();
+    const result = await mutator(members);
+    await mkdir(DATA_DIR, { recursive: true });
+    const tmp = `${MEMBERS_FILE}.${process.pid}.tmp`;
+    await writeFile(tmp, JSON.stringify(members, null, 2));
+    await rename(tmp, MEMBERS_FILE);
+    return result;
+  });
+  writeChain = run.catch(() => {});
+  return run;
+}
+
+// ---------------------------------------------------------------------------
+// HTTP helpers
+// ---------------------------------------------------------------------------
+function send(res, status, body, headers = {}) {
+  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
+  res.writeHead(status, {
+    ...SECURITY_HEADERS,
+    'Content-Type': typeof body === 'object' && !Buffer.isBuffer(body) ? 'application/json; charset=utf-8' : 'text/plain; charset=utf-8',
+    'Cache-Control': 'no-store',
+    ...headers,
+  });
+  res.end(payload);
+}
+
+class HttpError extends Error {
+  constructor(status, message) {
+    super(message);
+    this.status = status;
+  }
+}
+
+function readJson(req) {
+  if (!/^application\/json\b/i.test(req.headers['content-type'] || '')) {
+    return Promise.reject(new HttpError(415, 'Expected application/json'));
+  }
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let size = 0;
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(new HttpError(413, 'Request body too large'));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => {
+      try {
+        const value = JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}');
+        if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
+        resolve(value);
+      } catch {
+        reject(new HttpError(400, 'Invalid JSON body'));
+      }
+    });
+    req.on('error', reject);
+  });
+}
+
+// Reject cross-site API calls (CSRF / token-relay from other origins).
+function assertSameOrigin(req) {
+  const origin = req.headers.origin;
+  if (!origin || !ORIGINS.includes(origin)) throw new HttpError(403, 'Cross-origin request rejected');
+}
+
+const EMAIL_RE = /^[^\s@]{1,64}@[^\s@]+\.[^\s@]{2,}$/;
+const CONTROL_RE = /[\u0000-\u001f\u007f]/;
+const DRINKS = new Set(['', 'latte', 'espresso', 'cold-brew', 'cappuccino', 'tea', 'other']);
+
+function validateSignup(body) {
+  const errors = {};
+  const firstName = typeof body.firstName === 'string' ? body.firstName.trim() : '';
+  const email = normalizeEmail(body.email);
+  const birthday = typeof body.birthday === 'string' ? body.birthday.trim() : '';
+  const favoriteDrink = typeof body.favoriteDrink === 'string' ? body.favoriteDrink : '';
+
+  if (!firstName || firstName.length > 50 || CONTROL_RE.test(firstName)) errors.firstName = 'Please enter your first name (up to 50 characters).';
+  if (!EMAIL_RE.test(email) || email.length > 254) errors.email = 'Please enter a valid email address.';
+  if (birthday && !/^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(birthday)) errors.birthday = 'Birthday must be in MM-DD format.';
+  if (!DRINKS.has(favoriteDrink)) errors.favoriteDrink = 'Please choose a drink from the list.';
+  if (body.acceptTerms !== true) errors.acceptTerms = 'Please accept the rewards program terms.';
+
+  return {
+    errors,
+    value: { firstName, email, birthday: birthday || null, favoriteDrink: favoriteDrink || null, marketingOptIn: body.marketingOptIn === true },
+  };
+}
+
+// ---------------------------------------------------------------------------
+// API handlers
+// ---------------------------------------------------------------------------
+function handleNonce(req, res, session) {
+  assertSameOrigin(req);
+  const nonce = randomBytes(24).toString('base64url');
+  session.nonce = { value: nonce, expires: Date.now() + NONCE_TTL_MS };
+  send(res, 200, { nonce, expiresIn: NONCE_TTL_MS / 1000 });
+}
+
+async function handleVerify(req, res, session) {
+  assertSameOrigin(req);
+  const body = await readJson(req);
+  if (rateLimited(session)) throw new HttpError(429, 'Too many verification attempts. Please wait a minute.');
+
+  // Nonces are single use: consume it before verifying so a token can't be replayed.
+  const nonce = session.nonce && session.nonce.expires > Date.now() ? session.nonce.value : null;
+  session.nonce = null;
+
+  const submitted = typeof body.email === 'string' && body.email.trim() ? body.email : undefined;
+  try {
+    const result = await verifyEmailPresentation(body.presentationToken, {
+      expectedNonce: nonce,
+      expectedEmail: submitted,
+      audiences: ORIGINS,
+      discoverIssuer,
+      fetchJson,
+    });
+    session.verified = { email: result.email, issuer: result.issuer, at: new Date().toISOString(), expires: Date.now() + VERIFIED_TTL_MS };
+    send(res, 200, { verified: true, email: result.email, issuer: result.issuer });
+  } catch (err) {
+    if (!(err instanceof VerificationError)) throw err;
+    console.warn(`[evp] verification failed: ${err.code} - ${err.message}`);
+    send(res, 422, { verified: false, code: err.code, error: "We couldn't confirm that email automatically." });
+  }
+}
+
+async function handleSignup(req, res, session) {
+  assertSameOrigin(req);
+  const body = await readJson(req);
+  const { errors, value } = validateSignup(body);
+  if (Object.keys(errors).length) return send(res, 400, { error: 'Please fix the highlighted fields.', fields: errors });
+
+  // Verified status comes only from the server-side session, never from the client.
+  const v = session.verified;
+  const emailVerified = Boolean(v && v.expires > Date.now() && v.email === value.email);
+
+  const outcome = await withMembers((members) => {
+    if (members.some((m) => m.email === value.email)) return null;
+    const member = {
+      id: randomUUID(),
+      ...value,
+      emailVerified,
+      emailVerifiedAt: emailVerified ? v.at : null,
+      emailVerificationMethod: emailVerified ? 'evp' : null,
+      emailVerificationIssuer: emailVerified ? v.issuer : null,
+      rewardsStatus: emailVerified ? 'active' : 'pending_email_verification',
+      points: emailVerified ? 50 : 0,
+      createdAt: new Date().toISOString(),
+    };
+    members.push(member);
+    return member;
+  });
+
+  if (!outcome) return send(res, 409, { error: 'An account with this email already exists. Try signing in instead.' });
+  if (emailVerified) session.verified = null;
+
+  const { id, firstName, email, rewardsStatus, points } = outcome;
+  send(res, 201, { member: { id, firstName, email, emailVerified, rewardsStatus, points } });
+}
+
+const ROUTES = {
+  'POST /api/email-verification/nonce': handleNonce,
+  'POST /api/email-verification/verify': handleVerify,
+  'POST /api/rewards/signup': handleSignup,
+};
+
+// ---------------------------------------------------------------------------
+// Server
+// ---------------------------------------------------------------------------
+const server = http.createServer(async (req, res) => {
+  try {
+    const { pathname } = new URL(req.url, 'http://localhost');
+
+    if (pathname.startsWith('/api/')) {
+      const handler = ROUTES[`${req.method} ${pathname}`];
+      if (!handler) throw new HttpError(Object.keys(ROUTES).some((r) => r.endsWith(` ${pathname}`)) ? 405 : 404, 'Not found');
+      return await handler(req, res, getSession(req, res));
+    }
+
+    const asset = STATIC[pathname];
+    if (!asset || (req.method !== 'GET' && req.method !== 'HEAD')) return send(res, 404, 'Not found');
+    const content = await readFile(path.join(ROOT, asset.file));
+    send(res, 200, req.method === 'HEAD' ? '' : content, { 'Content-Type': asset.type, 'Cache-Control': 'no-cache' });
+  } catch (err) {
+    if (err instanceof HttpError) return send(res, err.status, { error: err.message });
+    console.error(err);
+    if (!res.headersSent) send(res, 500, { error: 'Something went wrong. Please try again.' });
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`The Daily Grind listening on http://localhost:${PORT} (RP origins: ${ORIGINS.join(', ')})`);
+});
