+++ b/test/email-verification.test.js
@@ -0,0 +1,150 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createHash, generateKeyPairSync, sign } from 'node:crypto';
+import { verifyEmailPresentation, VerificationError } from '../lib/email-verification.js';
+import { isPublicAddress } from '../lib/issuer-discovery.js';
+
+const b64 = (v) => Buffer.from(typeof v === 'string' ? v : JSON.stringify(v)).toString('base64url');
+
+function jws(header, payload, privateKey, alg) {
+  const input = `${b64(header)}.${b64(payload)}`;
+  const sig = alg === 'EdDSA'
+    ? sign(null, Buffer.from(input), privateKey)
+    : sign('sha256', Buffer.from(input), { key: privateKey, dsaEncoding: 'ieee-p1363' });
+  return `${input}.${sig.toString('base64url')}`;
+}
+
+const issuerKeys = generateKeyPairSync('ec', { namedCurve: 'P-256' });
+const issuerJwk = { ...issuerKeys.publicKey.export({ format: 'jwk' }), kid: 'k1', use: 'sig', alg: 'ES256' };
+const browserKeys = generateKeyPairSync('ed25519');
+const browserJwk = browserKeys.publicKey.export({ format: 'jwk' });
+
+const NOW = Date.UTC(2026, 10, 19, 12, 0, 0);
+const nowSec = NOW / 1000;
+const AUD = 'https://dailygrind.example';
+const NONCE = 'n-0S6_WzA2Mj';
+
+function makeToken({ claims = {}, kb = {}, sdHeader = {}, kbHeader = {}, signer = issuerKeys.privateKey } = {}) {
+  const sdJwt = jws(
+    { alg: 'ES256', kid: 'k1', typ: 'evp+sd-jwt', ...sdHeader },
+    { iss: 'issuer.example', iat: nowSec - 10, cnf: { jwk: browserJwk }, email: 'Jane@Mail.Example', email_verified: true, ...claims },
+    signer,
+    'ES256',
+  );
+  const sdHash = createHash('sha256').update(`${sdJwt}~`).digest('base64url');
+  const kbJwt = jws(
+    { alg: 'EdDSA', typ: 'kb+jwt', ...kbHeader },
+    { aud: AUD, nonce: NONCE, iat: nowSec - 2, sd_hash: sdHash, ...kb },
+    browserKeys.privateKey,
+    'EdDSA',
+  );
+  return `${sdJwt}~${kbJwt}`;
+}
+
+const fetched = [];
+const baseOpts = () => ({
+  expectedNonce: NONCE,
+  audiences: [AUD],
+  expectedEmail: 'jane@mail.example',
+  now: NOW,
+  discoverIssuer: async (domain) => {
+    assert.equal(domain, 'mail.example');
+    return 'issuer.example';
+  },
+  fetchJson: async (url) => {
+    fetched.push(url);
+    if (url === 'https://issuer.example/.well-known/email-verification') {
+      return { issuance_endpoint: 'https://issuer.example/issue', jwks_uri: 'https://issuer.example/jwks', signing_alg_values_supported: ['ES256'] };
+    }
+    if (url === 'https://issuer.example/jwks') return { keys: [issuerJwk] };
+    throw new Error(`unexpected fetch ${url}`);
+  },
+});
+
+async function rejectsWith(code, token, overrides = {}) {
+  await assert.rejects(verifyEmailPresentation(token, { ...baseOpts(), ...overrides }), (err) => {
+    assert.ok(err instanceof VerificationError, err.message);
+    assert.equal(err.code, code);
+    return true;
+  });
+}
+
+test('accepts a valid presentation and normalizes the email', async () => {
+  const result = await verifyEmailPresentation(makeToken(), baseOpts());
+  assert.deepEqual(result, { email: 'jane@mail.example', issuer: 'issuer.example' });
+  assert.ok(fetched.includes('https://issuer.example/jwks'));
+});
+
+test('accepts iss expressed as an https origin', async () => {
+  const result = await verifyEmailPresentation(makeToken({ claims: { iss: 'https://issuer.example' } }), baseOpts());
+  assert.equal(result.issuer, 'issuer.example');
+});
+
+test('rejects wrong nonce, audience, or stale key binding', async () => {
+  await rejectsWith('wrong_nonce', makeToken({ kb: { nonce: 'other' } }));
+  await rejectsWith('nonce_missing', makeToken(), { expectedNonce: null });
+  await rejectsWith('wrong_audience', makeToken({ kb: { aud: 'https://evil.example' } }));
+  await rejectsWith('expired', makeToken({ kb: { iat: nowSec - 3600 } }));
+  await rejectsWith('not_yet_valid', makeToken({ kb: { iat: nowSec + 3600 } }));
+});
+
+test('rejects a key binding that is not tied to the issuer token', async () => {
+  await rejectsWith('bad_sd_hash', makeToken({ kb: { sd_hash: 'AAAA' } }));
+});
+
+test('rejects swapping in a different issuer token under the same KB-JWT', async () => {
+  const [, kbJwt] = makeToken().split('~');
+  const [otherSd] = makeToken({ claims: { email: 'attacker@mail.example' } }).split('~');
+  await rejectsWith('bad_sd_hash', `${otherSd}~${kbJwt}`, { expectedEmail: 'attacker@mail.example' });
+});
+
+test('rejects email mismatch and unverified email', async () => {
+  await rejectsWith('email_mismatch', makeToken(), { expectedEmail: 'someone@else.example' });
+  await rejectsWith('email_not_verified', makeToken({ claims: { email_verified: false } }));
+});
+
+test('rejects an issuer not authorized by DNS for the email domain', async () => {
+  await rejectsWith('issuer_mismatch', makeToken({ claims: { iss: 'evil-issuer.example' } }));
+  await rejectsWith('issuer_unknown', makeToken(), { discoverIssuer: async () => { throw new Error('ENOTFOUND'); } });
+});
+
+test('rejects a forged issuer signature', async () => {
+  const attacker = generateKeyPairSync('ec', { namedCurve: 'P-256' });
+  await rejectsWith('bad_signature', makeToken({ signer: attacker.privateKey }));
+});
+
+test('rejects a forged key binding signature', async () => {
+  const token = makeToken();
+  const [sd, kb] = token.split('~');
+  const [h, p] = kb.split('.');
+  const forged = sign(null, Buffer.from(`${h}.${p}`), generateKeyPairSync('ed25519').privateKey).toString('base64url');
+  await rejectsWith('bad_signature', `${sd}~${h}.${p}.${forged}`);
+});
+
+test('rejects alg none / HMAC / wrong typ / crit headers', async () => {
+  await rejectsWith('unsupported_alg', makeToken({ kbHeader: { alg: 'none' } }));
+  await rejectsWith('unsupported_alg', makeToken({ kbHeader: { alg: 'HS256' } }));
+  await rejectsWith('wrong_type', makeToken({ sdHeader: { typ: 'JWT' } }));
+  await rejectsWith('wrong_type', makeToken({ kbHeader: { typ: 'JWT' } }));
+  await rejectsWith('unsupported_token', makeToken({ sdHeader: { crit: ['x'] } }));
+});
+
+test('rejects unknown kid and missing key binding', async () => {
+  await rejectsWith('key_not_found', makeToken({ sdHeader: { kid: 'nope' } }));
+  await rejectsWith('malformed_token', `${makeToken().split('~')[0]}~`);
+  await rejectsWith('malformed_token', 'not-a-token');
+});
+
+test('rejects a non-https jwks_uri', async () => {
+  const opts = baseOpts();
+  const inner = opts.fetchJson;
+  opts.fetchJson = async (url) => (url.endsWith('/email-verification') ? { jwks_uri: 'http://issuer.example/jwks' } : inner(url));
+  await rejectsWith('issuer_metadata', makeToken(), opts);
+});
+
+test('SSRF guard classifies addresses', () => {
+  for (const a of ['127.0.0.1', '10.1.2.3', '169.254.169.254', '192.168.1.1', '::1', 'fd00::1', '::ffff:127.0.0.1', 'fe80::1']) {
+    assert.equal(isPublicAddress(a), false, a);
+  }
+  for (const a of ['8.8.8.8', '2606:4700:4700::1111', '::ffff:8.8.8.8']) assert.equal(isPublicAddress(a), true, a);
+});

