+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Visually Stable Mixed Fonts</title>
+  <style>
+    :root {
+      color-scheme: light dark;
+    }
+
+    body {
+      margin: 0;
+      padding: 2rem;
+      font-family: system-ui, sans-serif;
+      line-height: 1.6;
+      display: grid;
+      gap: 2rem;
+      max-width: 60ch;
+      margin-inline: auto;
+    }
+
+    section {
+      padding: 1.5rem;
+      border: 1px solid color-mix(in srgb, currentColor 25%, transparent);
+      border-radius: 0.75rem;
+    }
+
+    h2 {
+      margin-block-start: 0;
+      font-size: 1.25rem;
+      text-wrap: balance;
+    }
+
+    code {
+      padding: 0.1em 0.3em;
+      border-radius: 0.25em;
+      background: color-mix(in srgb, currentColor 10%, transparent);
+    }
+
+    /* Mixed fonts: normalize x-height of nested fonts automatically */
+    #mixed-fonts-container {
+      font-family: Georgia, "Times New Roman", serif;
+      font-size: 1.125rem;
+      /* Extract the x-height ratio from the primary font and apply it
+         to every descendant, including the monospace inline code. */
+      font-size-adjust: from-font;
+    }
+
+    #mixed-fonts-container code {
+      font-family: ui-monospace, "Courier New", Courier, monospace;
+      /* Inherits font-size-adjust (resolved to the parent's ratio). */
+    }
+
+    /* Independent theme: lock proportions to an explicit x-height ratio */
+    #independent-theme-container {
+      font-family: Verdana, Geneva, sans-serif;
+      font-size: 1rem;
+      /* Fixed aspect value (x-height / font-size) so the theme keeps the
+         same visual proportions regardless of which font actually loads. */
+      font-size-adjust: 0.5;
+    }
+
+    #independent-theme-container code {
+      font-family: ui-monospace, "Courier New", Courier, monospace;
+    }
+
+    /* Fallback for browsers without font-size-adjust support */
+    @supports not (font-size-adjust: from-font) {
+      #mixed-fonts-container code {
+        /* Monospace fonts usually render visually larger/smaller; nudge manually */
+        font-size: 0.9em;
+        line-height: 1;
+      }
+
+      #independent-theme-container {
+        font-size: 0.95rem;
+        line-height: 1.7;
+      }
+    }
+  </style>
+</head>
