+/**
+ * <coffee-card> — a menu item card with an accessible "favorite" toggle.
+ *
+ * Light DOM (progressively enhanced; readable without JS):
+ *   <coffee-card item-id="maple-oat-latte">
+ *     <img slot="media" src="…" alt="…">
+ *     <h3>Maple Oat Latte</h3>
+ *     <p>Description…</p>
+ *     <a slot="action" href="/menu/seasonal">View details</a>
+ *   </coffee-card>
+ *
+ * Attributes:
+ *   item-id    Stable id used to persist the favorite (falls back to heading text).
+ *   favorited  Boolean; reflects the favorite state so it can be set from markup.
+ *
+ * Events:
+ *   favorite-change  { detail: { id, name, favorited } }, bubbles + composed.
+ *
+ * Styling hooks:
+ *   Custom properties: --coffee-card-bg, --coffee-card-fg, --coffee-card-accent,
+ *                      --coffee-card-accent-fg, --coffee-card-radius, --coffee-card-highlight
+ *   Parts: card, media, body, favorite, action-area
+ *   States: coffee-card:state(favorited)
+ */
+
+const STORAGE_KEY = 'daily-grind:favorites';
+
+const readFavorites = () => {
+  try {
+    return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]'));
+  } catch {
+    return new Set();
+  }
+};
+
+const writeFavorites = (set) => {
+  try {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...set]));
+  } catch {
+    /* Storage unavailable (private mode, quota) — state still works for the session. */
+  }
+};
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--coffee-card-bg, #fff);
+    --_fg: var(--coffee-card-fg, #3e2723);
+    --_accent: var(--coffee-card-accent, #4e342e);
+    --_accent-fg: var(--coffee-card-accent-fg, #fff);
+    --_highlight: var(--coffee-card-highlight, #c62828);
+    --_radius: var(--coffee-card-radius, 8px);
+
+    display: block;
+    container-type: inline-size;
+    color: var(--_fg);
+  }
+  :host([hidden]) { display: none; }
+
+  .card {
+    position: relative;
+    display: grid;
+    grid-template-rows: auto 1fr;
+    height: 100%;
+    background: var(--_bg);
+    border-radius: var(--_radius);
+    box-shadow: 0 2px 5px rgb(0 0 0 / 0.1);
+    overflow: hidden;
+    transition: box-shadow 0.2s, translate 0.2s;
+  }
+  .card:has(:focus-visible),
+  .card:hover {
+    box-shadow: 0 6px 16px rgb(0 0 0 / 0.15);
+  }
+  @media (prefers-reduced-motion: no-preference) {
+    .card:hover { translate: 0 -2px; }
+  }
+
+  .media {
+    aspect-ratio: 3 / 2;
+    background: #d7ccc8;
+  }
+  ::slotted([slot="media"]) {
+    display: block;
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+  }
+
+  .body {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+    padding: 1.25rem;
+    text-align: center;
+  }
+  ::slotted(:is(h2, h3, h4)) {
+    margin: 0;
+    color: var(--_accent);
+    font-size: 1.2rem;
+  }
+  ::slotted(p) { margin: 0; }
+
+  .action-area {
+    margin-top: auto;
+    padding-top: 0.75rem;
+  }
+  ::slotted(a) {
+    display: inline-block;
+    background: var(--_accent);
+    color: var(--_accent-fg);
+    padding: 0.6rem 1.25rem;
+    border-radius: 5px;
+    text-decoration: none;
+    transition: filter 0.2s;
+  }
+  ::slotted(a:hover) { filter: brightness(0.8); }
+  ::slotted(a:focus-visible) {
+    outline: 3px solid var(--_accent);
+    outline-offset: 3px;
+  }
+
+  .favorite {
+    position: absolute;
+    top: 0.5rem;
+    right: 0.5rem;
+    display: grid;
+    place-items: center;
+    inline-size: 2.75rem;
+    block-size: 2.75rem;
+    padding: 0;
+    border: 0;
+    border-radius: 50%;
+    background: rgb(255 255 255 / 0.92);
+    color: var(--_accent);
+    font: inherit;
+    cursor: pointer;
+    box-shadow: 0 1px 4px rgb(0 0 0 / 0.25);
+  }
+  .favorite:focus-visible {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  .favorite svg {
+    inline-size: 1.4rem;
+    block-size: 1.4rem;
+    fill: none;
+    stroke: currentColor;
+    stroke-width: 2;
+  }
+  :host(:state(favorited)) .favorite { color: var(--_highlight); }
+  :host(:state(favorited)) .favorite svg { fill: currentColor; }
+  @media (prefers-reduced-motion: no-preference) {
+    :host(:state(favorited)) .favorite svg { animation: pop 0.25s ease-out; }
+  }
+  @keyframes pop { 50% { scale: 1.25; } }
+
+  @media (forced-colors: active) {
+    .favorite { border: 1px solid ButtonText; }
+    :host(:state(favorited)) .favorite svg { fill: ButtonText; }
+  }
+
+  /* Wider cards: media beside the text. */
+  @container (min-width: 34rem) {
+    .card { grid-template-rows: none; grid-template-columns: 2fr 3fr; }
+    .media { aspect-ratio: auto; }
+    .body { text-align: start; justify-content: center; }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <article class="card" part="card">
+    <div class="media" part="media"><slot name="media"></slot></div>
+    <div class="body" part="body">
+      <slot></slot>
+      <div class="action-area" part="action-area"><slot name="action"></slot></div>
+    </div>
+    <button class="favorite" part="favorite" type="button" aria-pressed="false">
+      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
+        <path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3.1 4.5 6.9 4.5c2.1 0 3.6 1.2 4.6 2.7h1c1-1.5 2.5-2.7 4.6-2.7 3.8 0 6 3.9 4.5 7.3C19.5 16.4 12 21 12 21z"/>
+      </svg>
+    </button>
+  </article>
+`;
+
+class CoffeeCard extends HTMLElement {
+  static observedAttributes = ['favorited'];
+
+  #internals;
+  #button;
+  #defaultSlot;
+  #restored = false;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#button = root.querySelector('.favorite');
+    this.#defaultSlot = root.querySelector('slot:not([name])');
+
+    this.#button.addEventListener('click', () => this.toggleFavorite());
+    // The heading may arrive after upgrade; keep the button's name in sync.
+    this.#defaultSlot.addEventListener('slotchange', () => this.#updateLabel());
+  }
+
+  connectedCallback() {
+    // Idempotent: restore persisted state only once, even if the card is moved.
+    if (!this.#restored) {
+      this.#restored = true;
+      if (!this.hasAttribute('favorited') && readFavorites().has(this.itemId)) {
+        this.favorited = true;
+      }
+    }
+    this.#sync();
+    this.#updateLabel();
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal !== newVal) this.#sync();
+  }
+
+  /** Display name taken from the slotted heading. */
+  get name() {
+    const heading = this.#defaultSlot
+      ?.assignedElements()
+      .find((el) => /^H[1-6]$/.test(el.tagName));
+    return heading?.textContent.trim() ?? '';
+  }
+
+  get itemId() {
+    return this.getAttribute('item-id') || this.name;
+  }
+
+  get favorited() {
+    return this.hasAttribute('favorited');
+  }
+
+  set favorited(on) {
+    this.toggleAttribute('favorited', Boolean(on));
+  }
+
+  toggleFavorite(force = !this.favorited) {
+    if (force === this.favorited) return;
+    this.favorited = force;
+
+    const favorites = readFavorites();
+    force ? favorites.add(this.itemId) : favorites.delete(this.itemId);
+    writeFavorites(favorites);
+
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { id: this.itemId, name: this.name, favorited: force },
+      }),
+    );
+  }
+
+  // Visual state, custom state and the accessible state all derive from the attribute.
+  #sync() {
+    const on = this.favorited;
+    this.#button.setAttribute('aria-pressed', String(on));
+    if (on) this.#internals.states.add('favorited');
+    else this.#internals.states.delete('favorited');
+  }
+
+  #updateLabel() {
+    const name = this.name;
+    this.#button.setAttribute('aria-label', name ? `Favorite ${name}` : 'Favorite');
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
+
+export { CoffeeCard };
