+ *     <a slot="actions" href="/order-online">Order Now</a>
+ *   </hero-banner>
+ *
+ * The background image is a real <img> (not a CSS background) so the browser
+ * can discover and prioritise it early, which helps LCP.
+ *
+ * Styling hooks:
+ *   Custom properties: --hero-min-height, --hero-overlay, --hero-fg,
+ *                      --hero-cta-bg, --hero-cta-fg
+ *   Parts: content, actions
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    display: grid;
+    position: relative;
+    isolation: isolate;
+    min-block-size: var(--hero-min-height, 60vh);
+    place-items: center;
+    padding: 3rem 20px;
+    overflow: hidden;
+    color: var(--hero-fg, #fff);
+    text-align: center;
+    background: #3e2723;
+  }
+  :host([hidden]) { display: none; }
+
+  .media,
+  .media::after {
+    position: absolute;
+    inset: 0;
+    z-index: -1;
+  }
+  .media::after {
+    content: "";
+    background: var(--hero-overlay, rgb(0 0 0 / 0.5));
+  }
+  ::slotted([slot="media"]) {
+    display: block;
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+  }
+
+  .content {
+    display: grid;
+    gap: 1rem;
+    justify-items: center;
+    max-inline-size: 40rem;
+  }
+  ::slotted(:is(h1, h2)) {
+    margin: 0;
