+    text-align: center;
+    color: var(--dg-text, #3e2723);
+    margin: 0;
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(var(--dg-grid-min, 250px), 1fr));
+    gap: var(--dg-grid-gap, 20px);
+    margin-top: 20px;
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <section part="section">
+    <div class="heading"><slot name="heading"></slot></div>
+    <div class="grid" part="grid" role="list"><slot></slot></div>
+  </section>
+`;
+
+/**
+ * <dg-card-grid>
+ *   <h2 slot="heading">Seasonal Favorites</h2>
+ *   <dg-coffee-card>...</dg-coffee-card>
+ * </dg-card-grid>
+ *
+ * Responsive grid section. The section is labelled by its slotted heading,
+ * and children are exposed as a list (each slotted child gets
+ * role="listitem" unless it already declares a role) so screen-reader users
+ * hear "list, 3 items".
+ */
+export class DgCardGrid extends HTMLElement {
+  #section;
+  #headingSlot;
+  #defaultSlot;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [baseStyles, styles];
+    root.append(template.content.cloneNode(true));
+    this.#section = root.querySelector('section');
+    this.#headingSlot = root.querySelector('slot[name="heading"]');
+    this.#defaultSlot = root.querySelector('slot:not([name])');
+  }
+
+  connectedCallback() {
+    this.#headingSlot.addEventListener('slotchange', this.#syncLabel);
+    this.#defaultSlot.addEventListener('slotchange', this.#syncItems);
+    this.#syncLabel();
+    this.#syncItems();
+  }
+
+  disconnectedCallback() {
+    this.#headingSlot.removeEventListener('slotchange', this.#syncLabel);
+    this.#defaultSlot.removeEventListener('slotchange', this.#syncItems);
+  }
+
+  // aria-labelledby can't cross the shadow boundary, so mirror the text.
+  #syncLabel = () => {
+    const [heading] = this.#headingSlot.assignedElements();
+    const text = heading?.textContent.trim();
+    if (text) this.#section.setAttribute('aria-label', text);
+    else this.#section.removeAttribute('aria-label');
+  };
+
+  #syncItems = () => {
+    for (const el of this.#defaultSlot.assignedElements()) {
+      if (!el.hasAttribute('role')) el.setAttribute('role', 'listitem');
+    }
+  };
+}
+
+customElements.define('dg-card-grid', DgCardGrid);
