+import { baseStyles, sheet, buttonSlottedCss } from './shared-styles.js';
+
+const styles = sheet(`
+  :host {
+    --_overlay: var(--dg-hero-overlay, rgba(0, 0, 0, 0.5));
+    display: flex;
+    flex-direction: column;
+    justify-content: center;
+    align-items: center;
+    min-height: var(--dg-hero-height, 60vh);
+    padding: 2rem 20px;
+    text-align: center;
+    color: #fff;
+    background-color: var(--dg-primary, #4e342e);
+    background-image:
+      linear-gradient(var(--_overlay), var(--_overlay)),
+      var(--_image, none);
+    background-size: cover;
+    background-position: center;
+  }
+
+  ::slotted(h1) {
+    font-size: clamp(2rem, 6vw, 3rem);
+    line-height: 1.2;
+    margin: 0 0 1rem;
+  }
+  ::slotted(p) { margin: 0; max-width: 40rem; }
+
+  .cta { margin-top: 15px; }
+  ${buttonSlottedCss('cta')}
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <slot></slot>
+  <div class="cta"><slot name="cta"></slot></div>
+`;
+
+/**
+ * <dg-hero image="https://...">
+ *   <h1>Headline</h1>
+ *   <p>Tagline</p>
+ *   <a slot="cta" href="/order-online">Order Now</a>
+ * </dg-hero>
+ *
+ * The background image is decorative (it is applied via CSS), so all
+ * meaningful content lives in the light DOM where it remains accessible
+ * and indexable even before the component upgrades.
+ */
+export class DgHero extends HTMLElement {
+  static observedAttributes = ['image'];
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [baseStyles, styles];
+    root.append(template.content.cloneNode(true));
+  }
+
+  attributeChangedCallback(name, _old, value) {
+    if (name === 'image') {
+      if (value) this.style.setProperty('--_image', `url(${JSON.stringify(value)})`);
+      else this.style.removeProperty('--_image');
+    }
+  }
+}
+
+customElements.define('dg-hero', DgHero);
