+import { baseStyles, sheet, focusRing } from './shared-styles.js';
+
+const styles = sheet(`
+  :host {
+    display: block;
+    position: sticky;
+    top: 0;
+    z-index: 1000;
+    background: var(--dg-primary, #4e342e);
+    color: var(--dg-on-primary, #fff);
+  }
+
+  nav {
+    display: flex;
+    flex-wrap: wrap;
+    justify-content: space-between;
+    align-items: center;
+    gap: 0.5rem 1rem;
+    padding: 1rem 5%;
+  }
+
+  .brand ::slotted(*) {
+    color: inherit;
+    font-size: 1.5rem;
+    font-weight: bold;
+    letter-spacing: 1px;
+    text-decoration: none;
+  }
+
+  .links {
+    display: flex;
+    align-items: center;
+    gap: 20px;
+  }
+
+  ::slotted(a) {
+    color: inherit;
+    text-decoration: none;
+    font-size: 0.9rem;
+    transition: color 0.3s;
+  }
+  ::slotted(a:hover) { color: var(--dg-accent, #ffab40); }
+  ::slotted(a:focus-visible) { ${focusRing} border-radius: 2px; }
+  ::slotted(a[aria-current="page"]) {
+    color: var(--dg-accent, #ffab40);
+    text-decoration: underline;
+    text-underline-offset: 4px;
+  }
+  ::slotted(a[data-variant="outline"]) {
+    border: 1px solid var(--dg-accent, #ffab40);
+    padding: 5px 12px;
+    border-radius: 4px;
+  }
+
+  .toggle {
+    display: none;
+    align-items: center;
+    gap: 0.5rem;
+    background: transparent;
+    color: inherit;
+    font: inherit;
+    font-size: 0.9rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    padding: 6px 12px;
+    cursor: pointer;
+  }
+  .toggle:focus-visible { ${focusRing} }
+
+  .bars, .bars::before, .bars::after {
+    display: block;
+    width: 18px;
+    height: 2px;
+    background: currentColor;
+    transition: transform 0.2s;
+  }
+  .bars { position: relative; }
+  .bars::before, .bars::after { content: ''; position: absolute; left: 0; }
+  .bars::before { top: -6px; }
+  .bars::after { top: 6px; }
+  [aria-expanded="true"] .bars { background: transparent; }
+  [aria-expanded="true"] .bars::before { transform: translateY(6px) rotate(45deg); }
+  [aria-expanded="true"] .bars::after { transform: translateY(-6px) rotate(-45deg); }
+
+  /* Collapsible menu on narrow viewports. */
+  @media (max-width: 720px) {
+    .toggle { display: inline-flex; }
+    .links {
+      flex-basis: 100%;
+      flex-direction: column;
+      align-items: flex-start;
+      gap: 12px;
+      padding: 0.5rem 0 0.25rem;
+    }
+    :host(:not([open])) .links { display: none; }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <nav part="nav">
+    <div class="brand"><slot name="brand"></slot></div>
+    <button class="toggle" type="button" part="toggle"
+            aria-expanded="false" aria-controls="links">
+      <span class="bars" aria-hidden="true"></span>
+      <span>Menu</span>
+    </button>
+    <div class="links" id="links" part="links"><slot></slot></div>
+  </nav>
+`;
+
+/**
+ * <dg-site-nav label="Main">
+ *   <a slot="brand" href="/">THE DAILY GRIND</a>
+ *   <a href="/menu">Menu</a> ...
+ *   <a href="/logout" data-variant="outline">Logout</a>
+ * </dg-site-nav>
+ *
+ * Sticky site navigation with a disclosure-pattern menu toggle on small
+ * screens. Attributes: `label` (accessible nav name), `open` (reflects the
+ * mobile menu state). Fires `dg-nav-toggle` with { open }.
+ */
+export class DgSiteNav extends HTMLElement {
+  static observedAttributes = ['label', 'open'];
+
+  #nav;
+  #toggle;
+  #mq = window.matchMedia('(max-width: 720px)');
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [baseStyles, styles];
+    root.append(template.content.cloneNode(true));
+    this.#nav = root.querySelector('nav');
+    this.#toggle = root.querySelector('.toggle');
+  }
+
+  connectedCallback() {
+    this.#nav.setAttribute('aria-label', this.getAttribute('label') || 'Main');
+    this.#toggle.addEventListener('click', this.#onToggle);
+    this.addEventListener('keydown', this.#onKeydown);
+    this.addEventListener('click', this.#onLinkClick);
+    this.#mq.addEventListener('change', this.#onViewportChange);
+  }
+
+  disconnectedCallback() {
+    this.#toggle.removeEventListener('click', this.#onToggle);
+    this.removeEventListener('keydown', this.#onKeydown);
+    this.removeEventListener('click', this.#onLinkClick);
+    this.#mq.removeEventListener('change', this.#onViewportChange);
+  }
+
+  attributeChangedCallback(name, _old, value) {
+    if (name === 'label') this.#nav.setAttribute('aria-label', value || 'Main');
+    if (name === 'open') this.#toggle.setAttribute('aria-expanded', String(value !== null));
+  }
+
+  get open() { return this.hasAttribute('open'); }
+  set open(v) { this.toggleAttribute('open', Boolean(v)); }
+
+  #setOpen(open) {
+    if (open === this.open) return;
+    this.open = open;
+    this.dispatchEvent(new CustomEvent('dg-nav-toggle', { detail: { open }, bubbles: true, composed: true }));
+  }
+
+  #onToggle = () => this.#setOpen(!this.open);
+
+  #onKeydown = (e) => {
+    if (e.key === 'Escape' && this.open) {
+      this.#setOpen(false);
+      this.#toggle.focus();
+    }
+  };
+
+  // Collapse the mobile menu after a link is chosen (helps in-page anchors).
+  #onLinkClick = (e) => {
+    if (this.#mq.matches && e.target.closest?.('a')) this.#setOpen(false);
+  };
+
+  #onViewportChange = (e) => { if (!e.matches) this.#setOpen(false); };
+}
+
+customElements.define('dg-site-nav', DgSiteNav);
