--- /dev/null
+++ b/components/shared-styles.js
@@ -0,0 +1,79 @@
+/**
+ * Shared constructable stylesheets for Daily Grind components.
+ *
+ * Design tokens (--dg-*) are CSS custom properties, which inherit through
+ * shadow boundaries, so the page can theme every component from :root while
+ * each component keeps its own structural styles encapsulated.
+ */
+
+const sheet = (css) => {
+  const s = new CSSStyleSheet();
+  s.replaceSync(css);
+  return s;
+};
+
+/** Base reset + utilities adopted by every component's shadow root. */
+export const baseStyles = sheet(`
+  :host {
+    box-sizing: border-box;
+    font-family: var(--dg-font, 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif);
+    color: var(--dg-text, #3e2723);
+  }
+  :host([hidden]) { display: none !important; }
+  *, *::before, *::after { box-sizing: inherit; }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px; height: 1px;
+    padding: 0; margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after {
+      transition-duration: 0.01ms !important;
+      animation-duration: 0.01ms !important;
+    }
+  }
+`);
+
+/**
+ * Button-link look, usable both for elements inside a shadow root (.btn)
+ * and, via buttonSlottedCss(), for light-DOM links projected into a slot.
+ */
+const btnRules = `
+  display: inline-block;
+  background: var(--dg-primary, #4e342e);
+  color: var(--dg-on-primary, #fff);
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  font: inherit;
+  font-weight: 600;
+  border: 2px solid transparent;
+  cursor: pointer;
+  transition: background-color 0.3s, color 0.3s;
+`;
+const btnHover = `background: var(--dg-primary-dark, #3e2723);`;
+const focusRing = `
+  outline: 3px solid var(--dg-focus, #ffab40);
+  outline-offset: 2px;
+`;
+
+export const buttonStyles = sheet(`
+  .btn { ${btnRules} }
+  .btn:hover { ${btnHover} }
+  .btn:focus-visible { ${focusRing} }
+`);
+
+/** Returns rules that give slotted links in `slotName` the button look. */
+export const buttonSlottedCss = (slotName) => `
+  ::slotted(a[slot="${slotName}"]) { ${btnRules} }
+  ::slotted(a[slot="${slotName}"]:hover) { ${btnHover} }
+  ::slotted(a[slot="${slotName}"]:focus-visible) { ${focusRing} }
+`;
+
+export { sheet, focusRing };
