+  <dialog class="confirm-dialog" id="confirm-dialog" aria-labelledby="confirm-title">
+    <form method="dialog">
+      <h3 id="confirm-title">Confirm your order</h3>
+      <ul id="confirm-items"></ul>
+      <p class="order-total"><span>Total</span> <span id="confirm-total"></span></p>
+      <div class="order-actions">
+        <button type="submit" class="btn btn-secondary" value="cancel">Cancel</button>
+        <button type="submit" class="btn" value="confirm" autofocus>Confirm Order</button>
+      </div>
+    </form>
+  </dialog>
+
+  <script type="module">
+    const MENU = {
+      "maple-oat-latte": { name: "Maple Oat Latte", basePrice: 5.75 },
+      "dark-roast-espresso": { name: "Dark Roast Espresso", basePrice: 3.5 },
+      "cold-brew": { name: "Cold Brew", basePrice: 4.75 },
+    };
+    const SIZES = { small: -0.5, medium: 0, large: 0.75 };
+    const DRINK_IDS = Object.keys(MENU);
+    const SIZE_IDS = Object.keys(SIZES);
+    const MAX_QUANTITY = 10;
+    const STORAGE_KEY = "daily-grind-order";
+
+    const currency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
+    const priceOf = (drink, size) => MENU[drink].basePrice + SIZES[size];
+    const sizeLabel = (size) => size[0].toUpperCase() + size.slice(1);
+
+    const $ = (id) => document.getElementById(id);
+    const itemsList = $("order-items");
+    const emptyMsg = $("order-empty");
+    const totalEl = $("order-total");
+    const statusEl = $("order-status");
+    const placeBtn = $("place-order");
+    const clearBtn = $("clear-order");
+    const dialog = $("confirm-dialog");
+
+    /** @type {{drink: string, size: string, quantity: number}[]} */
+    let order = loadOrder();
+
+    function loadOrder() {
+      try {
+        const saved = JSON.parse(sessionStorage.getItem(STORAGE_KEY) ?? "[]");
+        return Array.isArray(saved)
+          ? saved.filter((i) => MENU[i.drink] && i.size in SIZES && Number.isInteger(i.quantity) && i.quantity > 0)
+          : [];
+      } catch {
+        return [];
+      }
+    }
+
+    function saveOrder() {
+      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(order));
+    }
+
+    function orderSnapshot() {
+      const items = order.map((item) => {
+        const unitPrice = priceOf(item.drink, item.size);
+        return {
+          drink: item.drink,
+          name: MENU[item.drink].name,
+          size: item.size,
+          quantity: item.quantity,
+          unitPrice: currency.format(unitPrice),
+          lineTotal: currency.format(unitPrice * item.quantity),
+        };
+      });
+      const total = order.reduce((sum, i) => sum + priceOf(i.drink, i.size) * i.quantity, 0);
+      return { items, itemCount: order.reduce((n, i) => n + i.quantity, 0), total: currency.format(total) };
+    }
+
+    function setStatus(message) {
+      statusEl.textContent = message;
+    }
+
+    function render() {
+      const snapshot = orderSnapshot();
+      itemsList.replaceChildren(
+        ...snapshot.items.map((item) => {
+          const li = document.createElement("li");
+          const label = document.createElement("span");
+          label.textContent = `${item.quantity} × ${sizeLabel(item.size)} ${item.name}`;
+          const lineTotal = document.createElement("span");
+          lineTotal.className = "line-total";
+          lineTotal.textContent = item.lineTotal;
+          const remove = document.createElement("button");
+          remove.type = "button";
+          remove.className = "remove-item";
+          remove.textContent = "Remove";
+          remove.setAttribute("aria-label", `Remove ${sizeLabel(item.size)} ${item.name}`);
+          remove.addEventListener("click", () => {
+            const result = removeFromOrder(item.drink, item.size);
+            setStatus(result.message);
+          });
+          li.append(label, lineTotal, remove);
+          return li;
+        })
+      );
+      emptyMsg.hidden = order.length > 0;
+      totalEl.textContent = snapshot.total;
+      placeBtn.disabled = order.length === 0;
+      clearBtn.disabled = order.length === 0;
+    }
+
+    // ---- Core ordering actions (shared by the UI and the WebMCP tools) ----
+
+    function addToOrder(drink, size = "medium", quantity = 1) {
+      if (!MENU[drink]) {
+        return { error: `Unknown drink "${drink}".`, availableDrinks: DRINK_IDS };
+      }
+      if (!(size in SIZES)) {
+        return { error: `Unknown size "${size}".`, availableSizes: SIZE_IDS };
+      }
+      if (!Number.isInteger(quantity) || quantity < 1) {
+        return { error: "Quantity must be a whole number of at least 1." };
+      }
+      const existing = order.find((i) => i.drink === drink && i.size === size);
+      const newQuantity = (existing?.quantity ?? 0) + quantity;
+      if (newQuantity > MAX_QUANTITY) {
+        return {
+          error: `At most ${MAX_QUANTITY} of the same drink and size can be ordered; ${existing?.quantity ?? 0} already in the order.`,
+        };
+      }
+      if (existing) existing.quantity = newQuantity;
+      else order.push({ drink, size, quantity });
+      saveOrder();
+      render();
+      const message = `Added ${quantity} × ${sizeLabel(size)} ${MENU[drink].name} to your order.`;
+      return { message, order: orderSnapshot() };
+    }
+
+    function removeFromOrder(drink, size) {
+      const before = order.length;
+      order = order.filter((i) => !(i.drink === drink && (size === undefined || i.size === size)));
+      if (order.length === before) {
+        return { error: `No matching ${MENU[drink]?.name ?? drink} in the order.`, order: orderSnapshot() };
+      }
+      saveOrder();
+      render();
+      return { message: `Removed ${MENU[drink].name}${size ? ` (${size})` : ""} from your order.`, order: orderSnapshot() };
+    }
+
+    function clearOrder() {
+      order = [];
+      saveOrder();
+      render();
+      return { message: "Your order has been cleared.", order: orderSnapshot() };
+    }
+
+    /**
+     * Asks the user to confirm in a modal dialog, then places the order.
+     * Confirmation always requires a human click, even when an agent initiates it.
+     */
+    function placeOrder({ signal } = {}) {
+      if (order.length === 0) {
+        return Promise.resolve({ error: "The order is empty. Add drinks before placing it." });
+      }
+      if (dialog.open) {
+        return Promise.resolve({ error: "An order confirmation is already awaiting the user's response." });
+      }
+      const snapshot = orderSnapshot();
+      $("confirm-items").replaceChildren(
+        ...snapshot.items.map((item) => {
+          const li = document.createElement("li");
+          li.textContent = `${item.quantity} × ${sizeLabel(item.size)} ${item.name} — ${item.lineTotal}`;
+          return li;
+        })
+      );
+      $("confirm-total").textContent = snapshot.total;
+      dialog.returnValue = "";
+      dialog.showModal();
+
+      return new Promise((resolve, reject) => {
+        const cleanup = () => signal?.removeEventListener("abort", onAbort);
+        const onAbort = () => {
+          dialog.removeEventListener("close", onClose);
+          dialog.close();
+          reject(signal.reason);
+        };
+        const onClose = () => {
+          cleanup();
+          if (dialog.returnValue !== "confirm") {
+            setStatus("Order not placed.");
+            resolve({ status: "cancelled", message: "The user declined to place the order.", order: orderSnapshot() });
+            return;
+          }
+          const orderNumber = `DG-${Date.now().toString(36).toUpperCase()}`;
+          order = [];
+          saveOrder();
+          render();
+          const message = `Order ${orderNumber} placed! ${snapshot.itemCount} drink(s), ${snapshot.total}. We'll start brewing now.`;
+          setStatus(message);
+          resolve({ status: "placed", orderNumber, message, placedOrder: snapshot });
+        };
+        dialog.addEventListener("close", onClose, { once: true });
+        signal?.addEventListener("abort", onAbort, { once: true });
+      });
+    }
+
+    // ---- UI wiring ----
+
+    for (const [drink, item] of Object.entries(MENU)) {
+      document.querySelector(`[data-price-for="${drink}"]`).textContent =
+        `From ${currency.format(item.basePrice + Math.min(...Object.values(SIZES)))}`;
+    }
+
+    document.querySelectorAll(".order-form").forEach((form) => {
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        const data = new FormData(form);
+        const result = addToOrder(data.get("drink"), data.get("size"), Number(data.get("quantity")));
+        setStatus(result.error ?? result.message);
+        if (!result.error) form.reset();
+      });
+    });
+
+    clearBtn.addEventListener("click", () => setStatus(clearOrder().message));
+    placeBtn.addEventListener("click", () => placeOrder());
+
+    render();
+
+    // ---- WebMCP: expose ordering actions to browser AI agents ----
+
+    if ("modelContext" in document) {
+      // Abort this controller to unregister every ordering tool at once.
+      const registrations = new AbortController();
+      const { signal } = registrations;
+      const drinkSchema = {
+        type: "string",
+        enum: DRINK_IDS,
+        description: "Menu identifier of the seasonal drink.",
+      };
+      const sizeSchema = {
+        type: "string",
+        enum: SIZE_IDS,
+        default: "medium",
+        description: "Cup size; small is cheaper and large costs more than medium.",
+      };
+
+      const tools = [
+        {
+          name: "get_seasonal_menu",
+          description: "Lists the seasonal coffee drinks available to order, with prices for each size.",
+          inputSchema: { type: "object", properties: {} },
+          execute() {
+            return DRINK_IDS.map((drink) => ({
+              drink,
+              name: MENU[drink].name,
+              description: document.querySelector(`[data-drink="${drink}"] p`).textContent,
+              prices: Object.fromEntries(SIZE_IDS.map((size) => [size, currency.format(priceOf(drink, size))])),
+            }));
+          },
+          annotations: { readOnlyHint: true },
+        },
+        {
+          name: "get_current_order",
+          description: "Shows the drinks in the user's current, not-yet-placed order and its total.",
+          inputSchema: { type: "object", properties: {} },
+          execute() {
+            return orderSnapshot();
+          },
+          annotations: { readOnlyHint: true },
+        },
+        {
+          name: "add_drink_to_order",
+          description: "Adds a seasonal coffee drink to the user's order. Use when the user wants to order or add a drink.",
+          inputSchema: {
+            type: "object",
+            properties: {
+              drink: drinkSchema,
+              size: sizeSchema,
+              quantity: {
+                type: "integer",
+                minimum: 1,
+                maximum: MAX_QUANTITY,
+                default: 1,
+                description: "How many cups to add.",
+              },
+            },
+            required: ["drink"],
+          },
+          execute({ drink, size = "medium", quantity = 1 }) {
+            const result = addToOrder(drink, size, quantity);
+            setStatus(result.error ?? result.message);
+            return result;
+          },
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: "remove_drink_from_order",
+          description: "Removes a drink from the user's current order.",
+          inputSchema: {
+            type: "object",
+            properties: {
+              drink: drinkSchema,
+              size: {
+                type: "string",
+                enum: SIZE_IDS,
+                description: "Only remove this size; omit to remove the drink in every size.",
+              },
+            },
+            required: ["drink"],
+          },
+          execute({ drink, size }) {
+            if (!MENU[drink]) return { error: `Unknown drink "${drink}".`, availableDrinks: DRINK_IDS };
+            if (size !== undefined && !(size in SIZES)) return { error: `Unknown size "${size}".`, availableSizes: SIZE_IDS };
+            const result = removeFromOrder(drink, size);
+            setStatus(result.error ?? result.message);
+            return result;
+          },
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: "clear_order",
+          description: "Empties the user's current order without placing it.",
+          inputSchema: { type: "object", properties: {} },
+          execute() {
+            const result = clearOrder();
+            setStatus(result.message);
+            return result;
+          },
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: "place_order",
+          description:
+            "Submits the user's current order for preparation. The user is shown the order and must confirm it on the page before it is placed.",
+          inputSchema: { type: "object", properties: {} },
+          execute(_input, { signal: executionSignal }) {
+            return placeOrder({ signal: executionSignal });
+          },
+          annotations: { readOnlyHint: false, consequentialHint: true },
+        },
+      ];
+
+      for (const tool of tools) {
+        document.modelContext.registerTool(tool, { signal }).catch((err) => {
+          console.warn(`WebMCP: failed to register "${tool.name}"`, err);
+        });
+      }
+    }
+  </script>
+
