+import { useWebMCP } from 'use-webmcp-tool';
+import { navigate } from 'astro:transitions/client';
+
+export interface DirectoryArticle {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+}
+
+interface Props {
+  articles: DirectoryArticle[];
+}
