+const articleUrl = (slug: string) =>
+  new URL(`${import.meta.env.BASE_URL}articles/${slug}`, location.origin).href;
+
+/** Site-wide WebMCP tools for browsing the article catalogue. Renders nothing. */
+export default function ArticleDirectoryTools({ articles }: Props) {
+  const categories = [...new Set(articles.map(a => a.category.toLowerCase()))].sort();
+
+  useWebMCP<{ category?: unknown; limit?: unknown }>({
