+        limit: { type: 'integer', minimum: 1, maximum: 50, default: 10, description: 'Maximum number of articles to return.' },
+      },
+    },
+    execute({ category, limit = 10 }) {
+      if (category !== undefined && (typeof category !== 'string' || !categories.includes(category.toLowerCase()))) {
+        return { error: `Unknown category "${String(category)}".`, categories };
+      }
+      const max = Number(limit);
+      if (!Number.isInteger(max) || max < 1 || max > 50) {
+        return { error: 'limit must be a whole number between 1 and 50.' };
+      }
