@@ -0,0 +1,96 @@
+import { useWebMCP } from 'use-webmcp-tool';
+import { setReadingListItem } from '../lib/readingList';
+
+interface Props {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+  /** CSS selector of the element containing the rendered article body. */
+  bodySelector: string;
+}
+
+const WORDS_PER_MINUTE = 230;
+
+/** WebMCP tools scoped to the article currently on screen. Renders nothing. */
+export default function ArticleTools({ bodySelector, ...article }: Props) {
+  const getBody = () => document.querySelector<HTMLElement>(bodySelector);
+  const getHeadings = () =>
+    Array.from(getBody()?.querySelectorAll<HTMLHeadingElement>('h2, h3, h4') ?? []);
+
+  useWebMCP({
+    name: 'get_current_article',
+    description: 'Returns the full text and details of the article the reader is viewing, including its section headings and estimated reading time. Use to summarise, quote or answer questions about this article.',
+    inputSchema: { type: 'object', properties: {} },
+    execute() {
+      const text = (getBody()?.innerText ?? '').trim();
+      const wordCount = text ? text.split(/\s+/).length : 0;
+      return {
+        ...article,
+        url: location.href,
+        wordCount,
+        readingTimeMinutes: Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE)),
+        sections: getHeadings().map(h => h.textContent?.trim() ?? ''),
+        text,
+      };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP<{ section?: unknown }>({
+    name: 'scroll_to_article_section',
+    description: 'Scrolls the article to a section heading so the reader can see it.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        section: { type: 'string', description: 'Heading text of the section, as listed in get_current_article; partial matches work.' },
+      },
+      required: ['section'],
+    },
+    execute({ section }) {
+      const headings = getHeadings();
+      const titles = headings.map(h => h.textContent?.trim() ?? '');
+      if (typeof section !== 'string' || !section.trim()) {
+        return { error: 'Pass the heading text of a section.', sections: titles };
+      }
+      const needle = section.trim().toLowerCase();
+      const index = titles.findIndex(t => t.toLowerCase() === needle) >= 0
+        ? titles.findIndex(t => t.toLowerCase() === needle)
+        : titles.findIndex(t => t.toLowerCase().includes(needle));
+      if (index < 0) {
+        return { error: `No section matching "${section}".`, sections: titles };
+      }
+      const heading = headings[index];
+      const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
+      heading.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
+      return `Scrolled to "${titles[index]}".`;
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP<{ saved?: unknown }>({
+    name: 'set_current_article_saved',
+    description: "Saves the article the reader is viewing to their reading list, or removes it.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        saved: { type: 'boolean', default: true, description: 'true to save the article, false to remove it from the reading list.' },
+      },
+    },
+    async execute({ saved = true }, { signal }) {
+      if (typeof saved !== 'boolean') {
+        return { error: 'saved must be true or false.' };
+      }
+      const readingList = await setReadingListItem(article.slug, saved, signal);
+      return {
+        message: `"${article.title}" is ${readingList.includes(article.slug) ? 'saved to' : 'not on'} the reading list.`,
+        readingListCount: readingList.length,
+      };
+    },
+  });
+
+  return null;
+}
