+// Shared client-side helpers for the session-backed reading list.
+// Every change dispatches a `readinglistchange` event on `window` so that
+// bookmark buttons, the reading-list flyout and WebMCP tools stay in sync.
+
+export const READING_LIST_EVENT = 'readinglistchange';
+
+const endpoint = () => `${import.meta.env.BASE_URL}api/reading-list.json`;
+
+export async function fetchReadingList(signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(endpoint(), { signal });
+  if (!response.ok) throw new Error(`Reading list request failed (${response.status})`);
+  const data = await response.json();
+  return Array.isArray(data.readingList) ? data.readingList : [];
+}
+
+/** Toggles a slug on the server-side reading list and broadcasts the new list. */
+export async function toggleReadingListItem(slug: string, signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(endpoint(), {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+    signal,
+  });
+  if (!response.ok) throw new Error(`Reading list update failed (${response.status})`);
+  const data = await response.json();
+  const readingList: string[] = Array.isArray(data.readingList) ? data.readingList : [];
+  window.dispatchEvent(new CustomEvent(READING_LIST_EVENT, { detail: { readingList } }));
+  return readingList;
+}
+
+/** Idempotently adds or removes a slug (the API itself only toggles). */
+export async function setReadingListItem(slug: string, saved: boolean, signal?: AbortSignal): Promise<string[]> {
+  const current = await fetchReadingList(signal);
+  if (current.includes(slug) === saved) return current;
+  return toggleReadingListItem(slug, signal);
+}
+
+export function onReadingListChange(listener: (readingList: string[]) => void): () => void {
+  const handler = (event: Event) => listener((event as CustomEvent<{ readingList: string[] }>).detail.readingList);
+  window.addEventListener(READING_LIST_EVENT, handler);
+  return () => window.removeEventListener(READING_LIST_EVENT, handler);
+}
+
+/** Submit event fields added by the WebMCP declarative API (not yet in lib.dom). */
+export type AgentSubmitEvent = SubmitEvent & {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+};
