+/**
+ * Shared helpers for exposing The DevTools Times to in-browser AI agents via
+ * WebMCP (`navigator.modelContext`).
+ *
+ * - Declarative tools live on <form toolname="..."> elements (search + reading list).
+ * - Imperative tools are registered from `src/scripts/webmcp-tools.ts`.
+ *
+ * Everything here feature-detects so the site keeps working in browsers
+ * without WebMCP support.
+ */
+
+export interface ToolContent {
+  type: 'text';
+  text: string;
+}
+
+export interface ToolResult {
+  content: ToolContent[];
+  isError?: boolean;
+}
+
+export interface WebMCPTool {
+  name: string;
+  title?: string;
+  description: string;
+  inputSchema?: Record<string, unknown>;
+  annotations?: { readOnlyHint?: boolean; destructiveHint?: boolean; idempotentHint?: boolean };
+  execute: (input: any, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  category?: string;
+  author?: string;
+  date?: string;
+  readingTime?: number;
+  tags?: string[];
+}
+
+/** Window events used to keep UI islands in sync with agent-driven changes. */
+export const EVENTS = {
+  openSearch: 'devtools-times:open-search',
+  openReadingList: 'devtools-times:open-reading-list',
+  readingListChanged: 'devtools-times:reading-list-changed',
+} as const;
+
+const BASE_URL: string = import.meta.env.BASE_URL;
+
+export const articleUrl = (slug: string) =>
+  new URL(`${BASE_URL}articles/${slug}`, window.location.origin).toString();
+
+export function getModelContext(): any | undefined {
+  if (typeof navigator === 'undefined') return undefined;
+  return (navigator as any).modelContext;
+}
+
+export function hasWebMCP(): boolean {
+  return typeof getModelContext()?.registerTool === 'function';
+}
+
+/**
+ * Registers a tool and returns a function that unregisters it. Supports both
+ * the AbortSignal-based and the legacy `{ unregister }` / `unregisterTool`
+ * shapes of the WebMCP API.
+ */
+export function registerTool(tool: WebMCPTool): () => void {
+  const mc = getModelContext();
+  if (!mc || typeof mc.registerTool !== 'function') return () => {};
+
+  const controller = new AbortController();
+  let registration: any;
+  try {
+    registration = mc.registerTool(tool, { signal: controller.signal });
+  } catch (error) {
+    console.warn(`[WebMCP] Failed to register tool "${tool.name}":`, error);
+    return () => {};
+  }
+
+  let done = false;
+  return () => {
+    if (done) return;
+    done = true;
+    controller.abort();
+    try {
+      if (registration && typeof registration.unregister === 'function') {
+        registration.unregister();
+      } else if (typeof mc.unregisterTool === 'function') {
+        mc.unregisterTool(tool.name);
+      }
+    } catch {
+      // Already unregistered via the abort signal.
+    }
+  };
+}
+
+export const textResult = (data: unknown): ToolResult => ({
+  content: [{ type: 'text', text: typeof data === 'string' ? data : JSON.stringify(data, null, 2) }],
+});
+
+export const errorResult = (message: string): ToolResult => ({
+  content: [{ type: 'text', text: message }],
+  isError: true,
+});
+
+// ---------------------------------------------------------------------------
+// Data access
+// ---------------------------------------------------------------------------
+
+let articlesPromise: Promise<ArticleSummary[]> | null = null;
+
+export function fetchArticles(): Promise<ArticleSummary[]> {
+  if (!articlesPromise) {
+    articlesPromise = fetch(`${BASE_URL}api/articles.json`)
+      .then((response) => {
+        if (!response.ok) throw new Error(`Failed to load articles (${response.status})`);
+        return response.json();
+      })
+      .catch((error) => {
+        articlesPromise = null;
+        throw error;
+      });
+  }
+  return articlesPromise;
+}
+
+export function searchArticles(articles: ArticleSummary[], query: string, limit = 10) {
+  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
+  if (terms.length === 0) return [];
+  return articles
+    .map((article) => {
+      const title = article.title.toLowerCase();
+      const haystack = [article.summary, article.category, article.author, ...(article.tags ?? [])]
+        .join(' ')
+        .toLowerCase();
+      let score = 0;
+      for (const term of terms) {
+        if (title.includes(term)) score += 3;
+        else if (haystack.includes(term)) score += 1;
+        else return null; // every term must match somewhere
+      }
+      return { article, score };
+    })
+    .filter((hit): hit is { article: ArticleSummary; score: number } => hit !== null)
+    .sort((a, b) => b.score - a.score)
+    .slice(0, limit)
+    .map(({ article }) => article);
+}
+
+export async function getReadingList(): Promise<string[]> {
+  const response = await fetch(`${BASE_URL}api/reading-list.json`);
+  if (!response.ok) throw new Error(`Failed to load reading list (${response.status})`);
+  const data = await response.json();
+  return data.readingList ?? [];
+}
+
+export function notifyReadingListChanged(readingList: string[]) {
+  window.dispatchEvent(new CustomEvent(EVENTS.readingListChanged, { detail: { readingList } }));
+}
+
+/** The API only supports toggling, so check current state first to make this idempotent. */
+export async function setReadingListMembership(slug: string, saved: boolean): Promise<string[]> {
+  const current = await getReadingList();
+  if (current.includes(slug) === saved) return current;
+  const response = await fetch(`${BASE_URL}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  if (!response.ok) throw new Error(`Failed to update reading list (${response.status})`);
+  const data = await response.json();
+  const readingList: string[] = data.readingList ?? [];
+  notifyReadingListChanged(readingList);
+  return readingList;
+}
+
+/**
+ * Wires a declarative WebMCP form's submit handler: when an agent submits the
+ * form, `respondWith` hands the tool result back to the agent.
+ */
+export function respondToAgent(event: { nativeEvent?: Event } | Event, result: Promise<unknown>) {
+  const native: any = 'nativeEvent' in event && event.nativeEvent ? event.nativeEvent : event;
+  if (native?.agentInvoked && typeof native.respondWith === 'function') {
+    native.respondWith(result);
+  }
+}
