diff --git a/src/scripts/webmcp-tools.ts b/src/scripts/webmcp-tools.ts
new file mode 100644
index 0000000..501fc2c
--- /dev/null
+++ b/src/scripts/webmcp-tools.ts
@@ -0,0 +1,437 @@
+/**
+ * Imperative WebMCP tools for The DevTools Times.
+ *
+ * Site-wide tools are registered once. Article tools are registered on article
+ * pages only and re-evaluated on every Astro client-side navigation
+ * (`astro:page-load` / `astro:before-swap`), so agents only see tools that make
+ * sense for the current page.
+ *
+ * The search and reading-list *forms* are exposed declaratively (see
+ * SearchFlyout.tsx / ReadingListFlyout.tsx); `open_search` and
+ * `open_reading_list` reveal them so their tools become available.
+ */
+import {
+  EVENTS,
+  articleUrl,
+  errorResult,
+  fetchArticles,
+  getReadingList,
+  hasWebMCP,
+  registerTool,
+  setReadingListMembership,
+  textResult,
+  type WebMCPTool,
+} from '../lib/webmcp';
+
+const HIGHLIGHT_NAME = 'webmcp-article-match';
+
+// ---------------------------------------------------------------------------
+// Site-wide tools
+// ---------------------------------------------------------------------------
+
+const siteTools: WebMCPTool[] = [
+  {
+    name: 'list_articles',
+    title: 'List articles',
+    description:
+      'List articles published on The DevTools Times, newest first. Optionally filter by category. Returns slug, title, summary, category, author, date, reading time and URL for each article.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: {
+          type: 'string',
+          description: "Only return articles in this category (case-insensitive), e.g. 'sports', 'science', 'Politics'.",
+        },
+        limit: { type: 'integer', minimum: 1, maximum: 100, description: 'Maximum number of articles to return. Defaults to 20.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ category, limit = 20 }: { category?: string; limit?: number } = {}) {
+      const articles = await fetchArticles();
+      const filtered = articles
+        .filter((a) => !category || a.category?.toLowerCase() === category.toLowerCase())
+        .sort((a, b) => (b.date ?? '').localeCompare(a.date ?? ''));
+      const categories = [...new Set(articles.map((a) => a.category).filter(Boolean))];
+      return textResult({
+        total: filtered.length,
+        availableCategories: categories,
+        articles: filtered.slice(0, Math.max(1, Math.min(100, limit))).map((a) => ({
+          slug: a.slug,
+          title: a.title,
+          summary: a.summary,
+          category: a.category,
+          author: a.author,
+          date: a.date,
+          readingTimeMinutes: a.readingTime,
+          url: articleUrl(a.slug),
+        })),
+      });
+    },
+  },
+  {
+    name: 'get_reading_list',
+    title: 'Get reading list',
+    description: "Return the articles currently saved in the reader's reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const [slugs, articles] = await Promise.all([getReadingList(), fetchArticles()]);
+      return textResult({
+        count: slugs.length,
+        articles: slugs.map((slug) => {
+          const a = articles.find((article) => article.slug === slug);
+          return { slug, title: a?.title, summary: a?.summary, url: articleUrl(slug) };
+        }),
+      });
+    },
+  },
+  {
+    name: 'open_search',
+    title: 'Open search panel',
+    description:
+      'Open the site search panel, optionally pre-filled with a query. This reveals the "search_articles" form tool, which performs the search and returns results.',
+    inputSchema: {
+      type: 'object',
+      properties: { query: { type: 'string', description: 'Optional text to pre-fill in the search box.' } },
+    },
+    async execute({ query = '' }: { query?: string } = {}) {
+      window.dispatchEvent(new CustomEvent(EVENTS.openSearch, { detail: { query } }));
+      return textResult(
+        'Search panel opened. Use the "search_articles" tool to run a search and get results.',
+      );
+    },
+  },
+  {
+    name: 'open_reading_list',
+    title: 'Open reading list panel',
+    description:
+      'Open the reading list panel so the reader can see their saved articles. This reveals the "update_reading_list" form tool for adding or removing articles.',
+    inputSchema: { type: 'object', properties: {} },
+    async execute() {
+      window.dispatchEvent(new CustomEvent(EVENTS.openReadingList));
+      return textResult(
+        'Reading list panel opened. Use the "update_reading_list" tool to add or remove articles.',
+      );
+    },
+  },
+];
+
+// ---------------------------------------------------------------------------
+// Article page tools
+// ---------------------------------------------------------------------------
+
+interface ArticleDom {
+  root: HTMLElement;
+  body: HTMLElement;
+  slug: string;
+}
+
+function getArticleDom(): ArticleDom | null {
+  const root = document.querySelector<HTMLElement>('[data-article]');
+  const body = root?.querySelector<HTMLElement>('[data-article-body]');
+  const slug = root?.dataset.articleSlug;
+  return root && body && slug ? { root, body, slug } : null;
+}
+
+function articleMeta(root: HTMLElement) {
+  const d = root.dataset;
+  return {
+    slug: d.articleSlug,
+    title: d.articleTitle,
+    summary: d.articleSummary,
+    author: d.articleAuthor,
+    category: d.articleCategory,
+    date: d.articleDate,
+    readingTimeMinutes: d.articleReadingTime ? Number(d.articleReadingTime) : undefined,
+    tags: d.articleTags ? d.articleTags.split(',').filter(Boolean) : [],
+    url: d.articleSlug ? articleUrl(d.articleSlug) : window.location.href,
+  };
+}
+
+const bodyText = (body: HTMLElement) => (body.innerText || body.textContent || '').trim();
+const wordCount = (text: string) => text.split(/\s+/).filter(Boolean).length;
+
+function headings(body: HTMLElement) {
+  return [...body.querySelectorAll<HTMLElement>('h1, h2, h3, h4, h5, h6')].map((el) => ({
+    el,
+    level: Number(el.tagName.slice(1)),
+    text: (el.textContent || '').trim(),
+  }));
+}
+
+function blocks(body: HTMLElement) {
+  return [...body.querySelectorAll<HTMLElement>('p, li, blockquote, h1, h2, h3, h4, h5, h6, td, figcaption')];
+}
+
+function clearHighlights() {
+  (CSS as any).highlights?.delete(HIGHLIGHT_NAME);
+}
+
+function highlightMatches(body: HTMLElement, needle: string): number {
+  const registry = (CSS as any).highlights;
+  const HighlightCtor = (window as any).Highlight;
+  if (!registry || !HighlightCtor) return 0;
+
+  const ranges: Range[] = [];
+  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT);
+  const lowerNeedle = needle.toLowerCase();
+  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
+    const text = (node.textContent || '').toLowerCase();
+    let index = text.indexOf(lowerNeedle);
+    while (index !== -1) {
+      const range = new Range();
+      range.setStart(node, index);
+      range.setEnd(node, index + needle.length);
+      ranges.push(range);
+      index = text.indexOf(lowerNeedle, index + needle.length);
+    }
+  }
+  registry.set(HIGHLIGHT_NAME, new HighlightCtor(...ranges));
+  return ranges.length;
+}
+
+const notOnArticle = () =>
+  errorResult('No article is open. Navigate to an article page first (see list_articles for URLs).');
+
+const articleTools: WebMCPTool[] = [
+  {
+    name: 'get_current_article',
+    title: 'Get current article',
+    description:
+      'Return metadata (title, summary, author, category, date, tags, URL) for the article open on this page, and optionally its full text.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        includeBody: { type: 'boolean', description: 'Include the full article text. Defaults to true.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ includeBody = true }: { includeBody?: boolean } = {}) {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const text = bodyText(dom.body);
+      return textResult({
+        ...articleMeta(dom.root),
+        wordCount: wordCount(text),
+        ...(includeBody ? { body: text } : {}),
+      });
+    },
+  },
+  {
+    name: 'get_article_outline',
+    title: 'Get article outline',
+    description: 'Return the section headings of the current article in document order, with their heading level.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const outline = headings(dom.body).map(({ level, text }) => ({ level, text }));
+      return textResult({ title: dom.root.dataset.articleTitle, sections: outline });
+    },
+  },
+  {
+    name: 'get_article_reading_stats',
+    title: 'Get reading stats',
+    description:
+      "Compute the current article's word count, paragraph count and estimated reading time, plus how far the reader has scrolled through it.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        wordsPerMinute: {
+          type: 'integer',
+          minimum: 50,
+          maximum: 1000,
+          description: 'Reading speed used for the estimate. Defaults to 230.',
+        },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ wordsPerMinute = 230 }: { wordsPerMinute?: number } = {}) {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const words = wordCount(bodyText(dom.body));
+      const wpm = Math.max(50, Math.min(1000, wordsPerMinute));
+      const rect = dom.body.getBoundingClientRect();
+      const scrolled = Math.min(Math.max(window.innerHeight - rect.top, 0), rect.height);
+      const progress = rect.height > 0 ? Math.round((scrolled / rect.height) * 100) : 0;
+      const minutes = words / wpm;
+      return textResult({
+        wordCount: words,
+        paragraphCount: dom.body.querySelectorAll('p').length,
+        wordsPerMinute: wpm,
+        estimatedReadingTimeMinutes: Math.max(1, Math.round(minutes)),
+        publishedReadingTimeMinutes: articleMeta(dom.root).readingTimeMinutes,
+        readProgressPercent: progress,
+        estimatedMinutesRemaining: Math.max(0, Math.round(minutes * (1 - progress / 100))),
+      });
+    },
+  },
+  {
+    name: 'find_in_article',
+    title: 'Find in article',
+    description:
+      'Find text in the current article. Highlights every match on the page, scrolls the first match into view, and returns the paragraphs that contain it.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        text: { type: 'string', minLength: 1, description: 'Text to look for (case-insensitive).' },
+        scrollIntoView: { type: 'boolean', description: 'Scroll to the first match. Defaults to true.' },
+      },
+      required: ['text'],
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ text, scrollIntoView = true }: { text: string; scrollIntoView?: boolean }) {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const needle = (text ?? '').trim();
+      if (!needle) return errorResult('"text" must not be empty.');
+
+      const matches = blocks(dom.body).filter((el) =>
+        (el.textContent || '').toLowerCase().includes(needle.toLowerCase()),
+      );
+      // Skip containers whose matching child is already listed (e.g. <li><p>…</p></li>).
+      const leafMatches = matches.filter((el) => !matches.some((other) => other !== el && el.contains(other)));
+
+      clearHighlights();
+      const highlighted = leafMatches.length ? highlightMatches(dom.body, needle) : 0;
+      if (scrollIntoView && leafMatches[0]) {
+        leafMatches[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
+      }
+      return textResult({
+        query: needle,
+        matchCount: leafMatches.length,
+        highlightedOccurrences: highlighted,
+        matches: leafMatches.slice(0, 20).map((el) => (el.textContent || '').trim()),
+      });
+    },
+  },
+  {
+    name: 'scroll_to_article_section',
+    title: 'Scroll to section',
+    description:
+      'Scroll the page to a section of the current article by (partial) heading text. Use get_article_outline to see available sections.',
+    inputSchema: {
+      type: 'object',
+      properties: { heading: { type: 'string', minLength: 1, description: 'Full or partial heading text.' } },
+      required: ['heading'],
+    },
+    async execute({ heading }: { heading: string }) {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const query = (heading ?? '').trim().toLowerCase();
+      const all = headings(dom.body);
+      const target =
+        all.find((h) => h.text.toLowerCase() === query) ?? all.find((h) => h.text.toLowerCase().includes(query));
+      if (!target) {
+        return errorResult(
+          `No section matching "${heading}". Available sections: ${all.map((h) => h.text).join(' | ') || '(none)'}`,
+        );
+      }
+      target.el.scrollIntoView({ behavior: 'smooth', block: 'start' });
+      return textResult(`Scrolled to section "${target.text}".`);
+    },
+  },
+  {
+    name: 'set_current_article_saved',
+    title: 'Save current article',
+    description: "Save the current article to, or remove it from, the reader's reading list.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        saved: { type: 'boolean', description: 'true to save the article, false to remove it. Defaults to true.' },
+      },
+    },
+    annotations: { idempotentHint: true },
+    async execute({ saved = true }: { saved?: boolean } = {}) {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const readingList = await setReadingListMembership(dom.slug, saved);
+      return textResult({
+        slug: dom.slug,
+        title: dom.root.dataset.articleTitle,
+        saved: readingList.includes(dom.slug),
+        readingListCount: readingList.length,
+      });
+    },
+  },
+  {
+    name: 'get_related_articles',
+    title: 'Get related articles',
+    description: 'Return the related articles recommended below the current article.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const section = document.querySelector<HTMLElement>('[data-related-articles]');
+      if (!getArticleDom() || !section) return notOnArticle();
+      const seen = new Set<string>();
+      const related = [...section.querySelectorAll<HTMLAnchorElement>('a[href*="/articles/"]')]
+        .map((link) => {
+          const slug = new URL(link.href).pathname.split('/articles/')[1]?.replace(/\/$/, '');
+          const teaser = link.closest('article') ?? link;
+          return {
+            slug,
+            title: (teaser.querySelector('h1, h2, h3')?.textContent || '').trim(),
+            summary: (teaser.querySelector('p')?.textContent || '').trim(),
+            url: link.href,
+          };
+        })
+        .filter((a) => a.slug && a.title && !seen.has(a.slug) && seen.add(a.slug));
+      return textResult({ related });
+    },
+  },
+  {
+    name: 'get_article_share_links',
+    title: 'Get share links',
+    description: 'Return a canonical link to the current article plus ready-made share links for X, Facebook and email.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const dom = getArticleDom();
+      if (!dom) return notOnArticle();
+      const url = articleUrl(dom.slug);
+      const title = dom.root.dataset.articleTitle ?? document.title;
+      const u = encodeURIComponent(url);
+      const t = encodeURIComponent(title);
+      return textResult({
+        url,
+        title,
+        x: `https://x.com/intent/post?url=${u}&text=${t}`,
+        facebook: `https://www.facebook.com/sharer/sharer.php?u=${u}`,
+        email: `mailto:?subject=${t}&body=${u}`,
+      });
+    },
+  },
+];
+
+// ---------------------------------------------------------------------------
+// Registration lifecycle
+// ---------------------------------------------------------------------------
+
+function init() {
+  if (!hasWebMCP()) return;
+  const w = window as any;
+  if (w.__devtoolsTimesWebMCP) return; // module already initialised
+  w.__devtoolsTimesWebMCP = true;
+
+  siteTools.forEach(registerTool);
+
+  let unregisterArticleTools: Array<() => void> = [];
+  const teardownArticleTools = () => {
+    unregisterArticleTools.forEach((unregister) => unregister());
+    unregisterArticleTools = [];
+    clearHighlights();
+  };
+
+  const syncArticleTools = () => {
+    teardownArticleTools();
+    if (getArticleDom()) unregisterArticleTools = articleTools.map(registerTool);
+  };
+
+  // `astro:page-load` fires on the initial load and after every ClientRouter navigation.
+  document.addEventListener('astro:page-load', syncArticleTools);
+  document.addEventListener('astro:before-swap', teardownArticleTools);
+  syncArticleTools();
+}
+
+init();
